--
-- Idempotency: each DO $$ block early-returns (RAISE NOTICE) if its
-- external_id already exists. Safe to re-run.

-- ============================================================
-- Q01 — 2019-S-S-Q01 — chapter=ethics subtopic=fees_client_funds_advertising
-- classifier_note: Lawyer + funding-company referral → advertising/solicitation rules
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '91a9c02b-4c89-494b-96d4-27315376f615'::uuid;
  v_group_id uuid := 'bc90ecb3-9aa6-4f65-8004-4e2faf03e7b9'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '12e53d1d-4176-4574-9817-fc6128c87fe6'::uuid;
  v_ang_1 uuid := 'c7bdce67-1153-4388-98f1-cb18677864ef'::uuid;
  v_ang_2 uuid := 'b9c4d9fe-e969-4d01-b12e-59d2104abc42'::uuid;
  v_ang_3 uuid := '398345c4-2223-417f-8e68-76c86b35dc20'::uuid;
BEGIN
