  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q01', v_chapter_id, v_subtopic_id, 'יוסי פנה לעו"ד מידד לאחר שהופנה אליו על ידי חברת זכויות פנסיוניות בע"מ, הפועלת למטרת רווח ומפרסמת ברבים את נכונותה לממן שירותים משפטיים ללקוחותיה כחלק ממכלול השירותים שהיא נותנת. עו"ד מידד קיבל על עצמו את הטיפול לאחר ששכר טרחתו סוכם בכתב בינו לבין חברת זכויות פנסיוניות בע"מ. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 1}'::jsonb, 'השאלה עוסקת בכלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), האוסר על עורך דין לתת שירות משפטי ללקוח שהופנה אליו על ידי גוף שאינו עורך דין, הפועל למטרת רווח ולמטרה זו מפרסם ברבים מתן שירותים משפטיים. הכלל נועד למנוע עקיפה של כללי האתיקה הנוגעים לפרסומת, לשמור על עקרון ייחוד המקצוע ועל עצמאותו של עורך הדין, ולהגן על הציבור מפני הטעיה וניגוד עניינים.', 'כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע איסור מפורש על עורך דין לתת שירות משפטי ללקוח שהופנה אליו על ידי גוף שאינו עורך דין, שותפות של עורכי דין או חברת עורכי דין, הפועל למטרת רווח ולמטרה זו מפרסם ברבים מתן שירותים משפטיים. במקרה הנדון, חברת ''זכויות פנסיוניות בע"מ'' עונה על כל יסודות האיסור: היא אינה עורכת דין, היא פועלת למטרת רווח, והיא מפרסמת ברבים את מתן השירותים המשפטיים (בכך שהיא מציעה לממן אותם כחלק ממכלול שירותיה). תכלית הכלל, כפי שנקבע בבג"ץ פיצוי נמרץ (120877), היא למנוע עקיפה של כללי האתיקה החלים על עורכי דין, לשמור על עקרון ייחוד המקצוע, למנוע הטעיית לקוחות ולמנוע מצבים של ניגוד עניינים. לכן, עו"ד מידד פעל שלא כדין בקבלו את הטיפול מלקוח שהופנה אליו בנסיבות אלו.', 'הטעות הנפוצה היא לחשוב שכל עוד עורך הדין עצמו אינו מפרסם או משדל, אין בעיה, או להתעלם מהדרישה שהגוף המפנה יפעל למטרת רווח ויפרסם שירותים משפטיים.',
    '["כלל 11ב(א)", "הפניית לקוחות", "גוף למטרת רווח", "פרסום שירותים משפטיים", "ייחוד המקצוע", "ניגוד עניינים", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — איסור כלל 11ב(א):** מתי אסור לעו"ד לתת שירות ללקוח שהופנה אליו? ← כאשר הופנה ע"י גוף שאינו עו"ד, למטרת רווח, המפרסם שירותים משפטיים. כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986
**וריאציה 2 — תכלית הכלל:** מהי תכלית כלל 11ב(א)? ← מניעת עקיפת כללי האתיקה, שמירה על ייחוד המקצוע ומניעת הטעיה. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)
**וריאציה 3 — פגיעה בזכויות יסוד:** האם כלל 11ב פוגע בזכויות יסוד? ← כן, בחופש העיסוק ובאוטונומיה של הלקוחות, אך הפגיעה מידתית ולתכלית ראויה. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)', 'עו"ד ← לקוח מופנה ע"י גוף למטרת רווח המפרסם שירותים משפטיים ← אסור (כלל 11ב(א)).', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 11ב", "בג\"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים, נח(5) 792 (17.06.2004)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Lawyer + funding-company referral → advertising/solicitation rules | source_review_note: הסיווג לתת-נושא ''משמעת עורכי דין'' אינו מדויק, שכן השאלה עוסקת בעיקר בכללי פרסומת ושידול. יש לשקול הוספת תת-נושא מתאים יותר ל''אתיקה מקצועית'' או ''פרסומת עורכי דין'' תחת פרק רחב יותר של ''דיני לשכת עורכי הדין''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד מידד פעל שלא כדין, שכן לעולם שכר טרחה ישולם על ידי הלקוח ולא על ידי צד שלישי.', false, 'טענה זו שגויה. אין איסור גורף על תשלום שכר טרחה על ידי צד שלישי, אך יש לבחון את נסיבות התשלום ואת זהות הצד השלישי, במיוחד לאור כלל 11ב לכללי האתיקה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד מידד פעל כדין, שכן אין כל מניעה לקבל מצד שלישי תשלום בגין שכר הטרחה המגיע לו מלקוחו.', false, 'טענה זו שגויה. קיימת מניעה לקבל תשלום מצד שלישי כאשר הוא גוף הפועל למטרת רווח ומפרסם שירותים משפטיים, כפי שקובע כלל 11ב(א) לכללי האתיקה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד מידד פעל שלא כדין הואיל ויוסי לא חתם על הסכם שכר הטרחה לצד חברת זכויות פנסיוניות בע"מ הפועלת באופן המתואר לעיל.', false, 'טענה זו שגויה. אף שרצוי שהלקוח יהיה צד להסכם שכר הטרחה, הפגם העיקרי אינו בחתימת הלקוח, אלא בעצם קבלת הלקוח שהופנה על ידי גוף מסחרי המפרסם שירותים משפטיים, בניגוד לכלל 11ב(א).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד מידד פעל שלא כדין, שכן יוסי הופנה אליו על ידי חברת זכויות פנסיוניות בע"מ הפועלת באופן המתואר לעיל.', true, 'כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין לתת שירות משפטי ללקוח שהופנה אליו על ידי גוף שאינו עורך דין, הפועל למטרת רווח ולמטרה זו מפרסם ברבים מתן שירותים משפטיים. חברת זכויות פנסיוניות בע"מ עונה על הגדרה זו, ולכן עו"ד מידד פעל שלא כדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'איסור מתן שירותים על ידי עו"ד המועסק על ידי גוף שאינו עו"ד',
    1, 'עו"ד רותם מועסקת כשכירה בחברת ''גבייה מהירה בע"מ'', חברה הפועלת למטרת רווח ומתמחה בגביית חובות. החברה מציעה ללקוחותיה שירותי גבייה הכוללים ייצוג משפטי, וגובה מהם תמורה עבור שירותים אלו. עו"ד רותם מעניקה שירותים משפטיים ללקוחות החברה, שאינם מעסיקיה הישירים. האם פעולתה של עו"ד רותם מותרת?', 'שאלה זו עוסקת בכלל 11ב(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית), האוסר על עורך דין המועסק על ידי גוף שאינו עורך דין, לתת שירות משפטי למי שאינו מעסיקו, אם המעסיק פועל למטרת רווח וגובה תמורה בעד אותו שירות. הכלל נועד למנוע ניגוד עניינים מובנה ולשמור על עצמאותו המקצועית של עורך הדין.', 'כלל 11ב(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי ''עורך דין המועסק על ידי מי שאינו עורך דין, שותפות של עורכי דין או חברת עורכי דין (להלן - המעסיק), לא ייתן שירות משפטי למי שאינו מעסיקו אם המעסיק פועל למטרת רווח וגובה תמורה בעד אותו שירות משפטי''. תכלית הכלל היא למנוע מצבים של נאמנות כפולה וניגוד עניינים, שבהם עורך הדין עלול להיות מושפע מאינטרסים של מעסיקו שאינו עורך דין, במקום לפעול אך ורק לטובת הלקוח. במקרה זה, עו"ד רותם מועסקת בחברת גבייה למטרת רווח, והחברה גובה תמורה עבור השירותים המשפטיים שהיא מעניקה ללקוחות החברה. לכן, פעולתה של עו"ד רותם אסורה על פי כלל 11ב(ב).',
    'הטעות היא לחשוב שהאיסור חל רק אם עורך הדין עצמו גובה את התמורה, או להתעלם מהיסוד של ''מי שאינו מעסיקו''.', '["כלל 11ב(ב)", "ניגוד עניינים", "עצמאות מקצועית", "חברת גבייה", "אתיקה מקצועית", "שירות משפטי"]'::jsonb, '**וריאציה 1 — תכלית הכלל:** מהי תכלית כלל 11ב(ב)? ← מניעת ניגוד עניינים ושמירה על עצמאות עו"ד. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)
**וריאציה 2 — רכיבי העבירה:** מהם רכיבי העבירה לפי כלל 11ב(ב)? ← עו"ד מועסק ע"י גוף שאינו עו"ד, המעסיק פועל למטרת רווח, עו"ד נתן שירות למי שאינו מעסיקו, המעסיק גבה תמורה בעד אותו שירות. על"ע 4307/07 עו"ד דוד רויטמן נ'' לשכת עורכי הדין ועד מחוז חיפה (04.02.2008)
**וריאציה 3 — נאמנות כפולה:** מהו החשש מנאמנות כפולה? ← החלטות עו"ד יושפעו מאינטרסי המעסיק ולא רק הלקוח. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)', 'עו"ד מועסק ע"י גוף לא-עו"ד למטרת רווח ← אסור לתת שירות למי שאינו מעסיק ← אם המעסיק גובה תמורה.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 11ב(ב)", "בג\"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים, נח(5) 792 (17.06.2004)", "על\"ע 4307/07 עו\"ד דוד רויטמן נ'' לשכת עורכי הדין ועד מחוז חיפה (04.02.2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, כל עוד עו"ד רותם פועלת בנאמנות ללקוחותיה ואינה נמצאת בניגוד עניינים.', false, 'טענה זו שגויה. כלל 11ב(ב) נועד למנוע מצב של ניגוד עניינים מובנה, והוא אוסר על פעולה זו גם אם עורך הדין סבור שפעל בנאמנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, עו"ד רותם פועלת שלא כדין, שכן היא מועסקת על ידי גוף שאינו עורך דין, והמעסיק גובה תמורה בעד השירות המשפטי שהיא נותנת למי שאינו מעסיקה.', true, 'כלל 11ב(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין המועסק על ידי מי שאינו עורך דין (או שותפות/חברת עורכי דין) לתת שירות משפטי למי שאינו מעסיקו, אם המעסיק פועל למטרת רווח וגובה תמורה בעד אותו שירות משפטי. במקרה זה, עו"ד רותם עונה על כל יסודות האיסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, כל עוד חברת הגבייה אינה מפרסמת את עצמה כנותנת שירותים משפטיים.', false, 'טענה זו שגויה. תנאי הפרסום רלוונטי לכלל 11ב(א), אך כלל 11ב(ב) חל גם ללא פרסום, כל עוד המעסיק גובה תמורה בעד השירות המשפטי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן עו"ד רותם קיבלה אישור מיוחד מהוועד המרכזי של לשכת עורכי הדין.', false, 'טענה זו שגויה. אף שכלל 11ב(ג) מאפשר חריגה באישור הוועד המרכזי, אין זה הכלל, והפעולה אסורה ככלל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'רכיבי כלל 11ב(א) לכללי האתיקה',
    2, 'מהם ארבעת הרכיבים המצטברים הנדרשים להתקיימות עבירה לפי כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית)?', 'שאלה זו מפרטת את היסודות העובדתיים המצטברים הנדרשים להרשעה בעבירה משמעתית לפי כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית). הבנת רכיבים אלו חיונית להבחנה בין פעילות מותרת לאסורה בתחום הפניית לקוחות על ידי גורמי ביניים.', 'כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע איסור על עורך דין לתת שירות משפטי ללקוח שהופנה אליו על ידי גוף שאינו עורך דין, שותפות של עורכי דין או חברת עורכי דין, הפועל למטרת רווח ולמטרה זו מפרסם ברבים מתן שירותים משפטיים. הפסיקה פירשה כלל זה כדורש ארבעה רכיבים מצטברים: 1. עורך הדין נתן שירות משפטי ללקוח. 2. הלקוח הופנה אל עורך הדין על ידי גוף שאינו עורך דין. 3. הגוף פועל למטרת רווח. 4. הגוף מפרסם ברבים מתן שירותים משפטיים למטרת רווח. רק בהתקיים כל ארבעת הרכיבים הללו, תתגבש עבירה משמעתית לפי כלל זה.',
    'הטעות היא לבלבל בין הרכיבים של כלל 11ב(א) לבין אלו של כלל 11ב(ב), או להתעלם מכך שכל הרכיבים צריכים להתקיים במצטבר.', '["כלל 11ב(א)", "רכיבים מצטברים", "הפניית לקוחות", "גוף למטרת רווח", "פרסום שירותים משפטיים", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — רכיבי כלל 11ב(א):** מהם ארבעת הרכיבים המצטברים לכלל 11ב(א)? ← עו"ד נתן שירות, לקוח הופנה ע"י גוף לא-עו"ד, הגוף למטרת רווח, הגוף מפרסם שירותים משפטיים. בד"מ (ועדת משמעת לשכת עוה"ד מרכז) 4/23 ועדת האתיקה הארצית של לשכת עורכי הדין בישראל נ'' עו״ד תמיר טורגל (21.10.2025)
**וריאציה 2 — חשיבות הרכיבים:** האם כל הרכיבים חייבים להתקיים? ← כן, רק תשובה חיובית לכל השאלות תכניס לגדר הכלל. בד"מ (ועדת משמעת לשכת עוה"ד מרכז) 4/23 ועדת האתיקה הארצית של לשכת עורכי הדין בישראל נ'' עו״ד תמיר טורגל (21.10.2025)
**וריאציה 3 — תכלית הכלל:** מהי תכלית כלל 11ב(א)? ← מניעת עקיפת כללי האתיקה הנוגעים לפרסומת וייחוד המקצוע. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)', 'כלל 11ב(א) ← 4 רכיבים מצטברים: שירות עו"ד, הפניה מגוף לא-עו"ד, גוף למטרת רווח, גוף מפרסם שירותים משפטיים.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 11ב(א)", "בד\"מ (ועדת משמעת לשכת עוה\"ד מרכז) 4/23 ועדת האתיקה הארצית של לשכת עורכי הדין בישראל נ'' עו״ד תמיר טורגל (21.10.2025)", "בד\"מ (ועדת משמעת לשכת עוה\"ד תל אביב-יפו) 86/10 ועדת האתיקה של לשכת עורכי הדין מחוז תל אביב והמרכז נ'' עו\"ד פלוני (12.05.2011)", "בג\"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים, נח(5) 792 (17.06.2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'עורך הדין נתן שירות משפטי ללקוח; הלקוח הופנה על ידי גוף שאינו עורך דין; הגוף פועל למטרת רווח; הגוף מפרסם ברבים מתן שירותים משפטיים למטרת רווח.', true, 'אלו הם ארבעת הרכיבים המצטברים הנדרשים להתקיימות עבירה לפי כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), כפי שפורשו בפסיקה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'עורך הדין נתן שירות משפטי ללקוח; הלקוח הופנה על ידי גוף שאינו עורך דין; הגוף פועל למטרת רווח; הגוף גובה תמורה בעד השירות המשפטי.', false, 'טענה זו שגויה. הרכיב האחרון (''הגוף גובה תמורה'') שייך לכלל 11ב(ב), ולא לכלל 11ב(א) הדורש פרסום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'עורך הדין נתן שירות משפטי ללקוח; הלקוח הופנה על ידי גוף שאינו עורך דין; הגוף אינו פועל למטרת רווח; הגוף מפרסם ברבים מתן שירותים משפטיים למטרת רווח.', false, 'טענה זו שגויה. כלל 11ב(א) חל רק כאשר הגוף המפנה פועל למטרת רווח, ולא כאשר אינו פועל למטרת רווח.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'עורך הדין נתן שירות משפטי ללקוח; הלקוח הופנה על ידי גוף שאינו עורך דין; הגוף פועל למטרת רווח; הגוף אינו מפרסם ברבים מתן שירותים משפטיים.', false, 'טענה זו שגויה. כלל 11ב(א) דורש שהגוף המפנה יפרסם ברבים מתן שירותים משפטיים, ולא שלא יפרסם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריגים לכלל 11ב(א) – גוף שאינו למטרת רווח',
    3, 'עו"ד שירה קיבלה לקוח שהופנה אליה על ידי עמותה רשומה, שאינה פועלת למטרת רווח, ואשר מפרסמת ברבים את שירותיה הכוללים הפניה לייעוץ משפטי. האם עו"ד שירה עברה עבירה אתית?', 'שאלה זו בוחנת את אחד הרכיבים המהותיים של כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) – הדרישה שהגוף המפנה יפעל למטרת רווח. היא מדגישה כי היעדר רכיב זה שולל את תחולת האיסור, ומאפשר לעורכי דין לקבל לקוחות המופנים על ידי גופים חברתיים או ציבוריים שאינם למטרת רווח.', 'כלל 11ב(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין לתת שירות משפטי ללקוח שהופנה אליו על ידי גוף שאינו עורך דין, הפועל למטרת רווח ולמטרה זו מפרסם ברבים מתן שירותים משפטיים. אחד הרכיבים המצטברים הנדרשים להתקיימות עבירה לפי כלל זה הוא שהגוף המפנה יפעל ''למטרת רווח''. במקרה זה, מדובר בעמותה רשומה שאינה פועלת למטרת רווח. כפי שנקבע בפסיקה, עמותה, בהגדרתה לפי דין, היא גוף שמטרתו העיקרית אינה עשיית רווחים, ולכן חזקה היא כי רכיב זה אינו מתקיים. משכך, כלל 11ב(א) אינו חל, ועו"ד שירה לא עברה עבירה אתית בהקשר זה.',
    'הטעות היא להתעלם מהדרישה שהגוף המפנה יפעל ''למטרת רווח'', ולחשוב שכל הפניה מגוף שאינו עורך דין אסורה.', '["כלל 11ב(א)", "גוף למטרת רווח", "עמותה", "הפניית לקוחות", "רכיבים מצטברים", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — יסוד ''למטרת רווח'':** האם כלל 11ב(א) חל על גוף שאינו למטרת רווח? ← לא, יסוד ''למטרת רווח'' הוא רכיב מצטבר. בד"מ (ועדת משמעת לשכת עוה"ד מרכז) 4/23 ועדת האתיקה הארצית של לשכת עורכי הדין בישראל נ'' עו״ד תמיר טורגל (21.10.2025)
**וריאציה 2 — תכלית הכלל:** מהי תכלית כלל 11ב(א)? ← מניעת עקיפת כללי האתיקה הנוגעים לפרסומת וייחוד המקצוע. בג"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים (17.06.2004)
**וריאציה 3 — גופי ייעוץ והפניה:** האם גופי ייעוץ והפניה יכולים להפנות לעורכי דין? ← כן, כל עוד אינם מתיימרים לתת בעצמם שירות משפטי ומבהירים את טיב עיסוקם. ת"א (מחוזי ירושלים) 4033/02 לשכת עורכי הדין בישראל נ'' מרגלית אלבז רביבו (13.11.2005)', 'כלל 11ב(א) ← דורש גוף למטרת רווח ← עמותה שאינה למטרת רווח ← אינה מפרה את הכלל.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 11ב(א)", "בד\"מ (ועדת משמעת לשכת עוה\"ד מרכז) 4/23 ועדת האתיקה הארצית של לשכת עורכי הדין בישראל נ'' עו״ד תמיר טורגל (21.10.2025)", "בג\"ץ 9596/02 פיצוי נמרץ, המומחים למימוש זכויות רפואיות וביטוחים נ'' שר המשפטים, נח(5) 792 (17.06.2004)", "ת\"א (מחוזי ירושלים) 4033/02 לשכת עורכי הדין בישראל נ'' מרגלית אלבז רביבו (13.11.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, עצם הפרסום של העמותה והפניית הלקוח מהווה שידול אסור.', false, 'טענה זו שגויה. כלל 11ב(א) דורש שהגוף המפנה יפעל למטרת רווח, ובהיעדר יסוד זה, אין מדובר בשידול אסור לפי כלל זה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, עו"ד שירה לא עברה עבירה אתית, שכן העמותה אינה פועלת למטרת רווח, ולכן כלל 11ב(א) אינו חל.', true, 'אחד הרכיבים המצטברים להתקיימות עבירה לפי כלל 11ב(א) הוא שהגוף המפנה יפעל למטרת רווח. מאחר שהעמותה אינה פועלת למטרת רווח, כלל 11ב(א) אינו חל, ולכן עו"ד שירה לא עברה עבירה אתית בהקשר זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן העמותה קיבלה אישור מיוחד מהוועד המרכזי של לשכת עורכי הדין.', false, 'טענה זו שגויה. אישור הוועד המרכזי רלוונטי לחריגה מהכלל, אך במקרה זה הכלל אינו חל מלכתחילה בשל היעדר יסוד ''למטרת רווח''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם עו"ד שירה לא גבתה שכר טרחה מהלקוח.', false, 'טענה זו שגויה. גביית שכר טרחה אינה היסוד הקובע לעניין תחולת כלל 11ב(א), אלא זהות הגוף המפנה ואופי פעילותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הסגת גבול מקצוע עריכת הדין על ידי גוף שאינו עורך דין',
    4, 'חברת ''מימוש זכויות בע"מ'', שאינה חברת עורכי דין, מציעה לציבור שירותי ייעוץ משפטי בתחום הביטוח הלאומי, עריכת מסמכים משפטיים וייצוג בפני ועדות רפואיות. החברה גובה תמורה עבור שירותים אלו. מהן ההשלכות המשפטיות של פעילות זו?', 'שאלה זו עוסקת בעקרון ייחוד המקצוע של עריכת הדין, כפי שמעוגן בסעיף 20 לחוק לשכת עורכי הדין, ובסנקציות החלות על מי שמסיג גבול מקצוע זה. היא מדגישה את ההגנה על הציבור מפני גורמים בלתי מוסמכים ואת חשיבות הפיקוח על מתן שירותים משפטיים.', 'סעיף 20 לחוק לשכת עורכי הדין, תשכ"א-1961, מייחד פעולות מסוימות לעורכי דין בלבד, ובהן: ייצוג אדם אחר בפני בתי משפט, בתי דין וגופים בעלי סמכות שיפוטית או מעין שיפוטית (כמו ועדות רפואיות), עריכת מסמכים בעלי אופי משפטי, וייעוץ וחיווי דעת משפטיים. חברת ''מימוש זכויות בע"מ'' המבצעת פעולות אלו מסיגה את גבול מקצוע עריכת הדין. סעיף 96 לחוק קובע כי מי שאינו עורך דין ועושה פעולה שיוחסה לעורכי דין, דינו קנס. בנוסף, סעיף 98(א) לחוק קובע כי בית משפט לא יזדקק לתביעת שכר בעד שירות שנתן מי שאינו עורך דין, במידה שהיה בו שירות שיוחד לעורכי דין. לכן, החברה חשופה הן לסנקציות פליליות והן לשלילת זכותה לתבוע שכר עבור שירותיה.',
    'הטעות היא לחשוב שרק ייצוג בבתי משפט נחשב הסגת גבול מקצוע, או להתעלם מהסנקציה האזרחית של שלילת שכר.', '["ייחוד המקצוע", "חוק לשכת עורכי הדין סעיף 20", "חוק לשכת עורכי הדין סעיף 96", "חוק לשכת עורכי הדין סעיף 98(א)", "הסגת גבול מקצוע", "סנקציות פליליות", "שלילת שכר"]'::jsonb, '**וריאציה 1 — פעולות ייחודיות לעו"ד:** אילו פעולות שמורות לעורכי דין? ← ייצוג, ייעוץ ועריכת מסמכים משפטיים. סעיף 20 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 2 — סנקציה פלילית:** מהי הסנקציה הפלילית על הסגת גבול המקצוע? ← קנס. סעיף 96 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — סנקציה אזרחית:** מהי הסנקציה האזרחית על הסגת גבול המקצוע? ← שלילת שכר. סעיף 98(א) לחוק לשכת עורכי הדין, התשכ"א-1961', 'גוף לא-עו"ד מבצע פעולות ייחודיות לעו"ד ← הסגת גבול מקצוע ← סנקציה פלילית (קנס) + שלילת שכר.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיפים 20, 96, 98(א)", "ת\"א (מחוזי נצ'') 26961-12-10 מוניציפל בע\"מ נ'' עו\"ד שגיא רובין (29.10.2013)", "תא\"ק (שלום ת\"א) 59511-05-16 א. המאירי מיסוי עירוני בע\"מ נ'' חייקה בע\"מ (04.06.2017)", "ת\"א (מחוזי י-ם) 3002-09 לשכת עורכי הדין בישראל נ'' הכספת שירותי עזר בגבייה חוקית בע\"מ (18.11.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'פעילות החברה מותרת, שכן היא אינה מייצגת בבתי משפט.', false, 'טענה זו שגויה. סעיף 20 לחוק לשכת עורכי הדין מייחד פעולות רבות לעורכי דין, כולל ייעוץ ועריכת מסמכים משפטיים, ואינו מוגבל לייצוג בבתי משפט בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'פעילות החברה מהווה הסגת גבול מקצוע עריכת הדין, והיא חשופה לסנקציות פליליות ואינה יכולה לתבוע שכר עבור שירותים אלו.', true, 'סעיף 20 לחוק לשכת עורכי הדין מייחד פעולות כמו ייעוץ משפטי, עריכת מסמכים משפטיים וייצוג בפני גופים בעלי סמכות שיפוטית או מעין שיפוטית (כמו ועדות רפואיות) לעורכי דין בלבד. סעיף 96 לחוק קובע סנקציה פלילית על מי שאינו עורך דין ועושה פעולות אלו, וסעיף 98(א) שולל את זכותו לתבוע שכר עבורן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פעילות החברה מותרת, כל עוד היא מבהירה ללקוחותיה שאינה משרד עורכי דין.', false, 'טענה זו שגויה. אף שהבהרה כזו חשובה, היא אינה מכשירה פעולות המהוות הסגת גבול מקצוע עריכת הדין, האסורות על פי חוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'החברה חשופה לסנקציות פליליות בלבד, אך יכולה לתבוע שכר עבור שירותיה.', false, 'טענה זו שגויה. בנוסף לסנקציה הפלילית, סעיף 98(א) לחוק לשכת עורכי הדין שולל את זכותה של החברה לתבוע שכר עבור שירותים שיוחדו לעורכי דין.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 1, '2019-S-S-Q01';
END
$$;

