-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b08a1257-3ad5-40d6-b378-1132163b049f'::uuid;
  v_group_id uuid := '1bad643b-719d-4a76-9616-0b32e91c00d4'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
