  v_ang_0 uuid := 'd6bce3dd-38dd-4bb9-9497-c5884520296e'::uuid;
  v_ang_1 uuid := 'da8be4dc-0773-413d-8cdc-4442f107e629'::uuid;
  v_ang_2 uuid := '2e7e37d5-5fa5-43b8-84ee-963c4fc610f4'::uuid;
  v_ang_3 uuid := 'd6bcdfe6-ddae-41fa-ab54-52539c196ba5'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q02';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 2, '2019-S-S-Q02';
