  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q02', v_chapter_id, v_subtopic_id, 'אחריותו של מבקר המדינה היא:',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 2}'::jsonb, 'השאלה עוסקת באחריותו של מבקר המדינה, מוסד בעל מעמד חוקתי ייחודי במערך הרשויות בישראל. היא בוחנת את עקרון הפרדת הרשויות ואת מיקומו של מבקר המדינה כגוף עצמאי, האחראי בפני הכנסת בלבד, ואינו תלוי בממשלה. אחריות זו מבטיחה את יכולתו לפקח על פעולות המינהל הציבורי ללא חשש מהתערבות הרשות המבצעת.', 'סעיף 6 לחוק יסוד: מבקר המדינה קובע במפורש כי "במילוי תפקידיו יהיה מבקר המדינה אחראי בפני הכנסת בלבד ולא יהיה תלוי בממשלה". הכנסת היא בית הנבחרים של המדינה, כפי שנקבע בסעיף 1 לחוק יסוד: הכנסת. אחריות זו מבטיחה את עצמאותו של מבקר המדינה מהרשות המבצעת, ומאפשרת לו למלא את תפקידו כגורם מפקח על גורמי השלטון. מבקר המדינה נתפס לעיתים כ"רשות הרביעית" או "הרשות המבקרת", והוא פועל בשמה של הכנסת, אך אינו כפוף להוראותיה בפעולותיו. עצמאות זו מחוזקת גם על ידי העובדה שתקציבו נקבע על ידי ועדת הכספים של הכנסת (סעיף 10 לחוק יסוד: מבקר המדינה), וכי הוא אינו יכול להיות מועבר מכהונתו אלא ברוב מיוחד של חברי הכנסת (סעיף 13 לחוק יסוד: מבקר המדינה).', 'הטעות הנפוצה היא לבלבל בין אחריותו של מבקר המדינה לבין אחריותם של גופים אחרים במדינה, כגון הרשות המבצעת או הרשות השופטת, או לא להבין את מעמדו העצמאי והחוקתי הייחודי.',
    '["מבקר המדינה", "חוק יסוד: מבקר המדינה", "אחריותיות", "הכנסת", "עצמאות מבקר המדינה", "הפרדת רשויות", "רשות מבקרת"]'::jsonb, '**וריאציה 1 — אחריות ישירה:** בפני מי אחראי מבקר המדינה? ← בפני הכנסת בלבד. סעיף 6 לחוק-יסוד: מבקר המדינה
**וריאציה 2 — אי-תלות:** האם מבקר המדינה תלוי בממשלה? ← לא, הוא אינו תלוי בממשלה. סעיף 6 לחוק-יסוד: מבקר המדינה
**וריאציה 3 — מעמד:** כיצד נתפס מעמדו של מבקר המדינה? ← כ"רשות הרביעית" או "הרשות המבקרת". בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)', 'מבקר המדינה ← אחראי בפני הכנסת בלבד ← עצמאי מהממשלה ← נחשב ל"רשות הרביעית".', '["חוק-יסוד: מבקר המדינה, סעיפים 6, 10, 13", "בג\"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)", "רע\"א 5985/03 מדינת ישראל (משרד הבינוי והשיכון) נ'' אפרופים שיכון וייזום (1991) בע\"מ (03.11.2003)", "ת\"א (מחוזי חי'') 52925-02-12 קונדיטוריה שפיק בע\"מ ואח'' נ'' מדינת ישראל (25.02.2015)", "יצחק זמיר הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 61: מבקר המדינה"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''administrative'' subtopic=''administrative_authority_discretion'' | classifier_note: State Comptroller (מבקר המדינה) responsibilities — constitutional/admin governance; no dedicated subtopic | source_review_note: תת-הנושא ''ביטול סמכות בג"ץ'' אינו מתאים באופן מדויק לשאלה העוסקת באחריותו של מבקר המדינה. יש לשקול הוספת תת-נושא כללי יותר תחת ''חוקתי + בינלאומי פרטי'' שיעסוק במעמד ובתפקידי מוסדות המדינה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בפני נשיא המדינה.', false, 'טענה זו שגויה. נשיא המדינה הוא ראש המדינה, אך מבקר המדינה אינו אחראי בפניו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בפני הרשות המבצעת.', false, 'טענה זו שגויה. מבקר המדינה הוא גוף עצמאי ואינו תלוי בממשלה, שהיא הרשות המבצעת, אלא מבקר אותה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בפני בית הנבחרים של המדינה.', true, 'סעיף 6 לחוק יסוד: מבקר המדינה קובע במפורש כי מבקר המדינה אחראי בפני הכנסת בלבד, שהיא בית הנבחרים של המדינה. אחריות זו מבטיחה את עצמאותו של המבקר מהרשות המבצעת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בפני הרשות השופטת.', false, 'טענה זו שגויה. הרשות השופטת מפקחת על חוקיות פעולות הרשויות, אך מבקר המדינה אינו אחראי בפניה באופן ישיר על מילוי תפקידו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מעמד מבקר המדינה כ"רשות הרביעית"',
    1, 'כיצד נתפס מעמדו של מבקר המדינה במערך הרשויות בישראל?', 'שאלה זו עוסקת במעמדו הייחודי של מבקר המדינה במערך הרשויות בישראל. היא מדגישה את היותו מוסד בעל מעמד חוקתי, עצמאי ובלתי תלוי, המכונה לעיתים "הרשות הרביעית" או "הרשות המבקרת", ואת תפקידו בפיקוח על המינהל הציבורי.', 'מוסד מבקר המדינה הינו מוסד בעל מעמד חוקתי, השואב את סמכויותיו מחוק יסוד: מבקר המדינה ומחוק מבקר המדינה, התשי"ח-1958. הוא נתפס לעיתים כ"רשות הרביעית" או "הרשות המבקרת", בשל עצמאותו ואי-תלותו ברשות המבצעת. תפקידו המרכזי הוא לפקח על אופן פעולת המינהל הציבורי, לאתר ליקויים, להצביע על כשלים ולהמליץ המלצות לתיקון. המבקר אחראי בפני הכנסת בלבד, מה שמבטיח את אי-תלותו בממשלה. מעמד זה מבדיל אותו מגופים אחרים במדינה ומעניק לו סמכות מוסרית וציבורית רבה.',
    'הטעות הנפוצה היא לבלבל בין מבקר המדינה לבין גופים אחרים במערך השלטוני, כגון מבקר פנימי או זרוע של הרשות המבצעת, ובכך לא להבין את ייחודו ועצמאותו.', '["מבקר המדינה", "מעמד חוקתי", "רשות רביעית", "עצמאות מבקר המדינה", "פיקוח על המינהל הציבורי", "חוק יסוד: מבקר המדינה"]'::jsonb, '**וריאציה 1 — מעמד חוקתי:** מהו מעמדו של מבקר המדינה? ← מוסד בעל מעמד חוקתי, נתפס כ"רשות הרביעית". בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)
**וריאציה 2 — אחריות:** בפני מי אחראי מבקר המדינה? ← בפני הכנסת בלבד, אינו תלוי בממשלה. סעיף 6 לחוק-יסוד: מבקר המדינה
**וריאציה 3 — תפקיד:** מהו תפקידו המרכזי של המבקר? ← לפקח על אופן פעולת המינהל הציבורי. בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)', 'מבקר המדינה ← רשות רביעית ← מעמד חוקתי ← אחראי בפני הכנסת בלבד.',
    '["חוק-יסוד: מבקר המדינה, סעיף 6", "בג\"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)", "ת\"א (מחוזי חי'') 52925-02-12 קונדיטוריה שפיק בע\"מ ואח'' נ'' מדינת ישראל (25.02.2015)", "יצחק זמיר הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 61: מבקר המדינה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כזרוע של הרשות המבצעת, המסייעת לה בפיקוח פנימי.', false, 'טענה זו שגויה. מבקר המדינה הוא גוף עצמאי ונפרד מהרשות המבצעת, ותפקידו לבקר אותה, לא לסייע לה בפיקוח פנימי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כ"רשות הרביעית" או "הרשות המבקרת", בעל מעמד חוקתי ועצמאות תפקודית.', true, 'מוסד מבקר המדינה נתפס כ"רשות הרביעית" או "הרשות המבקרת" בשל מעמדו החוקתי, עצמאותו מהרשות המבצעת ואחריותו הבלעדית בפני הכנסת. תפקידו הוא לפקח על אופן פעולת המינהל הציבורי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כגוף מייעץ לכנסת, ללא סמכויות ביקורת עצמאיות.', false, 'טענה זו שגויה. למבקר המדינה סמכויות ביקורת נרחבות ועצמאיות, והוא אינו רק גוף מייעץ.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כגוף שיפוטי, המוסמך להכריע בסכסוכים מינהליים.', false, 'טענה זו שגויה. מבקר המדינה אינו גוף שיפוטי, וחוות דעתו אינה בבחינת פסק דין או הכרעה שיפוטית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תוקף משפטי של המלצות מבקר המדינה',
    2, 'מהו התוקף המשפטי של המלצות מבקר המדינה, והאם הגוף המבוקר חייב ליישם אותן?', 'שאלה זו עוסקת בתוקפן המשפטי של המלצות מבקר המדינה. היא מבהירה כי אף שלהמלצות אלו אין תוקף מחייב כשל פסק דין, הן אינן חסרות משקל, ועל הגופים המבוקרים מוטל נטל כבד לבחון אותן ולהתייחס אליהן ברצינות, שאם לא כן, עלולה התנהלותם להיחשב כבלתי סבירה.', 'הפסיקה קבעה באופן עקבי כי חוות דעתו של מבקר המדינה אינה בבחינת פסק דין והליך הביקורת אינו בגדר הליך שיפוטי או מעין-שיפוטי. לפיכך, להמלצות המובאות בחוות הדעת אין תוקף משפטי מחייב, ומבקר המדינה אינו יכול לאכוף במישרין על הגוף המבוקר לעשות פעולה או להימנע ממנה. עם זאת, אין להקל ראש במשקל ממצאיו והמלצותיו. גם אם המלצות מבקר המדינה אינן מחייבות במישרין את הרשות לנהוג על-פיהן, הרי שהן משפיעות על האופן שבו עליה להפעיל את שיקול דעתה. אם הגוף המבוקר אינו מיישם את ההמלצות, רובץ עליו נטל לנמק את החלטתו בנימוקים בעלי משקל. התעלמות גורפת ובלתי מנומקת מהמלצות המבקר, או אי-מתן משקל מספק להן, עלולה לעלות כדי אי-סבירות.',
    'הטעות היא להניח שהמלצות המבקר הן חסרות שיניים לחלוטין, או לחלופין, שהן מחייבות כמו פסק דין, מבלי להבין את מעמדן המיוחד כגורם המשפיע על סבירות שיקול הדעת המינהלי.', '["המלצות מבקר המדינה", "תוקף משפטי", "שיקול דעת מינהלי", "חוסר סבירות", "נטל נימוק", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — תוקף מחייב:** האם המלצות המבקר מחייבות? ← לא, אין להן תוקף משפטי מחייב. בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)
**וריאציה 2 — חובת התייחסות:** מהי חובת הגוף המבוקר? ← לבחון את ההמלצות ולהעניק להן משקל ראוי. בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)
**וריאציה 3 — התעלמות:** מהי ההשלכה של התעלמות מהמלצות המבקר? ← עלולה לעלות כדי אי-סבירות. בג"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)', 'המלצות מבקר ← לא מחייבות משפטית ← אך דורשות התייחסות רצינית ← התעלמות עלולה להיות בלתי סבירה.',
    '["בג\"ץ 9223/10 התנועה למען איכות השלטון בישראל נ'' ראש הממשלה (19.11.2012)", "ת\"א (מחוזי חי'') 52925-02-12 קונדיטוריה שפיק בע\"מ ואח'' נ'' מדינת ישראל (25.02.2015)", "בג\"ץ 3989/11 תנועת נאמני הר הבית בארץ ישראל נ'' ועדת הכנסת לביקורת המדינה (27.12.2012)", "יצחק זמיר הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 61: מבקר המדינה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המלצות המבקר מחייבות באופן מוחלט, ואי יישומן מהווה עבירה פלילית.', false, 'טענה זו שגויה. להמלצות המבקר אין תוקף משפטי מחייב, ואי יישומן אינו מהווה עבירה פלילית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'להמלצות המבקר אין תוקף משפטי מחייב, אך הגוף המבוקר חייב לבחון אותן ולהעניק להן משקל ראוי, ואי-התייחסות סבירה אליהן עלולה להיחשב כחוסר סבירות.', true, 'הפסיקה קבעה כי חוות דעתו של המבקר אינה בבחינת פסק דין, ולהמלצותיו אין תוקף משפטי מחייב. עם זאת, הגוף המבוקר אינו יכול להתעלם מהן באופן גורף ובלתי מנומק, ועליו לבחון אותן לגופן ולהעניק להן את המשקל הראוי. התעלמות בלתי מנומקת או אי-מתן משקל מספק עלולים לעלות כדי חוסר סבירות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המלצות המבקר מחייבות רק אם אושרו על ידי הכנסת.', false, 'טענה זו שגויה. אף שהכנסת מפקחת על יישום ההמלצות, אין צורך באישור מפורש שלה כדי שהמלצות המבקר יחייבו התייחסות מצד הגוף המבוקר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'להמלצות המבקר אין כל משקל משפטי, והגוף המבוקר רשאי להתעלם מהן לחלוטין.', false, 'טענה זו שגויה. אף שאין להן תוקף מחייב, לממצאים ולהמלצות המבקר יש חשיבות רבה, והתעלמות גורפת מהן עלולה להיחשב כחוסר סבירות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'ביקורת שיפוטית על פעולות מבקר המדינה',
    3, 'האם בית המשפט העליון מוסמך לקיים ביקורת שיפוטית על פעולות מבקר המדינה, ובאילו נסיבות?', 'שאלה זו בוחנת את גבולות הביקורת השיפוטית על פעולות מבקר המדינה. היא מדגישה את האיזון העדין בין עצמאותו של המבקר לבין הצורך בפיקוח שיפוטי, ומבהירה כי בית המשפט נוהג בריסון רב ויתערב רק במקרים חריגים וקיצוניים.', 'מעמדו המיוחד של מבקר המדינה, כרשות עצמאית ואחראית בפני הכנסת בלבד, מחייב את בית המשפט לנהוג בזהירות ובריסון רב בבואו לבחון את סבירות פעילותו. הפסיקה קבעה כי בית המשפט ימעט להתערב בעניינים שהועמדו לביקורת על ידי מבקר המדינה, והדברים יפים גם לגבי החלטותיו אם להידרש לנושא מסוים אם לאו. התערבות שיפוטית תתאפשר רק במקרים חריגים וקיצוניים, כגון חריגה מסמכות, חוסר סבירות קיצוני בהחלטותיו, או פגיעה מהותית בזכות הטיעון של המבוקר. הרציונל הוא לשמור על עצמאותו של המבקר ולאפשר לו למלא את תפקידו ללא חשש מהתערבות שיפוטית תכופה.',
    'הטעות היא לחשוב שאין כלל ביקורת שיפוטית על מבקר המדינה, או לחלופין, שביקורת זו זהה לביקורת על רשויות מינהליות אחרות, מבלי להבין את מידת הריסון הנדרשת.', '["ביקורת שיפוטית", "מבקר המדינה", "עצמאות מבקר המדינה", "חריגה מסמכות", "חוסר סבירות קיצוני", "זכות הטיעון", "ריסון שיפוטי"]'::jsonb, '**וריאציה 1 — ריסון שיפוטי:** האם בג"ץ מתערב בפעולות המבקר? ← כן, אך נוהג בריסון רב. בג"ץ 3059/15 התנועה למען איכות השלטון בישראל נ'' בנימין נתניהו, ראש ממשלת ישראל (10.11.2015)
**וריאציה 2 — מתי תתאפשר התערבות?** באילו מקרים יתערב בג"ץ? ← חריגה מסמכות, חוסר סבירות קיצוני, פגיעה בזכות הטיעון. בג"ץ 4914/94 יעקב טרנר נ'' מבקרת המדינה (30.10.1995)
**וריאציה 3 — שיקול דעת המבקר:** האם בג"ץ יתערב בשיקול דעת המבקר בבחירת נושאי ביקורת? ← ימעט להתערב, למבקר שיקול דעת רחב. בג"ץ 6700/19 אליעזר דוד הברפלד נ'' מבקר המדינה (04.02.2020)', 'ביקורת שיפוטית על מבקר ← בריסון רב ← רק במקרים חריגים (סמכות, סבירות קיצונית, זכות טיעון).',
    '["בג\"ץ 4914/94 יעקב טרנר נ'' מבקרת המדינה (30.10.1995)", "בג\"ץ 4870/10 רות בלום-דוד, עו\"ד נ'' מבקר המדינה (23.06.2011)", "בג\"ץ 3059/15 התנועה למען איכות השלטון בישראל נ'' בנימין נתניהו, ראש ממשלת ישראל (10.11.2015)", "בג\"ץ 6700/19 אליעזר דוד הברפלד נ'' מבקר המדינה (04.02.2020)", "יצחק זמיר הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 61: מבקר המדינה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מבקר המדינה פטור באופן מוחלט מביקורת שיפוטית בשל עצמאותו.', false, 'טענה זו שגויה. מבקר המדינה אינו פטור באופן מוחלט מביקורת שיפוטית, אם כי בית המשפט נוהג בריסון רב בהתערבות בפעולותיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, בית המשפט מוסמך לקיים ביקורת שיפוטית על פעולות המבקר, אך נוהג בריסון רב ויתערב רק במקרים חריגים של חריגה מסמכות, חוסר סבירות קיצוני או פגיעה בזכות הטיעון.', true, 'הפסיקה קבעה כי מבקר המדינה פטור במידה רבה, אך לא באופן מוחלט, מביקורת בג"ץ. בית המשפט ימעט להתערב בעניינים שהועמדו לביקורת על ידי מבקר המדינה, ויתערב רק במקרים חריגים וקיצוניים, כגון חריגה מסמכות, חוסר סבירות קיצוני בהחלטותיו, או פגיעה מהותית בזכות הטיעון של המבוקר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, בית המשפט מוסמך לבקר את פעולות המבקר באותה מידה שבה הוא מבקר כל רשות מינהלית אחרת.', false, 'טענה זו שגויה. בשל מעמדו המיוחד של מבקר המדינה, בית המשפט נוהג בריסון רב יותר בביקורת על פעולותיו מאשר על רשויות מינהליות רגילות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן המבקר עצמו מבקש את התערבות בית המשפט.', false, 'טענה זו שגויה. סמכות הביקורת השיפוטית אינה תלויה בבקשת המבקר, אלא נובעת מסמכותו של בית המשפט לפקח על חוקיות פעולות הרשויות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תפקידי מבקר המדינה כנציב תלונות הציבור',
    4, 'מהם תפקידיו של מבקר המדינה כנציב תלונות הציבור, ומה ההבדל המהותי בינו לבין תפקידו כמבקר המדינה?', 'שאלה זו מתמקדת בשני כובעיו של מבקר המדינה: כמבקר המדינה וכנציב תלונות הציבור. היא מבהירה את ההבדלים המהותיים בין שני התפקידים מבחינת יוזמת הביקורת, היקפה, וסוג הליקויים הנבדקים, תוך הדגשת חלוקת העבודה בין ביקורת רוחבית ויזומה לבין בירור תלונות אינדיווידואליות.', 'מבקר המדינה מפעיל את הביקורת בשתי דרכים עיקריות: האחת, הכנת דוחות וחוות דעת על המשק, הנכסים, הכספים, ההתחייבויות והמינהל של הגופים המבוקרים, אותם הוא מגיש לכנסת ומפרסם ברבים. בתפקיד זה, הביקורת היא יזומה ומתוכננת, ונועדה לבדוק תחומי פעולה שלמים. השנייה, במעמד של נציב תלונות הציבור, הוא מברר תלונות מאת הציבור נגד גוף מבוקר בגין מעשה מסוים הפוגע באדם מסוים. בתפקיד זה, המבקר אינו רשאי לערוך בירור ביוזמתו, אלא רק כאשר הוגשה אליו תלונה. ההבדל המהותי הוא שביקורת המדינה היא רוחבית ומערכתית, ואילו בירור תלונות הציבור הוא פרטני ואינדיווידואלי. עם זאת, גם כנציב תלונות הציבור, החלטות המבקר אינן יכולות להעניק זכות או סעד בבית משפט.',
    'הטעות היא לראות בשני התפקידים זהות מוחלטת, או לבלבל בין סמכויות הביקורת היזומה לבין סמכויות בירור התלונות, ובכך לא להבין את חלוקת העבודה המובהקת שקבע המחוקק.', '["מבקר המדינה", "נציב תלונות הציבור", "ביקורת יזומה", "בירור תלונות", "חלוקת עבודה", "חוק יסוד: מבקר המדינה", "חוק מבקר המדינה"]'::jsonb, '**וריאציה 1 — תפקיד מבקר המדינה:** מהו תפקידו כמבקר המדינה? ← עריכת ביקורת יזומה ורוחבית על גופים מבוקרים. סעיף 2(א) לחוק-יסוד: מבקר המדינה
**וריאציה 2 — תפקיד נציב תלונות הציבור:** מהו תפקידו כנציב תלונות הציבור? ← בירור תלונות אינדיווידואליות שהוגשו אליו. סעיף 4 לחוק-יסוד: מבקר המדינה
**וריאציה 3 — סמכות להוציא צווים:** האם לנציב תלונות הציבור סמכות להוציא צווים מחייבים? ← לא, החלטותיו אינן יכולות להעניק זכות או סעד בבית משפט. יואב דותן ביקורת שיפוטית על שיקול דעת מינהלי כרך א (2022) | 3.4.1 מבקר המדינה ונציב תלונות הציבור', 'מבקר המדינה ← ביקורת יזומה ורוחבית. נציב תלונות הציבור ← בירור תלונות אינדיווידואליות.',
    '["חוק-יסוד: מבקר המדינה, סעיפים 2, 4", "יצחק זמיר הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 61: מבקר המדינה", "יואב דותן ביקורת שיפוטית על שיקול דעת מינהלי כרך א (2022) | 3.4.1 מבקר המדינה ונציב תלונות הציבור"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כנציב תלונות הציבור, המבקר מברר תלונות יזומות על ליקויים מערכתיים, בדומה לתפקידו כמבקר המדינה.', false, 'טענה זו שגויה. כנציב תלונות הציבור, המבקר מברר תלונות אינדיווידואליות שהוגשו אליו, ולא ליקויים מערכתיים ביוזמתו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כנציב תלונות הציבור, המבקר מברר תלונות אינדיווידואליות שהוגשו אליו על מעשים הפוגעים באדם מסוים, בעוד שתפקידו כמבקר המדינה הוא לערוך ביקורת יזומה ורוחבית על גופים מבוקרים.', true, 'חוק יסוד: מבקר המדינה קובע כי המבקר יברר תלונות מאת הציבור על גופים ואנשים בתפקידו כ"נציב תלונות הציבור". תפקיד זה מתמקד בתלונות אינדיווידואליות על מעשים הפוגעים באדם מסוים. לעומת זאת, תפקידו כמבקר המדינה הוא לערוך ביקורת יזומה ורוחבית על המשק, הנכסים, הכספים והמינהל של הגופים המבוקרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'אין הבדל מהותי בין שני התפקידים, שניהם עוסקים בביקורת על רשויות המדינה.', false, 'טענה זו שגויה. קיים הבדל מהותי בין שני התפקידים מבחינת יוזמת הביקורת, היקפה וסוג הליקויים הנבדקים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כנציב תלונות הציבור, המבקר מוסמך להוציא צווים מחייבים, בניגוד לתפקידו כמבקר המדינה.', false, 'טענה זו שגויה. גם כנציב תלונות הציבור, החלטות המבקר אינן יכולות להעניק זכות או סעד בבית משפט, ואין לו סמכות להוציא צווים מחייבים, למעט חריגים ספציפיים להגנת חושפי שחיתויות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 2, '2019-S-S-Q02';
END
$$;

-- ============================================================
-- Q03 — 2019-S-S-Q03 — chapter=corporate subtopic=fiduciary_duties
-- classifier_note: Business judgment rule — officer duty of care
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e746f5c3-35aa-4b04-9b58-a1075bbd3e9f'::uuid;
  v_group_id uuid := '0c5ee068-fada-4245-a5cf-7965877a6590'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '09a13261-f750-4a6c-a849-2898a0e936fc'::uuid;
  v_ang_1 uuid := 'd68c4328-b804-4b23-bf4c-4e730a893341'::uuid;
  v_ang_2 uuid := '43a8263b-6bfc-4cac-9553-b92820afb0fa'::uuid;
  v_ang_3 uuid := 'e8bd61ee-f560-411d-91e6-d4add81395cb'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q03';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 3, '2019-S-S-Q03';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_duties' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q03', v_chapter_id, v_subtopic_id, 'איזה מהמשפטים הבאים הוא המדויק ביותר בנוגע לכלל שיקול הדעת העסקי:',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 3}'::jsonb, 'השאלה עוסקת בכלל שיקול הדעת העסקי (Business Judgment Rule), שהוא עקרון יסוד בדיני החברות בישראל, כפי שאומץ בפסיקת בית המשפט העליון בעניין ורדניקוב. הכלל מקנה לנושאי משרה "חזקת תקינות" מפני ביקורת שיפוטית מהותית על החלטותיהם העסקיות, וזאת בהתקיים שלושה תנאים מצטברים: היעדר ניגוד עניינים, תום לב סובייקטיבי, והחלטה "מיודעת". הנטל הראשוני לסתור חזקה זו מוטל על התובע.', 'כלל שיקול הדעת העסקי, שאומץ בפסיקת בית המשפט העליון בעניין ורדניקוב (ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ, פסקה 74; Reference 1, 2, 4, 5, 6, 9, 11, 12, 14, 18, 19, 20, 22, 24, 26, 27), קובע כי החלטות עסקיות שקיבלו נושאי משרה בחברה נהנות מ"חזקת תקינות". חזקה זו מקנה לנושאי המשרה מעין "חסינות" מפני הפעלת ביקורת שיפוטית מהותית על תוכן ההחלטה העסקית, וזאת בהתמלא שלושה תנאים מצטברים: 1. ההחלטה התקבלה שלא מתוך ניגוד עניינים. 2. ההחלטה התקבלה בתום לב (סובייקטיבי). 3. ההחלטה הייתה "מיודעת", כלומר לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים (Reference 1, 4, 5, 9, 11, 12, 19, 20, 22, 23, 24, 26). נושא משרה שקיבל החלטה תוך עמידה בשלושת התנאים הללו, ייהנה מ"חזקת תקינות", ובית המשפט ימשוך ידיו מבחינת הפעולה העסקית לגופה. מבחינה דיונית, הנטל הראשוני לסתור את חזקת התקינות המוקנית לנושאי המשרה מכוח הכלל מוטל על התובע (Reference 1, 2, 4, 5, 8, 9, 11, 12, 20, 22, 23, 24, 25, 26). אם לא עלה בידי התובע לסתור את חזקת התקינות, בית המשפט אינו נדרש לתוכן ההחלטה לגופה, אלא בוחן את הליך קבלת ההחלטה (Reference 1, 2, 11, 24).', 'הטעות הנפוצה היא לבלבל בין תנאי הכלל, או לחשוב שהכלל מקנה חסינות מוחלטת, או לטעות בזהות הצד הנושא בנטל ההוכחה הראשוני.',
    '["כלל שיקול הדעת העסקי", "חזקת תקינות", "חובת זהירות", "נושאי משרה", "ניגוד עניינים", "תום לב", "החלטה מיודעת", "נטל הוכחה"]'::jsonb, '**וריאציה 1 — תנאי הכלל:** מהם שלושת התנאים לתחולת כלל שיקול הדעת העסקי? ← היעדר ניגוד עניינים, תום לב, החלטה מיודעת. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל הראשוני לסתור את חזקת התקינות? ← התובע. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 3 — היקף הביקורת:** מה בוחן בית המשפט כאשר הכלל חל? ← את הליך קבלת ההחלטה, ולא את תוכן ההחלטה לגופה. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)', 'כלל שיקול הדעת העסקי ← חזקת תקינות לנושאי משרה ← בתנאי: ללא ניגוד עניינים, בתום לב, מיודעת ← נטל סתירה על התובע.', '["ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)", "ע\"א 7829/18 בטר פלייס ישראל נ'' שי אגסי (08.02.2022)", "ע\"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע\"מ (24.04.2018)", "תנ\"ג (מחוזי תל אביב-יפו) 36670-01-22 אורן דה לנגה נ'' יעקב אטרקצ''י (08.04.2025)", "צפורה כהן נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | א. התנאים לתחולת ההגנה"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''תובענות ייצוגיות'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Business judgment rule — officer duty of care | source_review_note: הסיווג לתת-נושא ''תובענות ייצוגיות'' אינו מדויק, שכן השאלה עוסקת בכלל שיקול הדעת העסקי שהוא עקרון יסוד בדיני חברות הנוגע לאחריות נושאי משרה, ולא רק לתובענות ייצוגיות. יש לשקול הוספת תת-נושא מתאים יותר ל''דיני חברות'' או ''אחריות נושאי משרה'' תחת פרק רחב יותר של ''דיני תאגידים'' או ''משפט מסחרי''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הכלל מעניק הגנה לנושאי משרה בחברה מפני תביעה בנוגע להחלטות שקיבלו אם פעלו בהיעדר ניגוד עניינים, בתום לב, וההחלטה שקיבלו הייתה "מיודעת", כלומר לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים. הנטל הראשוני לסתור את חזקת התקינות המוקנית לנושאי המשרה מכוח הכלל מוטל על התובע.', true, 'משפט זה מתאר במדויק את כלל שיקול הדעת העסקי כפי שאומץ בפסיקה הישראלית, כולל שלושת התנאים המצטברים לתחולתו (היעדר ניגוד עניינים, תום לב, החלטה מיודעת) ואת נטל ההוכחה הראשוני המוטל על התובע לסתור את חזקת התקינות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הכלל מעניק הגנה לנושאי משרה בחברה מפני תביעה בנוגע להחלטות שקיבלו אם פעלו בהיעדר ניגוד עניינים, בתום לב, וההחלטה הייתה "מיודעת", כלומר לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים, גם אם פעלו בפזיזות.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי אינו מגן על נושאי משרה שפעלו בפזיזות, שכן פזיזות עלולה להעיד על חוסר תום לב או על קבלת החלטה בלתי מיודעת, ובכך לסתור את חזקת התקינות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הכלל מעניק הגנה לנושאי משרה בחברה מפני תביעה בנוגע להחלטות שקיבלו אם פעלו בהיעדר ניגוד עניינים, בתום לב, וההחלטה הייתה "מיודעת", כלומר לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים, ובתנאי שבתקנון החברה הוענק לנושאי המשרה פטור מפני תביעות.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי הוא כלל משפטי עצמאי שאינו תלוי בקיומו של פטור בתקנון החברה. פטור הוא מנגנון נפרד להגבלת אחריות נושאי משרה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הכלל מעניק הגנה לנושאי משרה בחברה מפני תביעה בנוגע להחלטות שקיבלו נושאי המשרה אם פעלו בהיעדר ניגוד עניינים, בתום לב, וההחלטה הייתה "מיודעת", כלומר לאחר עיון בנתונים ושקילת השיקולים הרלוונטיים. נטל ההוכחה מוטל על נושאי המשרה בלבד.', false, 'טענה זו שגויה. הנטל הראשוני לסתור את חזקת התקינות מוטל על התובע, ורק אם הוא עמד בנטל זה, עשוי הנטל לעבור לנושאי המשרה, בהתאם לנסיבות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחולת כלל שיקול הדעת העסקי על מחדלים',
    1, 'דירקטוריון חברת "אלפא בע"מ" נמנע מלקבל החלטה אקטיבית בנוגע להשקעה קריטית, למרות שהוצגו בפניו נתונים רלוונטיים. כתוצאה מכך, החברה הפסידה הזדמנות עסקית משמעותית. האם כלל שיקול הדעת העסקי יגן על הדירקטורים מפני תביעה בגין מחדלם?', 'שאלה זו בוחנת את תחולתו של כלל שיקול הדעת העסקי על מחדלים של נושאי משרה, ולא רק על החלטות אקטיביות. הפסיקה הכירה באפשרות להחיל את הכלל גם על מחדלים, אך הדגישה את הקושי היישומי ואת הצורך לבחון האם המחדל עולה כדי חוסר תום לב או אי-קבלת החלטה "מיודעת", ובכך לסתור את חזקת התקינות.', 'כלל שיקול הדעת העסקי מקנה לנושאי משרה "חזקת תקינות" מפני ביקורת שיפוטית על החלטותיהם, אם התקיימו שלושה תנאים: היעדר ניגוד עניינים, תום לב סובייקטיבי, והחלטה "מיודעת" (informed decision). הפסיקה בישראל, ובפרט בעניין פינרוס (Reference 13, 17), קבעה כי ניתן להחיל את כלל שיקול הדעת העסקי גם על טענות למחדלים בפעולותיהם של נושאי המשרה בחברה. עם זאת, הקושי בהחלת הכלל על מחדלים קיים ברמה היישומית, שכן קשה לקבוע לגבי מחדל כי הוא התקבל בחוסר תום לב או בניגוד עניינים. במקרים כאלה, על התובע להראות כי נושאי המשרה היו יכולים להפעיל את שיקול דעתם העסקי אך בחרו שלא למלא אחר חובתם כנדרש, או האצילו את סמכותם שלא כדין. הימנעות מקבלת החלטה אקטיבית למרות קיומו של מידע רלוונטי עלולה להיחשב כהחלטה בלתי "מיודעת" או כחוסר תום לב, ובכך לסתור את חזקת התקינות המוקנית לנושאי המשרה.',
    'הטעות היא להניח שכלל שיקול הדעת העסקי חל רק על פעולות אקטיביות, או לחלופין, שהוא מגן באופן אוטומטי על מחדלים, מבלי לבחון את התקיימות תנאיו גם במקרה של מחדל.', '["כלל שיקול הדעת העסקי", "מחדל נושא משרה", "חובת זהירות", "חזקת תקינות", "החלטה מיודעת", "נטל הוכחה"]'::jsonb, '**וריאציה 1 — תחולה על מחדלים:** האם כלל שיקול הדעת העסקי חל על מחדלים? ← כן, ניתן להחיל אותו גם על מחדלים. ע"א 3417/16 פינרוס החזקות בע"מ נ'' התובע הייצוגי דב גולדשטיין (12.07.2021)
**וריאציה 2 — קושי יישומי:** מהו הקושי בהחלת הכלל על מחדלים? ← קשה לקבוע לגבי מחדל כי הוא התקבל בחוסר תום לב או בניגוד עניינים. ע"א 3417/16 פינרוס החזקות בע"מ נ'' התובע הייצוגי דב גולדשטיין (12.07.2021)
**וריאציה 3 — סתירת החזקה במחדל:** כיצד ניתן לסתור את חזקת התקינות במקרה של מחדל? ← להראות שנושאי המשרה היו יכולים לפעול אך בחרו שלא למלא חובתם, או האצילו סמכות שלא כדין. ע"א 3417/16 פינרוס החזקות בע"מ נ'' התובע הייצוגי דב גולדשטיין (12.07.2021)', 'כלל שיקול הדעת העסקי ← חל גם על מחדלים ← אך קשה יותר להוכיח תנאיו ← הימנעות מפעולה מיודעת סותרת חזקה.',
    '["ע\"א 3417/16 פינרוס החזקות בע\"מ נ'' התובע הייצוגי דב גולדשטיין (12.07.2021)", "ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)", "צפורה כהן נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | א. התנאים לתחולת ההגנה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, כלל שיקול הדעת העסקי חל רק על החלטות אקטיביות ולא על מחדלים.', false, 'טענה זו שגויה. הפסיקה הכירה באפשרות להחיל את כלל שיקול הדעת העסקי גם על מחדלים, אם כי היישום מורכב יותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, כלל שיקול הדעת העסקי יכול לחול גם על מחדלים, אך במקרה זה, הימנעות מקבלת החלטה למרות מידע רלוונטי עלולה להיחשב כהחלטה בלתי "מיודעת" או חוסר תום לב, ובכך לסתור את חזקת התקינות.', true, 'הפסיקה קבעה כי כלל שיקול הדעת העסקי יכול לחול גם על מחדלים, אך במקרים של מחדל, קשה יותר לעמוד בתנאי ה"החלטה מיודעת" או "תום לב", מה שעלול להוביל לסתירת חזקת התקינות. הימנעות מפעולה אקטיבית למרות מידע רלוונטי עלולה להיחשב כהפרת חובת הזהירות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, כל עוד הדירקטורים פעלו בתום לב ולא היה להם ניגוד עניינים, הכלל יגן עליהם גם במקרה של מחדל.', false, 'טענה זו שגויה. גם אם התקיימו תום לב והיעדר ניגוד עניינים, מחדל מפעולה למרות מידע רלוונטי עלול להעיד על חוסר קיום תנאי ה"החלטה מיודעת" ובכך לסתור את חזקת התקינות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן הדירקטוריון קיבל החלטה מפורשת שלא להשקיע, ולא רק נמנע מפעולה.', false, 'טענה זו שגויה. אף שהקושי ביישום הכלל על מחדלים קיים, הפסיקה הכירה באפשרות להחילו גם על מחדלים, ולא רק על החלטות אקטיביות מפורשות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'נטל ההוכחה בסתירת חזקת התקינות',
    2, 'חברת "בטא בע"מ" הגישה תביעה נגד דירקטור בחברה בטענה להפרת חובת זהירות, לאחר שהחלטה עסקית שקיבל הדירקטור גרמה לחברה נזק כבד. הדירקטור טוען להגנת כלל שיקול הדעת העסקי. מהו נטל ההוכחה המוטל על הצדדים בנסיבות אלו?', 'שאלה זו מתמקדת במשטר נטל ההוכחה הייחודי החל כאשר מועלית טענה להגנת כלל שיקול הדעת העסקי. היא מבהירה כי הנטל הראשוני לסתור את חזקת התקינות מוטל על התובע, ורק לאחר מכן, אם עמד בנטל זה, עשוי הנטל לעבור לנושאי המשרה להוכיח את הגינות ההחלטה.', 'כלל שיקול הדעת העסקי הוא במהותו כלל היוצר לטובת הנתבע (נושא המשרה) חזקה הניתנת לסתירה, ועל התובע מוטל הנטל הראשוני לסתור את "חזקת התקינות" המוקנית לנושאי המשרה מכוח כלל זה (עניין ורדניקוב, פסקה 75; Reference 1, 2, 4, 5, 8, 9, 11, 12, 20, 22, 23, 24, 25, 26). על התובע להראות כי ההחלטה התקבלה בחוסר תום לב סובייקטיבי, מתוך ניגוד עניינים, או שההחלטה הייתה בלתי "מיודעת" (דהיינו מבלי שנבחנו הנסיבות והעובדות המרכזיות הנוגעות לעניין). ככל שלא יעלה בידי התובע לעשות כן, יוסיפו נושאי המשרה ליהנות מהחזקה כי ההחלטה שקיבלו הייתה סבירה, והתביעה נגדם "תיחסם". אם עלה בידי התובע לסתור את חזקת התקינות, כי אז יחול סטנדרט ביקורת שיפוטית מחמיר יותר על ההחלטה, ולעיתים קרובות יעבור הנטל אל נושאי המשרה להוכיח את הגינות ההחלטה (עניין ורדניקוב, פסקה 25; Reference 15).',
    'הטעות היא לבלבל את משטר הנטלים ולהטיל את הנטל הראשוני על נושא המשרה, או להתעלם מהאופי הדו-שלבי של בחינת כלל שיקול הדעת העסקי.', '["נטל הוכחה", "חזקת תקינות", "כלל שיקול הדעת העסקי", "סתירת חזקה", "הגינות מלאה", "תום לב", "ניגוד עניינים", "החלטה מיודעת"]'::jsonb, '**וריאציה 1 — נטל ראשוני:** מי נושא בנטל הראשוני לסתור את חזקת התקינות? ← התובע. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 2 — מה צריך התובע להוכיח?** מה צריך התובע להוכיח כדי לסתור את החזקה? ← חוסר תום לב, ניגוד עניינים, או החלטה בלתי מיודעת. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 3 — תוצאת סתירת החזקה:** מה קורה אם התובע סתר את החזקה? ← עובר הנטל לנתבעים להוכיח את הגינות ההחלטה, בסטנדרט מחמיר יותר. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)', 'נטל הוכחה בסתירת BJR ← ראשוני על התובע (חוסר תום לב/ניגוד עניינים/לא מיודע) ← אם נסתר, עובר לנתבעים (הגינות).',
    '["ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)", "ע\"א 7829/18 בטר פלייס ישראל נ'' שי אגסי (08.02.2022)", "תנ\"ג (מחוזי תל אביב-יפו) 36670-01-22 אורן דה לנגה נ'' יעקב אטרקצ''י (08.04.2025)", "צפורה כהן נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | א. התנאים לתחולת ההגנה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הנטל הראשוני מוטל על הדירקטור להוכיח כי ההחלטה התקבלה בהיעדר ניגוד עניינים, בתום לב ובאופן מיודע.', false, 'טענה זו שגויה. הנטל הראשוני לסתור את חזקת התקינות מוטל על התובע, ולא על הדירקטור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הנטל הראשוני מוטל על החברה התובעת להראות כי ההחלטה התקבלה בחוסר תום לב, מתוך ניגוד עניינים או באופן בלתי מיודע. אם עמדה החברה בנטל זה, עובר הנטל לדירקטור להוכיח את הגינות ההחלטה.', true, 'כלל שיקול הדעת העסקי יוצר חזקת תקינות לטובת נושאי המשרה. הנטל הראשוני לסתור חזקה זו מוטל על התובע, ועליו להראות כי אחד משלושת התנאים (היעדר ניגוד עניינים, תום לב, החלטה מיודעת) לא התקיים. רק אם התובע עמד בנטל זה, עובר הנטל לדירקטור להוכיח את הגינות ההחלטה, לעיתים בסטנדרט של "הגינות מלאה".', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הנטל מוטל תמיד על החברה התובעת להוכיח רשלנות, ללא קשר לכלל שיקול הדעת העסקי.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי משנה את משטר הנטלים הרגיל בתביעת רשלנות, ומעניק חזקת תקינות לנושאי המשרה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הנטל מוטל תמיד על הדירקטור להוכיח את סבירות ההחלטה, שכן הוא הגורם המקצועי בחברה.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי נועד להגן על הדירקטורים מפני ביקורת שיפוטית על סבירות ההחלטה, ואינו מטיל עליהם נטל הוכחה ראשוני.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'כלל ההגינות המלאה כסטנדרט ביקורת מחמיר',
    3, 'דירקטוריון חברת "גמא בע"מ" אישר עסקה עם בעל השליטה בחברה, כאשר לבעל השליטה היה עניין אישי מובהק בעסקה. העסקה אושרה ללא גילוי נאות של כל הפרטים הרלוונטיים וללא בחינה מעמיקה של כדאיותה לחברה. האם כלל שיקול הדעת העסקי יגן על הדירקטורים במקרה זה, ואיזה סטנדרט ביקורת יחול?', 'שאלה זו עוסקת במצב שבו כלל שיקול הדעת העסקי נסתר, ובפרט כאשר מדובר בעסקאות עם בעלי עניין הנגועות בניגוד עניינים. במקרים אלו, הפסיקה בישראל, בהשראת הדין בדלאוור, מכירה בהחלת סטנדרט ביקורת מחמיר יותר, כגון כלל ההגינות המלאה, המטיל נטל כבד על נושאי המשרה להוכיח את הגינות העסקה הן פרוצדורלית והן מהותית.', 'כלל שיקול הדעת העסקי אינו חל כאשר ההחלטה התקבלה מתוך ניגוד עניינים או באופן בלתי "מיודע" (עניין ורדניקוב, פסקה 69; Reference 1, 4, 5, 9, 11, 12, 19, 20, 22, 23, 24, 26). במקרה זה, קיומו של עניין אישי מובהק לבעל השליטה, יחד עם חוסר גילוי ואי-בחינה מעמיקה, סותרים את חזקת התקינות. כאשר כלל שיקול הדעת העסקי נסתר, ובפרט במצבים של עסקאות עם בעלי עניין, ניתן להכשיר עסקאות אלה באמצעות עמידה בכלל ההגינות המלאה (Entire Fairness) (עניין ורדניקוב, פסקה 1; Reference 1, 3, 15, 16, 23, 26). כלל זה הוא סטנדרט ביקורת מחמיר, הדורש מהנתבעים להוכיח את הגינותה המלאה של העסקה, הן בהיבט של אופן אישורה (הגינות פרוצדורלית), והן בהיבט הכלכלי-עסקי (הגינות מהותית). יש לציין כי הדין הישראלי קובע הסדר פרוצדורלי מנדטורי לאישור עסקאות עם בעלי עניין, שנועד לנטרל ניגודי אינטרסים בטרם אישור העסקה (Reference 1, 26).',
    'הטעות היא לחשוב שכלל שיקול הדעת העסקי מגן על נושאי משרה גם במקרים של ניגוד עניינים מובהק, או לא להכיר בקיומם של סטנדרטים מחמירים יותר של ביקורת שיפוטית.', '["כלל שיקול הדעת העסקי", "כלל ההגינות המלאה", "ניגוד עניינים", "עסקאות עם בעלי עניין", "הגינות פרוצדורלית", "הגינות מהותית", "חזקת תקינות", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — סתירת BJR בניגוד עניינים:** האם ניגוד עניינים סותר את כלל שיקול הדעת העסקי? ← כן, זהו אחד משלושת התנאים לסתירת החזקה. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 2 — החלת כלל ההגינות המלאה:** מתי יחול כלל ההגינות המלאה? ← כאשר כלל שיקול הדעת העסקי נסתר, בפרט במצבים של עסקאות עם בעלי עניין וניגוד עניינים משמעותי. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)
**וריאציה 3 — דרישות כלל ההגינות המלאה:** מה נדרש להוכיח במסגרת כלל ההגינות המלאה? ← הגינות מלאה של העסקה, הן פרוצדורלית והן מהותית. ע"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)', 'ניגוד עניינים/חוסר יידוע ← סותר BJR ← מחיל כלל הגינות מלאה ← דורש הוכחת הגינות פרוצדורלית ומהותית.',
    '["ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)", "ע\"א 5635404/20 שרון עצמון נ'' אסם השקעות בע\"מ (09.12.2021)", "חוק החברות, תשנ\"ט-1999, סעיף 280", "זוהר גושן אסף אקשטיין דיני חברות (2023) | 7.1 כללי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כלל שיקול הדעת העסקי יגן על הדירקטורים, שכן הוא חל על כל החלטה עסקית.', false, 'טענה זו שגויה. קיומו של ניגוד עניינים מובהק סותר את אחד מתנאי כלל שיקול הדעת העסקי, ולכן הוא לא יגן על הדירקטורים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, כלל שיקול הדעת העסקי לא יגן על הדירקטורים בשל ניגוד העניינים וחוסר היידוע. במקרה זה יחול סטנדרט ביקורת מחמיר יותר, כגון כלל ההגינות המלאה, המחייב את הדירקטורים להוכיח את הגינותה המלאה של העסקה הן פרוצדורלית והן מהותית.', true, 'קיומו של ניגוד עניינים מובהק וחוסר יידוע סותרים את חזקת התקינות של כלל שיקול הדעת העסקי. במקרים כאלה, ובמיוחד בעסקאות עם בעלי עניין, הפסיקה מכירה בהחלת סטנדרט ביקורת מחמיר יותר, כגון כלל ההגינות המלאה, המטיל את הנטל על נושאי המשרה להוכיח את הגינות העסקה מכל היבטיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הכלל יגן על הדירקטורים, אך בית המשפט יבחן את ההחלטה ב"בחינה מוגברת" בלבד.', false, 'טענה זו שגויה. ניגוד עניינים מובהק וחוסר יידוע סותרים את הכלל, ומובילים לסטנדרט מחמיר יותר מ"בחינה מוגברת", כגון "הגינות מלאה".', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הדירקטורים יהיו חשופים לתביעה רק אם יוכח שהעסקה גרמה נזק ישיר לבעלי מניות המיעוט.', false, 'טענה זו שגויה. הפרת חובות נושאי משרה בשל ניגוד עניינים וחוסר יידוע עלולה להקים עילת תביעה לחברה עצמה, ללא קשר לנזק ישיר לבעלי מניות המיעוט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'כלל שיקול הדעת העסקי בתביעה נגזרת',
    4, 'בעל מניות בחברת "דלתא בע"מ" הגיש בקשה לאישור תביעה נגזרת נגד דירקטוריון החברה, בטענה שהדירקטוריון קיבל החלטה שלא להגיש תביעה נגד צד שלישי שגרם נזק לחברה. הדירקטוריון טוען להגנת כלל שיקול הדעת העסקי. מה הדין?', 'שאלה זו בוחנת את תחולתו של כלל שיקול הדעת העסקי בהקשר של תביעות נגזרות, ובפרט על החלטת דירקטוריון שלא להגיש תביעה בשם החברה. הפסיקה קבעה כי הכלל חל על החלטות אלו, אך עם סייג חשוב: הוא אינו חל כאשר התביעה היא נגד נושא משרה או בעל שליטה בחברה, בשל ניגוד עניינים מובנה.', 'הפסיקה בישראל, ובפרט בעניין מנשה (Reference 21, 22, 23, 24) ובעניין אורן דה לנגה (Reference 12), קבעה כי כלל שיקול הדעת העסקי חל גם על החלטות של האורגנים המוסמכים בחברה אם להפעיל את כוח התביעה אם לאו, וזאת בדומה לתחולתו על כל החלטה עסקית. החלטה להפעיל או שלא להפעיל את כוח התביעה של החברה היא החלטה עסקית, כאשר על הדירקטוריון להעריך האם התביעה וניהולה הן לטובת החברה, את עלות ניהול התביעה, השפעתה על המוניטין ועוד. עם זאת, בית המשפט הדגיש כי תחולת כלל שיקול הדעת העסקי שמורה למקרים בהם דירקטוריון החברה מחליט שלא להגיש תביעה נגד צד שלישי שאינו קשור לחברה. מנגד, הובהר כי אין להחיל את כלל שיקול הדעת העסקי כאשר מדובר בתביעה נגד נושא משרה או בעל השליטה בחברה, שכן במקרה כזה, החלטת הדירקטוריון שלא להפעיל את כוח התביעה תהיה "נגועה" מראש בניגוד עניינים (Reference 12).',
    'הטעות היא להכליל את תחולת כלל שיקול הדעת העסקי על כל החלטה שלא להגיש תביעה, מבלי להבחין בין תביעה נגד צד שלישי לתביעה נגד נושא משרה או בעל שליטה.', '["תביעה נגזרת", "כלל שיקול הדעת העסקי", "החלטה עסקית", "ניגוד עניינים", "בעיית נציג", "כוח תביעה של חברה", "חוק החברות סעיף 198"]'::jsonb, '**וריאציה 1 — תחולה על החלטה שלא לתבוע:** האם כלל שיקול הדעת העסקי חל על החלטה שלא להגיש תביעה? ← כן, זו החלטה עסקית ככל החלטה אחרת. ע"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע"מ (24.04.2018)
**וריאציה 2 — סייג לתחולה:** מתי הכלל לא יחול על החלטה שלא לתבוע? ← כאשר התביעה היא נגד נושא משרה או בעל שליטה בחברה, בשל ניגוד עניינים. תנ"ג (מחוזי תל אביב-יפו) 36670-01-22 אורן דה לנגה נ'' יעקב אטרקצ''י (08.04.2025)
**וריאציה 3 — תכלית החלה:** מהי תכלית החלת הכלל על החלטה שלא לתבוע? ← צמצום התערבות בתי המשפט ומניעת תביעות סרק. ע"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע"מ (24.04.2018)', 'BJR חל על החלטה שלא לתבוע ← למעט תביעה נגד נושא משרה/בעל שליטה ← אז יש ניגוד עניינים.',
    '["ע\"א 4857/16 אפרים מנשה נ'' יווז''ין אייר בע\"מ (24.04.2018)", "תנ\"ג (מחוזי תל אביב-יפו) 36670-01-22 אורן דה לנגה נ'' יעקב אטרקצ''י (08.04.2025)", "תנ\"ג (מחוזי תל אביב-יפו) 26054-10-21 דוד כהן נ'' דן חברה לתחבורה ציבורית בע\"מ (26.03.2023)", "חוק החברות, תשנ\"ט-1999, סעיף 198"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כלל שיקול הדעת העסקי אינו חל על החלטות דירקטוריון שלא להגיש תביעה, שכן זו אינה החלטה עסקית במהותה.', false, 'טענה זו שגויה. הפסיקה קבעה כי החלטה אם להפעיל את כוח התביעה של החברה היא החלטה עסקית ככל החלטה עסקית אחרת, ולכן כלל שיקול הדעת העסקי חל עליה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כלל שיקול הדעת העסקי חל על החלטת הדירקטוריון שלא להגיש תביעה נגד צד שלישי שאינו קשור לחברה, ובית המשפט ימעט להתערב בה, אלא אם כן התובע יוכיח שאחד מתנאי הכלל לא התקיים.', true, 'הפסיקה קבעה כי כלל שיקול הדעת העסקי חל גם על החלטות הדירקטוריון אם להפעיל או לא להפעיל את כוח התביעה של החברה, וזאת בדומה לתחולתו על כל החלטה עסקית אחרת. עם זאת, תחולת הכלל שמורה למקרים בהם התביעה היא נגד צד שלישי שאינו קשור לחברה, שאז אין סיבה להניח מראש שההחלטה נגועה בכשל או בבעיית נציג.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כלל שיקול הדעת העסקי חל על החלטת הדירקטוריון, אך הנטל להוכיח את סבירות ההחלטה מוטל על הדירקטוריון.', false, 'טענה זו שגויה. הנטל הראשוני לסתור את חזקת התקינות מוטל על התובע, ולא על הדירקטוריון, כאשר הכלל חל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כלל שיקול הדעת העסקי אינו חל במקרה זה, שכן תביעה נגזרת תמיד מעידה על ניגוד עניינים מובנה.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי אינו חל כאשר התביעה היא נגד נושא משרה או בעל שליטה בחברה, אך הוא חל כאשר התביעה היא נגד צד שלישי שאינו קשור לחברה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 3, '2019-S-S-Q03';
END
$$;

-- ============================================================
-- Q04 — 2019-S-S-Q04 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Section 284 (breach of trust by public servant); accessory to special-offender offense
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'f8c210f2-946f-4eb2-86b1-da7156e4210e'::uuid;
  v_group_id uuid := '958ad64b-0813-4623-97df-51c8d71f81fb'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f97424f1-8382-430f-b6cd-09df867f940e'::uuid;
  v_ang_1 uuid := '9cea3247-e58c-4633-9165-d1723c017585'::uuid;
  v_ang_2 uuid := 'aeecce9b-6034-44f6-849b-3bf37c03e12c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q04';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 4, '2019-S-S-Q04';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q04', v_chapter_id, v_subtopic_id, 'סעיף 284 לחוק העונשין, התשל"ז-1977, שכותרתו "מרמה והפרת אמונים", קובע: "עובד הציבור העושה במילוי תפקידו מעשה מרמה או הפרת אמונים הפוגע בציבור, אף אם לא היה במעשה משום עבירה אילו נעשה כנגד יחיד, דינו - מאסר שלוש שנים". עודד, שהוא עובד ציבור, ביצע יחד עם מנשה (שאינו עובד ציבור) מעשה מרמה הפוגע בציבור. האם ניתן להרשיע את מנשה בעבירה של מרמה והפרת אמונים?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 4}'::jsonb, 'השאלה עוסקת באחריות פלילית של אדם שאינו עובד ציבור, המבצע בצוותא עבירה של מרמה והפרת אמונים עם עובד ציבור. היא מתמקדת בפרשנות סעיף 34ב לחוק העונשין, המבחין בין "נתונים ענייניים" ל"נתונים אישיים", וקובעת כי הנתון של "עובד ציבור" הוא "נתון ענייני" החל על כל צד לעבירה, ובכך מאפשר להרשיע גם את מי שאינו עובד ציבור בעבירה זו.', 'סעיף 284 לחוק העונשין, תשל"ז-1977, מגדיר את עבירת מרמה והפרת אמונים כעבירה של "עובד ציבור" (Reference 1, 8, 9, 11, 12, 15). עבירה זו משתייכת לקבוצת העבירות המכונות "עבירות בעושה מיוחד", המאופיינות ברכיב נסיבתי של עושה ספציפי (Reference 1). עם זאת, סעיף 34ב לחוק העונשין קובע כי "נתון שהוא תנאי להתהוות עבירה, תהיה לו נפקות לגבי כל צד לאותה עבירה, אף אם אינו מתקיים בו" (Reference 1, 3, 4, 5, 6, 10, 2258-104, 4484-6). הפסיקה קבעה באופן עקבי כי הנתון של "עובד ציבור" בעבירת מרמה והפרת אמונים הוא "נתון ענייני" ולא "נתון אישי" (Reference 5, 6, 10). משמעות הדבר היא שנתון זה, המהווה תנאי להתהוות העבירה, חל על כל צד לעבירה, גם אם אינו עובד ציבור בעצמו, ובלבד שהיה מודע למבנה האובייקטיבי של העבירה (Reference 2, 10). לכן, במקרה הנדון, ניתן להרשיע את מנשה כמבצע בצוותא של עבירת מרמה והפרת אמונים, בהיותו צד לעבירה ששותפו (עודד) הוא עובד ציבור (Reference 5, 6, 13).', 'הטעות הנפוצה היא לחשוב שאדם שאינו עובד ציבור אינו יכול להיות מורשע בעבירה של מרמה והפרת אמונים, בשל הדרישה ל"עובד ציבור" ביסודות העבירה, מבלי להבין את תחולת סעיף 34ב לחוק העונשין.',
    '["מרמה והפרת אמונים", "עבירת עושה מיוחד", "סעיף 34ב לחוק העונשין", "נתון ענייני", "נתון אישי", "מבצע בצוותא", "אחריות פלילית", "עובד ציבור"]'::jsonb, '**וריאציה 1 — עבירת עושה מיוחד:** האם עבירת מרמה והפרת אמונים היא עבירת עושה מיוחד? ← כן, היא דורשת שהעושה יהיה "עובד ציבור". ת"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)
**וריאציה 2 — תחולת 34ב:** האם ניתן להרשיע שותף שאינו עובד ציבור? ← כן, מכוח סעיף 34ב לחוק העונשין. בש"פ 5984/18 פלוני נ'' מדינת ישראל (14.08.2018)
**וריאציה 3 — סיווג הנתון:** האם "עובד ציבור" הוא נתון ענייני או אישי? ← נתון ענייני. בש"פ 5984/18 פלוני נ'' מדינת ישראל (14.08.2018)', 'עבירת מרמה והפרת אמונים ← דורשת "עובד ציבור" (נתון ענייני) ← שותף שאינו עובד ציבור ← ניתן להרשיע כמבצע בצוותא מכוח סעיף 34ב לחוק העונשין.', '["חוק העונשין, תשל\"ז-1977, סעיפים 34ב, 284", "בש\"פ 5984/18 פלוני נ'' מדינת ישראל (14.08.2018)", "ת\"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)", "ע\"פ 2247/10 ימיני נ'' מדינת ישראל, פ\"ד סד(2) 666 (2011)", "ת\"פ (מחוזי ת\"א) 12935-02-17 מדינת ישראל נ'' איתמר שמעוני (11.11.2019)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Section 284 (breach of trust by public servant); accessory to special-offender offense | source_review_note: השאלה עוסקת בעקרונות כלליים של דיני עונשין (צדדים לעבירה, עבירות עושה מיוחד), ולא ספציפית ב"משמעת עורכי דין" או ב"סדר דין פלילי" (פרוצדורה). יש לשקול הוספת קטגוריה רחבה יותר של "דיני עונשין" או "החלק הכללי של דיני עונשין" עם תת-נושאים מתאימים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא, משום שמנשה אינו עובד ציבור.', false, 'טענה זו שגויה. אף שמנשה אינו עובד ציבור, ניתן להרשיעו בעבירה של מרמה והפרת אמונים כמבצע בצוותא, מכוח סעיף 34ב לחוק העונשין, שכן היותו של עודד עובד ציבור הוא "נתון ענייני".', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כן, משום שהנתון של "עובד ציבור" הוא תנאי להתהוות העבירה.', true, 'הנתון של "עובד ציבור" בעבירת מרמה והפרת אמונים הוא "נתון ענייני" (תנאי להתהוות העבירה). סעיף 34ב לחוק העונשין קובע כי נתון ענייני כזה יחול על כל צד לעבירה, אף אם אינו מתקיים בו. לכן, ניתן להרשיע את מנשה כמבצע בצוותא של העבירה, בהיותו צד לעבירה ששותפו (עודד) הוא עובד ציבור.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לא, משום שהנתון של "עובד ציבור" הוא נתון אישי.', false, 'טענה זו שגויה. הפסיקה קבעה באופן מפורש כי הנתון של "עובד ציבור" הוא "נתון ענייני" ולא "נתון אישי", ולכן הוא חל על כל צד לעבירה מכוח סעיף 34ב לחוק העונשין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כן, משום שעודד הוא מבצע באמצעות אחר.', false, 'טענה זו שגויה. המקרה מתאר ביצוע בצוותא, שבו שני הצדדים מבצעים את העבירה יחד. "מבצע באמצעות אחר" הוא מצב שבו אדם אחד מבצע את העבירה דרך אדם אחר שאינו בעל אחריות פלילית מלאה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תחולת סעיף 34ב על עבירות מחדל של עושה מיוחד',
    1, 'נהג אוטובוס (עובד ציבור) דרס הולך רגל ונמלט מהמקום, מבלי להגיש עזרה. נוסע שהיה עמו באוטובוס (שאינו עובד ציבור) ידע על הדריסה ועל מחדל הנהג, אך לא עשה דבר. האם ניתן להרשיע את הנוסע כמבצע בצוותא בעבירת הפקרה לאחר פגיעה (עבירת מחדל של עושה מיוחד)?', 'שאלה זו בוחנת את גבולות תחולתו של סעיף 34ב לחוק העונשין, העוסק בנתונים ענייניים ואישיים, על עבירות מחדל מסוג "עושה מיוחד". הפסיקה קבעה כי במקרים אלו, לא ניתן להטיל אחריות פלילית על מבצע בצוותא שאינו בעל הנתון המיוחד, אם אין לו חובת עשייה עצמאית לפעול.', 'סעיף 34ב לחוק העונשין קובע כי נתון שהוא תנאי להתהוות עבירה, תהיה לו נפקות לגבי כל צד לאותה עבירה, אף אם אינו מתקיים בו. אולם, הפסיקה, ובפרט בעניין ימיני (ע"פ 2247/10 ימיני נ'' מדינת ישראל), צמצמה את תחולת סעיף זה על עבירות מחדל מסוג "עושה מיוחד". נקבע כי לא ניתן להחיל את הוראת סעיף 34ב על מבצע בצוותא, כאשר העבירה של "עושה מיוחד" היא עבירה של מחדל, ובהיעדר מקור חובה עצמאי לפעול המוטל על המבצע בצוותא. במקרה הנדון, עבירת ההפקרה לאחר פגיעה (סעיף 64א לפקודת התעבורה) היא עבירת מחדל, ו"נהג רכב" הוא ה"עושה המיוחד" שעליו מוטלת חובת העשייה. הנוסע אינו "נהג רכב" ואין לו חובת עשייה עצמאית להגיש עזרה. לכן, לא ניתן להרשיעו כמבצע בצוותא בעבירה זו מכוח סעיף 34ב.',
    'הטעות היא להניח שסעיף 34ב חל באופן גורף על כל עבירות ה"עושה המיוחד", מבלי להבחין בין עבירות מעשה לעבירות מחדל, ומבלי לבחון את קיומה של חובת עשייה עצמאית.', '["סעיף 34ב לחוק העונשין", "עבירת עושה מיוחד", "עבירת מחדל", "חובת עשייה", "מבצע בצוותא", "הפקרה לאחר פגיעה", "עניין ימיני"]'::jsonb, '**וריאציה 1 — עבירת מחדל ו-34ב:** האם סעיף 34ב חל על עבירת מחדל של עושה מיוחד? ← לא, אם למבצע בצוותא אין חובת עשייה עצמאית. ת"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)
**וריאציה 2 — עניין ימיני:** מה קבע בית המשפט העליון בעניין ימיני? ← סעיף 34ב לא יחול על נוסע ברכב בעבירת הפקרה לאחר פגיעה, בהיעדר חובת עשייה עצמאית. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה
**וריאציה 3 — רציונל:** מהו הרציונל מאחורי צמצום זה? ← ללא מקור חובת עשייה, לא משתכללת עבירת המחדל לגבי השותף. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה', 'עבירת מחדל של עושה מיוחד ← סעיף 34ב לא חל על שותף ← אם אין לו חובת עשייה עצמאית.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34ב", "ע\"פ 2247/10 ימיני נ'' מדינת ישראל, פ\"ד סד(2) 666 (2011)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה", "ת\"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכוח סעיף 34ב לחוק העונשין, שכן הנתון של "נהג רכב" הוא נתון ענייני.', false, 'טענה זו שגויה. אף שהנתון של "נהג רכב" הוא נתון ענייני, הפסיקה קבעה כי סעיף 34ב לא יחול על עבירת מחדל של עושה מיוחד כאשר למבצע בצוותא אין חובת עשייה עצמאית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, משום שסעיף 34ב לחוק העונשין לא יחול על עבירת מחדל של עושה מיוחד, כאשר למבצע בצוותא (הנוסע) אין חובת עשייה עצמאית לפעול.', true, 'הפסיקה קבעה כי לא ניתן להחיל את הוראת סעיף 34ב על מבצע בצוותא בעבירת מחדל של עושה מיוחד, בהיעדר מקור חובה עצמאי לפעול המוטל על המבצע בצוותא. במקרה זה, הנוסע אינו "נהג רכב" ואין לו חובת עשייה עצמאית להגיש עזרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם הנוסע היה מודע לכך שהנהג הוא עובד ציבור.', false, 'טענה זו שגויה. מודעות למעמדו של הנהג אינה מספיקה כדי להטיל אחריות על הנוסע בעבירת מחדל של עושה מיוחד, בהיעדר חובת עשייה עצמאית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, משום שעבירת הפקרה לאחר פגיעה היא עבירה תוצאתית, ואין קשר סיבתי בין מחדל הנוסע לתוצאה.', false, 'טענה זו שגויה. עבירת הפקרה לאחר פגיעה היא עבירת מחדל, אך הבעיה העיקרית בהטלת אחריות על הנוסע אינה קשורה לקשר סיבתי, אלא להיעדר חובת עשייה עצמאית עליו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין נתון ענייני לנתון אישי בסעיף 34ב',
    2, 'מהי ההבחנה המהותית בין "נתון ענייני" ל"נתון אישי" לעניין סעיף 34ב לחוק העונשין?', 'שאלה זו מבהירה את ההבחנה הקריטית בין "נתון ענייני" ל"נתון אישי" בסעיף 34ב לחוק העונשין. הבנה זו חיונית לקביעת אחריות פלילית של שותפים לעבירה, במיוחד בעבירות הדורשות "עושה מיוחד", שכן היא קובעת אילו תנאים יחולו על כלל הצדדים לעבירה ואילו רק על הצד שבו הם מתקיימים.', 'סעיף 34ב לחוק העונשין מבחין בין "נתון ענייני" ל"נתון אישי". "נתון ענייני" הוא רכיב בהגדרת העבירה הקשור במעשה עצמו, אשר מבטא "מעמד" המייחד את עושה העבירה, ומהווה תנאי להשתכללותה. נפקותו של נתון ענייני חלה על כל צד לאותה עבירה, אף אם אינו מתקיים בו (עניין ימיני, פסקה 32; Reference 1, 2, 6). דוגמה לכך היא היותו של אדם "עובד ציבור" בעבירת מרמה והפרת אמונים. לעומת זאת, "נתון אישי" הוא נתון הקשור בעושה, שאין התהוות העבירה מותנית בו, אך יש בו כדי להצמיח, מכוח החוק, תוצאות בנוגע למידת הטיפול העונשי באותו צד בגין העבירה, לדרך הטיפול בו בגינה, או אף לאפשרות לנקוט טיפול עונשי כלשהו כלפיו (יורם רבין, יניב ואקי, דיני עונשין - כרך א, עמ'' 104; Reference 2258-104). דוגמאות לנתונים אישיים כוללות גיל קטינות, מועדות או חסינות (Reference 2258-106).',
    'הטעות היא לבלבל בין שני סוגי הנתונים, או לייחס לנתון אישי השפעה על עצם התהוות העבירה במקום על העונש או הטיפול העונשי.', '["נתון ענייני", "נתון אישי", "סעיף 34ב לחוק העונשין", "עבירת עושה מיוחד", "אחריות פלילית", "מבצע בצוותא", "השתכללות עבירה"]'::jsonb, '**וריאציה 1 — נתון ענייני:** מהו נתון ענייני? ← רכיב בהגדרת העבירה הקשור במעשה עצמו ומהווה תנאי להתהוותה, חל על כל צד. ת"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)
**וריאציה 2 — נתון אישי:** מהו נתון אישי? ← נתון הקשור בעושה, שאין התהוות העבירה מותנית בו, אך משפיע על העונש של אותו צד בלבד. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה
**וריאציה 3 — דוגמאות:** דוגמאות לנתונים אישיים? ← מועדות, גיל קטינות, חסינות. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה', 'נתון ענייני ← תנאי לעבירה, חל על כולם. נתון אישי ← קשור לעושה, משפיע על עונש, חל רק עליו.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34ב", "ת\"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (20.11.2016)", "בש\"פ 5984/18 פלוני נ'' מדינת ישראל (14.08.2018)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'נתון ענייני הוא רכיב בהגדרת העבירה הקשור במעשה עצמו ומהווה תנאי להתהוותה, ונפקותו חלה על כל צד לעבירה. נתון אישי הוא נתון הקשור בעושה, שאין התהוות העבירה מותנית בו, אך יש בו כדי להשפיע על העונש של אותו צד בלבד.', true, 'זוהי ההבחנה המדויקת בין נתון ענייני לנתון אישי כפי שנקבעה בפסיקה ובספרות המשפטית, ומשמעותה לעניין תחולת סעיף 34ב לחוק העונשין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'נתון ענייני קשור למניע של העושה, ואילו נתון אישי קשור לתוצאת העבירה.', false, 'טענה זו שגויה. ההבחנה בין נתון ענייני לאישי אינה קשורה למניע או לתוצאה, אלא למעמד העושה או לתנאי להתהוות העבירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'נתון ענייני חל רק על עבירות שוחד, ואילו נתון אישי חל על כל העבירות.', false, 'טענה זו שגויה. ההבחנה בין נתון ענייני לאישי היא כללית ואינה מוגבלת לעבירות שוחד בלבד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'נתון ענייני משפיע על חומרת העונש, ואילו נתון אישי קובע אם העבירה התרחשה בכלל.', false, 'טענה זו שגויה. נתון ענייני הוא תנאי להתהוות העבירה, ואילו נתון אישי משפיע על העונש, כלומר הסדר הפוך ממה שנטען.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סיווג נתון כענייני או אישי בעבירת המתת תינוק',
    3, 'שרה, השרויה בדיכאון לאחר לידה, הורגת את ולדה בתנאים הקבועים בסעיף 303 לחוק העונשין (המתת תינוק). אברהם, שאינו האב, מבצע עימה בצוותא את המעשה. האם אברהם יואשם בהמתת תינוק (סעיף 303) או ברצח/הריגה?', 'שאלה זו עוסקת במחלוקת אקדמית ופרשנית לגבי סיווג נתונים מסוימים כ"ענייניים" או "אישיים" בעבירות "עושה מיוחד", תוך התמקדות בעבירת המתת תינוק. היא מדגישה את הקושי ביישום סעיף 34ב לחוק העונשין במקרים גבוליים ואת ההשלכות המשפטיות השונות של כל סיווג.', 'הקושי ביישום סעיף 34ב לחוק העונשין נובע לעיתים מאי-בהירות בסיווג נתונים כ"אישיים" או "ענייניים". דוגמה לכך היא עבירת המתת תינוק (סעיף 303 לחוק העונשין), המייחדת את העבירה לאם התינוק בתנאים מסוימים. פלר, שהניח את התשתית העיונית לסעיף 34ב, סבר כי הנתונים המיוחדים המתקיימים בשרה (היותה אישה, אם, והיותה במצב של ערעור שיקול הדעת לאחר לידה) מהווים "נתונים ענייניים". לכן, אם אברהם מבצע עימה בצוותא את המעשה, הוא יואשם אף הוא בהמתת תינוק, שכן הנתון הענייני של האם חל גם עליו מכוח סעיף 34ב. סיווג זה משמעותו שהעבירה כולה משתנה מרצח/הריגה לעבירה קלה יותר של המתת תינוק, החלה על כלל המבצעים בצוותא, וזאת בשל אופי הנתון כחלק אינטגרלי מהגדרת העבירה ולא רק כנתון המשפיע על העונש.',
    'הטעות היא לראות בנתונים המיוחדים של האם בעבירת המתת תינוק כ"נתונים אישיים" המשפיעים רק על עונשה, ובכך להחמיר את דינו של השותף לעבירה.', '["סעיף 34ב לחוק העונשין", "נתון ענייני", "נתון אישי", "המתת תינוק", "עבירת עושה מיוחד", "מבצע בצוותא", "סיווג נתונים", "פלר"]'::jsonb, '**וריאציה 1 — גישת פלר:** לפי פלר, מהו סיווג הנתונים בעבירת המתת תינוק? ← נתונים ענייניים. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה
**וריאציה 2 — השלכה על השותף:** מהי ההשלכה של סיווג זה על השותף? ← יואשם בהמתת תינוק ולא ברצח/הריגה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה
**וריאציה 3 — רציונל:** מדוע נתונים אלו נחשבים ענייניים? ← הם משתלבים בנתונים נוספים ומהווים תנאי להגדרת העבירה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה', 'המתת תינוק ← נתונים ענייניים (לפי פלר) ← שותף יואשם בהמתת תינוק.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 303", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'אברהם יואשם בהמתת תינוק, שכן הנתונים המיוחדים המתקיימים בשרה (אישה, אם, דיכאון לאחר לידה) מהווים "נתונים ענייניים" החלים על כל צד לעבירה.', true, 'לפי גישת פלר, הנתונים המיוחדים בעבירת המתת תינוק הם "נתונים ענייניים" המשתלבים במבנה העבירה. לכן, הם חלים על כל צד לעבירה, ואברהם יואשם בהמתת תינוק ולא ברצח/הריגה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'אברהם יואשם ברצח או הריגה, שכן הנתונים המתקיימים בשרה הם "נתונים אישיים" החלים עליה בלבד.', false, 'טענה זו שגויה. לפי הגישה המקובלת, הנתונים בעבירת המתת תינוק הם ענייניים, שכן הם תנאי להתהוות העבירה הספציפית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'אברהם יואשם בהמתת תינוק רק אם יוכח שהיה מודע למצבה הנפשי של שרה.', false, 'טענה זו שגויה. מודעות למצב הנפשי של שרה אינה משנה את סיווג הנתון כענייני, אלא רלוונטית ליסוד הנפשי של אברהם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'אברהם יואשם בהמתת תינוק רק אם הוא אבי התינוק.', false, 'טענה זו שגויה. סעיף 303 לחוק העונשין מתייחס לאם התינוק, ולא לאב. מעמדו של אברהם כשותף נבחן לפי סעיף 34ב.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 4, '2019-S-S-Q04';
END
$$;

-- ============================================================
-- Q05 — 2019-S-S-Q05 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Extraterritorial application of penal law — solicitation abroad targeting Israel
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '56176a59-0dd7-48eb-afd2-68db2f930c68'::uuid;
  v_group_id uuid := 'b32c0102-cf78-47d8-8c04-5cb79be66e33'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ee3d9baf-126b-4d18-a888-965a9cf29cfe'::uuid;
  v_ang_1 uuid := 'ee4128f1-d789-46b8-8839-a936795c6cbb'::uuid;
  v_ang_2 uuid := '1ecb7bdc-6924-4f00-80f5-e1a0624af899'::uuid;
  v_ang_3 uuid := '39d57a21-8e66-4fbe-9c23-200f24d6e9f4'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q05';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 5, '2019-S-S-Q05';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q05', v_chapter_id, v_subtopic_id, 'במהלך פגישה עסקית שקיימו פינג, אזרח יפני, ואריקה, אזרחית שוודיה, בבית הקפה BDS בבלגיה ניסתה האחרונה לשדל את פינג לפרוץ לכספות בנק ישראל בירושלים ובכך לפגוע ברכוש של מדינת ישראל ולשבש את הפעילות התקינה של רשויות המדינה. פינג סירב והפריצה לא בוצעה. הנח כי השיחה בין השניים תועדה וכי יש אפשרות להביא את אריקה בפני שופט בישראל. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 5}'::jsonb, 'השאלה עוסקת בתחולה הטריטוריאלית של דיני העונשין של ישראל, ובפרט בהגדרת ''עבירת פנים'' לפי חוק העונשין. היא בוחנת מצב שבו ניסיון לשידול לעבירה בוצע מחוץ לישראל, אך העבירה עצמה הייתה אמורה להתבצע בתוך שטח ישראל, וכיצד הדבר משפיע על סמכות השיפוט של בתי המשפט בישראל.', 'סעיף 12 לחוק העונשין קובע כי דיני העונשין של ישראל יחולו על כל ''עבירת פנים''. סעיף 7(א)(2) לחוק העונשין מגדיר ''עבירת פנים'' באופן רחב, וכולל בתוכה ''מעשה הכנה לעבור עבירה, נסיון, נסיון לשדל אחר, או קשירת קשר לעבור עבירה, שנעשו מחוץ לשטח ישראל, ובלבד שהעבירה, כולה או מקצתה, היתה אמורה להיעשות בתוך שטח ישראל''. במקרה הנדון, אריקה ניסתה לשדל את פינג בבלגיה לפרוץ לכספות בנק ישראל בירושלים. מעשה זה, אף שבוצע מחוץ לישראל, נכנס לגדר סעיף 7(א)(2) מכיוון שהעבירה (פריצה לכספות) הייתה אמורה להיעשות בישראל. לכן, מדובר ב''עבירת פנים'', ודיני העונשין של ישראל חלים עליה ללא צורך בתנאים מיוחדים החלים על ''עבירות חוץ'', כגון הסכמת היועץ המשפטי לממשלה או דרישת פליליות כפולה. אזרחותם הזרה של המעורבים אינה רלוונטית במקרה זה.', 'הטעות הנפוצה היא לסווג את המעשה כ''עבירת חוץ'' בשל מקום ביצוע השידול, תוך התעלמות מהרחבת הגדרת ''עבירת פנים'' בסעיף 7(א)(2) לחוק העונשין, המתייחסת למעשים שנעשו מחוץ לישראל אך כוונו לביצוע עבירה בישראל.',
    '["עבירת פנים", "עבירת חוץ", "תחולה טריטוריאלית", "ניסיון לשידול", "חוק העונשין סעיף 7", "חוק העונשין סעיף 12"]'::jsonb, '**וריאציה 1 — שידול בחו"ל לעבירה בחו"ל:** אזרח ישראלי משדל אזרח ישראלי אחר בחו"ל לבצע עבירה בחו"ל. האם זו עבירת פנים? ← לא, זו ''עבירת חוץ'' שחלה עליה תחולה פרסונלית (סעיף 15 לחוק העונשין), ודורשת הסכמת היועמ"ש (סעיף 9(ב)).
**וריאציה 2 — קשירת קשר בחו"ל לעבירה בישראל:** קבוצת עבריינים קושרת קשר בחו"ל לבצע עבירה בישראל. האם זו עבירת פנים? ← כן, קשירת קשר שנעשתה מחוץ לישראל, ובלבד שהעבירה הייתה אמורה להיעשות בישראל, נחשבת לעבירת פנים לפי סעיף 7(א)(2) לחוק העונשין (עה"ס 1204-12-24 מיכאל פאן נ'' מדינת ישראל).

**וריאציה 3 — מעשה הכנה בחו"ל לעבירה בישראל:** אדם מבצע מעשה הכנה לעבירה בחו"ל, אך העבירה לא הושלמה בישראל. האם עדיין ניתן להעמיד לדין בישראל? ← כן, סעיף 7(א)(2) חל גם אם העבירה לא הושלמה, כל עוד היא ''הייתה אמורה להיעשות בתוך שטח ישראל'' (ע"פ 4596/05 רוזנשטיין נ'' מדינת ישראל).', 'ניסיון לשידול שנעשה מחוץ לישראל, אך העבירה הייתה אמורה להיעשות בישראל ← נחשב ל''עבירת פנים'' לפי סעיף 7(א)(2) לחוק העונשין, ודיני העונשין של ישראל חלים.', '["חוק העונשין, תשל\"ז-1977, סעיף 7", "חוק העונשין, תשל\"ז-1977, סעיף 12", "דנ\"פ 2980/04 חוזה אויקו נ'' מדינת ישראל, ס(4) 34 (29.12.2005)", "ע\"פ 4596/05 זאב רוזנשטיין נ'' מדינת ישראל, ס(3) 353 (30.11.2005)", "בש\"פ 9022/96 חאתם בן רידא שית נ'' מדינת ישראל, נ(5) 597 (12.01.1997)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014) | פרק 7 - תחולת דיני העונשין לפי מקום עשיית העבירה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Extraterritorial application of penal law — solicitation abroad targeting Israel | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''ערעור פלילי'' הוא פשרה, שכן הנושא הוא תחולה טריטוריאלית של דיני העונשין, שהוא נושא מהותי בדיני עונשין ולא פרוצדורלי במובן הצר. יש לשקול הוספת תת-נושא ''תחולה טריטוריאלית'' או ''סמכות שיפוט פלילית'' לרשימת תתי-הנושאים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן להטיל אחריות פלילית על אריקה בגין המעשה, שכן מדובר בניסיון לשידול לביצוע עבירה שבסופו של דבר לא התבצעה, שנעשה על ידי אזרחית זרה כלפי אזרח זר אחר, ללא כל זיקה וקשר לישראל.', false, 'טענה זו שגויה, שכן סעיף 7(א)(2) לחוק העונשין קובע במפורש כי ניסיון לשידול שנעשה מחוץ לישראל, אך העבירה הייתה אמורה להיעשות בישראל, נחשב ל''עבירת פנים'', ולכן קיימת זיקה לישראל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מכיוון שמדובר בעבירת חוץ, ניתן להטיל אחריות פלילית על אריקה מכוח התחולה על עבירות חוץ שנעשו נגד המדינה או העם היהודי, ואולם לא תהיה העמדה לדין אלא בידי היועץ המשפטי לממשלה או בהסכמתו בכתב, אם ראה כי יש בכך עניין לציבור.', false, 'טענה זו שגויה, שכן המעשה מתאים להגדרת ''עבירת פנים'' לפי סעיף 7(א)(2) לחוק העונשין, ולא ''עבירת חוץ''. לכן, אין צורך בהסכמת היועץ המשפטי לממשלה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מדובר בעבירת פנים, ואין כל מניעה להטיל אחריות פלילית על אריקה בשל העבירה אם יוכחו יסודותיה.', true, 'תשובה זו נכונה. ניסיון לשידול שנעשה מחוץ לישראל, אך העבירה הייתה אמורה להיעשות בישראל, נחשב ל''עבירת פנים'' לפי סעיף 7(א)(2) לחוק העונשין, ולכן דיני העונשין של ישראל חלים עליה ללא תנאים מיוחדים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מכיוון שמדובר בעבירת חוץ ניתן להטיל אחריות פלילית על אריקה מכוח התחולה על עבירות חוץ שנעשו נגד המדינה או העם היהודי, ואולם על השופט לוודא כי מדובר בעבירה גם לפי אותה מדינה וכי אריקה לא נשפטה כבר בגינה וזוכתה ממנה, ואם הורשעה – לא נשאה את עונשה.', false, 'טענה זו שגויה, שכן המעשה מסווג כ''עבירת פנים'' ולא כ''עבירת חוץ''. התנאים של פליליות כפולה ומעשה בית דין זר רלוונטיים רק לעבירות חוץ מסוימות, ולא לעבירת פנים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עבירת פנים: מעשה הכנה מחוץ לישראל',
    1, 'ראובן, אזרח ישראלי, תכנן בגרמניה לפוצץ בניין ממשלתי בישראל. הוא רכש את חומרי הנפץ בגרמניה ושלח אותם באמצעות בלדר לישראל, אך הבלדר נתפס בגבול. ראובן עצמו לא נכנס לישראל. האם ניתן להעמיד את ראובן לדין בישראל בגין מעשה הכנה לעבירה?', 'שאלה זו בוחנת את הבנת המושג ''עבירת פנים'' בהקשר של מעשי הכנה שבוצעו מחוץ לישראל, אך כוונו לפגוע בישראל. היא מתמקדת בסעיף 7(א)(2) לחוק העונשין, המרחיב את התחולה הטריטוריאלית של הדין הפלילי הישראלי.', 'סעיף 7(א)(2) לחוק העונשין קובע כי ''עבירת פנים'' כוללת מעשה הכנה לעבור עבירה, ניסיון, ניסיון לשדל אחר, או קשירת קשר לעבור עבירה, שנעשו מחוץ לשטח ישראל, ובלבד שהעבירה, כולה או מקצתה, הייתה אמורה להיעשות בתוך שטח ישראל. במקרה זה, ראובן ביצע מעשי הכנה (רכישת חומרי נפץ ושליחתם) מחוץ לישראל, אך מטרת העבירה (פיצוץ בניין ממשלתי) הייתה בישראל. לכן, למרות שראובן לא היה פיזית בישראל, מעשיו נחשבים ל''עבירת פנים'' ודיני העונשין של ישראל חלים עליו מכוח סעיף 12 לחוק העונשין. אין צורך בזיקה פרסונלית או בהסכמת היועץ המשפטי לממשלה במקרה זה.',
    'הטעות הנפוצה היא לחשוב שרק מעשים שבוצעו פיזית בתוך שטח ישראל יכולים להיחשב כ''עבירת פנים'', תוך התעלמות מהרחבת ההגדרה בסעיף 7(א)(2) לחוק העונשין.', '["עבירת פנים", "תחולה טריטוריאלית", "מעשה הכנה", "חוק העונשין סעיף 7(א)(2)", "סמכות שיפוט פלילית"]'::jsonb, '**וריאציה 1 — ניסיון לשידול מחו"ל:** אזרח זר משדל אזרח זר אחר בחו"ל לבצע עבירה בישראל. האם זו עבירת פנים? ← כן, לפי סעיף 7(א)(2) לחוק העונשין, אם העבירה הייתה אמורה להיעשות בישראל.
**וריאציה 2 — קשירת קשר מחו"ל:** קבוצת עבריינים קושרת קשר בחו"ל לבצע שוד בנק בישראל. האם זו עבירת פנים? ← כן, קשירת קשר שנעשתה מחוץ לישראל, ובלבד שהעבירה הייתה אמורה להיעשות בישראל, נחשבת לעבירת פנים לפי סעיף 7(א)(2) לחוק העונשין.
**וריאציה 3 — מעשה הכנה ללא השלמה:** אדם מבצע מעשה הכנה לעבירה בחו"ל, אך העבירה לא הושלמה בישראל. האם עדיין ניתן להעמיד לדין בישראל? ← כן, סעיף 7(א)(2) חל גם אם העבירה לא הושלמה, כל עוד היא ''הייתה אמורה להיעשות בתוך שטח ישראל''.', 'מעשה הכנה, ניסיון, ניסיון לשידול או קשירת קשר שנעשו מחוץ לישראל, אך העבירה הייתה אמורה להיעשות בישראל ← נחשבים ל''עבירת פנים'' ודיני העונשין של ישראל חלים.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 7(א)(2)", "חוק העונשין, תשל\"ז-1977, סעיף 12", "דנ\"פ 2980/04 חוזה אויקו נ'' מדינת ישראל, ס(4) 34 (29.12.2005)", "ע\"פ 4596/05 זאב רוזנשטיין נ'' מדינת ישראל, ס(3) 353 (30.11.2005)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014) | פרק 7 - תחולת דיני העונשין לפי מקום עשיית העבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, מכיוון שכל מעשי ההכנה בוצעו מחוץ לישראל, וראובן עצמו לא היה בישראל, אין לבית המשפט בישראל סמכות לדון בעניין.', false, 'טענה זו שגויה, שכן סעיף 7(א)(2) לחוק העונשין מרחיב את הגדרת ''עבירת פנים'' גם למעשי הכנה שנעשו מחוץ לישראל, אם העבירה הייתה אמורה להיעשות בישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, מכיוון שמעשה הכנה לעבור עבירה שנעשה מחוץ לישראל, ובלבד שהעבירה הייתה אמורה להיעשות בתוך שטח ישראל, נחשב ל''עבירת פנים''.', true, 'תשובה זו נכונה. סעיף 7(א)(2) לחוק העונשין קובע כי מעשה הכנה לעבירה שנעשה מחוץ לישראל, אך העבירה הייתה אמורה להיעשות בישראל, נחשב ל''עבירת פנים'', ולכן דיני העונשין של ישראל חלים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם היועץ המשפטי לממשלה יאשר את הגשת כתב האישום, שכן מדובר בעבירת חוץ נגד המדינה.', false, 'טענה זו שגויה, שכן המעשה מסווג כ''עבירת פנים'' לפי סעיף 7(א)(2) לחוק העונשין, ולא כ''עבירת חוץ''. לכן, אין צורך בהסכמת היועץ המשפטי לממשלה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן יוכח שראובן היה אזרח ישראלי בעת ביצוע מעשי ההכנה, שכן אחרת אין זיקה פרסונלית לישראל.', false, 'טענה זו שגויה. סעיף 7(א)(2) לחוק העונשין אינו דורש זיקה פרסונלית (אזרחות או תושבות ישראלית) אלא זיקה טריטוריאלית רחבה, המתבטאת בכוונה לבצע את העבירה בישראל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן ''מקצת העבירה'' ורכיבי היסוד העובדתי',
    2, 'מהו המבחן המרכזי לקביעה האם ''מקצתה'' של עבירה נעשה בתוך שטח ישראל, לצורך סיווגה כ''עבירת פנים''?', 'שאלה זו עוסקת במבחן המשפטי לקביעת ''מקצת העבירה'' בתוך שטח ישראל, שהוא קריטי לסיווג עבירה כ''עבירת פנים'' לפי סעיף 7(א)(1) לחוק העונשין. היא בוחנת את ההבנה של רכיבי היסוד העובדתי (התנהגותי, נסיבתי, תוצאתי) בהקשר זה.', 'הפסיקה והספרות המשפטית קובעות כי המונח ''מקצתה'' בסעיף 7(א)(1) לחוק העונשין מתייחס לחלק מהיסוד העובדתי של העבירה. היסוד העובדתי מורכב מרכיב התנהגותי, רכיב נסיבתי ורכיב תוצאתי. די בכך שאחד מרכיבים אלו התרחש בישראל כדי שהעבירה כולה תיחשב כ''עבירת פנים''. לדוגמה, אם הרכיב ההתנהגותי בוצע בחו"ל אך התוצאה התרחשה בישראל, או אם רכיב נסיבתי התקיים בישראל, העבירה תיחשב כ''עבירת פנים''.',
    'בלבול בין המבחן הטריטוריאלי של ''מקצת העבירה'' לבין עקרונות תחולה אחרים כמו תחולה פרסונלית או פרוטקטיבית, או התמקדות רק ברכיב ההתנהגותי של העבירה.', '["מקצת העבירה", "יסוד עובדתי", "רכיב התנהגותי", "רכיב נסיבתי", "רכיב תוצאתי", "חוק העונשין סעיף 7(א)(1)"]'::jsonb, '**וריאציה 1 — תוצאה בישראל:** אדם יורה בחו"ל ופוגע באדם אחר שנמצא בישראל. האם זו עבירת פנים? ← כן, הרכיב התוצאתי התרחש בישראל, ולכן זו ''מקצת העבירה'' בישראל (רע"פ 1178/97 כהנא נ'' מדינת ישראל).
**וריאציה 2 — שידול בישראל:** אדם משדל בישראל לבצע עבירה בחו"ל. האם זו עבירת פנים? ← כן, מעשה השידול בישראל מהווה ''מקצת העבירה'' (ע"פ 84/88 מדינת ישראל נ'' אברג''יל).

**וריאציה 3 — עבירת שרשרת:** חלק מעבירת שרשרת בוצע בישראל וחלק בחו"ל. האם כל השרשרת נחשבת לעבירת פנים? ← כן, אם חלק מהותי מהיסוד העובדתי של עבירת השרשרת בוצע בישראל, כל השרשרת תיחשב כ''עבירת פנים'' (דנ"פ 4603/97 משולם נ'' מדינת ישראל).', '''מקצת העבירה'' בישראל ← מתקיים אם חלק מהיסוד העובדתי (התנהגותי, נסיבתי או תוצאתי) התרחש בישראל.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 7(א)(1)", "רע\"פ 1178/97 גדליהו כהנא נ'' מדינת ישראל, נא(3) 266 (15.07.1997)", "דנ\"פ 4603/97 אהרן משולם נ'' מדינת ישראל, נא(3) 160 (29.06.1998)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014) | פרק 7 - תחולת דיני העונשין לפי מקום עשיית העבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המבחן הוא האם חלק מהיסוד הנפשי של העבירה התגבש בישראל.', false, 'טענה זו שגויה. המבחן המרכזי מתייחס ליסוד העובדתי של העבירה, ולא ליסוד הנפשי בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המבחן הוא האם חלק מהיסוד העובדתי של העבירה (התנהגותי, נסיבתי או תוצאתי) התרחש בישראל.', true, 'תשובה זו נכונה. הפסיקה והספרות המשפטית קובעות כי ''מקצת העבירה'' מתייחס לחלק מהיסוד העובדתי של העבירה, בין אם הוא התנהגותי, נסיבתי או תוצאתי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המבחן הוא האם העבריין היה אזרח או תושב ישראל בעת ביצוע העבירה.', false, 'טענה זו שגויה. אזרחות או תושבות רלוונטיות לתחולה פרסונלית של דיני העונשין (סעיף 15 לחוק העונשין), אך לא למבחן ''מקצת העבירה'' לצורך סיווג כ''עבירת פנים''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המבחן הוא האם העבירה גרמה נזק ישיר למדינת ישראל או לאזרחיה.', false, 'טענה זו שגויה. נזק למדינה או לאזרחיה רלוונטי לתחולה פרוטקטיבית (סעיף 13 לחוק העונשין), אך אינו המבחן לקביעת ''מקצת העבירה'' לצורך סיווג כ''עבירת פנים''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הסכמת היועץ המשפטי לעבירות חוץ',
    3, 'יוסי, אזרח ישראלי, ביצע עבירת הונאה חמורה בצרפת, שפגעה באזרח צרפתי. העבירה אינה קשורה למדינת ישראל. האם ניתן להעמיד את יוסי לדין בישראל ללא הסכמת היועץ המשפטי לממשלה?', 'שאלה זו בוחנת את אחד הסייגים הפרוצדורליים החשובים לתחולת דיני העונשין של ישראל על ''עבירות חוץ'', והוא הצורך בהסכמת היועץ המשפטי לממשלה. היא מתמקדת בסעיף 9(ב) לחוק העונשין.', 'סעיף 9(ב) לחוק העונשין קובע במפורש כי ''לא תהיה העמדה לדין על עבירת-חוץ אלא בידי היועץ המשפטי לממשלה או בהסכמתו בכתב''. במקרה זה, יוסי ביצע עבירת הונאה בצרפת שפגעה באזרח צרפתי, ואין לה זיקה טריטוריאלית לישראל, ולכן היא מסווגת כ''עבירת חוץ''. העובדה שיוסי הוא אזרח ישראלי מקנה לישראל סמכות שיפוט מכוח עקרון התחולה הפרסונלית (סעיף 15 לחוק העונשין), אך אינה מבטלת את הצורך בהסכמת היועץ המשפטי לממשלה להגשת כתב אישום.',
    'הטעות הנפוצה היא לחשוב שאזרחות ישראלית לבדה מספיקה להעמדה לדין על עבירת חוץ, תוך התעלמות מהדרישה הפרוצדורלית של הסכמת היועץ המשפטי לממשלה.', '["עבירת חוץ", "הסכמת היועץ המשפטי לממשלה", "תחולה פרסונלית", "חוק העונשין סעיף 9(ב)", "סמכות שיפוט פלילית"]'::jsonb, '**וריאציה 1 — עבירת סמים בחו"ל:** אזרח ישראלי סוחר בסמים בחו"ל. האם נדרשת הסכמת היועמ"ש? ← כן, אם זו ''עבירת חוץ'' לפי פקודת הסמים המסוכנים, סעיף 38(ד) דורש הסכמת היועמ"ש (דנ"פ 2980/04 אויקו נ'' מדינת ישראל).
**וריאציה 2 — עבירה נגד משפט העמים:** אזרח זר מבצע פשע מלחמה בחו"ל. האם נדרשת הסכמת היועמ"ש להעמדה לדין בישראל? ← כן, גם בעבירות לפי סעיף 16 לחוק העונשין (תחולה אוניברסלית) נדרשת הסכמת היועמ"ש לפי סעיף 9(ב) לחוק העונשין.
**וריאציה 3 — עבירת פנים עם רכיב חוץ:** אדם מבצע עבירה ש''מקצתה'' בישראל ו''מקצתה'' בחו"ל. האם נדרשת הסכמת היועמ"ש? ← לא, אם העבירה מסווגת כ''עבירת פנים'' לפי סעיף 7(א)(1) או 7(א)(2) לחוק העונשין, אין צורך בהסכמת היועמ"ש (דנ"פ 2980/04 אויקו נ'' מדינת ישראל).', 'העמדה לדין על ''עבירת חוץ'' ← מחייבת הסכמת היועץ המשפטי לממשלה, אם ראה עניין לציבור.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 9(ב)", "חוק העונשין, תשל\"ז-1977, סעיף 15", "דנ\"פ 2980/04 חוזה אויקו נ'' מדינת ישראל, ס(4) 34 (29.12.2005)", "אסף הרדוף, אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | פרק 17: תחולה במקום"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שיוסי הוא אזרח ישראלי, דיני העונשין של ישראל חלים עליו באופן אוטומטי, ללא צורך בהסכמת היועץ המשפטי לממשלה.', false, 'טענה זו שגויה. למרות שיוסי אזרח ישראלי, העבירה היא ''עבירת חוץ'', ולכן נדרשת הסכמת היועץ המשפטי לממשלה לפי סעיף 9(ב) לחוק העונשין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שמדובר ב''עבירת חוץ'', העמדה לדין בישראל דורשת את הסכמת היועץ המשפטי לממשלה, אם ראה כי יש בכך עניין לציבור.', true, 'תשובה זו נכונה. סעיף 9(ב) לחוק העונשין קובע כי לא תהיה העמדה לדין על ''עבירת חוץ'' אלא בידי היועץ המשפטי לממשלה או בהסכמתו בכתב, אם ראה כי יש בכך עניין לציבור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם העבירה נחשבת לעבירה גם לפי הדין הצרפתי (פליליות כפולה).', false, 'טענה זו שגויה. דרישת הפליליות הכפולה היא תנאי נוסף לתחולת דיני העונשין במקרים מסוימים של עבירות חוץ (למשל, סעיף 14(ב)(1) לחוק העונשין), אך היא אינה מחליפה את דרישת הסכמת היועץ המשפטי לממשלה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן העבירה פגעה באינטרסים חיוניים של מדינת ישראל.', false, 'טענה זו שגויה. פגיעה באינטרסים חיוניים של המדינה רלוונטית לתחולה פרוטקטיבית (סעיף 13 לחוק העונשין), אך אינה מבטלת את הצורך בהסכמת היועץ המשפטי לממשלה לעבירות חוץ.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'מעשה בית דין זר והשפעתו',
    4, 'דני, אזרח ישראלי, הורשע בגרמניה בעבירת הונאה חמורה וריצה את עונשו במלואו. לאחר שובו לישראל, מבקשת הפרקליטות להעמידו לדין בישראל על אותה עבירה. מה הדין?', 'שאלה זו עוסקת בהשפעת מעשה בית דין זר על סמכות השיפוט של ישראל, ובפרט בחריג לעקרון הריבונות הקבוע בסעיף 9(ג) לחוק העונשין. היא בוחנת את ההבנה מתי ישראל מוותרת על סמכותה לדון בעבירה שכבר נדונה בחו"ל.', 'סעיף 9(א) לחוק העונשין קובע עקרון כללי לפיו תחולת דיני העונשין של ישראל אינה מסויגת על ידי דין זר או מעשה בית דין זר, אלא אם כן נקבע אחרת בחוק. סעיף 9(ג) לחוק העונשין קובע חריג מפורש לעיקרון זה: ''דיני העונשין של ישראל לא יחולו עוד על עבירה, אם האדם נשפט עליה בחוץ לארץ לפי בקשת מדינת ישראל, ואם הורשע שם – גם נשא את עונשו עליה''. במקרה זה, דני הורשע וריצה את עונשו במלואו בגרמניה, ולכן, בהנחה שההעמדה לדין בגרמניה הייתה לבקשת מדינת ישראל, לא ניתן להעמידו לדין שוב בישראל על אותה עבירה.',
    'הטעות הנפוצה היא להתמקד בעקרון הכללי של אי-הסתייגות ממעשה בית דין זר (סעיף 9(א)), תוך התעלמות מהחריג הספציפי הקבוע בסעיף 9(ג) לחוק העונשין.', '["מעשה בית דין זר", "תחולת דיני העונשין", "חוק העונשין סעיף 9(ג)", "עקרון הריבונות", "ניכוי עונש"]'::jsonb, '**וריאציה 1 — זיכוי בחו"ל:** אדם זוכה בחו"ל מעבירה. האם ניתן להעמידו לדין בישראל? ← אם הזיכוי היה לבקשת ישראל, אז לא ניתן להעמיד לדין בישראל (סעיף 9(ג) לחוק העונשין).
**וריאציה 2 — ריצוי חלקי:** אדם הורשע בחו"ל וריצה חלק מעונשו. האם ניתן להעמידו לדין בישראל? ← אם ריצה רק חלק מהעונש, סעיף 9(ג) לא חל במלואו, אך ניתן לבקש מבית המשפט בישראל להורות על ריצוי יתרת העונש בישראל (סעיף 10 לחוק העונשין).
**וריאציה 3 — עבירת פנים:** אדם ביצע ''עבירת פנים'' והורשע עליה בחו"ל. האם מעשה בית דין זר ימנע העמדה לדין בישראל? ← לא, בעבירת פנים, עקרון הריבונות גובר, ואין מדינה חייבת להחיל דין זר על עבירה שבוצעה בשטחה (ע"פ 5136/22 אברהם לוקר נ'' מדינת ישראל).', 'מעשה בית דין זר ← ימנע העמדה לדין בישראל רק אם האדם נשפט, הורשע וריצה עונש בחו"ל לבקשת מדינת ישראל (סעיף 9(ג) לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 9(א)", "חוק העונשין, תשל\"ז-1977, סעיף 9(ג)", "חוק העונשין, תשל\"ז-1977, סעיף 10", "ע\"פ 5136/22 אברהם לוקר נ'' מדינת ישראל (10.11.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ניתן להעמיד את דני לדין בישראל, שכן תחולת דיני העונשין של ישראל אינה מסויגת על ידי מעשה בית דין זר, אלא אם נקבע אחרת בחוק.', false, 'טענה זו שגויה. למרות שסעיף 9(א) קובע עקרון כללי של אי-הסתייגות, סעיף 9(ג) לחוק העונשין קובע חריג מפורש למצב בו אדם נשפט וריצה עונש בחו"ל לבקשת ישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא ניתן להעמיד את דני לדין בישראל, מכיוון שדיני העונשין של ישראל לא יחולו עוד על עבירה אם האדם נשפט עליה בחוץ לארץ לפי בקשת מדינת ישראל, ואם הורשע שם – גם נשא את עונשו עליה.', true, 'תשובה זו נכונה. סעיף 9(ג) לחוק העונשין קובע חריג לעקרון הריבונות, לפיו אם אדם נשפט והורשע בחו"ל וריצה את עונשו לבקשת ישראל, דיני העונשין של ישראל לא יחולו עליו שוב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ניתן להעמיד את דני לדין בישראל, אך בית המשפט יתחשב בעונש שריצה בגרמניה בעת קביעת עונשו בישראל.', false, 'טענה זו שגויה. סעיף 11 לחוק העונשין קובע ניכוי עונש שריצה בחו"ל, אך זאת במקרה שבו בכל זאת הועמד לדין בישראל. במקרה זה, סעיף 9(ג) מונע את ההעמדה לדין מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא ניתן להעמיד את דני לדין בישראל, אלא אם כן העבירה שביצע בגרמניה אינה נחשבת לעבירה לפי הדין הישראלי.', false, 'טענה זו שגויה. העובדה שהעבירה נחשבת לעבירה לפי הדין הישראלי היא תנאי לתחולת דיני העונשין של ישראל, אך אינה מבטלת את החריג של מעשה בית דין זר לפי סעיף 9(ג).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 5, '2019-S-S-Q05';
END
$$;

