-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '50f15f56-c34b-449e-8ba0-4ea886d0dfdd'::uuid;
  v_group_id uuid := '6f885be8-df22-435b-960a-29591f6e19aa'::uuid;
  v_chapter_id uuid;
