  v_existing_id uuid;
  v_ang_0 uuid := 'ed39f086-1aef-4bbb-8fd5-5438c2fc8136'::uuid;
  v_ang_1 uuid := '9a68c41e-0344-4842-a395-05d72a90d3e4'::uuid;
  v_ang_2 uuid := 'c2cefea5-b629-4b21-9700-3dd71de886de'::uuid;
  v_ang_3 uuid := 'd73c0751-61e4-4072-aff7-5114c3fab335'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q06';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 6, '2019-S-S-Q06';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q06', v_chapter_id, v_subtopic_id, 'על נאור הוטל עונש של קנס, והוא מבקש מבית המשפט כי הקנס ישולם בתשלומים (לשיעורין). מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 6}'::jsonb, 'השאלה עוסקת בסמכות בית המשפט לקבוע תשלום קנס לשיעורין, ובהשלכות קביעה זו על הפעלת מאסר חלף קנס. היא בוחנת את הוראות סעיפים 66 ו-71 לחוק העונשין, המגדירים את הכללים לתשלום קנסות ואת מנגנון המאסר במקום קנס.', 'סעיף 66(א) לחוק העונשין קובע כי קנס שהוטל ישולם מיד, אך בית המשפט רשאי לצוות שהקנס ישולם תוך תקופה שקבע ובתנאים שקבע, לרבות תשלום לשיעורין. כלומר, אין חובה על בית המשפט לאפשר תשלום לשיעורין, אלא זו נתונה לשיקול דעתו. סעיף 66(ב) לחוק העונשין מבהיר כי אם קבע בית המשפט כי הקנס ישולם לשיעורין, יחולו הוראות סעיף 71 לחוק העונשין (העוסק במאסר במקום קנס) לגבי כל שיעור ושיעור. משמעות הדבר היא שאי-תשלום של אחד מהשיעורים במועדו עלול להוביל להפעלת המאסר חלף קנס בגין אותו שיעור שלא שולם. לכן, בית המשפט רשאי לקבוע תשלום לשיעורין, והמאסר חלף קנס יחול על כל תשלום בנפרד.', 'הטעות הנפוצה היא לחשוב שמתן אפשרות לתשלום קנס לשיעורין מבטל את האפשרות להטיל מאסר במקום קנס, או שבית המשפט חייב לאפשר תשלום לשיעורין.',
    '["קנס", "תשלומים לשיעורין", "מאסר חלף קנס", "שיקול דעת בית המשפט", "חוק העונשין סעיף 66", "חוק העונשין סעיף 71"]'::jsonb, '**וריאציה 1 — חובת תשלום מיידי:** האם קנס חייב להיות משולם מיד? ← ככלל כן, אלא אם בית המשפט קבע אחרת (סעיף 66(א) לחוק העונשין).
**וריאציה 2 — מאסר חלף קנס לשיעורין:** האם מאסר חלף קנס חל על כל תשלום בנפרד? ← כן, אם הקנס נקבע לשיעורין, הוראות סעיף 71 חלות לגבי כל שיעור ושיעור (סעיף 66(ב) לחוק העונשין).
**וריאציה 3 — שיקול דעת בית המשפט:** האם בית המשפט חייב לאפשר תשלומים לשיעורין? ← לא, בית המשפט רשאי, אך לא חייב, לצוות על תשלום לשיעורין (סעיף 66(א) לחוק העונשין).', 'בית המשפט רשאי לאפשר תשלום קנס לשיעורין ← מאסר חלף קנס יחול על כל שיעור בנפרד.', '["חוק העונשין, תשל\"ז-1977, סעיף 66", "חוק העונשין, תשל\"ז-1977, סעיף 71", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 8 קנס", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | מאסר במקום קנס"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Fine paid in installments — sentencing rule | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''ערעור פלילי'' הוא פשרה, שכן הנושא הוא ענישה וקנסות, שהוא נושא מהותי בדיני עונשין ולא פרוצדורלי במובן הצר. יש לשקול הוספת תת-נושא ''ענישה'' או ''קנסות ומאסר חלף קנס'' לרשימת תתי-הנושאים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט חייב לקבוע כי הקנס ישולם בתשלומים, אך לא יהיה ניתן להטיל מאסר במקום קנס לגבי כל תשלום ותשלום.', false, 'טענה זו שגויה, שכן בית המשפט אינו חייב לאפשר תשלום לשיעורין, אלא רשאי לעשות כן. כמו כן, מאסר במקום קנס חל על כל תשלום בנפרד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט רשאי לקבוע כי הקנס ישולם בתשלומים, ויהיה ניתן להטיל מאסר במקום קנס לגבי כל תשלום ותשלום.', true, 'תשובה זו נכונה. סעיף 66(א) לחוק העונשין קובע שבית המשפט רשאי לצוות על תשלום קנס לשיעורין, וסעיף 66(ב) קובע כי הוראות סעיף 71 (מאסר במקום קנס) יחולו לגבי כל שיעור ושיעור.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט חייב לקבוע כי הקנס ישולם בתשלומים, ויהיה ניתן להטיל מאסר במקום קנס לגבי כל תשלום ותשלום.', false, 'טענה זו שגויה, שכן בית המשפט אינו חייב לאפשר תשלום לשיעורין, אלא רשאי לעשות כן.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי לקבוע כי הקנס ישולם בתשלומים, אך לא יהיה ניתן להטיל מאסר במקום קנס לגבי כל תשלום ותשלום.', false, 'טענה זו שגויה, שכן סעיף 66(ב) לחוק העונשין קובע במפורש כי הוראות סעיף 71 (מאסר במקום קנס) יחולו לגבי כל שיעור ושיעור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'בחירת הנאשם בין קנס למאסר חלף קנס',
    1, 'על ראובן הוטל קנס בסך 20,000 ש"ח או 20 ימי מאסר תמורתו. ראובן, הנתון במאסר בגין עבירות אחרות ובעל יכולת כלכלית לשלם את הקנס, מבקש לרצות את המאסר שנקבע חלף תשלום הקנס, במצטבר לעונש המאסר שנגזר עליו. מה הדין?', 'שאלה זו בוחנת את היקף שיקול הדעת של נאשם בבחירה בין תשלום קנס לבין ריצוי מאסר חלף קנס, במיוחד כאשר קיימת יכולת כלכלית לשלם. היא מתייחסת למחלוקת פסיקתית בנושא זה, כפי שבאה לידי ביטוי בפסק הדין תפ"ח (מחוזי ת"א) 59874-03-22.', 'לפי דעת הרוב בפסק הדין תפ"ח (מחוזי ת"א) 59874-03-22 מדינת ישראל נ'' דוד אבידן קוינגטון, כאשר בית המשפט מטיל קנס כספי לצד חלופת מאסר תחתיו, ככלל נתונה לנאשם אפשרות הבחירה לשלם את הקנס או לרצות מאסר בפועל תמורתו, וסיבותיו עמו. זאת, גם כאשר מדובר באדם שהוא בעל יכולת כלכלית. עמדה זו נסמכת על לשון סעיף 71 לחוק העונשין ועל הכלל הפרשני המקל עם הנאשם (סעיף 34כא לחוק העונשין). דעת המיעוט סברה כי אין מדובר בחופש בחירה מוחלט, וכי ההחלטה נתונה לשיקול דעת בית המשפט, תוך העדפת גביית הקנס.',
    'הטעות הנפוצה היא להניח כי מאסר חלף קנס הוא תמיד אמצעי אכיפתי בלבד, וכי לנאשם בעל יכולת כלכלית אין זכות לבחור בריצוי מאסר במקום תשלום הקנס.', '["מאסר חלף קנס", "קנס", "שיקול דעת הנאשם", "חוק העונשין סעיף 71", "כלל הפרשנות המקל"]'::jsonb, '**וריאציה 1 — נאשם עני:** נאשם חסר אמצעים מבקש לרצות מאסר חלף קנס. האם בית המשפט יאפשר? ← כן, במקרה כזה, הבחירה בריצוי מאסר היא לגיטימית ומתבקשת (תפ"ח (מחוזי ת"א) 59874-03-22).
**וריאציה 2 — קנס בעבירות כלכליות:** נאשם שהורשע בעבירת מרמה ומעדיף מאסר חלף קנס. האם בית המשפט יאפשר? ← לפי דעת הרוב, כן. אולם, יש הטוענים כי בעבירות כלכליות, הקנס הוא אמצעי יעיל להבטיח שהפשע לא ישתלם (תפ"ח (מחוזי ת"א) 59874-03-22).
**וריאציה 3 — הליכי גבייה:** נאשם מבקש לרצות מאסר חלף קנס לאחר שהחלו נגדו הליכי גבייה. האם הליכי הגבייה ייפסקו? ← כן, כל עוד הקנס לא נגבה, הליכי הגבייה ייפסקו והנאשם יישלח למאסר חלף קנס (תפ"ח (מחוזי ת"א) 59874-03-22).', 'נאשם שהוטל עליו קנס עם חלופת מאסר ← רשאי לבחור לרצות את המאסר חלף קנס, גם אם יש לו יכולת לשלם, וזאת לפי דעת הרוב בפסיקה.',
    '["תפ\"ח (מחוזי ת\"א) 59874-03-22 מדינת ישראל נ'' דוד אבידן קוינגטון (8.4.2025)", "חוק העונשין, תשל\"ז-1977, סעיף 71", "חוק העונשין, תשל\"ז-1977, סעיף 34כא"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט ידחה את בקשתו של ראובן, שכן מאסר חלף קנס הוא מוצא אחרון ונועד לתמרץ תשלום, ולא לאפשר התחמקות ממנו על ידי בעלי יכולת.', false, 'טענה זו משקפת את עמדת המיעוט בפסיקה, אך דעת הרוב קובעת כי לנאשם נתונה אפשרות הבחירה, גם אם הוא בעל יכולת כלכלית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט יקבל את בקשתו של ראובן, שכן ככלל נתונה לנאשם אפשרות הבחירה לשלם את הקנס או לרצות מאסר בפועל תמורתו, וסיבותיו עמו.', true, 'תשובה זו נכונה. לפי דעת הרוב בפסיקה, כאשר בית המשפט מטיל קנס כספי לצד חלופת מאסר, נתונה לנאשם אפשרות הבחירה בין השניים, וזאת בהתאם לכלל הפרשנות המקל עם הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יקבל את בקשתו של ראובן, אך רק אם יוכיח כי מצבו הכלכלי אינו מאפשר לו לשלם את הקנס, שכן אחרת אין הצדקה לריצוי מאסר.', false, 'טענה זו שגויה. לפי דעת הרוב, אפשרות הבחירה נתונה לנאשם גם אם הוא בעל יכולת כלכלית, ואין צורך להוכיח חוסר יכולת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט ידחה את בקשתו של ראובן, שכן מאסר חלף קנס נועד להניב הכנסה לאוצר המדינה, ואין לאפשר לנאשם לחמוק מתשלום קנס שהוטל עליו.', false, 'טענה זו משקפת את עמדת המדינה ודעת המיעוט בפסיקה, אך דעת הרוב קובעת כי לנאשם יש זכות בחירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תכליות מאסר חלף קנס',
    2, 'מהי התכלית העיקרית של מוסד המאסר חלף קנס, כפי שהיא באה לידי ביטוי בחוק העונשין ובפסיקה?', 'שאלה זו עוסקת בתכליות העומדות בבסיס מוסד המאסר חלף קנס. היא בוחנת את ההבנה כי מדובר בכלי בעל אופי כפול – אכיפתי ועונשי – שנועד להבטיח את גביית הקנסות שהוטלו בהליכים פליליים.', 'מאסר חלף קנס, המעוגן בסעיף 71 לחוק העונשין, הינו אמצעי לכפיית ציות לעונש הקנס, המאפשר כליאתו של אדם שלא שילם קנס שהוטל עליו במסגרת הליך פלילי. הקושי בגביית הקנס עשוי להפכו לעונש חסר משמעות, ולפיכך ביקש המחוקק לבצרו בדרך של ''חרב מתהפכת'' לצדו מאסר חלף קנס. עם זאת, כאשר המאסר מופעל ומבוצע, הוא מפסיק להיות אמצעי לחץ והופך להיות העונש גופו. כלומר, מדובר בעונש ''היברידי'' בעל תכלית אכיפתית ותכלית עונשית כאחד.',
    'הטעות הנפוצה היא לראות במאסר חלף קנס אמצעי אכיפתי בלבד, או עונשי בלבד, תוך התעלמות מהאופי הכפול שלו.', '["מאסר חלף קנס", "תכלית אכיפתית", "תכלית עונשית", "חוק העונשין סעיף 71", "קנס"]'::jsonb, '**וריאציה 1 — קנס כעונש בינוני:** היכן ממוקם עונש הקנס על רצף העונשים? ← בין עונש המאסר לעונש המבחן, ונתפס כבינוני בחומרתו (תפ"ח (מחוזי ת"א) 59874-03-22).
**וריאציה 2 — מאסר חלף קנס ככישלון:** האם כליאת עבריין בשל השתמטות מתשלום קנס נחשבת לכישלון? ← כן, הן בשימוש בעונש והן באכיפתו, שכן מטרת הקנס היא להוות חלופה יעילה למאסר (יורם רבין, יניב ואקי, דיני עונשין - כרך ג (2022)).
**וריאציה 3 — יתרונות הקנס:** מהם היתרונות היחסיים של עונש הקנס? ← יעילות הרתעתית, תרומה לקופת המדינה, הפעלה זולה יחסית, פגיעה פחות הרסנית בנאשם בהשוואה למאסר (תפ"ח (מחוזי ת"א) 59874-03-22).', 'מאסר חלף קנס ← אמצעי לכפיית תשלום קנס (אכיפתי) וגם עונש בפני עצמו (עונשי).',
    '["תפ\"ח (מחוזי ת\"א) 59874-03-22 מדינת ישראל נ'' דוד אבידן קוינגטון (8.4.2025)", "רע\"ב 1049/15 ניזרי נ'' שירות בתי הסוהר (18.6.2015)", "ת\"פ (שלום קריות) 3590/01 מדינת ישראל/ המרכז לגביית אגרות וקנסות נ'' חמדה גנדי סלאח (14.11.2019)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 8 קנס"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'התכלית העיקרית היא עונשית גרידא, שכן המאסר מהווה עונש בפני עצמו על אי-ציות להוראת בית המשפט.', false, 'טענה זו שגויה. למרות שלמאסר חלף קנס יש גם פן עונשי, תכליתו העיקרית היא אכיפתית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'התכלית העיקרית היא אכיפתית, כלומר לכפות על הנאשם לשלם את הקנס שהוטל עליו, אך יש לו גם פן עונשי.', true, 'תשובה זו נכונה. מאסר חלף קנס נועד בעיקרו כאמצעי לכפיית ציות לעונש הקנס, אך הוא גם מהווה עונש בפני עצמו כאשר הוא מופעל ומבוצע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'התכלית העיקרית היא שיקומית, שכן ריצוי מאסר מאפשר לנאשם להרהר במעשיו ולהשתקם.', false, 'טענה זו שגויה. תכלית שיקומית אינה התכלית העיקרית של מאסר חלף קנס, אשר מתמקד באכיפת תשלום הקנס.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'התכלית העיקרית היא הרתעתית, למנוע מנאשמים אחרים לבצע עבירות דומות.', false, 'טענה זו שגויה. למרות שלמאסר חלף קנס יש גם אלמנט הרתעתי, תכליתו העיקרית היא אכיפתית כלפי הנאשם הספציפי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'מאסר חלף קנס אל מול פיצויים',
    3, 'על שמעון הוטל קנס בסך 10,000 ש"ח או חודשיים מאסר תמורתו, וכן חובה לשלם פיצויים בסך 50,000 ש"ח לנפגע העבירה. שמעון הפקיד 15,000 ש"ח, אך סכום זה נזקף במלואו על חשבון הפיצויים, בהתאם לסעיף 77(ג) לחוק העונשין. האם ניתן להפעיל נגד שמעון את המאסר חלף קנס?', 'שאלה זו עוסקת בממשק המורכב שבין הטלת קנס, פיצויים לנפגע עבירה, ומאסר חלף קנס. היא בוחנת את פרשנות סעיף 77(ג) לחוק העונשין, הקובע סדר זקיפה של תשלומים, ואת השפעתו על הפעלת מאסר חלף קנס, כפי שנדונה בפסיקת בית המשפט העליון.', 'סעיף 77(ג) לחוק העונשין קובע כי סכום ששולם או נגבה על חשבון קנס שיש בצדו חובת פיצויים, ייזקף תחילה על חשבון הפיצויים. בפסק הדין רע"פ 7621/15 מוסרי נ'' מדינת ישראל, נדונה השאלה האם ניתן לאסור אדם בגין אי-תשלום קנס, כאשר סכום הקנס הופקד אך נזקף ושולם לשם פיצוי נפגע העבירה ולא לטובת פירעון הקנס. דעת הרוב, מפי המשנה לנשיאה (בדימ'') מלצר, קבעה כי פרשנות המערערים מוצאת אחיזה בלשון החוק, וכי די בכך שהנאשם הפקיד סכום העולה על גובה הקנס כדי להסיר את חרב המאסר, גם אם סכום זה הועבר בסופו של יום לנפגעי העבירה. זאת, בניגוד לדעת המיעוט שסברה כי הקנס צריך להיות משולם בפועל.',
    'הטעות הנפוצה היא לפרש את סעיף 77(ג) באופן מצומצם, כך שסדר הזקיפה בלבד הוא הקובע, ולא להבין את השלכתו על מניעת הפעלת מאסר חלף קנס כאשר סכום שווה לקנס הופקד, גם אם נזקף לפיצויים.', '["מאסר חלף קנס", "פיצויים לנפגע עבירה", "חוק העונשין סעיף 77(ג)", "סדר זקיפת תשלומים", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — תשלום חלקי:** נאשם חויב בקנס ובפיצויים, ושילם סכום הנמוך מהקנס. האם ניתן להפעיל מאסר חלף קנס? ← כן, אם הסכום ששולם נמוך מהקנס, לא מתקיים התנאי למניעת המאסר חלף קנס (רע"פ 7621/15 מוסרי).
**וריאציה 2 — אין פיצויים:** נאשם חויב בקנס בלבד. האם הפקדת סכום הקנס תמנע מאסר חלף קנס? ← כן, במקרה כזה, הפקדת הסכום מהווה תשלום הקנס ומבטלת את הצורך במאסר חלף קנס.
**וריאציה 3 — מאסר חלף פיצוי:** האם ניתן לקבוע מאסר חלף אי-תשלום פיצויים? ← לא, החוק אינו מאפשר להטיל מאסר חלף אי-תשלום פיצויים, שכן פיצוי הוא חיוב אזרחי (יורם רבין, יניב ואקי, דיני עונשין - כרך ג (2022) | יב. מאסר חלף פיצוי).', 'הפקדת סכום השווה לקנס (גם אם נזקף לפיצויים) ← מונעת הפעלת מאסר חלף קנס (לפי דעת הרוב ברע"פ 7621/15 מוסרי).',
    '["רע\"פ 7621/15 יצחק מוסרי נ'' מדינת ישראל (1.7.2021)", "חוק העונשין, תשל\"ז-1977, סעיף 77(ג)", "ע\"פ 8458/11 יוסי שובל נ'' מדינת ישראל (11.9.2013)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | יב. מאסר חלף פיצוי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שהקנס לא שולם בפועל, וסעיף 77(ג) קובע סדר זקיפה בלבד ואינו מבטל את חובת תשלום הקנס.', false, 'טענה זו משקפת את עמדת המיעוט בפסיקה, אשר סברה כי לשון החוק מתייחסת לפרעון הקנס בפועל ולא רק להפקדת סכום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שדי בכך שהנאשם הפקיד סכום העולה על גובה הקנס כדי להסיר את חרב המאסר חלף קנס, גם אם הסכום נזקף לפיצויים.', true, 'תשובה זו נכונה. לפי דעת הרוב ברע"פ 7621/15 מוסרי, די בכך שהנאשם הפקיד סכום השווה או עולה על גובה הקנס, גם אם הוא נזקף לפיצויים, כדי למנוע את הפעלת המאסר חלף קנס.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך בית המשפט יתחשב בסכום ששולם לפיצויים ויפחית את תקופת המאסר חלף קנס באופן יחסי.', false, 'טענה זו שגויה. הפחתה יחסית של תקופת המאסר חלף קנס מתרחשת כאשר משולם חלק מהקנס עצמו (סעיף 71(ד) לחוק העונשין), ולא כאשר סכום נזקף לפיצויים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, מכיוון שאין להטיל מאסר חלף פיצויים, וסעיף 77(ג) משווה את דין הפיצויים לקנס לעניין גבייה בלבד.', false, 'טענה זו שגויה. אמנם אין להטיל מאסר חלף פיצויים, אך השאלה היא האם הפקדת הסכום מסירה את המאסר חלף קנס, ולא האם הפיצויים עצמם ניתנים להמרה במאסר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סדר נשיאת מאסר חלף קנס ומאסר רגיל',
    4, 'יוסי מרצה עונש מאסר פלילי בגין עבירת שוד. במהלך ריצוי המאסר, הופעל נגדו צו מאסר חלף קנס בגין אי-תשלום קנס שהוטל עליו בעבר. מהו סדר נשיאת המאסרים במקרה זה?', 'שאלה זו עוסקת בסדר נשיאת עונשי מאסר, ובפרט במצב שבו נאשם מרצה מאסר פלילי ומוטל עליו מאסר חלף קנס. היא בוחנת את הוראות סעיף 46 לחוק העונשין, הקובע כלל ספציפי לסדר זה.', 'סעיף 46 לחוק העונשין, העוסק ב''סדר נשיאת מאסר פלילי'', קובע כי כאשר אדם המרצה עונש מאסר פלילי אינו עומד בתשלום קנס שהושת עליו, והוא נדרש לרצות מאסר במקומו, ''יופסק'' ריצוי עונש המאסר הפלילי לשם נשיאת המאסר בגין אי-תשלום הקנס. לאחר מכן, ''ישוב ויימשך'' המאסר הפלילי משתם המאסר חלף קנס. ההיגיון בכך נעוץ במדיניות המחוקק להמריץ תשלום קנסות על-ידי מי שחייב בהם. כלל זה מבטיח כי המאסר חלף קנס ירוצה באופן מיידי, לפני המשך ריצוי המאסר הפלילי.',
    'הטעות הנפוצה היא לחשוב שמאסר חלף קנס ירוצה לאחר סיום המאסר הפלילי, או במקביל אליו, תוך התעלמות מהכלל המפורש הקבוע בסעיף 46 לחוק העונשין.', '["מאסר חלף קנס", "מאסר פלילי", "סדר נשיאת מאסרים", "חוק העונשין סעיף 46", "אכיפת קנסות"]'::jsonb, '**וריאציה 1 — מאסר חלף קנס נוסף:** נאשם מרצה מאסר חלף קנס, ומוטל עליו מאסר חלף קנס נוסף. מהו סדר הנשיאה? ← המאסר חלף קנס הנוסף ירוצה במצטבר למאסר חלף קנס הראשון, אלא אם בית המשפט הורה אחרת (סעיף 71(ה) לחוק העונשין).
**וריאציה 2 — מאסר חלף קנס לפני מאסר פלילי:** נאשם נידון למאסר פלילי ולמאסר חלף קנס. מה ירוצה קודם? ← המאסר חלף קנס ירוצה תחילה לפני כל מאסר פלילי אחר (סעיף 46 לחוק העונשין).
**וריאציה 3 — עיכוב ביצוע מאסר חלף קנס:** האם ניתן לעכב ביצוע מאסר חלף קנס? ← כן, בית המשפט רשאי לעכב ביצוע עונש, אך סמכות זו מוגבלת, לרוב לפעם אחת נוספת (בש"פ 9098/15 ג''סאר נ'' מדינת ישראל).', 'מאסר חלף קנס בעת ריצוי מאסר פלילי ← המאסר הפלילי יופסק, המאסר חלף קנס ירוצה תחילה, ולאחר מכן יחודש המאסר הפלילי.',
    '["בש\"פ 9098/15 אשרף ג''סאר נ'' מדינת ישראל (19.1.2016)", "חוק העונשין, תשל\"ז-1977, סעיף 46", "חוק העונשין, תשל\"ז-1977, סעיף 71(ה)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 8 קנס"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'יוסי ימשיך לרצות את המאסר הפלילי, ולאחר סיומו יתחיל לרצות את המאסר חלף קנס.', false, 'טענה זו שגויה. סעיף 46 לחוק העונשין קובע סדר נשיאה הפוך במקרה של מאסר חלף קנס.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'המאסר הפלילי יופסק, יוסי יישא תחילה את המאסר חלף קנס, ולאחר מכן ימשיך בריצוי יתרת המאסר הפלילי.', true, 'תשובה זו נכונה. סעיף 46 לחוק העונשין קובע כי אם אדם במאסר פלילי בעת שהוטל עליו מאסר בשל אי-תשלום קנס, יופסק המאסר הפלילי לשם נשיאת המאסר חלף קנס, וישוב ויימשך משתם המאסר האמור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'יוסי ירצה את שני המאסרים במקביל, כאשר תקופת המאסר הארוכה יותר היא שתקבע את משך הכליאה הכולל.', false, 'טענה זו שגויה. סעיף 46 לחוק העונשין קובע סדר נשיאה עוקב, ולא מקביל, במקרה של מאסר חלף קנס.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט רשאי לקבוע את סדר נשיאת המאסרים לפי שיקול דעתו, בהתחשב בנסיבות העניין.', false, 'טענה זו שגויה. סעיף 46 לחוק העונשין קובע כלל ברור לגבי סדר נשיאת מאסר חלף קנס, ואינו מותיר שיקול דעת לבית המשפט בעניין זה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 6, '2019-S-S-Q06';
END
$$;

