-- Q07 — 2019-S-S-Q07 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Withdrawal from criminal attempt (חרטה) — sec. 28 פקודת העונשין, burden of proof
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'fc756f1d-9fdc-4c00-a2fb-4e22529ef840'::uuid;
  v_group_id uuid := '69aaf7f7-c01f-4a60-8ce7-81f8d36df1e9'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '5c5b4e31-33d9-4ef7-87ae-1c927bddab0d'::uuid;
  v_ang_1 uuid := '401c5e01-ba1b-4b63-b3dc-ae6fccae911c'::uuid;
  v_ang_2 uuid := '1ebbeeec-9827-4f09-8691-0f8c86761b46'::uuid;
  v_ang_3 uuid := '4951cf6d-e1f6-4e9e-995a-7118a9cf1f84'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q07';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 7, '2019-S-S-Q07';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q07', v_chapter_id, v_subtopic_id, 'מהי רמת נטל הוכחת הפטור עקב חרטה המנוי בסעיף 28 לחוק העונשין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 7}'::jsonb, 'השאלה עוסקת בנטל ההוכחה החל על נאשם הטוען לפטור עקב חרטה, המנוי בסעיף 28 לחוק העונשין. היא בוחנת את ההבחנה בין רמת ההוכחה הנדרשת במקרה זה (מאזן הסתברויות) לבין רמת ההוכחה הכללית בסייגים לאחריות פלילית (ספק סביר).', 'סעיף 28 לחוק העונשין קובע כי ''מי שניסה לעבור עבירה, לא יישא באחריות פלילית לניסיון, אם הוכיח שמחפץ נפשו בלבד ומתוך חרטה, חדל מהשלמת המעשה או תרם תרומה של ממש למניעת התוצאות שבהן מותנית השלמת העבירה''. לשון החוק ''אם הוכיח'' מטילה את נטל ההוכחה על הנאשם. הפסיקה קבעה כי נטל זה הוא ברמת מאזן ההסתברויות, בדומה למשפט האזרחי (ע"פ 5767/14 פלוני נ'' מדינת ישראל; ע"פ 297/11 סעיד נ'' מדינת ישראל; ע"פ 10110/03 גמליאל נ'' מדינת ישראל; ע"פ 5268/04 מינין נ'' מדינת ישראל; ע"פ 401/99 מצארווה נ'' מדינת ישראל). זאת בניגוד לכלל הרחב החל על רוב הסייגים לאחריות פלילית (כגון הגנה עצמית, אי-שפיות הדעת), שם די לנאשם לעורר ספק סביר בדבר קיומו של הסייג, והנטל להסיר ספק זה מעבר לכל ספק סביר מוטל על התביעה (סעיפים 34ה ו-34כב(ב) לחוק העונשין).', 'הטעות הנפוצה היא לבלבל בין רמת ההוכחה הנדרשת בפטור עקב חרטה (מאזן הסתברויות) לבין רמת ההוכחה הכללית בסייגים לאחריות פלילית (ספק סביר).',
    '["פטור עקב חרטה", "נטל ההוכחה", "מאזן הסתברויות", "ספק סביר", "סייג לאחריות פלילית", "חוק העונשין סעיף 28"]'::jsonb, '**וריאציה 1 — נטל ההוכחה בסייגים כלליים:** מהו נטל ההוכחה הנדרש לנאשם הטוען לסייג לאחריות פלילית (כגון הגנה עצמית)? ← די לו לנאשם לעורר ספק סביר בדבר קיומו של הסייג, והנטל עובר לתביעה להסירו מעבר לכל ספק סביר (סעיפים 34ה ו-34כב(ב) לחוק העונשין).
**וריאציה 2 — תנאי הפטור עקב חרטה:** מהם התנאים המצטברים לפטור עקב חרטה? ← חדילה מהשלמת המעשה או תרומה למניעת התוצאות; מחפץ נפשו בלבד; ומתוך חרטה (סעיף 28 לחוק העונשין).
**וריאציה 3 — תכלית הפטור עקב חרטה:** מהן התכליות העיקריות של הפטור עקב חרטה? ← טעם מוסרי (שינוי במצב הנפשי של הנאשם) וטעם תועלתני (עידוד עבריינים לחדול ממעשיהם) (ע"פ 5767/14 פלוני).', 'נטל ההוכחה לפטור עקב חרטה (סעיף 28 לחוק העונשין) ← מוטל על הנאשם ברמת מאזן ההסתברויות, בניגוד לרוב הסייגים האחרים.', '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "ע\"פ 297/11 מחסן סעיד נ'' מדינת ישראל (22.07.2013)", "ע\"פ 10110/03 עופר גמליאל נ'' מדינת ישראל (11.12.2006)", "ע\"פ 5268/04 ליודמילה מינין נ'' מדינת ישראל (07.11.2005)", "ע\"פ 401/99 עאמר מצארווה נ'' מדינת ישראל, נג(3) 561 (11.07.1999)", "יניב ואקי, דיני ראיות כרך ד (2021) | פרק 66 נטל ההוכחה במשפט הפלילי", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | פטור עקב חרטה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''ערעור פלילי'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Withdrawal from criminal attempt (חרטה) — sec. 28 פקודת העונשין, burden of proof | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''ערעור פלילי'' הוא פשרה, שכן הנושא הוא הגנה מהותית בדיני עונשין ונטל הוכחתה, ולא נושא פרוצדורלי במובן הצר. יש לשקול הוספת תת-נושא ''הגנות בחוק העונשין'' או ''נטל ההוכחה בפלילים'' לרשימת תתי-הנושאים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הוכחת הטענה ברמה מעבר לכל ספק סביר.', false, 'טענה זו שגויה. רמת ההוכחה ''מעבר לכל ספק סביר'' מוטלת על התביעה להוכחת אשמת הנאשם, ולא על הנאשם להוכחת סייג הפטור עקב חרטה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הוכחת הטענה ברמה של מאזן ההסתברויות.', true, 'תשובה זו נכונה. הפסיקה קבעה כי נטל ההוכחה לפטור עקב חרטה מוטל על הנאשם ברמת מאזן ההסתברויות, בדומה למשפט האזרחי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הוכחה הטענה ברמת ודאות קרובה לוודאי.', false, 'טענה זו שגויה. רמת ''ודאות קרובה לוודאי'' אינה רמת הוכחה מוכרת בדין הפלילי הישראלי לעניין סייגים לאחריות פלילית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הוכחת הטענה ברמת ניצוץ ראייתי.', false, 'טענה זו שגויה. ''ניצוץ ראייתי'' אינו רמת הוכחה מספקת להוכחת סייג לאחריות פלילית, אלא רק להעלאת טענה או עוררות ספק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תנאי הפטור עקב חרטה: חדילה מחפץ נפשו',
    1, 'דני ניסה לשדוד בנק, אך במהלך השוד הגיעה המשטרה למקום. דני, שחשש שייתפס, הפסיק את ניסיון השוד ונמלט מהמקום. האם דני זכאי לפטור עקב חרטה?', 'שאלה זו בוחנת את אחד התנאים המצטברים לפטור עקב חרטה, והוא שהחדילה מהשלמת המעשה נעשתה ''מחפץ נפשו בלבד''. היא מדגישה את ההבחנה בין חרטה פנימית לבין הפסקת המעשה עקב גורמים חיצוניים.', 'סעיף 28 לחוק העונשין דורש שהחדילה מהשלמת המעשה או התרומה למניעת התוצאות תהיה ''מחפץ נפשו בלבד''. הפסיקה מפרשת תנאי זה כדרישה שהחזרה מהשלמת העבירה תהיה ביוזמת העושה וללא השפעה של גורם חיצוני. כלומר, אם העושה חדל מהמעשה בגלל חשש שייתפס, קושי חיצוני, או חוסר יכולת להשלים את העבירה, לא יחול הפטור. במקרה זה, דני הפסיק את ניסיון השוד רק משום שחשש שייתפס עקב הגעת המשטרה, וזהו גורם חיצוני שאינו מעיד על חרטה ''מחפץ נפשו בלבד''.',
    'הטעות הנפוצה היא לראות בכל הפסקה של ניסיון עבירה כחרטה, מבלי להבחין בין הפסקה הנובעת מרצון פנימי לבין הפסקה הנובעת מנסיבות חיצוניות.', '["פטור עקב חרטה", "חדילה מחפץ נפשו בלבד", "גורם חיצוני", "ניסיון", "חוק העונשין סעיף 28"]'::jsonb, '**וריאציה 1 — מעצור בנשק:** אדם ניסה לירות אך נתקל במעצור בנשק וחדל. האם יזכה לפטור? ← לא, זו חדילה עקב גורם חיצוני ולא ''מחפץ נפשו בלבד'' (ע"פ 5767/14 פלוני).
**וריאציה 2 — התנגדות הקורבן:** אדם ניסה לאנוס אך חדל עקב התנגדות נמרצת של הקורבן. האם יזכה לפטור? ← לא, זו חדילה עקב גורם חיצוני (התנגדות הקורבן) ולא ''מחפץ נפשו בלבד'' (ע"פ 401/99 מצארווה).
**וריאציה 3 — שינוי תוכנית:** אדם חדל מביצוע עבירה כי החליט לדחות אותה למועד אחר או לבצע אותה נגד קורבן אחר. האם יזכה לפטור? ← לא, זו אינה חרטה מלאה אלא שיקול דעת תועלתני (ע"פ 8457/15 ווזווז).', 'חדילה ''מחפץ נפשו בלבד'' ← דורשת יוזמה פנימית של העושה, ללא השפעת גורמים חיצוניים (כגון חשש מתפיסה או קושי בביצוע).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "ע\"פ 401/99 עאמר מצארווה נ'' מדינת ישראל, נג(3) 561 (11.07.1999)", "ע\"פ 8457/15 מדינת ישראל נ'' עומר בן גאזי ווזווז (01.11.2018)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | פטור עקב חרטה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שדני חדל מהשלמת המעשה, ואין זה משנה מה היה המניע לחדילה.', false, 'טענה זו שגויה. אחד התנאים המצטברים לפטור עקב חרטה הוא שהחדילה תהיה ''מחפץ נפשו בלבד'', ולא עקב גורמים חיצוניים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שהחדילה מהשלמת המעשה נבעה מגורם חיצוני (הגעת המשטרה), ולא ''מחפץ נפשו בלבד'' ומתוך חרטה פנימית.', true, 'תשובה זו נכונה. הפסיקה קובעת כי חדילה ''מחפץ נפשו בלבד'' דורשת יוזמה פנימית של העושה, ללא השפעת גורמים חיצוניים כמו חשש מתפיסה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוכיח כי בנוסף לחשש מתפיסה, חש גם חרטה מוסרית על מעשיו.', false, 'טענה זו שגויה. גם אם הייתה חרטה מוסרית, אם החדילה נבעה בעיקר מגורם חיצוני, התנאי של ''מחפץ נפשו בלבד'' לא מתקיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שדני לא תרם תרומה של ממש למניעת התוצאות, אלא רק נמלט.', false, 'טענה זו שגויה חלקית. אמנם דני לא תרם תרומה אקטיבית, אך התנאי הוא חדילה מהשלמת המעשה או תרומה למניעת התוצאות. הבעיה העיקרית היא שהחדילה לא הייתה ''מחפץ נפשו בלבד''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי הפטור עקב חרטה: פעולה חיצונית',
    2, 'יעל תכננה להרעיל את בן זוגה. היא קנתה רעל, הכינה את המשקה, אך ברגע האחרון התחרטה ורק חשבה לעצמה שהיא לא מסוגלת לעשות זאת. היא לא נקטה כל פעולה אקטיבית למנוע את השלמת העבירה, והרעל נשאר על השולחן. האם יעל זכאית לפטור עקב חרטה?', 'שאלה זו מתמקדת בדרישה לפעולה חיצונית המבטאת חרטה, ולא רק תחושה פנימית, כתנאי לקבלת הפטור עקב חרטה לפי סעיף 28 לחוק העונשין.', 'הפסיקה קבעה כי על מנת ליהנות מהפטור עקב חרטה, אין די בכך שהנאשם יחוש תחושת חרטה סובייקטיבית פנימית. החרטה צריכה להשתקף בפעולה חיצונית של הנאשם למניעת עשיית העבירה או השלמתה (ע"פ 10110/03 גמליאל נ'' מדינת ישראל; ת"פ (מחוזי י-ם) 55653-12-15 מדינת ישראל נ'' עטאיא אבו עישה). במקרה זה, יעל רק חשה חרטה פנימית אך לא נקטה כל פעולה אקטיבית למנוע את השלמת העבירה (למשל, להזעיק עזרה, להשמיד את הרעל, או להזהיר את הקורבן). לכן, היא לא תזכה לפטור.',
    'התבלבלות בין תחושת חרטה פנימית לבין הדרישה המשפטית לפעולה אקטיבית המבטאת חרטה.', '["פטור עקב חרטה", "פעולה חיצונית", "חרטה פנימית", "ניסיון", "חוק העונשין סעיף 28"]'::jsonb, '**וריאציה 1 — חרטה והזעקת עזרה:** אדם ניסה לחנוק את בתו, התחרט והזעיק כוחות חירום. האם יזכה לפטור? ← כן, הזעקת כוחות חירום היא פעולה חיצונית המבטאת תרומה למניעת התוצאות (ע"פ 5767/14 פלוני).
**וריאציה 2 — חרטה והשמדת ראיות:** אדם ניסה לבצע עבירה, התחרט והשמיד את כלי הפשע. האם יזכה לפטור? ← כן, השמדת כלי הפשע יכולה להיחשב כפעולה חיצונית למניעת השלמת העבירה או תוצאותיה.
**וריאציה 3 — חרטה ודיווח למשטרה:** אדם תכנן עבירה, התחרט ודיווח למשטרה על התוכנית. האם יזכה לפטור? ← כן, דיווח למשטרה הוא פעולה חיצונית אקטיבית למניעת העבירה (ע"פ 10110/03 גמליאל).', 'פטור עקב חרטה ← דורש פעולה חיצונית אקטיבית למניעת השלמת העבירה או תוצאותיה, ולא רק תחושת חרטה פנימית.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 10110/03 עופר גמליאל נ'' מדינת ישראל (11.12.2006)", "ת\"פ (מחוזי י-ם) 55653-12-15 מדינת ישראל נ'' עטאיא אבו עישה (28.06.2016)", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | פטור עקב חרטה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, מכיוון שהיא חשה חרטה פנימית כנה, ודי בכך כדי לזכות בפטור.', false, 'טענה זו שגויה. הפסיקה דורשת פעולה חיצונית המבטאת חרטה, ולא רק תחושה פנימית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, מכיוון שחרטה פנימית בלבד אינה מספקת, ונדרשת פעולה חיצונית אקטיבית למניעת השלמת העבירה או תוצאותיה.', true, 'תשובה זו נכונה. הפסיקה קבעה כי על החרטה להשתקף בפעולה חיצונית של הנאשם למניעת עשיית העבירה או השלמתה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אם תוכיח כי החרטה נבעה משינוי מוסרי עמוק ולא משיקולים תועלתניים.', false, 'טענה זו שגויה. למרות שהטעם המוסרי הוא אחד מתכליות הפטור, הוא אינו מחליף את הדרישה לפעולה חיצונית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, מכיוון שהיא לא תרמה תרומה של ממש למניעת התוצאות, שכן הרעל נשאר על השולחן.', false, 'טענה זו שגויה חלקית. אמנם היא לא תרמה תרומה של ממש, אך הבעיה העיקרית היא היעדר פעולה חיצונית כלשהי המבטאת חרטה, ולא רק היעדר תרומה למניעת התוצאות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פטור עקב חרטה בעבירה מושלמת אחרת',
    3, 'ראובן פרץ לדירה במטרה לגנוב רכוש. לאחר שנכנס לדירה, התחרט על מעשה הגניבה והחליט לא לגנוב דבר. הוא יצא מהדירה מבלי לקחת דבר. האם ראובן זכאי לפטור מלא מאחריות פלילית?', 'שאלה זו עוסקת בסייג הקבוע בסעיף 28 לחוק העונשין, לפיו הפטור עקב חרטה אינו גורע מאחריותו הפלילית של הנאשם בשל עבירה מושלמת אחרת שבוצעה במהלך הניסיון. היא בוחנת את ההבנה של היקף הפטור.', 'סעיף 28 לחוק העונשין קובע במפורש כי ''אין באמור כדי לגרוע מאחריותו הפלילית בשל עבירה מושלמת אחרת שבמעשה''. משמעות הדבר היא שאם במהלך ניסיון לבצע עבירה, הושלמה עבירה אחרת, הנאשם יישא באחריות פלילית על אותה עבירה מושלמת, גם אם הוא זכאי לפטור עקב חרטה על הניסיון לעבירה העיקרית. במקרה זה, ראובן פרץ לדירה, ובכך השלים את עבירת הפריצה. גם אם התחרט על הגניבה ולא ביצע אותה, הוא עדיין יישא באחריות פלילית על עבירת הפריצה.',
    'הטעות הנפוצה היא לחשוב שהפטור עקב חרטה מעניק חסינות מוחלטת מכל אחריות פלילית הקשורה לאירוע, תוך התעלמות מהסייג המפורש בסעיף 28 לגבי עבירות מושלמות אחרות.', '["פטור עקב חרטה", "עבירה מושלמת אחרת", "ניסיון", "חוק העונשין סעיף 28", "אחריות פלילית"]'::jsonb, '**וריאציה 1 — ניסיון רצח ופציעה:** אדם ניסה לרצוח, פצע את הקורבן קשה, ואז התחרט. האם יורשע בפציעה? ← כן, הפטור עקב חרטה על ניסיון הרצח אינו גורע מאחריותו על עבירת הפציעה המושלמת (ע"פ 5767/14 פלוני).
**וריאציה 2 — ניסיון אונס ותקיפה:** אדם ניסה לאנוס, תקף את הקורבן, ואז חדל. האם יורשע בתקיפה? ← כן, עבירת התקיפה הושלמה, והפטור על ניסיון האונס אינו חל עליה.
**וריאציה 3 — הכנה לטרור וחרטה:** אדם ביצע הכנה לביצוע מעשה טרור, ואז התחרט. האם יזכה לפטור? ← סעיף 28(ג) לחוק המאבק בטרור קובע כי הוראות סעיף 28 לחוק העונשין יחולו גם על הכנה לביצוע מעשה טרור, ולכן אם התנאים מתקיימים, יזכה לפטור על ההכנה, אך לא על עבירה מושלמת אחרת.', 'פטור עקב חרטה ← אינו פוטר מאחריות פלילית על עבירה מושלמת אחרת שבוצעה במהלך הניסיון.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "חוק המאבק בטרור, תשע\"ו-2016, סעיף 28(ג)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026) | פטור עקב חרטה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שהתחרט על מעשה הגניבה ולא השלים את העבירה העיקרית.', false, 'טענה זו שגויה. הפטור עקב חרטה אינו פוטר מאחריות פלילית על עבירה מושלמת אחרת שבוצעה במהלך הניסיון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, ראובן יורשע בעבירת פריצה, שכן הפטור עקב חרטה אינו גורע מאחריותו הפלילית בשל עבירה מושלמת אחרת שבמעשה.', true, 'תשובה זו נכונה. סעיף 28 לחוק העונשין קובע במפורש כי הפטור אינו גורע מאחריות פלילית על עבירה מושלמת אחרת, כמו פריצה במקרה זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך בית המשפט יתחשב בחרטתו כשיקול להקלה בעונש על עבירת הפריצה.', false, 'טענה זו שגויה. למרות שחרטה יכולה להוות שיקול לעונש, היא אינה מעניקה פטור מלא מאחריות פלילית על עבירה מושלמת אחרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, מכיוון שחרטה על גניבה אינה רלוונטית לעבירת פריצה, שהיא עבירה נפרדת.', false, 'טענה זו שגויה. החרטה רלוונטית לעבירת הגניבה, אך סעיף 28 קובע במפורש שהיא אינה פוטרת מעבירה מושלמת אחרת, כמו הפריצה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'נטל ההוכחה בסייגים לאחריות פלילית כללית',
    4, 'ראובן מואשם בעבירת תקיפה וטוען להגנה עצמית. מהי רמת נטל ההוכחה המוטלת על ראובן להוכחת טענתו?', 'שאלה זו עוסקת בנטל ההוכחה הכללי החל על נאשם הטוען לסייג לאחריות פלילית (כגון הגנה עצמית), בניגוד לנטל ההוכחה הספציפי של הפטור עקב חרטה. היא בוחנת את ההוראות הכלליות בסעיפים 34ה ו-34כב(ב) לחוק העונשין.', 'סעיפים 34ה ו-34כב(ב) לחוק העונשין קובעים את הכלל לגבי נטל ההוכחה בסייגים לאחריות פלילית. סעיף 34ה קובע חזקה כי מעשה נעשה בתנאים שאין בהם סייג לאחריות פלילית, ולכן על הנאשם מוטל נטל הבאת הראיות הראשוני לעורר את הסייג. אולם, סעיף 34כב(ב) קובע כי אם התעורר ספק סביר שמא קיים סייג לאחריות פלילית, והספק לא הוסר, יחול הסייג. כלומר, די לנאשם לעורר ספק סביר בדבר קיומו של הסייג, והנטל להסיר ספק זה מעבר לכל ספק סביר מוטל על התביעה (ע"פ 5466627 הרב אליהו בקשי דורון נ'' מדינת ישראל; יניב ואקי, דיני ראיות כרך ד). זהו הכלל החל על רוב הסייגים, בניגוד לפטור עקב חרטה שבו נטל השכנוע מוטל על הנאשם ברמת מאזן ההסתברויות.',
    'הטעות הנפוצה היא להחיל את רמת ההוכחה של מאזן ההסתברויות, הנדרשת בפטור עקב חרטה, על כלל הסייגים לאחריות פלילית, תוך התעלמות מהכלל המקל יותר של ספק סביר.', '["נטל ההוכחה", "סייג לאחריות פלילית", "הגנה עצמית", "ספק סביר", "חוק העונשין סעיף 34ה", "חוק העונשין סעיף 34כב(ב)"]'::jsonb, '**וריאציה 1 — סייג אי-שפיות הדעת:** נאשם טוען לאי-שפיות הדעת. מהו נטל ההוכחה? ← די לו לעורר ספק סביר בדבר אי-שפיותו, והנטל עובר לתביעה להסיר ספק זה (יניב ואקי, דיני ראיות כרך ד).
**וריאציה 2 — סייג שכרות:** נאשם טוען לשכרות. מהו נטל ההוכחה? ← די לו לעורר ספק סביר בדבר שכרותו, והנטל עובר לתביעה להסיר ספק זה (יניב ואקי, דיני ראיות כרך ד).
**וריאציה 3 — חזקה בחוק:** חוק מסוים קובע חזקה לחובת הנאשם (למשל, החזקת סכין למטרה לא כשרה). מהו נטל ההוכחה לסתירת החזקה? ← על הנאשם להוכיח את סתירת החזקה ברמת מאזן ההסתברויות (יורם רבין, יניב ואקי, דיני עונשין כרך ב | פרק 34).', 'ברוב הסייגים לאחריות פלילית ← די לנאשם לעורר ספק סביר, והנטל להסרתו עובר לתביעה מעבר לכל ספק סביר.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34ה", "חוק העונשין, תשל\"ז-1977, סעיף 34כב(ב)", "ע\"פ 5466627 הרב אליהו בקשי דורון נ'' מדינת ישראל (25.05.2021)", "יניב ואקי, דיני ראיות כרך ד (2021) | פרק 66 נטל ההוכחה במשפט הפלילי", "יורם רבין, יניב ואקי, דיני עונשין - כרך ב (2014) | פרק 34 - רף ההוכחה להוכחת סייג לאחריות פלילית"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'עליו להוכיח את טענתו ברמה של מאזן ההסתברויות.', false, 'טענה זו שגויה. רמת מאזן ההסתברויות נדרשת רק במקרים חריגים בהם החוק מטיל במפורש נטל שכנוע על הנאשם, כמו בפטור עקב חרטה, ולא בהגנה עצמית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'די לו לעורר ספק סביר בדבר אי-קיומה של הגנה עצמית, והנטל עובר לתביעה להסיר ספק זה מעבר לכל ספק סביר.', true, 'תשובה זו נכונה. לפי סעיפים 34ה ו-34כב(ב) לחוק העונשין, ברוב הסייגים לאחריות פלילית, די לנאשם לעורר ספק סביר, והנטל להסרתו עובר לתביעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'עליו להוכיח את טענתו ברמה מעבר לכל ספק סביר.', false, 'טענה זו שגויה. רמת ''מעבר לכל ספק סביר'' מוטלת על התביעה להוכחת אשמת הנאשם, ולא על הנאשם להוכחת סייג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הנטל להוכחת הגנה עצמית מוטל על התביעה מלכתחילה, ואין על הנאשם כל נטל.', false, 'טענה זו שגויה. על הנאשם מוטל נטל הבאת הראיות הראשוני לעורר את הסייג, ורק לאחר מכן עובר נטל השכנוע לתביעה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 7, '2019-S-S-Q07';
END
$$;

