  v_ang_0 uuid := '52675f93-90d0-48ea-b66f-6225bf2b117f'::uuid;
  v_ang_1 uuid := 'a05a1d2c-5707-4c1c-8de7-d1daa34a4750'::uuid;
  v_ang_2 uuid := '0a95a668-89c5-4f79-b644-702c18a16f68'::uuid;
