  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q08', v_chapter_id, v_subtopic_id, 'חברותו של עו"ד ירושלמי בלשכת עורכי הדין פקעה השנה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 8}'::jsonb, 'השאלה עוסקת בהשלכות פקיעת חברות בלשכת עורכי הדין, ובפרט בעקרון שמירת המרות של הלשכה על חבריה לשעבר וזכותם לגבות שכר עבור שירותים שניתנו לפני פקיעת החברות. היא מתבססת על סעיף 50 לחוק לשכת עורכי הדין.', 'סעיף 50 לחוק לשכת עורכי הדין, התשכ"א-1961, קובע שני עקרונות מרכזיים לגבי מי שחברותו בלשכה פקעה: ראשית, הוא ''נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות''. משמעות הדבר היא שלשכת עורכי הדין שומרת על סמכותה המשמעתית לדון בעניינים אתיים שבוצעו על ידי עורך הדין בעת שהיה חבר בלשכה, גם אם חברותו פקעה מאוחר יותר. שנית, הוא ''רשאי הוא לגבות שכרו בעד שירותים שנתן לפני כן''. כלומר, פקיעת החברות אינה גורעת מזכותו של עורך הדין לגבות שכר עבור עבודתו שבוצעה כדין לפני פקיעת חברותו. הוראות אלו מבטיחות את המשך הפיקוח על התנהלות עורכי הדין ואת זכויותיהם הכלכליות גם לאחר סיום חברותם.', 'הטעות הנפוצה היא לחשוב שפקיעת חברות בלשכה מנתקת לחלוטין את הקשר בין עורך הדין ללשכה, הן מבחינת סמכות משמעתית והן מבחינת זכויות כלכליות.',
    '["פקיעת חברות", "שמירת מרות הלשכה", "שיפוט משמעתי", "גביית שכר טרחה", "חוק לשכת עורכי הדין סעיף 50"]'::jsonb, '**וריאציה 1 — פרישה מרצון:** עו"ד הודיע על פרישתו מהלשכה. האם הלשכה יכולה לדון בו על עבירה שביצע לפני הפרישה? ← כן, סעיף 50 לחוק לשכת עורכי הדין קובע שמירת מרות לגבי כל מה שאירע לפני פקיעת החברות.
**וריאציה 2 — פקיעת חברות עקב חדלות פירעון:** עו"ד שחברותו פקעה עקב צו לפתיחת הליכי חדלות פירעון. האם הוא רשאי לגבות שכר עבור שירותים שנתן לפני כן? ← כן, סעיף 50 חל גם על פקיעת חברות מסיבה זו, והוא רשאי לגבות שכר עבור שירותים שנתן לפני כן.
**וריאציה 3 — חידוש חברות:** עו"ד שחברותו פקעה מבקש לחדש אותה. האם הלשכה רשאית לסרב? ← הלשכה רשאית לסרב רק על סמך הרשעה או עובדות שאירעו אחרי פקיעת החברות (סעיף 51 לחוק לשכת עורכי הדין).', 'פקיעת חברות בלשכה ← אינה מבטלת את מרות הלשכה על מעשים שקדמו לפקיעה, ואינה גורעת מזכות עורך הדין לגבות שכר עבור שירותים שניתנו לפני כן.', '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 50", "נבו - המתמחה, אתיקה מקצועית: השיפוט המשמעתי (2026) | פרק א - מבוא", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 49. השעיית חברות", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 51. חידוש חברות"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''licensing_bar_membership'' | classifier_note: Lawyer''s bar-membership expiry — licensing consequences | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''משמעת עורכי דין'' הוא פשרה, שכן הנושא הוא דיני אתיקה מקצועית ושיפוט משמעתי, שהוא תחום נפרד מדיני סדר הדין הפלילי. יש לשקול הוספת פרק ''אתיקה מקצועית'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הוא נשאר נתון למרות הלשכה עד לסוף השנה, והוא רשאי לגבות שכר בעד שירותים שנתן לפני פקיעת החברות.', false, 'טענה זו שגויה. מרות הלשכה אינה מוגבלת בזמן קלנדרי (עד סוף השנה) אלא חלה על כל מה שאירע לפני פקיעת החברות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הוא נשאר נתון למרות הלשכה לגבי כל מה שאירע לפני פקיעת החברות, והוא רשאי לגבות שכר בעד שירותים שהתחייב לתיתם עד 3 שנים לפני פקיעת החברות.', false, 'טענה זו שגויה. הזכות לגבות שכר אינה מוגבלת ל-3 שנים לפני פקיעת החברות, אלא חלה על כל שירות שניתן לפני כן.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הוא נשאר נתון למרות הלשכה לגבי כל מה שאירע לפני פקיעת החברות, והוא רשאי לגבות שכר בעד שירותים שנתן לפני פקיעת החברות.', true, 'תשובה זו נכונה. סעיף 50 לחוק לשכת עורכי הדין קובע כי מי שחברותו פקעה נשאר נתון למרות הלשכה לגבי מעשים שקדמו לפקיעה, ורשאי לגבות שכר עבור שירותים שנתן לפני כן.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הוא נשאר נתון למרות הלשכה עד 3 שנים מפקיעת החברות, והוא רשאי לגבות שכר בעד שירותים שנתן לפני פקיעת החברות.', false, 'טענה זו שגויה. מרות הלשכה אינה מוגבלת בזמן (עד 3 שנים מפקיעת החברות) אלא חלה על כל מה שאירע לפני פקיעת החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'השעיה על תנאי ותחילת הפעלתה',
    1, 'עו"ד כהן הוטלה עליו השעיה על תנאי למשך שנה. לאחר מכן, הוא הורשע בעבירת משמעת נוספת שהפעילה את ההשעיה על תנאי. בית הדין המשמעתי לא קבע מועד אחר לתחילת ההשעיה. מתי תתחיל השעייתו של עו"ד כהן?', 'שאלה זו עוסקת במועד תחילתה של השעיה על תנאי שהופעלה, נושא חשוב בדיני המשמעת של עורכי הדין. היא בוחנת את הבנת הוראת סעיף 68ד לכללי האתיקה המקצועית.', 'סעיף 68ד לכללי האתיקה המקצועית קובע במפורש כי ''מי שהופעלה נגדו השעיה על תנאי יתחיל לשאת בעונש ביום מתן הצו המפעיל, זולת אם ציווה בית הדין המשמעתי על יום התחלה אחר''. במקרה הנדון, בית הדין המשמעתי לא קבע יום תחילת השעיה אחר, ולכן ההשעיה תתחיל ביום מתן פסק הדין המפעיל את ההשעיה על תנאי.',
    'הטעות הנפוצה היא לבלבל בין מועד הטלת ההשעיה על תנאי לבין מועד תחילת ריצוי ההשעיה בפועל, או להניח קיומם של כללי תחילת ריצוי שאינם קבועים בחוק.', '["השעיה על תנאי", "הפעלת השעיה", "תחילת ריצוי עונש", "בית דין משמעתי", "כללי האתיקה המקצועית"]'::jsonb, '**וריאציה 1 — קביעת מועד אחר:** האם בית הדין המשמעתי רשאי לקבוע מועד אחר לתחילת ההשעיה? ← כן, סעיף 68ד מאפשר לבית הדין לצוות על יום התחלה אחר.
**וריאציה 2 — השעיה על תנאי שלא הופעלה:** מה קורה להשעיה על תנאי אם לא בוצעה עבירה נוספת בתקופת התנאי? ← ההשעיה לא תופעל והעונש לא ירוצה.
**וריאציה 3 — השעיה על תנאי ומאסר:** האם השעיה על תנאי יכולה להיות מושפעת מריצוי עונש מאסר? ← השעיה על תנאי היא עונש משמעתי נפרד, אך ריצוי מאסר עשוי להשפיע על יכולת עורך הדין לעסוק במקצוע, ובכך על משמעות ההשעיה.', 'השעיה על תנאי שהופעלה ← מתחילה ביום מתן הצו המפעיל, אלא אם בית הדין קבע מועד אחר.',
    '["נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 68ד. תחילת השעיה שהופעלה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ההשעיה תתחיל ביום מתן פסק הדין המפעיל את ההשעיה על תנאי.', true, 'תשובה זו נכונה. סעיף 68ד לכללי האתיקה קובע כי מי שהופעלה נגדו השעיה על תנאי יתחיל לשאת בעונש ביום מתן הצו המפעיל, אלא אם נקבע אחרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ההשעיה תתחיל ביום ביצוע עבירת המשמעת הנוספת.', false, 'טענה זו שגויה. תחילת ההשעיה אינה נקבעת לפי מועד ביצוע העבירה, אלא לפי מועד מתן הצו המפעיל, אלא אם נקבע אחרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ההשעיה תתחיל ביום מתן פסק הדין המקורי שהטיל את ההשעיה על תנאי.', false, 'טענה זו שגויה. ההשעיה על תנאי אינה מתחילה במועד הטלתה, אלא רק במועד הפעלתה, אם וכאשר תופעל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ההשעיה תתחיל 30 יום לאחר מתן פסק הדין המפעיל, כדי לאפשר הגשת ערעור.', false, 'טענה זו שגויה. אין הוראה כזו בחוק לשכת עורכי הדין לגבי תחילת השעיה שהופעלה, אלא אם בית הדין קבע זאת במפורש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'סדר נשיאת עונשי השעיה',
    2, 'עו"ד לוי נידון לשני עונשי השעיה: השעיה של חצי שנה בגין עבירה אחת, והשעיה של שנה בגין עבירה אחרת. בית הדין המשמעתי לא קבע דבר לגבי סדר נשיאת העונשים. כיצד יישא עו"ד לוי את עונשי ההשעיה?', 'שאלה זו עוסקת בכללים לקביעת סדר נשיאת עונשי השעיה כאשר עורך דין נידון למספר עונשים כאלה. היא בוחנת את הוראות סעיף 68ה לכללי האתיקה המקצועית, הקובע את ברירת המחדל בהיעדר קביעה מפורשת של בית הדין.', 'סעיף 68ה(א) לכללי האתיקה המקצועית קובע כי ''מי שנדון במשפט אחד לעונשי השעיה בשל עבירות שונות, ולא הורה בית הדין המשמעתי שישאם, כולם או מקצתם, בזה אחר זה, לא ישא אלא את עונש ההשעיה של התקופה הארוכה ביותר''. במקרה הנדון, עו"ד לוי נידון לשני עונשי השעיה (חצי שנה ושנה) באותו משפט, ובית הדין לא קבע סדר נשיאה. לכן, הוא יישא רק את עונש ההשעיה של התקופה הארוכה ביותר, שהיא שנה אחת.',
    'הטעות הנפוצה היא להניח שכל עונשי השעיה נישאים במצטבר, או במקביל, תוך התעלמות מהכלל הספציפי הקבוע בסעיף 68ה(א) לכללי האתיקה.', '["עונשי השעיה", "סדר נשיאת עונשים", "השעיה חופפת", "בית דין משמעתי", "כללי האתיקה המקצועית"]'::jsonb, '**וריאציה 1 — השעיה על תנאי והשעיה נוספת:** עו"ד הוטלה עליו השעיה על תנאי, ולאחר מכן הורשע בעבירה נוספת והופעלה ההשעיה על תנאי. האם העונשים יצטברו? ← כן, סעיף 68ג קובע ששתי תקופות ההשעיה יישאו בזו אחר זו, אלא אם בית הדין הורה אחרת.

**וריאציה 2 — שני פסקי דין נפרדים:** עו"ד נידון להשעיה בפסק דין אחד, ולפני שריצה את כולה, נידון להשעיה נוספת בפסק דין אחר. בית הדין האחרון לא קבע סדר נשיאה. כיצד יישא את העונשים? ← הוא יישא רק את עונש ההשעיה של התקופה הארוכה ביותר, לפי סעיף 68ה(ב).
**וריאציה 3 — קביעה מפורשת של בית הדין:** האם בית הדין המשמעתי רשאי לקבוע ששני עונשי השעיה יישאו במצטבר? ← כן, סעיפים 68ג ו-68ה מאפשרים לבית הדין לצוות על נשיאה בזו אחר זו (מצטברת) מטעמים שיירשמו.', 'שני עונשי השעיה באותו משפט ללא קביעה מפורשת ← יישא רק את עונש ההשעיה הארוך ביותר.',
    '["נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 68ג. תקופת השעיה בזו אחר זו", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 68ה. השעיה חופפת"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הוא יישא את שתי תקופות ההשעיה בזו אחר זו, כלומר שנה וחצי בסך הכל.', false, 'טענה זו שגויה. כלל ברירת המחדל, בהיעדר קביעה מפורשת, הוא נשיאת העונש הארוך ביותר, ולא נשיאה מצטברת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הוא יישא רק את עונש ההשעיה של התקופה הארוכה ביותר, כלומר שנה אחת.', true, 'תשובה זו נכונה. סעיף 68ה(א) לכללי האתיקה קובע כי אם לא הורה בית הדין אחרת, יישא הנידון רק את עונש ההשעיה של התקופה הארוכה ביותר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הוא יישא את שתי תקופות ההשעיה במקביל, כלומר שנה אחת.', false, 'טענה זו שגויה. למרות שהתוצאה זהה לתשובה הנכונה, הנימוק המשפטי הוא נשיאת העונש הארוך ביותר, ולא נשיאה מקבילה של שניהם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'בית הדין המשמעתי יקבע בדיעבד את סדר נשיאת העונשים, לפי שיקול דעתו.', false, 'טענה זו שגויה. בהיעדר קביעה מפורשת, הכלל הקבוע בחוק הוא שיישא את העונש הארוך ביותר, ואין צורך בקביעה בדיעבד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'השעיית חברות בחברת עורכי דין',
    3, 'עו"ד שרה, שהיא שותפה בחברת עורכי דין, הושעתה מחברותה בלשכה למשך שנה. מהן ההשלכות המיידיות של השעיה זו על זכויותיה בחברת עורכי הדין?', 'שאלה זו בוחנת את ההשלכות הספציפיות של השעיית עורך דין מחברותו בלשכה, כאשר אותו עורך דין הוא גם חבר בחברת עורכי דין. היא מתמקדת בהוראות סעיף 59ד לכללי האתיקה המקצועית, המגבילות את זכויותיו הכלכליות והניהוליות של עורך דין מושעה בחברה.', 'סעיף 59ד(א) לכללי האתיקה המקצועית קובע כי ''חבר בחברת עורכי דין שהושעה מחברותו בלשכה לא יהיה זכאי לקבל בתקופת השעייתו כל תשלום מהחברה חוץ מתשלומים בעד שירות שנתן לפני שהושעה ולא כל חלק מרווחי החברה שהרוויחה בשעה שהיה מושעה כאמור''. בנוסף, סעיף 59ד(ב) קובע כי עורך דין מושעה ''לא יפעיל כל זכות או סמכות שיש לו כחבר בחברה או כמנהל או כפקיד החברה''. לכן, עו"ד שרה לא תהיה זכאית לתשלומים או רווחים בתקופת השעייתה, למעט שכר עבור שירותים שנתנה לפני ההשעיה, ולא תוכל להפעיל את זכויותיה וסמכויותיה בחברה.',
    'הטעות הנפוצה היא להניח שהשעיה משמעתית משפיעה רק על היכולת לעסוק במקצוע באופן כללי, ולא להבין את ההגבלות הספציפיות החלות על עורך דין מושעה שהוא חלק מחברת עורכי דין.', '["השעיית חברות", "חברת עורכי דין", "זכויות עורך דין מושעה", "כללי האתיקה המקצועית", "סעיף 59ד"]'::jsonb, '**וריאציה 1 — איסור העסקת מושעה:** האם חברת עורכי דין רשאית להעסיק עורך דין מושעה? ← לא, סעיף 59 לכללי האתיקה אוסר על עורך דין להעסיק חבר שהושעה.
**וריאציה 2 — פעולות מיוחדות לעורך דין:** האם עורך דין מושעה רשאי לבצע פעולות המיוחדות לעורך דין? ← לא, עורך דין שהושעה אינו רשאי לעשות פעולות המיוחדות לעורך דין (סעיף 49 לכללי האתיקה).
**וריאציה 3 — שמירת מרות הלשכה:** האם עורך דין מושעה נשאר נתון לשיפוטה המשמעתי של הלשכה? ← כן, עורך דין שהושעה מוסיף להיות נתון לשיפוטה המשמעתי של הלשכה (סעיף 50א לחוק לשכת עורכי הדין).', 'עו"ד מושעה בחברת עורכי דין ← לא זכאי לתשלומים או רווחים בתקופת ההשעיה (למעט שכר קודם), ולא יפעיל זכויות או סמכויות בחברה.',
    '["נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 59ד. איסור השתתפות למי שהושעה", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 49. השעיית חברות", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 50א. חבר הלשכה שהושעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'היא לא תהיה זכאית לקבל תשלום מהחברה, למעט שכר עבור שירותים שנתנה לפני ההשעיה, ולא חלק מרווחי החברה שהרוויחה בתקופת השעייתה.', true, 'תשובה זו נכונה. סעיף 59ד(א) לכללי האתיקה קובע במפורש את ההגבלות על תשלומים ורווחים לעורך דין מושעה בחברת עורכי דין, תוך חריג לשירותים שניתנו לפני ההשעיה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'היא תמשיך לקבל את חלקה ברווחי החברה, אך לא תוכל להפעיל זכויות ניהול או סמכויות כחברה בחברה.', false, 'טענה זו שגויה. סעיף 59ד(א) קובע במפורש כי עורך דין מושעה אינו זכאי לחלק מרווחי החברה שהרוויחה בתקופת השעייתו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'היא תהיה זכאית לקבל תשלום מהחברה עבור שירותים שנתנה לפני ההשעיה וגם עבור שירותים שנתנה במהלך ההשעיה, אם קיבלה אישור מיוחד לכך.', false, 'טענה זו שגויה. עורך דין מושעה אינו רשאי לתת שירותים משפטיים, ולכן לא יהיה זכאי לתשלום עבור שירותים שנתן במהלך ההשעיה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'חברותה בחברת עורכי הדין תפקע אוטומטית עם השעייתה מחברותה בלשכה.', false, 'טענה זו שגויה. השעיה מחברות בלשכה אינה גוררת פקיעה אוטומטית של חברות בחברת עורכי דין, אלא הגבלות על פעילות וזכויות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'שיפוט משמעתי לאחר פרישה',
    4, 'עו"ד דני פרש מחברותו בלשכת עורכי הדין לפני 5 שנים. כעת, הלשכה מבקשת לפתוח נגדו בהליכים משמעתיים בגין עבירה אתית שביצע לפני פרישתו. האם הלשכה מוסמכת לדון בעניינו של עו"ד דני?', 'שאלה זו עוסקת בעקרון שמירת המרות של לשכת עורכי הדין על חבריה לשעבר, כפי שנקבע בסעיף 50 לחוק לשכת עורכי הדין. היא בוחנת את סמכותה של הלשכה לדון בעבירות משמעת שבוצעו לפני פקיעת החברות.', 'סעיף 50 לחוק לשכת עורכי הדין קובע כי ''מי שפרש מן הלשכה או שחברותו פקעה מסיבה אחרת, נשאר נתון למרות הלשכה בכל מה שאירע לפני פקיעת החברות''. עקרון זה מאפשר ללשכה להמשיך ולקיים הליכים משמעתיים נגד עורך דין לשעבר בגין מעשים שביצע בעת שהיה חבר בלשכה. פסיקת בית המשפט העליון, למשל בעל"ע 2531/01 חרמון נ'' הוועד המחוזי, אישרה עקרון זה, תוך הדגשה כי מטרת דין המשמעת היא להגן על אמון הציבור במקצוע. עם זאת, על הקובל להפעיל את הליך המשמעת בתום לב ובתוך זמן סביר, ושיהוי עלול להוות טענת הגנה.',
    'הטעות הנפוצה היא לחשוב שפרישה מהלשכה מעניקה חסינות מוחלטת מפני הליכים משמעתיים בגין עבירות שבוצעו בעבר.', '["פקיעת חברות", "שמירת מרות הלשכה", "שיפוט משמעתי", "חוק לשכת עורכי הדין סעיף 50", "טענת שיהוי"]'::jsonb, '**וריאציה 1 — חידוש חברות לאחר פרישה:** עו"ד שפרש מבקש לחדש את חברותו. האם הלשכה רשאית לסרב? ← הלשכה רשאית לסרב רק על סמך הרשעה או עובדות שאירעו אחרי פקיעת החברות (סעיף 51 לחוק לשכת עורכי הדין).
**וריאציה 2 — פקיעת חברות עקב אי-תשלום דמי חבר:** עו"ד שחברותו פקעה עקב אי-תשלום דמי חבר. האם הוא נתון למרות הלשכה? ← כן, סעיף 50 חל גם על פקיעת חברות מסיבה זו.
**וריאציה 3 — שופט לשעבר:** שופט לשעבר, שחברותו בלשכה הופסקה עקב מינויו, הורשע בעבירה פלילית בתקופת כהונתו. האם הלשכה רשאית לסרב לחדש את חברותו? ← כן, הלשכה רשאית שלא לחדש את חברותו אם הורשע בעבירה פלילית או משמעת שהביאה לסיום כהונתו (סעיף 52א(ג) לחוק לשכת עורכי הדין).', 'עו"ד שפרש מהלשכה ← נשאר נתון למרותה ולשיפוטה המשמעתי לגבי מעשים שקדמו לפרישה, ורשאי לגבות שכר עבור שירותים שנתן לפני כן.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 50", "נבו - המתמחה, אתיקה מקצועית: השיפוט המשמעתי (2026) | פרק ב - השיפוט המשמעתי", "על\"ע 2531/01 חרמון נ'' הוועד המחוזי של לשכת עורכי-הדין בתל-אביב-יפו, פ\"ד נח(4) 55 (2004)", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | 52א. הפסקת חברותם של חברי הלשכה לתקופת כהונתם כשופטים, כדיינים או כרשמים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, מכיוון שחברותו בלשכה פקעה, והוא אינו נתון עוד למרותה ולשיפוטה המשמעתי של הלשכה.', false, 'טענה זו שגויה. סעיף 50 לחוק לשכת עורכי הדין קובע במפורש כי מרות הלשכה נשמרת לגבי מעשים שקדמו לפקיעת החברות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, מכיוון שמי שפרש מן הלשכה נשאר נתון למרותה ולשיפוטה המשמעתי לגבי כל מה שאירע לפני פקיעת החברות.', true, 'תשובה זו נכונה. סעיף 50 לחוק לשכת עורכי הדין קובע את עקרון שמירת המרות, המאפשר ללשכה לדון בעניינים שקדמו לפרישה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם העבירה האתית שביצע היא עבירה פלילית שיש עמה קלון.', false, 'טענה זו שגויה. שמירת המרות חלה על כל עבירה אתית שבוצעה לפני פקיעת החברות, ולא רק על עבירות פליליות שיש עמן קלון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הלשכה פתחה בהליכים נגדו תוך שנה מיום פרישתו.', false, 'טענה זו שגויה. אין בחוק הגבלת זמן כזו לפתיחת הליכים משמעתיים לאחר פרישה, אם כי שיהוי עלול להוות טענת הגנה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 8, '2019-S-S-Q08';
END
$$;

