  v_ang_0 uuid := 'd516563f-89f4-42ac-acc0-5ebb81f4bb65'::uuid;
  v_ang_1 uuid := 'f04a2ef1-1f6e-46a8-8d93-df02ca391e23'::uuid;
  v_ang_2 uuid := 'b2447f23-0e6a-4929-9b81-cef44b816b62'::uuid;
  v_ang_3 uuid := 'e49578bb-2603-45d6-91bd-fe830337b6d1'::uuid;
BEGIN
