  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q09', v_chapter_id, v_subtopic_id, 'אלון הוא עורך דין שגם מכהן כדירקטור בחברה ציבורית. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 9}'::jsonb, 'השאלה עוסקת במעמדו של עורך דין המכהן כדירקטור בחברה ציבורית, ובפרט בסמכותו להביע דעה משפטית במסגרת תפקידו זה, בהתאם לכללי האתיקה המקצועית.', 'סעיף 3 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, קובע במפורש כי ''עורך דין המכהן כדירקטור בחברה ציבורית רשאי להביע דעה בעניין משפטי במסגרת תפקידו כדירקטור''. כלל זה נועד לאפשר לדירקטור עורך הדין לתרום ממומחיותו המשפטית לדיוני הדירקטוריון, מבלי שייחשב כמי שנותן שירותים משפטיים לחברה באופן המנוגד לכללים אחרים (כגון האיסור על ייצוג או מתן ייעוץ שוטף בתשלום). הבעת דעה משפטית היא חלק אינטגרלי מתפקידו של דירקטור בעל ידע משפטי, והיא תורמת לקבלת החלטות מושכלות בדירקטוריון.', 'הטעות הנפוצה היא לחשוב שעורך דין המכהן כדירקטור אינו רשאי כלל להביע דעה משפטית, מחשש לניגוד עניינים או מתן שירותים משפטיים אסורים, תוך התעלמות מההיתר המפורש שבכללים.',
    '["עורך דין", "דירקטור", "חברה ציבורית", "דעה משפטית", "כללי אתיקה", "ניגוד עניינים"]'::jsonb, '**וריאציה 1 — ייעוץ משפטי בתשלום:** האם עורך דין-דירקטור רשאי לתת ייעוץ משפטי בתשלום לחברה? ← לא, סעיף 2 לכללים אוסר על עורך דין-דירקטור לתת שירותים משפטיים לחברה בתמורה.
**וריאציה 2 — ייצוג משפטי:** האם עורך דין-דירקטור רשאי לייצג את החברה בבית משפט? ← לא, סעיף 2 לכללים אוסר על עורך דין-דירקטור לייצג את החברה.
**וריאציה 3 — דעה משפטית בכתב:** האם עורך דין-דירקטור רשאי להביע דעה משפטית בכתב במסגרת תפקידו? ← כן, הכלל מתיר הבעת דעה משפטית במסגרת תפקידו כדירקטור, ואין הגבלה על צורת ההבעה (סעיף 3 לכללים).', 'עו"ד-דירקטור בחברה ציבורית ← רשאי להביע דעה משפטית בדירקטוריון, אך אסור לו לתת שירותים משפטיים או לייצג את החברה.', '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 3", "כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 2"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fiduciary_privilege_conflict'' | classifier_note: Lawyer concurrently serving as director — conflict of interest rules | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''משמעת עורכי דין'' הוא פשרה, שכן הנושא הוא דיני אתיקה מקצועית, שהוא תחום נפרד מדיני סדר הדין הפלילי. יש לשקול הוספת פרק ''אתיקה מקצועית'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אלון רשאי להביע דעה בעניין משפטי במסגרת תפקידו בדירקטוריון.', true, 'תשובה זו נכונה. סעיף 3 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) קובע במפורש כי עורך דין המכהן כדירקטור רשאי להביע דעה בעניין משפטי במסגרת תפקידו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אסור לאלון להביע את דעתו בעניין משפטי במסגרת תפקידו בדירקטוריון.', false, 'טענה זו שגויה. הכללים מתירים במפורש לעורך דין-דירקטור להביע דעה משפטית במסגרת תפקידו, וזאת בניגוד לאיסור על מתן שירותים משפטיים או ייצוג.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אלון רשאי להביע דעה בעניין משפטי במסגרת תפקידו בדירקטוריון, כל עוד הוא גם מייצג משפטית את החברה.', false, 'טענה זו שגויה. עורך דין המכהן כדירקטור בחברה ציבורית אינו רשאי לייצג את החברה משפטית, גם אם הוא מביע דעה משפטית בדירקטוריון.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אסור לאלון להביע את דעתו בעניין משפטי במסגרת תפקידו בדירקטוריון אלא במסגרת ייצוגו המשפטי את החברה.', false, 'טענה זו שגויה. עורך דין המכהן כדירקטור בחברה ציבורית אינו רשאי לייצג את החברה משפטית כלל, והבעת דעה משפטית מותרת גם ללא ייצוג.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ייצוג משפטי של החברה על ידי הדירקטור',
    1, 'עו"ד דנה מכהנת כדירקטורית בחברה ציבורית. החברה נתבעה בבית משפט, ודנה מציעה לייצג את החברה בהליך המשפטי. מה הדין?', 'שאלה זו בוחנת את האיסור על עורך דין המכהן כדירקטור בחברה ציבורית לתת שירותים משפטיים לחברה, ובפרט לייצגה בבית משפט, בהתאם לכללי האתיקה המקצועית.', 'סעיף 2 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, קובע במפורש כי ''עורך דין המכהן כדירקטור בחברה ציבורית לא ייתן לחברה שירותים משפטיים, בין בתמורה ובין שלא בתמורה, ולא ייצג אותה בבית משפט או בפני רשות אחרת''. איסור זה נועד למנוע ניגוד עניינים פוטנציאלי ולשמור על עצמאותו המקצועית של עורך הדין, שכן תפקיד הדירקטור מחייב נאמנות לחברה כולה, בעוד ייצוג משפטי מחייב נאמנות ללקוח הספציפי.',
    'הטעות הנפוצה היא לחשוב שעורך דין-דירקטור רשאי לייצג את החברה אם זה ללא תמורה או אם זה לטובת החברה, תוך התעלמות מהאיסור המוחלט שבכללים.', '["עורך דין", "דירקטור", "חברה ציבורית", "ייצוג משפטי", "שירותים משפטיים", "כללי אתיקה", "ניגוד עניינים"]'::jsonb, '**וריאציה 1 — ייעוץ משפטי שוטף:** האם עורך דין-דירקטור רשאי לתת ייעוץ משפטי שוטף לחברה? ← לא, זה נחשב למתן שירותים משפטיים האסורים לפי סעיף 2 לכללים.
**וריאציה 2 — מזכיר חברה:** האם עורך דין-דירקטור רשאי לכהן גם כמזכיר החברה? ← לא, סעיף 4 לכללים אוסר על עורך דין-דירקטור לכהן כמזכיר החברה.
**וריאציה 3 — חברה פרטית:** האם האיסור על ייצוג חל גם על עורך דין-דירקטור בחברה פרטית? ← הכללים מתייחסים במפורש לחברה ציבורית. לגבי חברה פרטית, האיסור אינו מפורש בכללים אלה, אך עשוי לעלות שאלת ניגוד עניינים כללית מכוח כללי האתיקה הכלליים.', 'עו"ד-דירקטור בחברה ציבורית ← אסור לו לתת שירותים משפטיים או לייצג את החברה, בין בתמורה ובין שלא בתמורה.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 2", "כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 4"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'דנה רשאית לייצג את החברה, שכן היא בעלת ידע משפטי רלוונטי וזה יחסוך לחברה הוצאות.', false, 'טענה זו שגויה. סעיף 2 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) אוסר על עורך דין-דירקטור לייצג את החברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'דנה אינה רשאית לייצג את החברה, שכן עורך דין המכהן כדירקטור בחברה ציבורית אינו רשאי לתת לה שירותים משפטיים.', true, 'תשובה זו נכונה. סעיף 2 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) קובע איסור גורף על עורך דין-דירקטור לתת שירותים משפטיים לחברה, לרבות ייצוג בבית משפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'דנה רשאית לייצג את החברה, אך רק אם הייצוג ניתן ללא תמורה.', false, 'טענה זו שגויה. האיסור על מתן שירותים משפטיים וייצוג הוא מוחלט, בין בתמורה ובין שלא בתמורה, כאמור בסעיף 2 לכללים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'דנה אינה רשאית לייצג את החברה, אלא אם כן קיבלה אישור מיוחד מלשכת עורכי הדין.', false, 'טענה זו שגויה. אין היתר כזה בכללים, והאיסור הוא גורף ונועד למנוע ניגוד עניינים פוטנציאלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת ''חברה ציבורית'' לעניין הכללים',
    2, 'עו"ד יוסי מכהן כדירקטור בחברה פרטית, שאינה נסחרת בבורסה, אך יש לה 50 בעלי מניות. האם הכללים החלים על דירקטורים בחברה ציבורית חלים עליו?', 'שאלה זו בוחנת את הגדרת ''חברה ציבורית'' לעניין כללי האתיקה החלים על עורכי דין המכהנים כדירקטורים, ומדגישה את ההבחנה בין חברה ציבורית לפרטית בהקשר זה.', 'סעיף 1 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, מגדיר ''חברה ציבורית'' כ''חברה ציבורית כמשמעותה בחוק ניירות ערך, תשכ"ח-1968''. חוק ניירות ערך מגדיר חברה ציבורית כחברה שניירות הערך שלה הוצעו לציבור על פי תשקיף והם נסחרים בבורסה. חברה פרטית, גם אם יש לה מספר רב של בעלי מניות, אינה נחשבת לחברה ציבורית לעניין זה אם ניירות הערך שלה אינם נסחרים בבורסה. לכן, הכללים הספציפיים לדירקטורים בחברה ציבורית אינם חלים על עו"ד יוסי.',
    'הטעות הנפוצה היא לבלבל בין חברה פרטית בעלת מספר רב של בעלי מניות לבין חברה ציבורית כהגדרתה בחוק ניירות ערך, אשר דורשת מסחר בבורסה.', '["חברה ציבורית", "חברה פרטית", "חוק ניירות ערך", "דירקטור", "כללי אתיקה", "הגדרות בחוק"]'::jsonb, '**וריאציה 1 — חברה ממשלתית:** האם חברה ממשלתית נחשבת לחברה ציבורית לעניין הכללים? ← לא, חברה ממשלתית אינה בהכרח חברה ציבורית כהגדרתה בחוק ניירות ערך, אלא אם ניירות הערך שלה נסחרים בבורסה.
**וריאציה 2 — חברה בת של ציבורית:** האם חברה בת של חברה ציבורית נחשבת לציבורית לעניין הכללים? ← לא, רק החברה האם שהיא ציבורית כהגדרתה בחוק ניירות ערך, אלא אם כן גם ניירות הערך של החברה הבת נסחרים בבורסה.
**וריאציה 3 — תכלית ההגדרה:** מדוע הכללים מגבילים את עצמם לחברה ציבורית? ← בשל הרגישות הציבורית הגבוהה יותר, חובות הדיווח והשקיפות, והחשש לניגוד עניינים מורכב יותר בחברות אלו.', 'הכללים לדירקטורים-עורכי דין ← חלים רק על ''חברה ציבורית'' כהגדרתה בחוק ניירות ערך (נסחרת בבורסה).',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 1", "חוק ניירות ערך, תשכ\"ח-1968"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, מכיוון שלחברה יש מספר רב של בעלי מניות, היא נחשבת לציבורית לעניין הכללים.', false, 'טענה זו שגויה. הגדרת ''חברה ציבורית'' לעניין הכללים היא ספציפית ומתייחסת לחברה ציבורית כהגדרתה בחוק ניירות ערך, ולא למספר בעלי המניות בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, מכיוון שהכללים חלים רק על חברה ציבורית כהגדרתה בחוק ניירות ערך, והחברה אינה נסחרת בבורסה.', true, 'תשובה זו נכונה. סעיף 1 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) מפנה להגדרת ''חברה ציבורית'' בחוק ניירות ערך, הדורשת בין היתר מסחר בבורסה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אם החברה מפרסמת דוחות כספיים לציבור באופן וולונטרי.', false, 'טענה זו שגויה. פרסום דוחות כספיים וולונטרי אינו הופך חברה פרטית לציבורית כהגדרתה בחוק ניירות ערך ולעניין הכללים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן יוסי הוא גם בעל שליטה בחברה, שאז חלים עליו כללי אתיקה מחמירים יותר.', false, 'טענה זו שגויה. מעמד יוסי כבעל שליטה אינו משנה את הגדרת החברה לעניין הכללים הספציפיים לדירקטורים בחברה ציבורית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הבעת דעה משפטית בדירקטוריון חברה פרטית',
    3, 'עו"ד מיכל מכהנת כדירקטורית בחברה פרטית. במהלך ישיבת דירקטוריון, היא מתבקשת להביע את דעתה בעניין משפטי הנוגע לפעילות החברה. האם מיכל רשאית להביע דעה זו?', 'שאלה זו בוחנת את תחולת כללי האתיקה הספציפיים לדירקטורים בחברה ציבורית על עורכי דין המכהנים כדירקטורים בחברה פרטית, ובפרט את סוגיית הבעת דעה משפטית.', 'כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, חלים במפורש על ''חברה ציבורית'' כהגדרתה בחוק ניירות ערך. הכללים אינם אוסרים על עורך דין המכהן כדירקטור בחברה פרטית להביע דעה בעניין משפטי במסגרת תפקידו. למעשה, סעיף 3 לכללים מתיר זאת במפורש אף בחברה ציבורית. כל עוד הבעת הדעה היא במסגרת תפקידו כדירקטור ואינה מהווה מתן שירותים משפטיים לחברה (כגון ייצוג או ייעוץ שוטף בתשלום), ואינה יוצרת ניגוד עניינים כללי לפי כללי האתיקה הרחבים יותר, היא מותרת.',
    'הטעות הנפוצה היא להרחיב את תחולת הכללים הספציפיים לחברה ציבורית גם לחברה פרטית, או לבלבל בין הבעת דעה משפטית לבין מתן שירותים משפטיים אסורים.', '["חברה פרטית", "חברה ציבורית", "דירקטור", "הבעת דעה משפטית", "כללי אתיקה", "תחולת כללים"]'::jsonb, '**וריאציה 1 — מתן שירותים משפטיים בחברה פרטית:** האם עו"ד-דירקטור בחברה פרטית רשאי לתת שירותים משפטיים לחברה? ← הכללים הספציפיים אינם אוסרים זאת, אך יש לבחון את כללי האתיקה הכלליים לגבי ניגוד עניינים וטוהר המקצוע.
**וריאציה 2 — ייצוג משפטי בחברה פרטית:** האם עו"ד-דירקטור בחברה פרטית רשאי לייצג את החברה בבית משפט? ← הכללים הספציפיים אינם אוסרים זאת, אך הדבר עלול ליצור ניגוד עניינים חמור ולפגוע בטוהר המקצוע, ולכן לרוב לא יתאפשר.
**וריאציה 3 — תפקיד דירקטור בחברה פרטית:** מהי התכלית של עו"ד המכהן כדירקטור בחברה פרטית? ← לתרום ממומחיותו המשפטית לדיוני הדירקטוריון ולקבל החלטות עסקיות מושכלות, תוך שמירה על כללי האתיקה הכלליים.', 'עו"ד-דירקטור בחברה פרטית ← רשאי להביע דעה משפטית במסגרת תפקידו, שכן הכללים הספציפיים חלים רק על חברות ציבוריות.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 3", "כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שהכללים הספציפיים לדירקטורים בחברה ציבורית אינם חלים על חברה פרטית, ואין איסור כללי על הבעת דעה משפטית.', true, 'תשובה זו נכונה. הכללים הספציפיים (סעיפים 2-4) חלים רק על חברה ציבורית. בהיעדר איסור מפורש, עורך דין-דירקטור בחברה פרטית רשאי להביע דעה משפטית, כל עוד אין בכך מתן שירותים משפטיים או ניגוד עניינים כללי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שגם בחברה פרטית, עורך דין המכהן כדירקטור אינו רשאי להביע דעה משפטית כדי למנוע ניגוד עניינים.', false, 'טענה זו שגויה. האיסור המפורש על הבעת דעה משפטית אינו קיים בחברה פרטית, והכללים מתירים זאת בחברה ציבורית, קל וחומר בחברה פרטית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם היא אינה מקבלת תמורה נוספת עבור הבעת הדעה המשפטית.', false, 'טענה זו שגויה. הבעת דעה משפטית במסגרת תפקיד דירקטור אינה נחשבת למתן שירות משפטי הדורש תמורה נפרדת, והיא חלק מתפקידו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן קיבלה אישור מיוחד מלשכת עורכי הדין להביע דעה משפטית בחברה פרטית.', false, 'טענה זו שגויה. אין דרישה לאישור מיוחד להבעת דעה משפטית במסגרת תפקיד דירקטור בחברה פרטית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הגבלות נוספות על עורך דין המכהן כדירקטור',
    4, 'עו"ד נועה מכהנת כדירקטורית בחברה ציבורית. אילו תפקידים נוספים אסור לה לכהן בהם בחברה זו, על פי כללי האתיקה?', 'שאלה זו עוסקת בהגבלות נוספות המוטלות על עורך דין המכהן כדירקטור בחברה ציבורית, מעבר לאיסור על מתן שירותים משפטיים. היא בוחנת את הוראות סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית).', 'סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ"ט-1988, קובע כי ''עורך דין המכהן כדירקטור בחברה ציבורית לא יכהן באותה חברה כמזכיר החברה, כמבקר פנים, כיועץ משפטי פנימי או בכל תפקיד אחר המקנה לו מעמד של עובד החברה''. איסור זה נועד להבטיח את עצמאותו של הדירקטור עורך הדין ולמנוע מצב של כפיפות ניהולית או תלות בחברה, שעלולה לפגוע בשיקול דעתו כדירקטור ובאתיקה המקצועית שלו.',
    'הטעות הנפוצה היא לחשוב שההגבלות מסתכמות באיסור על מתן שירותים משפטיים, תוך התעלמות מהאיסור על כהונה בתפקידים ניהוליים מסוימים בחברה.', '["עורך דין", "דירקטור", "חברה ציבורית", "הגבלות אתיות", "מזכיר חברה", "מבקר פנים", "יועץ משפטי פנימי", "כללי אתיקה"]'::jsonb, '**וריאציה 1 — תפקיד ''אחר'' המקנה מעמד עובד:** האם עורך דין-דירקטור רשאי לכהן כסמנכ"ל שיווק בחברה? ← לא, תפקיד זה מקנה מעמד של עובד החברה, ולכן אסור לפי סעיף 4 לכללים.
**וריאציה 2 — דירקטור חיצוני:** האם ההגבלות חלות גם על דירקטור חיצוני שהוא עורך דין? ← כן, הכללים חלים על כל עורך דין המכהן כדירקטור בחברה ציבורית, ללא הבחנה בין סוגי הדירקטורים.
**וריאציה 3 — תכלית האיסור:** מדוע אסור לעורך דין-דירקטור לכהן בתפקידים אלו? ← כדי למנוע ניגוד עניינים, לשמור על עצמאותו של הדירקטור, ולהבטיח שיוכל למלא את תפקידו הפיקוחי ללא משוא פנים.', 'עו"ד-דירקטור בחברה ציבורית ← אסור לכהן גם כמזכיר חברה, מבקר פנים, יועץ משפטי פנימי או כל תפקיד עובד אחר בחברה.',
    '["כללי לשכת עורכי הדין (דירקטורים בחברה ציבורית), תשמ\"ט-1988, סעיף 4"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'מזכיר החברה, מבקר פנים, או יועץ משפטי פנימי של החברה.', true, 'תשובה זו נכונה. סעיף 4 לכללי לשכת עורכי הדין (דירקטורים בחברה ציבורית) אוסר על עורך דין-דירקטור לכהן בתפקידים אלו בחברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'יושב ראש הדירקטוריון, חבר ועדת ביקורת, או חבר ועדת תגמול.', false, 'טענה זו שגויה. הכללים אינם אוסרים על עורך דין-דירקטור לכהן בתפקידים אלו, שהם חלק מתפקידי הדירקטוריון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כל תפקיד ניהולי בחברה, למעט תפקיד דירקטור.', false, 'טענה זו שגויה. הכללים מפרטים תפקידים ספציפיים האסורים, ולא כל תפקיד ניהולי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כל תפקיד המקנה לה שכר נוסף מעבר לשכר הדירקטורים.', false, 'טענה זו שגויה. האיסור אינו על קבלת שכר נוסף כשלעצמו, אלא על כהונה בתפקידים ספציפיים המנויים בכללים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 9, '2019-S-S-Q09';
END
$$;

