-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '28ac0a56-b3d5-453a-b144-d5388988b214'::uuid;
  v_group_id uuid := 'f12d3f01-29d9-4aca-99f1-57139c83ed86'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '9ec8595d-eb9e-4e61-9422-2bcddebc2a12'::uuid;
  v_ang_1 uuid := 'de7d50b5-a691-44f9-a63a-4212bb0976b3'::uuid;
  v_ang_2 uuid := '08632f13-587b-493c-8aa8-e3a4a9186814'::uuid;
  v_ang_3 uuid := '6c400425-2f03-4106-a3cd-200f90a3ff3b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q10';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 10, '2019-S-S-Q10';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'damages_assessment' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'damages_assessment', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q10', v_chapter_id, v_subtopic_id, 'בשנת 2015 נפצע נח בתאונה. בעקבות תביעת נזקי גוף שהגיש קיבל נח פיצוי כולל בסך 500,000 ש"ח מחברת הביטוח של המזיק. בשנת 2017 הוכרז נח פושט רגל, לאחר שהוגשו נגדו תביעות חוב בסך כולל של 750,000 ש"ח. הנאמן שמונה לטפל בנכסיו של נח מבקש להעביר את הפיצוי לקופת פשיטת הרגל, לצורך חלוקה בין הנושים. האם הוא רשאי לעשות כן?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 10}'::jsonb, 'השאלה עוסקת בהלכה שנקבעה בע"א 10217/16 ב.ת.ב. נ'' ג''ינר (הלכת ג''ינר), אשר שינתה את הלכת ידידיה. הלכת ג''ינר קבעה כי פיצויים בגין אובדן כושר השתכרות של פושט רגל מוקנים לנאמן וייכנסו לקופת הכינוס, בעוד שאר רכיבי הפיצוי האישיים נשארים בידי פושט הרגל.', 'הלכת ג''ינר (ע"א 10217/16) קבעה כי המושג ''נכס'' בדיני הנזיקין כולל אף את כושר ההשתכרות של הניזוק. לפיכך, פיצויים בגין פגיעה בכושר ההשתכרות של פושט רגל יוקנו לנאמן ויופקדו בקופת פשיטת הרגל. זאת, בניגוד להלכת ידידיה שקבעה כי פיצויים בגין נזקי גוף אינם מהווים ''נכס'' ואינם מוקנים לנאמן. בית המשפט הדגיש כי רכיבי פיצוי עבור נזק בלתי ממוני, פגיעה באוטונומיה, עזרת צד ג'' והוצאות רפואיות בעבר ובעתיד, נחשבים ל''זכויות אישיות'' של פושט הרגל ויישארו בידיו. (ע"א 10217/16, פסקאות 40, 55; דנ"א 1996/19 קוגן, מיני-רציו). הלכה זו חלה גם כאשר הפיצוי התקבל לפני הכרזת פשיטת הרגל, וגם כאשר הפיצוי ניתן באופן גלובלי או בפשרה, כאשר במקרים אלו בית המשפט יחלץ את רכיב אובדן כושר ההשתכרות. (ע"א 10217/16, פסקאות 43-44).', 'בלבול בין הלכת ידידיה הישנה לבין הלכת ג''ינר החדשה, או אי-הבחנה בין ראשי הנזק השונים לעניין הקנייתם לנאמן.',
    '["פושט רגל", "נאמן", "פיצויים בגין נזקי גוף", "אובדן כושר השתכרות", "קופת כינוס", "הלכת ג''ינר", "הלכת ידידיה", "סעיף 21(1) לפקודת הנזיקין"]'::jsonb, '**וריאציה 1 — פיצוי על כאב וסבל:** נח קיבל פיצוי רק על כאב וסבל. האם הנאמן רשאי להעבירם לקופה? ← לא, פיצוי על כאב וסבל נחשב לזכות אישית ואינו מוקנה לנאמן (ע"א 10217/16 ג''ינר).
**וריאציה 2 — תביעה לפני פשיטת רגל:** נח הגיש את התביעה וקיבל את הפיצוי לפני שהוכרז פושט רגל. האם הנאמן רשאי לדרוש את הפיצוי? ← כן, הלכת ג''ינר חלה גם על פיצויים שהתקבלו לפני הכרזת פשיטת הרגל, ככל שהם נוגעים לאובדן כושר השתכרות (ע"א 10217/16 ג''ינר).
**וריאציה 3 — פיצוי גלובלי:** נח קיבל פיצוי גלובלי ללא פירוט ראשי נזק. האם הנאמן יכול לדרוש את חלקו? ← כן, בית המשפט יחלץ את רכיב אובדן כושר ההשתכרות מתוך הפיצוי הגלובלי (ע"א 10217/16 ג''ינר, פסקאות 43-44).', 'הלכת ג''ינר ← פיצוי על אובדן כושר השתכרות של פושט רגל מוקנה לנאמן; פיצויים אישיים (כאב וסבל, הוצאות רפואיות) נשארים בידי החייב.', '["ע\"א 10217/16 ב.ת.ב - בניני תעשיה באר-שבע בע\"מ נ'' רפאל ג''ינר (17.01.2019)", "דנ\"א 1996/19 בני קוגן נ'' ב.ת.ב - בנייני תעשיה באר-שבע בע\"מ (11.01.2021)", "נבו - המתמחה, דיני נזיקין (2026) | פקודת הנזיקין [נוסח חדש] | (+) הסבר לסייג", "פקודת הנזיקין [נוסח חדש], סעיף 21(1)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''חדלות פירעון ובוררות'' subtopic=''פתיחת הליכים'' → mapped chapter=''torts'' subtopic=''damages_assessment'' | classifier_note: Trustee in bankruptcy claiming tort compensation paid pre-bankruptcy — straddles torts (damages) and insolvency. Insolvency is in the procedural track; closest substantive home is torts/damages_assessment | source_review_note: הסיווג תחת ''חדלות פירעון ובוררות'' ו''פתיחת הליכים'' הוא פשרה, שכן הנושא נוגע גם לדיני נזיקין. יש לשקול הוספת תת-נושא ''נכסי חייב'' או ''פיצויים בחדלות פירעון'' לרשימת תתי-הנושאים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הנאמן יכול להעביר לקופת פשיטת הרגל רק את הפיצוי היחסי בגין אובדן כושר השתכרותו של נח.', true, 'תשובה זו נכונה. הלכת ג''ינר קבעה כי פיצויים בגין אובדן כושר השתכרות מוקנים לנאמן, בעוד שאר רכיבי הפיצוי האישיים נשארים בידי פושט הרגל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הנאמן יכול להעביר לקופת פשיטת הרגל את מלוא סכום הפיצוי, שכן חובותיו של נח לנושים עולים על גובה הפיצוי כולו.', false, 'טענה זו שגויה. הלכת ג''ינר מבחינה בין רכיבי הפיצוי השונים, ואינה מאפשרת העברת מלוא הפיצוי לקופת הכינוס, גם אם חובות החייב גבוהים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הנאמן אינו רשאי להעביר את הפיצוי לקופת פשיטת הרגל משום שהפיצוי שקיבל נח היה פיצוי כולל עבור כל רכיבי הנזק, שאינו ניתן להפרדה.', false, 'טענה זו שגויה. הלכת ג''ינר קבעה קווים מנחים לחילוץ רכיב אובדן כושר ההשתכרות גם מפיצוי גלובלי או פשרה, כך שניתן להפריד את הרכיבים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הנאמן אינו רשאי להעביר את הפיצוי לקופת פשיטת הרגל משום שהאירוע הנזיקי התרחש לפני המועד שבו הוכרז נח פושט רגל.', false, 'טענה זו שגויה. הלכת ג''ינר חלה גם על פיצויים שהתקבלו לפני הכרזת פשיטת הרגל, ככל שהם נוגעים לאובדן כושר השתכרות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פיצויים בגין כאב וסבל של פושט רגל',
    1, 'יוסי, פושט רגל, נפגע בתאונת דרכים וקיבל פיצוי בסך 100,000 ש"ח בגין כאב וסבל בלבד. הנאמן מבקש להעביר את הסכום לקופת הכינוס. האם הנאמן רשאי לעשות כן?', 'שאלה זו בוחנת את ההבחנה בין רכיבי פיצוי שונים בתביעת נזקי גוף של פושט רגל, ומידת הקנייתם לקופת הכינוס, בהתאם להלכת ג''ינר.', 'הלכת ג''ינר (ע"א 10217/16) קבעה כי רכיבי פיצוי בגין ''זכויותיו האישיות'' של פושט הרגל, שאינן מהוות ''נכס'', ייוותרו בידיו ולא ייכנסו לקופת הכינוס. רכיבים אלו כוללים נזק בלתי ממוני, פגיעה באוטונומיה, עזרת צד ג'' והוצאות רפואיות. פיצוי בגין כאב וסבל נכלל בקטגוריית הנזק הבלתי ממוני, ולכן אינו מוקנה לנאמן. (ע"א 10217/16, פסקאות 40, 55; דנ"א 1996/19 קוגן, מיני-רציו).',
    'אי-הבחנה בין רכיבי נזק ''ממוניים'' ל''אישיים'' לעניין הקנייתם לנאמן.', '["פושט רגל", "נאמן", "פיצויים בגין כאב וסבל", "נזק בלתי ממוני", "קופת כינוס", "הלכת ג''ינר"]'::jsonb, '**וריאציה 1 — פיצוי על הוצאות רפואיות:** פושט רגל קיבל פיצוי על הוצאות רפואיות. האם הנאמן רשאי להעבירם לקופה? ← לא, הוצאות רפואיות נחשבות לזכות אישית ואינן מוקנות לנאמן (ע"א 10217/16 ג''ינר, פסקה 40).
**וריאציה 2 — פיצוי על עזרת צד ג'':** פושט רגל קיבל פיצוי על עזרת צד ג''. האם הנאמן רשאי להעבירם לקופה? ← לא, עזרת צד ג'' נחשבת לזכות אישית ואינה מוקנית לנאמן (ע"א 10217/16 ג''ינר, פסקה 40).
**וריאציה 3 — פיצוי על נזק לרכוש:** פושט רגל קיבל פיצוי על נזק לרכושו. האם הנאמן רשאי להעבירם לקופה? ← כן, נזק לרכוש הוא נזק ממון לנכסים ומוקנה לנאמן (ע"א 10217/16 ג''ינר, פסקה 57; דנ"א 1996/19 קוגן, פסקה 3 לדעת השופט אלרון).', 'פיצויים אישיים (כאב וסבל, הוצאות רפואיות, עזרת צד ג'') ← נשארים בידי פושט הרגל ואינם מוקנים לנאמן.',
    '["ע\"א 10217/16 ב.ת.ב - בניני תעשיה באר-שבע בע\"מ נ'' רפאל ג''ינר (17.01.2019)", "דנ\"א 1996/19 בני קוגן נ'' ב.ת.ב - בנייני תעשיה באר-שבע בע\"מ (11.01.2021)", "נבו - המתמחה, דיני נזיקין (2026) | פקודת הנזיקין [נוסח חדש] | (+) הסבר לסייג"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שכל פיצוי המתקבל על ידי פושט רגל מוקנה לקופת הכינוס.', false, 'טענה זו שגויה. הלכת ג''ינר מבחינה בין רכיבי פיצוי שונים, ואינה קובעת כי כל פיצוי מוקנה לקופת הכינוס.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שפיצוי בגין כאב וסבל נחשב לזכות אישית של פושט הרגל ואינו מוקנה לנאמן.', true, 'תשובה זו נכונה. הלכת ג''ינר קבעה כי פיצויים בגין נזק בלתי ממוני, כגון כאב וסבל, נשארים בידי פושט הרגל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוסי לא זקוק לסכום זה למחייתו הבסיסית.', false, 'טענה זו שגויה. הצורך למחייה רלוונטי רק לרכיבים המוקנים לנאמן, ולא לרכיבים שאינם מוקנים לו מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן בית המשפט של חדלות פירעון יורה במפורש על העברתם.', false, 'טענה זו שגויה. בית המשפט אינו יכול להורות על העברת רכיבים שאינם מוקנים לנאמן על פי דין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'זכות התביעה מול פירות התביעה',
    2, 'ראובן, פושט רגל, נפגע בתאונה ונגרם לו אובדן כושר השתכרות. הנאמן מבקש להגיש בשמו תביעה נזיקית נגד המזיק. האם הנאמן רשאי לנהל את התביעה הנזיקית בגין אובדן כושר השתכרות?', 'שאלה זו בוחנת את ההבחנה בין זכות התביעה לבין פירות התביעה בתביעת נזקי גוף של פושט רגל, ובפרט מי מוסמך לנהל את התביעה הנזיקית בגין אובדן כושר השתכרות, בהתאם להלכת ג''ינר והדיון הנוסף שבעקבותיה.', 'הלכת ג''ינר (ע"א 10217/16) קבעה בדעת רוב כי הזכות להגיש תביעה בגין עוולה שגרמה נזק לכושר השתכרותו של פושט רגל (ולזכות בפירותיה) מוקנית לנאמן. אולם, בדיון הנוסף (דנ"א 1996/19 קוגן), הובהר בדעת רוב כי הגם שזכות התביעה עבור רכיב אובדן כושר השתכרות מוקנית לנאמן, אין משמעות הדבר בהכרח כי הנאמן ינהל את התביעה הנזיקית או יהפוך לבעל דין מן המניין. ככלל, הניזוק-פושט הרגל אמור לקבל את אישור בית המשפט כדי להגיש או להמשיך בתביעת נזיקין. רק במקרה חריג, מקום בו הניזוק-פושט הרגל מסרב בחוסר תום לב להגיש תביעת נזיקין, יהיה הנאמן רשאי לבוא בנעליו ולהגיש תביעה בשמו, והכל בכפוף לאישור בית המשפט של חדלות פירעון. (דנ"א 1996/19 קוגן, פסקאות 17, 18 לדעת השופט עמית; ע"א 10217/16, פסקה 40).',
    'הטעות הנפוצה היא להסיק מהקניית פירות התביעה לנאמן כי גם זכות התביעה עצמה עוברת אליו, תוך התעלמות מההבחנה שנקבעה בדיון הנוסף.', '["פושט רגל", "נאמן", "זכות תביעה", "פירות תביעה", "אובדן כושר השתכרות", "הלכת ג''ינר", "דנ\"א קוגן"]'::jsonb, '**וריאציה 1 — סירוב בחוסר תום לב:** ראובן מסרב להגיש את התביעה בחוסר תום לב. האם הנאמן רשאי להגיש אותה? ← כן, זהו חריג לכלל, בכפוף לאישור בית המשפט של חדלות פירעון (דנ"א 1996/19 קוגן, פסקה 17).
**וריאציה 2 — פיקוח הנאמן:** אם פושט הרגל מנהל את התביעה, מה תפקידו של הנאמן? ← הנאמן יפקח על ההליך, ועורך הדין של פושט הרגל יצטרך ליידע אותו על הליכי התביעה (דנ"א 1996/19 קוגן, פסקה 17).
**וריאציה 3 — תביעה על נזק לרכוש בלבד:** אם העוולה גרמה רק נזק ממון לנכסי פושט הרגל (ללא נזקים אישיים), מי מנהל את התביעה? ← במקרה כזה, זכות התביעה עוברת לנאמן (דנ"א 1996/19 קוגן, פסקה 3 לדעת השופט אלרון).', 'זכות התביעה הנזיקית של פושט רגל ← נשארת בידיו, אך פירות התביעה בגין אובדן כושר השתכרות מוקנים לנאמן (למעט חריג של חוסר תום לב).',
    '["ע\"א 10217/16 ב.ת.ב - בניני תעשיה באר-שבע בע\"מ נ'' רפאל ג''ינר (17.01.2019)", "דנ\"א 1996/19 בני קוגן נ'' ב.ת.ב - בנייני תעשיה באר-שבע בע\"מ (11.01.2021)", "נבו - המתמחה, דיני נזיקין (2026) | פקודת הנזיקין [נוסח חדש] | (+) הסבר לסייג"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, מכיוון שהזכות להגיש תביעה בגין אובדן כושר השתכרות מוקנית לנאמן.', false, 'טענה זו שגויה. דעת הרוב בדיון הנוסף קבעה כי זכות התביעה עצמה נשארת בידי פושט הרגל, למעט חריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, הזכות להגיש ולנהל את התביעה נשארת בידי פושט הרגל, והנאמן זכאי רק לפירות התביעה בגין אובדן כושר השתכרות.', true, 'תשובה זו נכונה. דעת הרוב בדיון הנוסף (דנ"א 1996/19 קוגן) קבעה כי יש להבחין בין זכות התביעה (שנשארת בידי החייב) לבין פירות התביעה (המוקנים לנאמן).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם פושט הרגל מסרב בחוסר תום לב להגיש את התביעה בעצמו.', false, 'טענה זו שגויה חלקית. זהו חריג לכלל, אך הכלל הוא שהזכות לנהל את התביעה נשארת בידי פושט הרגל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, מכיוון שהתביעה הנזיקית היא זכות אישית של פושט הרגל ואינה קשורה להליכי חדלות פירעון.', false, 'טענה זו שגויה. אמנם התביעה היא אישית, אך פירותיה בגין אובדן כושר השתכרות מוקנים לנאמן, ולכן יש קשר להליכי חדלות פירעון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חילוץ רכיב הפיצוי מתוך פשרה גלובלית',
    3, 'שמעון, פושט רגל, נפגע בתאונה וקיבל פיצוי גלובלי בסך 300,000 ש"ח במסגרת הסכם פשרה, ללא פירוט ראשי הנזק. הנאמן מבקש לקבוע את חלקו בקופת הכינוס. כיצד יקבע בית המשפט של חדלות פירעון את הסכום שיועבר לנאמן?', 'שאלה זו עוסקת בקווים המנחים שנקבעו בהלכת ג''ינר לחילוץ רכיב הפיצוי בגין אובדן כושר השתכרות מתוך פיצוי גלובלי או הסכם פשרה, במקרים בהם פושט רגל מקבל פיצויים בגין נזקי גוף.', 'הלכת ג''ינר (ע"א 10217/16) התייחסה למקרים בהם תביעת פיצויים בגין נזקי גוף מסתיימת בפשרה או בפסק דין גלובלי, ללא פירוט ראשי הנזק. במקרים אלו, בית המשפט קבע כי יש לשאוף מלכתחילה שפסק הדין הנזיקי יכלול הערכה מפורשת של רכיבי הפיצוי בגין הפסדי השתכרות. אם פסק הדין הנזיקי לא יכלול הערכה כזו, או אם ההליך הסתיים טרם כניסת הניזוק להליך חדלות הפירעון, על בית המשפט הדן בתיק חדלות הפירעון ''לחלץ'' מתוך סכום הפיצוי הכולל את סכום הפיצוי המשקף את גובה הפסדי ההשתכרות, תוך התחשבות בסכום הכולל ובפרמטרים הרלוונטיים. (ע"א 10217/16, פסקאות 43-44; דנ"א 1996/19 קוגן, פסקה 18 לדעת השופט עמית).',
    'הטעות הנפוצה היא לחשוב שפיצוי גלובלי אינו ניתן לחלוקה, או שאין מנגנון משפטי לקביעת חלקו של הנאמן במקרים כאלה.', '["פושט רגל", "נאמן", "פיצוי גלובלי", "הסכם פשרה", "אובדן כושר השתכרות", "קווים מנחים", "הלכת ג''ינר"]'::jsonb, '**וריאציה 1 — פירוט בסיס השכר:** מה צריך לכלול פסק דין נזיקי במקרה של פושט רגל? ← יש לציין את בסיס השכר ושיעור הגריעה מהשכר שהיוו בסיס לסכום הפיצוי שנפסק, כדי שניתן יהיה לחלץ את הסכום הרלוונטי (ע"א 10217/16 ג''ינר, פסקה 44).
**וריאציה 2 — תקופת הפיצוי:** לאיזו תקופה יועבר רכיב הפיצוי בגין הפסדי השתכרות לנאמן? ← לתקופת הליך חדלות הפירעון (דנ"א 1996/19 קוגן, פסקה 18 לדעת השופט עמית).
**וריאציה 3 — העברה חד פעמית:** כיצד תתבצע העברת הסכומים לקופת הכינוס? ← באופן חד פעמי ולא מדי חודש, כדי לא לפגוע באופן היוון הפיצוי (ע"א 10217/16 ג''ינר, פסקה 40).', 'פיצוי גלובלי לפושט רגל ← בית המשפט יחלץ את רכיב אובדן כושר ההשתכרות לפי קווים מנחים, ויועבר לנאמן.',
    '["ע\"א 10217/16 ב.ת.ב - בניני תעשיה באר-שבע בע\"מ נ'' רפאל ג''ינר (17.01.2019)", "דנ\"א 1996/19 בני קוגן נ'' ב.ת.ב - בנייני תעשיה באר-שבע בע\"מ (11.01.2021)", "חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 4(ג)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 79א"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'בית המשפט יחלץ את רכיב הפיצוי בגין הפסדי השתכרות בעבר ואובדן כושר השתכרות לעתיד, תוך התחשבות בסכום הכולל ובפרמטרים רלוונטיים.', true, 'תשובה זו נכונה. הלכת ג''ינר קבעה קווים מנחים לחילוץ רכיב אובדן כושר השתכרות מפיצוי גלובלי או פשרה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הנאמן אינו יכול לדרוש חלק מהפיצוי, מכיוון שלא ניתן להפריד את רכיבי הנזק מתוך פיצוי גלובלי.', false, 'טענה זו שגויה. הלכת ג''ינר קבעה מנגנון לחילוץ רכיב אובדן כושר השתכרות גם מפיצוי גלובלי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הפיצוי כולו יישאר בידי שמעון, שכן הסכם פשרה אינו נחשב לפסק דין לעניין הקניית פיצויים לנאמן.', false, 'טענה זו שגויה. הלכת ג''ינר חלה גם על פיצויים שניתנו בפשרה, ואינה מבחינה בין פסק דין לפשרה לעניין זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הנאמן יקבל 50% מהפיצוי הגלובלי, כברירת מחדל במקרים של פיצוי ללא פירוט.', false, 'טענה זו שגויה. אין כלל כזה הקובע חלוקה של 50% כברירת מחדל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'שיקול דעת בית המשפט בהעברת פיצויים',
    4, 'אבי, פושט רגל, קיבל פיצוי בגין אובדן כושר השתכרות בסך 200,000 ש"ח. הנאמן מבקש להעביר את מלוא הסכום לקופת הכינוס. אבי טוען כי הוא זקוק לחלק מהסכום לצורך מחייתו ומחיית תלויים בו. האם בית המשפט של חדלות פירעון רשאי להותיר חלק מהפיצוי בידי אבי?', 'שאלה זו עוסקת בשיקול הדעת של בית המשפט של חדלות פירעון להותיר חלק מפיצויי אובדן כושר השתכרות בידי פושט רגל, למרות שהם מוקנים לנאמן, וזאת לצורך מחייתו ומחיית תלויים בו, בהתאם להלכת ג''ינר.', 'הלכת ג''ינר (ע"א 10217/16) קבעה כי אף כאשר סכום מסוים מתוך הפיצוי הנזיקי הכולל הוגדר כפיצוי בגין אובדן כושר השתכרות, הוא לא יועבר לידי הנאמן אלא יישאר בידי פושט הרגל, וזאת מקום שייקבע כי סכום זה דרוש לפושט הרגל לצורך הוצאות מחייתו, מחיית התלויים בו, או לצורך הוצאותיו הרפואיות שנגרמו כתוצאה מהאירוע הנזיקי. בית המשפט של חדלות פירעון צריך לעשות שימוש מושכל בסמכות זו, בדומה לסמכותו לפי סעיף 111(א) לפקודת פשיטת הרגל, המאפשרת לו להורות על העברת הכנסותיו של פושט הרגל לנאמן, אך מותירה בידיו את שיקול הדעת להותיר חלק מההכנסות בידי פושט הרגל לצורך מחייתו ומחיית התלויים בו בכבוד. (ע"א 10217/16, פסקה 15 לדעת השופט אלרון, פסקה 37 לדעת השופטת וילנר).',
    'הטעות הנפוצה היא לחשוב שהקניית הפיצוי לנאמן היא מוחלטת ואינה מאפשרת לבית המשפט להתחשב בצרכי החייב.', '["פושט רגל", "נאמן", "אובדן כושר השתכרות", "שיקול דעת בית המשפט", "צרכי מחייה", "הוצאות רפואיות", "פקודת פשיטת הרגל סעיף 111(א)", "הלכת ג''ינר"]'::jsonb, '**וריאציה 1 — תכלית הסמכות:** מהי תכלית הסמכות של בית המשפט להותיר כספים בידי פושט הרגל? ← להגן על פושט הרגל מפני פגיעה קשה ביכולתו להתקיים ולכלכל את משפחתו בכבוד (ע"א 10217/16 ג''ינר, פסקה 15 לדעת השופט אלרון).
**וריאציה 2 — סכום הפיצוי:** האם בית המשפט יכול להותיר בידי פושט הרגל סכום העולה על צרכי מחייתו הבסיסיים? ← לא, הסמכות מוגבלת לסכומים הדרושים למחייה בכבוד ולהוצאות רפואיות (ע"א 10217/16 ג''ינר, פסקה 15 לדעת השופט אלרון).
**וריאציה 3 — השפעה על ההפטר:** האם גובה הפיצוי שייפסק לזכות החייב בראש הנזק של אובדן כושר השתכרות יכול להשפיע על מועד ההפטר? ← כן, מועד ההפטר יושפע גם מגובה הפיצוי שייפסק לזכות החייב בראש נזק זה (ע"א 10217/16 ג''ינר, פסקה 12 לדעת השופט אלרון).', 'בית המשפט של חדלות פירעון ← רשאי להותיר חלק מפיצויי אובדן כושר השתכרות בידי פושט הרגל לצורך מחייתו, מחיית תלויים בו או הוצאות רפואיות.',
    '["ע\"א 10217/16 ב.ת.ב - בניני תעשיה באר-שבע בע\"מ נ'' רפאל ג''ינר (17.01.2019)", "פקודת פשיטת הרגל [נוסח חדש], תש\"ם-1980, סעיף 111(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, מכיוון שפיצוי בגין אובדן כושר השתכרות מוקנה במלואו לנאמן, ואין לבית המשפט שיקול דעת בעניין.', false, 'טענה זו שגויה. לבית המשפט של חדלות פירעון יש שיקול דעת להתחשב בצרכי המחייה של החייב ותלויים בו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט רשאי להותיר חלק מהסכום בידי אבי, אם יקבע כי סכום זה דרוש לו לצורך מחייתו, מחיית תלויים בו, או הוצאות רפואיות שנגרמו מהאירוע הנזיקי.', true, 'תשובה זו נכונה. הלכת ג''ינר קבעה כי בית המשפט רשאי להפעיל שיקול דעת זה, בדומה לסמכותו לפי סעיף 111(א) לפקודת פשיטת הרגל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם אבי יוכיח כי ללא סכום זה הוא יגיע לפת לחם.', false, 'טענה זו שגויה. הסטנדרט הוא ''מחייה בכבוד'' ולא ''פת לחם'', וכולל גם הוצאות רפואיות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הנאמן הסכים לכך מראש.', false, 'טענה זו שגויה. שיקול הדעת נתון לבית המשפט, ולא תלוי בהסכמת הנאמן.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 10, '2019-S-S-Q10';
END
$$;

