DO $$
DECLARE
  v_sq_id uuid := 'e46b74e9-8c4c-4825-b461-9a8b157a4269'::uuid;
  v_group_id uuid := 'c6eed758-ed73-4f0c-838f-6e6ed2cd46ee'::uuid;
