  v_ang_0 uuid := '406008a6-9462-4b19-a161-1c62215ff3ee'::uuid;
  v_ang_1 uuid := '47415b03-6a42-4175-8dff-48321652dfe7'::uuid;
  v_ang_2 uuid := '32606bc3-bb82-4e0a-bac2-d28099bb3e94'::uuid;
  v_ang_3 uuid := '591c652b-1894-45ca-ba09-3625303e1462'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q11';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 11, '2019-S-S-Q11';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
