  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q11', v_chapter_id, v_subtopic_id, 'נועה היא עורכת דין יחידה בשני משרדי עורכי דין אשר בבעלותה הבלעדית. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 11}'::jsonb, 'השאלה עוסקת בהוראת כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, המגבילה את מספר המשרדים שעורך דין רשאי לקיים. הכלל נועד להבטיח נוכחות קבועה של עורך דין בכל משרד ולמנוע ניהול משרדים ללא פיקוח מקצועי נאות.', 'כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע במפורש כי ''עורך דין לא יקיים יותר ממשרד אחד, אלא אם כן בכל משרד נמצא עורך דין שמקום עבודתו הקבוע הוא באותו משרד''. תכלית הכלל היא למנוע מצב של משרדים ''רפאים'' המנוהלים על ידי פקידות או ללא נוכחות עורך דין קבוע, ובכך להבטיח שירות מקצועי הולם ושמירה על כבוד המקצוע. במקרה הנדון, נועה היא עורכת דין יחידה בשני משרדים, ולכן היא מפרה את הכלל. קיימת אפשרות לקבל היתר חריג מהוועד המרכזי בהתייעצות עם הוועד המחוזי מטעמים מיוחדים (כלל 5(ב)), אך שאלה זו אינה מתארת קבלת היתר כזה.', 'הטעות הנפוצה היא לחשוב שבעלות בלעדית על המשרדים או היותה עורכת דין יחידה פוטרת אותה מהדרישה לנוכחות עורך דין קבוע בכל משרד, או לבלבל בין הגופים המוסמכים לתת היתר חריג.',
    '["ריבוי משרדים", "כללי אתיקה", "עורך דין יחיד", "נוכחות קבועה", "כלל 5(א)", "כבוד המקצוע"]'::jsonb, '**וריאציה 1 — משרד ללא עורך דין קבוע:** מה הסכנה במשרד ללא עורך דין קבוע? ← סכנה לטיפול לקוי, חוסר פיקוח, ופגיעה באמון הציבור במקצוע (בד"א 159/01, פסקה 7).
**וריאציה 2 — היתר חריג:** האם ניתן לקבל היתר לקיים שני משרדים ללא עורך דין קבוע בכל אחד? ← כן, הוועד המרכזי בהתייעצות עם הוועד המחוזי רשאי להתיר זאת מטעמים מיוחדים (כלל 5(ב)).
**וריאציה 3 — אחריות עורך הדין:** האם עורך דין אחראי גם על משרד שאינו נוכח בו באופן קבוע? ← כן, עורך הדין נושא באחריות מלאה להתנהלות המשרד ולמעשים הנעשים תחת שמו (בד"א 159/01, פסקה 3).', 'עו"ד יחיד בשני משרדים ← עבירה על כלל 5(א) לכללי האתיקה, אלא אם ניתן היתר מיוחד מהוועד המרכזי בהתייעצות עם המחוזי.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 5", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | פרק ג'' - משרד עורך הדין", "(ועדת משמעת לשכת עוה\"ד ארצי) 159/01 הועד המחוזי של לשכת עורכי הדין בתל אביב יפו נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב יפו (08.05.2003)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''licensing_bar_membership'' | classifier_note: Sole-practitioner lawyer with two practices — bar-membership/practice-structure rules | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''משמעת עורכי דין'' הוא פשרה, שכן הנושא הוא דיני אתיקה מקצועית, שהוא תחום נפרד מדיני סדר הדין הפלילי. יש לשקול הוספת פרק ''אתיקה מקצועית'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'נועה לא עברה על כללי האתיקה של לשכת עורכי הדין, אם אישר זאת הוועד המחוזי של הלשכה לתקופה קצובה.', false, 'טענה זו שגויה. הוועד המחוזי אינו הגוף המוסמך לאשר חריגה מכלל 5(א), וגם אם היה, ההיתר אינו אוטומטי אלא מותנה בנסיבות מיוחדות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'נועה לא עברה על כללי האתיקה של לשכת עורכי הדין, אם אישר זאת הוועד המרכזי של הלשכה בהתייעצות עם ראש לשכת עורכי הדין.', false, 'טענה זו שגויה. הוועד המרכזי אכן מוסמך לאשר חריגה, אך ההתייעצות היא עם הוועד המחוזי ולא עם ראש הלשכה, וזאת מטעמים מיוחדים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'נועה לא עברה על כללי האתיקה של לשכת עורכי הדין, אם אישר זאת ראש לשכת עורכי הדין בהתייעצות עם הוועד המרכזי, מטעמים מיוחדים שיירשמו.', false, 'טענה זו שגויה. ראש לשכת עורכי הדין אינו הגוף המוסמך לאשר חריגה מכלל 5(א), אלא הוועד המרכזי בהתייעצות עם הוועד המחוזי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'נועה עברה על כללי האתיקה של לשכת עורכי הדין.', true, 'תשובה זו נכונה. כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי עורך דין לא יקיים יותר ממשרד אחד, אלא אם כן בכל משרד נמצא עורך דין שמקום עבודתו הקבוע הוא באותו משרד. נועה, כעורכת דין יחידה בשני משרדים, מפרה כלל זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'משרד עורכי דין בבית מגורים',
    1, 'עו"ד דני מקיים משרד עורכי דין בביתו הפרטי, ובנוסף משרד נוסף בעיר אחרת. דני הוא עורך הדין היחיד בשני המשרדים. מה הדין?', 'שאלה זו בוחנת את תחולת כלל 5(א) לכללי האתיקה המקצועית על עורך דין המקיים משרד בביתו בנוסף למשרד נוסף. היא מדגישה כי גם משרד ביתי נחשב למשרד לכל דבר לעניין כלל זה.', 'כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי ''עורך דין לא יקיים יותר ממשרד אחד, אלא אם כן בכל משרד נמצא עורך דין שמקום עבודתו הקבוע הוא באותו משרד''. כלל 4(ב)(2) אמנם מתיר לייחד חלק מדירת מגורים למשרד, אך אין בכך כדי לפטור את עורך הדין מהוראות כלל 5(א) אם הוא מקיים משרד נוסף. במקרה זה, דני מקיים שני משרדים (אחד בביתו ואחד בעיר אחרת) והוא עורך הדין היחיד בשניהם, ולכן הוא מפר את כלל 5(א).',
    'הטעות הנפוצה היא לחשוב שמשרד ביתי אינו נחשב למשרד ''אמיתי'' לעניין כללי ריבוי המשרדים, או לבלבל בין ההיתר לייחד חלק מדירת מגורים למשרד לבין הדרישה לנוכחות עורך דין קבוע במשרד נוסף.', '["ריבוי משרדים", "משרד ביתי", "כללי אתיקה", "עורך דין יחיד", "כלל 5(א)", "כלל 4(ב)(2)"]'::jsonb, '**וריאציה 1 — משרד יחיד בבית:** האם עורך דין רשאי לקיים משרד יחיד בביתו? ← כן, כלל 4(ב)(2) מתיר לייחד חלק מדירת מגורים למשרד, וכלל 5(א) אינו נכנס לתמונה אם זהו המשרד היחיד.
**וריאציה 2 — משרד בבית עם עורך דין נוסף:** האם עורך דין רשאי לקיים משרד בביתו ומשרד נוסף בעיר אחרת, כאשר במשרד השני עובד עורך דין אחר באופן קבוע? ← כן, במקרה כזה מתקיימים תנאי כלל 5(א).

**וריאציה 3 — תכלית האיסור:** מדוע קיים איסור על ריבוי משרדים ללא עורך דין קבוע בכל אחד? ← כדי להבטיח פיקוח מקצועי נאות, זמינות ללקוחות, ולמנוע מצב של משרדים ''רפאים'' המנוהלים על ידי לא-עורכי דין (בד"א 159/01, פסקה 7).', 'משרד בבית + משרד נוסף ללא עו"ד קבוע בכל אחד ← עבירה על כלל 5(א), גם אם המשרד הביתי מותר כשלעצמו.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 5", "כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 4", "(ועדת משמעת לשכת עוה\"ד ארצי) 159/01 הועד המחוזי של לשכת עורכי הדין בתל אביב יפו נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב יפו (08.05.2003)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'דני לא עבר על כללי האתיקה, שכן משרד בבית מגורים אינו נחשב למשרד נוסף לעניין כלל 5(א).', false, 'טענה זו שגויה. גם משרד הממוקם בדירת מגורים נחשב למשרד לכל דבר לעניין כלל 5(א), ואינו פוטר את עורך הדין מהדרישה לנוכחות עורך דין קבוע בכל משרד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'דני עבר על כללי האתיקה, שכן גם משרד בבית מגורים נחשב למשרד נוסף לעניין כלל 5(א), ואין בו עורך דין קבוע מלבד דני.', true, 'תשובה זו נכונה. כלל 5(א) חל גם על משרד הממוקם בדירת מגורים. אם דני הוא עורך הדין היחיד בשני המשרדים, הוא מפר את הכלל המחייב נוכחות עורך דין קבוע בכל משרד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'דני לא עבר על כללי האתיקה, שכן כלל 4(ב)(2) מתיר לייחד חלק מדירת מגורים למשרד.', false, 'טענה זו שגויה. כלל 4(ב)(2) מתיר לייחד חלק מדירת מגורים למשרד, אך אינו פוטר את עורך הדין מהוראות כלל 5(א) לגבי ריבוי משרדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'דני עבר על כללי האתיקה, אך רק אם המשרד בביתו אינו עומד בתנאים ההולמים את כבוד המקצוע.', false, 'טענה זו שגויה. ההפרה נובעת מריבוי משרדים ללא עורך דין קבוע בכל אחד, ולא מתנאי המשרד בבית, אם כי גם תנאים שאינם הולמים את כבוד המקצוע יכולים להוות עבירה נפרדת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תכלית כלל 5(א) לכללי האתיקה',
    2, 'מהי התכלית העיקרית של כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), המגביל את מספר המשרדים שעורך דין רשאי לקיים?', 'שאלה זו מתמקדת בתכלית החקיקתית של כלל 5(א) לכללי האתיקה המקצועית, כפי שהיא מפורשת בפסיקה ובספרות המשפטית. היא בוחנת את ההבנה העמוקה של הרציונל מאחורי ההגבלה על ריבוי משרדים.', 'הספרות המשפטית והפסיקה מבהירות כי תכליתו של כלל 5(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) היא למנוע קיומם של סניפים המנוהלים על ידי פקידות, כאשר עורך הדין בעל המשרד מזדמן לאותו משרד לעיתים רחוקות. דרך עבודה זו נחשבת לסילוף של הרעיונות המונחים ביסוד ייחוד פעולות מסוימות לעורכי דין, ופוגעת ברמה המקצועית ובכבוד המקצוע. המטרה היא להבטיח נוכחות קבועה של עורך דין בכל משרד, כדי להבטיח שירות ברמה נאותה ופיקוח מקצועי. (בד"א 159/01, פסקה 7; קלינג, אתיקה בעריכת-דין, עמ'' 47).',
    'הטעות הנפוצה היא לייחס לכלל תכליות כלכליות או אדמיניסטרטיביות, במקום אתיקה מקצועית ושמירה על רמת השירות.', '["תכלית חקיקה", "כלל 5(א)", "אתיקה מקצועית", "כבוד המקצוע", "פיקוח מקצועי", "ניהול משרד"]'::jsonb, '**וריאציה 1 — משרד ללא עורך דין קבוע:** מה הסכנה במשרד ללא עורך דין קבוע? ← סכנה לטיפול לקוי, חוסר פיקוח, ופגיעה באמון הציבור במקצוע (בד"א 159/01, פסקה 7).

**וריאציה 2 — פרשנות תכליתית:** האם ניתן לפרש את כלל 5(א) באופן רחב כדי לכלול כל מקרה בו מתנהל משרד ללא עורך דין קבוע? ← בית הדין הארצי ציין כי ניסוחו של הכלל מחייב קיומם של שני משרדים לפחות, ומסכל פרשנות רחבה מדי (בד"א 159/01, פסקה 7).
**וריאציה 3 — תיקון הכלל:** האם יש קריאה לתיקון הכלל? ← כן, הוצע שמחוקק המשנה יתקן את נוסח הסעיף באופן שיתאים לתכליתו החקיקתית, מבלי להכביד בתנאים עובדתיים לא הכרחיים (בד"א 159/01, פסקה 8).', 'תכלית כלל 5(א) ← הבטחת נוכחות עו"ד קבוע בכל משרד, למניעת ניהול לא מקצועי ופגיעה בכבוד המקצוע.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 5", "(ועדת משמעת לשכת עוה\"ד ארצי) 159/01 הועד המחוזי של לשכת עורכי הדין בתל אביב יפו נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב יפו (08.05.2003)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למנוע תחרות בלתי הוגנת בין עורכי דין על ידי הגבלת מספר המשרדים.', false, 'טענה זו שגויה. תכלית הכלל אינה הגבלת תחרות, אלא הבטחת רמה מקצועית נאותה ושמירה על כבוד המקצוע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'להבטיח נוכחות קבועה של עורך דין בכל משרד ולמנוע ניהול משרדים ללא פיקוח מקצועי נאות.', true, 'תשובה זו נכונה. תכלית הכלל היא למנוע מצב בו משרדים מנוהלים על ידי פקידות או ללא נוכחות עורך דין קבוע, ובכך להבטיח שירות מקצועי הולם ושמירה על כבוד המקצוע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'למנוע מעורכי דין להשתמט מתשלום דמי חבר ללשכה עבור כל משרד.', false, 'טענה זו שגויה. תשלום דמי חבר אינו קשור למספר המשרדים, אלא לחברות בלשכה, ואינו תכלית הכלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'להקל על הפיקוח של לשכת עורכי הדין על משרדי עורכי הדין.', false, 'טענה זו שגויה. למרות שהכלל עשוי להקל על הפיקוח, זו אינה תכליתו העיקרית, אלא תוצאה נלווית של הבטחת רמה מקצועית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'היתר מיוחד לריבוי משרדים',
    3, 'עו"ד רותם מבקשת לקיים שני משרדי עורכי דין, כאשר היא עורכת הדין היחידה בשניהם, מטעמים מיוחדים הקשורים לנגישות לציבור באזור מרוחק. מי הגוף המוסמך לאשר חריגה כזו מכלל 5(א) לכללי האתיקה?', 'שאלה זו בוחנת את ההיתר החריג לקיים יותר ממשרד אחד ללא עורך דין קבוע בכל משרד, ואת הגוף המוסמך להעניק היתר כזה, בהתאם לכלל 5(ב) לכללי האתיקה המקצועית.', 'כלל 5(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי ''הועד המרכזי בהתייעצות עם הועד המחוזי שבתחום סמכותו נמצא משרדו של עורך הדין, רשאי להתיר מטעמים מיוחדים חריגה מהוראת סעיף קטן (א), בתנאים ולתקופה שימצא לנכון''. למרות שהוועד המרכזי בוטל ברפורמה בחוק לשכת עורכי הדין ורוב סמכויותיו הועברו למועצה הארצית, כללי האתיקה לא תוקנו בהתאם, ולכן הכלל עדיין מתייחס לוועד המרכזי. (אתיקה מקצועית - כללי האתיקה, פרק ג'' - משרד עורך הדין, סעיף 5, הערת מערכת).',
    'הטעות הנפוצה היא לבלבל בין הגופים השונים בלשכה או להניח שהכללים עודכנו בהתאם לשינויים בחוק לשכת עורכי הדין.', '["היתר חריג", "ריבוי משרדים", "כלל 5(ב)", "וועד מרכזי", "וועד מחוזי", "טעמים מיוחדים"]'::jsonb, '**וריאציה 1 — תנאי ההיתר:** מהם התנאים למתן היתר חריג? ← ההיתר יינתן מטעמים מיוחדים, בתנאים ולתקופה שימצא לנכון הוועד המרכזי (כלל 5(ב)).
**וריאציה 2 — ביטול הוועד המרכזי:** מה המשמעות של ביטול הוועד המרכזי על סמכות זו? ← למרות הביטול, הכלל עדיין מתייחס לוועד המרכזי, ויש צורך בתיקון הכללים כדי להבהיר את הגוף המוסמך (אתיקה מקצועית - כללי האתיקה, פרק ג'' - משרד עורך הדין, סעיף 5, הערת מערכת).
**וריאציה 3 — דוגמא ל''טעמים מיוחדים'':** מה יכול להיחשב כ''טעמים מיוחדים''? ← צורך ציבורי מיוחד, כגון מתן שירותים משפטיים באזור מרוחק שאין בו עורכי דין אחרים, או נסיבות אישיות חריגות של עורך הדין, כל עוד נשמרת רמת השירות המקצועי.', 'היתר לריבוי משרדים ללא עו"ד קבוע בכל אחד ← ניתן על ידי הוועד המרכזי (בהתייעצות עם המחוזי) מטעמים מיוחדים.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 5", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | פרק ג'' - משרד עורך הדין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הוועד המחוזי של לשכת עורכי הדין, בהתייעצות עם הוועד המרכזי.', false, 'טענה זו שגויה. הוועד המרכזי הוא הגוף המוסמך לאשר, בהתייעצות עם הוועד המחוזי, ולא להיפך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'המועצה הארצית של לשכת עורכי הדין, בהתייעצות עם הוועד המחוזי.', false, 'טענה זו שגויה. למרות שהמועצה הארצית החליפה את הוועד המרכזי בסמכויות רבות, כלל 5(ב) עדיין מתייחס לוועד המרכזי, ואין הוראה מפורשת המעבירה סמכות זו למועצה הארצית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הוועד המרכזי של לשכת עורכי הדין, בהתייעצות עם הוועד המחוזי שבתחום סמכותו נמצא משרדו של עורך הדין.', true, 'תשובה זו נכונה. כלל 5(ב) קובע במפורש כי הוועד המרכזי, בהתייעצות עם הוועד המחוזי, רשאי להתיר חריגה מהוראת סעיף קטן (א) מטעמים מיוחדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בית הדין המשמעתי הארצי של לשכת עורכי הדין, לאחר שמיעת טיעוני הצדדים.', false, 'טענה זו שגויה. בית הדין המשמעתי עוסק באכיפת הכללים ושיפוט עבירות, ולא במתן היתרים מראש לחריגה מהם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'איסור שותפות עם מי שאינו עורך דין',
    4, 'עו"ד אלי מקיים משרד עורכי דין אחד. הוא התקשר בהסכם עם מר יוסי, שאינו עורך דין, לפיו יוסי ינהל את הקשר עם לקוחות מסוימים ויקבל אחוזים משכר הטרחה. אלי אינו נוכח במשרד באופן קבוע. מה הדין?', 'שאלה זו בוחנת שילוב של שתי עבירות אתיות נפוצות: איסור שותפות עם מי שאינו עורך דין (סעיף 58 לחוק לשכת עורכי הדין) והפרת כלל 5(א) לכללי האתיקה המקצועית, הנוגע לנוכחות עורך דין קבוע במשרד.', 'סעיף 58 לחוק לשכת עורכי הדין קובע כי ''עורך דין לא יעסוק במקצועו בשותפות עם אדם שאינו עורך דין''. הסכם לפיו אדם שאינו עורך דין מנהל קשר עם לקוחות ומקבל אחוזים משכר הטרחה, נחשב לשותפות אסורה. בנוסף, אם אלי אינו נוכח במשרד באופן קבוע, הוא מפר גם את כלל 5(א) לכללי האתיקה, המחייב נוכחות עורך דין קבוע במשרד. הפסיקה רואה בחומרה רבה מקרים של שיתוף פעולה עם מי שאינו עורך דין, במיוחד כאשר הדבר מוביל להפקרת המשרד לניהולו של גורם חיצוני (בד"א 159/01, פסקאות 2-3).',
    'הטעות הנפוצה היא להתמקד רק באחת העבירות האתיות (שותפות או ריבוי משרדים) ולא לזהות את השילוב של שתיהן, או לבלבל בין העסקת עובד לבין שותפות אסורה.', '["שותפות אסורה", "סעיף 58 לחוק לשכת עורכי הדין", "כלל 5(א)", "נוכחות קבועה", "אתיקה מקצועית", "ניהול משרד"]'::jsonb, '**וריאציה 1 — אחריות עורך הדין:** האם עורך הדין אחראי למעשיו של מי שאינו עורך דין במשרדו? ← כן, עורך הדין נושא באחריות מלאה להתנהלות המשרד ולמעשים הנעשים תחת שמו (בד"א 159/01, פסקה 3).
**וריאציה 2 — הוכחת שותפות:** כיצד מוכיחים שותפות אסורה? ← לא נדרש הסכם שותפות פורמלי, אלא די בהוכחת אלמנטים המציינים שותפות או שיתוף בעסקים, כגון חלוקת רווחים, ניהול משותף וכדומה (בד"א 159/01, פסקה 10).
**וריאציה 3 — עבירת סל:** האם התנהלות כזו יכולה להיחשב גם כ''מעשה שאינו הולם את מקצוע עריכת הדין''? ← כן, הפרת כללים אלו נחשבת גם כהתנהגות שאינה הולמת את מקצוע עריכת הדין לפי סעיף 61(3) לחוק לשכת עורכי הדין (בד"מ (ועדת משמעת לשכת עוה"ד חיפה) 42/00, פסקה 16).', 'שותפות עם לא-עורך דין + היעדר נוכחות קבועה ← עבירה על סעיף 58 לחוק לשכת עורכי הדין ועל כלל 5(א) לכללי האתיקה.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 58", "כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 5", "(ועדת משמעת לשכת עוה\"ד ארצי) 159/01 הועד המחוזי של לשכת עורכי הדין בתל אביב יפו נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב יפו (08.05.2003)", "בד\"מ (ועדת משמעת לשכת עוה\"ד חיפה) 42/00 לשכת עורכי-הדין - הוועד המחוזי חיפה והצפון נ'' מר פלוני (28.02.2001)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'אלי עבר על כללי האתיקה, שכן מדובר בשותפות אסורה עם מי שאינו עורך דין, וכן על כלל 5(א) עקב היעדר נוכחות קבועה.', true, 'תשובה זו נכונה. המקרה מתאר שתי עבירות אתיות: שותפות אסורה עם מי שאינו עורך דין לפי סעיף 58 לחוק לשכת עורכי הדין, והפרה של כלל 5(א) עקב היעדר נוכחות קבועה של עורך דין במשרד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'אלי לא עבר על כללי האתיקה, שכן הוא מקיים רק משרד אחד, ויוסי אינו שותף רשמי במשרד.', false, 'טענה זו שגויה. גם אם יוסי אינו שותף רשמי, הסכם לקבלת אחוזים משכר טרחה וניהול קשר עם לקוחות יכול להיחשב כשותפות אסורה. בנוסף, היעדר נוכחות קבועה של אלי במשרד מפר את כלל 5(א).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'אלי עבר על כללי האתיקה רק אם יוסי נתן שירותים משפטיים בפועל ללקוחות.', false, 'טענה זו שגויה. עצם ההתקשרות בהסכם שותפות עם מי שאינו עורך דין, וכן היעדר נוכחות קבועה של עורך דין במשרד, מהוות עבירות אתיות גם ללא מתן שירותים משפטיים בפועל על ידי יוסי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'אלי לא עבר על כללי האתיקה, שכן הוא רשאי להעסיק עובדים שאינם עורכי דין במשרדו.', false, 'טענה זו שגויה. העסקת עובדים מותרת, אך לא באופן המהווה שותפות אסורה או ניהול משרד ללא פיקוח מקצועי נאות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 11, '2019-S-S-Q11';
END
$$;

