  v_ang_0 uuid := '77c8b68b-dda0-4db5-9997-91ef26d5e662'::uuid;
  v_ang_1 uuid := '03028e8f-8cb4-4d0f-b97a-464034392adb'::uuid;
  v_ang_2 uuid := '8ecc1c69-75ee-4658-9b0d-18064825a0b5'::uuid;
  v_ang_3 uuid := '7120a3dc-5f26-4a2e-bef1-4bf009c3ee45'::uuid;
BEGIN
