  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q12', v_chapter_id, v_subtopic_id, 'עליזה פנתה אל עו"ד שגיא על מנת שיגיש תביעת יחסי עבודה (שלא בסעד זמני) נגד מעסיקה הקודם, משרד עורכי דין. עו"ד שגיא שיגר למשרד עורכי הדין מכתב התראה בדבר כוונתו להגיש תביעה כנגדם אשר קבלתו אושרה בשיחת טלפון, ולאחר שבוע הגיש עו"ד שגיא תביעה בשם עליזה לבית הדין האזורי לעבודה בחיפה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 12}'::jsonb, 'השאלה עוסקת בהוראת כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, המחייבת עורך דין לפנות בכתב לעורך דין אחר לפני פתיחת הליך משפטי נגדו, במטרה לנסות ליישב את הסכסוך בדרכי שלום, ובלבד שפנייה זו לא תגרום נזק ללקוח. השאלה בוחנת את היעדר תקופת המתנה קבועה בכלל זה.', 'כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי ''בטרם יפתח עורך דין בשם לקוחו בהליך משפטי נגד עורך דין אחר, יפנה אל אותו עורך דין בכתב, ואם קיימת אפשרות - אף בעל פה, כדי לנסות וליישב את הסכסוך בדרכי שלום, ובלבד שפניה כאמור לא תגרום נזק ללקוח''. הכלל דורש פנייה בכתב וניסיון ליישב את הסכסוך, אך אינו קובע תקופת המתנה מינימלית קבועה (כגון 14, 21 או 30 ימים) בין מועד הפנייה למועד הגשת התביעה. במקרה הנדון, עו"ד שגיא שיגר מכתב התראה וקיבל אישור קבלה, ובכך עמד בדרישת הכלל. העובדה שהגיש את התביעה לאחר שבוע אינה מהווה הפרה של הכלל, שכן לא נקבעה תקופת המתנה מחייבת. הפסיקה אף הדגישה כי כלל 31 פועל במישור האתי בלבד ואינו גורע מזכויות התובעים (ע"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו"ד משה גולדברג, פסקה 12.2).', 'הטעות הנפוצה היא להניח קיומה של תקופת המתנה קבועה (כגון 14, 21 או 30 ימים) בין הפנייה לעורך הדין הנתבע לבין הגשת התביעה, בעוד שהכלל עצמו אינו קובע תקופה כזו.',
    '["כלל 31", "אתיקה מקצועית", "פנייה לעורך דין", "הליך משפטי", "יישוב סכסוכים", "תקופת המתנה"]'::jsonb, '**וריאציה 1 — תביעה בסעד זמני:** האם כלל 31 חל אם התביעה כוללת בקשה לסעד זמני? ← לא, אם הפנייה עלולה לגרום נזק ללקוח, הכלל אינו חל (סעיף 31 לכללים).
**וריאציה 2 — פנייה בעל פה בלבד:** האם פנייה בעל פה בלבד מספיקה? ← לא, הכלל דורש פנייה בכתב, ופנייה בעל פה היא אפשרות נוספת (סעיף 31 לכללים).
**וריאציה 3 — השלכות הפרה:** מהן ההשלכות אם עו"ד מפר את כלל 31? ← עו"ד עלול לעמוד לדין משמעתי, אך הדבר אינו גורע מזכויותיו המהותיות של לקוחו (ע"ב 5157/06 אלתר שטול, פסקה 12.2).', 'כלל 31 ← דורש פנייה בכתב לעו"ד אחר לפני תביעה (לא בסעד זמני) וניסיון ליישב סכסוך, אך אינו קובע תקופת המתנה קבועה.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "ע\"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו\"ד משה גולדברג (10.12.2006)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer-to-lawyer demand letter procedure (notice + service to opposing firm before filing) | source_review_note: הסיווג תחת ''סדר דין פלילי'' ו''משמעת עורכי דין'' הוא פשרה, שכן הנושא הוא דיני אתיקה מקצועית, שהוא תחום נפרד מדיני סדר הדין הפלילי. יש לשקול הוספת פרק ''אתיקה מקצועית'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד שגיא הפר את כללי האתיקה של לשכת עורכי הדין בכך שלא המתין 14 ימים לפחות ממועד הפנייה למשרד עורכי הדין עד למועד הגשת התביעה.', false, 'טענה זו שגויה. כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) אינו קובע תקופת המתנה מינימלית קבועה לפני הגשת תביעה, אלא דורש פנייה בכתב וניסיון ליישב את הסכסוך בדרכי שלום.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד שגיא הפר את כללי האתיקה של לשכת עורכי הדין בכך שלא המתין 21 ימים לפחות ממועד הפנייה למשרד עורכי הדין עד למועד הגשת התביעה.', false, 'טענה זו שגויה. כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) אינו קובע תקופת המתנה מינימלית קבועה לפני הגשת תביעה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד שגיא הפר את כללי האתיקה של לשכת עורכי הדין בכך שלא המתין 30 ימים לפחות ממועד הפנייה למשרד עורכי הדין עד למועד הגשת התביעה.', false, 'טענה זו שגויה. כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) אינו קובע תקופת המתנה מינימלית קבועה לפני הגשת תביעה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד שגיא לא הפר את כללי האתיקה של לשכת עורכי הדין.', true, 'תשובה זו נכונה. כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) דורש פנייה בכתב וניסיון ליישב את הסכסוך בדרכי שלום, אך אינו קובע תקופת המתנה מינימלית קבועה. במקרה זה, עו"ד שגיא שיגר מכתב התראה וקיבל אישור קבלה, ובכך עמד בדרישת הכלל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פנייה בעל פה לעורך דין',
    1, 'עו"ד ראובן מתכוון להגיש תביעה נגד עו"ד שמעון. הוא מתקשר לשמעון ומיידע אותו על כוונתו להגיש תביעה, אך אינו שולח מכתב בכתב. האם עו"ד ראובן פעל כדין?', 'שאלה זו בוחנת את דרישת הכתב בפנייה לעורך דין אחר לפני הגשת תביעה, בהתאם לכלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית).', 'כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי ''בטרם יפתח עורך דין בשם לקוחו בהליך משפטי נגד עורך דין אחר, יפנה אל אותו עורך דין בכתב, ואם קיימת אפשרות - אף בעל פה, כדי לנסות וליישב את הסכסוך בדרכי שלום''. לשון הכלל ברורה: הדרישה העיקרית היא פנייה בכתב, והפנייה בעל פה היא אפשרות נוספת, אך אינה מהווה תחליף לדרישת הכתב. לכן, עו"ד ראובן לא פעל כדין אם הסתפק בפנייה בעל פה בלבד.',
    'הטעות הנפוצה היא לחשוב שפנייה בעל פה, במיוחד אם היא מתועדת או מאושרת, מספקת את דרישת כלל 31, תוך התעלמות מהדרישה המפורשת לפנייה בכתב.', '["כלל 31", "אתיקה מקצועית", "פנייה בכתב", "פנייה בעל פה", "יישוב סכסוכים"]'::jsonb, '**וריאציה 1 — פנייה בכתב בלבד:** האם פנייה בכתב בלבד מספיקה? ← כן, הכלל דורש פנייה בכתב כדרישה עיקרית.
**וריאציה 2 — פנייה בעל פה ואז בכתב:** האם מותר לפנות בעל פה ואז לשלוח מכתב? ← כן, כל עוד הפנייה בכתב מתבצעת לפני הגשת התביעה.
**וריאציה 3 — תכלית דרישת הכתב:** מדוע הכלל דורש פנייה בכתב? ← כדי להבטיח תיעוד, בהירות, ורצינות בניסיון ליישב את הסכסוך, וכדי למנוע מחלוקות עובדתיות לגבי עצם הפנייה ותוכנה.', 'כלל 31 ← דורש פנייה בכתב לעו"ד אחר לפני תביעה; פנייה בעל פה היא בנוסף, לא במקום.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שכלל 31 מתיר פנייה בעל פה.', false, 'טענה זו שגויה. כלל 31 דורש פנייה בכתב כדרישה עיקרית, ופנייה בעל פה היא אפשרות נוספת, לא תחליף.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שכלל 31 דורש פנייה בכתב, ופנייה בעל פה אינה מספקת כשלעצמה.', true, 'תשובה זו נכונה. כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי ''יפנה אל אותו עורך דין בכתב, ואם קיימת אפשרות - אף בעל פה''. הדרישה העיקרית היא פנייה בכתב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם עו"ד שמעון אישר בשיחת הטלפון כי קיבל את ההתראה.', false, 'טענה זו שגויה. אישור קבלה בעל פה אינו מייתר את הדרישה לפנייה בכתב על פי כלל 31.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן עו"ד ראובן תיעד את שיחת הטלפון בכתב.', false, 'טענה זו שגויה. תיעוד שיחת הטלפון אינו הופך את הפנייה בעל פה לפנייה בכתב כנדרש בכלל 31.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תכלית כלל 31',
    2, 'מהי התכלית העיקרית של כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית)?', 'שאלה זו מתמקדת בתכלית החקיקתית של כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), כפי שהיא מפורשת בפסיקה ובספרות המשפטית.', 'הפסיקה מבהירה כי תכליתו של כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) היא למנוע הגשת תביעות מיותרות בין עורכי דין, לעודד פתרון סכסוכים בדרכי שלום, ולשמור על כבוד המקצוע ועל יחסים קולגיאליים. הכלל נועד לאפשר לעורכי הדין המעורבים ללבן את המחלוקת ביניהם מחוץ לכותלי בית המשפט, ובכך למנוע התדיינויות מיותרות ולשמר את מעמדו של המקצוע. (ע"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו"ד משה גולדברג, פסקה 12.2).',
    'הטעות הנפוצה היא לייחס לכלל תכליות פרוצדורליות גרידא או הגנה על עורך הדין הנתבע, במקום אתיקה מקצועית ושמירה על כבוד המקצוע.', '["כלל 31", "תכלית חקיקה", "אתיקה מקצועית", "כבוד המקצוע", "יישוב סכסוכים", "קולגיאליות"]'::jsonb, '**וריאציה 1 — חשיבות הקולגיאליות:** מדוע חשוב לשמור על יחסים קולגיאליים בין עורכי דין? ← כדי לאפשר עבודה יעילה, לטובת הלקוחות, ולשמור על מעמדו הציבורי של המקצוע.
**וריאציה 2 — מניעת סחבת:** האם הכלל נועד למנוע סחבת? ← בעקיפין כן, על ידי עידוד פתרון מהיר ויעיל של סכסוכים מחוץ לבית המשפט.
**וריאציה 3 — השפעה על הלקוח:** האם תכלית הכלל היא גם להגן על הלקוח? ← כן, על ידי הבטחת טיפול מקצועי ויעיל בסכסוך, ומניעת התדיינויות מיותרות שעלולות להזיק לו.', 'תכלית כלל 31 ← יישוב סכסוכים בדרכי שלום, מניעת תביעות מיותרות, שמירה על כבוד המקצוע ויחסים קולגיאליים.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "ע\"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו\"ד משה גולדברג (10.12.2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למנוע הגשת תביעות מיותרות ולנסות ליישב סכסוכים בין עורכי דין בדרכי שלום.', true, 'תשובה זו נכונה. תכלית הכלל היא לעודד פתרון סכסוכים מחוץ לכותלי בית המשפט, לשמור על כבוד המקצוע ועל יחסים קולגיאליים בין עורכי דין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'להגן על עורך הדין הנתבע מפני תביעות פתאומיות ובלתי צפויות.', false, 'טענה זו שגויה. למרות שהכלל עשוי להגן על עורך הדין הנתבע, זו אינה תכליתו העיקרית, אלא תוצאה נלווית של שמירה על כבוד המקצוע וקולגיאליות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'להבטיח כי עורך הדין המגיש את התביעה יקבל אישור מלשכת עורכי הדין לפני הגשתה.', false, 'טענה זו שגויה. הכלל אינו דורש אישור מלשכת עורכי הדין, אלא פנייה ישירה לעורך הדין הנתבע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לצמצם את העומס על בתי המשפט על ידי מניעת הגשת תביעות בין עורכי דין.', false, 'טענה זו שגויה. למרות שהכלל עשוי לתרום לצמצום העומס, זו אינה תכליתו העיקרית, אלא תוצאה נלווית של עידוד יישוב סכסוכים בדרכי שלום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פנייה לעורך דין במקרה של סעד זמני',
    3, 'עו"ד דנה מתכוונת להגיש בקשה לסעד זמני (כגון צו עיקול) נגד עו"ד יואב. האם עו"ד דנה חייבת לפנות לעו"ד יואב בכתב לפני הגשת הבקשה?', 'שאלה זו בוחנת את החריג לכלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), המאפשר אי-פנייה לעורך דין אחר לפני הגשת הליך משפטי, כאשר פנייה כזו עלולה לגרום נזק ללקוח, כגון במקרים של סעדים זמניים.', 'כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע חריג מפורש לדרישת הפנייה המוקדמת: ''ובלבד שפניה כאמור לא תגרום נזק ללקוח''. במקרים של סעדים זמניים, כגון צו עיקול, צו מניעה זמני וכדומה, פנייה מוקדמת לעורך הדין הנתבע עלולה לסכל את מטרת הסעד, לאפשר לו להבריח נכסים או לבצע פעולות שיפגעו בלקוח, ובכך לגרום נזק בלתי הפיך. לכן, במקרים אלו, עורך הדין המגיש את הבקשה לסעד זמני פטור מחובת הפנייה המוקדמת.',
    'הטעות הנפוצה היא לחשוב שכלל 31 הוא מוחלט וחל בכל מקרה, תוך התעלמות מהחריג המפורש לגבי נזק ללקוח, שהוא רלוונטי במיוחד לסעדים זמניים.', '["כלל 31", "אתיקה מקצועית", "סעד זמני", "צו עיקול", "נזק ללקוח", "חריגים לכללים"]'::jsonb, '**וריאציה 1 — צו מניעה זמני:** האם עו"ד חייב לפנות לפני הגשת בקשה לצו מניעה זמני? ← לא, אם הפנייה עלולה לסכל את מטרת הצו ולגרום נזק ללקוח.
**וריאציה 2 — מי קובע את הנזק:** מי קובע אם הפנייה תגרום נזק ללקוח? ← עורך הדין המגיש את התביעה, בשיקול דעת מקצועי, תוך כדי עמידה בסטנדרטים של תום לב.
**וריאציה 3 — חובת יידוע לאחר הגשה:** האם יש חובה ליידע את עורך הדין הנתבע לאחר קבלת הסעד הזמני? ← כן, יש חובה לנהוג בתום לב וליידע את עורך הדין הנתבע בהקדם האפשרי לאחר קבלת הסעד, אלא אם כן בית המשפט הורה אחרת.', 'כלל 31 ← לא חל אם פנייה מוקדמת תגרום נזק ללקוח (למשל, בסעד זמני).',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שכלל 31 חל על כל הליך משפטי נגד עורך דין אחר.', false, 'טענה זו שגויה. כלל 31 כולל חריג מפורש למקרים בהם הפנייה עלולה לגרום נזק ללקוח, כגון בסעדים זמניים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, אם הפנייה עלולה לגרום נזק ללקוח, כגון במקרים של סעדים זמניים.', true, 'תשובה זו נכונה. כלל 31 קובע חריג מפורש: ''ובלבד שפניה כאמור לא תגרום נזק ללקוח''. במקרים של סעדים זמניים, פנייה מוקדמת עלולה לסכל את מטרת הסעד ולגרום נזק ללקוח, ולכן הכלל אינו חל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך היא יכולה להסתפק בפנייה בעל פה.', false, 'טענה זו שגויה. גם אם הכלל היה חל, פנייה בעל פה אינה מספקת כשלעצמה, והחריג מתייחס למקרים בהם אין צורך בפנייה כלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עו"ד יואב הוא עורך הדין המייצג את הצד שכנגד בתיק אחר.', false, 'טענה זו שגויה. הקשר בין עורכי הדין בתיקים אחרים אינו רלוונטי לחריג שבכלל 31.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלכות אי-ציות לכלל 31',
    4, 'עו"ד משה הגיש תביעה נגד עו"ד רחל מבלי לפנות אליה מראש בכתב, בניגוד לכלל 31. מהן ההשלכות של מעשה זה?', 'שאלה זו בוחנת את ההשלכות של הפרת כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), ובפרט את ההבחנה בין המישור האתי לבין המישור המהותי של זכויות הלקוח.', 'הפסיקה קבעה באופן מפורש כי כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) הוא כלל שפועל במישור האתי בלבד, ואין בו כדי לגרוע מזכויות התובעים (ע"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו"ד משה גולדברג, פסקה 12.2). המשמעות היא שעורך דין המפר את הכלל עלול לעמוד לדין משמעתי בפני בתי הדין של לשכת עורכי הדין, אך הפרה זו כשלעצמה לא תביא לדחיית התביעה שהגיש בשם לקוחו, ולא תפגע בזכויותיו המהותיות של הלקוח. בית המשפט עשוי להתייחס להפרה זו לעניין הוצאות משפט, אך לא לעניין עצם קיום התביעה.',
    'הטעות הנפוצה היא לחשוב שהפרת כלל אתי פרוצדורלי גוררת סנקציה דיונית חמורה, כגון דחיית התביעה, במקום סנקציה משמעתית נגד עורך הדין.', '["כלל 31", "אתיקה מקצועית", "עבירת משמעת", "זכויות לקוח", "מישור אתי", "סנקציות"]'::jsonb, '**וריאציה 1 — סנקציה משמעתית:** איזו סנקציה עלולה להיות מוטלת על עו"ד משה? ← נזיפה, קנס, השעיה או הוצאה מהלשכה, בהתאם לחומרת העבירה ונסיבותיה.
**וריאציה 2 — השפעה על הוצאות:** האם הפרת כלל 31 יכולה להשפיע על פסיקת הוצאות משפט? ← כן, בית המשפט עשוי להתחשב בהפרה זו בעת פסיקת הוצאות, במיוחד אם ההפרה גרמה להתדיינות מיותרת (ע"ב 5157/06 אלתר שטול, פסקה 12.2).
**וריאציה 3 — חובת בית המשפט:** האם בית המשפט חייב לדון בהפרת כלל 31? ← בית המשפט אינו חייב לדון בהפרה, שכן היא במישור האתי, אך הוא רשאי להפנות את העניין ללשכת עורכי הדין.', 'הפרת כלל 31 ← עבירת משמעת לעו"ד, אך אינה פוגעת בזכויות הלקוח או מובילה לדחיית התביעה.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "ע\"ב (עבודה תל אביב-יפו) 5157/06 אלתר שטול - עו\"ד משה גולדברג (10.12.2006)", "סע\"ש (אזורי חי'') 18266-12-21 אהרון צידון - תכשיטי מאי בע\"מ (26.03.2025)", "סע\"ש (אזורי ת\"א) 62865-08-21 אוסאמה בני ג''אבר - יפת שלמה (24.01.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'התביעה שהגיש עו"ד משה בשם לקוחו תידחה על הסף.', false, 'טענה זו שגויה. הפרת כלל 31 היא עבירה אתית-משמעתית, אך אינה גורעת מזכויותיו המהותיות של הלקוח ואינה מובילה לדחיית התביעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'עו"ד משה עבר עבירת משמעת, אך הדבר אינו גורע מזכויותיו המהותיות של לקוחו.', true, 'תשובה זו נכונה. הפסיקה קבעה כי כלל 31 פועל במישור האתי בלבד, ואינו גורע מזכויות התובעים. עו"ד משה עלול לעמוד לדין משמעתי, אך התביעה שהגיש בשם לקוחו לא תיפגע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'עו"ד משה יחויב בהוצאות משפט גבוהות לטובת עו"ד רחל, אך התביעה תמשיך להתנהל.', false, 'טענה זו שגויה. חיוב בהוצאות משפט אינו סנקציה אוטומטית על הפרת כלל 31, אלא נתון לשיקול דעת בית המשפט בהתאם לנסיבות התיק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'עו"ד משה יחויב לפנות לעו"ד רחל בכתב, ורק לאחר מכן יוכל להמשיך בהליך המשפטי.', false, 'טענה זו שגויה. לאחר הגשת התביעה, אין חובה להשלים את הפנייה המוקדמת, אם כי בית המשפט עשוי להמליץ על ניסיון ליישוב סכסוך.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 12, '2019-S-S-Q12';
END
$$;

-- ============================================================
-- Q13 — 2019-S-S-Q13 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Self-defense (סייגים לאחריות פלילית) — burglar killed by homeowner; reasonableness threshold
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd4b107f9-0a82-46eb-99f5-81eb17b5fb4a'::uuid;
  v_group_id uuid := '609f07ad-0fa5-499a-87c2-1112d15f9cef'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '1f800b8c-6c8c-4ab4-acab-d5f77b8a68dd'::uuid;
  v_ang_1 uuid := '4aff91dc-9808-4a77-a3d2-a2e5f4632b09'::uuid;
  v_ang_2 uuid := 'fe183f70-be9c-4253-91db-fafdf960fa58'::uuid;
  v_ang_3 uuid := '8040c4e3-e342-4fba-9f07-407af0e8d2af'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q13';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 13, '2019-S-S-Q13';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q13', v_chapter_id, v_subtopic_id, 'שמחה התפרץ לביתו של ששון כדי לבצע שוד. ששון הדף את שמחה וגרם למותו. ההדיפה לא הייתה סבירה, אך היא לא הייתה בלתי-סבירה בעליל. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 13}'::jsonb, 'השאלה עוסקת בהבחנה בין שני סייגים לאחריות פלילית בדיני העונשין: סייג ההגנה העצמית (סעיף 34י לחוק העונשין) וסייג הגנת בית מגורים, בית עסק ומשק חקלאי מגודר (סעיף 34י1 לחוק העונשין). היא מתמקדת במבחן הסבירות השונה הנדרש בכל אחד מהסייגים, ובפרט במבחן המקל של ''לא בלתי סביר בעליל'' החל על הגנת הבית.', 'סעיף 34י לחוק העונשין קובע את סייג ההגנה העצמית, הדורש שהמעשה שנעשה כדי להדוף תקיפה שלא כדין יהיה ''סביר בנסיבות העניין''. לעומת זאת, סעיף 34י1 לחוק העונשין, המכונה ''חוק דרומי'' או ''הגנת הבית'', קובע סייג מקל יותר לאחריות פלילית במקרים של התפרצות או פריצה לבית מגורים, בית עסק או משק חקלאי מגודר. במקרים אלו, נדרש שהמעשה ''לא היה בלתי סביר בעליל בנסיבות העניין''. ההבחנה בין ''סביר'' ל''לא בלתי סביר בעליל'' היא מהותית: ''לא בלתי סביר בעליל'' מאפשר טווח רחב יותר של תגובה, ואינו דורש עמידה במבחן הסבירות המדוקדק. במקרה הנדון, ההדיפה לא הייתה סבירה (ולכן לא עומדת בתנאי סייג הגנה עצמית), אך היא לא הייתה בלתי סבירה בעליל (ולכן עומדת בתנאי סייג הגנת הבית). לפיכך, ששון פטור מאחריות פלילית מכוח סייג הגנת הבית.', 'הטעות הנפוצה היא לבלבל בין מבחני הסבירות השונים של סייג ההגנה העצמית וסייג הגנת הבית, או ליישם את מבחן הסבירות הרגיל גם על הגנת הבית.',
    '["הגנה עצמית", "הגנת בית מגורים", "סייג לאחריות פלילית", "סבירות", "בלתי סביר בעליל", "חוק העונשין סעיף 34י", "חוק העונשין סעיף 34י1"]'::jsonb, '**וריאציה 1 — תקיפה מחוץ לבית:** שמחה התפרץ לחצר המגודרת של ששון. האם חל סייג הגנת הבית? ← כן, ''משק חקלאי מגודר'' כולל גם חצר מגודרת, וניתן להחיל את הסייג (סעיף 34י1).
**וריאציה 2 — מעשה בלתי סביר בעליל:** ששון הדף את שמחה בכוח שהיה בלתי סביר בעליל. האם הוא פטור? ← לא, סעיף 34טז קובע כי אם המעשה היה בלתי סביר בעליל, לא יחול אף סייג.
**וריאציה 3 — תכלית ההבחנה:** מדוע המחוקק קבע מבחן מקל יותר להגנה בתוך הבית? ← כדי להעניק הגנה מוגברת לאדם הנמצא במעוזו, ולהרתיע פורצים, תוך הכרה בלחץ הנפשי במצב כזה (דנ"פ 1042/07 אטיאס, פסקה 10).', 'הגנה עצמית ← דורשת סבירות; הגנת הבית ← דורשת ''לא בלתי סביר בעליל'' (מקל יותר), ורק בתוך הנכס המוגן.', '["חוק העונשין, תשל\"ז-1977, סעיף 34י", "חוק העונשין, תשל\"ז-1977, סעיף 34י1", "חוק העונשין, תשל\"ז-1977, סעיף 34טז", "דנ\"פ 1042/07 אטיאס נ'' מדינת ישראל (20.08.2009)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Self-defense (סייגים לאחריות פלילית) — burglar killed by homeowner; reasonableness threshold | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (סייגים לאחריות פלילית), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין פלילי'' ו''משפט חוזר'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני עונשין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ששון פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג ההגנה העצמית, אך ששון אינו פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג הגנת הבית ("הגנת בית מגורים, בית עסק ומשק חקלאי מגודר").', false, 'טענה זו שגויה. סייג הגנה עצמית דורש סבירות, ואילו סייג הגנת הבית דורש שהמעשה לא יהיה בלתי סביר בעליל, תנאי מקל יותר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ששון אינו פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג ההגנה העצמית, אך ששון פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג הגנת הבית.', true, 'תשובה זו נכונה. סייג הגנה עצמית (סעיף 34י לחוק העונשין) דורש שהמעשה יהיה סביר, תנאי שלא התקיים כאן. לעומת זאת, סייג הגנת בית מגורים (סעיף 34י1 לחוק העונשין) דורש שהמעשה לא יהיה בלתי סביר בעליל, תנאי שהתקיים במקרה זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ששון פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג ההגנה העצמית או את סייג הגנת הבית.', false, 'טענה זו שגויה. ששון אינו פטור מכוח סייג ההגנה העצמית, שכן מעשיו לא היו סבירים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ששון אינו פטור מאחריות פלילית אם בית המשפט יחיל על המקרה את סייג ההגנה העצמית או את סייג הגנת הבית.', false, 'טענה זו שגויה. ששון פטור מאחריות פלילית מכוח סייג הגנת הבית, שכן מעשיו לא היו בלתי סבירים בעליל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הגנה עצמית מול הגנת בית - תקיפה מחוץ לבית',
    1, 'ראובן הותקף על ידי שמעון מחוץ לביתו. ראובן הדף את שמעון בכוח שאינו בלתי סביר בעליל, אך גם אינו עומד במבחן הסבירות המדוקדק של הגנה עצמית רגילה. האם ראובן פטור מאחריות פלילית?', 'שאלה זו בוחנת את תחולת סייג הגנת בית מגורים (סעיף 34י1 לחוק העונשין) על אירועים המתרחשים מחוץ לגבולות הנכס המוגן, ומדגישה את ההבחנה בין סייג זה לבין סייג ההגנה העצמית הרגיל.', 'סייג הגנת בית מגורים, בית עסק ומשק חקלאי מגודר (סעיף 34י1 לחוק העונשין) חל רק על מעשה שנעשה ''בתוך'' אחד מהמקומות המנויים בסעיף. מאחר שהתקיפה התרחשה מחוץ לביתו של ראובן, סייג זה אינו יכול לחול. במקרה כזה, יש לבחון את תחולת סייג ההגנה העצמית הרגיל (סעיף 34י), הדורש שהמעשה יהיה ''סביר בנסיבות העניין''. מאחר שהכוח שהפעיל ראובן לא עמד במבחן הסבירות המדוקדק, הוא אינו פטור מאחריות פלילית מכוח סייג ההגנה העצמית.',
    'הטעות הנפוצה היא להרחיב את תחולת סייג הגנת הבית גם למקרים המתרחשים מחוץ לגבולות הנכס, או לבלבל בין מבחן הסבירות הרגיל למבחן ''לא בלתי סביר בעליל''.', '["הגנה עצמית", "הגנת בית מגורים", "סייג לאחריות פלילית", "תחולת סייג", "סבירות", "חוק העונשין"]'::jsonb, '**וריאציה 1 — תקיפה בחצר הבית:** ראובן הותקף בחצר ביתו המגודרת. האם חל סייג הגנת הבית? ← כן, ''משק חקלאי מגודר'' כולל גם חצר מגודרת, וניתן להחיל את הסייג (סעיף 34י1).
**וריאציה 2 — תקיפה ברחוב:** ראובן הותקף ברחוב. האם חל סייג הגנת הבית? ← לא, סייג הגנת הבית אינו חל על אירועים ברחוב, אלא רק הגנה עצמית רגילה (סעיף 34י).
**וריאציה 3 — תכלית הגנת הבית:** מדוע יש סייג מקל יותר להגנה בתוך הבית? ← כדי להעניק הגנה מוגברת לאדם הנמצא במעוזו, ולהרתיע פורצים (דנ"פ 1042/07 אטיאס נ'' מדינת ישראל, פסקה 10).', 'הגנת בית מגורים ← חלה רק בתוך הנכס המוגן; מחוץ לנכס ← רק הגנה עצמית רגילה (דורשת סבירות).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34י", "חוק העונשין, תשל\"ז-1977, סעיף 34י1", "דנ\"פ 1042/07 אטיאס נ'' מדינת ישראל (20.08.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שהכוח שהפעיל לא היה בלתי סביר בעליל.', false, 'טענה זו שגויה. מבחן ''לא בלתי סביר בעליל'' חל רק על סייג הגנת בית מגורים, וזה אינו חל על אירוע מחוץ לבית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שסייג הגנת בית מגורים אינו חל על אירוע שהתרחש מחוץ לבית.', true, 'תשובה זו נכונה. סייג הגנת בית מגורים (סעיף 34י1 לחוק העונשין) חל רק על מעשה שנעשה ''בתוך בית מגורים, בית עסק או משק חקלאי מגודר''. מאחר שהאירוע התרחש מחוץ לבית, סייג זה אינו רלוונטי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, מכיוון שהותקף על ידי שמעון.', false, 'טענה זו שגויה. עצם התקיפה אינה פוטרת מאחריות אם תנאי הסייגים אינם מתקיימים במלואם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שהכוח שהפעיל לא היה סביר.', false, 'טענה זו נכונה חלקית, אך התשובה המלאה והמדויקת יותר היא שסייג הגנת הבית אינו חל כלל, ולכן נדרשת סבירות רגילה של הגנה עצמית, שלא התקיימה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי סייג הגנת בית מגורים',
    2, 'מהם התנאים המצטברים הנדרשים להחלת סייג הגנת בית מגורים (סעיף 34י1 לחוק העונשין)?', 'שאלה זו בוחנת את היכרות עם התנאים המצטברים להחלת סייג הגנת בית מגורים, בית עסק ומשק חקלאי מגודר, כפי שהם מפורטים בסעיף 34י1 לחוק העונשין.', 'סעיף 34י1 לחוק העונשין קובע כי ''לא יישא אדם באחריות פלילית למעשה שהיה דרוש באופן מיידי כדי להדוף מי שמתפרץ או נכנס לבית מגורים, לבית עסק או למשק חקלאי מגודר, שלו או של זולתו, בכוונה לבצע עבירה, ובלבד שהמעשה לא היה בלתי סביר בעליל בנסיבות העניין''. התנאים המצטברים הם: 1. מעשה שנעשה בתוך בית מגורים, בית עסק או משק חקלאי מגודר. 2. המעשה נועד להדוף מי שמתפרץ או נכנס בכוונה לבצע עבירה. 3. המעשה לא היה בלתי סביר בעליל בנסיבות העניין.',
    'הטעות הנפוצה היא לבלבל בין תנאי סייג הגנת הבית לבין תנאי סייג ההגנה העצמית הרגיל, במיוחד בכל הנוגע למבחן הסבירות ולסוג הסכנה.', '["הגנת בית מגורים", "סייג לאחריות פלילית", "חוק העונשין סעיף 34י1", "התפרצות", "פריצה", "לא בלתי סביר בעליל"]'::jsonb, '**וריאציה 1 — ''דרוש באופן מיידי'':** מה משמעות הדרישה שהמעשה יהיה ''דרוש באופן מיידי''? ← שהמעשה היה הכרחי באותו רגע כדי להדוף את הפורץ, וכי לא הייתה חלופה סבירה אחרת (דנ"פ 1042/07 אטיאס, פסקה 10).
**וריאציה 2 — ''בכוונה לבצע עבירה'':** מה קורה אם הפורץ נכנס ללא כוונה לבצע עבירה? ← סייג הגנת הבית לא יחול, שכן זהו תנאי מהותי להחלתו (סעיף 34י1).
**וריאציה 3 — ''שלו או של זולתו'':** האם הסייג חל גם אם הפורץ מתפרץ לבית של שכן? ← כן, הסייג חל גם על הגנה על רכושו של זולתו (סעיף 34י1).', 'תנאי הגנת הבית ← בתוך נכס מוגן, נגד פורץ/מתפרץ בכוונה לעבור עבירה, והמעשה לא בלתי סביר בעליל.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34י1", "דנ\"פ 1042/07 אטיאס נ'' מדינת ישראל (20.08.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מעשה שנעשה בתוך בית מגורים, בית עסק או משק חקלאי מגודר, כדי למנוע התפרצות או פריצה, והמעשה לא היה בלתי סביר בעליל.', true, 'תשובה זו נכונה. אלו הם התנאים המצטברים המפורטים בסעיף 34י1 לחוק העונשין, המהווים את ליבת סייג הגנת הבית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מעשה שנעשה בתוך בית מגורים, בית עסק או משק חקלאי מגודר, כדי להדוף תקיפה שלא כדין, והמעשה היה סביר.', false, 'טענה זו שגויה. סייג הגנת הבית אינו דורש ''תקיפה שלא כדין'' אלא ''התפרצות או פריצה'', ומבחן הסבירות המדוקדק אינו חל עליו, אלא מבחן ''לא בלתי סביר בעליל''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מעשה שנעשה בכל מקום, כדי למנוע התפרצות או פריצה, והמעשה לא היה בלתי סביר בעליל.', false, 'טענה זו שגויה. הסייג מוגבל למקום ספציפי (בית מגורים, עסק, משק חקלאי מגודר) ואינו חל ''בכל מקום''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מעשה שנעשה בתוך בית מגורים, בית עסק או משק חקלאי מגודר, כדי למנוע התפרצות או פריצה, והמעשה היה הכרחי.', false, 'טענה זו שגויה. דרישת ההכרחיות היא חלק מתנאי סייג הגנה עצמית רגילה, אך הגנת הבית מתמקדת במבחן ''לא בלתי סביר בעליל'' ולא בהכרחיות כשלעצמה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הגנה עצמית - חריג הסבירות',
    3, 'ראובן הותקף על ידי שמעון. ראובן הדף את שמעון בכוח שהיה בלתי סביר בעליל. האם ראובן פטור מאחריות פלילית מכוח סייג ההגנה העצמית?', 'שאלה זו בוחנת את הגבול העליון של הפעלת כוח במסגרת סייגי ההגנה, ומדגישה כי גם במקרים של הגנה עצמית או הגנת בית, הפעלת כוח ''בלתי סביר בעליל'' תשלול את תחולת הסייג, בהתאם לסעיף 34טז לחוק העונשין.', 'סעיף 34טז לחוק העונשין קובע כי ''הוראות סעיפים 34י, 34יא ו-34יב לא יחולו כאשר המעשה לא היה סביר בנסיבות העניין, אלא אם כן המעשה לא היה בלתי סביר בעליל''. כלומר, כדי שסייג הגנה עצמית (סעיף 34י) יחול, המעשה חייב להיות סביר. אם המעשה אינו סביר, אך גם אינו ''בלתי סביר בעליל'', הוא יכול לחסות תחת סייג הגנת הבית (סעיף 34י1). אולם, אם המעשה היה ''בלתי סביר בעליל'', הוא חורג מכל גבולות ההגנה המותרת, ולא יחול עליו אף אחד מהסייגים, כולל הגנה עצמית או הגנת הבית.',
    'הטעות הנפוצה היא לחשוב שכל הפעלת כוח בתגובה לתקיפה תזכה לסייג, תוך התעלמות מהגבול העליון של ''בלתי סביר בעליל'' ששולל כל סייג.', '["הגנה עצמית", "סייג לאחריות פלילית", "בלתי סביר בעליל", "סבירות", "חוק העונשין סעיף 34טז", "חריגה מהגנה"]'::jsonb, '**וריאציה 1 — הגנה עצמית רגילה:** מהו מבחן הסבירות בהגנה עצמית רגילה? ← המעשה צריך להיות סביר בנסיבות העניין, כלומר, יחסיות בין הנזק הצפוי לתוקף לבין הנזק הנמנע מהמותקף (סעיף 34י).
**וריאציה 2 — חריגה מהגנה:** מה קורה אם אדם חרג מהגנה עצמית? ← הוא יישא באחריות פלילית, אלא אם כן חרג במידה מועטה ובתום לב, ואז ייתכן שיחול סייג ''הגנה עצמית מופרזת'' (סעיף 34טז).
**וריאציה 3 — ''בלתי סביר בעליל'' כסף תחתון:** האם ''בלתי סביר בעליל'' הוא סף תחתון או עליון? ← זהו סף עליון, שמעבר לו אין כלל הגנה. כלומר, אם המעשה היה בלתי סביר בעליל, אין פטור מאחריות פלילית (סעיף 34טז).', 'מעשה ''בלתי סביר בעליל'' ← שולל כל סייג לאחריות פלילית, כולל הגנה עצמית והגנת הבית.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34י", "חוק העונשין, תשל\"ז-1977, סעיף 34טז"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שהותקף שלא כדין.', false, 'טענה זו שגויה. עצם התקיפה אינה מספיקה, יש לעמוד בכל תנאי הסייג, כולל מבחן הסבירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שהכוח שהפעיל היה בלתי סביר בעליל.', true, 'תשובה זו נכונה. סעיף 34טז לחוק העונשין קובע כי סייג הגנה עצמית (סעיף 34י) לא יחול כאשר המעשה לא היה סביר בנסיבות העניין. במקרה זה, המעשה היה ''בלתי סביר בעליל'', ולכן הוא אינו עומד גם במבחן המקל של הגנת הבית, וממילא לא בסבירות הנדרשת להגנה עצמית רגילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם לא הייתה לו דרך אחרת להדוף את התקיפה.', false, 'טענה זו שגויה. דרישת ההכרחיות היא תנאי לסייג, אך גם אם התקיימה, אם הכוח היה בלתי סביר בעליל, הסייג לא יחול.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן התקיפה הייתה בתוך ביתו.', false, 'טענה זו שגויה. גם אם התקיפה הייתה בתוך ביתו, אם הכוח היה בלתי סביר בעליל, לא יחול אף סייג, שכן ''בלתי סביר בעליל'' הוא מעבר לגבולות ההגנה המותרת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סייג צורך מול הגנה עצמית',
    4, 'ראובן נקלע למצב חירום בו נשקפה סכנה מיידית לחייו, אך לא הייתה זו תקיפה אנושית (למשל, סכנת טביעה). כדי להציל את חייו, ביצע ראובן עבירה פלילית (למשל, שבר חלון של רכב כדי להשיג חבל). האם ראובן יכול לטעון לסייג הגנה עצמית?', 'שאלה זו בוחנת את ההבחנה בין סייג ההגנה העצמית (סעיף 34י לחוק העונשין) לבין סייג הצורך (סעיף 34יא לחוק העונשין), ובפרט את הדרישה ל''תקיפה שלא כדין'' כתנאי להחלת הגנה עצמית.', 'סייג ההגנה העצמית (סעיף 34י לחוק העונשין) חל רק כאשר אדם מגן על עצמו מפני ''תקיפה שלא כדין'' מצד אדם אחר. במקרה המתואר, הסכנה לחייו של ראובן אינה נובעת מתקיפה אנושית, אלא ממצב חירום טבעי (סכנת טביעה). במקרים כאלה, הסייג הרלוונטי לבחינה הוא סייג הצורך (סעיף 34יא לחוק העונשין), המאפשר פטור מאחריות פלילית כאשר אדם מבצע עבירה כדי להציל את עצמו או זולתו מסכנה מוחשית של פגיעה חמורה, ובתנאי שהמעשה היה הכרחי וסביר בנסיבות העניין.',
    'הטעות הנפוצה היא לבלבל בין סייג הגנה עצמית לסייג הצורך, ולחשוב שהגנה עצמית חלה על כל סכנה, ללא קשר למקורה האנושי.', '["הגנה עצמית", "סייג הצורך", "סייג לאחריות פלילית", "תקיפה שלא כדין", "מצב חירום", "חוק העונשין"]'::jsonb, '**וריאציה 1 — תנאי סייג הצורך:** מהם התנאים העיקריים לסייג הצורך? ← סכנה מוחשית של פגיעה חמורה, מעשה הכרחי וסביר בנסיבות העניין (סעיף 34יא).
**וריאציה 2 — סכנה עצמית:** האם סייג הצורך חל גם אם אדם גרם לסכנה לעצמו? ← כן, סייג הצורך יכול לחול גם אם הסכנה נגרמה באשמתו של העושה, כל עוד התנאים מתקיימים (ע"פ 419/68 מדינת ישראל נ'' לוי).
**וריאציה 3 — סכנה לרכוש:** האם סייג הצורך חל גם על הצלת רכוש? ← כן, סייג הצורך חל גם על הצלת רכוש, אך מבחן הסבירות יהיה מחמיר יותר (סעיף 34יא).', 'הגנה עצמית ← נגד תקיפה אנושית; צורך ← נגד כל סכנה מוחשית (לאו דווקא אנושית).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34י", "חוק העונשין, תשל\"ז-1977, סעיף 34יא", "ע\"פ 419/68 מדינת ישראל נ'' לוי, פ\"ד כג(1) 533 (1969)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, מכיוון שסייג הגנה עצמית חל על כל סכנה מיידית לחיי אדם.', false, 'טענה זו שגויה. סייג הגנה עצמית מוגבל לתקיפה אנושית, ולא לכל סכנה מיידית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, מכיוון שסייג הגנה עצמית חל רק במקרה של תקיפה שלא כדין מצד אדם אחר.', true, 'תשובה זו נכונה. סעיף 34י לחוק העונשין דורש ''תקיפה שלא כדין'' כתנאי להחלת סייג הגנה עצמית. במקרה של סכנה שאינה נובעת מתקיפה אנושית, ייתכן שיחול סייג הצורך (סעיף 34יא).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אם המעשה היה הכרחי וסביר בנסיבות העניין.', false, 'טענה זו שגויה. אלו תנאים לסייג הצורך, אך לא התנאי המהותי של ''תקיפה שלא כדין'' הנדרש להגנה עצמית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הסכנה נבעה ממעשה של המדינה.', false, 'טענה זו שגויה. מקור הסכנה אינו רלוונטי להבחנה בין הגנה עצמית לצורך.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 13, '2019-S-S-Q13';
END
$$;

-- ============================================================
-- Q14 — 2019-S-S-Q14 — chapter=criminal_substantive subtopic=sentencing
-- classifier_note: Minimum sentence for attempted sex offense (sec. 345(a)(1))
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'bd2d12d0-6a3b-4e02-baba-c2e2f1c452cb'::uuid;
  v_group_id uuid := 'f9465899-a3ec-4bd3-b75c-7c10e452ed30'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'e48bb6ba-cd5e-4aec-a090-eca550255f90'::uuid;
  v_ang_1 uuid := '63b0cf6e-6450-4c3f-ad65-98046e5c95e5'::uuid;
  v_ang_2 uuid := 'bfe3ebd1-3421-4f01-aa25-b9d3ec5891ba'::uuid;
  v_ang_3 uuid := 'dac716e1-0619-43a5-8680-d7b69df6a198'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q14';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 14, '2019-S-S-Q14';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q14', v_chapter_id, v_subtopic_id, 'אליק הורשע בניסיון לבצע עבירה לפי סעיף 345(א)(1), ובית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המזערי שעל בית המשפט לגזור על אליק?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 14}'::jsonb, 'השאלה עוסקת בהבחנה בין עונש מזערי לעבירה מושלמת לבין עונש מזערי לניסיון לעבירה, בהתאם לסעיף 355(א) לחוק העונשין, הקובע עונש מזערי לעבירות מין חמורות. היא מדגישה כי הוראת העונש המזערי חלה רק על העבירות המנויות בה במפורש, ואינה חלה על עבירות ניסיון, אלא אם כן צוין אחרת.', 'סעיף 355(א) לחוק העונשין קובע עונש מזערי של רבע מהעונש המרבי לעבירות המנויות בו במפורש, ובהן סעיף 345 (אונס). העונש המרבי על אונס הוא 16 שנות מאסר, ולכן העונש המזערי על אונס מושלם הוא 4 שנות מאסר. עם זאת, סעיף 355(א) אינו מזכיר עבירות ניסיון. סעיף 27 לחוק העונשין קובע כי ''המנסה לעבור עבירה, דינו - מחצית העונש שנקבע לעבירה, אך לא יותר מעשרים שנות מאסר''. מאחר שסעיף 355(א) אינו חל על עבירות ניסיון, אין עונש מזערי קבוע בחוק על ניסיון לאונס. בית המשפט רשאי לגזור על אליק כל עונש עד למחצית העונש המרבי שנקבע לעבירה המושלמת (8 שנות מאסר), ללא מגבלת מינימום.', 'הטעות הנפוצה היא להחיל את הוראת העונש המזערי הקבועה בסעיף 355(א) גם על עבירות ניסיון, למרות שהסעיף אינו מזכיר אותן במפורש, ובכך להתעלם מההבחנה בין עבירה מושלמת לניסיון לעבירה.',
    '["עונש מזערי", "ניסיון לעבירה", "אונס", "חוק העונשין סעיף 355(א)", "חוק העונשין סעיף 27", "גזירת דין", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — עונש מרבי לניסיון:** מהו העונש המרבי על ניסיון לאונס? ← מחצית העונש המרבי על אונס (16 שנים), כלומר 8 שנות מאסר (סעיף 34ד לחוק העונשין).
**וריאציה 2 — עונש מזערי בחוקים אחרים:** האם יש עבירות ניסיון אחרות שעליהן חל עונש מזערי? ← כן, אם חוק ספציפי קובע עונש מזערי גם לניסיון לעבירה מסוימת, אך זהו חריג לכלל.
**וריאציה 3 — תכלית ההבחנה:** מדוע אין עונש מזערי על ניסיון לעבירה? ← המחוקק בחר להבחין בין עבירה מושלמת לניסיון, ולהותיר לבית המשפט שיקול דעת רחב יותר בגזירת העונש על ניסיון, תוך התחשבות בנסיבות אי-ההשלמה.', 'עונש מזערי (סעיף 355(א)) ← חל רק על עבירות מושלמות המנויות בו במפורש; לא חל על ניסיון לעבירה, אלא אם צוין אחרת.', '["חוק העונשין, תשל\"ז-1977, סעיף 27", "חוק העונשין, תשל\"ז-1977, סעיף 345(א)(1)", "חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "חוק העונשין, תשל\"ז-1977, סעיף 34ד"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Minimum sentence for attempted sex offense (sec. 345(a)(1)) | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (עונש מזערי, ניסיון לעבירה), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין פלילי'' ו''משפט חוזר'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני עונשין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', '2 שנות מאסר.', false, 'טענה זו שגויה. 2 שנות מאסר הן רבע מהעונש המרבי לעבירת ניסיון לאונס, אך סעיף 355(א) אינו חל על עבירות ניסיון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', '4 שנות מאסר.', false, 'טענה זו שגויה. 4 שנות מאסר הן רבע מהעונש המרבי לעבירת אונס מושלמת, אך סעיף 355(א) אינו חל על עבירות ניסיון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', '8 שנות מאסר.', false, 'טענה זו שגויה. 8 שנות מאסר הן מחצית מהעונש המרבי לעבירת אונס מושלמת, ואינן רלוונטיות לעונש מזערי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין עונש מזערי על מעשהו של אליק.', true, 'תשובה זו נכונה. סעיף 355(א) לחוק העונשין קובע עונש מזערי רק לעבירות המנויות בו במפורש. סעיף 345 (אונס) מנוי, אך סעיף 27 (ניסיון לעבירה) אינו מנוי. לכן, אין עונש מזערי על ניסיון לאונס, ובית המשפט רשאי לגזור כל עונש עד למחצית העונש המרבי שנקבע לעבירה המושלמת (סעיף 34ד לחוק העונשין).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עונש מזערי לעבירה מושלמת',
    1, 'אליק הורשע בעבירת אונס לפי סעיף 345(א)(1) לחוק העונשין, ובית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המזערי שעל בית המשפט לגזור על אליק?', 'שאלה זו בוחנת את יישום הוראת סעיף 355(א) לחוק העונשין, הקובעת עונש מזערי לעבירות מין חמורות, על עבירת אונס מושלמת, כאשר בית המשפט לא מצא טעמים מיוחדים להקל בעונש.', 'סעיף 345(א)(1) לחוק העונשין קובע כי העונש המרבי על עבירת אונס הוא 16 שנות מאסר. סעיף 355(א) לחוק העונשין קובע כי ''הורשע אדם בעבירה לפי סעיפים 345... לא יפחת עונשו מרבע העונש המרבי שנקבע לאותה עבירה''. במקרה זה, רבע מ-16 שנות מאסר הוא 4 שנות מאסר. מאחר שבית המשפט לא מצא סיבה להקל בעונשו, עליו לגזור על אליק עונש מזערי של 4 שנות מאסר.',
    'הטעות הנפוצה היא לחשב את העונש המזערי באופן שגוי, או לבלבל בין עבירה מושלמת לניסיון לעבירה.', '["עונש מזערי", "עונש מרבי", "אונס", "חוק העונשין סעיף 355(א)", "חוק העונשין סעיף 345(א)(1)", "גזירת דין"]'::jsonb, '**וריאציה 1 — עונש מזערי לעבירה אחרת:** מהו העונש המזערי לעבירה לפי סעיף 348(א) (מעשה סדום)? ← העונש המרבי הוא 10 שנים, לכן העונש המזערי הוא 2.5 שנות מאסר (1/4 מ-10).
**וריאציה 2 — תכלית העונש המזערי:** מדוע נקבע עונש מזערי לעבירות אלו? ← כדי להבטיח ענישה מחמירה ומרתיעה על עבירות מין חמורות, ולהגביל את שיקול הדעת של בית המשפט כלפי מטה.
**וריאציה 3 — עונש מזערי לעבירה קלה יותר:** מהו העונש המזערי לעבירה לפי סעיף 345(ב) (אונס בנסיבות מחמירות)? ← העונש המרבי הוא 20 שנים, לכן העונש המזערי הוא 5 שנות מאסר (1/4 מ-20).', 'עבירת אונס מושלמת (סעיף 345(א)(1)) ← עונש מרבי 16 שנים ← עונש מזערי 4 שנים (רבע מהמרבי, לפי סעיף 355(א)).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 345(א)(1)", "חוק העונשין, תשל\"ז-1977, סעיף 355(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', '2 שנות מאסר.', false, 'טענה זו שגויה. 2 שנות מאסר הן רבע מהעונש המרבי לעבירת ניסיון לאונס, אך לא לעבירת אונס מושלמת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', '4 שנות מאסר.', true, 'תשובה זו נכונה. העונש המרבי לעבירת אונס לפי סעיף 345(א)(1) הוא 16 שנות מאסר. סעיף 355(א) קובע עונש מזערי של רבע מהעונש המרבי, כלומר 1/4 מ-16 שנים = 4 שנות מאסר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', '8 שנות מאסר.', false, 'טענה זו שגויה. 8 שנות מאסר הן מחצית מהעונש המרבי, ואינן העונש המזערי הקבוע בחוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'אין עונש מזערי על מעשהו של אליק.', false, 'טענה זו שגויה. סעיף 355(א) קובע במפורש עונש מזערי לעבירת אונס מושלמת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת ניסיון לעבירה',
    2, 'מהו התנאי המרכזי להרשעה בעבירת ניסיון, לפי חוק העונשין?', 'שאלה זו בוחנת את הגדרת עבירת הניסיון בדיני העונשין, כפי שנקבעה בסעיף 25 לחוק העונשין, ואת היסודות הנדרשים להרשעה בעבירה זו.', 'סעיף 25 לחוק העונשין, תשל"ז-1977, מגדיר ניסיון לעבירה כ''עשיית מעשה לשם ביצוע עבירה, שדינו מאסר, כשהעבירה לא הושלמה''. היסודות הנדרשים הם: 1. יסוד עובדתי: עשיית מעשה שהוא ''לשם ביצוע העבירה'' (מעבר לשלב ההכנה). 2. יסוד נפשי: כוונה לבצע את העבירה המושלמת. 3. העבירה לא הושלמה. במקרה של אליק, הוא ביצע מעשה לשם ביצוע אונס, אך העבירה לא הושלמה, ולכן הורשע בניסיון.',
    'הטעות הנפוצה היא לבלבל בין שלב ההכנה לעבירה לבין שלב הניסיון, או להתעלם מדרישת הכוונה הספציפית להשלמת העבירה.', '["ניסיון לעבירה", "חוק העונשין סעיף 25", "יסוד עובדתי", "יסוד נפשי", "כוונה", "השלמת עבירה"]'::jsonb, '**וריאציה 1 — חרטה מרצון:** מה קורה אם אדם מתחרט מרצון ומפסיק את הניסיון? ← סעיף 28 לחוק העונשין קובע פטור מאחריות פלילית אם הניסיון לא הושלם עקב חרטה מרצון.
**וריאציה 2 — ניסיון בלתי אפשרי:** מהו ניסיון בלתי אפשרי? ← ניסיון לבצע עבירה שלא ניתן להשלימה בשל העדר אמצעים או חפץ, אך עדיין ניתן להרשיע בניסיון אם הייתה כוונה (סעיף 26 לחוק העונשין).
**וריאציה 3 — עונש על ניסיון:** מהו העונש על ניסיון לעבירה? ← העונש על ניסיון הוא מחצית העונש שנקבע לעבירה המושלמת, אך לא יותר מ-20 שנות מאסר (סעיף 34ד לחוק העונשין).', 'ניסיון לעבירה ← מעשה לשם ביצוע עבירה + כוונה + אי-השלמה (סעיף 25 לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 25", "חוק העונשין, תשל\"ז-1977, סעיף 26", "חוק העונשין, תשל\"ז-1977, סעיף 28", "חוק העונשין, תשל\"ז-1977, סעיף 34ד"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ביצוע מעשה שהיווה הכנה לעבירה, מתוך כוונה לבצעה.', false, 'טענה זו שגויה. הכנה לעבירה אינה מספיקה להרשעה בניסיון, אלא נדרש מעשה שהוא ''לשם ביצוע העבירה''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ביצוע מעשה שהוא לשם ביצוע העבירה, מתוך כוונה לבצעה, והעבירה לא הושלמה.', true, 'תשובה זו נכונה. סעיף 25 לחוק העונשין מגדיר ניסיון כ''עשיית מעשה לשם ביצוע עבירה, שדינו מאסר, כשהעבירה לא הושלמה''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ביצוע כל מעשה הקשור לעבירה, גם ללא כוונה להשלימה.', false, 'טענה זו שגויה. נדרשת כוונה להשלים את העבירה, וכן שהמעשה יהיה ''לשם ביצוע העבירה''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'ביצוע כל מעשה שגרם נזק, גם אם לא הייתה כוונה לבצע עבירה.', false, 'טענה זו שגויה. ניסיון דורש כוונה פלילית ספציפית לבצע את העבירה, ולא רק גרימת נזק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הקלה בעונש מזערי מטעמים מיוחדים',
    3, 'אליק הורשע בעבירת אונס לפי סעיף 345(א)(1) לחוק העונשין. בית המשפט שקל לגזור עליו עונש של 3 שנות מאסר. האם בית המשפט רשאי לעשות זאת?', 'שאלה זו בוחנת את החריג לכלל העונש המזערי הקבוע בסעיף 355(א) לחוק העונשין, המאפשר לבית המשפט להקל בעונש מטעמים מיוחדים שיירשמו.', 'סעיף 355(א) לחוק העונשין קובע כי העונש לא יפחת מרבע העונש המרבי, ''אלא אם כן החליט בית המשפט, מטעמים מיוחדים שיירשמו, להקל בעונשו''. כלומר, בית המשפט רשאי לחרוג מהעונש המזערי הקבוע בחוק, אך עליו לנמק את החלטתו ב''טעמים מיוחדים'' ולרשום אותם. טעמים אלו יכולים להיות קשורים לנסיבות ביצוע העבירה, לנסיבותיו האישיות של הנאשם, או לשילוב של שניהם, ובלבד שהם חריגים ויוצאי דופן (ע"פ 10049/08 פלוני נ'' מדינת ישראל, פסקה 12).',
    'הטעות הנפוצה היא לחשוב שהעונש המזערי הוא מוחלט ובלתי ניתן להקלה, או לבלבל בין ''טעמים מיוחדים'' לבין שיקולי ענישה רגילים.', '["עונש מזערי", "הקלה בעונש", "טעמים מיוחדים", "שיקול דעת שיפוטי", "חוק העונשין סעיף 355(א)", "גזירת דין"]'::jsonb, '**וריאציה 1 — מהם ''טעמים מיוחדים''?:** מה יכול להיחשב כ''טעמים מיוחדים''? ← נסיבות חריגות ביותר של העבירה או של הנאשם, כגון שיתוף פעולה יוצא דופן, נזק חמור שנגרם לנאשם כתוצאה מההליך, או נסיבות אישיות קשות במיוחד (ע"פ 10049/08 פלוני, פסקה 12).
**וריאציה 2 — חובת הרישום:** מדוע חשוב ש''טעמים מיוחדים'' יירשמו? ← כדי להבטיח שקיפות, ביקורת שיפוטית, וכדי שההחלטה לא תהיה שרירותית.
**וריאציה 3 — הקלה מתחת לרבע:** האם בית המשפט רשאי לגזור עונש נמוך מרבע העונש המרבי? ← כן, אם מצא טעמים מיוחדים שיירשמו, הוא רשאי להקל בעונש המזערי, כלומר לגזור עונש נמוך יותר מרבע העונש המרבי.', 'הקלה בעונש מזערי (סעיף 355(א)) ← אפשרית רק מ''טעמים מיוחדים שיירשמו'' על ידי בית המשפט.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "ע\"פ 10049/08 פלוני נ'' מדינת ישראל (20.01.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, אם מצא טעמים מיוחדים שיירשמו להקל בעונשו.', true, 'תשובה זו נכונה. סעיף 355(א) מאפשר לבית המשפט להקל בעונש המזערי, אם מצא ''טעמים מיוחדים שיירשמו''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שהעונש המזערי לעבירה זו הוא 4 שנות מאסר, ואין אפשרות להקל בו.', false, 'טענה זו שגויה. קיימת אפשרות להקל בעונש המזערי, אך רק מטעמים מיוחדים שיירשמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם התביעה הסכימה להקלה בעונש.', false, 'טענה זו שגויה. הסכמת התביעה אינה תנאי מספק להקלה בעונש המזערי, אלא נדרשים טעמים מיוחדים של בית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן אליק שיתף פעולה באופן מלא עם רשויות החקירה.', false, 'טענה זו שגויה. שיתוף פעולה יכול להוות שיקול להקלה, אך אינו התנאי היחיד או המכריע להפעלת סעיף 355(א).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'עונש מזערי לעבירות אחרות',
    4, 'האם סעיף 355(א) לחוק העונשין קובע עונש מזערי גם לעבירת סחר בבני אדם?', 'שאלה זו בוחנת את ההבנה כי סעיף 355(א) לחוק העונשין קובע רשימה סגורה של עבירות שעליהן חל העונש המזערי, וכי עבירות שאינן מנויות בו במפורש אינן כפופות להוראה זו, גם אם הן חמורות.', 'סעיף 355(א) לחוק העונשין קובע רשימה סגורה של עבירות שעליהן חל העונש המזערי של רבע מהעונש המרבי. רשימה זו כוללת את סעיפים 345 (אונס), 348(א), (ב) או (ג1) (מעשה סדום, מעשה מגונה בכפייה), ו-351(א), (ב) או (ג)(1) או (2) (בעילה אסורה בהסכמה, מעשה סדום בקטין, מעשה מגונה בקטין). עבירת סחר בבני אדם מוגדרת בסעיף 377א לחוק העונשין, ואינה נכללת ברשימה זו. לכן, סעיף 355(א) אינו קובע עונש מזערי לעבירת סחר בבני אדם.',
    'הטעות הנפוצה היא להרחיב את תחולת סעיף 355(א) לעבירות דומות או חמורות אחרות שאינן מנויות בו במפורש, תוך התעלמות מהאופי הסגור של הרשימה.', '["עונש מזערי", "רשימה סגורה", "חוק העונשין סעיף 355(א)", "סחר בבני אדם", "עבירות מין", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — עבירות נוספות עם עונש מזערי:** האם יש עבירות נוספות בחוק העונשין עם עונש מזערי? ← כן, למשל, סעיף 355(ב) קובע עונש מזערי של חמישית מהעונש המרבי לעבירות מין מסוימות כלפי קטינים.
**וריאציה 2 — עבירות סמים:** האם יש עונש מזערי לעבירות סמים? ← כן, פקודת הסמים המסוכנים קובעת עונשי מינימום לעבירות סמים מסוימות, למשל סעיף 19א לפקודה.
**וריאציה 3 — חשיבות הרשימה הסגורה:** מדוע המחוקק בחר ברשימה סגורה של עבירות בסעיף 355(א)? ← כדי להבטיח ודאות משפטית ולהגביל את תחולת העונש המזערי רק לעבירות החמורות ביותר שהוגדרו במפורש על ידו.', 'סעיף 355(א) ← רשימה סגורה של עבירות מין חמורות; עבירות שאינן מנויות בו (כמו סחר בבני אדם) אינן כפופות לעונש המזערי שבו.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "חוק העונשין, תשל\"ז-1977, סעיף 377א", "חוק העונשין, תשל\"ז-1977, סעיף 355(ב)", "פקודת הסמים המסוכנים [נוסח חדש], תשל\"ג-1973, סעיף 19א"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, סעיף 355(א) חל על כל עבירות המין החמורות, כולל סחר בבני אדם.', false, 'טענה זו שגויה. סעיף 355(א) חל רק על העבירות המנויות בו במפורש, וסחר בבני אדם אינו נכלל ברשימה זו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, סעיף 355(א) חל רק על העבירות המנויות בו במפורש, וסחר בבני אדם אינו אחת מהן.', true, 'תשובה זו נכונה. סעיף 355(א) מונה רשימה סגורה של סעיפים (345, 348(א), (ב) או (ג1), או 351(א), (ב) או (ג)(1) או (2)), ועבירת סחר בבני אדם (סעיף 377א) אינה נכללת בהם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם העבירה בוצעה כלפי קטין.', false, 'טענה זו שגויה. גיל הקורבן משפיע על חומרת העבירה ועל העונש המרבי, אך אינו מכניס עבירה שאינה מנויה בסעיף 355(א) לתחולתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן נקבע עונש מזערי ספציפי לעבירה זו בחוק אחר.', false, 'טענה זו שגויה. השאלה מתייחסת ספציפית לסעיף 355(א), ואין להסיק ממנה על קיומם של עונשים מזעריים בחוקים אחרים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 14, '2019-S-S-Q14';
END
$$;

-- ============================================================
-- Q15 — 2019-S-S-Q15 — chapter=criminal_substantive subtopic=sentencing
-- classifier_note: Minimum sentence for being accomplice to sec. 345(a)(1)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '872aea5e-f764-42d7-a8b1-7bcbccbc5ea1'::uuid;
  v_group_id uuid := '3dd96969-3344-4c84-b537-f495990d1dad'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'bcd84c34-a55e-4a15-a663-cd4b26368ab6'::uuid;
  v_ang_1 uuid := '275a23f8-a21b-479e-bcb8-5b87f2fa147a'::uuid;
  v_ang_2 uuid := 'd08539e4-3fa8-4dc5-9b1f-49530d36b4ac'::uuid;
  v_ang_3 uuid := '38f3d5ce-3fb9-41f8-839f-907b0409b31e'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q15';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 15, '2019-S-S-Q15';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q15', v_chapter_id, v_subtopic_id, 'אלכסנדר הורשע בסיוע לעבירה לפי סעיף 345(א)(1), ובית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המזערי שעל בית המשפט לגזור על אלכסנדר?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 15}'::jsonb, 'השאלה עוסקת בחישוב העונש המזערי על סיוע לעבירה, תוך התייחסות לשני סעיפים מרכזיים בחוק העונשין: סעיף 355(א) הקובע עונש מזערי לעבירות מין חמורות, וסעיף 32(3) הקובע את העונש על סיוע לעבירה שיש לה עונש מזערי. היא מדגישה את הצורך ביישום מדויק של הוראות אלו.', 'סעיף 345(א)(1) לחוק העונשין קובע כי העונש המרבי על עבירת אונס הוא 16 שנות מאסר. סעיף 355(א) לחוק העונשין קובע כי ''הורשע אדם בעבירה לפי סעיפים 345... לא יפחת עונשו מרבע העונש המרבי שנקבע לאותה עבירה''. לכן, העונש המזערי לעבירת אונס מושלמת הוא רבע מ-16 שנות מאסר, כלומר 4 שנות מאסר. כעת, יש לבחון את העונש על סיוע. סעיף 32(3) לחוק העונשין קובע כי אם לעבירה העיקרית נקבע עונש מזערי, עונשו של המסייע ''לא יפחת ממחצית העונש המזערי''. לפיכך, העונש המזערי שעל בית המשפט לגזור על אלכסנדר, שהורשע בסיוע לאונס, הוא מחצית מ-4 שנות המאסר, כלומר 2 שנות מאסר. בית המשפט לא מצא סיבה להקל בעונשו, ולכן עליו לגזור עונש זה.', 'הטעות הנפוצה היא לבלבל בין העונש המזערי לעבירה המושלמת לבין העונש המזערי לסיוע לעבירה, או לחשב את העונש המזערי לסיוע ישירות ממחצית העונש המרבי של העבירה העיקרית, מבלי להתחשב בעונש המזערי של העבירה העיקרית.',
    '["עונש מזערי", "סיוע לעבירה", "חוק העונשין סעיף 355(א)", "חוק העונשין סעיף 32(3)", "עבירות מין", "גזירת דין"]'::jsonb, '**וריאציה 1 — עונש מזערי לעבירה מושלמת:** מהו העונש המזערי על אונס מושלם? ← 4 שנות מאסר (רבע מ-16 שנים, לפי סעיף 355(א)).
**וריאציה 2 — סיוע לעבירה ללא עונש מזערי:** מהו העונש המרבי לסיוע לעבירה שהעונש המרבי עליה הוא 10 שנים ואין לה עונש מזערי? ← 5 שנות מאסר (מחצית מ-10, לפי סעיף 32).
**וריאציה 3 — טעמים מיוחדים:** האם בית המשפט יכול לגזור על אלכסנדר פחות מ-2 שנות מאסר? ← כן, אם מצא ''טעמים מיוחדים שיירשמו'' להקל בעונשו, לפי סעיף 355(א) בשינויים המחויבים לסיוע.', 'סיוע לעבירה עם עונש מזערי ← העונש המזערי הוא מחצית העונש המזערי של העבירה העיקרית (סעיף 32(3) לחוק העונשין).', '["חוק העונשין, תשל\"ז-1977, סעיף 345(א)(1)", "חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "חוק העונשין, תשל\"ז-1977, סעיף 32(3)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Minimum sentence for being accomplice to sec. 345(a)(1) | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (עונש מזערי, סיוע לעבירה), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין פלילי'' ו''משפט חוזר'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני עונשין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', '2 שנות מאסר.', true, 'תשובה זו נכונה. העונש המרבי לעבירת אונס הוא 16 שנות מאסר. העונש המזערי לעבירת אונס הוא רבע מהעונש המרבי, כלומר 4 שנות מאסר. העונש המזערי לסיוע לעבירה עם עונש מזערי הוא מחצית העונש המזערי של העבירה העיקרית, כלומר 2 שנות מאסר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', '4 שנות מאסר.', false, 'טענה זו שגויה. 4 שנות מאסר הוא העונש המזערי לעבירת אונס מושלמת, אך לא לעבירת סיוע לאונס.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', '8 שנות מאסר.', false, 'טענה זו שגויה. 8 שנות מאסר הוא מחצית העונש המרבי לעבירת אונס מושלמת, אך אינו העונש המזערי לסיוע לאונס.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין עונש מזערי על מעשהו של אלכסנדר.', false, 'טענה זו שגויה. סעיף 32(3) לחוק העונשין קובע עונש מזערי לסיוע לעבירה שיש לה עונש מזערי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עונש מזערי לסיוע לעבירה ללא עונש מזערי',
    1, 'דניאל הורשע בסיוע לעבירת גניבה, שהעונש המרבי עליה הוא 3 שנות מאסר, ואין לה עונש מזערי. בית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המרבי שניתן לגזור על דניאל?', 'שאלה זו בוחנת את הכלל הבסיסי הקבוע בסעיף 32 לחוק העונשין, הקובע את העונש המרבי על סיוע לעבירה כאשר לעבירה העיקרית אין עונש מזערי או חובה ספציפיים.', 'סעיף 32 לחוק העונשין קובע כי ''הסיוע לעבור עבירה, עונשו - מחצית העונש שנקבע בחיקוק בשל ביצועה העיקרי''. במקרה זה, העונש המרבי לעבירת הגניבה הוא 3 שנות מאסר. לכן, העונש המרבי שניתן לגזור על דניאל בגין סיוע לעבירה זו הוא מחצית מ-3 שנות מאסר, כלומר שנה וחצי מאסר. אין עונש מזערי ספציפי לעבירת גניבה, ולכן לא חלים החריגים המפורטים בסעיף 32(3) או 32(4).',
    'הטעות הנפוצה היא לבלבל בין העונש המרבי לעבירה העיקרית לבין העונש המרבי לסיוע, או להניח קיומו של עונש מזערי גם כאשר החוק אינו קובע זאת במפורש.', '["סיוע לעבירה", "עונש מרבי", "חוק העונשין סעיף 32", "עבירות ללא עונש מזערי", "גניבה"]'::jsonb, '**וריאציה 1 — עבירה עם עונש מרבי גבוה:** מהו העונש המרבי לסיוע לעבירה שהעונש המרבי עליה הוא 10 שנות מאסר? ← 5 שנות מאסר (מחצית מ-10).
**וריאציה 2 — עבירת חטא:** האם ניתן להרשיע בסיוע לעבירת חטא? ← לא, סעיף 34ג לחוק העונשין קובע כי ניסיון, שידול, ניסיון לשידול וסיוע לעבירת חטא אינם ענישים.
**וריאציה 3 — סיוע לאחר מעשה:** מה ההבדל בין סיוע לעבירה לסיוע לאחר מעשה? ← סיוע לעבירה (סעיף 31) מתרחש לפני או בשעת ביצוע העבירה, ואילו סיוע לאחר מעשה (סעיף 260(א)) מתרחש לאחר ביצוע העבירה ונועד למנוע את תפיסת המבצע או גילוי העבירה, ועונשו קל יותר.', 'סיוע לעבירה ללא עונש מזערי ← עונש מרבי הוא מחצית העונש המרבי של העבירה העיקרית (סעיף 32).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 32", "חוק העונשין, תשל\"ז-1977, סעיף 34ג", "חוק העונשין, תשל\"ז-1977, סעיף 260(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'שנה וחצי מאסר.', true, 'תשובה זו נכונה. סעיף 32 לחוק העונשין קובע כי העונש על סיוע לעבירה הוא מחצית העונש שנקבע בחיקוק בשל ביצועה העיקרי. במקרה זה, מחצית מ-3 שנות מאסר היא שנה וחצי מאסר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', '3 שנות מאסר.', false, 'טענה זו שגויה. 3 שנות מאסר הוא העונש המרבי לעבירה העיקרית, לא לסיוע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'אין עונש מרבי קבוע בחוק לסיוע לעבירת גניבה.', false, 'טענה זו שגויה. סעיף 32 לחוק העונשין קובע כלל ברור לחישוב העונש המרבי לסיוע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'חצי שנה מאסר.', false, 'טענה זו שגויה. חצי שנה מאסר אינו תואם את חישוב מחצית העונש המרבי לעבירה העיקרית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'טעמים מיוחדים להקלה בעונש מזערי',
    2, 'בית המשפט הורשע את ראובן בעבירת אונס לפי סעיף 345(א)(1) לחוק העונשין. התביעה ביקשה לגזור עליו 4 שנות מאסר, אך בית המשפט שקל לגזור עליו 3 שנות מאסר. האם בית המשפט רשאי לעשות זאת?', 'שאלה זו בוחנת את החריג לכלל העונש המזערי הקבוע בסעיף 355(א) לחוק העונשין, המאפשר לבית המשפט להקל בעונש מטעמים מיוחדים שיירשמו.', 'סעיף 355(א) לחוק העונשין קובע כי העונש לא יפחת מרבע העונש המרבי, ''אלא אם כן החליט בית המשפט, מטעמים מיוחדים שיירשמו, להקל בעונשו''. העונש המרבי על אונס הוא 16 שנות מאסר, ולכן העונש המזערי הוא 4 שנות מאסר. בית המשפט רשאי לחרוג מעונש מזערי זה ולגזור 3 שנות מאסר, אך ורק אם מצא ''טעמים מיוחדים'' המצדיקים זאת, ועליו לפרט טעמים אלו בפסק הדין. טעמים אלו יכולים להיות קשורים לנסיבות ביצוע העבירה, לנסיבותיו האישיות של הנאשם, או לשילוב של שניהם, ובלבד שהם חריגים ויוצאי דופן (ע"פ 10049/08 פלוני נ'' מדינת ישראל, פסקה 12).',
    'הטעות הנפוצה היא לחשוב שהעונש המזערי הוא מוחלט ובלתי ניתן להקלה, או לבלבל בין ''טעמים מיוחדים'' לבין שיקולי ענישה רגילים.', '["עונש מזערי", "הקלה בעונש", "טעמים מיוחדים", "שיקול דעת שיפוטי", "חוק העונשין סעיף 355(א)", "גזירת דין"]'::jsonb, '**וריאציה 1 — מהם ''טעמים מיוחדים''?:** מה יכול להיחשב כ''טעמים מיוחדים''? ← נסיבות חריגות ביותר של העבירה או של הנאשם, כגון שיתוף פעולה יוצא דופן, נזק חמור שנגרם לנאשם כתוצאה מההליך, או נסיבות אישיות קשות במיוחד (ע"פ 10049/08 פלוני, פסקה 12).
**וריאציה 2 — חובת הרישום:** מדוע חשוב ש''טעמים מיוחדים'' יירשמו? ← כדי להבטיח שקיפות, ביקורת שיפוטית, וכדי שההחלטה לא תהיה שרירותית.
**וריאציה 3 — עונש מזערי ומאסר על תנאי:** האם ניתן להטיל חלק מהעונש המזערי כמאסר על תנאי? ← כן, הפסיקה קבעה כי ניתן להטיל חלק מהעונש המזערי בדרך של מאסר מותנה, אך סעיף 355(ב) קובע כי בהעדר טעמים מיוחדים, עונש המאסר לא יהיה כולו על תנאי (תפח"ע (מחוזי תל אביב-יפו) 26891-11-23 מדינת ישראל נ'' פלונית, פסקה 19).', 'הקלה בעונש מזערי (סעיף 355(א)) ← אפשרית רק מ''טעמים מיוחדים שיירשמו'' על ידי בית המשפט.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "ע\"פ 10049/08 פלוני נ'' מדינת ישראל (20.01.2009)", "תפח\"ע (מחוזי תל אביב-יפו) 26891-11-23 מדינת ישראל נ'' פלונית (18.07.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, אם מצא טעמים מיוחדים שיירשמו להקל בעונשו.', true, 'תשובה זו נכונה. סעיף 355(א) לחוק העונשין מאפשר לבית המשפט להקל בעונש המזערי (רבע מהעונש המרבי) אם מצא ''טעמים מיוחדים שיירשמו''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, מכיוון שהעונש המזערי לעבירה זו הוא 4 שנות מאסר, ואין אפשרות להקל בו.', false, 'טענה זו שגויה. קיימת אפשרות להקל בעונש המזערי, אך רק מטעמים מיוחדים שיירשמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אם התביעה הסכימה להקלה בעונש.', false, 'טענה זו שגויה. הסכמת התביעה אינה תנאי מספק להקלה בעונש המזערי, אלא נדרשים טעמים מיוחדים של בית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן ראובן שיתף פעולה באופן מלא עם רשויות החקירה.', false, 'טענה זו שגויה. שיתוף פעולה יכול להוות שיקול להקלה, אך אינו התנאי היחיד או המכריע להפעלת סעיף 355(א).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סיוע לעבירה עם עונש מאסר עולם חובה',
    3, 'שמעון הורשע בסיוע לעבירת רצח בנסיבות מחמירות, שהעונש עליה הוא מאסר עולם חובה. בית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המרבי שניתן לגזור על שמעון?', 'שאלה זו בוחנת את החריג הספציפי הקבוע בסעיף 32(1) לחוק העונשין, הדן בעונש המרבי על סיוע לעבירה שהעונש עליה הוא מיתה או מאסר עולם חובה.', 'סעיף 32 לחוק העונשין קובע כלל לפיו עונשו של המסייע הוא מחצית העונש שנקבע בחיקוק בשל ביצועה העיקרי. אולם, סעיף 32(1) קובע חריג לכלל זה: ''ואולם אם נקבע לה - (1) עונש מיתה או מאסר עולם חובה - עונשו מאסר עשרים שנה''. מאחר שעבירת רצח בנסיבות מחמירות נושאת עונש מאסר עולם חובה, העונש המרבי שניתן לגזור על שמעון בגין סיוע לעבירה זו הוא 20 שנות מאסר.',
    'הטעות הנפוצה היא ליישם את הכלל הכללי של מחצית העונש המרבי גם במקרים בהם קיימים חריגים ספציפיים בסעיף 32.', '["סיוע לעבירה", "מאסר עולם חובה", "עונש מרבי", "חוק העונשין סעיף 32(1)", "רצח בנסיבות מחמירות"]'::jsonb, '**וריאציה 1 — עונש מאסר עולם (לא חובה):** מהו העונש המרבי לסיוע לעבירה שהעונש עליה הוא מאסר עולם (לא חובה)? ← 10 שנות מאסר, לפי סעיף 32(2) לחוק העונשין.
**וריאציה 2 — לפני תיקון 39:** מה היה עונשו של המסייע לפני תיקון 39 לחוק העונשין? ← עונשו של המסייע היה זהה לעונשו של המבצע העיקרי (רבין וואקי, דיני עונשין, עמ'' 57).
**וריאציה 3 — תכלית החריג:** מדוע נקבע חריג ספציפי לעונש מיתה או מאסר עולם חובה? ← כדי להבטיח ענישה חמורה על סיוע לעבירות החמורות ביותר, אך עדיין להבחין בין המסייע למבצע העיקרי.', 'סיוע לעבירה עם מאסר עולם חובה ← עונש מרבי 20 שנה (סעיף 32(1) לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 32(1)", "חוק העונשין, תשל\"ז-1977, סעיף 32(2)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ג. העונש על סיוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'מאסר עולם.', false, 'טענה זו שגויה. מאסר עולם הוא העונש למבצע העיקרי, לא למסייע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', '20 שנות מאסר.', true, 'תשובה זו נכונה. סעיף 32(1) לחוק העונשין קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע הוא מאסר 20 שנה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', '10 שנות מאסר.', false, 'טענה זו שגויה. 10 שנות מאסר הוא העונש המרבי לסיוע לעבירה שהעונש עליה הוא מאסר עולם (לא חובה), לפי סעיף 32(2).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'מחצית העונש שייגזר על המבצע העיקרי.', false, 'טענה זו שגויה. זהו הכלל הכללי בסעיף 32, אך סעיף 32(1) קובע חריג ספציפי למקרים של מאסר עולם חובה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'יחס בין עונש מסייע למבצע',
    4, 'אמיר הורשע בסיוע לעבירת החזקת סם מסוכן שלא לצריכה עצמית, ואשר הורשע בביצוע העבירה העיקרית. בית המשפט המחוזי גזר על שניהם עונש מאסר זהה. האם בית המשפט העליון יתערב בגזר הדין?', 'שאלה זו בוחנת את גמישותו של הכלל הקבוע בסעיף 32 לחוק העונשין, הקובע את היחס בין עונשו של המסייע לעונשו של המבצע העיקרי, ואת שיקול הדעת של בית המשפט לסטות מכלל זה במקרים חריגים.', 'הפסיקה קבעה כי הכלל הקבוע בסעיף 32 לחוק העונשין, לפיו עונשו של המסייע הוא מחצית העונש שנקבע לביצועה העיקרי של העבירה, אינו נוסחה מתמטית מחייבת. בית המשפט רשאי לסטות מכלל זה, ובמקרים חריגים של ''דרגת סיוע גבוהה'', אף להשוות את עונשו של המסייע לעונשו של המבצע העיקרי (ע"פ 4592/15 אשר מסעוד פדידה נ'' מדינת ישראל, פסקה 2). סטייה כזו תתאפשר כאשר תרומת המסייע לביצוע העבירה בעלת משקל משמעותי, והוא גילה מעורבות אקטיבית בביצוע, עד כדי כך שבלא מעורבותו העבירה לא הייתה מתגבשת (ע"פ 4592/15 פדידה, פסקה 2). במקרה כזה, בית המשפט העליון לא יתערב בגזר הדין.',
    'הטעות הנפוצה היא לראות בסעיף 32 כלל נוקשה ובלתי ניתן לסטייה, תוך התעלמות מהפסיקה המרחיבה את שיקול הדעת השיפוטי.', '["סיוע לעבירה", "עונש על סיוע", "שיקול דעת שיפוטי", "חוק העונשין סעיף 32", "דרגת סיוע", "השוואת עונשים"]'::jsonb, '**וריאציה 1 — גזירת דין אינדיבידואלית:** האם גזירת הדין של המסייע היא תמיד אינדיבידואלית? ← כן, מלאכת גזירת הדין היא תמיד אינדיבידואלית ומשתנה לפי נסיבותיו המיוחדות של המקרה ושל הנאשם (ת"פ (מחוזי ב"ש) 62962-06-21 מדינת ישראל נ'' אביאל כהן, פסקה 11).
**וריאציה 2 — שיקולים לסטייה:** אילו שיקולים ינחו את בית המשפט בסטייה מהכלל? ← טיב המעורבות של המסייע, משכה ועומקה, חשיבות חלקו של המסייע וכיצד הסיוע אפשר לממש את התוכנית העבריינית או הקל זאת (ע"פ 4592/15 פדידה, פסקה 2).
**וריאציה 3 — עמדת התביעה:** האם בית המשפט מחויב בעמדת התביעה לעניין העונש? ← לא, בית המשפט אינו מחויב בעמדת התביעה, ויכול לסטות הימנה לקולה או לחומרה, כאשר נסיבות העניין והאינטרס הציבורי מחייבים זאת (ע"פ 4592/15 פדידה, פסקה 28).', 'עונש מסייע ← ככלל מחצית עונש מבצע, אך לא נוסחה מתמטית; ניתן לסטות לחומרה (ואף להשוות) לפי דרגת הסיוע המשמעותית (ע"פ 4592/15 פדידה).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 32", "ע\"פ 4592/15 אשר מסעוד פדידה נ'' מדינת ישראל (08.02.2016)", "ת\"פ (מחוזי ב\"ש) 62962-06-21 מדינת ישראל נ'' אביאל כהן (15.12.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, מכיוון שעונשו של המסייע חייב להיות מחצית מעונשו של המבצע העיקרי, ואין לסטות מכלל זה.', false, 'טענה זו שגויה. הפסיקה קבעה כי הכלל של מחצית העונש אינו נוסחה מתמטית מחייבת, וניתן לסטות ממנו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, מכיוון שניתן לסטות מהכלל הקבוע בסעיף 32 לחוק העונשין ולהשוות את עונשו של המסייע לעונשו של המבצע העיקרי במקרים חריגים של ''דרגת סיוע גבוהה''.', true, 'תשובה זו נכונה. הפסיקה הכירה באפשרות לסטות מהכלל של מחצית העונש ולהשוות את עונשו של המסייע לעונשו של המבצע העיקרי, במקרים חריגים בהם תרומת המסייע לביצוע העבירה בעלת משקל משמעותי ומהווה ''דרגת סיוע גבוהה''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אלא אם כן התביעה הסכימה לעונש זהה במסגרת הסדר טיעון.', false, 'טענה זו שגויה. הסכמת התביעה אינה מחייבת את בית המשפט, ובית המשפט רשאי לסטות מהסדר טיעון אם אינו מקיים איזון ראוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, מכיוון שבית המשפט העליון אינו מתערב בשיקולי ענישה של הערכאה הדיונית.', false, 'טענה זו שגויה. בית המשפט העליון מתערב בגזרי דין במקרים חריגים, כולל סטייה מעקרונות ענישה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 15, '2019-S-S-Q15';
END
$$;

-- ============================================================
-- Q16 — 2019-S-S-Q16 — chapter=criminal_substantive subtopic=sentencing
-- classifier_note: Minimum sentence for solicitation of sec. 345(a)(1)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '3690151d-f532-4cc2-b1b3-12ec81c733cf'::uuid;
  v_group_id uuid := 'e90973fb-2d98-48c7-bbec-7dd6df01589a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'db0be279-eafc-413b-b9ee-bbbd2d5e4406'::uuid;
  v_ang_1 uuid := '0082ef09-88fe-410e-b730-4bfeec4f88fe'::uuid;
  v_ang_2 uuid := 'cffde306-47c2-4793-a917-df7050b5ac6f'::uuid;
  v_ang_3 uuid := '91aa1713-93c5-47bb-beb0-1c051a113500'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q16';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 16, '2019-S-S-Q16';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q16', v_chapter_id, v_subtopic_id, 'אליהו הורשע בשידול לעבירה לפי סעיף 345(א)(1), ובית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המזערי שעל בית המשפט לגזור על אליהו?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 16}'::jsonb, 'השאלה עוסקת בחישוב העונש המזערי על שידול לעבירה, תוך התייחסות לסעיף 355(א) לחוק העונשין הקובע עונש מזערי לעבירות מין חמורות, ולסעיף 34ד לחוק העונשין הקובע כי דין השידול הוא כדין הביצוע העיקרי. היא מדגישה את הצורך ביישום מדויק של הוראות אלו.', 'סעיף 345(א)(1) לחוק העונשין קובע כי העונש המרבי על עבירת אונס הוא 16 שנות מאסר. סעיף 355(א) לחוק העונשין קובע כי ''הורשע אדם בעבירה לפי סעיפים 345... לא יפחת עונשו מרבע העונש המרבי שנקבע לאותה עבירה, אלא אם כן החליט בית המשפט, מטעמים מיוחדים שיירשמו, להקל בעונשו''. לכן, העונש המזערי לעבירת אונס מושלמת הוא רבע מ-16 שנות מאסר, כלומר 4 שנות מאסר. סעיף 34ד לחוק העונשין קובע כי ''מלבד אם נאמר בחיקוק או משתמע ממנו אחרת, כל דין החל על הביצוע העיקרי של העבירה המושלמת חל גם על ניסיון, שידול, ניסיון לשידול או סיוע, לאותה עבירה''. מאחר שאין הוראה ספציפית בחוק העונשין הקובעת עונש שונה לשידול לעבירת אונס, דין השידול הוא כדין הביצוע העיקרי. לפיכך, העונש המזערי שעל בית המשפט לגזור על אליהו, שהורשע בשידול לאונס, הוא 4 שנות מאסר. בית המשפט לא מצא סיבה להקל בעונשו, ולכן עליו לגזור עונש זה.', 'הטעות הנפוצה היא לבלבל בין דין השידול לדין הסיוע, ולחשב את העונש המזערי לשידול כמחצית העונש המזערי של העבירה העיקרית, כפי שנעשה בסיוע (סעיף 32(3)).',
    '["עונש מזערי", "שידול לעבירה", "אונס", "חוק העונשין סעיף 355(א)", "חוק העונשין סעיף 34ד", "גזירת דין", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — עונש מזערי לעבירה מושלמת:** מהו העונש המזערי על אונס מושלם? ← 4 שנות מאסר (רבע מ-16 שנים, לפי סעיף 355(א)).
**וריאציה 2 — סיוע לעבירה עם עונש מזערי:** מהו העונש המזערי לסיוע לעבירת אונס? ← 2 שנות מאסר (מחצית העונש המזערי של העבירה העיקרית, לפי סעיף 32(3)).
**וריאציה 3 — טעמים מיוחדים:** האם בית המשפט יכול לגזור על אליהו פחות מ-4 שנות מאסר? ← כן, אם מצא ''טעמים מיוחדים שיירשמו'' להקל בעונשו, לפי סעיף 355(א) המוחל על שידול.', 'שידול לעבירה עם עונש מזערי ← העונש המזערי הוא זהה לעונש המזערי של העבירה העיקרית (סעיף 34ד לחוק העונשין).', '["חוק העונשין, תשל\"ז-1977, סעיף 345(א)(1)", "חוק העונשין, תשל\"ז-1977, סעיף 355(א)", "חוק העונשין, תשל\"ז-1977, סעיף 34ד", "חוק העונשין, תשל\"ז-1977, סעיף 32(3)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Minimum sentence for solicitation of sec. 345(a)(1) | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (עונש מזערי, שידול לעבירה), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין פלילי'' ו''משפט חוזר'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני עונשין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', '2 שנות מאסר.', false, 'טענה זו שגויה. 2 שנות מאסר הוא העונש המזערי לסיוע לעבירת אונס, ולא לשידול לעבירת אונס.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', '4 שנות מאסר.', true, 'תשובה זו נכונה. העונש המרבי לעבירת אונס (סעיף 345(א)(1)) הוא 16 שנות מאסר. העונש המזערי לעבירת אונס (סעיף 355(א)) הוא רבע מהעונש המרבי, כלומר 4 שנות מאסר. סעיף 34ד לחוק העונשין קובע כי דין השידול הוא כדין הביצוע העיקרי, ולכן העונש המזערי על שידול לאונס הוא 4 שנות מאסר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', '8 שנות מאסר.', false, 'טענה זו שגויה. 8 שנות מאסר הוא מחצית העונש המרבי לעבירת אונס, ואינו העונש המזערי לשידול.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין עונש מזערי על מעשהו של אליהו.', false, 'טענה זו שגויה. סעיף 355(א) קובע עונש מזערי לעבירת אונס, וסעיף 34ד מחיל דין זה גם על שידול.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עונש מזערי לשידול לעבירה ללא עונש מזערי',
    1, 'דניאל הורשע בשידול לעבירת גניבה, שהעונש המרבי עליה הוא 3 שנות מאסר, ואין לה עונש מזערי. בית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המרבי שניתן לגזור על דניאל?', 'שאלה זו בוחנת את הכלל הבסיסי הקבוע בסעיף 34ד לחוק העונשין, הקובע כי דין השידול הוא כדין הביצוע העיקרי של העבירה, בהיעדר הוראה מפורשת אחרת.', 'סעיף 34ד לחוק העונשין קובע כי ''מלבד אם נאמר בחיקוק או משתמע ממנו אחרת, כל דין החל על הביצוע העיקרי של העבירה המושלמת חל גם על ניסיון, שידול, ניסיון לשידול או סיוע, לאותה עבירה''. מאחר שאין הוראה ספציפית בחוק העונשין הקובעת עונש שונה לשידול לעבירת גניבה, העונש המרבי על שידול לגניבה יהיה זהה לעונש המרבי על גניבה, שהוא 3 שנות מאסר. אין עונש מזערי לעבירת גניבה, ולכן גם לשידול לגניבה אין עונש מזערי.',
    'הטעות הנפוצה היא לבלבל בין העונש המרבי לשידול לבין העונש המרבי לסיוע, או להניח קיומו של עונש מזערי גם כאשר החוק אינו קובע זאת במפורש.', '["שידול לעבירה", "עונש מרבי", "חוק העונשין סעיף 34ד", "עבירות ללא עונש מזערי", "גניבה"]'::jsonb, '**וריאציה 1 — עונש מרבי לשידול לעבירה עם עונש מרבי גבוה:** מהו העונש המרבי לשידול לעבירה שהעונש המרבי עליה הוא 10 שנות מאסר? ← 10 שנות מאסר, לפי סעיף 34ד לחוק העונשין.
**וריאציה 2 — שידול לעבירת חטא:** האם ניתן להרשיע בשידול לעבירת חטא? ← לא, סעיף 34ג לחוק העונשין קובע כי שידול לעבירת חטא אינו עניש.
**וריאציה 3 — תכלית השוואת העונש:** מדוע עונשו של המשדל זהה לעונשו של המבצע העיקרי? ← תרומתו של המשדל לביצוע העבירה היא ראשית ומכרעת, שכן הוא מביא את המבצע להחליט לבצע את העבירה (יורם רבין, יניב ואקי, דיני עונשין - כרך א, 2014, עמ'' 30).', 'שידול לעבירה ללא עונש מזערי ← עונש מרבי זהה לעונש המרבי של העבירה העיקרית (סעיף 34ד).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34ד", "חוק העונשין, תשל\"ז-1977, סעיף 34ג", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ג. העונש על שידול"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'שנה וחצי מאסר.', false, 'טענה זו שגויה. שנה וחצי מאסר הוא העונש המרבי לסיוע לעבירת גניבה, לא לשידול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', '3 שנות מאסר.', true, 'תשובה זו נכונה. סעיף 34ד לחוק העונשין קובע כי דין השידול הוא כדין הביצוע העיקרי, אלא אם נאמר בחיקוק אחרת. מאחר שאין הוראה ספציפית לעונש על שידול לגניבה, העונש המרבי על שידול לגניבה הוא זהה לעונש המרבי על גניבה, כלומר 3 שנות מאסר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'אין עונש מרבי קבוע בחוק לשידול לעבירת גניבה.', false, 'טענה זו שגויה. סעיף 34ד לחוק העונשין קובע כלל ברור לחישוב העונש המרבי לשידול.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'חצי שנה מאסר.', false, 'טענה זו שגויה. חצי שנה מאסר אינו תואם את חישוב העונש המרבי לשידול לעבירת גניבה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי השידול לעבירה',
    2, 'מהו היסוד העובדתי הנדרש להרשעה בשידול לעבירה, לפי חוק העונשין?', 'שאלה זו בוחנת את היכרות עם היסוד העובדתי של עבירת השידול, כפי שהוא מוגדר בסעיף 30 לחוק העונשין.', 'סעיף 30 לחוק העונשין, תשל"ז-1977, מגדיר שידול כ''המביא אחר לידי עשיית עבירה בשכנוע, בעידוד, בדרישה, בהפצרה או בכל דרך שיש בה משום הפעלת לחץ''. היסוד העובדתי מתמקד בפעולת המשדל שמטרתה להשפיע על רצונו של אדם אחר לבצע עבירה. תמצית השידול היא הבאת אחר לידי ביצוע העבירה, כלומר בתרומת המשדל לכך שהמבצע העיקרי החליט (או החליט סופית) לבצע את העבירה (ע"פ 8469/99 אסקין נ'' מדינת ישראל).',
    'הטעות הנפוצה היא לבלבל בין היסוד העובדתי של שידול לבין היסודות העובדתיים של צורות השתתפות אחרות בעבירה, כגון סיוע או ניסיון.', '["שידול לעבירה", "יסוד עובדתי", "חוק העונשין סעיף 30", "הבאת אחר לידי עשיית עבירה", "שכנוע", "עידוד"]'::jsonb, '**וריאציה 1 — יסוד נפשי בשידול:** מהו היסוד הנפשי הנדרש בשידול? ← מחשבה פלילית, כלומר מודעות לטיב ההתנהגות וכוונה להביא את המשודל לידי ביצוע העבירה (יורם רבין, יניב ואקי, דיני עונשין - כרך א, 2014, עמ'' 171).
**וריאציה 2 — שידול שלא צלח:** מה דינו של שידול שלא צלח? ← שידול שלא צלח הוא ניסיון לשידול, ועונשו זהה לעונש על סיוע (מחצית העונש על העבירה העיקרית, בכפוף לחריגים) (נבו - המתמחה, דיני עונשין ודרכי ענישה, 2026, עמ'' 44).
**וריאציה 3 — שידול במחדל:** האם ניתן לשדל במחדל? ← קיימת מחלוקת בספרות המשפטית בנושא, אך הגישה הרווחת היא ששידול דורש התנהגות אקטיבית (רוני רוזנברג, ''שידול במחדל - האמנם אפשרי הוא?'', דין ודברים ז 425, 2014).', 'שידול ← הבאת אחר לידי עשיית עבירה באמצעות לחץ (סעיף 30 לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 30", "ע\"פ 8469/99 אסקין נ'' מדינת ישראל, פ\"ד נה(2) 65 (2001)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | ההבחנה בין עבירת השידול לעבירת הסיוע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ביצוע מעשה עזרה למבצע העיקרי לפני או בשעת ביצוע העבירה.', false, 'טענה זו שגויה. זהו היסוד העובדתי של סיוע לעבירה, לא של שידול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הבאת אדם אחר לידי עשיית עבירה בשכנוע, בעידוד, בדרישה, בהפצרה או בכל דרך שיש בה משום הפעלת לחץ.', true, 'תשובה זו נכונה. סעיף 30 לחוק העונשין מגדיר את היסוד העובדתי של שידול לעבירה באופן זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ביצוע מעשה שהוא לשם ביצוע העבירה, מתוך כוונה לבצעה, והעבירה לא הושלמה.', false, 'טענה זו שגויה. זהו היסוד העובדתי של ניסיון לעבירה, לא של שידול.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'ביצוע מעשה לאחר ביצוע העבירה, שמטרתו למנוע את תפיסת המבצע או גילוי העבירה.', false, 'טענה זו שגויה. זהו היסוד העובדתי של סיוע לאחר מעשה, לא של שידול.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שידול לעבירה עם עונש מיתה/מאסר עולם חובה',
    3, 'שמעון הורשע בשידול לעבירת רצח בנסיבות מחמירות, שהעונש עליה הוא מאסר עולם חובה. בית המשפט לא מצא סיבה להקל בעונשו. מהו העונש המרבי שניתן לגזור על שמעון?', 'שאלה זו בוחנת את החריג הספציפי הקבוע בסעיף 32(1) לחוק העונשין, המוחל על שידול באמצעות סעיף 34ד, ודן בעונש המרבי על שידול לעבירה שהעונש עליה הוא מיתה או מאסר עולם חובה.', 'סעיף 34ד לחוק העונשין קובע כי דין השידול הוא כדין הביצוע העיקרי, אלא אם נאמר בחיקוק אחרת. סעיף 32 לחוק העונשין, הדן בעונש על סיוע, קובע חריגים לכלל מחצית העונש. סעיף 32(1) קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע הוא מאסר 20 שנה. הוראה זו, בהיותה ''דין החל על הביצוע העיקרי'' (במובן של קביעת עונש חובה), חלה גם על שידול באמצעות סעיף 34ד. מאחר שעבירת רצח בנסיבות מחמירות נושאת עונש מאסר עולם חובה, העונש המרבי שניתן לגזור על שמעון בגין שידול לעבירה זו הוא 20 שנות מאסר.',
    'הטעות הנפוצה היא ליישם את הכלל הכללי של השוואת עונש המשדל לעונש המבצע העיקרי ללא התחשבות בחריגים הספציפיים הקבועים בסעיף 32, המוחלים גם על שידול.', '["שידול לעבירה", "מאסר עולם חובה", "עונש מרבי", "חוק העונשין סעיף 34ד", "חוק העונשין סעיף 32(1)", "רצח בנסיבות מחמירות"]'::jsonb, '**וריאציה 1 — עונש מאסר עולם (לא חובה):** מהו העונש המרבי לשידול לעבירה שהעונש עליה הוא מאסר עולם (לא חובה)? ← 10 שנות מאסר, לפי סעיף 32(2) לחוק העונשין, המוחל על שידול.
**וריאציה 2 — שידול לרצח (לפני הרפורמה):** מה היה עונשו של משדל לרצח לפני הרפורמה בעבירות ההמתה? ← מאסר עולם ועונש זה בלבד, כפי שנקבע בעניין מסראווה (ע"פ 7894/03 מסראווה נ'' מדינת ישראל).
**וריאציה 3 — ניסיון לשידול לעבירה עם מאסר עולם חובה:** מהו העונש המרבי לניסיון לשידול לעבירה עם מאסר עולם חובה? ← 20 שנות מאסר, לפי סעיף 33(1) לחוק העונשין.', 'שידול לעבירה עם מאסר עולם חובה ← עונש מרבי 20 שנה (סעיפים 34ד ו-32(1) לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34ד", "חוק העונשין, תשל\"ז-1977, סעיף 32(1)", "חוק העונשין, תשל\"ז-1977, סעיף 32(2)", "חוק העונשין, תשל\"ז-1977, סעיף 33(1)", "ע\"פ 7894/03 מסראווה נ'' מדינת ישראל, תק-על 08(1) 2391 (2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'מאסר עולם.', false, 'טענה זו שגויה. מאסר עולם הוא העונש למבצע העיקרי, לא למשדל, במקרה של מאסר עולם חובה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', '20 שנות מאסר.', true, 'תשובה זו נכונה. סעיף 32(1) לחוק העונשין, המוחל על שידול באמצעות סעיף 34ד, קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע (ושל המשדל) הוא מאסר 20 שנה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', '10 שנות מאסר.', false, 'טענה זו שגויה. 10 שנות מאסר הוא העונש המרבי לסיוע או שידול לעבירה שהעונש עליה הוא מאסר עולם (לא חובה), לפי סעיף 32(2).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'מחצית העונש שייגזר על המבצע העיקרי.', false, 'טענה זו שגויה. זהו הכלל הכללי בסעיף 32, אך סעיף 32(1) קובע חריג ספציפי למקרים של מאסר עולם חובה, החל גם על שידול.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הבחנה בין שידול לסיוע',
    4, 'מהו ההבדל המהותי העיקרי בין שידול לעבירה לבין סיוע לעבירה, בהיבט של תרומתם לעבירה?', 'שאלה זו בוחנת את ההבחנה המהותית בין שידול לסיוע, שהיא קריטית להבנת צורות ההשתתפות בעבירה בדיני העונשין.', 'ההבחנה המהותית בין שידול (סעיף 30 לחוק העונשין) לסיוע (סעיף 31 לחוק העונשין) טמונה בתרומתם לעבירה. השידול מתמקד בהבאת אדם אחר לידי עשיית העבירה, כלומר בתרומת המשדל לכך שהמבצע העיקרי החליט (או החליט סופית) לבצע את העבירה. תרומתו של המשדל היא בעיקרה במישור המנטלי, ביצירת היסוד הנפשי אצל המשודל. לעומת זאת, הסיוע מתמקד במעשה עזרה למבצע העיקרי, כלומר בתרומה ליסוד העובדתי של העבירה, לאחר שההחלטה לבצע את העבירה כבר התקבלה. עונשו של המשדל זהה לעונשו של המבצע העיקרי (סעיף 34ד), בעוד שעונשו של המסייע הוא מחצית העונש (סעיף 32), מה שמצביע על חומרה יתרה שמייחס המחוקק לשידול ביחס לסיוע (עניין אסקין, עמ'' 82).',
    'הטעות הנפוצה היא לראות בשידול ובסיוע פעולות דומות, או לבלבל בין תזמונם או בין השפעתם על היסוד העובדתי מול היסוד הנפשי.', '["שידול לעבירה", "סיוע לעבירה", "יסוד עובדתי", "יסוד נפשי", "הבחנה בין צורות השתתפות", "חוק העונשין סעיף 30", "חוק העונשין סעיף 31"]'::jsonb, '**וריאציה 1 — עונש על שידול מול סיוע:** מהו ההבדל בענישה בין שידול לסיוע? ← עונשו של המשדל זהה לעונשו של המבצע העיקרי (סעיף 34ד), בעוד שעונשו של המסייע הוא מחצית העונש (סעיף 32).
**וריאציה 2 — סיוע לאחר מעשה:** מה ההבדל בין סיוע לעבירה לסיוע לאחר מעשה? ← סיוע לעבירה מתרחש לפני או בשעת ביצוע העבירה, ואילו סיוע לאחר מעשה (סעיף 260(א)) מתרחש לאחר ביצוע העבירה ונועד למנוע את תפיסת המבצע או גילוי העבירה.
**וריאציה 3 — תרומה ראשית מול משנית:** כיצד מתוארת תרומתם של המשדל והמסייע? ← תרומת המשדל נחשבת ''ראשית'' ו''מכרעת'', בעוד תרומת המסייע נחשבת ''משנית'' (יורם רבין, יניב ואקי, דיני עונשין - כרך א, 2014, עמ'' 171).', 'שידול ← גורם להחלטה לבצע עבירה (יסוד נפשי); סיוע ← עוזר בביצועה (יסוד עובדתי).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 30", "חוק העונשין, תשל\"ז-1977, סעיף 31", "חוק העונשין, תשל\"ז-1977, סעיף 32", "חוק העונשין, תשל\"ז-1977, סעיף 34ד", "ע\"פ 8469/99 אסקין נ'' מדינת ישראל, פ\"ד נה(2) 65 (2001)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'שידול מתרחש לפני העבירה, וסיוע מתרחש במהלכה.', false, 'טענה זו שגויה. סיוע יכול להתרחש גם לפני העבירה, ולא רק במהלכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'שידול מביא את המבצע להחליט לבצע את העבירה, ואילו סיוע מסייע בביצועה לאחר שההחלטה כבר התקבלה.', true, 'תשובה זו נכונה. השידול מתמקד ביצירת היסוד הנפשי אצל המבצע, בעוד הסיוע מתמקד בתרומה ליסוד העובדתי של העבירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שידול הוא תמיד עבירה חמורה יותר מסיוע, ללא קשר לנסיבות.', false, 'טענה זו שגויה. שידול נחשב חמור יותר ככלל, אך ישנם מקרים בהם סיוע יכול להיות חמור יותר משידול קל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שידול דורש כוונה מיוחדת, ואילו סיוע דורש רק מודעות.', false, 'טענה זו שגויה. גם שידול וגם סיוע דורשים יסוד נפשי של מחשבה פלילית, הכולל מודעות וכוונה (בשידול - כוונה להביא לביצוע, בסיוע - כוונה לסייע).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 16, '2019-S-S-Q16';
END
$$;

-- ============================================================
-- Q17 — 2019-S-S-Q17 — chapter=corporate subtopic=companies_formation
-- classifier_note: External-director eligibility under sec. 240(b) — merger context
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '1bee3be5-585d-4dcb-a7d6-81d143dc9705'::uuid;
  v_group_id uuid := '9a8678a3-5f91-4499-8f6f-38cbc0465e5b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '676619a6-09fe-4009-8430-f2d71fc2f541'::uuid;
  v_ang_1 uuid := '92ad3eb0-45e8-4637-ab41-f4533b55d009'::uuid;
  v_ang_2 uuid := '3cb49780-20b0-4afe-8a5a-5eb221afc453'::uuid;
  v_ang_3 uuid := '65d6d489-1fd4-46ae-b099-9dc9bf332274'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q17';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 17, '2019-S-S-Q17';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q17', v_chapter_id, v_subtopic_id, 'דוד כיהן כדירקטור חיצוני בתאגיד אחר כהגדרתו בסעיף 240(ב) לחוק החברות, התשנ"ט-1999, שהוא חברת יעד במיזוג החברות. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 17}'::jsonb, 'השאלה עוסקת בתנאי הכשירות למינוי דירקטור חיצוני, ובפרט בחריג לכלל ה''זיקה'' במקרה של מיזוג חברות. היא מדגישה את חשיבות עצמאות הדירקטור החיצוני ואת המנגנונים שנקבעו בחוק החברות ובתקנות כדי להבטיח אותה.', 'סעיף 240(ב) לחוק החברות, התשנ"ט-1999, קובע כי לא ימונה לדירקטור חיצוני יחיד שיש לו ''זיקה'' לחברה, לבעל השליטה בה, או לתאגיד אחר, במועד המינוי או בשנתיים שקדמו לו. ''זיקה'' מוגדרת, בין היתר, כקיום יחסי עבודה, קשרים עסקיים או מקצועיים דרך כלל, שליטה, או כהונה כנושא משרה. עם זאת, תקנה 3 לתקנות החברות (עניינים שאינם מהווים זיקה), תשס"ז-2006, קובעת חריג מפורש לכלל זה: ''מי שכיהן כדירקטור חיצוני בתאגיד אחר שהוא חברת יעד, לא ייחשב בשל כך, כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות''. מטרת חריג זה היא לאפשר המשכיות ויעילות במקרים של מיזוג, מבלי לפגוע בעצמאות הדירקטור החיצוני, שכן כהונתו הקודמת בחברת היעד אינה יוצרת תלות בחברה הקולטת. לכן, דוד לא ייחשב כבעל זיקה לחברה הקולטת.', 'הטעות הנפוצה היא ליישם את הכלל הכללי של ''זיקה'' כפי שמופיע בסעיף 240(ב) לחוק החברות, מבלי להתחשב בחריגים הספציפיים הקבועים בתקנות, ובפרט בתקנה 3 הנוגעת למיזוג חברות.',
    '["דירקטור חיצוני", "זיקה", "חוק החברות סעיף 240(ב)", "תקנות החברות (עניינים שאינם מהווים זיקה)", "מיזוג חברות", "חברת יעד", "חברה קולטת"]'::jsonb, '**וריאציה 1 — מטרת תקנות הזיקה:** מדוע נחקקו תקנות החברות (עניינים שאינם מהווים זיקה)? ← כדי להקל על הגדרת ''זיקה'' במקרים מסוימים, ולאפשר גמישות תוך שמירה על עקרון עצמאות הדח"צ (יוסף גרוס, חוק החברות, 2016, עמ'' 18).
**וריאציה 2 — זיקה לקרוב של בעל השליטה:** האם זיקה לקרוב של בעל השליטה פוסלת מינוי דח"צ? ← כן, סעיף 240(ב) לחוק החברות קובע במפורש שזיקה לקרוב של בעל השליטה פוסלת מינוי.
**וריאציה 3 — חשיבות הדח"צ:** מדוע קיימת חשיבות רבה לעצמאות הדירקטור החיצוני? ← הדח"צ משמש כ''שומר סף'' המגן על אינטרסי החברה ובעלי מניות המיעוט מפני ניצול לרעה מצד בעל השליטה (ע"א 7735/14 ורדניקוב נ'' אלוביץ, פסקה 157).', 'דח"צ בחברת יעד במיזוג ← לא נחשב בעל זיקה לחברה הקולטת (תקנה 3 לתקנות הזיקה), חריג לכלל הזיקה בסעיף 240(ב) לחוק החברות.', '["חוק החברות, תשנ\"ט-1999, סעיף 240(ב)", "תקנות החברות (עניינים שאינם מהווים זיקה), תשס\"ז-2006, תקנה 3", "יוסף גרוס חוק החברות (2016) | 8.2 חריג: מינוי דח\"צ בחברה בת בשליטה מלאה", "ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: External-director eligibility under sec. 240(b) — merger context | source_review_note: השאלה עוסקת בדיני חברות מהותיים (כשירות דירקטורים, זיקה), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני חברות'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הוא ייחשב בשל כך כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות.', false, 'טענה זו שגויה. כהונה כדירקטור חיצוני בחברת יעד אינה יוצרת זיקה לחברה הקולטת לאחר מיזוג, בהתאם לתקנות החברות (עניינים שאינם מהווים זיקה).', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הוא לא ייחשב בשל כך כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות.', true, 'תשובה זו נכונה. תקנה 3 לתקנות החברות (עניינים שאינם מהווים זיקה), תשס"ז-2006, קובעת במפורש כי מי שכיהן כדירקטור חיצוני בתאגיד אחר שהוא חברת יעד, לא ייחשב בשל כך כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הוא ייחשב בשל כך כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות, אלא אם ועדת הביקורת אישרה קודם למיזוג כי מדובר בזיקה זניחה.', false, 'טענה זו שגויה. החריג לזיקה במקרה של מיזוג אינו תלוי באישור ועדת הביקורת על זיקה זניחה, אלא הוא חריג מוחלט הקבוע בתקנה 3 לתקנות החברות (עניינים שאינם מהווים זיקה).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הוא ייחשב בשל כך כמי שיש לו זיקה לחברה הקולטת לאחר מיזוג החברות, אלא אם ועדת הביקורת אישרה קודם למינויו בחברה הממוזגת כי מדובר בזיקה זניחה.', false, 'טענה זו שגויה. החריג לזיקה במקרה של מיזוג אינו תלוי באישור ועדת הביקורת על זיקה זניחה, והוא חל באופן אוטומטי על כהונה קודמת בחברת יעד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'זיקה עקב קשרים עסקיים',
    1, 'דנה כיהנה כיועצת משפטית חיצונית לחברת "אלפא" במשך שלוש שנים. כעת היא מועמדת לכהן כדירקטורית חיצונית בחברת "בטא", שהיא בעלת השליטה בחברת "אלפא". האם דנה יכולה להתמנות כדירקטורית חיצונית בחברת "בטא"?', 'שאלה זו בוחנת את היקף הגדרת ''זיקה'' הפוסלת מינוי דירקטור חיצוני, תוך התמקדות בקשרים עם תאגידים אחרים שבשליטת בעל השליטה, כפי שקבוע בסעיף 240(ב) לחוק החברות.', 'סעיף 240(ב) לחוק החברות קובע כי לא ימונה לדירקטור חיצוני יחיד שיש לו, במועד המינוי או בשנתיים שקדמו למועד המינוי, זיקה לחברה, לבעל השליטה בחברה, או לתאגיד אחר שבעל השליטה בו הוא החברה או בעל השליטה בה. ''זיקה'' מוגדרת, בין היתר, כ''קיום יחסי עבודה, קיום קשרים עסקיים או מקצועיים דרך כלל''. במקרה זה, דנה כיהנה כיועצת משפטית חיצונית לחברת ''אלפא'', שהיא תאגיד שבשליטת ''בטא'' (בעלת השליטה). לכן, לדנה הייתה זיקה לתאגיד אחר שבשליטת בעל השליטה של חברת ''בטא'' בשלוש השנים שקדמו למועד המינוי, מה שפוסל את מינויה כדירקטורית חיצונית בחברת ''בטא''.',
    'הטעות הנפוצה היא להתמקד רק בזיקה ישירה לחברה או לבעל השליטה, ולהתעלם מהרחבת ההגדרה ל''תאגיד אחר'' שבשליטת בעל השליטה.', '["דירקטור חיצוני", "זיקה", "חוק החברות סעיף 240(ב)", "תאגיד אחר", "בעל שליטה", "קשרים עסקיים או מקצועיים"]'::jsonb, '**וריאציה 1 — זיקה לקרוב של בעל השליטה:** האם זיקה לקרוב של בעל השליטה פוסלת מינוי דח"צ? ← כן, סעיף 240(ב) לחוק החברות קובע במפורש שזיקה לקרוב של בעל השליטה פוסלת מינוי.
**וריאציה 2 — תקופת הזיקה:** מהי תקופת הבחינה לזיקה? ← במועד המינוי או בשנתיים שקדמו למועד המינוי (סעיף 240(ב) לחוק החברות).
**וריאציה 3 — זיקה זניחה:** האם קשרים עסקיים זניחים יכולים לא להוות זיקה? ← כן, בתנאים מסוימים הקבועים בתקנה 5 לתקנות החברות (עניינים שאינם מהווים זיקה), ובאישור ועדת הביקורת והאסיפה הכללית.', 'זיקה לתאגיד אחר שבשליטת בעל השליטה ← פוסלת מינוי דח"צ אם התקיימה בשנתיים שקדמו למינוי (סעיף 240(ב)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 240(ב)", "תקנות החברות (עניינים שאינם מהווים זיקה), תשס\"ז-2006, תקנה 5", "יוסף גרוס דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018) | 10.2 מבחן הזיקה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שחלפו שנתיים ממועד סיום כהונתה כיועצת משפטית.', false, 'טענה זו שגויה. דנה כיהנה כיועצת משפטית לחברת ''אלפא'', שהיא תאגיד אחר שבעל השליטה בו (חברת ''בטא'') הוא בעל השליטה בחברה בה היא מועמדת לכהן. סעיף 240(ב) לחוק החברות אוסר זיקה לתאגיד אחר בשנתיים שקדמו למועד המינוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שהייתה לה זיקה לחברה שבשליטת בעל השליטה בשנתיים שקדמו למועד המינוי.', true, 'תשובה זו נכונה. סעיף 240(ב) לחוק החברות קובע כי לא ימונה לדירקטור חיצוני מי שיש לו, במועד המינוי או בשנתיים שקדמו לו, זיקה לתאגיד אחר שבעל השליטה בו הוא החברה או בעל השליטה בה. קשרים עסקיים או מקצועיים דרך כלל נחשבים ל''זיקה''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם ועדת הביקורת של חברת "בטא" אישרה כי מדובר בזיקה זניחה.', false, 'טענה זו שגויה. החריג של זיקה זניחה (תקנה 5 לתקנות הזיקה) חל על קשרים עסקיים או מקצועיים עם החברה עצמה, ולא על זיקה לתאגיד אחר שבשליטת בעל השליטה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שיועץ משפטי חיצוני אינו יכול לכהן כדירקטור חיצוני בשום מקרה.', false, 'טענה זו שגויה. יועץ משפטי חיצוני יכול לכהן כדירקטור חיצוני, ובלבד שלא קיימת זיקה הפוסלת אותו לפי סעיף 240(ב) לחוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת "זיקה" בחוק החברות',
    2, 'מהי ההגדרה המרכזית ל"זיקה" הפוסלת מינוי דירקטור חיצוני, כפי שנקבעה בסעיף 240(ב) לחוק החברות?', 'שאלה זו מתמקדת בהגדרת המונח ''זיקה'' כפי שמופיעה בסעיף 240(ב) לחוק החברות, שהיא אבן יסוד בקביעת כשירותו של דירקטור חיצוני.', 'סעיף 240(ב) לחוק החברות מגדיר ''זיקה'' כ''קיום יחסי עבודה, קיום קשרים עסקיים או מקצועיים דרך כלל או שליטה, וכן כהונה כנושא משרה, למעט כהונה של דירקטור שמונה כדי לכהן כדירקטור חיצוני בחברה שעומדת להציע לראשונה מניות לציבור''. הגדרה זו נועדה להבטיח את עצמאותו של הדירקטור החיצוני ולמנוע מצב של ניגוד עניינים או תלות בבעל השליטה או בהנהלת החברה. הפסיקה והספרות מדגישות את הפרשנות המרחיבה למונח זה, כדי להגשים את תכלית החוק.',
    'הטעות הנפוצה היא לכלול בהגדרת ''זיקה'' קשרים שאינם מנויים במפורש בחוק, או להתעלם מהחריגים הקבועים בתקנות.', '["דירקטור חיצוני", "זיקה", "חוק החברות סעיף 240(ב)", "כשירות למינוי", "עצמאות דירקטורים", "ניגוד עניינים"]'::jsonb, '**וריאציה 1 — חריגים להגדרה:** האם ישנם חריגים להגדרת ''זיקה''? ← כן, השר רשאי לקבוע בתקנות עניינים מסוימים שלא יהוו זיקה, כפי שנעשה בתקנות החברות (עניינים שאינם מהווים זיקה) (סעיף 240(ב) לחוק החברות).
**וריאציה 2 — מטרת הזיקה:** מהי מטרת דרישת היעדר הזיקה? ← לחזק את עצמאות הדח"צ ואי-תלותו בבעל השליטה, כדי לאפשר לו למלא תפקידו כראוי כשומר סף (יוסף גרוס, דירקטורים ונושאי משרה בעידן הממשל התאגידי, 2018, עמ'' 19).
**וריאציה 3 — זיקה בחברה ללא בעל שליטה:** כיצד נבחנת זיקה בחברה שאין בה בעל שליטה? ← נבחנת זיקה ליו"ר הדירקטוריון, המנהל הכללי, בעל מניות מהותי או נושא המשרה הבכיר ביותר בתחום הכספים (סעיף 240(ב) לחוק החברות).', 'הגדרת ''זיקה'' (סעיף 240(ב)) ← יחסי עבודה, קשרים עסקיים/מקצועיים דרך כלל, שליטה, כהונה כנושא משרה.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 240(ב)", "יוסף גרוס דירקטורים ונושאי משרה בעידן הממשל התאגידי (2018) | 10.2 מבחן הזיקה", "אירית חביב-סגל דיני חברות - כרך א (2007) | 3.ג. חובת מינויים של דירקטורים חיצוניים, דירקטורים עצמאיים, ווועדת ביקורת 1. ההסדר בחוק החברות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'החזקת מניות בחברה או קשר משפחתי לבעל השליטה.', false, 'טענה זו שגויה. החזקת מניות כשלעצמה אינה זיקה פוסלת, אלא אם היא מקנה שליטה. קשר משפחתי לקרוב של בעל השליטה פוסל, אך זו אינה ההגדרה המלאה של ''זיקה''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיום יחסי עבודה, קיום קשרים עסקיים או מקצועיים דרך כלל, שליטה, או כהונה כנושא משרה.', true, 'תשובה זו נכונה. זוהי ההגדרה המפורשת של ''זיקה'' בסעיף 240(ב) לחוק החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כל קשר שיש בו כדי לפגוע בעצמאותו של הדירקטור, לפי שיקול דעת ועדת הביקורת.', false, 'טענה זו שגויה. למרות שזהו הרציונל, החוק קובע הגדרה ספציפית ל''זיקה'', ושיקול דעת ועדת הביקורת מוגבל לחריגים מסוימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קבלת תמורה מהחברה או מבעל השליטה, למעט גמול כדירקטור.', false, 'טענה זו שגויה. קבלת תמורה בניגוד לסעיף 244(ב) לחוק החברות פוסלת כהונה, אך אינה ההגדרה המרכזית של ''זיקה'' בסעיף 240(ב).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'זיקה בחברה בת בשליטה מלאה',
    3, 'רונית מכהנת כדירקטורית חיצונית בחברת "אם" ציבורית. חברת "אם" רכשה חברת "בת" בשליטה ובבעלות מלאה. האם רונית יכולה לכהן כדירקטורית חיצונית גם בחברת "בת" מבלי שייחשב הדבר לזיקה?', 'שאלה זו בוחנת את אחד החריגים החשובים לכלל הזיקה הפוסלת מינוי דירקטור חיצוני, והוא האפשרות לכהן כדירקטור חיצוני גם בחברות בנות בשליטה ובבעלות מלאה, בכפוף לתנאים ספציפיים הקבועים בתקנות.', 'תקנה 2 לתקנות החברות (עניינים שאינם מהווים זיקה), תשס"ז-2006, קובעת חריג לכלל הזיקה. היא מאפשרת לחברה ציבורית למנות דירקטור חיצוני לדירקטוריון בחברות הנמצאות בשליטתה ובבעלותה המלאה של חברה שבה הוא מכהן כדירקטור חיצוני, ולא יראו בכך זיקה. זאת, ובלבד שיתקיימו תנאים מצטברים, כגון הגבלת הגמול שרשאי הדירקטור החיצוני לקבל, פירוט החברות הבנות שבהן יכהן, וכן הגבלה על מספר החברות הבנות שבהן הוא יכול לכהן (עד ארבע חברות בנות). תנאים אלו נועדו לאזן בין הצורך ביעילות תאגידית לבין שמירה על עצמאותו של הדירקטור החיצוני.',
    'הטעות הנפוצה היא לחשוב שכל כהונה בשתי חברות יוצרת זיקה, או להתעלם מהתנאים המצטברים המורכבים הקבועים בתקנות לחריג זה.', '["דירקטור חיצוני", "זיקה", "חברות בנות", "שליטה ובבעלות מלאה", "תקנות החברות (עניינים שאינם מהווים זיקה)", "גמול דירקטורים"]'::jsonb, '**וריאציה 1 — מטרת החריג:** מדוע נקבע חריג לזיקה עבור חברות בנות? ← כדי לאפשר יעילות תאגידית בקבוצות חברות, תוך שמירה על עצמאות הדח"צ באמצעות הגבלות על גמול ומספר חברות (יוסף גרוס, חוק החברות, 2016, עמ'' 19).

**וריאציה 2 — הגבלת מספר חברות בנות:** כמה חברות בנות יכול דח"צ לכהן? ← עד ארבע חברות בנות (תקנה 2(6) לתקנות הזיקה).
**וריאציה 3 — שינוי גמול:** האם ניתן לשנות את הגמול של דח"צ בחברות בנות במהלך כהונתו? ← לא, ההחלטה בדבר תשלום גמול בחברות בנות לא תשתנה במשך כל תקופת כהונה של שלוש שנים (תקנה 2(2) לתקנות הזיקה).', 'דח"צ בחברת אם ובחברה בת בשליטה מלאה ← מותר בתנאים (תקנה 2 לתקנות הזיקה).',
    '["תקנות החברות (עניינים שאינם מהווים זיקה), תשס\"ז-2006, תקנה 2", "יוסף גרוס חוק החברות (2016) | 8.2 חריג: מינוי דח\"צ בחברה בת בשליטה מלאה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, כהונה בשתי חברות תמיד תיחשב לזיקה הפוסלת מינוי דירקטור חיצוני.', false, 'טענה זו שגויה. תקנות החברות (עניינים שאינם מהווים זיקה) קובעות חריג ספציפי לכהונה בחברות בנות בשליטה ובבעלות מלאה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, בתנאים מסוימים הקבועים בתקנות, כגון הגבלת גמול ומספר חברות בנות.', true, 'תשובה זו נכונה. תקנה 2 לתקנות החברות (עניינים שאינם מהווים זיקה) קובעת חריג לכלל הזיקה, המאפשר לדירקטור חיצוני לכהן גם בחברות בנות בשליטה ובבעלות מלאה, ובלבד שמתקיימים תנאים מצטברים כגון הגבלת הגמול ומספר החברות הבנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם חברת "בת" אינה חברה ציבורית.', false, 'טענה זו שגויה. החריג אינו תלוי בסוג החברה הבת (ציבורית או פרטית), אלא בתנאים המצטברים הקבועים בתקנה 2 לתקנות הזיקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן רונית ויתרה על גמול עבור כהונתה בחברת "בת".', false, 'טענה זו שגויה. ויתור על גמול אינו תנאי מספק, אלא ישנם תנאים נוספים ומורכבים יותר הקבועים בתקנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הפסקת כהונת דירקטור חיצוני',
    4, 'חברה ציבורית מעוניינת להפסיק את כהונתו של דירקטור חיצוני. באילו נסיבות ניתן להפסיק את כהונתו של דירקטור חיצוני?', 'שאלה זו עוסקת בהגנה על עצמאותם של דירקטורים חיצוניים באמצעות הגבלת האפשרות להפסיק את כהונתם, כפי שנקבע בסעיף 245(ב) לחוק החברות.', 'סעיף 245(ב) לחוק החברות קובע במפורש כי ''דירקטור חיצוני לא יפוטר וכהונתו לא תופסק אלא בהתאם להוראות סעיפים 233, 246 ו-247''. סעיף 233 עוסק בהפסקת כהונה על ידי בית המשפט, סעיף 246 עוסק במקרים בהם הדירקטור אינו עומד עוד בתנאי הכשירות (ואז האסיפה הכללית רשאית להחליט על הפסקת כהונתו ברוב מיוחס), וסעיף 247 עוסק בהפסקת כהונה על ידי בית המשפט בשל פקיעת תנאי הכשירות או הפרת חובת האמונים. הגבלה זו נועדה להבטיח את עצמאותו של הדירקטור החיצוני ולאפשר לו למלא את תפקידו כשומר סף ללא חשש מפיטורים שרירותיים (עניין ורדניקוב, פסקה 157).',
    'הטעות הנפוצה היא להשוות את מעמדו של הדירקטור החיצוני לזה של דירקטור רגיל, שניתן לפטרו על ידי האסיפה הכללית בכל עת (סעיף 29 לחוק החברות).', '["דירקטור חיצוני", "הפסקת כהונה", "חוק החברות סעיף 245(ב)", "עצמאות דירקטורים", "שומר סף", "פיטורים"]'::jsonb, '**וריאציה 1 — פיטורי דירקטור רגיל:** כיצד ניתן לפטר דירקטור רגיל? ← האסיפה הכללית רשאית לפטר דירקטור רגיל בכל עת, ברוב רגיל (סעיף 29 לחוק החברות).
**וריאציה 2 — תפקיד בית המשפט:** מתי בית המשפט יכול להפסיק כהונת דח"צ? ← במקרים של פגם בכשירותו או הפרת חובת אמונים (סעיפים 233 ו-247 לחוק החברות).
**וריאציה 3 — רוב נדרש להפסקת כהונה:** איזה רוב נדרש באסיפה הכללית להפסקת כהונת דח"צ שאינו עומד בתנאי כשירות? ← רוב מיוחס הדרוש למינויו (סעיף 246 לחוק החברות).', 'הפסקת כהונת דח"צ ← רק לפי סעיפים 233, 246, 247 לחוק החברות, להבטחת עצמאותו.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 245(ב)", "חוק החברות, תשנ\"ט-1999, סעיף 233", "חוק החברות, תשנ\"ט-1999, סעיף 246", "חוק החברות, תשנ\"ט-1999, סעיף 247", "ע\"א 7735/14 אילן ורדניקוב נ'' שאול אלוביץ (28.12.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'האסיפה הכללית רשאית לפטר אותו בכל עת, ברוב רגיל.', false, 'טענה זו שגויה. בניגוד לדירקטור רגיל, דירקטור חיצוני אינו ניתן לפיטורים על ידי האסיפה הכללית ברוב רגיל, כדי להבטיח את עצמאותו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'רק בהתאם להוראות סעיפים 233, 246 ו-247 לחוק החברות.', true, 'תשובה זו נכונה. סעיף 245(ב) לחוק החברות קובע במפורש כי דירקטור חיצוני לא יפוטר וכהונתו לא תופסק אלא בהתאם להוראות סעיפים 233 (הפסקת כהונה על ידי בית המשפט), 246 (אי עמידה בתנאי כשירות) ו-247 (הפסקת כהונה על ידי בית המשפט בשל פקיעת תנאי כשירות או הפרת אמונים).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'רק אם הדירקטור החיצוני הגיש את התפטרותו מרצונו החופשי.', false, 'טענה זו שגויה. התפטרות היא דרך אחת לסיום כהונה, אך החוק קובע גם דרכים אחרות להפסקת כהונה שלא מרצון הדירקטור, במקרים ספציפיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'רק אם הדירקטוריון החליט על כך ברוב מיוחס של שני שלישים מחבריו.', false, 'טענה זו שגויה. הדירקטוריון אינו מוסמך להפסיק כהונה של דירקטור חיצוני, אלא רק האסיפה הכללית בנסיבות מסוימות או בית המשפט.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 17, '2019-S-S-Q17';
END
$$;

