-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'fc6969ce-e701-447c-8657-fb97ea02a208'::uuid;
  v_group_id uuid := 'a6f9f224-2a01-4e12-8c57-f0422c816a78'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '676245f7-7ff5-4ad3-b36d-045c2c092763'::uuid;
  v_ang_1 uuid := 'f0499c4c-a1b8-42f4-bbc8-c393f35c702f'::uuid;
  v_ang_2 uuid := '2b8d67e2-f3f6-4ae2-b139-cd59911a5c4f'::uuid;
  v_ang_3 uuid := '2373650c-4872-4c0d-bf3e-7bb224389ab0'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q18';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 18, '2019-S-S-Q18';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q18', v_chapter_id, v_subtopic_id, 'מאיה חתמה חוזה עם חברת הפקות מטעמו של תאגיד שידור ציבורי, ולפיו הותנתה השתתפותה בטקס המוזיקה השנתי בכך שהיא תזכה בפרס האמנית המצטיינת לפי הערכתם של פאנל מוזיקאים מקצועיים. להפתעתה בחר פאנל המוזיקאים בהתאם להערכה שביצע להעניק את הפרס למשתתף אחר. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 18}'::jsonb, 'השאלה עוסקת בהיקף השפיטות של חוזים למתן פרס, ציון או תואר, בהתאם לסעיף 33 לחוק החוזים (חלק כללי). סעיף זה קובע כי הכרעה או הערכה מקצועית אינן נושא לדיון בבית משפט, אך הפסיקה צמצמה את תחולתו והבהירה כי הוא אינו חוסם ביקורת שיפוטית על פגמים מנהליים, חוסר סמכות, שרירות או אפליה.', 'סעיף 33 לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי ''חוזה שלפיו יינתן ציון, תואר, פרס וכיוצא באלה על פי הכרעה או הערכה של אחד הצדדים או של אדם שלישי, אין ההכרעה או ההערכה לפי החוזה נושא לדיון בבית משפט''. הוראה זו נועדה למנוע התערבות של בית המשפט בשיקול דעת מקצועי טהור (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב). עם זאת, הפסיקה, החל מע"א 838/87 שני נ'' אוניברסיטת תל-אביב, הבהירה כי סעיף 33 אינו חוסם דיון משפטי בשאלות שאינן נוגעות לשיקול הדעת המקצועי עצמו. בית המשפט רשאי לבחון האם ההחלטה התקבלה בסמכות, ללא שרירות, אפליה או שיקולים זרים. כלומר, בית המשפט לא יחליף את שיקול הדעת המקצועי של פאנל המוזיקאים לגבי מי ראוי לפרס, אך הוא רשאי לדון בתוקף ההתחייבות החוזית, בהשלכות של אי קיומה הנטען, ובפגמים פרוצדורליים או מנהליים שנפלו בהליך קבלת ההחלטה, כגון חוסר תום לב, אפליה או חוסר סמכות (ה"פ (מחוזי ת"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו).', 'הטעות הנפוצה היא לפרש את סעיף 33 כחסינות מוחלטת מביקורת שיפוטית על כל היבט של חוזה למתן ציון, תואר או פרס, במקום להבחין בין שיקול הדעת המקצועי לבין פגמים אחרים.',
    '["חוזה למתן פרס", "אי-שפיטות", "סעיף 33 לחוק החuזים", "שיקול דעת מקצועי", "ביקורת שיפוטית", "פגמים מנהליים", "חוסר סמכות"]'::jsonb, '**וריאציה 1 — מטרת הסעיף:** מהי מטרת סעיף 33 לחוק החוזים? ← למנוע התערבות בית המשפט בשיקול דעת מקצועי הקשור למתן ציון, תואר או פרס (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).
**וריאציה 2 — שפיטות היבטים אחרים:** אילו היבטים של חוזה למתן פרס כן שפיטים? ← שאלות הקשורות בכשרות הצדדים, סמכות, תוקף החוזה, חוסר תום לב, שרירות או אפליה (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 3 — פרס ישראל:** האם הרציונל של סעיף 33 חל גם על פרס ישראל? ← כן, הפסיקה הרחיבה את הרציונל של הסעיף גם להחלטות של ועדות ציבוריות המעניקות פרסים, תוך ריסון בביקורת שיפוטית (בג"ץ 8076/21 ועדת השופטים להענקת פרס ישראל נ'' שרת החינוך).', 'סעיף 33 לחוק החוזים ← אי-שפיטות הכרעה/הערכה מקצועית ← שפיטות פגמים פרוצדורליים/חוסר סמכות/אפליה/חוסר תום לב.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 33", "ע\"א 838/87 שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380 (1988)", "ה\"פ (מחוזי ת\"א) 15024-09-18 אברהם פרל נ'' אוניברסיטת תל אביב (03.04.2019)", "ה\"פ (מחוזי ת\"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו (31.10.2012)", "בג\"ץ 8076/21 ועדת השופטים להענקת פרס ישראל לשנת תשפ\"א בתחום חקר מדעי המחשב נ'' שרת החינוך (29.03.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Non-justiciable contract clause (חוזה בלתי שפיט) — judicial review of performance | source_review_note: השאלה עוסקת בדיני חוזים מהותיים (חוזים בלתי שפיטים), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני חוזים'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ההערכה לפי החוזה יכולה להיות נושא לדיון בבית משפט.', false, 'טענה זו שגויה. סעיף 33 לחוק החוזים קובע במפורש כי הערכה מקצועית למתן פרס אינה נושא לדיון בבית משפט.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ההערכה לפי החוזה אינה יכולה להיות נושא לדיון בבית משפט, אך בית המשפט רשאי לדון בהכרעה לפי החוזה.', false, 'טענה זו שגויה. סעיף 33 לחוק החוזים מתייחס הן ל''הכרעה'' והן ל''הערכה'' כבלתי שפיטות, כאשר שתיהן מתייחסות לשיקול דעת מקצועי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ההערכה לפי החוזה אינה יכולה להיות נושא לדיון בבית משפט, אך בית המשפט רשאי לדון בתוקף ההתחייבות ובהשלכות של אי קיומה הנטען.', true, 'תשובה זו נכונה. סעיף 33 לחוק החוזים מוציא מביקורת שיפוטית רק את ההכרעה או ההערכה המקצועית עצמה, אך אינו חוסם דיון משפטי בשאלות אחרות הקשורות לחוזה, כגון תוקפו, סמכות הגורם המחליט, פגמים מנהליים, שרירות, אפליה או חוסר תום לב.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ההערכה לפי החוזה אינה יכולה להיות נושא לדיון בבית משפט, אך בית המשפט רשאי לקבוע הערכה מטעמו.', false, 'טענה זו שגויה. בית המשפט אינו מחליף את שיקול הדעת המקצועי של הגורם המוסמך בשיקול דעתו שלו, ואינו קובע הערכה מטעמו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שפיטות החלטה אקדמית בעניין ציון',
    1, 'דניאל, סטודנטית לרפואה, נכשלה בבחינה בקורס חובה. היא טוענת כי נפלה טעות מהותית בבדיקת הבחינה שלה, וכי היא זכאית לציון עובר. האם בית המשפט יתערב בהחלטת האוניברסיטה בעניין הציון?', 'שאלה זו בוחנת את תחולת סעיף 33 לחוק החוזים על החלטות אקדמיות הנוגעות למתן ציונים, ואת היקף הביקורת השיפוטית המותרת במקרים אלו. היא מדגישה את ההבחנה בין שיקול דעת מקצועי לבין פגמים מנהליים.', 'סעיף 33 לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי ''חוזה שלפיו יינתן ציון, תואר, פרס וכיוצא באלה על פי הכרעה או הערכה של אחד הצדדים או של אדם שלישי, אין ההכרעה או ההערכה לפי החוזה נושא לדיון בבית משפט''. הוראה זו מבטאת את הרעיון שבית המשפט לא יתערב בשיקול דעת מקצועי של מוסד אקדמי בכל הקשור למתן ציונים. עם זאת, הפסיקה קבעה כי סעיף זה אינו חוסם דיון משפטי במקום שהשאלה הדורשת הכרעה אינה נוגעת לשיקול דעת מקצועי, אלא לפגמים מנהליים כגון חוסר סמכות, שרירות, אפליה או שיקולים זרים (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב). במקרה של טעות בבדיקת בחינה, בית המשפט לא יחליף את שיקול דעת הבודק, אך עשוי לבחון אם ההליך היה תקין והוגן.',
    'הטעות הנפוצה היא לחשוב שכל החלטה אקדמית חסינה מביקורת שיפוטית, או לחלופין, שבית המשפט יתערב בשיקול הדעת המקצועי עצמו.', '["סעיף 33 לחוק החוזים", "אי-שפיטות", "ציון אקדמי", "שיקול דעת מקצועי", "פגמים מנהליים", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — טעות בחישוב ציון:** האם בית המשפט יתערב אם הוכח שהאוניברסיטה טעתה בחישוב סופי של הציון? ← כן, טעות אריתמטית אינה שיקול דעת מקצועי ושפיטה (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).

**וריאציה 2 — אפליה בקביעת ציון:** האם בית המשפט יתערב אם הוכח שהציון ניתן מתוך אפליה? ← כן, אפליה היא פגם מנהלי חמור המצדיק התערבות (ה"פ (מחוזי חי'') 1682-04-20 חנצ''ין נ'' הטכניון).
**וריאציה 3 — שינוי קריטריונים רטרואקטיבי:** האם בית המשפט יתערב אם האוניברסיטה שינתה קריטריונים למתן ציון רטרואקטיבית? ← כן, שינוי רטרואקטיבי עשוי להיחשב כחוסר תום לב או שרירות, ושפיט (ה"פ (מחוזי חי'') 52133-10-19 בן חמו נ'' הטכניון).', 'ציון בחינה ← אי-שפיטות ההערכה המקצועית ← שפיטות פגמים בהליך/אפליה/חוסר סמכות (סעיף 33 לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 33", "ע\"א 838/87 שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380 (1988)", "ה\"פ (מחוזי ת\"א) 15024-09-18 אברהם פרל נ'' אוניברסיטת תל אביב (03.04.2019)", "ה\"פ (מחוזי חיפה) 1682-04-20 אלון חנצ''ין נ'' הטכניון - מכון טכנולוגי לישראל (24.12.2020)", "ה\"פ (מחוזי חי'') 52133-10-19 ליאור בן חמו נ'' הטכניון - מכון טכנולוגי לישראל (13.09.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, אם יוכיח דניאל כי נפלה טעות אובייקטיבית בחישוב הציון.', false, 'טענה זו שגויה. גם טעות אובייקטיבית בחישוב הציון נחשבת לחלק מההערכה המקצועית שאינה שפיטה, אלא אם היא מעידה על פגם חמור יותר כמו שרירות או חוסר סמכות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, בית המשפט לא יתערב בשיקול דעת מקצועי הקשור למתן ציון, אלא אם הוכחו פגמים מנהליים חמורים.', true, 'תשובה זו נכונה. סעיף 33 לחוק החוזים מונע התערבות בשיקול דעת מקצועי בענייני ציונים, אך מאפשר ביקורת על פגמים מנהליים כגון שרירות, אפליה או חוסר סמכות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, בית המשפט יחליף את שיקול דעתה של האוניברסיטה בשיקול דעתו ויקבע את הציון הנכון.', false, 'טענה זו שגויה. בית המשפט אינו מחליף את שיקול הדעת המקצועי של מוסד אקדמי בשיקול דעתו שלו, אלא בוחן את חוקיות ההחלטה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מערכת היחסים בין סטודנט לאוניברסיטה אינה חוזית ולכן אינה שפיטה כלל.', false, 'טענה זו שגויה. מערכת היחסים בין סטודנט לאוניברסיטה היא בעלת אופי חוזי, ורק ההכרעה או ההערכה המקצועית אינן שפיטות, לא כלל היחסים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היקף סעיף 33 לחוק החוזים',
    2, 'מהו היקף אי-השפיטות הקבוע בסעיף 33 לחוק החוזים (חלק כללי)?', 'שאלה זו מבהירה את גבולות השפיטות של חוזים למתן ציון, תואר או פרס, כפי שנקבעו בסעיף 33 לחוק החוזים. היא מדגישה כי אי-השפיטות מתייחסת לשיקול הדעת המקצועי, אך אינה מונעת ביקורת שיפוטית על פגמים אחרים.', 'סעיף 33 לחוק החוזים (חלק כללי) קובע כי הכרעה או הערכה מקצועית למתן ציון, תואר או פרס אינה נושא לדיון בבית משפט. אולם, כפי שנקבע בע"א 838/87 שני נ'' אוניברסיטת תל-אביב, אין בהוראה זו כדי להסיר מאופי היחסים בין סטודנט לאוניברסיטה את מהותם החוזית, ואין בה כדי לחסום דיון משפטי במקום שהשאלה הדורשת הכרעה אינה נוגעת לשיקול דעת מקצועי. בית המשפט רשאי להתערב כאשר מדובר בחוסר סמכות, שרירות, אפליה או פגמים אחרים הפוגעים בשיקול הדעת של רשות מקצועית מחליטה. כלומר, בית המשפט לא יחליף את שיקול הדעת המקצועי, אך יבחן את תקינות ההליך ואת חוקיות ההחלטה.',
    'הטעות הנפוצה היא לפרש את סעיף 33 כחסינות מוחלטת מביקורת שיפוטית, במקום כהגבלה על התערבות בשיקול דעת מקצועי טהור.', '["סעיף 33 לחוק החוזים", "שפיטות", "אי-שפיטות", "שיקול דעת מקצועי", "פגמים מנהליים", "חוסר סמכות", "אפליה"]'::jsonb, '**וריאציה 1 — מטרת הסעיף:** מהי מטרת סעיף 33? ← למנוע התערבות בית המשפט בשיקול דעת מקצועי הקשור למתן ציון, תואר או פרס (ה"פ (מחוזי ת"א) 15024-09-18 פרל נ'' אוניברסיטת תל אביב).
**וריאציה 2 — שפיטות נורמטיבית מול מוסדית:** כיצד סעיף 33 מתיישב עם שפיטות נורמטיבית? ← הסעיף אינו שולל שפיטות נורמטיבית (קיום נורמה משפטית), אלא קובע אי-שפיטות מוסדית (אי-התערבות בית המשפט) בנוגע לשיקול הדעת המקצועי (גבריאלה שלו ואפי צמח, דיני חוזים, 2019, עמ'' 15).
**וריאציה 3 — דוגמאות לפגמים שפיטים:** אילו פגמים בהחלטה אקדמית יהיו שפיטים? ← חוסר סמכות, שרירות, אפליה, שיקולים זרים או פגמים פרוצדורליים (ה"פ (מחוזי ת"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו).', 'סעיף 33 ← אי-שפיטות שיקול דעת מקצועי ← שפיטות פגמים מנהליים/חוסר סמכות/אפליה (ע"א שני).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 33", "ע\"א 838/87 שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380 (1988)", "ה\"פ (מחוזי ת\"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו (31.10.2012)", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | פרק 21 חוזים בלתי אכיפים וחוזים בלתי שפיטים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הסעיף מוציא מביקורת שיפוטית את כלל היחסים החוזיים הקשורים למתן ציון, תואר או פרס.', false, 'טענה זו שגויה. הסעיף מוציא מביקורת שיפוטית רק את ההכרעה או ההערכה המקצועית, ולא את כלל היחסים החוזיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הסעיף מונע התערבות בשיקול דעת מקצועי הקשור למתן ציון, תואר או פרס, אך אינו חוסם דיון משפטי בפגמים מנהליים או בחוסר סמכות.', true, 'תשובה זו נכונה. סעיף 33 מבטא את הרעיון שבית המשפט אינו מחליף שיקול דעת מקצועי, אך הוא רשאי לבחון חוסר סמכות, שרירות, אפליה או פגמים אחרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הסעיף חל רק על חוזים בין גופים פרטיים ואינו רלוונטי להחלטות של מוסדות אקדמיים או רשויות ציבוריות.', false, 'טענה זו שגויה. הפסיקה הרחיבה את הרציונל של סעיף 33 גם להחלטות של מוסדות אקדמיים ורשויות ציבוריות, באמצעות סעיף 61(ב) לחוק החוזים או בדרך של השראה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הסעיף מאפשר לבית המשפט לבחון את סבירות ההכרעה או ההערכה, אך לא את תוכנה המקצועי.', false, 'טענה זו שגויה. בית המשפט אינו בוחן את סבירות ההכרעה או ההערכה המקצועית עצמה, אלא את תקינות ההליך שהוביל אליה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שפיטות פרס המוענק על ידי רשות ציבורית',
    3, 'שר החינוך החליט שלא לאשר את המלצת ועדת השופטים להעניק את פרס ישראל לפרופ'' כהן, בטענה כי פרופ'' כהן הביע עמדות פוליטיות קיצוניות. פרופ'' כהן עתר לבג"ץ בטענה שהחלטת השר אינה חוקית. מה הדין?', 'שאלה זו עוסקת בשפיטות החלטות הנוגעות להענקת פרס ישראל, המוענק על ידי רשות ציבורית. היא בוחנת את היקף הביקורת השיפוטית של בג"ץ על החלטות אלו, תוך התייחסות לרציונל של סעיף 33 לחוק החוזים והחריגים לו במשפט המנהלי.', 'החלטות הנוגעות להענקת פרס ישראל, אף שהן כפופות לכללי המשפט הציבורי, נחשבות כ''כמעט חסינות'' מפני התערבות שיפוטית, בדומה לרציונל של סעיף 33 לחוק החוזים (בג"ץ 8076/21 ועדת השופטים להענקת פרס ישראל נ'' שרת החינוך). בית המשפט העליון נוקט בריסון רב ויתערב רק במקרים חריגים וקיצוניים, כגון כאשר השר שקל שיקולים שאינם ממין העניין (כמו עמדות פוליטיות שאינן קשורות לפועלו המקצועי של המועמד), פעל בשרירות, או כאשר נפלו פגמים דיוניים חמורים (בג"ץ 2199/21 ועדת השופטים להענקת פרס ישראל נ'' שר החינוך). במקרה של פרופ'' כהן, אם השר פסל את מועמדותו בשל עמדות פוליטיות שאינן קשורות לתחום המקצועי שבגינו הומלץ לפרס, הדבר עשוי להיחשב כשיקול זר המצדיק התערבות בג"ץ.',
    'הטעות הנפוצה היא להניח שכל החלטה של רשות ציבורית שפיטה באופן מלא, או לחלופין, שכל החלטה על פרס חסינה לחלוטין מביקורת.', '["פרס ישראל", "שפיטות", "משפט מינהלי", "סעיף 33 לחוק החוזים", "שיקול דעת שר", "שיקולים זרים", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — התערבות בשיקולים זרים:** האם בג"ץ יתערב אם השר פסל מועמד לפרס ישראל בשל חתימה על עצומה פוליטית? ← כן, כפי שקרה בעניין גולדרייך, אם השיקול אינו ממין העניין (בג"ץ 8076/21 ועדת השופטים להענקת פרס ישראל נ'' שרת החינוך).
**וריאציה 2 — פגמים דיוניים:** האם בג"ץ יתערב אם ועדת הפרס לא הייתה מודעת לעובדות מהותיות לגבי המועמד? ← כן, כפי שקרה בעניין שניצר, פגם דיוני כזה מצדיק התערבות (בג"ץ 2205/97 מסאלה נ'' שר החינוך והתרבות).
**וריאציה 3 — אמירות גזעניות:** האם אמירות גזעניות של מועמד לפרס ישראל יכולות להצדיק שלילת הפרס? ← כן, במקרים קיצוניים של ביזוי והשפלה קשים, גם אם אינן קשורות לפועלו המקצועי (בג"ץ 3401/24 בתיה כהנא דרור נ'' שר החינוך).', 'פרס ישראל ← כמעט חסין מביקורת שיפוטית (רציונל סעיף 33) ← התערבות רק במקרים חריגים וקיצוניים (פגמים מנהליים חמורים, שיקולים זרים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 33", "בג\"ץ 8076/21 ועדת השופטים להענקת פרס ישראל לשנת תשפ\"א בתחום חקר מדעי המחשב נ'' שרת החינוך (29.03.2022)", "בג\"ץ 2199/21 ועדת השופטים להענקת פרס ישראל לשנת תשפ\"א בתחום חקר המתמטיקה, חקר מדעי המחשב נ'' שר החינוך (12.08.2021)", "בג\"ץ 3401/24 בתיה כהנא דרור נ'' שר החינוך (08.05.2024)", "בג\"ץ 2205/97 מסאלה נ'' שר החינוך והתרבות, פ\"ד נא(1) 233 (1997)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'בג"ץ לא יתערב כלל, שכן פרס ישראל הוא נושא בלתי שפיט לחלוטין.', false, 'טענה זו שגויה. למרות הגישה המרוסנת, בג"ץ אינו רואה את נושא פרס ישראל כבלתי שפיט לחלוטין, ויכול להתערב במקרים חריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'בג"ץ יתערב רק אם הוכח שהשר פעל בחוסר סמכות מובהק, ולא בשל שיקולים זרים.', false, 'טענה זו שגויה. בג"ץ יתערב גם במקרים של שיקולים זרים, כפי שקרה בעניין גולדרייך, ולא רק בחוסר סמכות מובהק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'בג"ץ יתערב רק במקרים חריגים וקיצוניים, אם הוכח שהשר שקל שיקולים שאינם ממין העניין או פעל בשרירות.', true, 'תשובה זו נכונה. הפסיקה קבעה כי התערבות בהחלטות הנוגעות לפרס ישראל שמורה למקרים חריגים וקיצוניים, כגון שקילת שיקולים זרים או שרירות, תוך שמירה על עקרון אי-ההתערבות בשיקול הדעת המקצועי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בג"ץ יחליף את שיקול דעתו של השר ויקבע אם פרופ'' כהן ראוי לפרס.', false, 'טענה זו שגויה. בג"ץ אינו מחליף את שיקול דעתה של הרשות המנהלית בשיקול דעתו שלו, אלא בוחן את חוקיות ההחלטה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'שפיטות היבטים חוזיים נלווים',
    4, 'אביב הגישה מועמדות ללימודי רפואה באוניברסיטה, ועמדה בכל קריטריוני הקבלה שפורסמו. למרות זאת, מועמדותה נדחתה ללא הסבר, בעוד מועמדים אחרים עם נתונים זהים התקבלו. אביב טוענת לאפליה. האם בית המשפט יתערב במקרה זה?', 'שאלה זו בוחנת את גבולות סעיף 33 לחוק החוזים בהקשר של יחסי סטודנט-אוניברסיטה, ומדגישה כי למרות אי-השפיטות של שיקול הדעת המקצועי, בית המשפט יתערב במקרים של פגמים מנהליים כגון אפליה.', 'מערכת היחסים בין סטודנט לאוניברסיטה היא בעלת אופי חוזי, והתקנונים והקטלוגים של האוניברסיטה נחשבים לחוזים אחידים (ה"פ (מחוזי חי'') 52133-10-19 בן חמו נ'' הטכניון). סעיף 33 לחוק החוזים מונע התערבות בשיקול דעת מקצועי הקשור למתן תואר או ציון, אך אינו חוסם דיון משפטי בשאלות שאינן נוגעות לשיקול דעת מקצועי טהור. כאשר סטודנט עומד בכל קריטריוני הקבלה ומועמדותו נדחית ללא הסבר, בעוד מועמדים זהים מתקבלים, עולה חשש לאפליה. אפליה היא פגם מנהלי חמור המצדיק התערבות שיפוטית, שכן היא פוגעת בעקרונות של שוויון והגינות, ואינה נחשבת לחלק משיקול הדעת המקצועי החסין מביקורת (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב). בית המשפט לא יקבע את קריטריוני הקבלה, אך יבחן אם האוניברסיטה פעלה בסמכות ובהגינות ביישומם.',
    'הטעות הנפוצה היא להניח שכל החלטה של מוסד אקדמי, כולל החלטות קבלה, חסינה מביקורת שיפוטית בשל סעיף 33.', '["שפיטות", "אפליה", "קריטריוני קבלה", "חופש אקדמי", "סעיף 33 לחוק החוזים", "יחסים חוזיים", "פגמים מנהליים"]'::jsonb, '**וריאציה 1 — קביעת קריטריונים:** האם בית המשפט יתערב בקביעת קריטריוני קבלה ללימודים? ← לא, קביעת קריטריונים היא שיקול דעת אקדמי טהור שאינו שפיט (ה"פ (מחוזי ת"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו).
**וריאציה 2 — חוסר סמכות:** האם בית המשפט יתערב אם ההחלטה על דחיית המועמדות התקבלה על ידי גורם לא מוסמך? ← כן, חוסר סמכות הוא פגם שפיט (ע"א 838/87 שני נ'' אוניברסיטת תל-אביב).
**וריאציה 3 — שרירות:** האם בית המשפט יתערב אם האוניברסיטה דחתה מועמדות באופן שרירותי וללא נימוק? ← כן, שרירות היא פגם מנהלי המצדיק התערבות (ה"פ (מחוזי חי'') 17162-11-14 פליק נ'' המרכז האקדמי כרמל).', 'קריטריונים אקדמיים ← אי-שפיטות קביעתם ← שפיטות יישומם (אפליה, חוסר סמכות, שרירות).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 33", "ע\"א 838/87 שני נ'' אוניברסיטת תל-אביב, פ\"ד מב(2) 380 (1988)", "ה\"פ (מחוזי ת\"א) 23174-09-12 ש.ב. נ'' המכללה האקדמית תל אביב יפו (31.10.2012)", "ה\"פ (מחוזי חי'') 17162-11-14 אמיר פליק נ'' המרכז האקדמי כרמל בע\"מ (חל\"צ) (28.04.2015)", "ה\"פ (מחוזי חי'') 52133-10-19 ליאור בן חמו נ'' הטכניון - מכון טכנולוגי לישראל (13.09.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, קביעת קריטריוני קבלה ויישומם הם שיקול דעת אקדמי טהור שאינו שפיט.', false, 'טענה זו שגויה. בעוד שקביעת הקריטריונים היא שיקול דעת אקדמי, יישומם באופן מפלה או שרירותי אינו חסין מביקורת שיפוטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט יתערב אם הוכח שהאוניברסיטה פעלה באפליה, שכן סעיף 33 אינו חוסם דיון בפגמים מנהליים.', true, 'תשובה זו נכונה. סעיף 33 לחוק החוזים אינו מונע התערבות שיפוטית במקרים של אפליה, שרירות או חוסר סמכות, גם אם מדובר בהחלטה של מוסד אקדמי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, מכיוון שהחלטה על קבלה ללימודים היא בגדר ''הכרעה'' שאינה נושא לדיון בבית משפט.', false, 'טענה זו שגויה. ההכרעה עצמה אינה שפיטה, אך הדרך שבה התקבלה ההכרעה, ובפרט אם היא נגועה באפליה, כן שפיטה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, בית המשפט יורה לאוניברסיטה לקבל את אביב ללימודים, שכן היא עמדה בקריטריונים.', false, 'טענה זו שגויה. בית המשפט לא יורה על קבלה ללימודים, אלא יבחן את תקינות ההליך ועשוי להורות על בחינה מחודשת של המועמדות, אם ימצא פגם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 18, '2019-S-S-Q18';
END
$$;

-- ============================================================
-- Q19 — 2019-S-S-Q19 — chapter=contracts subtopic=limitation
-- classifier_note: Limitation period start for cancellation of conditional/illegal contract
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '1c6fb855-9d93-4b53-bb17-3bbaa1b1ebf3'::uuid;
  v_group_id uuid := 'fc66c2ae-1175-4c4f-a658-d2d750d5ee28'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '0bf7e286-dc46-44cb-87b0-7f56a60666b0'::uuid;
  v_ang_1 uuid := '1a7742d1-e85d-4d4f-bc07-3819e37312ba'::uuid;
  v_ang_2 uuid := '786c6518-0b1d-400c-827d-a922a2ce93fe'::uuid;
  v_ang_3 uuid := 'e41cd8b9-3e5b-4d68-b726-d35c99ebd7ae'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q19';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 19, '2019-S-S-Q19';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q19', v_chapter_id, v_subtopic_id, 'דוד מעוניין לתבוע ביטול חוזה שכרת, שנקבע בו כי ייכנס לתוקף רק אם יתקיים תנאי חיצוני לחוזה שאינו תלוי בצדדים. טענתו היא שהתנאי שעליו הסכימו הופך את החוזה לבלתי חוקי. ממתי תחל להימנות תקופת ההתיישנות של התביעה?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 19}'::jsonb, 'השאלה עוסקת בהיבט ספציפי של דיני ההתיישנות, הנוגע למועד תחילת מרוץ ההתיישנות בתביעה לביטול חוזה בלתי חוקי, במיוחד כאשר החוזה כולל תנאי מתלה. היא מדגישה את הכלל לפיו עילת אי-החוקיות נולדת במועד כריתת החוזה, ללא קשר למועד התקיימות התנאי המתלה.', 'סעיף 6 לחוק ההתיישנות, התשי"ח-1958, קובע כי תקופת ההתיישנות מתחילה ביום שבו נולדה עילת התובענה. כאשר מדובר בתביעה לבטלות חוזה בלתי חוקי, עילת אי-החוקיות נוצרת במועד כריתת החוזה, ולכן מרוץ ההתיישנות יחל במועד זה. הפסיקה קבעה כי מרוץ ההתיישנות יחל במועד כריתת החוזה גם אם החוזה הוא על תנאי ואי-החוקיות נוגעת לתנאי, שכן חוזה על תנאי הוא חוזה שלם בעל תוקף מלא מעת כריתתו (רע"א 6774/19 אפרידר החברה לשיכון ופיתוח לישראל בע"מ נ'' עיריית ראש העין, פסקה 27; ע"א 4752/14 נכסי רמת אביב בע"מ נ'' עיריית תל-אביב, כפי שמצוטט בנבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות, עמ'' 77). לפיכך, גם אם התנאי המתלה טרם התקיים, עצם קיומו של החוזה הבלתי חוקי הוא עילת התביעה, ומרוץ ההתיישנות מתחיל במועד כריתתו.', 'הטעות הנפוצה היא לחשוב שתנאי מתלה מעכב את תחילת מרוץ ההתיישנות עד להתקיימותו, או שמועד הגילוי של אי-החוקיות הוא הקובע, במקום מועד כריתת החוזה.',
    '["התיישנות", "עילת תביעה", "חוזה בלתי חוקי", "חוזה על תנאי", "תנאי מתלה", "מועד כריתת חוזה"]'::jsonb, '**וריאציה 1 — תביעת השבה בחוזה פסול:** מתי תחל התיישנות בתביעת השבה בגין חוזה פסול? ← ביום שבו נפל פסול בחוזה או ביום שבו טובת ההנאה ניתנה, לפי המאוחר מביניהם (רע"א 6774/19 אפרידר).
**וריאציה 2 — תביעה לביטול תנאי מקפח:** מתי תחל התיישנות בתביעה לביטול תנאי מקפח בחוזה אחיד? ← ממועד כריתת החוזה (רע"א 6734/09 סלון ירושלים מוצרי חשמל בע"מ ואח'' נ'' כלליר תפעול ואחזקה בע"מ).
**וריאציה 3 — חוזה על תנאי ותוקפו:** האם חוזה על תנאי הוא חוזה שלם מרגע כריתתו? ← כן, חוזה על תנאי הוא חוזה שלם מרגע כריתתו, ואין השלכה רטרואקטיבית לעניין תוקפו (ע"א 489/89 אלדר שרון נ'' שבח מקרקעין).', 'התיישנות תביעה לבטלות חוזה בלתי חוקי (גם אם על תנאי) ← ממועד כריתת החוזה (סעיף 6 לחוק ההתיישנות).', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 6", "רע\"א 6774/19 אפרידר החברה לשיכון ופיתוח לישראל בע\"מ נ'' עיריית ראש העין (25.05.2021)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות", "ע\"א 4752/14 נכסי רמת אביב בע\"מ נ'' עיריית תל-אביב (16.06.2016)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Limitation period start for cancellation of conditional/illegal contract | source_review_note: השאלה עוסקת בדיני התיישנות בהקשר של דיני חוזים (חוזים בלתי חוקיים וחוזים על תנאי), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני התיישנות'' או ''דיני חוזים'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ממועד התקיימות התנאי.', false, 'טענה זו שגויה. מועד התקיימות התנאי אינו רלוונטי לתחילת מרוץ ההתיישנות בתביעה לבטלות חוזה בלתי חוקי, שכן החוזה נחשב שלם מרגע כריתתו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מהמועד שבו דוד גילה כי התנאי אינו חוקי לטענתו.', false, 'טענה זו שגויה. מועד הגילוי רלוונטי לחריגים לכלל ההתיישנות (כגון תרמית או התיישנות שלא מדעת), אך לא למועד הולדת עילת התביעה לבטלות חוזה בלתי חוקי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ממועד גילוי דוד על התקיימות התנאי.', false, 'טענה זו שגויה. מועד הגילוי על התקיימות התנאי אינו משפיע על מועד תחילת מרוץ ההתיישנות בתביעה לבטלות חוזה בלתי חוקי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ממועד כריתת החוזה.', true, 'תשובה זו נכונה. בתביעה לבטלות חוזה בלתי חוקי, מרוץ ההתיישנות יחל במועד כריתת החוזה, שכן עילת אי-החוקיות נוצרת במועד זה, גם אם החוזה הוא על תנאי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מועד תחילת התיישנות בתביעת הפרת חוזה',
    1, 'ראובן חתם על חוזה עם שמעון לבניית בית. שמעון הפר את החוזה בכך שלא השלים את עבודות חיזוק היסודות במועד שנקבע. 8 שנים לאחר מכן, הבית התמוטט עקב ליקויים ביסודות. מתי תחל תקופת ההתיישנות לתביעת פיצויים בגין נזק התמוטטות הבית?', 'שאלה זו עוסקת במועד תחילת מרוץ ההתיישנות בתביעה חוזית, תוך הבחנה בין תביעה לאכיפה/ביטול לבין תביעה לפיצויים בגין נזק שנגרם עקב ההפרה, בהתאם לסעיף 6 לחוק ההתיישנות.', 'סעיף 6 לחוק ההתיישנות, התשי"ח-1958, קובע כי תקופת ההתיישנות מתחילה ביום שבו נולדה עילת התובענה. בתביעה לאכיפת חוזה או לביטולו עקב הפרה, מרוץ ההתיישנות יחל במועד הפרת החוזה, שכן כבר אז יש בידי התובע עילת תביעה בשלה (ע"א 3599/94 שמעון יופיטר נ'' בנק לאומי לישראל בע"מ). לעומת זאת, בתביעה לפיצויים בגין נזק שנגרם עקב הפרת חוזה, הנזק הוא חלק מעילת התביעה (סעיף 10 לחוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970), ולכן מרוץ ההתיישנות יחל במועד קרות הנזק (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות, עמ'' 76). במקרה זה, מדובר בתביעה לפיצויים בגין נזק התמוטטות הבית, ולכן מרוץ ההתיישנות יחל במועד התמוטטות הבית, שהוא מועד קרות הנזק.',
    'הטעות הנפוצה היא בלבול בין מועד ההפרה למועד קרות הנזק כתחילת מרוץ ההתיישנות, בהתאם לסעד המבוקש.', '["התיישנות", "עילת תביעה", "הפרת חוזה", "פיצויים", "מועד קרות נזק", "אכיפת חוזה"]'::jsonb, '**וריאציה 1 — תביעה לאכיפה:** מתי תחל התיישנות בתביעה לאכיפת חוזה? ← ממועד הפרת החוזה (ע"א 3599/94 יופיטר).
**וריאציה 2 — הפרה מתמשכת:** מתי תחל התיישנות בהפרה מתמשכת (כגון אי-תשלום דמי שכירות)? ← כל יום של הפרה יוצר עילת תביעה חדשה שמניין ההתיישנות מתחיל למחרת היום (רע"א 8856/06 גרינפלד נ'' הירקון בע"מ).
**וריאציה 3 — כוח תביעה קונקרטי:** מהו המבחן ל"כוח תביעה" לצורך התיישנות? ← מועד קיומה של עילת תביעה קונקרטית בידי התובע, המקיימת בידיו מערכת עובדות חיוניות הנדרשות לביסוס תביעתו (ע"א 9382/02 בולוס ובניו - חברה לאירוח ותיירות בע"מ נ'' בנק דיסקונט למשכנתאות בע"מ).', 'תביעת פיצויים על הפרת חוזה ← התיישנות ממועד קרות הנזק; תביעת אכיפה/ביטול ← התיישנות ממועד ההפרה.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 6", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 10", "ע\"א 3599/94 שמעון יופיטר נ'' בנק לאומי לישראל בע\"מ, פ\"ד נ(5) 423 (1996)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות", "טל חבקין התיישנות (2021) | פרק שמיני סעיף 6 לחוק ההתיישנות - תחילת ההתיישנות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ממועד הפרת החוזה (אי השלמת העבודות).', false, 'טענה זו שגויה. מועד הפרת החוזה הוא תחילת מרוץ ההתיישנות לתביעה לאכיפה או ביטול החוזה, אך לא לתביעת פיצויים בגין נזק שנגרם עקב ההפרה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ממועד התמוטטות הבית (קרות הנזק).', true, 'תשובה זו נכונה. בתביעה לפיצויים בגין נזק שנגרם עקב הפרת חוזה, הנזק הוא חלק מעילת התביעה, ולכן מרוץ ההתיישנות יחל במועד קרות הנזק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ממועד כריתת החוזה.', false, 'טענה זו שגויה. מועד כריתת החוזה אינו רלוונטי לתחילת מרוץ ההתיישנות בתביעה לפיצויים בגין הפרת חוזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ממועד גילוי הנזק על ידי ראובן.', false, 'טענה זו שגויה. מועד הגילוי רלוונטי לחריגים לכלל ההתיישנות (כגון התיישנות שלא מדעת), אך לא למועד הולדת עילת התביעה לפיצויים בגין נזק שנגרם עקב הפרה, אשר נולדת במועד קרות הנזק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מאפייני תנאי מתלה בחוזה',
    2, 'מהם המאפיינים העיקריים של תנאי מתלה בחוזה, כפי שנקבעו בחוק ובפסיקה?', 'שאלה זו מתמקדת בהגדרת תנאי מתלה בחוזה, תוך הבחנה בינו לבין התחייבות חוזית רגילה, כפי שנקבע בסעיף 27 לחוק החוזים ובפסיקה.', 'סעיף 27(א) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי ''חוזה יכול שיהיה תלוי בהתקיים תנאי (להלן - תנאי מתלה)''. הפסיקה הוסיפה וקבעה כי תנאי מתלה הוא תנאי המותנה בדרך כלל בהתקיימות אירוע עתידי, בלתי-ודאי, שהוא חיצוני לחוזה ואינו מטיל חובה על מי מהצדדים. זאת להבדיל מתניה חוזית שהיא חיוב שאת ביצועו נוטל על עצמו אחד הצדדים לחוזה (ע"א 4445/10 ישיבה וכולל אבן חיים נ'' חברת צמרות המושבה יזום והשקעות בע"מ, פסקה 7; ת"א (שלום חי'') 34197-06-22 יונתן שוורץ נ'' מיכאל גרטופסקי, פסקה 58). המסקנה אם מדובר בתנאי מתלה או בהתחייבות חוזית רגילה נבחנת בכל מקרה לגופו, תוך התחקות אחר אומד דעת הצדדים כפי שהיא משתקפת מתוך תנאי החוזה במכלול ומנסיבות כריתתו.',
    'הטעות הנפוצה היא לבלבל בין תנאי מתלה לבין חיוב חוזי רגיל, או להתעלם מהדרישה שהאירוע יהיה חיצוני לחוזה ובלתי ודאי.', '["תנאי מתלה", "חוזה על תנאי", "חוק החוזים סעיף 27", "אירוע עתידי", "בלתי ודאי", "חיצוני לחוזה"]'::jsonb, '**וריאציה 1 — תנאי מתלה מול תנאי מפסיק:** מה ההבדל בין תנאי מתלה לתנאי מפסיק? ← תנאי מתלה מעכב את כניסת החוזה לתוקף עד להתקיימותו, ואילו תנאי מפסיק מפסיק את תוקף החוזה עם התקיימותו (סעיף 27(א) לחוק החוזים).
**וריאציה 2 — חוזה טעון רישיון:** האם חוזה הטעון רישיון הוא תנאי מתלה? ← חזקה שקבלת הרישיון היא תנאי מתלה (סעיף 27(ב) לחוק החוזים).
**וריאציה 3 — תוקף חוזה על תנאי:** האם חוזה על תנאי הוא חוזה שלם מרגע כריתתו? ← כן, חוזה על תנאי הוא חוזה שלם מרגע כריתתו, ואין השלכה רטרואקטיבית לעניין תוקפו (ע"א 489/89 אלדר שרון נ'' שבח מקרקעין).', 'תנאי מתלה ← אירוע עתידי, בלתי ודאי, חיצוני לחוזה, אינו מטיל חובה (סעיף 27 לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 27", "ע\"א 4445/10 ישיבה וכולל אבן חיים נ'' חברת צמרות המושבה יזום והשקעות בע\"מ (05.09.2012)", "תפ\"מ (שלום קריות) 34197-06-22 יונתן שוורץ נ'' מיכאל גרטופסקי (06.02.2023)", "ע\"א 8561/03 חלקה 21 בגוש 6286 בע\"מ נ'' עיריית ראשון-לציון, נט(3) 398 (22.11.2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'אירוע עתידי, ודאי, חיצוני לחוזה ומטיל חובה על אחד הצדדים.', false, 'טענה זו שגויה. תנאי מתלה הוא אירוע בלתי ודאי ואינו מטיל חובה על מי מהצדדים, בניגוד לחיוב חוזי רגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'אירוע עתידי, בלתי ודאי, חיצוני לחוזה ואינו מטיל חובה על מי מהצדדים.', true, 'תשובה זו נכונה. אלו הם המאפיינים המרכזיים של תנאי מתלה, המבחינים אותו מחיוב חוזי רגיל, כפי שנקבע בסעיף 27 לחוק החוזים ובפסיקה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'אירוע עבר, ודאי, פנימי לחוזה ומטיל חובה על שני הצדדים.', false, 'טענה זו שגויה. תנאי מתלה הוא אירוע עתידי, בלתי ודאי וחיצוני לחוזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אירוע עתידי, בלתי ודאי, פנימי לחוזה ומטיל חובה על אחד הצדדים.', false, 'טענה זו שגויה. תנאי מתלה הוא אירוע חיצוני לחוזה ואינו מטיל חובה על מי מהצדדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סיכול תנאי מתלה ותום לב',
    3, 'חברת בנייה התחייבה להשיג היתר בנייה כתנאי מתלה לחוזה מכר דירה. החברה לא פעלה לקבלת ההיתר, ואף ניסתה להגדיל את אחוזי הבנייה מעבר למוקנה, מה שמנע את קבלתו. האם החברה יכולה לטעון שהחוזה בטל בשל אי-קיום התנאי המתלה?', 'שאלה זו בוחנת את תחולת סעיף 28 לחוק החוזים, העוסק בסיכול תנאי מתלה, ואת הקשר שלו לחובת תום הלב בקיום חוזים. היא מדגישה כי צד שמנע את קיום התנאי אינו יכול ליהנות מאי-קיומו.', 'סעיף 28(א) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי ''היה חוזה מותנה בתנאי מתלה וצד אחד מנע את קיום התנאי, אין הוא זכאי להסתמך על אי-קיומו''. הוראה זו מבטאת את עקרון תום הלב בקיום חוזים (ע"א 247779/91 ק. צ. מפעלי גז ואנרגיה (1982) בע"מ נ'' מקסימה המרכז להפרדת אויר בע"מ, פסקה 4). במקרה המתואר, חברת הבנייה לא רק שלא פעלה לקבלת ההיתר, אלא אף ניסתה להגדיל את אחוזי הבנייה, פעולה שסיכלה את קבלת ההיתר. בית המשפט המחוזי בת"א (ת"א (מחוזי ת"א) 33947-03-16 שרון יצחק נהרי נ'' אזורים בנין (1965) בע"מ, פסקה 71) קבע כי סיכול מכוון של חיובים אינו מקנה זכות להסתמך על תנאי מתלה, וכי על הצד לנהוג בתום לב בהפעלת התנאי. לכן, החברה אינה יכולה לטעון שהחוזה בטל בשל אי-קיום התנאי המתלה.',
    'הטעות הנפוצה היא להתעלם מהוראת סעיף 28 לחוק החוזים, ולחשוב שאי-קיום תנאי מתלה מוביל תמיד לבטלות החוזה, גם אם צד לחוזה הוא שגרם לאי-קיומו.', '["תנאי מתלה", "סיכול תנאי", "חוק החוזים סעיף 28", "חובת תום לב", "מניעות סטטוטורית", "הפרת חוזה"]'::jsonb, '**וריאציה 1 — חריג לסיכול תנאי:** מתי צד שמנע את קיום התנאי כן יכול להסתמך על אי-קיומו? ← אם מנע את קיום התנאי שלא בזדון ושלא ברשלנות, או אם היה התנאי דבר שהצד היה בן חורין לעשותו או לא לעשותו (סעיף 28(ג) לחוק החוזים).
**וריאציה 2 — תוצאת סיכול תנאי:** מהי התוצאה המשפטית של סיכול תנאי מתלה? ← יראו את התנאי כאילו התקיים, והחוזה ייכנס לתוקף (ע"א 247779/91 ק. צ. מפעלי גז ואנרגיה (1982) בע"מ נ'' מקסימה המרכז להפרדת אויר בע"מ).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח סיכול תנאי? ← על הצד הטוען לסיכול (ת"א (מחוזי ת"א) 33947-03-16 שרון יצחק נהרי נ'' אזורים בנין (1965) בע"מ, פסקה 71).', 'סיכול תנאי מתלה ← צד שמנע קיומו אינו יכול להסתמך על אי-קיומו (סעיף 28 לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 28", "ע\"א 247779/91 ק. צ. מפעלי גז ואנרגיה (1982) בע\"מ נ'' מקסימה המרכז להפרדת אויר בע\"מ, מז(2) 642 (27.05.1993)", "ת\"א (מחוזי ת\"א) 33947-03-16 שרון יצחק נהרי נ'' אזורים בנין (1965) בע\"מ (14.02.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מכיוון שהתנאי המתלה לא התקיים, החוזה בטל מאליו.', false, 'טענה זו שגויה. למרות שאי-קיום תנאי מתלה מבטל חוזה, צד שמנע את קיום התנאי אינו יכול להסתמך על כך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מכיוון שצד שמנע את קיום התנאי אינו זכאי להסתמך על אי-קיומו, בהתאם לסעיף 28 לחוק החוזים.', true, 'תשובה זו נכונה. סעיף 28(א) לחוק החוזים מונע מצד שמנע את קיום התנאי המתלה מלהסתמך על אי-קיומו, במיוחד כאשר מדובר בחוסר תום לב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם פעלה שלא בזדון ושלא ברשלנות.', false, 'טענה זו שגויה. סעיף 28(ג) לחוק החוזים קובע חריג זה, אך במקרה המתואר החברה פעלה באופן מכוון (ניסיון להגדיל אחוזי בנייה) שגרם לסיכול התנאי, מה שמעיד על זדון או רשלנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן התובע יוכיח שהחברה פעלה בחוסר תום לב מובהק.', false, 'טענה זו שגויה. סעיף 28(א) קובע כלל מניעות כללי, וחוסר תום הלב הוא פן של חובה זו, אך הנטל אינו בהכרח על התובע להוכיח חוסר תום לב מובהק מעבר למניעת קיום התנאי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'התיישנות תביעת השבה לאחר ביטול חוזה',
    4, 'ראובן ביטל חוזה עם שמעון עקב הפרה יסודית. ראובן שילם לשמעון מקדמה בסך 10,000 ש"ח בעת כריתת החוזה. מתי תחל תקופת ההתיישנות לתביעת השבה של המקדמה?', 'שאלה זו עוסקת במועד תחילת מרוץ ההתיישנות בתביעת השבה לאחר ביטול חוזה עקב הפרה, בהתאם לסעיף 6 לחוק ההתיישנות ולסעיף 9 לחוק החוזים (תרופות).', 'סעיף 6 לחוק ההתיישנות, התשי"ח-1958, קובע כי תקופת ההתיישנות מתחילה ביום שבו נולדה עילת התובענה. סעיף 9 לחוק החוזים (תרופות בשל הפרת חוזה), תשל"א-1970, קובע כי משבוטל החוזה, חייבים הצדדים להשיב זה לזה את מה שקיבלו על פי החוזה. כלומר, הזכות להשבה משתכללת במועד ביטול החוזה, ולכן במועד זה יחל מרוץ ההתיישנות (ע"א 9371/00 אלבשארה לעידוד תיירות בע"מ נ'' קוסטודיה פרנציסקנה דה טרה סנטה, פ"ד נו(4) 798, 806 (2002); נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות, עמ'' 76). במקרה זה, ראובן ביטל את החוזה, ורק אז נולדה לו הזכות לתבוע השבה של המקדמה ששילם. לכן, מרוץ ההתיישנות יחל ממועד ביטול החוזה.',
    'הטעות הנפוצה היא לבלבל בין מועד התשלום או מועד ההפרה לבין מועד ביטול החוזה כתחילת מרוץ ההתיישנות בתביעת השבה.', '["התיישנות", "עילת תביעה", "ביטול חוזה", "השבה", "חוק החוזים (תרופות)", "מועד ביטול חוזה"]'::jsonb, '**וריאציה 1 — השבה בחוזה פסול:** מתי תחל התיישנות בתביעת השבה בגין חוזה פסול? ← ביום שבו נפל פסול בחוזה או ביום שבו טובת ההנאה ניתנה, לפי המאוחר מביניהם (רע"א 6774/19 אפרידר).
**וריאציה 2 — הודעת ביטול:** מהו המועד שבו משתכלל הביטול לצורך התיישנות? ← המועד שבו נתקבלה הודעת הביטול אצל המפר (ע"א 9371/00 אלבשארה).
**וריאציה 3 — זכות מהותית מול דיונית:** האם חלוף תקופת ההתיישנות מבטל את הזכות המהותית? ← לא, חלוף תקופת ההתיישנות אינו מבטל את הזכות המהותית גופה, אלא רק את הזכות הדיונית לתבוע בבית המשפט (סעיף 2 לחוק ההתיישנות; עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ).', 'תביעת השבה לאחר ביטול חוזה ← התיישנות ממועד ביטול החוזה (סעיף 9 לחוק החוזים (תרופות)).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 6", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 9", "ע\"א 9371/00 אלבשארה לעידוד תיירות בע\"מ נ'' קוסטודיה פרנציסקנה דה טרה סנטה, פ\"ד נו(4) 798 (2002)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | פרק שני - תקופת ההתיישנות", "עע\"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע\"מ (15.04.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ממועד כריתת החוזה.', false, 'טענה זו שגויה. מועד כריתת החוזה אינו רלוונטי לתביעת השבה לאחר ביטול חוזה, שכן זכות ההשבה נולדת רק עם הביטול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ממועד הפרת החוזה על ידי שמעון.', false, 'טענה זו שגויה. מועד ההפרה הוא תחילת מרוץ ההתיישנות לתביעה לאכיפה או ביטול החוזה, אך לא לתביעת השבה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ממועד ביטול החוזה על ידי ראובן.', true, 'תשובה זו נכונה. תביעה להשבת מה שניתן על פי חוזה בעקבות ביטולו נולדת במועד הביטול, שכן אז משתכללת זכות ההשבה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'ממועד התשלום של המקדמה.', false, 'טענה זו שגויה. מועד התשלום אינו רלוונטי לתחילת מרוץ ההתיישנות בתביעת השבה לאחר ביטול חוזה, שכן זכות ההשבה טרם נולדה במועד זה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 19, '2019-S-S-Q19';
END
$$;

-- ============================================================
-- Q20 — 2019-S-S-Q20 — chapter=contracts subtopic=limitation
-- classifier_note: Limitation on enforcement of judgment after failed negotiations (ע"א 8301/98 הדסה אנואר)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '80e4e4a0-ba0e-4bd6-86d2-9bb1da5fa01e'::uuid;
  v_group_id uuid := '65576e48-92df-49f9-bb3b-bef30c3c896b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'a685aca0-eb67-4ea1-92ab-5697c658f518'::uuid;
  v_ang_1 uuid := 'decc511c-533c-4aef-b1f1-d6d1d800f9d4'::uuid;
  v_ang_2 uuid := 'c54c917f-11fe-49c1-8701-66289de9db53'::uuid;
  v_ang_3 uuid := 'b00aad34-77b0-4cbe-b845-03081b0a7d85'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q20';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 20, '2019-S-S-Q20';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q20', v_chapter_id, v_subtopic_id, 'ע"א 8301/98 הדסה אנואר נ. ש.א.פ. בע"מ, בפסקה 6: "מקום שבו דרך המשא ומתן לא צלחה שוב קם הצורך להגן על אינטרס ההסתמכות של החייב, לפיכך אם ''ישן'' התובע על זכויותיו לאחר כישלון המשא ומתן וחולפת תקופת ההתיישנות, קמה תחולה להוראת סעיף 21 לחוק ההתיישנות ורשאי החייב לטעון טענת התיישנות. ודוק, בית-המשפט העליון קבע בפרשת לחאם [5], כאמור, כי ''פעולה לביצוע פסק-הדין יוצרת חזקה שלפיה עומד הזוכה על ביצוע פסק-הדין...'', ואולם ''זוכה שאינו משלים את פעולתו במשך שנים רבות, סותר חזקה זו ומפיץ ריח של ויתור על זכותו לפי פסק-הדין'' (שם, בעמ'' 623). בקביעה זו של בית-המשפט העליון טמונה בהכרח ההנחה כי ''פעולה כל שהיא'' לביצוע פסק-הדין אינה רק הפעולה האחרונה, המשלימה, לביצוע פסק-הדין (לאמור, פתיחת הליכי הוצאה לפועל), כי אם גם פעולות קודמות לכך". מה מן האמור להלן עולה מהדברים האמורים?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 20}'::jsonb, 'השאלה עוסקת בהתיישנות פסקי דין, ובפרט בפרשנות המונח ''פעולה כל שהיא כדי לבצעו'' בסעיף 21 לחוק ההתיישנות, תשי"ח-1958. היא מתמקדת בהלכה הפסוקה שקבעה כי גם משא ומתן לביצוע פסק דין נחשב לפעולה כזו, המאפסת את מירוץ ההתיישנות.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע תקופת התיישנות של 25 שנה לפסק דין, אלא אם הזכאי עשה ''פעולה כל שהיא כדי לבצעו''. בית המשפט העליון, בע"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע"מ, בהתבסס על ע"א 288/95 לחאם נ'' אל-זארובי, פירש את המונח ''פעולה כל שהיא'' באופן רחב. נקבע כי פעולה זו אינה מצטמצמת רק לפתיחת הליכי הוצאה לפועל, אלא כוללת גם פעולות קודמות ואפקטיביות אחרות שנועדו להביא לביצוע פסק הדין. בפרט, נקבע כי ניהול משא ומתן לביצוע פסק דין נחשב ל''פעולה כל שהיא'' כזו, שכן הוא מלמד שהזוכה עומד על זכותו ומעוניין לממשה. פעולה כזו יוצרת חזקה שהזוכה עומד על ביצוע פסק הדין ומאפסת את מירוץ ההתיישנות, כלומר, תקופת ההתיישנות של 25 שנה מתחילה להימנות מחדש ממועד סיום הפעולה. עם זאת, אם המשא ומתן נכשל והזוכה ''ישן'' על זכויותיו לאחר מכן, החזקה נסתרת ומרוץ ההתיישנות מתחדש.', 'הטעות הנפוצה היא לחשוב שרק הליכי הוצאה לפועל פורמליים נחשבים ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות, או להניח שפעולה כזו מבטלת את ההתיישנות לצמיתות ולא רק מאפסת אותה.',
    '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פעולה לביצוע פסק דין", "משא ומתן", "איפוס מירוץ ההתיישנות", "חזקת ויתור", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — מטרת סעיף 21:** מהי התכלית החברתית של סעיף 21 לחוק ההתיישנות? ← להגן על אינטרס ההסתמכות של החייב ולהקנות לו ודאות בדבר זכויותיו וחובותיו (ע"א 8301/98 אנואר, פסקה 4).
**וריאציה 2 — הבחנה בין איפוס לעיכוב:** מה ההבדל בין איפוס מירוץ ההתיישנות לעיכובו? ← איפוס (כמו בסעיף 21) מתחיל את המירוץ מחדש מתחילתו, בעוד עיכוב (כמו בסעיפים 10-15 לחוק) עוצר את המירוץ וממשיך אותו מהנקודה שבה נעצר (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות, 2026, עמ'' 89).
**וריאציה 3 — פסק דין הצהרתי:** האם פסק דין הצהרתי שאינו טעון ביצוע נתון להתיישנות? ← לא, פסק דין כזה אינו נתון להתיישנות כלל (סעיף 21 סיפא לחוק ההתיישנות).', 'משא ומתן לביצוע פסק דין ← נחשב ל''פעולה כל שהיא'' (סעיף 21) ← מאפסת את מירוץ ההתיישנות של 25 שנה ← מתחיל מחדש ממועד סיום הפעולה, אך לא מונע התיישנות אם הזוכה ''ישן'' על זכויותיו לאחר מכן.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, פ\"ד נד(2) 598 (2000)", "דוד בר-אופיר הוצאה לפועל הליכים והלכות - כרך א (2025) | 42. התיישנות - שיהוי - פרשנות - התנהגות המעכבת התיישנות", "טל חבקין התיישנות (2021) | פרק עשרים וחמישה סעיף 21 לחוק ההתיישנות - התיישנות פסק דין"]'::jsonb,
    'classification_review: original chapter=''הוצאה לפועל'' subtopic=''פתיחת תיקים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Limitation on enforcement of judgment after failed negotiations (ע"א 8301/98 הדסה אנואר)', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'משא ומתן אינו מהווה פעולה לביצוע פסק דין היוצרת חזקה שלפיה עומד הזוכה על ביצוע פסק הדין.', false, 'טענה זו שגויה. פסק הדין קובע במפורש כי משא ומתן נחשב ל''פעולה כל שהיא'' לביצוע פסק דין, היוצרת חזקה שהזוכה עומד על ביצועו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'משא ומתן מהווה פעולה לביצוע פסק דין היוצרת חזקה שלפיה עומד הזוכה על ביצוע פסק הדין.', true, 'תשובה זו נכונה. פסק הדין בעניין אנואר, בהתבסס על פרשת לחאם, קובע כי משא ומתן לביצוע פסק דין נכלל בהגדרה הרחבה של ''פעולה כל שהיא'' לעניין סעיף 21 לחוק ההתיישנות, ויוצר חזקה שהזוכה עומד על זכותו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'משא ומתן מהווה פעולה לביצוע פסק דין היוצרת חזקה שלפיה התובע לא "ישן" על זכויותיו לאחר כישלון המשא ומתן.', false, 'טענה זו שגויה. משא ומתן יוצר חזקה שהזוכה עומד על זכויותיו, אך אם המשא ומתן נכשל והזוכה ''ישן'' על זכויותיו לאחר מכן, החזקה נסתרת ומרוץ ההתיישנות מתחדש.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'משא ומתן שנכשל אינו מהווה פעולה לביצוע פסק דין היוצרת חזקה שלפיה עומד הזוכה על ביצוע פסק הדין.', false, 'טענה זו שגויה. עצם קיום המשא ומתן, גם אם נכשל, נחשב לפעולה המאפסת את מרוץ ההתיישנות. כישלונו רק מאפשר את חידוש המרוץ לאחר מכן, אם הזוכה לא פעל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פעולות נוספות המאפסות מירוץ התיישנות פסק דין',
    1, 'פסק דין לפינוי דירה ניתן לפני 20 שנה. הזוכה לא פתח תיק הוצאה לפועל, אך לפני 5 שנים רשם הערת אזהרה על הנכס מכוח פסק הדין. האם רישום הערת האזהרה נחשב ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות?', 'שאלה זו בוחנת את הפרשנות הרחבה למונח ''פעולה כל שהיא'' בסעיף 21 לחוק ההתיישנות, המאפסת את מירוץ ההתיישנות של פסק דין, ומתמקדת בשאלה האם רישום הערת אזהרה נכלל בהגדרה זו.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי פסק דין מתיישן לאחר 25 שנה אם הזכאי לא עשה ''פעולה כל שהיא כדי לבצעו''. הפסיקה, ובפרט ע"א 8301/98 אנואר נ'' ש.א.פ. בע"מ, קבעה כי המונח ''פעולה כל שהיא'' יפורש באופן רחב וכולל פעולות אפקטיביות שנעשו במטרה להביא לביצוע פסק הדין, ולא רק הליכי הוצאה לפועל פורמליים. ה"פ (מחוזי י-ם) 51681-05-16 שמואל רולנד בן ברון נ'' רחל ורד קבע במפורש כי רישום הערת אזהרה מהווה ''פעולה כלשהי'' בדרך לביצוע פסק הדין, שכן הוא מבטא את כוונת הצדדים לבצע את העסקה ולהביאה לכדי השלמת הרישום, ובכך מפסיק את מירוץ ההתיישנות. לכן, רישום הערת האזהרה במקרה זה יאפס את מירוץ ההתיישנות, והוא יחל מחדש ממועד הרישום.',
    'הטעות הנפוצה היא לחשוב שרק פעולות אכיפה ישירות בלשכת ההוצאה לפועל נחשבות ל''פעולה כל שהיא'', ולהתעלם מפעולות אחרות המבטאות את עמידת הזוכה על זכותו.', '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פעולה לביצוע פסק דין", "הערת אזהרה", "איפוס מירוץ ההתיישנות", "פרשנות רחבה"]'::jsonb, '**וריאציה 1 — הגשת תביעה חדשה:** האם הגשת תביעה חדשה המבוססת על פסק הדין המקורי נחשבת לפעולה? ← כן, הגשת תובענה נוספת לביצועו מאפסת את המירוץ (טל חבקין, התיישנות, 2021, עמ'' 2).
**וריאציה 2 — פעילות מתמשכת:** האם ''מנהג בעלים'' מתמשך (כגון גביית שכר דירה) נחשב לפעולה המאפסת את המירוץ? ← לרוב לא, אם מדובר בהמשך מציאות קיימת ולא באקט חדש המבטא כוונה לבצע את פסק הדין (ה"פ (מחוזי י-ם) 51681-05-16 בן ברון).
**וריאציה 3 — ידיעת החייב:** האם פעולה שלא הובאה לידיעת החייב מאפסת את המירוץ? ← מבחינת טעמי ההתיישנות, יש הטוענים שלא, שכן אינטרס ההסתמכות של החייב לא נפגע (טל חבקין, התיישנות, 2021, עמ'' 2).', 'פעולה לביצוע פסק דין (סעיף 21) ← פרשנות רחבה, כוללת רישום הערת אזהרה ← מאפסת את מירוץ ההתיישנות.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)", "ה\"פ (מחוזי י-ם) 51681-05-16 שמואל רולנד בן ברון נ'' רחל ורד (08.03.2021)", "טל חבקין התיישנות (2021) | פרק עשרים וחמישה סעיף 21 לחוק ההתיישנות - התיישנות פסק דין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, רק פתיחת תיק הוצאה לפועל נחשבת לפעולה המאפסת את מירוץ ההתיישנות.', false, 'טענה זו שגויה. הפסיקה הרחיבה את הפרשנות ל''פעולה כל שהיא'' מעבר לפתיחת תיק הוצאה לפועל, וכוללת פעולות אפקטיביות נוספות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, רישום הערת אזהרה נחשב ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות, שכן הוא מבטא את עמידת הזוכה על זכותו.', true, 'תשובה זו נכונה. הפסיקה קבעה כי רישום הערת אזהרה, אף שאינו הליך ביצועי במובן הדווקני, מבטא את כוונת הזוכה לבצע את פסק הדין ומהווה ''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן החייב ידע בפועל על רישום הערת האזהרה.', false, 'טענה זו שגויה. אף שקיימת גישה בספרות הדורשת ידיעה של החייב, הפסיקה לא קבעה זאת כתנאי הכרחי לכל ''פעולה כל שהיא'' המאפסת את המירוץ, במיוחד כאשר מדובר בפעולה פומבית כמו רישום הערת אזהרה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם חלפו פחות מ-25 שנה ממועד מתן פסק הדין המקורי.', false, 'טענה זו שגויה. מטרת ה''פעולה כל שהיא'' היא לאפס את מירוץ ההתיישנות, כלומר להתחיל מניין חדש של 25 שנה ממועד הפעולה, ללא קשר לזמן שחלף קודם לכן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'ההבחנה בין פסק דין טעון ביצוע ללא טעון ביצוע',
    2, 'בית המשפט נתן פסק דין הקובע כי ראובן הוא הבעלים של חלקה מסוימת במקרקעין, אך לא הורה על רישום הבעלות בלשכת רישום המקרקעין. האם פסק דין זה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות?', 'שאלה זו עוסקת בהבחנה בין פסק דין ''טעון ביצוע'' לבין פסק דין ''שאינו טעון ביצוע'' לעניין סעיף 21 לחוק ההתיישנות, וכיצד הבחנה זו משפיעה על תחולת דיני ההתיישנות על פסקי דין הצהרתיים.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי פסק דין ''שאינו טעון ביצוע אינו נתון להתיישנות''. פסק דין טעון ביצוע הוא כזה המחייב את הנתבע לעשות מעשה, כמו חיוב כספי או צו לביצוע בעין. לעומתו, פסק דין שאינו טעון ביצוע הוא פסק דין שאינו מחייב לעשות מעשה, כמו פסק דין הצהרתי מסוג ''חפצא'', שאין צורך לאכוף אותו (ע"א 288/95 לחאם נ'' אל-זארובי, פ"ד נד(2) 598, 610). במקרה זה, פסק הדין רק מצהיר על בעלותו של ראובן בחלקה, אך אינו מורה על פעולה אופרטיבית כלשהי, כגון רישום הבעלות. לכן, הוא נחשב לפסק דין שאינו טעון ביצוע ואינו נתון להתיישנות. יש לציין כי אם פסק הדין היה מורה על רישום הבעלות, הוא היה נחשב לטעון ביצוע (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות פסק דין, עמ'' 89).',
    'הטעות הנפוצה היא להניח שכל פסק דין המעניק זכות במקרקעין הוא ''טעון ביצוע'', גם אם אינו מורה על פעולה אופרטיבית למימוש הזכות.', '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פסק דין טעון ביצוע", "פסק דין הצהרתי", "מקרקעין", "רישום זכויות"]'::jsonb, '**וריאציה 1 — פסק דין המורה על רישום:** האם פסק דין המורה על רישום בעלות במקרקעין נתון להתיישנות? ← כן, הוא טעון ביצוע ולכן נתון להתיישנות של 25 שנה (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות, 2026, עמ'' 89).
**וריאציה 2 — פסק דין המאמץ הסכם פשרה:** האם פסק דין המאמץ הסכם פשרה שנזנח על ידי הצדדים נתון להתיישנות? ← לא, במקרה כזה לא יחול סעיף 21 לחוק ההתיישנות (ישראל גלעד, התיישנות בדין האזרחי, 2022, עמ'' 6).
**וריאציה 3 — הרציונל להבחנה:** מהו הרציונל להבחנה בין פסק דין טעון ביצוע ללא טעון ביצוע? ← פסק דין שאינו טעון ביצוע אינו דורש אכיפה, ולכן אין טעם להגביל את תוקפו בזמן (ע"א 288/95 לחאם).', 'פסק דין הצהרתי שאינו מורה על פעולה אופרטיבית ← אינו טעון ביצוע ← אינו נתון להתיישנות (סעיף 21 סיפא לחוק ההתיישנות).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, פ\"ד נד(2) 598 (2000)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות פסק דין", "ישראל גלעד התיישנות בדין האזרחי (2022) | פרק שישי תקופת ההתיישנות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, כל פסק דין, למעט פסק דין הצהרתי מובהק שאינו דורש כל פעולה, נתון להתיישנות.', false, 'טענה זו שגויה. פסק דין הצהרתי שאינו דורש פעולה למימוש הזכות אינו נתון להתיישנות. השאלה היא האם פסק דין זה דורש פעולה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, פסק דין המצהיר על זכות בעלות במקרקעין, שאינו מורה על צעד אופרטיבי, אינו טעון ביצוע ולכן אינו נתון להתיישנות.', true, 'תשובה זו נכונה. פסק דין הצהרתי שאינו מחייב לעשות מעשה, כמו פסק דין המצהיר על בעלות ללא הוראה לרישום, אינו טעון ביצוע ולכן אינו נתון להתיישנות, בהתאם לסיפא של סעיף 21 לחוק ההתיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, מכיוון שמימוש זכות הבעלות במקרקעין טעון רישום, ולכן פסק הדין נחשב לטעון ביצוע.', false, 'טענה זו שגויה. אף שמימוש זכות הבעלות טעון רישום, אם פסק הדין עצמו אינו מורה על פעולת הרישום, הוא נחשב לפסק דין הצהרתי שאינו טעון ביצוע לעניין סעיף 21.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן הזוכה הוכיח כי פעל לרישום הבעלות בלשכת רישום המקרקעין.', false, 'טענה זו שגויה. השאלה היא האם פסק הדין טעון ביצוע מלכתחילה, ולא האם הזוכה פעל לביצועו. אם אינו טעון ביצוע, הוא אינו נתון להתיישנות כלל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התיישנות פסק דין נגד המדינה',
    3, 'בית המשפט נתן פסק דין כספי נגד מדינת ישראל. האם פסק דין זה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות, וכיצד מתבצעת ''פעולה לביצועו'' לעניין סעיף זה?', 'שאלה זו בוחנת את תחולת דיני ההתיישנות על פסקי דין כספיים שניתנו נגד המדינה, ואת אופן ביצועם, תוך התייחסות למנגנון הייחודי הקבוע בחוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין).', 'פסק דין שניתן נגד המדינה דינו לעניין הוצאה לפועל כדין כל פסק דין (סעיף 6 לחוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין)). לכן, פסק דין כספי נגד המדינה נתון להתיישנות של 25 שנה לפי סעיף 21 לחוק ההתיישנות. עם זאת, ביצוע פסק דין נגד המדינה אינו מתבצע באמצעות המערכת הרגילה של ההוצאה לפועל. במקום זאת, הפרקליט האחראי מעביר בקשה לתשלום החוב לחשב המשרד הרלוונטי, והוא זה שמשלם לזוכה את הסכום (נבו - המתמחה, דיני הוצאה לפועל (2026) | פסק דין נגד המדינה, עמ'' 122). פעולה זו של העברת הבקשה לתשלום לחשב המשרד הרלוונטי תיחשב ל''פעולה כל שהיא'' לביצוע פסק הדין לעניין סעיף 21 לחוק ההתיישנות, המאפסת את מירוץ ההתיישנות.',
    'הטעות הנפוצה היא להניח שמעמדה המיוחד של המדינה פוטר אותה מדיני ההתיישנות, או לבלבל בין מנגנון הביצוע הייחודי לבין תחולת דיני ההתיישנות.', '["התיישנות פסק דין", "המדינה כבעל דין", "סעיף 21 לחוק ההתיישנות", "הוצאה לפועל נגד המדינה", "פעולה לביצוע פסק דין", "חוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין)"]'::jsonb, '**וריאציה 1 — מטרת ההסדר המיוחד:** מדוע קיים הסדר מיוחד לביצוע פסקי דין נגד המדינה? ← כדי למנוע הליכי אכיפה כופים נגד המדינה ולאפשר תשלום מסודר (נבו - המתמחה, דיני הוצאה לפועל, 2026, עמ'' 122).
**וריאציה 2 — פסק דין לטובת המדינה:** האם פסק דין לטובת המדינה נתון להתיישנות? ← כן, דינו לעניין הוצאה לפועל כדין כל פסק דין (נבו - המתמחה, דיני הוצאה לפועל, 2026, עמ'' 122).
**וריאציה 3 — שיהוי מנהלי:** האם ניתן לטעון לשיהוי מנהלי נגד המדינה בהליכי גבייה? ← כן, הפסיקה הכירה בתחולת דיני השיהוי המנהליים על הליכי גבייה פסיביים של המדינה (עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ).', 'פסק דין נגד המדינה ← נתון להתיישנות 25 שנה (סעיף 21) ← ''פעולה לביצועו'' היא העברת בקשה לתשלום לחשב המשרד הרלוונטי.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "נבו - המתמחה דיני הוצאה לפועל (2026) | פסק דין נגד המדינה", "עע\"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע\"מ (15.04.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'פסק דין נגד המדינה אינו נתון להתיישנות כלל, בשל מעמדה המיוחד של המדינה.', false, 'טענה זו שגויה. פסק דין נגד המדינה נתון להתיישנות, ואין חריג כללי המבטל את תחולת חוק ההתיישנות עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, פסק דין נגד המדינה נתון להתיישנות של 25 שנה, ו''פעולה לביצועו'' היא העברת הבקשה לתשלום לחשב המשרד הרלוונטי.', true, 'תשובה זו נכונה. פסק דין נגד המדינה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות. ''פעולה לביצועו'' אינה מתבצעת דרך ההוצאה לפועל הרגילה, אלא באמצעות העברת הבקשה לתשלום לחשב המשרד הרלוונטי במשרד האוצר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, פסק דין נגד המדינה נתון להתיישנות של 7 שנים, בדומה לתביעה אזרחית רגילה.', false, 'טענה זו שגויה. תקופת ההתיישנות לפסק דין היא 25 שנה, ולא 7 שנים, גם כאשר המדינה היא החייבת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן המדינה טענה במפורש טענת התיישנות בהזדמנות הראשונה.', false, 'טענה זו שגויה. טענת התיישנות היא טענה דיונית שיש לטעון בהזדמנות הראשונה, אך היא אינה קובעת אם פסק הדין נתון להתיישנות מלכתחילה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השפעת הודאת בעל דין על התיישנות פסק דין',
    4, 'פסק דין כספי ניתן לפני 20 שנה. לפני 10 שנים, החייב הודה בכתב בפני הזוכה בקיום החוב הפסוק. האם הודאה זו מאפסת את מירוץ ההתיישנות של פסק הדין?', 'שאלה זו בוחנת את השפעת הודאת בעל דין על מירוץ ההתיישנות של פסק דין, תוך התייחסות לסעיף 9 לחוק ההתיישנות, המהווה עילה לאיפוס מירוץ ההתיישנות.', 'סעיף 9 לחוק ההתיישנות, תשי"ח-1958, קובע כי ''הודה הנתבע, בכתב או בפני בית משפט, בין בתוך תקופת ההתיישנות ובין לאחריה, בקיום זכות התובע, תתחיל תקופת ההתיישנות מיום ההודאה''. הוראה זו חלה גם על התיישנות פסק דין, שכן פסק דין מקים זכות לזוכה. הודאת החייב בקיום החוב הפסוק מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה (ע"א 8301/98 אנואר נ'' ש.א.פ. בע"מ, פסקה 2). במקרה זה, הודאת החייב בכתב לפני 10 שנים מאפסת את מירוץ ההתיישנות, והוא יחל מחדש ממועד ההודאה. לכן, פסק הדין לא התיישן.',
    'הטעות הנפוצה היא לחשוב שסעיף 9 לחוק ההתיישנות חל רק על עילות תביעה רגילות ולא על פסקי דין, או לבלבל בין ''הודאה'' לבין ''פעולה כל שהיא'' לביצוע פסק דין.', '["התיישנות פסק דין", "סעיף 9 לחוק ההתיישנות", "הודאת בעל דין", "איפוס מירוץ ההתיישנות", "חוב פסוק", "זכות דיונית"]'::jsonb, '**וריאציה 1 — ביצוע מקצת הזכות:** האם ביצוע מקצת הזכות נחשב להודאה? ← כן, מעשה שיש בו משום ביצוע מקצת הזכות, דינו כהודאה לעניין סעיף 9 לחוק ההתיישנות.
**וריאציה 2 — הודאה עם טיעון התיישנות:** האם הודאה שהיה עמה טיעון התיישנות נחשבת להודאה? ← לא, סעיף 9 לחוק ההתיישנות קובע במפורש ''למעט הודאה שהיה עמה טיעון התיישנות''.
**וריאציה 3 — הודאה לאחר תקופת ההתיישנות:** האם הודאה שניתנה לאחר שחלפה תקופת ההתיישנות מאפסת את המירוץ? ← כן, סעיף 9 קובע ''בין בתוך תקופת ההתיישנות ובין לאחריה''.', 'הודאת בעל דין (סעיף 9) ← מאפסת מירוץ התיישנות פסק דין ← מתחיל מחדש מיום ההודאה.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, סעיף 9 לחוק ההתיישנות (הודאת בעל דין) אינו חל על התיישנות פסק דין.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות חל גם על התיישנות פסק דין, ומהווה עילה לאיפוס מירוץ ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, הודאת בעל דין בקיום זכות מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה.', true, 'תשובה זו נכונה. סעיף 9 לחוק ההתיישנות קובע כי הודאת בעל דין בקיום זכות מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה. הוראה זו חלה גם על התיישנות פסק דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, מכיוון שחלפו יותר מ-7 שנים ממועד מתן פסק הדין המקורי.', false, 'טענה זו שגויה. תקופת ההתיישנות לפסק דין היא 25 שנה, והודאת בעל דין מאפסת את המירוץ ללא קשר לזמן שחלף קודם לכן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם ההודאה ניתנה בפני בית משפט ולא בכתב בפני הזוכה.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות מכיר בהודאה ''בכתב או בפני בית משפט''.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 20, '2019-S-S-Q20';
END
$$;

-- ============================================================
-- Q21 — 2019-S-S-Q21 — chapter=contracts subtopic=limitation
-- classifier_note: Same case (ע"א 8301/98) but framed re evictions — limitation on execution of judgment
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '31f00332-c460-44b2-acae-35455680662e'::uuid;
  v_group_id uuid := '3acf5706-e59b-477f-8171-16449b9f281f'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '22acfb0f-ed87-4d55-b0f4-7db6d56dbe07'::uuid;
  v_ang_1 uuid := '4d11bad5-06ef-4c3e-bad5-7d940b73cb59'::uuid;
  v_ang_2 uuid := 'ee762327-c911-4fc8-9841-734f7ba727e0'::uuid;
  v_ang_3 uuid := 'f6d46be6-adfd-4156-a594-be5f38952fed'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q21';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 21, '2019-S-S-Q21';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q21', v_chapter_id, v_subtopic_id, 'ע"א 8301/98 הדסה אנואר נ. ש.א.פ. בע"מ, בפסקה 6: "מקום שבו דרך המשא ומתן לא צלחה שוב קם הצורך להגן על אינטרס ההסתמכות של החייב, לפיכך אם ''ישן'' התובע על זכויותיו לאחר כישלון המשא ומתן וחולפת תקופת ההתיישנות, קמה תחולה להוראת סעיף 21 לחוק ההתיישנות ורשאי החייב לטעון טענת התיישנות. ודוק, בית-המשפט העליון קבע בפרשת לחאם [5], כאמור, כי ''פעולה לביצוע פסק-הדין יוצרת חזקה שלפיה עומד הזוכה על ביצוע פסק-הדין...'', ואולם ''זוכה שאינו משלים את פעולתו במשך שנים רבות, סותר חזקה זו ומפיץ ריח של ויתור על זכותו לפי פסק-הדין'' (שם, בעמ'' 623). בקביעה זו של בית-המשפט העליון טמונה בהכרח ההנחה כי ''פעולה כל שהיא'' לביצוע פסק-הדין אינה רק הפעולה האחרונה, המשלימה, לביצוע פסק-הדין (לאמור, פתיחת הליכי הוצאה לפועל), כי אם גם פעולות קודמות לכך". בהינתן כי פסק הדין שצוטט עוסק בביצוע פסק דין של פינוי מקרקעין, מהו המשפט הנכון שעולה מהדברים האמורים בו?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 21}'::jsonb, 'השאלה עוסקת בהתיישנות פסקי דין, ובפרט בפרשנות המונח ''פעולה כל שהיא כדי לבצעו'' בסעיף 21 לחוק ההתיישנות, תשי"ח-1958. היא מתמקדת בהלכה הפסוקה שקבעה כי גם משא ומתן לביצוע פסק דין נחשב לפעולה כזו, המאפסת את מירוץ ההתיישנות.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע תקופת התיישנות של 25 שנה לפסק דין, אלא אם הזכאי עשה ''פעולה כל שהיא כדי לבצעו''. בית המשפט העליון, בע"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע"מ, בהתבסס על ע"א 288/95 לחאם נ'' אל-זארובי, פירש את המונח ''פעולה כל שהיא'' באופן רחב. נקבע כי פעולה זו אינה מצטמצמת רק לפתיחת הליכי הוצאה לפועל, אלא כוללת גם פעולות קודמות ואפקטיביות אחרות שנועדו להביא לביצוע פסק הדין. בפרט, נקבע כי ניהול משא ומתן לביצוע פסק דין נחשב ל''פעולה כל שהיא'' כזו, שכן הוא מלמד שהזוכה עומד על זכותו ומעוניין לממשה. פעולה כזו יוצרת חזקה שהזוכה עומד על ביצוע פסק הדין ומאפסת את מירוץ ההתיישנות, כלומר, תקופת ההתיישנות של 25 שנה מתחילה להימנות מחדש ממועד סיום הפעולה. עם זאת, אם המשא ומתן נכשל והזוכה ''ישן'' על זכויותיו לאחר מכן, החזקה נסתרת ומרוץ ההתיישנות מתחדש.', 'הטעות הנפוצה היא לחשוב שרק הליכי הוצאה לפועל פורמליים נחשבים ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות, או להניח שפעולה כזו מבטלת את ההתיישנות לצמיתות ולא רק מאפסת אותה.',
    '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פעולה לביצוע פסק דין", "משא ומתן", "איפוס מירוץ ההתיישנות", "חזקת ויתור", "פרשנות חוק"]'::jsonb, '**וריאציה 1 — מטרת סעיף 21:** מהי התכלית החברתית של סעיף 21 לחוק ההתיישנות? ← להגן על אינטרס ההסתמכות של החייב ולהקנות לו ודאות בדבר זכויותיו וחובותיו (ע"א 8301/98 אנואר, פסקה 4).
**וריאציה 2 — הבחנה בין איפוס לעיכוב:** מה ההבדל בין איפוס מירוץ ההתיישנות לעיכובו? ← איפוס (כמו בסעיף 21) מתחיל את המירוץ מחדש מתחילתו, בעוד עיכוב (כמו בסעיפים 10-15 לחוק) עוצר את המירוץ וממשיך אותו מהנקודה שבה נעצר (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות, 2026, עמ'' 89).
**וריאציה 3 — פסק דין הצהרתי:** האם פסק דין הצהרתי שאינו טעון ביצוע נתון להתיישנות? ← לא, פסק דין כזה אינו נתון להתיישנות כלל (סעיף 21 סיפא לחוק ההתיישנות).', 'משא ומתן לביצוע פסק דין ← נחשב ל''פעולה כל שהיא'' (סעיף 21) ← מאפסת את מירוץ ההתיישנות של 25 שנה ← מתחיל מחדש ממועד סיום הפעולה, אך לא מונע התיישנות אם הזוכה ''ישן'' על זכויותיו לאחר מכן.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, פ\"ד נד(2) 598 (2000)", "דוד בר-אופיר הוצאה לפועל הליכים והלכות - כרך א (2025) | 42. התיישנות - שיהוי - פרשנות - התנהגות המעכבת התיישנות", "טל חבקין התיישנות (2021) | פרק עשרים וחמישה סעיף 21 לחוק ההתיישנות - התיישנות פסק דין"]'::jsonb,
    'classification_review: original chapter=''הוצאה לפועל'' subtopic=''פתיחת תיקים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Same case (ע"א 8301/98) but framed re evictions — limitation on execution of judgment', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כפעולה לביצוע פסק הדין תיחשב רק אותה פעולה פיזית המביאה בפועל לפינוי של המקרקעין.', false, 'טענה זו שגויה. פסק הדין קובע במפורש כי ''פעולה כל שהיא'' אינה רק הפעולה האחרונה, המשלימה, לביצוע פסק הדין, אלא גם פעולות קודמות לכך.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'פעולה לביצוע פסק הדין היא אך ורק פתיחת תיק פינוי בהוצאה לפועל.', false, 'טענה זו שגויה. פסק הדין מבהיר כי ''פעולה כל שהיא'' אינה מצטמצמת אך ורק לפעולה באמצעות רשויות האכיפה (כמו פתיחת תיק הוצאה לפועל).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'פעולה לביצוע פסק הדין היא לא בהכרח פעולה המביאה לפינוי המקרקעין.', true, 'תשובה זו נכונה. פסק הדין קובע כי עצם הקביעה שחזקה הקמה בעקבות פעולה לביצוע פסק הדין ניתנת לסתירה וכי מירוץ ההתיישנות עשוי להתחדש, מלמדת כי אין מדובר בהכרח בפעולה המביאה להשלמת הביצוע של פסק הדין ומימושו.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'פעולה לביצוע פסק הדין יכולה להיות כל פעולה שהיא כל עוד היא תרמה בפועל במבחן התוצאה לפינוי המקרקעין.', false, 'טענה זו שגויה. פסק הדין מבהיר כי ''פעולה כל שהיא'' אינה חייבת להביא בפועל לתוצאה הסופית של הביצוע, אלא די בפעולה המבטאת את עמידת הזוכה על זכותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פעולות נוספות המאפסת מירוץ התיישנות פסק דין',
    1, 'פסק דין לפינוי דירה ניתן לפני 20 שנה. הזוכה לא פתח תיק הוצאה לפועל, אך לפני 5 שנים רשם הערת אזהרה על הנכס מכוח פסק הדין. האם רישום הערת האזהרה נחשב ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות?', 'שאלה זו בוחנת את הפרשנות הרחבה למונח ''פעולה כל שהיא'' בסעיף 21 לחוק ההתיישנות, המאפסת את מירוץ ההתיישנות של פסק דין, ומתמקדת בשאלה האם רישום הערת אזהרה נכלל בהגדרה זו.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי פסק דין מתיישן לאחר 25 שנה אם הזכאי לא עשה ''פעולה כל שהיא כדי לבצעו''. הפסיקה, ובפרט ע"א 8301/98 אנואר נ'' ש.א.פ. בע"מ, קבעה כי המונח ''פעולה כל שהיא'' יפורש באופן רחב וכולל פעולות אפקטיביות שנעשו במטרה להביא לביצוע פסק הדין, ולא רק הליכי הוצאה לפועל פורמליים. ה"פ (מחוזי י-ם) 51681-05-16 שמואל רולנד בן ברון נ'' רחל ורד קבע במפורש כי רישום הערת אזהרה מהווה ''פעולה כלשהי'' בדרך לביצוע פסק הדין, שכן הוא מבטא את כוונת הצדדים לבצע את העסקה ולהביאה לכדי השלמת הרישום, ובכך מפסיק את מירוץ ההתיישנות. לכן, רישום הערת האזהרה במקרה זה יאפס את מירוץ ההתיישנות, והוא יחל מחדש ממועד הרישום.',
    'הטעות הנפוצה היא לחשוב שרק פעולות אכיפה ישירות בלשכת ההוצאה לפועל נחשבות ל''פעולה כל שהיא'', ולהתעלם מפעולות אחרות המבטאות את עמידת הזוכה על זכותו.', '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פעולה לביצוע פסק דין", "הערת אזהרה", "איפוס מירוץ ההתיישנות", "פרשנות רחבה"]'::jsonb, '**וריאציה 1 — הגשת תביעה חדשה:** האם הגשת תביעה חדשה המבוססת על פסק הדין המקורי נחשבת לפעולה? ← כן, הגשת תובענה נוספת לביצועו מאפסת את המירוץ (טל חבקין, התיישנות, 2021, עמ'' 2).
**וריאציה 2 — פעילות מתמשכת:** האם ''מנהג בעלים'' מתמשך (כגון גביית שכר דירה) נחשב לפעולה המאפסת את המירוץ? ← לרוב לא, אם מדובר בהמשך מציאות קיימת ולא באקט חדש המבטא כוונה לבצע את פסק הדין (ה"פ (מחוזי י-ם) 51681-05-16 בן ברון).
**וריאציה 3 — ידיעת החייב:** האם פעולה שלא הובאה לידיעת החייב מאפסת את המירוץ? ← מבחינת טעמי ההתיישנות, יש הטוענים שלא, שכן אינטרס ההסתמכות של החייב לא נפגע (טל חבקין, התיישנות, 2021, עמ'' 2).', 'פעולה לביצוע פסק דין (סעיף 21) ← פרשנות רחבה, כוללת רישום הערת אזהרה ← מאפסת את מירוץ ההתיישנות.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)", "ה\"פ (מחוזי י-ם) 51681-05-16 שמואל רולנד בן ברון נ'' רחל ורד (08.03.2021)", "טל חבקין התיישנות (2021) | פרק עשרים וחמישה סעיף 21 לחוק ההתיישנות - התיישנות פסק דין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, רק פתיחת תיק הוצאה לפועל נחשבת לפעולה המאפסת את מירוץ ההתיישנות.', false, 'טענה זו שגויה. הפסיקה הרחיבה את הפרשנות ל''פעולה כל שהיא'' מעבר לפתיחת תיק הוצאה לפועל, וכוללת פעולות אפקטיביות נוספות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, רישום הערת אזהרה נחשב ל''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות, שכן הוא מבטא את עמידת הזוכה על זכותו.', true, 'תשובה זו נכונה. הפסיקה קבעה כי רישום הערת אזהרה, אף שאינו הליך ביצועי במובן הדווקני, מבטא את כוונת הזוכה לבצע את פסק הדין ומהווה ''פעולה כל שהיא'' המאפסת את מירוץ ההתיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן החייב ידע בפועל על רישום הערת האזהרה.', false, 'טענה זו שגויה. אף שקיימת גישה בספרות הדורשת ידיעה של החייב, הפסיקה לא קבעה זאת כתנאי הכרחי לכל ''פעולה כל שהיא'' המאפסת את המירוץ, במיוחד כאשר מדובר בפעולה פומבית כמו רישום הערת אזהרה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם חלפו פחות מ-25 שנה ממועד מתן פסק הדין המקורי.', false, 'טענה זו שגויה. מטרת ה''פעולה כל שהיא'' היא לאפס את מירוץ ההתיישנות, כלומר להתחיל מניין חדש של 25 שנה ממועד הפעולה, ללא קשר לזמן שחלף קודם לכן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'ההבחנה בין פסק דין טעון ביצוע ללא טעון ביצוע',
    2, 'בית המשפט נתן פסק דין הקובע כי ראובן הוא הבעלים של חלקה מסוימת במקרקעין, אך לא הורה על רישום הבעלות בלשכת רישום המקרקעין. האם פסק דין זה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות?', 'שאלה זו עוסקת בהבחנה בין פסק דין ''טעון ביצוע'' לבין פסק דין ''שאינו טעון ביצוע'' לעניין סעיף 21 לחוק ההתיישנות, וכיצד הבחנה זו משפיעה על תחולת דיני ההתיישנות על פסקי דין הצהרתיים.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי פסק דין ''שאינו טעון ביצוע אינו נתון להתיישנות''. פסק דין טעון ביצוע הוא כזה המחייב את הנתבע לעשות מעשה, כמו חיוב כספי או צו לביצוע בעין. לעומתו, פסק דין שאינו טעון ביצוע הוא פסק דין שאינו מחייב לעשות מעשה, כמו פסק דין הצהרתי מסוג ''חפצא'', שאין צורך לאכוף אותו (ע"א 288/95 לחאם נ'' אל-זארובי, פ"ד נד(2) 598, 610). במקרה זה, פסק הדין רק מצהיר על בעלותו של ראובן בחלקה, אך אינו מורה על פעולה אופרטיבית כלשהי, כגון רישום הבעלות. לכן, הוא נחשב לפסק דין שאינו טעון ביצוע ואינו נתון להתיישנות. יש לציין כי אם פסק הדין היה מורה על רישום הבעלות, הוא היה נחשב לטעון ביצוע (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות פסק דין, עמ'' 89).',
    'הטעות הנפוצה היא להניח שכל פסק דין המעניק זכות במקרקעין הוא ''טעון ביצוע'', גם אם אינו מורה על פעולה אופרטיבית למימוש הזכות.', '["התיישנות פסק דין", "סעיף 21 לחוק ההתיישנות", "פסק דין טעון ביצוע", "פסק דין הצהרתי", "מקרקעין", "רישום זכויות"]'::jsonb, '**וריאציה 1 — פסק דין המורה על רישום:** האם פסק דין המורה על רישום בעלות במקרקעין נתון להתיישנות? ← כן, הוא טעון ביצוע ולכן נתון להתיישנות של 25 שנה (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות, 2026, עמ'' 89).
**וריאציה 2 — פסק דין המאמץ הסכם פשרה:** האם פסק דין המאמץ הסכם פשרה שנזנח על ידי הצדדים נתון להתיישנות? ← לא, במקרה כזה לא יחול סעיף 21 לחוק ההתיישנות (ישראל גלעד, התיישנות בדין האזרחי, 2022, עמ'' 6).
**וריאציה 3 — הרציונל להבחנה:** מהו הרציונל להבחנה בין פסק דין טעון ביצוע ללא טעון ביצוע? ← פסק דין שאינו טעון ביצוע אינו דורש אכיפה, ולכן אין טעם להגביל את תוקפו בזמן (ע"א 288/95 לחאם).', 'פסק דין הצהרתי שאינו מורה על פעולה אופרטיבית ← אינו טעון ביצוע ← אינו נתון להתיישנות (סעיף 21 סיפא לחוק ההתיישנות).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, פ\"ד נד(2) 598 (2000)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | התיישנות פסק דין", "ישראל גלעד התיישנות בדין האזרחי (2022) | פרק שישי תקופת ההתיישנות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, כל פסק דין, למעט פסק דין הצהרתי מובהק שאינו דורש כל פעולה, נתון להתיישנות.', false, 'טענה זו שגויה. פסק דין הצהרתי שאינו דורש פעולה למימוש הזכות אינו נתון להתיישנות. השאלה היא האם פסק דין זה דורש פעולה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, פסק דין המצהיר על זכות בעלות במקרקעין, שאינו מורה על צעד אופרטיבי, אינו טעון ביצוע ולכן אינו נתון להתיישנות.', true, 'תשובה זו נכונה. פסק דין הצהרתי שאינו מחייב לעשות מעשה, כמו פסק דין המצהיר על בעלות ללא הוראה לרישום, אינו טעון ביצוע ולכן אינו נתון להתיישנות, בהתאם לסיפא של סעיף 21 לחוק ההתיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, מכיוון שמימוש זכות הבעלות במקרקעין טעון רישום, ולכן פסק הדין נחשב לטעון ביצוע.', false, 'טענה זו שגויה. אף שמימוש זכות הבעלות טעון רישום, אם פסק הדין עצמו אינו מורה על פעולת הרישום, הוא נחשב לפסק דין הצהרתי שאינו טעון ביצוע לעניין סעיף 21.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן הזוכה הוכיח כי פעל לרישום הבעלות בלשכת רישום המקרקעין.', false, 'טענה זו שגויה. השאלה היא האם פסק הדין טעון ביצוע מלכתחילה, ולא האם הזוכה פעל לביצועו. אם אינו טעון ביצוע, הוא אינו נתון להתיישנות כלל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התיישנות פסק דין נגד המדינה',
    3, 'בית המשפט נתן פסק דין כספי נגד מדינת ישראל. האם פסק דין זה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות, וכיצד מתבצעת ''פעולה לביצועו'' לעניין סעיף זה?', 'שאלה זו בוחנת את תחולת דיני ההתיישנות על פסקי דין כספיים שניתנו נגד המדינה, ואת אופן ביצועם, תוך התייחסות למנגנון הייחודי הקבוע בחוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין).', 'פסק דין שניתן נגד המדינה דינו לעניין הוצאה לפועל כדין כל פסק דין (סעיף 6 לחוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין)). לכן, פסק דין כספי נגד המדינה נתון להתיישנות של 25 שנה לפי סעיף 21 לחוק ההתיישנות. עם זאת, ביצוע פסק דין נגד המדינה אינו מתבצע באמצעות המערכת הרגילה של ההוצאה לפועל. במקום זאת, הפרקליט האחראי מעביר בקשה לתשלום החוב לחשב המשרד הרלוונטי, והוא זה שמשלם לזוכה את הסכום (נבו - המתמחה, דיני הוצאה לפועל (2026) | פסק דין נגד המדינה, עמ'' 122). פעולה זו של העברת הבקשה לתשלום לחשב המשרד הרלוונטי תיחשב ל''פעולה כל שהיא'' לביצוע פסק הדין לעניין סעיף 21 לחוק ההתיישנות, המאפסת את מירוץ ההתיישנות.',
    'הטעות הנפוצה היא להניח שמעמדה המיוחד של המדינה פוטר אותה מדיני ההתיישנות, או לבלבל בין מנגנון הביצוע הייחודי לבין תחולת דיני ההתיישנות.', '["התיישנות פסק דין", "המדינה כבעל דין", "סעיף 21 לחוק ההתיישנות", "הוצאה לפועל נגד המדינה", "פעולה לביצוע פסק דין", "חוק לתיקון סדרי הדין האזרחי (המדינה כבעל דין)"]'::jsonb, '**וריאציה 1 — מטרת ההסדר המיוחד:** מדוע קיים הסדר מיוחד לביצוע פסקי דין נגד המדינה? ← כדי למנוע הליכי אכיפה כופים נגד המדינה ולאפשר תשלום מסודר (נבו - המתמחה, דיני הוצאה לפועל, 2026, עמ'' 122).
**וריאציה 2 — פסק דין לטובת המדינה:** האם פסק דין לטובת המדינה נתון להתיישנות? ← כן, דינו לעניין הוצאה לפועל כדין כל פסק דין (נבו - המתמחה, דיני הוצאה לפועל, 2026, עמ'' 122).
**וריאציה 3 — שיהוי מנהלי:** האם ניתן לטעון לשיהוי מנהלי נגד המדינה בהליכי גבייה? ← כן, הפסיקה הכירה בתחולת דיני השיהוי המנהליים על הליכי גבייה פסיביים של המדינה (עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ).', 'פסק דין נגד המדינה ← נתון להתיישנות 25 שנה (סעיף 21) ← ''פעולה לביצועו'' היא העברת בקשה לתשלום לחשב המשרד הרלוונטי.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "נבו - המתמחה דיני הוצאה לפועל (2026) | פסק דין נגד המדינה", "עע\"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע\"מ (15.04.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'פסק דין נגד המדינה אינו נתון להתיישנות כלל, בשל מעמדה המיוחד של המדינה.', false, 'טענה זו שגויה. פסק דין נגד המדינה נתון להתיישנות, ואין חריג כללי המבטל את תחולת חוק ההתיישנות עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, פסק דין נגד המדינה נתון להתיישנות של 25 שנה, ו''פעולה לביצועו'' היא העברת הבקשה לתשלום לחשב המשרד הרלוונטי.', true, 'תשובה זו נכונה. פסק דין נגד המדינה נתון להתיישנות לפי סעיף 21 לחוק ההתיישנות. ''פעולה לביצועו'' אינה מתבצעת דרך ההוצאה לפועל הרגילה, אלא באמצעות העברת הבקשה לתשלום לחשב המשרד הרלוונטי במשרד האוצר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, פסק דין נגד המדינה נתון להתיישנות של 7 שנים, בדומה לתביעה אזרחית רגילה.', false, 'טענה זו שגויה. תקופת ההתיישנות לפסק דין היא 25 שנה, ולא 7 שנים, גם כאשר המדינה היא החייבת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן המדינה טענה במפורש טענת התיישנות בהזדמנות הראשונה.', false, 'טענה זו שגויה. טענת התיישנות היא טענה דיונית שיש לטעון בהזדמנות הראשונה, אך היא אינה קובעת אם פסק הדין נתון להתיישנות מלכתחילה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השפעת הודאת בעל דין על התיישנות פסק דין',
    4, 'פסק דין כספי ניתן לפני 20 שנה. לפני 10 שנים, החייב הודה בכתב בפני הזוכה בקיום החוב הפסוק. האם הודאה זו מאפסת את מירוץ ההתיישנות של פסק הדין?', 'שאלה זו בוחנת את השפעת הודאת בעל דין על מירוץ ההתיישנות של פסק דין, תוך התייחסות לסעיף 9 לחוק ההתיישנות, המהווה עילה לאיפוס מירוץ ההתיישנות.', 'סעיף 9 לחוק ההתיישנות, תשי"ח-1958, קובע כי ''הודה הנתבע, בכתב או בפני בית משפט, בין בתוך תקופת ההתיישנות ובין לאחריה, בקיום זכות התובע, תתחיל תקופת ההתיישנות מיום ההודאה''. הוראה זו חלה גם על התיישנות פסק דין, שכן פסק דין מקים זכות לזוכה. הודאת החייב בקיום החוב הפסוק מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה (ע"א 8301/98 אנואר נ'' ש.א.פ. בע"מ, פסקה 2). במקרה זה, הודאת החייב בכתב לפני 10 שנים מאפסת את מירוץ ההתיישנות, והוא יחל מחדש ממועד ההודאה. לכן, פסק הדין לא התיישן.',
    'הטעות הנפוצה היא לחשוב שסעיף 9 לחוק ההתיישנות חל רק על עילות תביעה רגילות ולא על פסקי דין, או לבלבל בין ''הודאה'' לבין ''פעולה כל שהיא'' לביצוע פסק דין.', '["התיישנות פסק דין", "סעיף 9 לחוק ההתיישנות", "הודאת בעל דין", "איפוס מירוץ ההתיישנות", "חוב פסוק", "זכות דיונית"]'::jsonb, '**וריאציה 1 — ביצוע מקצת הזכות:** האם ביצוע מקצת הזכות נחשב להודאה? ← כן, מעשה שיש בו משום ביצוע מקצת הזכות, דינו כהודאה לעניין סעיף 9 לחוק ההתיישנות.
**וריאציה 2 — הודאה עם טיעון התיישנות:** האם הודאה שהיה עמה טיעון התיישנות נחשבת להודאה? ← לא, סעיף 9 לחוק ההתיישנות קובע במפורש ''למעט הודאה שהיה עמה טיעון התיישנות''.
**וריאציה 3 — הודאה לאחר תקופת ההתיישנות:** האם הודאה שניתנה לאחר שחלפה תקופת ההתיישנות מאפסת את המירוץ? ← כן, סעיף 9 קובע ''בין בתוך תקופת ההתיישנות ובין לאחריה''.', 'הודאת בעל דין (סעיף 9) ← מאפסת מירוץ התיישנות פסק דין ← מתחיל מחדש מיום ההודאה.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, פ\"ד נו(3) 345 (2002)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, סעיף 9 לחוק ההתיישנות (הודאת בעל דין) אינו חל על התיישנות פסק דין.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות חל גם על התיישנות פסק דין, ומהווה עילה לאיפוס מירוץ ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, הודאת בעל דין בקיום זכות מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה.', true, 'תשובה זו נכונה. סעיף 9 לחוק ההתיישנות קובע כי הודאת בעל דין בקיום זכות מאפסת את מירוץ ההתיישנות, והוא יחל מחדש מיום ההודאה. הוראה זו חלה גם על התיישנות פסק דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, מכיוון שחלפו יותר מ-7 שנים ממועד מתן פסק הדין המקורי.', false, 'טענה זו שגויה. תקופת ההתיישנות לפסק דין היא 25 שנה, והודאת בעל דין מאפסת את המירוץ ללא קשר לזמן שחלף קודם לכן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם ההודאה ניתנה בפני בית משפט ולא בכתב בפני הזוכה.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות מכיר בהודאה ''בכתב או בפני בית משפט''.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 21, '2019-S-S-Q21';
END
$$;

-- ============================================================
-- Q22 — 2019-S-S-Q22 — chapter=corporate subtopic=companies_formation
-- classifier_note: Merger of two private companies — approval requirements
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'cf0da9d7-bf5b-4516-b927-0f851f65fb6b'::uuid;
  v_group_id uuid := 'f4f8f4e1-3e96-407e-b3ee-4b520e07a67b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'd97407e7-9acc-49a8-88ed-cbfd4c29cd7f'::uuid;
  v_ang_1 uuid := 'ea4709aa-64ff-480c-97ec-b205b0d643b1'::uuid;
  v_ang_2 uuid := '64f285d6-f094-4f4b-8ceb-7ca1825f1fd1'::uuid;
  v_ang_3 uuid := '50ab15ba-b84f-467f-bf8d-17f555f01b1c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 22, '2019-S-S-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q22', v_chapter_id, v_subtopic_id, 'חברת ציפורה בע"מ התאגדה ביום 1.1.2000. בעקבות מצבה הכלכלי הרעוע נבחנה האפשרות למיזוגה עם חברת משה בע"מ שהתאגדה ביום 1.1.2002. החברות הן חברות פרטיות. הצעת המיזוג הועברה לאישור האסיפה הכללית של חברת ציפורה בע"מ. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 22}'::jsonb, 'השאלה עוסקת בהוראות המעבר בחוק החברות, התשנ"ט-1999, הנוגעות לאישור מיזוג בחברות שהתאגדו לפני כניסתו לתוקף של החוק. היא מדגישה את הרוב המיוחס הנדרש לאישור מיזוג בחברות אלו, בניגוד לרוב הרגיל הנדרש בחברות חדשות.', 'חוק החברות, התשנ"ט-1999, נכנס לתוקף ביום 1.2.2000 (סעיף 377 לחוק החברות). חברת ציפורה בע"מ התאגדה ביום 1.1.2000, ולכן היא נחשבת לחברה שהתאגדה לפני תחילתו של חוק זה. סעיף 327(א) לחוק החברות קובע הוראת מעבר מיוחדת לעניין מיזוג בחברות כאלה: ''חברה שהתאגדה לפני תחילתו של חוק זה, יראו כאילו קבעה בתקנונה הוראה לפיה אישור מיזוג טעון רוב באסיפה הכללית של שלושה רבעים מקרב בעלי המניות המשתתפים בהצבעה, למעט הנמנעים, ויחולו הוראות סעיף 20''. הוראה זו נועדה לכבד את הציפיות הלגיטימיות של בעלי המניות בחברות ותיקות, שבהן לא די היה ברוב רגיל לאישור שינויים מבניים (צפורה כהן, בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | ב.מכירה כפויה במיזוג, עמ'' 9). לכן, הרוב הנדרש לאישור המיזוג בחברת ציפורה בע"מ הוא שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', 'הטעות הנפוצה היא להתעלם מהוראות המעבר וליישם את הכלל הכללי של רוב רגיל לאישור מיזוג, החל רק על חברות שהתאגדו לאחר כניסת חוק החברות לתוקף.',
    '["מיזוג חברות", "חוק החברות", "הוראות מעבר", "אסיפה כללית", "רוב מיוחס", "חברה ותיקה", "סעיף 327(א)"]'::jsonb, '**וריאציה 1 — חברה חדשה:** מה הרוב הנדרש למיזוג בחברה שהתאגדה אחרי חוק החברות? ← רוב רגיל באסיפה הכללית, אלא אם נקבע אחרת בתקנון (סעיף 320(א) לחוק החברות).
**וריאציה 2 — שינוי תקנון בחברה ותיקה:** מה הרוב הנדרש לשינוי תקנון בחברה ותיקה (ללא הוראה ספציפית בתקנון)? ← 75% מן המשתתפים בהצבעה, למעט הנמנעים (סעיף 24(3) לחוק החברות; ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ, פסקה 8).
**וריאציה 3 — תכלית הוראות המעבר:** מהי תכלית הוראות המעבר בחוק החברות? ← לכבד ציפיות לגיטימיות של בעלי מניות בחברות ותיקות ולהתאים את הדין החדש למבנים קיימים (צפורה כהן, בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'', 2006, עמ'' 9).', 'חברה שהתאגדה לפני 1.2.2000 ← אישור מיזוג באסיפה כללית ← רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים (סעיף 327(א) לחוק החברות).', '["חוק החברות, תשנ\"ט-1999, סעיף 20", "חוק החברות, תשנ\"ט-1999, סעיף 327", "חוק החברות, תשנ\"ט-1999, סעיף 377", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | ב.מכירה כפויה במיזוג", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Merger of two private companies — approval requirements | source_review_note: השאלה עוסקת בדיני חברות, תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני חברות'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לצורך אישור ההצעה נדרש רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', true, 'תשובה זו נכונה. חברת ציפורה התאגדה לפני כניסתו לתוקף של חוק החברות (1.2.2000), ולכן חל עליה סעיף 327(א) לחוק, הקובע רוב מיוחס של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים, לאישור מיזוג.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לצורך אישור ההצעה נדרש רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, כולל נמנעים.', false, 'טענה זו שגויה. סעיף 327(א) לחוק החברות קובע במפורש כי הרוב הנדרש הוא ''למעט הנמנעים''.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לצורך אישור ההצעה נדרש רוב של מחצית (רוב רגיל) מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', false, 'טענה זו שגויה. רוב רגיל נדרש לחברות שהתאגדו לאחר כניסת חוק החברות לתוקף, ולא לחברות ותיקות כמו חברת ציפורה, אלא אם נקבע אחרת בתקנון.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לצורך אישור ההצעה נדרש רוב של מחצית (רוב רגיל) מבעלי המניות המשתתפים בהצבעה, כולל נמנעים.', false, 'טענה זו שגויה. רוב רגיל אינו הרוב הנדרש לחברות ותיקות, ובכל מקרה, נמנעים אינם נכללים במניין הקולות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'רוב נדרש למיזוג בחברה חדשה',
    1, 'חברת אלפא בע"מ התאגדה ביום 1.1.2005. הצעת מיזוג עם חברת בטא בע"מ הועברה לאישור האסיפה הכללית של חברת אלפא בע"מ. מה הרוב הנדרש לאישור המיזוג, בהיעדר הוראה אחרת בתקנון?', 'שאלה זו בוחנת את הרוב הנדרש לאישור מיזוג בחברה שהתאגדה לאחר כניסתו לתוקף של חוק החברות, בהתאם לכלל ברירת המחדל הקבוע בסעיף 320(א) לחוק החברות.', 'סעיף 320(א) לחוק החברות, התשנ"ט-1999, קובע כי מיזוג טעון אישור האסיפה הכללית של כל אחת מהחברות המתמזגות. הרוב הנדרש לאישור מיזוג הוא רוב רגיל, אלא אם כן נקבע אחרת בתקנון החברה (יוסף גרוס, חוק החברות (2016) | 12. אישור האסיפה הכללית, עמ'' 25). רוב רגיל משמעו רוב של מחצית מבעלי המניות המשתתפים בהצבעה, למעט הנמנעים. חברת אלפא התאגדה בשנת 2005, כלומר לאחר כניסתו לתוקף של חוק החברות (1.2.2000, סעיף 377 לחוק החברות). לכן, בהיעדר הוראה אחרת בתקנון, הרוב הנדרש לאישור המיזוג הוא רוב רגיל מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.',
    'הטעות הנפוצה היא לבלבל בין הרוב הנדרש לחברות שהתאגדו לפני חוק החברות (שלושה רבעים) לבין הרוב הנדרש לחברות שהתאגדו אחריו (רוב רגיל).', '["מיזוג חברות", "חוק החברות", "אסיפה כללית", "רוב רגיל", "הוראות מעבר", "סעיף 320(א)"]'::jsonb, '**וריאציה 1 — חברה ותיקה:** מה הרוב הנדרש למיזוג בחברה שהתאגדה לפני חוק החברות? ← שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים (סעיף 327(א) לחוק החברות).
**וריאציה 2 — שינוי תקנון:** מה הרוב הנדרש לשינוי תקנון בחברה חדשה? ← רוב רגיל באסיפה הכללית, אלא אם נקבע אחרת בתקנון (סעיף 20(א) לחוק החברות).
**וריאציה 3 — נמנעים:** האם קולות נמנעים נספרים במניין הרוב? ← לא, הרוב מחושב מקרב המשתתפים בהצבעה, למעט הנמנעים (סעיפים 20(א), 320(א), 327(א) לחוק החברות).', 'חברה חדשה (לאחר 1.2.2000) ← אישור מיזוג באסיפה כללית ← רוב רגיל (סעיף 320(א) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 20(א)", "חוק החברות, תשנ\"ט-1999, סעיף 320(א)", "חוק החברות, תשנ\"ט-1999, סעיף 377", "יוסף גרוס חוק החברות (2016) | 12. אישור האסיפה הכללית"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'רוב רגיל (מחצית) מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', true, 'תשובה זו נכונה. חברת אלפא התאגדה לאחר כניסתו לתוקף של חוק החברות, ולכן חל הכלל הקבוע בסעיף 320(א) לחוק, הדורש רוב רגיל לאישור מיזוג, אלא אם נקבע אחרת בתקנון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'רוב רגיל (מחצית) מבעלי המניות המשתתפים בהצבעה, כולל נמנעים.', false, 'טענה זו שגויה. גם ברוב רגיל, נמנעים אינם נכללים במניין הקולות, אלא אם נקבע אחרת במפורש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', false, 'טענה זו שגויה. רוב של שלושה רבעים נדרש לחברות שהתאגדו לפני כניסת חוק החברות לתוקף, ולא לחברות חדשות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'שלושה רבעים מבעלי המניות המשתתפים בהצבעה, כולל נמנעים.', false, 'טענה זו שגויה. רוב של שלושה רבעים אינו הרוב הנדרש לחברות חדשות, ובכל מקרה, נמנעים אינם נכללים במניין הקולות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת מיזוג בחוק החברות',
    2, 'מהם המאפיינים המרכזיים של ''מיזוג'' כהגדרתו בחוק החברות, התשנ"ט-1999?', 'שאלה זו בוחנת את הבנת המונח ''מיזוג'' כפי שהוא מוגדר בחוק החברות, תוך התמקדות במאפייניו המהותיים המבחינים אותו מצורות אחרות של שינוי מבנה תאגידי.', 'הגדרת ''מיזוג'' בסעיף 1 לחוק החברות, התשנ"ט-1999, קובעת כי מיזוג הוא ''העברה של כלל הנכסים והחיובים, לרבות חיובים מותנים, עתידיים, ידועים ובלתי ידועים, של חברת יעד לחברה קולטת, אשר כתוצאה ממנה מתחסלת חברת היעד, בהתאם לסעיף 323''. הגדרה זו מצביעה על שני מאפיינים מרכזיים: ראשית, העברת מכלול הנכסים והחיובים של חברת היעד לחברה הקולטת; ושנית, חיסולה של חברת היעד (אירית חביב-סגל, דיני חברות - כרך ב (2007) | 2. עסקת המיזוג, עמ'' 5). לכן, התשובה הנכונה היא זו המדגישה את שני המאפיינים הללו.',
    'הטעות הנפוצה היא לבלבל בין מיזוג לבין רכישת מניות או רכישת נכסים, שאינם כרוכים בחיסול החברה הנרכשת או בהעברת כלל נכסיה וחיובים.', '["מיזוג חברות", "חוק החברות", "חברת יעד", "חברה קולטת", "חיסול חברה", "העברת נכסים וחיובים"]'::jsonb, '**וריאציה 1 — מיזוג משולש הופכי:** מהו מיזוג משולש הופכי? ← מיזוג שבו חברת יעד מתמזגת עם ולתוך חברת בת של החברה הקולטת, באופן שחברת היעד הופכת לחברת בת של החברה הקולטת (ת"צ (כלכלית) 25349-03-20 מיכל רוה נ'' ICC Industrues, Inc.).
**וריאציה 2 — אישור דירקטוריון:** האם מיזוג דורש אישור דירקטוריון? ← כן, בכל אחת מהחברות המתמזגות (יוסף גרוס, חוק החברות, 2016, עמ'' 19).
**וריאציה 3 — הגנת נושים:** אילו הגנות קיימות לנושים במיזוג? ← הנושים רשאים לפנות לבית המשפט אם קיים חשש לפגיעה ביכולת החברה הקולטת לעמוד בהתחייבויותיה, וקיימת חובת אמונים מוגברת של קברניטי החברה כלפי הנושים (אירית חביב-סגל, דיני חברות - כרך ב, 2007, עמ'' 5).', 'מיזוג ← העברת כלל נכסים וחיובים + חיסול חברת היעד (סעיף 1 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 1", "חוק החברות, תשנ\"ט-1999, סעיף 323", "אירית חביב-סגל דיני חברות - כרך ב (2007) | 2. עסקת המיזוג", "ת\"צ (כלכלית) 25349-03-20 מיכל רוה נ'' ICC Industrues, Inc (17.09.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'העברת כלל הנכסים והחיובים של חברת יעד לחברה קולטת, וחיסול חברת היעד.', true, 'תשובה זו נכונה. הגדרת ''מיזוג'' בסעיף 1 לחוק החברות כוללת את שני המאפיינים המרכזיים הללו: העברת מכלול הנכסים והחיובים, וחיסול החברה המעבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'רכישת מניות שליטה בחברה אחרת, ללא חיסול החברה הנרכשת.', false, 'טענה זו שגויה. רכישת מניות שליטה היא דרך אחרת לשינוי מבנה שליטה, אך אינה מיזוג כהגדרתו בחוק, שכן היא אינה כרוכה בחיסול החברה הנרכשת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הסכם לשיתוף פעולה עסקי בין שתי חברות, ללא שינוי במבנה הבעלות.', false, 'טענה זו שגויה. הסכם לשיתוף פעולה אינו מיזוג, שכן הוא אינו כרוך בהעברת נכסים וחיובים או בחיסול חברה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'העברת נכסים מסוימים מחברה אחת לאחרת, תוך שמירה על קיומן של שתי החברות.', false, 'טענה זו שגויה. העברת נכסים מסוימים היא מכירת נכסים, ולא מיזוג, שכן מיזוג כולל את כלל הנכסים והחיובים וחיסול החברה המעבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אישור מיזוג בחברה עם מניות סוגים',
    3, 'חברת גמא בע"מ, שהתאגדה בשנת 2003, מחזיקה במניות רגילות ובמניות בכורה. הצעת מיזוג עם חברה אחרת עלולה לפגוע בזכויותיהם של בעלי מניות הבכורה. מהו הרוב הנדרש לאישור המיזוג במקרה זה?', 'שאלה זו בוחנת את הרוב הנדרש לאישור מיזוג בחברה בעלת מניות מסוגים שונים, כאשר המיזוג עלול לפגוע בזכויות סוג מסוים, בהתאם לסעיף 20(ג) לחוק החברות.', 'סעיף 20(ג) לחוק החברות, התשנ"ט-1999, קובע כי ''היו מניות החברה מחולקות לסוגים, לא ייעשה שינוי בתקנון שיפגע בזכויותיו של סוג מניות ללא אישור אסיפת אותו סוג, אלא אם כן נקבע אחרת בתקנון''. הוראה זו חלה גם על אישור מיזוג, שכן מיזוג יכול להיחשב כשינוי בתקנון הפוגע בזכויות סוג (יוסף גרוס, חוק החברות (2016) | 7.4 שינוי בזכויות סוג, עמ'' 13). בנוסף, סעיף 320(ב) לחוק החברות קובע כי אם בחברת יעד קיימות מניות המחולקות לסוגים, דרושה אסיפה כללית של כל אחד מסוגי המניות. לכן, במקרה זה, נדרש אישור האסיפה הכללית ברוב רגיל, וכן אישור של אסיפה נפרדת של בעלי מניות הבכורה, שזכויותיהם נפגעות מהמיזוג.',
    'הטעות הנפוצה היא להתעלם מהדרישה לאישור אסיפת סוג כאשר מניות החברה מחולקות לסוגים שונים וזכויותיהם נפגעות.', '["מיזוג חברות", "מניות סוגים", "זכויות סוג", "אסיפת סוג", "חוק החברות סעיף 20(ג)", "חוק החברות סעיף 320(ב)"]'::jsonb, '**וריאציה 1 — חברה ותיקה עם מניות סוגים:** מה הרוב הנדרש למיזוג בחברה ותיקה עם מניות סוגים? ← שלושה רבעים באסיפה הכללית, וכן אישור אסיפת סוג (סעיף 327(א) ו-20(ג) לחוק החברות).
**וריאציה 2 — שינוי תקנון הפוגע בזכויות סוג:** האם שינוי תקנון הפוגע בזכויות סוג דורש אישור אסיפת סוג? ← כן, אלא אם נקבע אחרת בתקנון (סעיף 20(ג) לחוק החברות).
**וריאציה 3 — הגנה על המיעוט:** מהי התכלית של דרישת אישור אסיפת סוג? ← להגן על בעלי מניות המיעוט בסוג מסוים מפני פגיעה בזכויותיהם על ידי רוב בעלי המניות הכללי (ע"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט, פסקה 30).', 'מיזוג בחברה עם מניות סוגים ← אישור אסיפה כללית + אישור אסיפת סוג שזכויותיו נפגעות (סעיף 20(ג) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "חוק החברות, תשנ\"ט-1999, סעיף 320(ב)", "יוסף גרוס חוק החברות (2016) | 7.4 שינוי בזכויות סוג", "ע\"א 3432/17 שי טופז (יוכט) נ'' חיים יוכט (16.04.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'אישור האסיפה הכללית ברוב רגיל בלבד.', false, 'טענה זו שגויה. כאשר יש פגיעה בזכויות סוג, נדרש אישור נוסף של אסיפת הסוג.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'אישור האסיפה הכללית ברוב רגיל, וכן אישור של אסיפה נפרדת של בעלי מניות הבכורה.', true, 'תשובה זו נכונה. סעיף 20(ג) לחוק החברות קובע כי שינוי בתקנון שיפגע בזכויותיו של סוג מניות דורש אישור אסיפת אותו סוג, בנוסף לאישור האסיפה הכללית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'אישור של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, ללא צורך באסיפת סוג.', false, 'טענה זו שגויה. רוב של שלושה רבעים אינו הרוב הנדרש לחברה שהתאגדה לאחר חוק החברות, ובכל מקרה, אינו מייתר את הצורך באסיפת סוג כאשר יש פגיעה בזכויות סוג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'אישור בית המשפט בלבד, ללא צורך באישור בעלי המניות.', false, 'טענה זו שגויה. אישור בית המשפט אינו מחליף את אישור בעלי המניות במיזוג, אלא מתווסף במקרים מסוימים או כסעד לבעלי מניות מתנגדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעד הערכה בהצעת רכש מלאה',
    4, 'חברת דלתא בע"מ הגישה הצעת רכש מלאה למניות חברת אפסילון בע"מ. ההצעה התקבלה, ובעלי מניות מתנגדים נאלצו למכור את מניותיהם. אחד מבעלי המניות המתנגדים סבור כי התמורה שקיבל הייתה פחותה משווין ההוגן של המניות. איזה סעד עומד לרשותו?', 'שאלה זו עוסקת בסעד הערכה הניתן לבעלי מניות מתנגדים בהצעת רכש מלאה, בהתאם לסעיף 338 לחוק החברות, המאפשר לבית המשפט לקבוע את השווי ההוגן של המניות.', 'סעיף 338 לחוק החברות, התשנ"ט-1999, קובע כי ''בית המשפט רשאי, לבקשתו של כל מי שהיה ניצע בהצעת רכש מלאה שהתקבלה כאמור בסעיפים 336(ג) ו-337(א) או (א1), לקבוע, כי התמורה בעבור המניות היתה פחות משוויין ההוגן, וכי יש לשלם את השווי ההוגן, כפי שיקבע בית המשפט''. סעד זה, המכונה ''סעד הערכה'', נועד להגן על בעלי מניות המיעוט מפני כפיית מכירה בתמורה שאינה הוגנת (רע"א 779/06 קיטאל החזקות ופיתוח בינלאומי בע"מ נ'' שאול ממן, פסקה 6). לכן, בעל המניות המתנגד רשאי לפנות לבית המשפט בבקשה לקבוע את השווי ההוגן של מניותיו.',
    'הטעות הנפוצה היא לחשוב שאין סעד לבעלי מניות מתנגדים בהצעת רכש מלאה, או לבלבל בין סעד הערכה לבין סעדים אחרים כמו ביטול העסקה או תביעת קיפוח.', '["הצעת רכש מלאה", "סעד הערכה", "שווי הוגן", "חוק החברות סעיף 338", "בעלי מניות מתנגדים", "הגנת המיעוט"]'::jsonb, '**וריאציה 1 — הגבלת סעד הערכה:** האם המציע רשאי להגביל את האפשרות לבקש סעד הערכה? ← כן, למעט במקרים שבהם לא עמד בחובות הגילוי המוטלות עליו (רע"א 779/06 קיטאל, פסקה 9).
**וריאציה 2 — שיטת הערכה:** איזו שיטת הערכה מועדפת לקביעת שווי הוגן? ← שיטת ה-DCF (Discounted Cash Flow) היא שיטת בסיס מועדפת, אלא אם כן נסיבות המקרה מצדיקות שיטה אחרת (רע"א 779/06 קיטאל, מיני-רציו).
**וריאציה 3 — מיזוג מול הצעת רכש:** האם סעד הערכה קיים גם במיזוג? ← כן, סעד הערכה קיים הן במיזוגים והן בהצעת רכש מלאה (רע"א 779/06 קיטאל, פסקה 10).', 'הצעת רכש מלאה ← בעל מניות מתנגד שקיבל תמורה לא הוגנת ← רשאי לבקש מבית המשפט לקבוע שווי הוגן (סעיף 338 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 338", "רע\"א 779/06 קיטאל החזקות ופיתוח בינלאומי בע\"מ נ'' שאול ממן (28.08.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בעל המניות רשאי לפנות לבית המשפט בבקשה שיקבע כי התמורה שקיבל הייתה פחותה משווין ההוגן של המניות, וכי יש לשלם לו את השווי ההוגן.', true, 'תשובה זו נכונה. סעיף 338 לחוק החברות מקנה לניצע בהצעת רכש מלאה שהתקבלה את הזכות לפנות לבית המשפט בבקשה לקבוע את השווי ההוגן של מניותיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בעל המניות רשאי לבטל את עסקת המכירה של מניותיו, שכן היא נכפתה עליו.', false, 'טענה זו שגויה. הצעת רכש מלאה מאפשרת כפיית מכירה על בעלי מניות מתנגדים, ואין להם זכות לבטל את העסקה לאחר שהתקבלה כדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בעל המניות רשאי לתבוע את החברה בגין קיפוח המיעוט, ללא קשר לשווי ההוגן.', false, 'טענה זו שגויה. אף שקיפוח מיעוט הוא סעד אפשרי במקרים מסוימים, במקרה של הצעת רכש מלאה, הסעד הספציפי והישיר הוא סעד הערכה לפי סעיף 338 לחוק החברות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בעל המניות אינו זכאי לכל סעד, שכן ההצעה התקבלה כדין.', false, 'טענה זו שגויה. חוק החברות מעניק סעד ספציפי לבעלי מניות מתנגדים בהצעת רכש מלאה, גם אם ההצעה התקבלה כדין, כדי להבטיח תמורה הוגנת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 22, '2019-S-S-Q22';
END
$$;

-- ============================================================
-- Q23 — 2019-S-S-Q23 — chapter=corporate subtopic=companies_formation
-- classifier_note: Changing limited→unlimited liability via article amendment
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b9b930b4-2e41-4e26-a33b-6d149a73b3e3'::uuid;
  v_group_id uuid := '7e0a78c3-36d7-4de8-bc35-200d6061c9d6'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '832f8c4a-5a9c-46a5-abb3-163ba2d8f200'::uuid;
  v_ang_1 uuid := '6937c35e-dd92-43ef-bfda-a4ff9bd17e4b'::uuid;
  v_ang_2 uuid := 'a7fc79ec-eefd-4179-a491-1a8cafdca387'::uuid;
  v_ang_3 uuid := 'fa75211a-e012-4b32-9522-ade7097b2deb'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q23';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 23, '2019-S-S-Q23';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q23', v_chapter_id, v_subtopic_id, 'חברת שרה בע"מ היא חברה שאחריות בעלי המניות בה היא מוגבלת. החברה התאגדה ביום 1.1.2017. בדעת בעלי המניות בחברה לשנות את תקנון החברה כך שהיא תהפוך להיות חברה שאחריות בעלי המניות בה היא בלתי מוגבלת. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 23}'::jsonb, 'השאלה עוסקת בהוראות המעבר בחוק החברות, התשנ"ט-1999, הנוגעות לאישור מיזוג בחברות שהתאגדו לפני כניסתו לתוקף של החוק. היא מדגישה את הרוב המיוחס הנדרש לאישור מיזוג בחברות אלו, בניגוד לרוב הרגיל הנדרש בחברות חדשות.', 'חוק החברות, התשנ"ט-1999, נכנס לתוקף ביום 1.2.2000 (סעיף 377 לחוק החברות). חברת ציפורה בע"מ התאגדה ביום 1.1.2000, ולכן היא נחשבת לחברה שהתאגדה לפני תחילתו של חוק זה. סעיף 327(א) לחוק החברות קובע הוראת מעבר מיוחדת לעניין מיזוג בחברות כאלה: ''חברה שהתאגדה לפני תחילתו של חוק זה, יראו כאילו קבעה בתקנונה הוראה לפיה אישור מיזוג טעון רוב באסיפה הכללית של שלושה רבעים מקרב בעלי המניות המשתתפים בהצבעה, למעט הנמנעים, ויחולו הוראות סעיף 20''. הוראה זו נועדה לכבד את הציפיות הלגיטימיות של בעלי המניות בחברות ותיקות, שבהן לא די היה ברוב רגיל לאישור שינויים מבניים (צפורה כהן, בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | ב.מכירה כפויה במיזוג, עמ'' 9). לכן, הרוב הנדרש לאישור המיזוג בחברת ציפורה בע"מ הוא שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', 'הטעות הנפוצה היא להתעלם מהוראות המעבר וליישם את הכלל הכללי של רוב רגיל לאישור מיזוג, החל רק על חברות שהתאגדו לאחר כניסת חוק החברות לתוקף.',
    '["מיזוג חברות", "חוק החברות", "הוראות מעבר", "אסיפה כללית", "רוב מיוחס", "חברה ותיקה", "סעיף 327(א)"]'::jsonb, '**וריאציה 1 — חברה חדשה:** מה הרוב הנדרש למיזוג בחברה שהתאגדה אחרי חוק החברות? ← רוב רגיל באסיפה הכללית, אלא אם נקבע אחרת בתקנון (סעיף 320(א) לחוק החברות).
**וריאציה 2 — שינוי תקנון בחברה ותיקה:** מה הרוב הנדרש לשינוי תקנון בחברה ותיקה (ללא הוראה ספציפית בתקנון)? ← 75% מן המשתתפים בהצבעה, למעט הנמנעים (סעיף 24(3) לחוק החברות; ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ, פסקה 8).
**וריאציה 3 — תכלית הוראות המעבר:** מהי תכלית הוראות המעבר בחוק החברות? ← לכבד ציפיות לגיטימיות של בעלי מניות בחברות ותיקות ולהתאים את הדין החדש למבנים קיימים (צפורה כהן, בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'', 2006, עמ'' 9).', 'חברה שהתאגדה לפני 1.2.2000 ← אישור מיזוג באסיפה כללית ← רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים (סעיף 327(א) לחוק החברות).', '["חוק החברות, תשנ\"ט-1999, סעיף 20", "חוק החברות, תשנ\"ט-1999, סעיף 327", "חוק החברות, תשנ\"ט-1999, סעיף 377", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | ב.מכירה כפויה במיזוג", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Changing limited→unlimited liability via article amendment | source_review_note: השאלה עוסקת בדיני חברות, תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני חברות'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לצורך השינוי נדרשת הסכמה של לפחות מחצית מבעלי המניות בחברה.', false, 'טענה זו שגויה. שינוי המטיל אחריות בלתי מוגבלת על בעל מניה דורש הסכמה פה אחד, ולא רוב רגיל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לצורך השינוי נדרשת הסכמה של בעלי מניות המחזיקים לפחות מחצית ממניות החברה.', false, 'טענה זו שגויה. שינוי המטיל אחריות בלתי מוגבלת על בעל מניה דורש הסכמה פה אחד, ולא רוב רגיל של המניות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לצורך השינוי נדרשת הסכמה של בעלי מניות המחזיקים לפחות שלושה רבעים ממניות החברה.', false, 'טענה זו שגויה. רוב של שלושה רבעים נדרש לשינויים מסוימים בתקנון, אך לא לשינוי המטיל אחריות בלתי מוגבלת, הדורש הסכמה פה אחד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לצורך השינוי נדרשת הסכמה של כלל בעלי המניות בחברה.', true, 'תשובה זו נכונה. סעיף 344(ב) לחוק החברות קובע כי שינוי בתקנון המטיל אחריות בלתי מוגבלת על בעל מניה טעון הסכמת כל בעלי המניות בחברה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שינוי אחריות מוגבלת לבלתי מוגבלת בחברה ציבורית',
    1, 'חברת אלפא בע"מ היא חברה ציבורית שאחריות בעלי המניות בה מוגבלת. בדעת בעלי המניות בחברה לשנות את תקנון החברה כך שהיא תהפוך להיות חברה שאחריות בעלי המניות בה היא בלתי מוגבלת. מה הדין?', 'בחינת תחולת הדרישה להסכמה פה אחד לשינוי אחריות מוגבלת לבלתי מוגבלת גם על חברות ציבוריות, והדגשת האוניברסליות של סעיף 344(ב) לחוק החברות.', 'סעיף 344(ב) לחוק החברות, התשנ"ט-1999, קובע באופן גורף כי ''שינוי בתקנון חברה, המטיל אחריות בלתי מוגבלת על בעל מניה, טעון הסכמת כל בעלי המניות בחברה''. הוראה זו אינה מבחינה בין חברה פרטית לציבורית, והיא חלה על כל סוגי החברות. הרציונל לדרישה המחמירה של הסכמה פה אחד נובע מההגנה על אינטרס בעלי המניות שלא יוטל עליהם סיכון אישי נוסף ללא הסכמתם המפורשת.',
    'סטודנטים עלולים לחשוב שקיימת הבחנה בין חברות פרטיות לציבוריות לעניין זה, בדומה להבחנות אחרות הקיימות בחוק החברות.', '["חברה ציבורית", "אחריות מוגבלת", "אחריות בלתי מוגבלת", "הסכמה פה אחד", "סעיף 344(ב) לחוק החברות"]'::jsonb, '**וריאציה 1 — חברה ממשלתית:** האם סעיף 344(ב) חל גם על חברה ממשלתית? ← כן, חוק החברות חל על חברות ממשלתיות בשינויים המחויבים (סעיף 345 לחוק החברות).
**וריאציה 2 — שינוי שם חברה:** מה הרוב הנדרש לשינוי שם חברה ציבורית? ← רוב רגיל באסיפה הכללית (סעיף 20(א) לחוק החברות).
**וריאציה 3 — תכלית ההגנה:** מדוע נדרשת הסכמה פה אחד לשינוי אחריות? ← כדי להגן על בעלי המניות מפני הטלת אחריות אישית בלתי מוגבלת ללא הסכמתם המפורשת, שכן אחריות מוגבלת היא מאפיין יסודי של חברה (צפורה כהן, בעלי מניות בחברה - כרך א'', 2006, עמ'' 12).', 'שינוי אחריות מוגבלת לבלתי מוגבלת ← דורש הסכמת כל בעלי המניות, גם בחברה ציבורית (סעיף 344(ב)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 344(ב)", "חוק החברות, תשנ\"ט-1999, סעיף 345", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך א'' (2006) | 1. אחריות בעלי מניות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לצורך השינוי נדרשת הסכמה של לפחות מחצית מבעלי המניות בחברה.', false, 'טענה זו שגויה. שינוי המטיל אחריות בלתי מוגבלת על בעל מניה דורש הסכמה פה אחד, ולא רוב רגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לצורך השינוי נדרשת הסכמה של בעלי מניות המחזיקים לפחות מחצית ממניות החברה.', false, 'טענה זו שגויה. שינוי המטיל אחריות בלתי מוגבלת על בעל מניה דורש הסכמה פה אחד, ולא רוב רגיל של המניות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לצורך השינוי נדרשת הסכמה של בעלי מניות המחזיקים לפחות שלושה רבעים ממניות החברה.', false, 'טענה זו שגויה. רוב של שלושה רבעים נדרש לשינויים מסוימים בתקנון, אך לא לשינוי המטיל אחריות בלתי מוגבלת, הדורש הסכמה פה אחד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לצורך השינוי נדרשת הסכמה של כלל בעלי המניות בחברה.', true, 'תשובה זו נכונה. סעיף 344(ב) לחוק החברות קובע כי שינוי המטיל אחריות בלתי מוגבלת על בעל מניה טעון הסכמת כל בעלי המניות בחברה, ללא הבחנה בין חברה פרטית לציבורית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'שינוי תקנון הפוגע בזכויות בעלי מניות',
    2, 'חברת בטא בע"מ, חברה פרטית, מעוניינת לשנות את תקנונה באופן שיפחית את זכויות הדיבידנד של בעלי מניות מסוימים. מה הרוב הנדרש לאישור שינוי זה?', 'שאלה זו בוחנת את הרוב הנדרש לשינוי תקנון חברה כאשר השינוי פוגע בזכויות בעלי מניות, בהתאם לסעיף 20(ב) לחוק החברות.', 'סעיף 20(ב) לחוק החברות, התשנ"ט-1999, קובע כי ''שינוי בתקנון שיפגע בזכויותיו של בעל מניה, טעון אישור האסיפה הכללית ברוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט הנמנעים, אלא אם כן נקבע אחרת בתקנון''. הפחתת זכויות דיבידנד נחשבת לפגיעה בזכויות בעל מניה. לכן, בהיעדר הוראה אחרת בתקנון, נדרש רוב מיוחס של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.',
    'הטעות הנפוצה היא לבלבל בין הרוב הרגיל הנדרש לשינוי תקנון שאינו פוגע בזכויות, לבין הרוב המיוחס הנדרש כאשר יש פגיעה בזכויות בעלי מניות.', '["שינוי תקנון", "זכויות בעלי מניות", "רוב מיוחס", "אסיפה כללית", "סעיף 20(ב) לחוק החברות", "דיבידנד"]'::jsonb, '**וריאציה 1 — שינוי תקנון שאינו פוגע בזכויות:** מה הרוב הנדרש לשינוי תקנון שאינו פוגע בזכויות בעלי מניות? ← רוב רגיל באסיפה הכללית (סעיף 20(א) לחוק החברות).
**וריאציה 2 — פגיעה בזכויות סוג:** מה הרוב הנדרש אם השינוי פוגע בזכויות של סוג מניות מסוים? ← בנוסף לרוב המיוחס באסיפה הכללית, נדרש גם אישור אסיפת אותו סוג מניות (סעיף 20(ג) לחוק החברות).
**וריאציה 3 — תכלית הרוב המיוחס:** מהי התכלית של דרישת הרוב המיוחס במקרה של פגיעה בזכויות? ← להגן על בעלי מניות המיעוט מפני שינויים הפוגעים בזכויותיהם על ידי בעלי מניות הרוב (צפורה כהן, בעלי מניות בחברה - כרך ב'', 2006, עמ'' 13).', 'שינוי תקנון הפוגע בזכויות בעל מניה ← רוב של שלושה רבעים באסיפה הכללית (סעיף 20(ב) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 20(ב)", "חוק החברות, תשנ\"ט-1999, סעיף 20(א)", "חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך ב'' (2006) | 1. אחריות בעלי מניות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'רוב רגיל באסיפה הכללית.', false, 'טענה זו שגויה. רוב רגיל אינו מספיק כאשר השינוי פוגע בזכויות בעלי מניות מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים.', true, 'תשובה זו נכונה. סעיף 20(ב) לחוק החברות קובע כי שינוי בתקנון הפוגע בזכויות בעל מניה דורש רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, למעט נמנעים, אלא אם נקבע אחרת בתקנון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הסכמה של כלל בעלי המניות בחברה.', false, 'טענה זו שגויה. הסכמה פה אחד נדרשת רק לשינוי המטיל אחריות בלתי מוגבלת, ולא לכל שינוי הפוגע בזכויות בעלי מניות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אישור בית המשפט בלבד.', false, 'טענה זו שגויה. אישור בית המשפט אינו מחליף את אישור בעלי המניות, אלא מתווסף במקרים מסוימים או כסעד לבעלי מניות מקופחים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שינוי אחריות מוגבלת לבלתי מוגבלת בחברה בעלת מניות סוגים',
    3, 'חברת גמא בע"מ היא חברה פרטית בעלת מניות רגילות ומניות בכורה. בדעת בעלי המניות בחברה לשנות את תקנון החברה כך שהיא תהפוך להיות חברה שאחריות בעלי המניות בה היא בלתי מוגבלת. מה הרוב הנדרש לאישור שינוי זה?', 'שאלה זו בוחנת את הרוב הנדרש לשינוי אחריות מוגבלת לבלתי מוגבלת בחברה בעלת מניות סוגים, תוך התייחסות לדרישת הסכמה פה אחד (סעיף 344(ב)) אל מול דרישת אסיפת סוג (סעיף 20(ג)).', 'סעיף 344(ב) לחוק החברות קובע כי שינוי המטיל אחריות בלתי מוגבלת על בעל מניה טעון הסכמת כל בעלי המניות בחברה. דרישה זו היא הדרישה המחמירה ביותר בחוק החברות. סעיף 20(ג) לחוק קובע כי שינוי בתקנון שיפגע בזכויותיו של סוג מניות דורש אישור אסיפת אותו סוג. במקרה של שינוי אחריות מוגבלת לבלתי מוגבלת, מדובר בפגיעה מהותית בזכויות כל בעלי המניות, מכל הסוגים. מכיוון שסעיף 344(ב) דורש הסכמה של ''כל בעלי המניות'', הרי שהסכמה זו כוללת בהכרח את הסכמת כל בעלי המניות מכל סוג, ולכן היא מייתרת את הצורך בקיום אסיפות סוג נפרדות. הסכמה פה אחד של כלל בעלי המניות היא דרישה חזקה יותר וכוללת את דרישת אסיפת הסוג.',
    'הטעות הנפוצה היא לחשוב שיש צורך בדרישה כפולה: גם הסכמה פה אחד של כלל בעלי המניות וגם אסיפות סוג נפרדות. בפועל, הסכמה פה אחד של כלל בעלי המניות כוללת את הסכמת כל סוגי המניות.', '["אחריות מוגבלת", "אחריות בלתי מוגבלת", "מניות סוגים", "הסכמה פה אחד", "אסיפת סוג", "סעיף 344(ב) לחוק החברות", "סעיף 20(ג) לחוק החברות"]'::jsonb, '**וריאציה 1 — שינוי שם חברה עם מניות סוגים:** מה הרוב הנדרש לשינוי שם חברה בעלת מניות סוגים? ← רוב רגיל באסיפה הכללית, ללא צורך באסיפת סוג, שכן שינוי שם אינו פוגע בזכויות סוג (סעיף 20(א) לחוק החברות).
**וריאציה 2 — שינוי זכויות הצבעה של סוג:** מה הרוב הנדרש לשינוי בתקנון המפחית את זכויות ההצבעה של סוג מניות מסוים? ← רוב של שלושה רבעים באסיפה הכללית, וכן אישור אסיפת אותו סוג מניות (סעיף 20(ב) ו-20(ג) לחוק החברות).
**וריאציה 3 — תכלית הסכמה פה אחד:** מדוע המחוקק דורש הסכמה פה אחד לשינוי אחריות? ← כדי להבטיח שכל בעל מניה יסכים באופן מפורש לנטילת סיכון אישי בלתי מוגבל, שכן זו פגיעה מהותית בזכות יסוד של בעל מניה בחברה (צפורה כהן, בעלי מניות בחברה - כרך א'', 2006, עמ'' 12).', 'שינוי אחריות מוגבלת לבלתי מוגבלת בחברה עם מניות סוגים ← הסכמת כלל בעלי המניות (סעיף 344(ב)) ← מייתר אסיפת סוג.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 344(ב)", "חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך א'' (2006) | 1. אחריות בעלי מניות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הסכמה של כלל בעלי המניות בחברה, ללא צורך באישור אסיפת סוג נפרדת.', true, 'תשובה זו נכונה. סעיף 344(ב) לחוק החברות דורש הסכמה של כלל בעלי המניות. דרישה זו חזקה יותר מדרישת אסיפת סוג, ולכן היא כוללת אותה. כלומר, אם כל בעלי המניות, מכל הסוגים, מסכימים, אין צורך באסיפת סוג נפרדת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הסכמה של כלל בעלי המניות בחברה, וכן אישור של אסיפה נפרדת של כל סוג מניות.', false, 'טענה זו שגויה. דרישת הסכמה פה אחד של כלל בעלי המניות מייתרת את הצורך באסיפת סוג נפרדת, שכן היא כוללת את הסכמת כל בעלי המניות מכל סוג.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'רוב של שלושה רבעים מבעלי המניות המשתתפים בהצבעה, וכן אישור של אסיפה נפרדת של כל סוג מניות.', false, 'טענה זו שגויה. רוב של שלושה רבעים אינו הרוב הנדרש לשינוי אחריות מוגבלת לבלתי מוגבלת, הדורש הסכמה פה אחד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רוב רגיל באסיפה הכללית, וכן אישור של אסיפה נפרדת של כל סוג מניות.', false, 'טענה זו שגויה. רוב רגיל אינו הרוב הנדרש לשינוי אחריות מוגבלת לבלתי מוגבלת, וגם לא לשינוי הפוגע בזכויות סוג.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעד לבעל מניות מתנגד לשינוי אחריות',
    4, 'חברת דלתא בע"מ, חברה פרטית, מעוניינת לשנות את תקנונה כך שאחריות בעלי המניות בה תהפוך לבלתי מוגבלת. בעל מניות אחד מתנגד לשינוי. מהו הסעד העיקרי העומד לרשותו?', 'שאלה זו בוחנת את הסעד העיקרי העומד לרשות בעל מניות המתנגד לשינוי אחריות מוגבלת לבלתי מוגבלת, תוך הדגשת המשמעות של דרישת ההסכמה פה אחד הקבועה בסעיף 344(ב) לחוק החברות.', 'סעיף 344(ב) לחוק החברות, התשנ"ט-1999, קובע כי ''שינוי בתקנון חברה, המטיל אחריות בלתי מוגבלת על בעל מניה, טעון הסכמת כל בעלי המניות בחברה''. משמעות הדבר היא שכל בעל מניות בחברה מחזיק בזכות וטו על שינוי כזה. אם בעל מניות אחד מתנגד לשינוי, הרי שההסכמה פה אחד אינה מתקיימת, והשינוי אינו יכול לצאת לפועל. לכן, הסעד העיקרי והאפקטיבי ביותר העומד לרשות בעל המניות המתנגד הוא פשוט להתנגד להצעה, ובכך למנוע את אישורה.',
    'הטעות הנפוצה היא לחפש סעד אקטיבי (כמו תביעה או דרישת רכישה) במקום להבין שההגנה הטובה ביותר טמונה בדרישת הרוב המחמירה, המעניקה זכות וטו לכל בעל מניות.', '["אחריות מוגבלת", "אחריות בלתי מוגבלת", "הסכמה פה אחד", "זכות וטו", "סעיף 344(ב) לחוק החברות", "הגנת בעלי מניות"]'::jsonb, '**וריאציה 1 — סעד הערכה במיזוג:** האם בעל מניות מתנגד למיזוג זכאי לסעד הערכה? ← כן, הוא רשאי לדרוש מהחברה לרכוש את מניותיו בשווי הוגן (סעיף 341 לחוק החברות).
**וריאציה 2 — תביעת קיפוח מיעוט:** מתי ניתן להגיש תביעת קיפוח מיעוט? ← כאשר בעלי השליטה בחברה פועלים באופן הפוגע בציפיות הלגיטימיות של בעלי מניות המיעוט, גם אם ההחלטה התקבלה כדין (סעיף 191 לחוק החברות).
**וריאציה 3 — שינוי תקנון המפחית זכויות:** מה הסעד לבעל מניות שזכויותיו נפגעו משינוי תקנון שאושר ברוב מיוחס? ← הוא יכול לטעון לקיפוח מיעוט אם השינוי נעשה בחוסר תום לב או באופן בלתי הוגן (סעיף 191 לחוק החברות).', 'התנגדות לשינוי אחריות מוגבלת לבלתי מוגבלת ← זכות וטו לכל בעל מניות (סעיף 344(ב)) ← מונעת את השינוי.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 344(ב)", "חוק החברות, תשנ\"ט-1999, סעיף 341", "חוק החברות, תשנ\"ט-1999, סעיף 191"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בעל המניות רשאי לדרוש מהחברה לרכוש את מניותיו בשווי הוגן.', false, 'טענה זו שגויה. חוק החברות אינו מקנה זכות לדרוש רכישה כפויה של מניות במקרה של שינוי אחריות מוגבלת לבלתי מוגבלת, בניגוד למקרים אחרים כמו מיזוג או הצעת רכש מלאה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בעל המניות יכול למנוע את השינוי, שכן נדרשת הסכמה של כלל בעלי המניות.', true, 'תשובה זו נכונה. מכיוון שסעיף 344(ב) לחוק החברות דורש הסכמה של כלל בעלי המניות לשינוי המטיל אחריות בלתי מוגבלת, התנגדות של בעל מניות אחד מספיקה כדי למנוע את השינוי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בעל המניות רשאי לתבוע את החברה בגין קיפוח המיעוט, גם אם השינוי לא אושר.', false, 'טענה זו שגויה. תביעת קיפוח מיעוט רלוונטית כאשר החלטה התקבלה כדין אך פוגעת במיעוט. במקרה זה, אם בעל המניות מתנגד, ההחלטה לא יכולה להתקבל כדין מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בעל המניות רשאי לפנות לבית המשפט בבקשה לביטול השינוי לאחר שאושר.', false, 'טענה זו שגויה. אם השינוי אושר, משמע שכל בעלי המניות הסכימו לו, ולכן בעל המניות המתנגד לא יוכל לבקש את ביטולו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 23, '2019-S-S-Q23';
END
$$;

