  v_ang_0 uuid := 'a143a91c-dce6-4090-9e88-532c42db6da8'::uuid;
  v_ang_1 uuid := '9a3a7893-364f-4062-8040-2f0e030a3125'::uuid;
  v_ang_2 uuid := 'f59355a6-142c-4b4c-afcb-8e3f82bcca6e'::uuid;
  v_ang_3 uuid := '9245e0ec-41d8-4eca-a253-6b88b0d020d1'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q24';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 24, '2019-S-S-Q24';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_duties' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q24', v_chapter_id, v_subtopic_id, 'אברהם הוא נושא משרה בחברת יצחק בע"מ. בשל פעילותו במסגרת זו נפתחה כלפיו חקירה פלילית בעבירה שאינה דורשת הוכחת מחשבה פלילית. לשם כך שכר אברהם את שירותיו של עו"ד נחמני. לאחר סיום החקירה נסגר התיק בלא כתב אישום, אך הוטל עליו כופר לתשלום. אברהם מבקש מן החברה שיפוי על הוצאותיו (שכר טרחת עורך הדין בסכום סביר ותשלום הכופר). מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 24}'::jsonb, 'השאלה עוסקת בשיפוי נושאי משרה בחברה, ובפרט בהבחנה בין שיפוי על הוצאות הגנה לבין שיפוי על קנסות או כופר, בהתאם לסעיף 260 לחוק החברות, התשנ"ט-1999. היא מדגישה את ההבדל בתנאים לאישור רטרואקטיבי של הוראת שיפוי עבור כל אחד מסוגי ההוצאות.', 'סעיף 260 לחוק החברות, התשנ"ט-1999, מסדיר את נושא השיפוי לנושאי משרה. סעיף 260(א) קובע כי חברה רשאית לשפות נושא משרה בגין הוצאות הגנה סבירות (סעיף 260(א)(1) ו-(2)) וכן בגין תשלום כופר או קנס (סעיף 260(א)(3)). עם זאת, קיימת הבחנה מהותית בין סוגי ההוצאות לעניין האפשרות לקבוע הוראת שיפוי רטרואקטיבית: שיפוי בגין הוצאות הגנה (כמו שכר טרחת עורך דין) יכול להינתן ''מראש או בדיעבד'', כלומר, ניתן לקבוע הוראת שיפוי רטרואקטיבית בתקנון החברה והיא תחול על הוצאות אלו. לעומת זאת, שיפוי בגין כופר או קנס מותר רק אם הוראת השיפוי נקבעה ''מראש'' בתקנון, כלומר, לפני המעשה או המחדל שבגינו הוטל הכופר/קנס. בנוסף, שיפוי על כופר/קנס מותר רק אם מדובר בעבירה שאינה דורשת הוכחת מחשבה פלילית. במקרה הנדון, אברהם מבקש שיפוי על שכר טרחת עו"ד (הוצאות הגנה) ועל תשלום כופר. החברה רשאית לשפות אותו על שכר טרחת עו"ד גם אם הוראת השיפוי תיקבע רטרואקטיבית. אולם, היא אינה רשאית לשפות אותו על תשלום הכופר אם הוראת השיפוי נקבעה רטרואקטיבית, שכן שיפוי על כופר דורש הוראה מראש.', 'הטעות הנפוצה היא להניח שכל סוגי השיפוי ניתנים לאישור רטרואקטיבי, או לבלבל בין התנאים לשיפוי על הוצאות הגנה לבין התנאים לשיפוי על קנסות/כופר.',
    '["שיפוי נושא משרה", "חוק החברות", "הוצאות הגנה", "קנסות", "כופר", "רטרואקטיביות", "מחשבה פלילית", "סעיף 260"]'::jsonb, '**וריאציה 1 — שיפוי על קנסות בעבירות תעבורה:** האם ניתן לשפות נושא משרה על קנסות תעבורה? ← כן, אם נקבעה הוראת שיפוי מראש בתקנון, שכן עבירות תעבורה רבות אינן דורשות מחשבה פלילית.
**וריאציה 2 — שיפוי על הוצאות הגנה בהרשעה:** האם ניתן לשפות נושא משרה על הוצאות הגנה אם הורשע בעבירה פלילית הדורשת מחשבה פלילית? ← לא, סעיף 260(ב)(1) לחוק החברות אוסר שיפוי במקרה כזה.
**וריאציה 3 — ביטוח אחריות נושאי משרה:** האם ביטוח אחריות נושאי משרה כפוף לאותן מגבלות כמו שיפוי? ← כן, סעיף 260(ב) לחוק החברות קובע מגבלות דומות גם על ביטוח אחריות.', 'שיפוי נושא משרה ← הוצאות הגנה (כן, רטרואקטיבי) ← קנס/כופר (לא, אלא אם כן הוראה מראש ואין מחשבה פלילית) (סעיף 260 לחוק החברות).', '["חוק החברות, תשנ\"ט-1999, סעיף 260", "פקודת מס הכנסה [נוסח חדש], סעיף 221(א)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Officer indemnification — administrative fine after criminal investigation closed | source_review_note: השאלה עוסקת בדיני חברות, תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני חברות'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החברה רשאית לשפות את אברהם בגין שני התשלומים אם תיקבע לכך הוראה רטרואקטיבית בתקנון.', false, 'טענה זו שגויה. סעיף 260(א)(3) לחוק החברות מאפשר שיפוי על כופר רק אם הוראת השיפוי נקבעה בתקנון מראש, ולא רטרואקטיבית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'החברה רשאית לשפות את אברהם בגין שכר טרחת עורך הדין בלבד אם תיקבע לכך הוראה רטרואקטיבית בתקנון.', true, 'תשובה זו נכונה. סעיף 260(א)(1) לחוק החברות מאפשר שיפוי על הוצאות הגנה, גם אם הוראת השיפוי נקבעה רטרואקטיבית. עם זאת, שיפוי על כופר (שהוא סוג של קנס) מוגבל יותר ואינו ניתן לשיפוי רטרואקטיבי בעבירה שאינה דורשת מחשבה פלילית, אלא אם נקבע מראש.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'החברה רשאית לשפות את אברהם בגין תשלום הכופר בלבד אם תיקבע לכך הוראה רטרואקטיבית בתקנון.', false, 'טענה זו שגויה. שיפוי על כופר אינו יכול להיעשות רטרואקטיבית, ושיפוי על הוצאות הגנה מותר גם הוא.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החברה אינה רשאית לשפות את אברהם אם תיקבע לכך הוראה רטרואקטיבית בתקנון, אלא רק אם הייתה הוראה כזו בתקנון לפני המקרה.', false, 'טענה זו שגויה. סעיף 260(א)(1) לחוק החברות מאפשר שיפוי רטרואקטיבי על הוצאות הגנה, בניגוד לשיפוי על קנסות וכופר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שיפוי על הוצאות הגנה בתביעה אזרחית',
    1, 'אברהם הוא נושא משרה בחברת יצחק בע"מ. נגדו הוגשה תביעה אזרחית בגין רשלנות שנגרמה עקב פעילותו בחברה. החברה מבקשת לשפות אותו על הוצאות הגנתו בתביעה. מה הדין?', 'שאלה זו בוחנת את היקף השיפוי לנושאי משרה בחברה בגין הוצאות הגנה בתביעות אזרחיות, ובפרט את האפשרות לקבוע הוראת שיפוי רטרואקטיבית בתקנון החברה.', 'סעיף 260(א)(1) ו-(2) לחוק החברות, התשנ"ט-1999, מאפשרים לחברה לשפות נושא משרה בגין הוצאות הגנה סבירות שהוציא או שחויב בהן, לרבות שכר טרחת עורך דין, בתביעה אזרחית שהוגשה נגדו עקב מעשה או מחדל שלו כנושא משרה. סעיף 260(א) קובע כי הוראת שיפוי יכולה להינתן ''מראש או בדיעבד''. כלומר, ניתן לקבוע הוראת שיפוי רטרואקטיבית בתקנון החברה, והיא תחול על הוצאות הגנה בתביעה אזרחית, כל עוד לא חל אחד מהחריגים שבסעיף 260(ב) (למשל, הפרת חובת אמונים או מעשה מכוון).',
    'הטעות הנפוצה היא לחשוב ששיפוי רטרואקטיבי אינו אפשרי כלל, או לבלבל בין התנאים לשיפוי על הוצאות הגנה לבין התנאים לשיפוי על קנסות.', '["שיפוי נושא משרה", "חוק החברות", "הוצאות הגנה", "תביעה אזרחית", "רטרואקטיביות", "תקנון חברה"]'::jsonb, '**וריאציה 1 — שיפוי על הוצאות הסדר פשרה:** האם ניתן לשפות נושא משרה על הוצאות הסדר פשרה בתביעה אזרחית? ← כן, סעיף 260(א)(2) לחוק החברות מאפשר שיפוי על סכום פשרה סביר, בתנאי שהסדר הפשרה אושר על ידי החברה.
**וריאציה 2 — שיפוי על הוצאות הגנה בתביעה ייצוגית:** האם ניתן לשפות נושא משרה על הוצאות הגנה בתביעה ייצוגית? ← כן, כל עוד לא חל אחד מהחריגים שבסעיף 260(ב) לחוק החברות (ע"א 10076/08 בנק דיסקונט לישראל בע"מ נ'' ברוך אלבס).
**וריאציה 3 — שיפוי על הוצאות הגנה בתביעה נגזרת:** האם ניתן לשפות נושא משרה על הוצאות הגנה בתביעה נגזרת? ← לא, סעיף 260(ב)(3) לחוק החברות אוסר שיפוי על הוצאות הגנה בתביעה נגזרת.', 'שיפוי נושא משרה ← הוצאות הגנה בתביעה אזרחית ← מותר, גם רטרואקטיבית (סעיף 260(א)(1)-(2)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 260(א)", "חוק החברות, תשנ\"ט-1999, סעיף 260(ב)", "ע\"א 10076/08 בנק דיסקונט לישראל בע\"מ נ'' ברוך אלבס (20.07.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'החברה רשאית לשפות את אברהם על הוצאות הגנתו בתביעה האזרחית, גם אם תיקבע לכך הוראה רטרואקטיבית בתקנון.', true, 'תשובה זו נכונה. סעיף 260(א)(1) ו-(2) לחוק החברות מאפשרים שיפוי נושא משרה על הוצאות הגנה סבירות בתביעה אזרחית, וניתן לקבוע הוראת שיפוי רטרואקטיבית בתקנון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'החברה אינה רשאית לשפות את אברהם על הוצאות הגנתו, שכן מדובר בתביעת רשלנות.', false, 'טענה זו שגויה. רשלנות אינה נכללת בחריגים לשיפוי הקבועים בסעיף 260(ב) לחוק החברות, ולכן ניתן לשפות בגינה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'החברה רשאית לשפות את אברהם רק אם הוראת השיפוי הייתה קיימת בתקנון לפני הגשת התביעה.', false, 'טענה זו שגויה. סעיף 260(א) לחוק החברות מאפשר שיפוי על הוצאות הגנה גם אם הוראת השיפוי נקבעה רטרואקטיבית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'החברה רשאית לשפות את אברהם רק אם יזוכה באופן מלא מהתביעה.', false, 'טענה זו שגויה. שיפוי על הוצאות הגנה אפשרי גם אם נושא המשרה לא זוכה באופן מלא, כל עוד לא חל אחד מהחריגים שבסעיף 260(ב).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים לשיפוי על קנסות',
    2, 'חברת יצחק בע"מ מעוניינת לשפות את אברהם, נושא משרה בה, על קנס שהוטל עליו בגין עבירה פלילית שאינה דורשת הוכחת מחשבה פלילית. מהם התנאים לשיפוי על קנסות כאלה?', 'שאלה זו מתמקדת בתנאים הספציפיים לשיפוי נושאי משרה בגין קנסות או כופר שהוטלו עליהם, תוך הדגשת ההבחנה בין עבירות הדורשות מחשבה פלילית לאלו שאינן דורשות, ודרישת קביעת הוראת שיפוי מראש.', 'סעיף 260(א)(3) לחוק החברות, התשנ"ט-1999, קובע כי חברה רשאית לשפות נושא משרה בגין ''תשלום כופר כהגדרתו בסעיף 221(א) לפקודת מס הכנסה, או הוצאה אחרת שאושרה על פי דין, בקשר לעבירה שאינה דורשת הוכחת מחשבה פלילית''. סעיף 260(א) מבהיר כי שיפוי על קנסות או כופר יכול להינתן רק ''מראש'', כלומר, הוראת השיפוי חייבת להיות קיימת בתקנון החברה לפני המעשה או המחדל שבגינו הוטל הקנס. שיפוי רטרואקטיבי אינו אפשרי במקרה זה. בנוסף, סעיף 260(ב)(1) אוסר שיפוי על קנסות שהוטלו בגין עבירה פלילית הדורשת הוכחת מחשבה פלילית.',
    'הטעות הנפוצה היא להניח ששיפוי על קנסות וכופר כפוף לאותם תנאים כמו שיפוי על הוצאות הגנה, ובפרט להתעלם מהדרישה לקביעת הוראת שיפוי מראש.', '["שיפוי נושא משרה", "קנסות", "כופר", "עבירה פלילית", "מחשבה פלילית", "הוראת שיפוי מראש", "סעיף 260(א)(3)"]'::jsonb, '**וריאציה 1 — שיפוי על קנסות בעבירות תעבורה:** האם ניתן לשפות נושא משרה על קנסות תעבורה? ← כן, אם נקבעה הוראת שיפוי מראש בתקנון, שכן עבירות תעבורה רבות אינן דורשות מחשבה פלילית.
**וריאציה 2 — שיפוי על קנסות מינהליים:** האם ניתן לשפות נושא משרה על קנסות מינהליים? ← כן, אם נקבעה הוראת שיפוי מראש בתקנון, שכן קנסות מינהליים אינם דורשים מחשבה פלילית.
**וריאציה 3 — שיפוי על קנסות בעבירות מס:** האם ניתן לשפות נושא משרה על כופר שהוטל בעבירת מס? ← כן, אם נקבעה הוראת שיפוי מראש בתקנון, שכן כופר הוא סוג של קנס בעבירה שאינה דורשת מחשבה פלילית (סעיף 260(א)(3) לחוק החברות).', 'שיפוי נושא משרה ← קנס/כופר ← רק בעבירה ללא מחשבה פלילית + הוראת שיפוי מראש (סעיף 260(א)(3)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 260(א)", "חוק החברות, תשנ\"ט-1999, סעיף 260(ב)", "פקודת מס הכנסה [נוסח חדש], סעיף 221(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'החברה רשאית לשפות את אברהם על קנס שהוטל עליו, רק אם הקנס הוטל בגין עבירה שאינה דורשת הוכחת מחשבה פלילית, ובתנאי שהחברה קבעה הוראת שיפוי בתקנון מראש.', true, 'תשובה זו נכונה. סעיף 260(א)(3) לחוק החברות מאפשר שיפוי על קנסות רק בעבירות שאינן דורשות מחשבה פלילית, ורק אם הוראת השיפוי נקבעה מראש בתקנון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'החברה רשאית לשפות את אברהם על קנס, גם אם הוראת השיפוי נקבעה רטרואקטיבית בתקנון.', false, 'טענה זו שגויה. שיפוי על קנסות אינו יכול להיעשות רטרואקטיבית, אלא רק אם הוראת השיפוי נקבעה מראש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'החברה רשאית לשפות את אברהם על קנס, ללא קשר לסוג העבירה, כל עוד נקבעה הוראת שיפוי בתקנון.', false, 'טענה זו שגויה. סעיף 260(ב)(1) לחוק החברות אוסר שיפוי על קנסות בעבירות הדורשות מחשבה פלילית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'החברה אינה רשאית לשפות את אברהם על קנסות כלל, שכן מדובר בסנקציה פלילית.', false, 'טענה זו שגויה. סעיף 260(א)(3) לחוק החברות מאפשר שיפוי על קנסות מסוימים, בכפוף לתנאים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שיפוי במקרה של הרשעה בעבירה',
    3, 'אברהם, נושא משרה בחברת יצחק בע"מ, הורשע בעבירה פלילית שדורשת הוכחת מחשבה פלילית. האם החברה רשאית לשפות אותו על הוצאות הגנתו במשפט?', 'שאלה זו בוחנת את החריגים לשיפוי נושאי משרה, ובפרט את האיסור המוחלט על שיפוי במקרה של הרשעה בעבירה פלילית הדורשת מחשבה פלילית, בהתאם לסעיף 260(ב) לחוק החברות.', 'סעיף 260(ב) לחוק החברות, התשנ"ט-1999, קובע רשימה של מקרים בהם חברה אינה רשאית לשפות נושא משרה. אחד המקרים המרכזיים הוא כאשר נושא המשרה ''הורשע בעבירה פלילית הדורשת הוכחת מחשבה פלילית'' (סעיף 260(ב)(1)). איסור זה הוא מוחלט ונועד למנוע מצב שבו החברה תממן הגנה משפטית או תשלומים לנושא משרה שביצע עבירה חמורה מתוך כוונה פלילית. לכן, במקרה זה, החברה אינה רשאית לשפות את אברהם על הוצאות הגנתו.',
    'הטעות הנפוצה היא להתעלם מהחריגים לשיפוי, או לחשוב שניתן להתנות עליהם באמצעות הוראות תקנון.', '["שיפוי נושא משרה", "חריגים לשיפוי", "הרשעה פלילית", "מחשבה פלילית", "חוק החברות סעיף 260(ב)", "אחריות נושאי משרה"]'::jsonb, '**וריאציה 1 — הפרת חובת אמונים:** האם ניתן לשפות נושא משרה שהפר את חובת אמונים לחברה? ← לא, סעיף 260(ב)(1) לחוק החברות אוסר שיפוי במקרה של הפרת חובת אמונים.
**וריאציה 2 — מעשה מכוון:** האם ניתן לשפות נושא משרה שביצע מעשה מכוון שגרם נזק לחברה? ← לא, סעיף 260(ב)(1) לחוק החברות אוסר שיפוי במקרה של מעשה מכוון.
**וריאציה 3 — תביעה נגזרת:** האם ניתן לשפות נושא משרה על הוצאות הגנה בתביעה נגזרת? ← לא, סעיף 260(ב)(3) לחוק החברות אוסר שיפוי על הוצאות הגנה בתביעה נגזרת.', 'שיפוי נושא משרה ← אסור במקרה של הרשעה בעבירה פלילית הדורשת מחשבה פלילית (סעיף 260(ב)(1)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 260(ב)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, החברה רשאית לשפות את אברהם על הוצאות הגנתו, כל עוד נקבעה הוראת שיפוי בתקנון.', false, 'טענה זו שגויה. סעיף 260(ב)(1) לחוק החברות אוסר שיפוי במקרה של הרשעה בעבירה פלילית הדורשת מחשבה פלילית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, החברה אינה רשאית לשפות את אברהם על הוצאות הגנתו אם הורשע בעבירה פלילית שדורשת הוכחת מחשבה פלילית.', true, 'תשובה זו נכונה. סעיף 260(ב)(1) לחוק החברות קובע איסור מוחלט על שיפוי נושא משרה שהורשע בעבירה פלילית הדורשת הוכחת מחשבה פלילית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הוראת השיפוי נקבעה מראש בתקנון החברה.', false, 'טענה זו שגויה. גם אם הוראת השיפוי נקבעה מראש, היא אינה יכולה לגבור על האיסור המוחלט שבסעיף 260(ב)(1) לחוק החברות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אם בית המשפט קבע כי המעשה נעשה בתום לב ולטובת החברה.', false, 'טענה זו שגויה. קביעת בית המשפט בדבר תום לב אינה רלוונטית כאשר מדובר בהרשעה בעבירה פלילית הדורשת מחשבה פלילית, המהווה חריג מפורש לשיפוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ביטוח אחריות נושאי משרה',
    4, 'חברת יצחק בע"מ מעוניינת להגן על נושאי המשרה שלה מפני תביעות והוצאות משפטיות. איזו דרך נוספת, מלבד שיפוי, עומדת לרשותה?', 'שאלה זו בוחנת את האפשרות של חברה להגן על נושאי המשרה שלה באמצעות ביטוח אחריות, כחלופה או השלמה לשיפוי, תוך התייחסות למגבלות הקבועות בחוק החברות.', 'סעיף 260(א)(4) לחוק החברות, התשנ"ט-1999, מאפשר לחברה להתקשר בחוזה ביטוח אחריות עם נושא משרה, המכסה את אחריותו בשל חובות שונות, לרבות הוצאות הגנה וחיובים כספיים. ביטוח זה הוא כלי נפוץ להגנה על נושאי משרה, והוא כפוף למגבלות דומות לאלו החלות על שיפוי, המפורטות בסעיף 260(ב) לחוק. כך למשל, ביטוח לא יכסה הפרת חובת אמונים, מעשה מכוון, או עבירה פלילית הדורשת מחשבה פלילית (סעיף 260(ב)(1)).',
    'הטעות הנפוצה היא לחשוב שביטוח אחריות נושאי משרה מעניק כיסוי בלתי מוגבל, או שאינו כפוף למגבלות החלות על שיפוי.', '["ביטוח אחריות נושאי משרה", "שיפוי", "חוק החברות", "הוצאות הגנה", "חובת אמונים", "מגבלות ביטוח"]'::jsonb, '**וריאציה 1 — ביטוח על הפרת חובת אמונים:** האם ביטוח אחריות נושאי משרה יכול לכסות הפרת חובת אמונים? ← לא, סעיף 260(ב)(1) לחוק החברות אוסר ביטוח על הפרת חובת אמונים.
**וריאציה 2 — ביטוח על קנסות:** האם ביטוח אחריות נושאי משרה יכול לכסות קנסות? ← כן, אם הקנס הוטל בגין עבירה שאינה דורשת מחשבה פלילית (סעיף 260(א)(4) ו-260(ב)(1) לחוק החברות).
**וריאציה 3 — תכלית הביטוח:** מהי התכלית של ביטוח אחריות נושאי משרה? ← למשוך ולשמר נושאי משרה איכותיים, תוך הגנה עליהם מפני סיכונים משפטיים הכרוכים בתפקידם, מבלי לפגוע בעקרונות אחריות בסיסיים (ע"א 10076/08 בנק דיסקונט לישראל בע"מ נ'' ברוך אלבס).', 'הגנה על נושאי משרה ← ביטוח אחריות (סעיף 260(א)(4)) ← כפוף למגבלות דומות לשיפוי (סעיף 260(ב)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 260(א)", "חוק החברות, תשנ\"ט-1999, סעיף 260(ב)", "ע\"א 10076/08 בנק דיסקונט לישראל בע\"מ נ'' ברוך אלבס (20.07.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'החברה רשאית לרכוש ביטוח אחריות לנושאי משרה, המכסה הוצאות הגנה וחיובים מסוימים, בכפוף למגבלות חוק החברות.', true, 'תשובה זו נכונה. סעיף 260(א)(4) לחוק החברות מאפשר לחברה לרכוש ביטוח אחריות לנושאי משרה, המהווה כלי נפוץ להגנה עליהם, בכפוף למגבלות דומות לאלו החלות על שיפוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'החברה רשאית להעניק לנושאי המשרה מענק מיוחד לכיסוי הוצאות, ללא קשר לתקנון.', false, 'טענה זו שגויה. כל תשלום לנושא משרה חייב להיות בהתאם להוראות חוק החברות והתקנון, ולא ניתן להעניק מענקים ללא בסיס חוקי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'החברה רשאית להבטיח לנושאי המשרה כי לא ייתבעו על ידה לעולם.', false, 'טענה זו שגויה. חברה אינה יכולה לוותר על זכויותיה לתבוע נושאי משרה במקרים מסוימים, במיוחד כאשר מדובר בהפרת חובות חמורות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'החברה רשאית להקים קרן ייעודית לכיסוי הוצאות משפטיות של נושאי משרה, ללא מגבלות.', false, 'טענה זו שגויה. הקמת קרן כזו תהיה כפופה למגבלות השיפוי והביטוח הקבועות בחוק החברות, ולא תהיה ''ללא מגבלות''.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 24, '2019-S-S-Q24';
END
$$;

-- ============================================================
-- Q25 — 2019-S-S-Q25 — chapter=property subtopic=condominiums
-- classifier_note: Solar water heater on shared condominium roof — common property
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'f69c9d20-f09c-46a5-9e60-6220c1da8d13'::uuid;
  v_group_id uuid := '9412c99b-3f71-42d9-9d89-6ecd363a839b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'e7156449-15e3-42de-a579-233675d86a69'::uuid;
  v_ang_1 uuid := '27af82f8-fec4-4f26-a110-6a27200e87fb'::uuid;
  v_ang_2 uuid := '331e4de4-5ca9-4126-bac9-46e7d9145587'::uuid;
  v_ang_3 uuid := 'ee329542-ded7-41d7-b2bb-64b65a05d007'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 25, '2019-S-S-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'condominiums' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'condominiums', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q25', v_chapter_id, v_subtopic_id, 'אילנה מתגוררת בבית משותף, והגג הוא חלק מהרכוש המשותף. בעקבות חיבתה של אילנה למקלחות חמות ובעקבות חשבון החשמל האחרון שקיבלה, החליטה אילנה להתקין דוד שמש על גג הבית המשותף. על הגג די מקום להתקין דודי שמש לכלל הדיירים, אך אף לא אחד מהם נהג כך והדיירים כלל לא עושים שימוש בגג. תקנון הבית המשותף אינו מייעד שימוש לגג. הוועדה המקומית לתכנון ולבנייה אישרה את ההתקנה, וההתקנה לא צפויה לפגוע בחזות המבנה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 25}'::jsonb, 'השאלה עוסקת בזכותו של דייר בבית משותף להתקין דוד שמש על גג הבית המשותף, שהוא רכוש משותף, ללא צורך באישור בעלי הדירות האחרים. היא מתבססת על סעיף 59א לחוק המקרקעין, התשכ"ט-1969, המפרט את התנאים המצטברים שבהתקיימם זכות זו קיימת.', 'סעיף 59א(א) לחוק המקרקעין, התשכ"ט-1969, קובע כי ''על אף האמור בכל דין או תקנון, רשאי בעל דירה להתקין על גג הבית המשותף, או על חלק אחר של הרכוש המשותף, דוד שמש, ובלבד שמתקיימים כל אלה: (1) ההתקנה אינה פוגעת בחזות הבניין; (2) ההתקנה אינה מונעת מדיירים אחרים להתקין דוד שמש; (3) קיים אישור של הוועדה המקומית לתכנון ולבנייה להתקנה''. במקרה הנדון, כל התנאים הללו מתקיימים: הגג הוא רכוש משותף, על הגג די מקום לדודים נוספים, ההתקנה לא צפויה לפגוע בחזות המבנה, והוועדה המקומית אישרה אותה. בנוסף, תקנון הבית המשותף אינו מייעד שימוש לגג, כך שאין הוראה ספציפית סותרת. לכן, אילנה אינה זקוקה לאישור מבעלי הדירות והיא רשאית לפעול על דעת עצמה.', 'הטעות הנפוצה היא לחשוב שכל שינוי ברכוש המשותף דורש אישור של רוב בעלי הדירות (או רוב מיוחס), ולהתעלם מההוראה הספציפית והחריגה שבסעיף 59א לחוק המקרקעין, המאפשרת התקנת דוד שמש ללא אישור כזה, בכפוף לתנאים.',
    '["בית משותף", "רכוש משותף", "דוד שמש", "חוק המקרקעין סעיף 59א", "אישור בעלי דירות", "חזות הבניין", "אישור ועדה מקומית"]'::jsonb, '**וריאציה 1 — תקנון האוסר התקנה:** האם תקנון בית משותף יכול לאסור התקנת דוד שמש גם אם התנאים בסעיף 59א מתקיימים? ← לא, הסעיף פותח במילים ''על אף האמור בכל דין או תקנון'', ולכן הוא גובר על הוראות תקנון סותרות.
**וריאציה 2 — התקנת מזגן:** האם סעיף 59א חל גם על התקנת מזגן על קיר חיצוני? ← לא, הסעיף מתייחס ספציפית לדוד שמש. התקנת מזגן כפופה לכללים הכלליים של שינויים ברכוש המשותף (רוב מיוחס או הסכמה פה אחד, תלוי בהיקף השינוי).
**וריאציה 3 — תכלית הסעיף:** מהי התכלית של סעיף 59א לחוק המקרקעין? ← לעודד שימוש באנרגיה סולארית ולמנוע סחטנות מיעוט בבתים משותפים, תוך איזון בין זכויות הדיירים (דברי ההסבר להצעת החוק).', 'התקנת דוד שמש על רכוש משותף ← מותרת ללא אישור דיירים ← אם מתקיימים 3 תנאים מצטברים (סעיף 59א לחוק המקרקעין).', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 59א"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''condominiums'' | classifier_note: Solar water heater on shared condominium roof — common property | source_review_note: השאלה עוסקת בדיני מקרקעין (בתים משותפים), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני מקרקעין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אילנה זקוקה לאישור שלושה רבעים מבעלי הדירות בבית.', false, 'טענה זו שגויה. סעיף 59א לחוק המקרקעין פוטר את הדייר מהצורך באישור בעלי הדירות, בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אילנה זקוקה לאישור שני שלישים מבעלי הדירות בבית.', false, 'טענה זו שגויה. סעיף 59א לחוק המקרקעין פוטר את הדייר מהצורך באישור בעלי הדירות, בכפוף לתנאים מסוימים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אילנה זקוקה לאישור מחצית מבעלי הדירות בבית.', false, 'טענה זו שגויה. סעיף 59א לחוק המקרקעין פוטר את הדייר מהצורך באישור בעלי הדירות, בכפוף לתנאים מסוימים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אילנה אינה זקוקה לאישור מבעלי הדירות, והיא רשאית לפעול על דעת עצמה.', true, 'תשובה זו נכונה. סעיף 59א(א) לחוק המקרקעין קובע כי דייר רשאי להתקין דוד שמש על גג הבית המשותף ללא צורך באישור בעלי הדירות, וזאת אם התקיימו התנאים המפורטים בסעיף, כפי שמתואר בשאלה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התקנת דוד שמש הפוגעת בחזות המבנה',
    1, 'אילנה מתגוררת בבית משותף, והגג הוא חלק מהרכוש המשותף. היא מעוניינת להתקין דוד שמש על גג הבית המשותף. הוועדה המקומית לתכנון ולבנייה אישרה את ההתקנה, אך קבעה כי ההתקנה, באופן שבו היא מתוכננת, תפגע באופן ניכר בחזות המבנה. מה הדין?', 'שאלה זו בוחנת את אחד התנאים המצטברים להתקנת דוד שמש על גג בית משותף ללא אישור בעלי הדירות – אי פגיעה בחזות המבנה, בהתאם לסעיף 59א(א)(1) לחוק המקרקעין.', 'סעיף 59א(א) לחוק המקרקעין, התשכ"ט-1969, קובע כי דייר רשאי להתקין דוד שמש על גג הבית המשותף ללא צורך באישור בעלי הדירות, וזאת בכפוף לשלושה תנאים מצטברים. אחד מהתנאים הללו, המפורט בסעיף 59א(א)(1), הוא כי ההתקנה ''אינה פוגעת בחזות הבניין''. במקרה זה, הוועדה המקומית קבעה כי ההתקנה תפגע באופן ניכר בחזות המבנה. משכך, אחד התנאים המהותיים להתקנה ללא אישור בעלי הדירות אינו מתקיים, ואילנה אינה רשאית להתקין את דוד השמש.',
    'הטעות הנפוצה היא להתמקד רק באישור הוועדה המקומית ולהתעלם מהתנאי הנוסף של אי פגיעה בחזות המבנה.', '["בית משותף", "רכוש משותף", "דוד שמש", "חזות הבניין", "חוק המקרקעין סעיף 59א", "אישור בעלי דירות"]'::jsonb, '**וריאציה 1 — אישור הוועדה המקומית:** האם ניתן להתקין דוד שמש ללא אישור הוועדה המקומית? ← לא, אישור הוועדה המקומית הוא תנאי הכרחי (סעיף 59א(א)(3) לחוק המקרקעין).
**וריאציה 2 — פגיעה בחזות:** מי קובע אם יש פגיעה בחזות הבניין? ← הוועדה המקומית לתכנון ולבנייה, או בית המשפט במקרה של מחלוקת (סעיף 59א(א)(1) לחוק המקרקעין).
**וריאציה 3 — התקנה על קיר חיצוני:** האם סעיף 59א חל גם על התקנת דוד שמש על קיר חיצוני של הבית המשותף? ← הסעיף מתייחס ל''גג או חלק אחר של הרכוש המשותף'', וקיר חיצוני יכול להיכלל בכך, בכפוף לתנאים (ע"א 10076/08 בנק דיסקונט לישראל בע"מ נ'' ברוך אלבס, פסקה 12).', 'התקנת דוד שמש ← דורשת אי פגיעה בחזות הבניין (סעיף 59א(א)(1)) ← אחרת, אסורה ללא אישור בעלי הדירות.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 59א(א)", "ע\"א 10076/08 בנק דיסקונט לישראל בע\"מ נ'' ברוך אלבס (20.07.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'אילנה רשאית להתקין את דוד השמש, שכן הוועדה המקומית אישרה את ההתקנה.', false, 'טענה זו שגויה. אישור הוועדה המקומית הוא תנאי הכרחי אך לא מספיק. פגיעה בחזות המבנה מונעת את ההתקנה ללא אישור בעלי הדירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'אילנה אינה רשאית להתקין את דוד השמש, שכן ההתקנה פוגעת בחזות המבנה.', true, 'תשובה זו נכונה. סעיף 59א(א)(1) לחוק המקרקעין קובע כי התקנת דוד שמש ללא אישור בעלי הדירות מותרת רק אם היא ''אינה פוגעת בחזות הבניין''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'אילנה רשאית להתקין את דוד השמש, אך תידרש לשלם פיצויים לבעלי הדירות האחרים.', false, 'טענה זו שגויה. פגיעה בחזות המבנה מונעת את עצם ההתקנה ללא אישור, ולא רק מחייבת פיצויים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'אילנה זקוקה לאישור רוב רגיל מבעלי הדירות בבית כדי להתקין את דוד השמש.', false, 'טענה זו שגויה. במקרה של פגיעה בחזות המבנה, נדרש אישור של כל בעלי הדירות או רוב מיוחס, ולא רוב רגיל, שכן מדובר בשינוי מהותי ברכוש המשותף.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי סעיף 59א לחוק המקרקעין',
    2, 'מהם התנאים המצטברים שבהתקיימם רשאי דייר בבית משותף להתקין דוד שמש על גג הבית המשותף, ללא צורך באישור בעלי הדירות?', 'שאלה זו בוחנת את הבקיאות בתנאים המצטברים המפורטים בסעיף 59א(א) לחוק המקרקעין, המאפשרים התקנת דוד שמש על רכוש משותף ללא צורך באישור בעלי הדירות.', 'סעיף 59א(א) לחוק המקרקעין, התשכ"ט-1969, מפרט שלושה תנאים מצטברים שבהתקיימם רשאי דייר בבית משותף להתקין דוד שמש על גג הבית המשותף, או על חלק אחר של הרכוש המשותף, ללא צורך באישור בעלי הדירות: (1) ההתקנה אינה פוגעת בחזות הבניין; (2) ההתקנה אינה מונעת מדיירים אחרים להתקין דוד שמש; (3) קיים אישור של הוועדה המקומית לתכנון ולבנייה להתקנה. רק כאשר כל שלושת התנאים הללו מתקיימים, רשאי הדייר לפעול על דעת עצמו.',
    'הטעות הנפוצה היא לזכור חלק מהתנאים אך לא את כולם, או לבלבל בין אישור הוועדה המקומית לאישור בעלי הדירות.', '["בית משותף", "רכוש משותף", "דוד שמש", "תנאים מצטברים", "חזות הבניין", "אישור הוועדה המקומית", "חוק המקרקעין סעיף 59א"]'::jsonb, '**וריאציה 1 — תכלית הסעיף:** מהי התכלית של סעיף 59א לחוק המקרקעין? ← לעודד שימוש באנרגיה סולארית ולמנוע סחטנות מיעוט בבתים משותפים (דברי ההסבר להצעת החוק).
**וריאציה 2 — התקנת מזגן:** האם סעיף 59א חל גם על התקנת מזגן על קיר חיצוני? ← לא, הסעיף מתייחס ספציפית לדוד שמש. התקנת מזגן כפופה לכללים הכלליים של שינויים ברכוש המשותף (רוב מיוחס או הסכמה פה אחד, תלוי בהיקף השינוי).
**וריאציה 3 — תקנון האוסר התקנה:** האם תקנון בית משותף יכול לאסור התקנת דוד שמש גם אם התנאים בסעיף 59א מתקיימים? ← לא, הסעיף פותח במילים ''על אף האמור בכל דין או תקנון'', ולכן הוא גובר על הוראות תקנון סותרות.', 'התקנת דוד שמש ללא אישור דיירים ← 3 תנאים מצטברים: חזות, מקום לאחרים, אישור ועדה (סעיף 59א(א)).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 59א(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ההתקנה אינה פוגעת בחזות הבניין, אינה מונעת מדיירים אחרים להתקין דוד שמש, וקיים אישור של הוועדה המקומית לתכנון ולבנייה.', true, 'תשובה זו נכונה. אלו הם שלושת התנאים המצטברים המפורטים בסעיף 59א(א) לחוק המקרקעין, שבהתקיימם אין צורך באישור בעלי הדירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ההתקנה אינה פוגעת בחזות הבניין, אינה מונעת מדיירים אחרים להתקין דוד שמש, וקיים אישור של רוב בעלי הדירות.', false, 'טענה זו שגויה. סעיף 59א(א) פוטר את הדייר מהצורך באישור בעלי הדירות, ומחליף אותו באישור הוועדה המקומית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ההתקנה אינה פוגעת בחזות הבניין, וקיים אישור של הוועדה המקומית לתכנון ולבנייה, ללא קשר למקום שנותר לדיירים אחרים.', false, 'טענה זו שגויה. התנאי של אי מניעת התקנה על ידי דיירים אחרים הוא תנאי מצטבר ומהותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'ההתקנה אינה פוגעת בחזות הבניין, וקיים אישור של רוב בעלי הדירות, ללא קשר לאישור הוועדה המקומית.', false, 'טענה זו שגויה. נדרש אישור הוועדה המקומית, ולא אישור בעלי הדירות, וכן התנאי של אי מניעת התקנה על ידי אחרים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התקנת דוד שמש המונעת התקנה עתידית',
    3, 'אילנה מתגוררת בבית משותף, והגג הוא חלק מהרכוש המשותף. היא מעוניינת להתקין דוד שמש על גג הבית המשותף. הוועדה המקומית לתכנון ולבנייה אישרה את ההתקנה, וההתקנה לא צפויה לפגוע בחזות המבנה. עם זאת, אילנה מתכננת להתקין דוד שמש גדול במיוחד, אשר יתפוס את כל השטח הפנוי על הגג, כך שלא יישאר מקום לדיירים אחרים להתקין דודים משלהם בעתיד. מה הדין?', 'שאלה זו בוחנת את התנאי השלישי בסעיף 59א(א) לחוק המקרקעין, לפיו התקנת דוד שמש על רכוש משותף ללא אישור בעלי הדירות מותרת רק אם היא אינה מונעת מדיירים אחרים להתקין דוד שמש משלהם.', 'סעיף 59א(א)(2) לחוק המקרקעין, התשכ"ט-1969, קובע במפורש כי התקנת דוד שמש על גג הבית המשותף ללא אישור בעלי הדירות מותרת רק אם היא ''אינה מונעת מדיירים אחרים להתקין דוד שמש''. במקרה זה, אילנה מתכננת להתקין דוד שמש שימנע מדיירים אחרים להתקין דודים משלהם בעתיד. משכך, תנאי מהותי זה אינו מתקיים, ואילנה אינה רשאית להתקין את דוד השמש באופן זה ללא קבלת אישור מפורש מכלל בעלי הדירות, שכן היא פוגעת בזכותם הפוטנציאלית לשימוש ברכוש המשותף.',
    'הטעות הנפוצה היא להתעלם מההיבט העתידי של מניעת התקנה על ידי דיירים אחרים, ולחשוב שהתנאי מתייחס רק למצב הקיים.', '["בית משותף", "רכוש משותף", "דוד שמש", "מניעת שימוש", "זכויות דיירים", "חוק המקרקעין סעיף 59א"]'::jsonb, '**וריאציה 1 — התקנה חלקית:** מה הדין אם אילנה מתקינה דוד שמש קטן, אך דייר אחר רוצה להתקין דוד גדול יותר ואין מקום? ← אילנה רשאית, כל עוד ההתקנה שלה לא מנעה התקנה סבירה של דודים אחרים. השאלה היא האם נשאר מקום סביר (סעיף 59א(א)(2) לחוק המקרקעין).
**וריאציה 2 — שימוש ייחודי בגג:** האם דייר שקיבל זכות שימוש ייחודי בגג רשאי להתקין דוד שמש ללא הגבלה? ← כן, אם הגג הוצמד לדירתו, הוא רשאי לעשות בו שימוש סביר, בכפוף לחוק התכנון והבנייה (ע"א 239/79 מילר נ'' וקנין).
**וריאציה 3 — תביעה נגד אילנה:** מי רשאי להגיש תביעה נגד אילנה אם היא מונעת התקנה מדיירים אחרים? ← כל דייר שנפגע, או נציגות הבית המשותף, רשאים לפנות למפקח על הבתים המשותפים (סעיף 72 לחוק המקרקעין).', 'התקנת דוד שמש ← אסורה אם מונעת מדיירים אחרים להתקין דודים (סעיף 59א(א)(2)).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 59א(א)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 72", "ע\"א 239/79 מילר נ'' וקנין, פ\"ד לד(1) 365 (1979)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'אילנה רשאית להתקין את דוד השמש, שכן הוועדה המקומית אישרה את ההתקנה והיא אינה פוגעת בחזות.', false, 'טענה זו שגויה. אישור הוועדה ואי פגיעה בחזות אינם מספיקים. ישנו תנאי נוסף של אי מניעת התקנה על ידי דיירים אחרים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'אילנה אינה רשאית להתקין את דוד השמש, שכן ההתקנה מונעת מדיירים אחרים להתקין דודים משלהם.', true, 'תשובה זו נכונה. סעיף 59א(א)(2) לחוק המקרקעין קובע כי התקנת דוד שמש ללא אישור בעלי הדירות מותרת רק אם היא ''אינה מונעת מדיירים אחרים להתקין דוד שמש''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'אילנה רשאית להתקין את דוד השמש, אך תידרש להסדיר מקום חלופי לדיירים אחרים.', false, 'טענה זו שגויה. החוק אינו מאפשר הסדרת מקום חלופי, אלא דורש שההתקנה עצמה לא תמנע מדיירים אחרים להתקין דודים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'אילנה זקוקה לאישור רוב מיוחס של בעלי הדירות כדי להתקין את דוד השמש.', false, 'טענה זו שגויה. במקרה של מניעת התקנה על ידי אחרים, ההתקנה אסורה ללא אישור פה אחד של כל בעלי הדירות, שכן היא פוגעת בזכות קניינית פוטנציאלית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעד לדייר שנפגע מהתקנה',
    4, 'אילנה התקינה דוד שמש על גג הבית המשותף ללא אישור הוועדה המקומית לתכנון ולבנייה, וההתקנה פוגעת בחזות המבנה. דייר אחר בבית, ראובן, מעוניין לפעול נגדה. איזה סעד עיקרי עומד לרשותו של ראובן?', 'שאלה זו בוחנת את הסעד הפרוצדורלי העיקרי העומד לרשות דייר בבית משותף שנפגע מהתקנה בלתי חוקית של דוד שמש על הרכוש המשותף, תוך התמקדות בסמכות המפקח על הבתים המשותפים.', 'סעיף 72 לחוק המקרקעין, התשכ"ט-1969, מקנה למפקח על רישום המקרקעין (המכונה ''המפקח על הבתים המשותפים'') סמכות ייחודית לדון בסכסוכים בין בעלי דירות בבית משותף, לרבות סכסוכים הנוגעים לשימוש ברכוש המשותף. במקרה זה, התקנת דוד השמש על ידי אילנה נעשתה בניגוד לתנאי סעיף 59א לחוק המקרקעין (היעדר אישור ועדה מקומית ופגיעה בחזות המבנה), ולכן היא בלתי חוקית. ראובן, כדייר שנפגע, רשאי להגיש תביעה למפקח על הבתים המשותפים, אשר בסמכותו להורות על הסרת הדוד ועל השבת המצב לקדמותו.',
    'הטעות הנפוצה היא לפנות לבית משפט השלום או לנקוט בפעולה עצמית, במקום לנצל את המסלול הייעודי והיעיל יותר של המפקח על הבתים המשותפים.', '["בית משותף", "רכוש משותף", "מפקח על רישום המקרקעין", "סמכות המפקח", "סכסוכי שכנים", "חוק המקרקעין סעיף 72"]'::jsonb, '**וריאציה 1 — סמכות המפקח:** האם המפקח מוסמך לדון גם בתביעות כספיות? ← כן, המפקח מוסמך לדון גם בתביעות כספיות הנובעות מסכסוכי בתים משותפים, עד לסכום מסוים (סעיף 72(ב) לחוק המקרקעין).
**וריאציה 2 — ערעור על החלטת המפקח:** לאן מוגש ערעור על החלטת המפקח? ← לבית המשפט המחוזי (סעיף 77 לחוק המקרקעין).
**וריאציה 3 — סמכות מקבילה:** האם לבית משפט השלום יש סמכות מקבילה לדון בסכסוכי בתים משותפים? ← כן, אך לרוב עדיף לפנות למפקח בשל מומחיותו והליך מהיר יותר (ע"א 515/65 רייזמן נ'' ויינברג).', 'דייר נפגע מהתקנה בלתי חוקית ברכוש משותף ← פנייה למפקח על הבתים המשותפים (סעיף 72 לחוק המקרקעין) ← סעד יעיל.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 72", "חוק המקרקעין, תשכ\"ט-1969, סעיף 77", "ע\"א 515/65 רייזמן נ'' ויינברג, פ\"ד כ(1) 281 (1966)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ראובן רשאי להגיש תביעה לבית משפט השלום בגין הסגת גבול.', false, 'טענה זו שגויה. אף שניתן לטעון להסגת גבול, הסעד היעיל והמתאים יותר במקרים של סכסוכי בתים משותפים הוא פנייה למפקח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ראובן רשאי לפנות למפקח על רישום המקרקעין בבקשה להורות על הסרת דוד השמש.', true, 'תשובה זו נכונה. למפקח על רישום המקרקעין (המכונה ''המפקח על הבתים המשותפים'') סמכות לדון בסכסוכים בין בעלי דירות בבית משותף, לרבות סכסוכים הנוגעים לשימוש ברכוש המשותף, ולהורות על הסרת התקנות בלתי חוקיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ראובן רשאי להסיר את דוד השמש בעצמו, שכן הוא הותקן בניגוד לחוק.', false, 'טענה זו שגויה. אסור לדייר לעשות דין לעצמו ולהסיר רכוש שהותקן על ידי דייר אחר, גם אם הוא הותקן בניגוד לחוק. יש לפעול בדרכים משפטיות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'ראובן רשאי להגיש תלונה למשטרה בגין עבירה על חוק התכנון והבנייה.', false, 'טענה זו שגויה. הגשת תלונה למשטרה היא הליך פלילי שאינו מספק סעד אזרחי ישיר לראובן, ואינו הדרך היעילה להסרת הדוד.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 25, '2019-S-S-Q25';
END
$$;

-- ============================================================
-- Q26 — 2019-S-S-Q26 — chapter=property subtopic=real_estate
-- classifier_note: Co-ownership of real estate — partition restrictions in joint-ownership agreement
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'c867f490-e9dd-470a-8d4b-45b2561f6689'::uuid;
  v_group_id uuid := '8e2c101c-f3e9-4dc8-ab4b-ad583185e156'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f88230b6-0574-4346-b37e-277a8abcbbc6'::uuid;
  v_ang_1 uuid := 'c7d1e023-811b-42eb-bec2-944021966550'::uuid;
  v_ang_2 uuid := 'd76986db-a7eb-459d-b6a6-9be98c4ef919'::uuid;
  v_ang_3 uuid := '8cfcc7fd-9aec-4ae4-ab57-c9712008149b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 26, '2019-S-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'real_estate' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'real_estate', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q26', v_chapter_id, v_subtopic_id, 'יואב, אבישי ועמשא רכשו יחד שדה מקרקעין באזור הגלבוע, בחלקים שווים. מכיוון ששלושתם חברים זה שנים רבות, החליטו להסכים בהסכם השיתוף כי כל שותף רשאי למכור את חלקו לצד שלישי רק בחלוף 10 שנים מיום חתימת ההסכם ובהסכמת שני השותפים האחרים בלבד. עמשא החליט למכור את חלקו לאבנר תמורת תשלום כספי גבוה מהמקובל, אך יואב ואבישי מתנגדים לכך נחרצות. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 26}'::jsonb, 'השאלה עוסקת בהוראת סעיף 34 לחוק המקרקעין, התשכ"ט-1969, המגבילה את תוקפן של תניות בהסכם שיתוף השוללות או מגבילות את זכותו של שותף לעשות דיספוזיציה בחלקו במקרקעין משותפים. היא בוחנת את משך הזמן המרבי לתוקף הגבלה כזו, גם אם הצדדים הסכימו על תקופה ארוכה יותר.', 'סעיף 34(א) לחוק המקרקעין, התשכ"ט-1969, קובע עקרון יסוד בדיני שיתוף במקרקעין, לפיו ''כל שותף רשאי להעביר חלקו במקרקעין המשותפים, או לעשות בחלקו עסקה אחרת, בלי הסכמת יתר השותפים''. עקרון זה מבטא את חופש העבירות של זכויות במקרקעין. סעיף 34(ב) מסייג את העיקרון וקובע כי ''תניה בהסכם שיתוף השוללת או מגבילה זכות כאמור בסעיף קטן (א) אין כוחה יפה לתקופה העולה על חמש שנים''. כלומר, גם אם השותפים הסכימו בהסכם השיתוף על הגבלה ארוכה יותר (כמו 10 שנים במקרה זה), תוקפה של ההגבלה מוגבל לחמש שנים בלבד. לאחר חלוף חמש שנים מיום חתימת ההסכם, ההגבלה פוקעת, והשותף רשאי למכור את חלקו ללא הסכמת יתר השותפים. פסק הדין בע"א 4843/23 שלמה אביטל נ'' תמיר משאט (2024) חידד כי סעיף זה חל על הגבלות נגטיביות על כוח דיספוזיציה, ולא על הקניית זכות קניינית כמו זכות קדימה.', 'הטעות הנפוצה היא להניח כי חופש החוזים מאפשר לשותפים לקבוע כל תקופת הגבלה שיחפצו בה, ולהתעלם מההגבלה הקוגנטית הקבועה בסעיף 34(ב) לחוק המקרקעין.',
    '["שיתוף במקרקעין", "הסכם שיתוף", "זכות דיספוזיציה", "הגבלת עבירות", "סעיף 34 לחוק המקרקעין", "תוקף הגבלה בזמן", "קוגנטיות"]'::jsonb, '**וריאציה 1 — הגבלת פירוק שיתוף:** מה הדין אם הסכם השיתוף מגביל את הזכות לדרוש פירוק שיתוף ל-10 שנים? ← הגבלה זו תקפה רק ל-3 שנים (סעיף 37(ב) לחוק המקרקעין).
**וריאציה 2 — זכות קדימה:** מה הדין אם הסכם השיתוף מעניק זכות קדימה לשותפים לרכישת חלקו של שותף אחר? ← זכות קדימה אינה מוגבלת בזמן על ידי סעיף 34(ב) לחוק המקרקעין, כפי שנקבע בע"א 4843/23 אביטל נ'' משאט.
**וריאציה 3 — הסכם שיתוף לא רשום:** האם הסכם שיתוף לא רשום מחייב צד שלישי שרכש חלק במקרקעין? ← לא, אלא אם ידע או היה עליו לדעת על קיומו (סעיף 29(א) לחוק המקרקעין; ע"א 269/74 בוקובזה נ'' הממונה על המרשם).', 'הגבלת זכות שותף למכור חלקו במקרקעין ← בהסכם שיתוף ← תקפה ל-5 שנים בלבד (סעיף 34(ב) לחוק המקרקעין).', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 34", "ע\"א 4843/23 שלמה אביטל נ'' תמיר משאט (31.10.2024)", "יעקב שקד פירוק שיתוף במקרקעין (2020) | 1.4.1 כללי", "יהושע ויסמן דיני קניין - בעלות ושיתוף (1997) | (א) עיסקאוח במנה במקרקעין"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''real_estate'' | classifier_note: Co-ownership of real estate — partition restrictions in joint-ownership agreement | source_review_note: השאלה עוסקת בדיני מקרקעין (שיתוף במקרקעין), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרק ''דיני מקרקעין'' לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עמשא רשאי למכור את חלקו לאבנר מיד.', false, 'טענה זו שגויה. ההגבלה על מכירת חלקו של שותף תקפה למשך חמש שנים, ורק לאחריהן רשאי השותף למכור את חלקו ללא הסכמת יתר השותפים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עמשא רשאי למכור את חלקו לאבנר רק בחלוף 5 שנים מיום חתימת ההסכם.', true, 'תשובה זו נכונה. סעיף 34(ב) לחוק המקרקעין קובע כי תניה בהסכם שיתוף השוללת או מגבילה את זכותו של שותף להעביר את חלקו, אין כוחה יפה לתקופה העולה על חמש שנים. לכן, ההגבלה החוזית למשך 10 שנים תקפה רק ל-5 שנים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עמשא רשאי למכור את חלקו לאבנר רק בחלוף 10 שנים מיום חתימת ההסכם.', false, 'טענה זו שגויה. סעיף 34(ב) לחוק המקרקעין מגביל את תוקפה של תניה כזו לחמש שנים בלבד, גם אם הצדדים הסכימו על תקופה ארוכה יותר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עמשא לא יהיה רשאי למכור את חלקו לאבנר אלא לאחר קבלת ההסכמה של יואב ושל אבישי.', false, 'טענה זו שגויה. לאחר חלוף חמש שנים, ההגבלה החוזית פוקעת, ועמשא רשאי למכור את חלקו ללא הסכמת יואב ואבישי, בהתאם לסעיף 34(א) לחוק המקרקעין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הגבלת פירוק שיתוף בהסכם',
    1, 'יואב, אבישי ועמשא רכשו יחד שדה מקרקעין בחלקים שווים. בהסכם השיתוף ביניהם נקבע כי אף שותף לא יהיה רשאי לדרוש פירוק שיתוף במקרקעין במשך 10 שנים מיום חתימת ההסכם. בחלוף 4 שנים, עמשא מעוניין לדרוש פירוק שיתוף. מה הדין?', 'שאלה זו בוחנת את תוקפה של תניה בהסכם שיתוף המגבילה את הזכות לדרוש פירוק שיתוף במקרקעין, בהתאם לסעיף 37(ב) לחוק המקרקעין, ואת ההבחנה בינה לבין הגבלת עבירות.', 'סעיף 37(א) לחוק המקרקעין, התשכ"ט-1969, קובע כי כל שותף במקרקעין משותפים זכאי בכל עת לדרוש פירוק השיתוף. סעיף 37(ב) מסייג זאת וקובע כי ''היתה בהסכם שיתוף תניה השוללת או מגבילה את הזכות לדרוש פירוק השיתוף לתקופה העולה על שלוש שנים, רשאי בית המשפט, כעבור שלוש שנים, לצוות על פירוק השיתוף, על אף התניה, אם נראה לו הדבר צודק בנסיבות הענין''. במקרה הנדון, הסכם השיתוף מגביל את פירוק השיתוף ל-10 שנים. מכיוון שחלפו 4 שנים, עברו כבר 3 השנים הקבועות בחוק, ולכן עמשא רשאי לדרוש פירוק שיתוף, ובית המשפט רשאי לצוות על כך אם ימצא לנכון. הוראה זו מבטאת את ''זכות היציאה'' של שותף מהשיתוף.',
    'הטעות הנפוצה היא לבלבל בין תקופת ההגבלה על פירוק שיתוף (3 שנים) לבין תקופת ההגבלה על עבירות (5 שנים).', '["פירוק שיתוף", "הסכם שיתוף", "זכות יציאה", "הגבלת פירוק שיתוף", "סעיף 37 לחוק המקרקעין", "סמכות בית המשפט"]'::jsonb, '**וריאציה 1 — הסכם שיתוף לא רשום:** האם הגבלה על פירוק שיתוף בהסכם שיתוף לא רשום מחייבת? ← כן, בין הצדדים להסכם, אך תוקפה מוגבל ל-3 שנים (ת"א (שלום חי'') 18700-01-13 א.א ארזים שיווק ובניית פרוייקטים בע"מ נ'' דן יקוטי).
**וריאציה 2 — פירוק שיתוף בנסיבות מיוחדות:** האם בית המשפט יכול לצוות על פירוק שיתוף לפני תום 3 השנים? ← לא, סעיף 37(ב) קובע במפורש ''כעבור שלוש שנים''.
**וריאציה 3 — תכלית הגבלת הזמן:** מהי התכלית של הגבלת הזמן על תניות המונעות פירוק שיתוף? ← למנוע קיפאון בנכסים ולאפשר לשותפים לצאת מיחסים שאינם רצויים להם, תוך איזון עם יציבות השיתוף (יהושע ויסמן, דיני קניין - בעלות ושיתוף, עמ'' 132).', 'הגבלת פירוק שיתוף בהסכם ← תקפה ל-3 שנים בלבד ← לאחריהן בית המשפט רשאי לצוות על פירוק (סעיף 37(ב)).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 37", "ת\"א (שלום חי'') 18700-01-13 א.א ארזים שיווק ובניית פרוייקטים בע\"מ נ'' דן יקוטי (19.04.2015)", "יהושע ויסמן דיני קניין - בעלות ושיתוף (1997) | (א) עיסקאוח במנה במקרקעין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'עמשא רשאי לדרוש פירוק שיתוף מיד, שכן הגבלה זו אינה תקפה כלל.', false, 'טענה זו שגויה. הגבלה על פירוק שיתוף תקפה לתקופה של עד שלוש שנים, ולאחר מכן בית המשפט רשאי להתערב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'עמשא אינו רשאי לדרוש פירוק שיתוף, שכן טרם חלפו 10 שנים מיום חתימת ההסכם.', false, 'טענה זו שגויה. הגבלה על פירוק שיתוף תקפה לכל היותר לשלוש שנים, גם אם הצדדים הסכימו על תקופה ארוכה יותר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'עמשא רשאי לדרוש פירוק שיתוף, שכן חלפו 3 שנים מיום חתימת ההסכם, ובית המשפט רשאי לצוות על הפירוק.', true, 'תשובה זו נכונה. סעיף 37(ב) לחוק המקרקעין קובע כי תניה בהסכם שיתוף המגבילה את הזכות לדרוש פירוק שיתוף לתקופה העולה על שלוש שנים, רשאי בית המשפט, כעבור שלוש שנים, לצוות על פירוק השיתוף, אם נראה לו הדבר צודק בנסיבות העניין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'עמשא רשאי לדרוש פירוק שיתוף רק בחלוף 5 שנים מיום חתימת ההסכם.', false, 'טענה זו שגויה. מגבלת חמש השנים מתייחסת להגבלת עבירות (סעיף 34(ב)), ואילו הגבלת פירוק שיתוף מוגבלת לשלוש שנים (סעיף 37(ב)).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין הגבלת עבירות לזכות קדימה',
    2, 'יואב, אבישי ועמשא רכשו יחד שדה מקרקעין בחלקים שווים. בהסכם השיתוף ביניהם נקבע כי אם אחד השותפים יחליט למכור את חלקו, עליו להציע אותו תחילה לשני השותפים האחרים, ורק אם אלה יסרבו, יהיה רשאי למכור לצד שלישי. ההסכם לא הגביל את תוקף זכות הקדימה בזמן. בחלוף 10 שנים, עמשא מעוניין למכור את חלקו לאבנר, אך יואב ואבישי דורשים לממש את זכות הקדימה שלהם. מה הדין?', 'שאלה זו בוחנת את ההבחנה המהותית בין תניה המגבילה את זכות העבירות של שותף (הכפופה לסעיף 34(ב) לחוק המקרקעין) לבין תניה המעניקה זכות קדימה, אשר אינה מוגבלת בזמן על ידי סעיף זה, כפי שנקבע בפסיקת בית המשפט העליון.', 'פסק הדין בע"א 4843/23 שלמה אביטל נ'' תמיר משאט (2024) דן בשאלה האם סעיף 34(ב) לחוק המקרקעין, המגביל תניות בהסכם שיתוף השוללות או מגבילות את זכותו של שותף לעשות דיספוזיציה בחלקו לחמש שנים, חל על תניה המעניקה זכות קדימה. בית המשפט העליון קבע, בדעת רוב, כי סעיף 34(ב) אינו חל על זכות קדימה. הנימוק המרכזי הוא שזכות קדימה, במתכונתה המבטיחה מחיר שוק, אינה ''שוללת או מגבילה'' את העבירות, אלא רק מטילה מגבלה על זהות הרוכש ומציבה את בעל זכות הקדימה ב''ראש התור''. היא אינה מונעת את עצם האפשרות להעביר את המקרקעין. לכן, זכות הקדימה במקרה זה תקפה, ועמשא חייב להציע את חלקו ליואב ואבישי תחילה.',
    'הטעות הנפוצה היא להחיל את מגבלת חמש השנים שבסעיף 34(ב) באופן גורף על כל סוגי ההגבלות בהסכם שיתוף, כולל זכות קדימה, מבלי להבין את ההבחנה שנקבעה בפסיקה.', '["זכות קדימה", "הסכם שיתוף", "הגבלת עבירות", "סעיף 34(ב) לחוק המקרקעין", "פסיקת בית המשפט העליון", "זכות קניינית מול אובליגטורית"]'::jsonb, '**וריאציה 1 — זכות קדימה במחיר קבוע מראש:** האם זכות קדימה המבטיחה מחיר קבוע מראש, הנמוך ממחיר שוק, כפופה לסעיף 34(ב)? ← השופטת כנפי-שטייניץ השאירה שאלה זו בצריך עיון, אך רמזה כי במקרה כזה ייתכן שסעיף 34(ב) יחול, שכן היא פוגעת באופן ממשי בעבירות (ע"א 4843/23 אביטל נ'' משאט, פסקה 20 לחוות דעתה).

**וריאציה 2 — זכות קדימה מכוח חוק:** האם זכות קדימה מכוח חוק (כמו בין בני זוג) מוגבלת בזמן? ← לא, זכות קדימה מכוח חוק אינה מוגבלת בזמן על ידי סעיף 34(ב) (יהושע ויסמן, דיני קניין: זכויות קדימה ופרקי משכון, עמ'' 97).
**וריאציה 3 — רישום זכות קדימה:** האם זכות קדימה הסכמית ניתנת לרישום? ← כן, ורישומה מעניק לה תוקף קנייני כלפי צדדים שלישיים (סעיף 99 לחוק המקרקעין).', 'זכות קדימה הסכמית ← אינה מוגבלת בזמן על ידי סעיף 34(ב) לחוק המקרקעין ← אם מבטיחה מחיר שוק (ע"א 4843/23 אביטל).',
    '["ע\"א 4843/23 שלמה אביטל נ'' תמיר משאט (31.10.2024)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 34(ב)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 99", "יהושע ויסמן דיני קניין: זכויות קדימה ופרקי משכון (2014) | יג. פקיעת זכות הקדימה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'זכות הקדימה פקעה בחלוף 5 שנים, ולכן עמשא רשאי למכור את חלקו לאבנר ללא צורך בהצעתו ליואב ואבישי.', false, 'טענה זו שגויה. סעיף 34(ב) לחוק המקרקעין אינו חל על זכות קדימה, כפי שנקבע בפסיקה העדכנית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'זכות הקדימה תקפה, ועמשא חייב להציע את חלקו ליואב ואבישי תחילה.', true, 'תשובה זו נכונה. פסק הדין בע"א 4843/23 שלמה אביטל נ'' תמיר משאט קבע כי סעיף 34(ב) לחוק המקרקעין, המגביל תניות בהסכם שיתוף לחמש שנים, אינו חל על זכות קדימה הסכמית, שכן זכות קדימה אינה נחשבת להגבלה על העבירות במובן של הסעיף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'זכות הקדימה תקפה רק אם נרשמה במרשם המקרקעין.', false, 'טענה זו שגויה. זכות קדימה הסכמית מחייבת את הצדדים להסכם גם ללא רישום, אם כי הרישום מעניק לה תוקף קנייני כלפי צדדים שלישיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'זכות הקדימה תקפה רק אם נקבע בה מחיר שוק למכירה.', false, 'טענה זו שגויה. אף שזכות קדימה המבטיחה מחיר שוק נחשבת לפחות פוגענית בעבירות, עצם קיומה של זכות קדימה אינו תלוי במנגנון קביעת המחיר, אלא ביסודות העדיפות והוולונטריות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תוקף הסכם שיתוף לא רשום כלפי צד שלישי',
    3, 'יואב, אבישי ועמשא רכשו יחד שדה מקרקעין בחלקים שווים. בהסכם השיתוף ביניהם נקבע כי כל שותף רשאי למכור את חלקו לצד שלישי רק בחלוף 10 שנים מיום חתימת ההסכם. הסכם השיתוף לא נרשם במרשם המקרקעין. בחלוף 4 שנים, עמשא מכר את חלקו לאבנר, אשר לא ידע ולא היה עליו לדעת על קיומו של הסכם השיתוף. יואב ואבישי מתנגדים למכירה. מה הדין?', 'שאלה זו בוחנת את תוקפו של הסכם שיתוף במקרקעין כלפי צד שלישי, כאשר ההסכם לא נרשם במרשם המקרקעין, בהתאם לסעיף 29(א) לחוק המקרקעין.', 'סעיף 29(א) לחוק המקרקעין, התשכ"ט-1969, קובע כי ''הסכם בין השותפים בדבר ניהול המקרקעין המשותפים והשימוש בהם ובדבר זכויותיהם וחובותיהם בכל הנוגע למקרקעין (להלן - הסכם שיתוף) ניתן לרישום, ומשנרשם, כוחו יפה גם כלפי אדם שנעשה שותף לאחר מכן וכל אדם אחר''. כלומר, הסכם שיתוף שאינו רשום מחייב רק את הצדדים לו. כדי שהסכם שיתוף יחייב צד שלישי (כמו אבנר), עליו להיות רשום, או שהצד השלישי ידע או היה עליו לדעת על קיומו (ע"א 269/74 בוקובזה נ'' הממונה על המרשם). במקרה זה, ההסכם לא נרשם ואבנר לא ידע ולא היה עליו לדעת על קיומו, ולכן ההסכם אינו מחייב אותו.',
    'הטעות הנפוצה היא לחשוב שהסכם שיתוף, מעצם היותו הסכם הנוגע למקרקעין, מחייב כל רוכש, גם אם לא נרשם וגם אם הרוכש לא ידע עליו.', '["הסכם שיתוף", "רישום מקרקעין", "תוקף כלפי צד שלישי", "ידיעה קונסטרוקטיבית", "סעיף 29(א) לחוק המקרקעין", "עקרון הפומביות"]'::jsonb, '**וריאציה 1 — הסכם שיתוף רשום:** האם הסכם שיתוף רשום מחייב צד שלישי שרכש חלק במקרקעין? ← כן, כוחו יפה כלפי כל אדם אחר, גם אם לא ידע עליו (סעיף 29(א) לחוק המקרקעין).
**וריאציה 2 — הסכם שיתוף במיטלטלין:** האם הסכם שיתוף במיטלטלין מחייב צד שלישי שידע עליו? ← כן, סעיף 9(ג) לחוק המיטלטלין קובע כי כוחו יפה כלפי צד שלישי שידע או היה עליו לדעת על קיומו.
**וריאציה 3 — חובת תום לב:** האם צד שלישי שידע על הסכם שיתוף לא רשום חייב לפעול בתום לב? ← כן, הפסיקה הכירה בכך שחובת תום הלב יכולה להרחיב את תחולת הסכם שיתוף לא רשום גם על צד שלישי שידע עליו (ע"א 48/16 ציון דהאן נ'' יגאל שמחון).', 'הסכם שיתוף לא רשום ← אינו מחייב צד שלישי ← אלא אם ידע או היה עליו לדעת (סעיף 29(א)).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 29(א)", "ע\"א 269/74 מנחם בוקובזה נ'' הממונה על המרשם, כט(1) 243 (05.11.1974)", "חוק המיטלטלין, תשל\"א-1971, סעיף 9(ג)", "ע\"א 48/16 ציון דהאן נ'' יגאל שמחון (09.08.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'ההסכם מחייב את אבנר, שכן הוא נכנס בנעלי עמשא.', false, 'טענה זו שגויה. הסכם שיתוף לא רשום אינו מחייב צד שלישי שלא ידע עליו, גם אם הוא רוכש זכויות משותף שהיה צד להסכם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'ההסכם אינו מחייב את אבנר, שכן הוא לא נרשם במרשם המקרקעין ואבנר לא ידע עליו.', true, 'תשובה זו נכונה. סעיף 29(א) לחוק המקרקעין קובע כי הסכם שיתוף שאינו רשום אינו מחייב צד שלישי שלא ידע או לא היה עליו לדעת על קיומו. במקרה זה, אבנר לא ידע ולא היה עליו לדעת, ולכן אינו כפוף להסכם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'ההסכם מחייב את אבנר, שכן הוא נוגע לזכויות במקרקעין.', false, 'טענה זו שגויה. אף שההסכם נוגע למקרקעין, תוקפו כלפי צד שלישי תלוי ברישומו או בידיעתו של הצד השלישי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'ההסכם אינו מחייב את אבנר, אך יואב ואבישי רשאים לתבוע את עמשא בגין הפרת הסכם.', false, 'טענה זו נכונה חלקית, אך אינה התשובה המלאה לשאלה. אכן, יואב ואבישי רשאים לתבוע את עמשא, אך השאלה מתמקדת בתוקף ההסכם כלפי אבנר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים במקרה של הפרת הסכם שיתוף',
    4, 'יואב, אבישי ועמשא רכשו יחד שדה מקרקעין בחלקים שווים. בהסכם שיתוף רשום ביניהם נקבע כי כל שותף רשאי למכור את חלקו לצד שלישי רק בחלוף 5 שנים מיום חתימת ההסכם. בחלוף שנתיים, עמשא מכר את חלקו לאבנר, בניגוד להסכם. יואב ואבישי מעוניינים לפעול נגד עמשא ו/או אבנר. מהם הסעדים העיקריים העומדים לרשותם?', 'שאלה זו בוחנת את הסעדים העומדים לרשות שותפים במקרקעין במקרה של הפרת הסכם שיתוף רשום, תוך התייחסות לתוקפו הקנייני של ההסכם כלפי צדדים שלישיים.', 'הסכם שיתוף רשום במרשם המקרקעין, בהתאם לסעיף 29(א) לחוק המקרקעין, התשכ"ט-1969, ''כוחו יפה גם כלפי אדם שנעשה שותף לאחר מכן וכל אדם אחר''. משמעות הדבר היא שההגבלה על מכירת חלקו של עמשא, שהייתה תקפה למשך 5 שנים, מחייבת גם את אבנר. מכיוון שעמשא מכר את חלקו לאבנר בחלוף שנתיים בלבד, הוא הפר את הסכם השיתוף. יואב ואבישי רשאים לתבוע את עמשא בגין הפרת הסכם, ולדרוש סעדים חוזיים כגון אכיפה או פיצויים. בנוסף, מכיוון שההסכם היה רשום, אבנר כפוף לו, ולכן יואב ואבישי רשאים לדרוש את ביטול העסקה עם אבנר, שכן היא נעשתה בניגוד להוראות הסכם השיתוף המחייבות אותו.',
    'הטעות הנפוצה היא להתעלם מהמשמעות הקניינית של רישום הסכם שיתוף, ולחשוב שתום ליבו של הרוכש מגן עליו גם במקרה של הסכם רשום.', '["הסכם שיתוף רשום", "תוקף קנייני", "הפרת הסכם", "אכיפה", "ביטול עסקה", "סעיף 29(א) לחוק המקרקעין", "סעדים"]'::jsonb, '**וריאציה 1 — הסכם שיתוף לא רשום:** מהם הסעדים אם הסכם השיתוף לא היה רשום ואבנר לא ידע עליו? ← יואב ואבישי יוכלו לתבוע את עמשא בגין הפרת הסכם, אך לא יוכלו לדרוש את ביטול העסקה מאבנר (סעיף 29(א) לחוק המקרקעין).
**וריאציה 2 — תביעה לפירוק שיתוף:** האם יואב ואבישי יכולים לדרוש פירוק שיתוף? ← לא, שכן הגבלת פירוק שיתוף תקפה ל-3 שנים, וחלפו רק שנתיים (סעיף 37(ב) לחוק המקרקעין).
**וריאציה 3 — סמכות המפקח:** האם המפקח על רישום המקרקעין מוסמך לדון בסכסוך זה? ← כן, סכסוכים הנוגעים להסכם שיתוף בין בעלי דירות בבית משותף נמצאים בסמכות המפקח (סעיף 72 לחוק המקרקעין), אך במקרה של שדה מקרקעין, הסמכות היא לבית המשפט המוסמך.', 'הפרת הסכם שיתוף רשום ← תביעה נגד המפר + דרישה לביטול העסקה מהרוכש ← בשל תוקף קנייני (סעיף 29(א)).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 29(א)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 37(ב)", "חוק המקרקעין, תשכ\"ט-1969, סעיף 72"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'יואב ואבישי רשאים לתבוע את עמשא בגין הפרת הסכם, וכן לדרוש מאבנר את ביטול העסקה, שכן הסכם השיתוף היה רשום.', true, 'תשובה זו נכונה. הסכם שיתוף רשום מחייב גם את אבנר (סעיף 29(א) לחוק המקרקעין), ולכן העסקה עם אבנר נעשתה בניגוד להסכם. יואב ואבישי רשאים לתבוע את עמשא על הפרת הסכם וכן לדרוש את ביטול העסקה מאבנר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'יואב ואבישי רשאים לתבוע את עמשא בגין הפרת הסכם, אך אינם יכולים לדרוש את ביטול העסקה מאבנר, שכן אבנר רכש את הזכויות בתום לב.', false, 'טענה זו שגויה. הסכם שיתוף רשום מעניק לו תוקף קנייני כלפי כולי עלמא, ולכן תום ליבו של אבנר אינו רלוונטי במקרה זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'יואב ואבישי רשאים לדרוש פירוק שיתוף מיידי, אך אינם יכולים לתבוע את עמשא או את אבנר.', false, 'טענה זו שגויה. הגבלה על פירוק שיתוף תקפה ל-3 שנים, ולכן לא ניתן לדרוש פירוק שיתוף מיידי. בנוסף, ניתן לתבוע את עמשא על הפרת הסכם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'יואב ואבישי רשאים לדרוש מאבנר פיצויים בלבד, שכן העסקה כבר בוצעה.', false, 'טענה זו שגויה. במקרה של הפרת הסכם שיתוף רשום, ניתן לדרוש גם אכיפה וביטול העסקה, ולא רק פיצויים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 26, '2019-S-S-Q26';
END
$$;

