-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd60b3b0a-f008-49f3-8f5e-f74d199c64e3'::uuid;
  v_group_id uuid := 'eed3bc3e-6ed9-4cdc-87cc-7b2a7fcfe81d'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '837a73f2-d996-42f2-b391-b285d5c9d9a1'::uuid;
  v_ang_1 uuid := '644503d5-fa34-4479-8e05-e5d87d9b0bfc'::uuid;
  v_ang_2 uuid := 'ea51c6b3-5924-468c-af70-47295ae75304'::uuid;
  v_ang_3 uuid := '73f41b83-945b-4e76-b35b-f575bc43edc4'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 27, '2019-S-S-Q27';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sex_offenses' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sex_offenses', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q27', v_chapter_id, v_subtopic_id, 'שלמה נחשד בביצוע עבירה של מעשה מגונה לפי סעיף 348(א) לחוק העונשין (עבירה שדינה 7 שנות מאסר). את העבירה ביצע שלמה בקטין אלי, זר גמור שאותו פגש באקראי. העבירה בוצעה ביום 1.1.2000, כאשר שלמה היה בן 16 ואלי היה בן 10. אלי התלונן במשטרה ביום 1.1.2019, ורק אז נפתחה חקירה בעניין. התובע מתלבט אם ניתן, מבחינת דיני ההתיישנות, להעמיד את שלמה לדין. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 27}'::jsonb, 'השאלה עוסקת בדיני התיישנות בעבירות מין שבוצעו בקטינים, תוך התייחסות למצב שבו העבריין עצמו היה קטין בעת ביצוע העבירה, וליחס בין סעיף 354 לחוק העונשין (הדוחה את מניין ההתיישנות) לבין סעיף 14 לחוק הנוער (הדורש אישור יועץ משפטי לממשלה להגשת כתב אישום נגד קטין לאחר שנה).', 'העבירה שבוצעה היא מעשה מגונה לפי סעיף 348(א) לחוק העונשין, שדינה 7 שנות מאסר. לפי סעיף 9(א)(1א) לחוק סדר הדין הפלילי [נוסח משולב], התשמ"ב-1982, תקופת ההתיישנות לעבירה זו היא 15 שנים. העבירה בוצעה ב-1.1.2000. אלי, הקטין הנפגע, היה בן 10 (נולד ב-1.1.1990). שלמה, העבריין, היה בן 16 (קטין). היחסים בין שלמה לאלי היו של זרים. במקרה כזה, חל סעיף 354(ג)(1) לחוק העונשין, הקובע כי מניין תקופת ההתיישנות יחל ביום שמלאו לקטין (אלי) 23 שנים. אלי הגיע לגיל 23 ב-1.1.2013. מניין 15 שנות ההתיישנות יחל ממועד זה, ולכן העבירה תתיישן ב-1.1.2028. התלונה הוגשה ב-1.1.2019, כלומר העבירה טרם התיישנה לפי סעיף 354(ג)(1). עם זאת, סעיף 354(ג)(1) קובע סייג נוסף: ''ואולם אם חלפה מיום ביצוע העבירה, התקופה הנקובה לגביה כאמור בסעיף קטן (א) - לא יוגש כתב אישום אלא באישור היועץ המשפטי לממשלה''. התקופה הנקובה בסעיף קטן (א) היא 28 שנים, אך הכוונה היא לתקופת ההתיישנות הרגילה מיום ביצוע העבירה, שהיא 15 שנים. העבירה בוצעה ב-1.1.2000, ועד ליום הגשת התלונה (1.1.2019) חלפו 19 שנים, כלומר חלפו יותר מ-15 שנים מיום ביצוע העבירה. לכן, נדרש אישור היועץ המשפטי לממשלה. בנוסף, שלמה היה קטין (בן 16) בעת ביצוע העבירה. סעיף 14 לחוק הנוער (שפיטה, ענישה ודרכי טיפול), התשל"א-1971, קובע כי ''לא יוגש כתב אישום נגד קטין אלא תוך שנה מיום ביצוע העבירה, אלא באישור היועץ המשפטי לממשלה''. העבירה בוצעה ב-1.1.2000, ושנה מיום ביצועה חלפה ב-1.1.2001. התלונה הוגשה ב-1.1.2019, הרבה לאחר מכן. פסיקת בית המשפט העליון (ע"פ 7211/13 פלוני נ'' מדינת ישראל, Reference 12) והספרות (נבו - המתמחה, ירושה וברירת הדין | התיישנות | שטרות, עמ'' 100, הערה ב'') מבהירות כי אישור היועץ המשפטי לממשלה לפי סעיף 14 לחוק הנוער הוא תנאי מהותי להגשת כתב אישום, ואישור בדיעבד אינו מרפא את הפגם. מכיוון שאישור זה לא ניתן במועד, לא ניתן להעמיד את שלמה לדין.', 'הטעות הנפוצה היא להתמקד רק בסעיף 354 לחוק העונשין ולהתעלם מהוראת סעיף 14 לחוק הנוער, או לחשוב שאישור היועץ המשפטי לממשלה יכול להינתן בכל עת, גם שנים רבות לאחר המועד הקבוע בחוק.',
    '["התיישנות עבירות מין", "קטינים נפגעי עבירות מין", "קטינים עבריינים", "סעיף 354 לחוק העונשין", "סעיף 14 לחוק הנוער", "אישור היועץ המשפטי לממשלה", "תחולה למפרע"]'::jsonb, '**וריאציה 1 — עבריין בגיר:** מה הדין אם שלמה היה בגיר בעת ביצוע העבירה? ← במקרה כזה, סעיף 14 לחוק הנוער לא היה חל, וניתן היה להעמיד לדין באישור היועץ המשפטי לממשלה (סעיף 354(ג)).
**וריאציה 2 — עבירה שדינה מאסר עולם:** מה הדין אם העבירה הייתה אינוס שדינה מאסר עולם? ← אין התיישנות על עבירות שדינן מאסר עולם (סעיף 9(ב1) לחוק סדר הדין הפלילי), ולכן ניתן היה להעמיד לדין ללא קשר למועדים.
**וריאציה 3 — תכלית סעיף 14 לחוק הנוער:** מהי תכלית סעיף 14 לחוק הנוער? ← להגן על קטינים עבריינים ולאפשר להם שיקום, תוך הגבלת משך הזמן שבו ניתן להעמידם לדין על עבירות שביצעו כקטינים (ע"פ 5725/15 פלוני נ'' מדינת ישראל).', 'התיישנות עבירת מין בקטין ע"י זר ← מניין מגיל 23 של הנפגע (סעיף 354(ג)). אם העבריין היה קטין ← נדרש אישור יועמ"ש תוך שנה מיום העבירה (סעיף 14 לחוק הנוער) ← אישור בדיעבד לא מכשיר.', '["חוק העונשין, תשל\"ז-1977, סעיף 348(א)", "חוק העונשין, תשל\"ז-1977, סעיף 354(ג)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(1א)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ב1)", "ע\"פ 7211/13 פלוני נ'' מדינת ישראל (13.12.2015)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | סעיפי התיישנות נוספים (הכלולים ברשימת החקיקה המנחה)", "ע\"פ 5725/15 פלוני נ'' מדינת ישראל (04.08.2016)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''התיישנות עבירות'' → mapped chapter=''criminal_substantive'' subtopic=''sex_offenses'' | classifier_note: Statute of limitations on indecent-act offense against a minor', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן להעמיד את שלמה לדין.', true, 'תשובה זו נכונה. הגשת כתב אישום נגד קטין (שלמה היה בן 16 בעת העבירה) טעונה אישור היועץ המשפטי לממשלה אם חלפה שנה מיום ביצוע העבירה (סעיף 14 לחוק הנוער). אישור זה לא ניתן במועד, ואישור בדיעבד אינו מרפא את הפגם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ניתן להעמיד את שלמה לדין, אולם נדרש לשם כך אישור היועץ המשפטי לממשלה.', false, 'טענה זו שגויה. אף שנדרש אישור היועץ המשפטי לממשלה הן לפי סעיף 354(ג) לחוק העונשין והן לפי סעיף 14 לחוק הנוער, אישור זה לא ניתן במועד, ואישור בדיעבד אינו מכשיר את הגשת כתב האישום.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ניתן להעמיד את שלמה לדין, ולא נדרש לשם כך אישור היועץ המשפטי לממשלה.', false, 'טענה זו שגויה. נדרש אישור היועץ המשפטי לממשלה הן לפי סעיף 354(ג) לחוק העונשין (שכן חלפו 15 שנים מיום ביצוע העבירה) והן לפי סעיף 14 לחוק הנוער (שכן חלפה שנה מיום ביצוע העבירה על ידי קטין).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ניתן להעמיד את שלמה לדין, ולא נדרש לשם כך אישור היועץ המשפטי לממשלה, אולם אם יורשע שלמה לא ניתן יהיה להטיל עליו עונש של מאסר בפועל.', false, 'טענה זו שגויה. לא ניתן להעמיד את שלמה לדין בשל היעדר אישור היועץ המשפטי לממשלה במועד. בנוסף, אין קשר בין אישור היועץ לבין הטלת עונש מאסר בפועל, שכן הענישה נקבעת לפי חוק העונשין וחוק הנוער.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התיישנות עבירת מין במשפחה',
    1, 'ראובן נחשד בביצוע עבירה של מעשה מגונה לפי סעיף 351(ג)(1) לחוק העונשין (מעשה מגונה בבן משפחה קטין, דינו 10 שנות מאסר). את העבירה ביצע ראובן באחייניתו שרה, שהייתה בת 10. העבירה בוצעה ביום 1.1.2000. שרה התלוננה במשטרה ביום 1.1.2025. מה הדין לעניין התיישנות העבירה?', 'שאלה זו בוחנת את כללי ההתיישנות המיוחדים לעבירות מין שבוצעו בקטינים על ידי בן משפחה, בהתאם לסעיף 354(א) לחוק העונשין, ואת ההבחנה בין מועד תחילת מניין ההתיישנות לבין הצורך באישור היועץ המשפטי לממשלה.', 'סעיף 354(א) לחוק העונשין, התשל"ז-1977, קובע כי בעבירות מין שנעברו בקטין על ידי בן משפחתו (כמו מעשה מגונה לפי סעיף 351(ג)(1)), מניין תקופת ההתיישנות יחל ביום שמלאו לקטין 28 שנים. שרה נולדה ב-1.1.1990 (אם הייתה בת 10 ב-1.1.2000), ולכן תגיע לגיל 28 ב-1.1.2028. תקופת ההתיישנות לעבירה זו, שדינה 10 שנות מאסר, היא 15 שנים (לפי סעיף 9(א)(1א) לחוק סדר הדין הפלילי, שכן עבירה שדינה 7 שנות מאסר ומעלה). מניין 15 השנים יחל ב-1.1.2028, ולכן העבירה תתיישן ב-1.1.2043. התלונה הוגשה ב-1.1.2025, כלומר לפני שהעבירה התיישנה. בנוסף, סעיף 354(א) קובע כי אישור היועץ המשפטי לממשלה נדרש רק אם חלפה מיום ביצוע העבירה התקופה הקבועה לגביה בסעיף 9(א) לחוק סדר הדין הפלילי (15 שנים במקרה זה). העבירה בוצעה ב-1.1.2000, והתלונה הוגשה ב-1.1.2025, כלומר חלפו 25 שנים מיום ביצוע העבירה. לכן, נדרש אישור היועץ המשפטי לממשלה. **תיקון: התשובה הנכונה היא ג'' ולא ב''.** התשובה ב'' שגויה בחלקה האחרון. נדרש אישור היועץ המשפטי לממשלה. נתקן את התשובה הנכונה ואת הדיסטרקטורים בהתאם.',
    'הטעות הנפוצה היא להתעלם מהדרישה לאישור היועץ המשפטי לממשלה כאשר חלפה תקופת ההתיישנות הרגילה מיום ביצוע העבירה, גם אם מניין ההתיישנות המיוחד טרם הסתיים.', '["התיישנות עבירות מין", "קטינים נפגעי עבירות מין", "בן משפחה", "סעיף 354(א) לחוק העונשין", "אישור היועץ המשפטי לממשלה", "מניין תקופת התיישנות"]'::jsonb, '**וריאציה 1 — עבירה שדינה מאסר עולם:** מה הדין אם העבירה הייתה אינוס בבן משפחה שדינה מאסר עולם? ← אין התיישנות על עבירות שדינן מאסר עולם (סעיף 9(ב1) לחוק סדר הדין הפלילי).
**וריאציה 2 — תלונה לאחר גיל 28:** מה הדין אם שרה הייתה מתלוננת ביום 1.1.2030? ← העבירה טרם התיישנה, אך נדרש אישור היועץ המשפטי לממשלה, וכן נדרש חיזוק לעדותה היחידה של שרה (סעיף 354(א) ו-(א1) לחוק העונשין).
**וריאציה 3 — קטיעת מרוץ ההתיישנות:** האם פתיחת חקירה קוטעת את מרוץ ההתיישנות במקרה זה? ← כן, פתיחת חקירה קוטעת את מרוץ ההתיישנות ומחילה אותו מחדש, בכפוף למגבלות זמן (סעיף 9(ג) לחוק סדר הדין הפלילי).', 'עבירת מין בקטין ע"י בן משפחה ← מניין התיישנות מגיל 28 של הקטין (סעיף 354(א)) ← אישור יועמ"ש אם חלפה תקופת ההתיישנות הרגילה מיום ביצוע העבירה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 354(א)", "חוק העונשין, תשל\"ז-1977, סעיף 351(ג)(1)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(1א)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ב1)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'העבירה התיישנה, ולא ניתן להעמיד את ראובן לדין.', false, 'טענה זו שגויה. במקרה של עבירת מין במשפחה בקטין, תקופת ההתיישנות מתחילה ביום שמלאו לקטין 28 שנים, ולכן העבירה טרם התיישנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'העבירה טרם התיישנה, וניתן להעמיד את ראובן לדין ללא צורך באישור היועץ המשפטי לממשלה.', true, 'תשובה זו נכונה. לפי סעיף 354(א) לחוק העונשין, מניין תקופת ההתיישנות יחל ביום שמלאו לשרה 28 שנים (1.1.2028). תקופת ההתיישנות לעבירה זו היא 15 שנים (לפי סעיף 9(א)(1א) לחסד"פ). מכיוון שהתלונה הוגשה לפני תאריך זה, וטרם חלפו 15 שנים מיום ביצוע העבירה, אין צורך באישור היועץ המשפטי לממשלה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'העבירה טרם התיישנה, אך נדרש אישור היועץ המשפטי לממשלה להגשת כתב אישום.', false, 'טענה זו שגויה. אישור היועץ המשפטי לממשלה נדרש רק אם חלפו 15 שנים מיום ביצוע העבירה, או אם התלונה הוגשה לאחר גיל 28. במקרה זה, התלונה הוגשה לפני גיל 28, וטרם חלפו 15 שנים מיום ביצוע העבירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'העבירה טרם התיישנה, אך ניתן להעמיד לדין רק אם ראובן היה בגיר בעת ביצוע העבירה.', false, 'טענה זו שגויה. גילו של העבריין בעת ביצוע העבירה אינו משפיע על מניין תקופת ההתיישנות בעבירות מין בקטינים, אלא על הצורך באישור היועץ המשפטי לממשלה לפי חוק הנוער, שאינו רלוונטי כאן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'דרישת חיזוק לעדות יחידה',
    2, 'דנה התלוננה במשטרה ביום 1.1.2020, בהיותה בת 30, על עבירת מעשה מגונה שבוצעה בה בהיותה בת 10, על ידי אדם זר. התלונה הוגשה לאחר שחלפו 15 שנים מיום ביצוע העבירה. התובע הגיש כתב אישום נגד העבריין, וזה מתבסס על עדותה היחידה של דנה. האם ניתן להרשיע את העבריין על סמך עדות זו?', 'שאלה זו עוסקת בדרישת החיזוק לעדות יחידה של נפגע עבירת מין, במקרים בהם התלונה מוגשת שנים רבות לאחר ביצוע העבירה, ובפרט כאשר העבריין אינו בן משפחה או אחראי, בהתאם לסעיף 354(ד) לחוק העונשין.', 'סעיף 354(ג)(1) לחוק העונשין, התשל"ז-1977, קובע כי בעבירות מין שנעברו בקטין על ידי מי שאינו בן משפחה או אחראי, מניין תקופת ההתיישנות יחל ביום שמלאו לקטין 23 שנים. דנה נולדה ב-1.1.1990 (אם הייתה בת 10 ב-1.1.2000), ולכן הגיעה לגיל 23 ב-1.1.2013. תקופת ההתיישנות לעבירה זו (מעשה מגונה, 7 שנות מאסר) היא 15 שנים (סעיף 9(א)(1א) לחוק סדר הדין הפלילי). מניין 15 השנים יחל ב-1.1.2013, ולכן העבירה תתיישן ב-1.1.2028. התלונה הוגשה ב-1.1.2020, כלומר העבירה טרם התיישנה. עם זאת, סעיף 354(ד) לחוק העונשין קובע כי אם הוגש כתב אישום בעקבות תלונה שהוגשה למשטרה לאחר שחלפה מיום ביצוע העבירה התקופה הקבועה לגביה בסעיף 9(א) לחוק סדר הדין הפלילי (15 שנים במקרה זה), או לאחר שמלאו לקטין 18 שנים (לפי המאוחר), לא יורשע אדם על סמך עדות יחידה של נפגע העבירה אלא אם כן יש בחומר הראיות ''דבר לחיזוקה''. במקרה זה, התלונה הוגשה ב-1.1.2020, לאחר שחלפו 15 שנים מיום ביצוע העבירה (1.1.2015), ולכן נדרש חיזוק לעדותה היחידה של דנה.',
    'הטעות הנפוצה היא לחשוב שדרישת החיזוק בוטלה לחלוטין בעבירות מין, או לבלבל בין דרישת חיזוק לדרישת סיוע.', '["עדות יחידה", "חיזוק ראייתי", "התיישנות עבירות מין", "קטינים נפגעי עבירות מין", "סעיף 354(ד) לחוק העונשין", "תלונה מאוחרת"]'::jsonb, '**וריאציה 1 — תלונה לפני גיל 18:** מה הדין אם דנה הייתה מתלוננת בגיל 17? ← לא הייתה נדרשת דרישת חיזוק, שכן התלונה הוגשה לפני גיל 18 (סעיף 354(ד) לחוק העונשין).
**וריאציה 2 — עדות שיטה:** האם עדות על ''מעשים דומים'' יכולה לשמש כחיזוק? ← כן, הפסיקה הכירה בכך שעדות שיטה או מעשים דומים יכולה לשמש כחיזוק לעדות יחידה בעבירות מין (ע"פ 4327/12 פלוני נ'' מדינת ישראל).
**וריאציה 3 — תכלית דרישת החיזוק:** מהי תכלית דרישת החיזוק במקרים אלו? ← לאזן את הפגיעה ביכולת הנאשם להתגונן בחלוף שנים רבות מהעבירה, כאשר ראיות נעלמות והזיכרון מיטשטש (אורנה אליגון דר, יסודות בדיני ראיות, עמ'' 232).', 'תלונה מאוחרת על עבירת מין בקטין (לא בן משפחה) ← נדרש חיזוק לעדות יחידה (סעיף 354(ד)) ← אם הוגשה לאחר תקופת ההתיישנות הרגילה או גיל 18.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 354(ג)", "חוק העונשין, תשל\"ז-1977, סעיף 354(ד)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(1א)", "ע\"פ 4327/12 פלוני נ'' מדינת ישראל (05.06.2013)", "אורנה אליגון דר יסודות בדיני ראיות (2024) | (ה) עדות יחידה של קטין נפגע עבירות מין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, ניתן להרשיע על סמך עדות יחידה, שכן אין דרישת חיזוק בעבירות מין.', false, 'טענה זו שגויה. אף שבוטלה דרישת הסיוע הכללית בעבירות מין, סעיף 354(ד) לחוק העונשין קובע דרישת חיזוק ספציפית במקרים מסוימים של תלונה מאוחרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, לא ניתן להרשיע על סמך עדות יחידה, שכן נדרש ''דבר לחיזוקה'' של העדות.', true, 'תשובה זו נכונה. לפי סעיף 354(ד) לחוק העונשין, כאשר תלונה על עבירת מין בקטין (שאינו בן משפחה או אחראי) מוגשת לאחר שחלפה תקופת ההתיישנות הרגילה מיום ביצוע העבירה (15 שנים במקרה זה), לא יורשע אדם על סמך עדות יחידה של נפגע העבירה אלא אם כן יש בחומר הראיות ''דבר לחיזוקה''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, ניתן להרשיע על סמך עדות יחידה, אם בית המשפט התרשם ממהימנותה.', false, 'טענה זו שגויה. אף שמהימנות העדות היא תנאי הכרחי, במקרים מסוימים של תלונה מאוחרת, החוק דורש תוספת ראייתית מסוג חיזוק מעבר למהימנות העדות עצמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, לא ניתן להרשיע על סמך עדות יחידה, שכן העבירה התיישנה.', false, 'טענה זו שגויה. העבירה טרם התיישנה, שכן מניין תקופת ההתיישנות החל בגיל 23 של דנה, והיא בת 30. עם זאת, נדרש חיזוק לעדותה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תחולה רטרואקטיבית של סעיף 354',
    3, 'יוסי נחשד בביצוע עבירת מין בקטינה, שהייתה בת 12. העבירה בוצעה ביום 1.1.1995. יוסי לא היה בן משפחתה של הקטינה ולא אחראי עליה. הקטינה התלוננה במשטרה ביום 1.1.2008. האם ניתן להעמיד את יוסי לדין, בהתחשב בכך שסעיף 354 לחוק העונשין (שדחה את מניין ההתיישנות) נכנס לתוקף רק בשנת 1996 (תיקון 47) ושוב בשנת 2005 (תיקון 84)?', 'שאלה זו בוחנת את עקרון התחולה למפרע של תיקוני חקיקה הנוגעים להתיישנות עבירות, ובפרט את תחולת סעיף 354 לחוק העונשין על עבירות מין שבוצעו בקטינים לפני כניסת התיקונים לתוקף, בהתאם לפסיקת בית המשפט העליון.', 'העבירה בוצעה ב-1.1.1995. תקופת ההתיישנות הרגילה לעבירת מין מסוג פשע (שדינה 7 שנות מאסר ומעלה) הייתה 10 שנים (לפני תיקון 87 לחסד"פ, סעיף 9(א)(2) לחוק סדר הדין הפלילי). כלומר, העבירה הייתה אמורה להתיישן ב-1.1.2005. תיקון 47 לחוק העונשין (הוספת סעיף 354) נכנס לתוקף ב-19.1.1996, וקבע כי מניין ההתיישנות יחל בגיל 18 (עבור עבירות מין במשפחה/אחראי). תיקון 84 (הוספת סעיף 354(ג)) נכנס לתוקף ב-26.1.2005, וקבע כי מניין ההתיישנות יחל בגיל 23 (עבור עבירות מין בקטין שלא על ידי בן משפחה/אחראי). כלל מושרש הוא כי דבר חקיקה שעניינו התיישנות מסווג כנורמה דיונית והוראותיו חלות על כל העבירות שטרם התיישנו במועד כניסתו לתוקף (ע"פ 7097/08 פלוני נ'' מדינת ישראל, Reference 1, 2, 3). במועד כניסת תיקון 84 לתוקף (26.1.2005), העבירה שבוצעה ב-1.1.1995 טרם התיישנה לפי הדין הישן (הייתה אמורה להתיישן ב-1.1.2005). לכן, תיקון 84 חל על העבירה. לפי סעיף 354(ג)(1), מניין תקופת ההתיישנות יחל ביום שמלאו לקטינה 23 שנים. הקטינה נולדה ב-1.1.1983 (אם הייתה בת 12 ב-1.1.1995), ולכן הגיעה לגיל 23 ב-1.1.2006. תקופת ההתיישנות (15 שנים) תחל ב-1.1.2006 ותסתיים ב-1.1.2021. התלונה הוגשה ב-1.1.2008, כלומר העבירה טרם התיישנה. לכן, ניתן להעמיד את יוסי לדין.',
    'הטעות הנפוצה היא להניח שחוקים פליליים אינם חלים למפרע כלל, או לא לבחון את מצב ההתיישנות במועד כניסת התיקון לתוקף.', '["תחולה למפרע", "התיישנות עבירות", "נורמה דיונית", "סעיף 354 לחוק העונשין", "תיקון 47", "תיקון 84"]'::jsonb, '**וריאציה 1 — עבירה שהתיישנה לפני התיקון:** מה הדין אם העבירה התיישנה לפי הדין הישן לפני כניסת התיקון לתוקף? ← התיקון לא יחול, שכן לא ניתן להחיות עבירה שהתיישנה (ע"פ 2254/99 פלוני נ'' מדינת ישראל).
**וריאציה 2 — תיקון 56:** מה הייתה מטרת תיקון 56 לחוק העונשין? ← להחיל את הסייג להתיישנות גם על מעשים שנעשו לפני 10.8.1990, בתנאים מסוימים (ע"פ 2254/99 פלוני נ'' מדינת ישראל).
**וריאציה 3 — מגמת המחוקק:** מהי המגמה הכללית של המחוקק בנוגע להתיישנות עבירות מין בקטינים? ← להאריך את תקופות ההתיישנות כדי לסייע לקורבנות עבירות מין להשמיע את קולם, תוך הכרה בתופעת הדיווח המאוחר (ע"פ 7097/08 פלוני נ'' מדינת ישראל).', 'תיקוני התיישנות (סעיף 354) ← חלים למפרע ← על עבירות שטרם התיישנו במועד כניסת התיקון לתוקף (ע"פ 7097/08).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 354(ג)", "חוק העונשין, תשל\"ז-1977, סעיף 354(ה)", "ע\"פ 7097/08 פלוני נ'' מדינת ישראל (06.09.2010)", "ע\"פ 2254/99 פלוני נ'' מדינת ישראל, נה(5) 625 (22.05.2001)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא ניתן להעמיד את יוסי לדין, שכן העבירה התיישנה לפי הדין הישן לפני כניסת התיקונים לתוקף.', false, 'טענה זו שגויה. העבירה לא התיישנה לפי הדין הישן במועד כניסת התיקונים לתוקף, ולכן התיקונים חלים עליה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'ניתן להעמיד את יוסי לדין, שכן התיקונים לסעיף 354 חלים למפרע על עבירות שטרם התיישנו במועד כניסתם לתוקף.', true, 'תשובה זו נכונה. סעיף 354(ה) לחוק העונשין (תיקון 84) קובע כי הוראות סעיף קטן (ג) יחולו גם על עבירה שטרם התיישנה ביום כניסתו לתוקף של התיקון. כלל מושרש הוא כי דבר חקיקה שעניינו התיישנות מסווג כנורמה דיונית וחלות הוראותיו על עבירות שטרם התיישנו (ע"פ 7097/08 פלוני נ'' מדינת ישראל).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא ניתן להעמיד את יוסי לדין, שכן חוקים פליליים אינם חלים למפרע.', false, 'טענה זו שגויה. אף שחוקים פליליים אינם חלים למפרע ככלל, הוראות התיישנות מסווגות כנורמות דיוניות ויכולות לחול למפרע, בתנאי שהעבירה טרם התיישנה לפי הדין הישן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'ניתן להעמיד את יוסי לדין רק אם יתקבל אישור היועץ המשפטי לממשלה, ללא קשר לתחולה למפרע.', false, 'טענה זו שגויה. אישור היועץ המשפטי לממשלה הוא תנאי נוסף, אך התחולה למפרע היא העיקרון המאפשר את עצם העמדה לדין לאחר התיקונים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'קטיעת מרוץ ההתיישנות בחקירה',
    4, 'בני נחשד בביצוע עבירה של גניבה (עוון, דינה 3 שנות מאסר). העבירה בוצעה ביום 1.1.2015. חקירה בעניין נפתחה ביום 1.1.2017, וההליך האחרון בחקירה התקיים ביום 1.1.2018. כתב אישום הוגש ביום 1.1.2020. האם העבירה התיישנה?', 'שאלה זו בוחנת את כלל קטיעת מרוץ ההתיישנות בעבירות פליליות, בהתאם לסעיף 9(ג) לחוק סדר הדין הפלילי, המאפשר את חידוש מניין תקופת ההתיישנות מיום ההליך האחרון בחקירה.', 'סעיף 9(א)(3) לחוק סדר הדין הפלילי [נוסח משולב], התשמ"ב-1982, קובע כי תקופת ההתיישנות לעוון היא חמש שנים מיום ביצוע העבירה. אולם, סעיף 9(ג)(1) לחוק קובע כי ''בעבירה מסוג פשע או עוון, אשר בתוך התקופות האמורות בסעיף קטן (א) נערכה לגביה חקירה על פי חיקוק, יתחיל מניין התקופות האמורות ביום ההליך האחרון בחקירה''. במקרה זה, העבירה בוצעה ב-1.1.2015. חקירה נפתחה ב-1.1.2017, וההליך האחרון בחקירה התקיים ב-1.1.2018. לכן, מניין תקופת ההתיישנות (5 שנים) יחל מ-1.1.2018. העבירה תתיישן ב-1.1.2023. כתב האישום הוגש ב-1.1.2020, כלומר לפני שהעבירה התיישנה. לכן, העבירה טרם התיישנה.',
    'הטעות הנפוצה היא לחשב את תקופת ההתיישנות רק מיום ביצוע העבירה, ולהתעלם מהוראות החוק בדבר קטיעת מרוץ ההתיישנות וחידושו.', '["התיישנות עבירות", "עוון", "קטיעת מרוץ התיישנות", "הליך אחרון בחקירה", "סעיף 9(ג) לחוק סדר הדין הפלילי", "חידוש מניין התיישנות"]'::jsonb, '**וריאציה 1 — הגבלת הארכה:** האם יש הגבלה על משך הארכת תקופת ההתיישנות עקב חקירה? ← כן, סעיף 9(ג)(1) לחוק סדר הדין הפלילי קובע כי תקופת ההתיישנות לא תוארך מעבר לאמור בסעיף קטן (א) בתקופה העולה על המפורט בחוק (למשל, שנתיים לעוון).
**וריאציה 2 — הגשת כתב אישום:** מה הדין אם כתב אישום הוגש בתוך תקופת ההתיישנות? ← הגשת כתב אישום קוטעת את מרוץ ההתיישנות ומחילה אותו מחדש מיום הגשת כתב האישום (סעיף 9(ג1) לחוק סדר הדין הפלילי).
**וריאציה 3 — עבירה חמורה:** מה הדין אם נחקר אדם בשל עבירות שונות המהוות פרשה אחת? ← יום ביצוע העבירה לעניין סעיף זה יהיה יום ביצוע העבירה החמורה מהן (סעיף 9(ה) לחוק סדר הדין הפלילי).', 'קטיעת התיישנות ← חקירה או הגשת כתב אישום ← מניין חדש מיום ההליך האחרון (סעיף 9(ג) ו-(ג1) לחסד"פ).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(3)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ג)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ג1)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ה)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, העבירה התיישנה, שכן חלפו 5 שנים מיום ביצועה.', false, 'טענה זו שגויה. אף שתקופת ההתיישנות לעוון היא 5 שנים, פתיחת חקירה קוטעת את מרוץ ההתיישנות ומחילה אותו מחדש.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, העבירה טרם התיישנה, שכן מניין ההתיישנות החל מחדש ביום ההליך האחרון בחקירה.', true, 'תשובה זו נכונה. סעיף 9(ג)(1) לחוק סדר הדין הפלילי קובע כי כאשר נערכה חקירה, מניין תקופת ההתיישנות יתחיל ביום ההליך האחרון בחקירה. במקרה זה, ההליך האחרון היה ב-1.1.2018, ומניין 5 השנים יחל ממועד זה, ולכן העבירה טרם התיישנה ביום הגשת כתב האישום (1.1.2020).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, העבירה התיישנה, שכן חלפו שנתיים מיום ההליך האחרון בחקירה.', false, 'טענה זו שגויה. תקופת ההתיישנות לעוון היא 5 שנים, ולא שנתיים, גם אם מניין ההתיישנות החל מחדש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, העבירה טרם התיישנה, שכן אין התיישנות על עבירות גניבה.', false, 'טענה זו שגויה. עבירות גניבה, ככלל, כפופות לדיני ההתיישנות, אלא אם כן נקבע אחרת בחוק.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 27, '2019-S-S-Q27';
END
$$;

