  v_ang_0 uuid := '8bbf288c-d76c-463e-8774-5ee4d1ea6ac1'::uuid;
  v_ang_1 uuid := '317e205b-e4e3-418a-ba70-b724949129f1'::uuid;
  v_ang_2 uuid := '67462740-f523-40ee-bb00-642a81789617'::uuid;
  v_ang_3 uuid := '707ee06f-b23d-4433-b698-b9d20fc3e991'::uuid;
BEGIN
