  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q28', v_chapter_id, v_subtopic_id, 'דני ודנה היו נשואים במשך כ-30 שנה החל בשנת 1980. במהלך שנים אלו צברו את כל רכושם וכולו נרשם על שמו של דני. דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון בין בני זוג, התשל"ג-1973. במהלך הנישואים נולדו להם שני ילדים. דני, שהיה טיפוס ממורמר ומעולם לא שמח בחלקו, תלה מגרעותיו אלו בדנה, ולכן כתב צוואה ובה הוריש את כל הרכוש הרשום על שמו לילדיו בלבד. דני נפטר. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 28}'::jsonb, 'השאלה עוסקת ביחס שבין זכות בן זוג לאיזון משאבים מכוח חוק יחסי ממון לבין הוראות צוואה. היא מדגישה את העיקרון לפיו זכות בן הזוג למחצית הרכוש שנצבר במהלך הנישואין קודמת לדיני הירושה ואינה חלק מעיזבונו של המנוח.', 'דני ודנה נישאו בשנת 1980, ולכן חל עליהם חוק יחסי ממון בין בני זוג, התשל"ג-1973. לפי סעיף 5 לחוק זה, עם פקיעת הנישואין (במקרה זה, עקב מותו של דני), זכאית דנה למחצית שוויים של כלל הנכסים שנצברו במהלך הנישואין. זכות זו היא ''חוב עזבון'' וקודמת לחלוקת העיזבון על פי צוואה או על פי דין. כלומר, יש לבצע תחילה את איזון המשאבים, ורק לאחר מכן, המחצית הנותרת (שהיא עיזבונו של דני) תחולק על פי צוואתו. במקרה זה, דני הוריש את כל הרכוש הרשום על שמו לילדיו בלבד. מכיוון שדנה זכאית למחצית הרכוש מכוח חוק יחסי ממון, רק המחצית השנייה היא עיזבונו של דני, ובה הוא רשאי לצוות כרצונו. לכן, הילדים יירשו את המחצית השנייה בלבד, ודנה תקבל את חלקה מכוח איזון המשאבים.', 'הטעות הנפוצה היא לראות את כל הרכוש הרשום על שם המנוח כחלק מעיזבונו, ולהתעלם מזכות בן הזוג לאיזון משאבים, שהיא זכות קניינית הקודמת לדיני הירושה.',
    '["איזון משאבים", "חוק יחסי ממון", "חוק הירושה", "צוואה", "עיזבון", "חוב עזבון", "זכות קניינית"]'::jsonb, '**וריאציה 1 — הלכת השיתוף:** מה הדין אם דני ודנה היו נשואים לפני 1.1.1974? ← עליהם הייתה חלה הלכת השיתוף, לפיה הרכוש המשותף היה מתחלק ביניהם בחלקים שווים, ורק חלקו של דני היה נכלל בעיזבון (ע"א 80/80 קוטלר נ'' קוטלר).
**וריאציה 2 — נכסים חיצוניים:** מה הדין אם לדני היו נכסים שקיבל בירושה במהלך הנישואין? ← נכסים אלו אינם נכללים באיזון המשאבים (סעיף 5(א)(1) לחוק יחסי ממון), ולכן הם היו חלק מעיזבונו של דני והיו עוברים לילדיו על פי הצוואה.
**וריאציה 3 — מזונות מהעיזבון:** האם דנה זכאית למזונות מהעיזבון? ← כן, אם היא זקוקה למזונות, בית המשפט רשאי לפסוק לה מזונות מהעיזבון, גם אם נושלה מהירושה (סעיף 56 לחוק הירושה).', 'זכות בן זוג לאיזון משאבים ← קודמת לצוואה ← רק היתרה היא עיזבון (סעיף 5 לחוק יחסי ממון, סעיף 11(ג) לחוק הירושה).', '["חוק יחסי ממון בין בני זוג, תשל\"ג-1973, סעיף 5", "חוק הירושה, תשכ\"ה-1965, סעיף 11(ג)", "חוק הירושה, תשכ\"ה-1965, סעיף 56", "ע\"א 80/80 קוטלר נ'' קוטלר, פ\"ד לה(1) 60 (1980)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''spousal_property'' | classifier_note: Spousal property after death — 30-year marriage, all assets in husband''s name | source_review_note: השאלה עוסקת בדיני ירושה ודיני משפחה (יחסי ממון), תחומים שאינם נכללים ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', '"מצווה לקיים את רצון המת", דני הוא הבעלים על הרכוש הרשום על שמו, ולכן רשאי להורישו לכל מי שעולה בדעתו. לכן הילדים נוטלים את כל הרכוש.', false, 'טענה זו שגויה. זכותה של דנה למחצית הרכוש מכוח חוק יחסי ממון קודמת לצוואה ואינה חלק מעיזבונו של דני.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא ניתן סתם כך לנשל את בן הזוג מהירושה, ולכן הצוואה פסולה. הירושה תהיה על פי דין.', false, 'טענה זו שגויה. הצוואה אינה פסולה, אלא חלה רק על חלקו של דני ברכוש לאחר איזון המשאבים. ניתן לנשל בן זוג מהירושה באמצעות צוואה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על אף הצוואה זכאית דנה למחצית מהרכוש מכוח חוק יחסי ממון. את המחצית השנייה רשאי דני להוריש לילדיו, והם בלבד יזכו בה.', true, 'תשובה זו נכונה. זכותה של דנה למחצית הרכוש מכוח איזון משאבים היא זכות קניינית שאינה חלק מעיזבונו של דני. רק המחצית הנותרת היא עיזבונו של דני, ובה הוא רשאי לצוות כרצונו, במקרה זה לילדיו.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על אף הצוואה זכאית דנה למחצית מהרכוש מכוח חוק יחסי ממון. במחצית השנייה הירושה תהיה על פי דין, כלומר מחצית (שהיא רבע) לדנה, ומחצית (שהיא רבע) לילדים.', false, 'טענה זו שגויה. דנה זכאית למחצית מכוח איזון משאבים. המחצית הנותרת היא עיזבונו של דני, ובה הוא ציווה לילדיו, ולכן היא לא תחולק על פי דין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ירושה על פי דין ואיזון משאבים',
    1, 'דני ודנה היו נשואים במשך כ-30 שנה החל בשנת 1980. במהלך שנים אלו צברו את כל רכושם וכולו נרשם על שמו של דני. דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון בין בני זוג, התשל"ג-1973. במהלך הנישואים נולדו להם שני ילדים. דני נפטר, ולא הותיר אחריו צוואה. מה הדין?', 'שאלה זו בוחנת את היחס בין זכות בן הזוג לאיזון משאבים מכוח חוק יחסי ממון לבין זכותו כיורש על פי דין, בהיעדר צוואה, בהתאם לסעיף 11 לחוק הירושה.', 'כאשר בן זוג נפטר, יש לבצע תחילה איזון משאבים לפי חוק יחסי ממון בין בני זוג, התשל"ג-1973. דנה זכאית למחצית הרכוש שנצבר במהלך הנישואין, וזכות זו קודמת לדיני הירושה. רק המחצית הנותרת היא עיזבונו של דני. בהיעדר צוואה, העיזבון יחולק על פי דין. סעיף 11(א)(1) לחוק הירושה, התשכ"ה-1965, קובע כי בן זוג יורש מחצית מהעיזבון כאשר למוריש יש ילדים. לכן, דנה תקבל מחצית מהרכוש מכוח איזון משאבים, ומהמחצית הנותרת (שהיא עיזבונו של דני) היא תקבל מחצית נוספת (כלומר רבע מהרכוש הכולל), ואת היתרה (רבע מהרכוש הכולל) יירשו הילדים בחלקים שווים ביניהם.',
    'הטעות הנפוצה היא לבלבל בין זכות בן הזוג לאיזון משאבים לבין זכותו כיורש, או לחשוב שאחת מהן מבטלת את השנייה.', '["איזון משאבים", "חוק יחסי ממון", "ירושה על פי דין", "חוק הירושה סעיף 11", "עיזבון", "זכות קניינית"]'::jsonb, '**וריאציה 1 — ירושה ללא ילדים:** מה הדין אם לדני ודנה לא היו ילדים? ← דנה הייתה יורשת את כל העיזבון (המחצית הנותרת לאחר איזון משאבים), אם לא היו הורים או אחים לדני (סעיף 11(א)(2) לחוק הירושה).
**וריאציה 2 — ירושה עם הורים:** מה הדין אם לדני ודנה לא היו ילדים, אך הוריו של דני היו בחיים? ← דנה הייתה יורשת שני שלישים מהעיזבון, והוריו של דני היו יורשים שליש (סעיף 11(א)(2) לחוק הירושה).
**וריאציה 3 — ירושה עם אחים:** מה הדין אם לדני ודנה לא היו ילדים והוריו לא בחיים, אך היו לו אחים? ← דנה הייתה יורשת שני שלישים מהעיזבון, ואחיו של דני היו יורשים שליש (סעיף 11(א)(2) לחוק הירושה).', 'מוות ללא צוואה ← תחילה איזון משאבים (מחצית לבן הזוג) ← אח"כ ירושה על פי דין מהעיזבון הנותר (סעיף 11 לחוק הירושה).',
    '["חוק יחסי ממון בין בני זוג, תשל\"ג-1973", "חוק הירושה, תשכ\"ה-1965, סעיף 11"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון, ואת המחצית השנייה יירשו הילדים בלבד.', false, 'טענה זו שגויה. במקרה של ירושה על פי דין, בן הזוג היורש זכאי לחלק מהעיזבון בנוסף לילדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון, ומהמחצית הנותרת תקבל דנה מחצית (שהיא רבע מהרכוש הכולל), ואת היתרה יירשו הילדים.', true, 'תשובה זו נכונה. דנה זכאית למחצית הרכוש מכוח איזון משאבים. המחצית הנותרת היא עיזבונו של דני, ובהיעדר צוואה, היא תחולק על פי דין: מחצית לדנה ומחצית לילדים (סעיף 11(א)(1) לחוק הירושה).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'דנה זכאית לכל הרכוש, שכן היא הייתה נשואה לדני במשך 30 שנה.', false, 'טענה זו שגויה. דנה אינה זכאית לכל הרכוש, שכן ישנם ילדים יורשים, וזכותה לאיזון משאבים היא למחצית בלבד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הילדים יירשו את כל הרכוש, שכן דנה כבר קיבלה את חלקה מכוח חוק יחסי ממון.', false, 'טענה זו שגויה. דנה זכאית גם לחלק מהעיזבון כיורשת על פי דין, בנוסף לזכותה לאיזון משאבים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מועד היווצרות זכות איזון המשאבים',
    2, 'דני ודנה נשואים משנת 1980. בשנת 2010 הגישה דנה תביעת גירושין. במהלך הדיונים, בשנת 2011, נפטר דני. כל הרכוש נרשם על שמו של דני. דני הותיר צוואה ובה הוריש את כל רכושו לילדיו בלבד. מתי נוצרת זכותה של דנה לאיזון משאבים?', 'שאלה זו בוחנת את מועד היווצרות הזכות לאיזון משאבים בין בני זוג שנישאו לאחר 1.1.1974, בהתאם לסעיף 5 לחוק יחסי ממון, ואת ההבחנה בין מועד זה לבין מועדים אחרים.', 'סעיף 5(א) לחוק יחסי ממון בין בני זוג, התשל"ג-1973, קובע כי ''עם התרת הנישואין או עם פטירתו של בן זוג, זכאי כל אחד מבני הזוג למחצית שוויים של כלל נכסי בני הזוג''. כלומר, הזכות לאיזון משאבים קמה עם פקיעת הנישואין, בין אם עקב גירושין ובין אם עקב מוות. במקרה זה, הנישואין פקעו עם פטירתו של דני בשנת 2011. לכן, ביום זה נוצרה זכותה של דנה לאיזון משאבים. חשוב לציין כי מדובר בהסדר דחוי, כלומר במהלך הנישואין לכל אחד מבני הזוג יש זכות עתידית לאיזון, אך היא מתגבשת וניתנת למימוש רק עם פקיעת הנישואין.',
    'הטעות הנפוצה היא לחשוב שהזכות לאיזון משאבים קמה כבר במהלך הנישואין, או עם הגשת תביעת גירושין, ולא עם פקיעת הנישואין בפועל.', '["איזון משאבים", "חוק יחסי ממון סעיף 5", "פקיעת נישואין", "הסדר דחוי", "מועד היווצרות זכות", "גירושין", "מוות"]'::jsonb, '**וריאציה 1 — בני זוג ידועים בציבור:** האם חוק יחסי ממון חל על ידועים בציבור? ← לא, על ידועים בציבור חלה הלכת השיתוף, אלא אם קבעו אחרת (ע"א 52/80 שחר נ'' פרידמן).
**וריאציה 2 — נכסים שאינם ברי איזון:** אילו נכסים אינם נכללים באיזון משאבים? ← נכסים שהיו לבן הזוג לפני הנישואין, נכסים שהתקבלו במתנה או בירושה בתקופת הנישואין, גימלה או פיצוי בגין נזק גוף, וכן נכסים שהוסכם עליהם בהסכם ממון (סעיף 5(א) לחוק יחסי ממון).
**וריאציה 3 — פטירה לפני גירושין:** מה הדין אם דני היה נפטר לפני הגשת תביעת הגירושין? ← הזכות לאיזון משאבים הייתה קמה גם אז, עם פטירתו, והייתה ממומשת על ידי עיזבונו (סעיף 5(א) לחוק יחסי ממון).', 'זכות איזון משאבים ← קמה עם פקיעת הנישואין (גירושין או מוות) ← הסדר דחוי (סעיף 5 לחוק יחסי ממון).',
    '["חוק יחסי ממון בין בני זוג, תשל\"ג-1973, סעיף 5(א)", "ע\"א 52/80 שחר נ'' פרידמן, פ\"ד לה(1) 60 (1980)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'זכותה של דנה לאיזון משאבים נוצרה ביום הגשת תביעת הגירושין.', false, 'טענה זו שגויה. הגשת תביעת גירושין אינה מועד פקיעת הנישואין, אלא רק תחילת ההליך לפקיעתם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'זכותה של דנה לאיזון משאבים נוצרה ביום פטירתו של דני.', true, 'תשובה זו נכונה. סעיף 5(א) לחוק יחסי ממון קובע כי עם פקיעת הנישואין עקב גירושין או מותו של בן זוג, קמה הזכות לאיזון משאבים. במקרה זה, הנישואין פקעו עם מותו של דני.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'זכותה של דנה לאיזון משאבים נוצרה ביום נישואיהם של דני ודנה.', false, 'טענה זו שגויה. חוק יחסי ממון קובע הסדר דחוי, לפיו הזכות לאיזון משאבים קמה רק עם פקיעת הנישואין, ולא במועד הנישואין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'זכותה של דנה לאיזון משאבים נוצרה ביום כניסתו לתוקף של חוק יחסי ממון.', false, 'טענה זו שגויה. אף שחוק יחסי ממון חל על בני זוג שנישאו לאחר 1.1.1974, הזכות לאיזון משאבים עצמה קמה רק עם פקיעת הנישואין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הסכם ממון וצוואה',
    3, 'דני ודנה נישאו בשנת 1980. לפני נישואיהם ערכו הסכם ממון שאושר כדין, ובו נקבע כי כל הרכוש שייצבר במהלך הנישואין יישאר בבעלותו הבלעדית של בן הזוג שעל שמו הוא רשום. דני נפטר והותיר צוואה ובה הוריש את כל הרכוש הרשום על שמו לילדיו בלבד. מה הדין?', 'שאלה זו בוחנת את עקרון חופש החוזים בדיני משפחה, ובפרט את תוקפו של הסכם ממון שאושר כדין, הגובר על הוראות חוק יחסי ממון, ואת השלכותיו על חלוקת הרכוש במקרה של מוות וצוואה.', 'חוק יחסי ממון בין בני זוג, התשל"ג-1973, קובע הסדר איזון משאבים כברירת מחדל לבני זוג שנישאו לאחר 1.1.1974. אולם, סעיף 3 לחוק מאפשר לבני זוג לערוך ''הסכם ממון'' ולקבוע בו הסדר שונה מזה הקבוע בחוק, ובלבד שההסכם אושר על ידי בית המשפט או בית הדין הרבני. הסכם ממון שאושר כדין גובר על הוראות החוק. במקרה זה, דני ודנה ערכו הסכם ממון שאושר כדין, ובו נקבע כי כל הרכוש שייצבר יישאר בבעלותו הבלעדית של בן הזוג שעל שמו הוא רשום. משמעות הדבר היא שדנה אינה זכאית לאיזון משאבים. לכן, כל הרכוש הרשום על שם דני הוא עיזבונו הבלעדי, ובהתאם לצוואתו, הוא יועבר לילדיו בלבד.',
    'הטעות הנפוצה היא לחשוב שחוק יחסי ממון הוא קוגנטי ואינו ניתן לשינוי באמצעות הסכם ממון, או לבלבל בין הסכם ממון לבין צוואה.', '["הסכם ממון", "חוק יחסי ממון סעיף 3", "אישור הסכם ממון", "חופש החוזים", "עיזבון", "צוואה"]'::jsonb, '**וריאציה 1 — הסכם ממון שלא אושר:** מה הדין אם הסכם הממון לא אושר כדין? ← הסכם הממון לא יהיה תקף, ויחול הסדר איזון המשאבים הקבוע בחוק יחסי ממון (סעיף 2 לחוק יחסי ממון).
**וריאציה 2 — הסכם ממון לאחר נישואין:** האם ניתן לערוך הסכם ממון לאחר הנישואין? ← כן, אך גם הוא טעון אישור בית המשפט או בית הדין הרבני (סעיף 2(א) לחוק יחסי ממון).
**וריאציה 3 — הסכם ממון וצוואה סותרת:** מה הדין אם הסכם הממון קובע חלוקה מסוימת, וצוואה מאוחרת סותרת אותה? ← הסכם הממון גובר על הצוואה ככל שהוא נוגע לרכוש המשותף, שכן הוא קובע את היקף העיזבון (ע"א 169/83 שי נ'' שי).', 'הסכם ממון שאושר כדין ← גובר על חוק יחסי ממון (סעיף 3) ← קובע את היקף העיזבון שעליו חלה הצוואה.',
    '["חוק יחסי ממון בין בני זוג, תשל\"ג-1973, סעיף 2", "חוק יחסי ממון בין בני זוג, תשל\"ג-1973, סעיף 3", "ע\"א 169/83 שי נ'' שי, פ\"ד לט(3) 776 (1985)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון, שכן הסכם ממון אינו יכול לגבור על הוראות חוק.', false, 'טענה זו שגויה. הסכם ממון שאושר כדין גובר על הוראות חוק יחסי ממון, שכן החוק מאפשר לבני זוג לקבוע הסדר שונה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'דנה אינה זכאית למחצית הרכוש מכוח חוק יחסי ממון, שכן הסכם הממון גובר על הוראות החוק. כל הרכוש הרשום על שם דני הוא עיזבונו, והוא יועבר לילדיו על פי הצוואה.', true, 'תשובה זו נכונה. הסכם ממון שאושר כדין גובר על הוראות חוק יחסי ממון (סעיף 3 לחוק). לכן, דנה אינה זכאית לאיזון משאבים. כל הרכוש הרשום על שם דני הוא עיזבונו, ובהתאם לצוואתו, הוא יועבר לילדיו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הסכם הממון בטל, שכן הוא מנשל את דנה מכל רכוש, וזה נוגד את תקנת הציבור.', false, 'טענה זו שגויה. הסכם ממון המבטל את איזון המשאבים אינו נוגד את תקנת הציבור, כל עוד אושר כדין ונעשה בהסכמה חופשית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'דנה זכאית למחצית הרכוש מכוח חוק יחסי ממון, אך רק אם תוכיח שהסכם הממון נחתם תחת עושק.', false, 'טענה זו שגויה. בהיעדר טענה תקפה לפגם בכריתת הסכם הממון, הוא תקף וגובר על הוראות החוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות עניינית בענייני ירושה ואיזון משאבים',
    4, 'דנה מעוניינת להגיש תביעה לאיזון משאבים וכן תביעה לביטול צוואתו של דני. לאיזה בית משפט יש סמכות עניינית לדון בתביעות אלו?', 'שאלה זו בוחנת את כללי הסמכות העניינית בענייני משפחה וירושה, ובפרט את סמכותו הייחודית של בית המשפט לענייני משפחה לדון בתביעות לאיזון משאבים ובתביעות הנוגעות לצוואות הקשורות ליחסי משפחה.', 'סעיף 1(1) לחוק בית המשפט לענייני משפחה, התשנ"ה-1995, קובע כי ''ענייני משפחה'' כוללים ''תובענה לאיזון משאבים''. סעיף 1(2) לחוק קובע כי ''ענייני משפחה'' כוללים גם ''תובענה בענייני ירושה, לרבות צוואות וירושות, כשהעניין הוא בין בני משפחה''. במקרה זה, דנה מעוניינת להגיש תביעה לאיזון משאבים (שהיא עניין משפחה מובהק) ותביעה לביטול צוואה (שהיא עניין ירושה בין בני משפחה). לכן, הסמכות העניינית לדון בשתי התביעות נתונה באופן בלעדי לבית המשפט לענייני משפחה. לבית הדין הרבני סמכות בענייני ירושה רק אם כל הצדדים הסכימו לכך, ואין לו סמכות לדון בתביעות לאיזון משאבים.',
    'הטעות הנפוצה היא לבלבל בין סמכות בית המשפט לענייני משפחה לבין סמכות בית הדין הרבני, או לחשוב שכל עניין ירושה נדון בבית המשפט המחוזי.', '["סמכות עניינית", "בית המשפט לענייני משפחה", "איזון משאבים", "צוואה", "חוק בית המשפט לענייני משפחה", "בית הדין הרבני"]'::jsonb, '**וריאציה 1 — סמכות בית הדין הרבני בירושה:** מתי לבית הדין הרבני יש סמכות לדון בענייני ירושה? ← רק אם כל היורשים הסכימו לכך בכתב (סעיף 155 לחוק הירושה).
**וריאציה 2 — סמכות בית המשפט המחוזי בירושה:** מתי לבית המשפט המחוזי יש סמכות לדון בענייני ירושה? ← כאשר העניין אינו בין בני משפחה, או כאשר אין הסכמה להעביר את הדיון לבית הדין הרבני (סעיף 1(2) לחוק בית המשפט לענייני משפחה).
**וריאציה 3 — סמכות מקבילה:** האם יש סמכות מקבילה בין בית המשפט לענייני משפחה לבית הדין הרבני בענייני ירושה? ← כן, אם כל היורשים הסכימו בכתב להעביר את הדיון לבית הדין הרבני (סעיף 155 לחוק הירושה).', 'תביעת איזון משאבים וביטול צוואה בין בני משפחה ← סמכות ייחודית לבית המשפט לענייני משפחה (חוק בית המשפט לענייני משפחה).',
    '["חוק בית המשפט לענייני משפחה, תשנ\"ה-1995, סעיף 1", "חוק הירושה, תשכ\"ה-1965, סעיף 155"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט לענייני משפחה בלבד.', true, 'תשובה זו נכונה. תביעה לאיזון משאבים ותביעה לביטול צוואה (כאשר היא קשורה ליחסי משפחה) נכללות בסמכותו הייחודית של בית המשפט לענייני משפחה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט המחוזי בלבד.', false, 'טענה זו שגויה. בית המשפט המחוזי דן בענייני ירושה שאינם בסמכות בית המשפט לענייני משפחה, אך לא בתביעות איזון משאבים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית הדין הרבני בלבד.', false, 'טענה זו שגויה. לבית הדין הרבני סמכות בענייני ירושה רק אם כל הצדדים הסכימו לכך, ואין לו סמכות ייחודית בענייני איזון משאבים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט לענייני משפחה או בית הדין הרבני, לפי בחירתה של דנה.', false, 'טענה זו שגויה. לבית הדין הרבני אין סמכות מקבילה או ייחודית לדון בתביעת איזון משאבים, וסמכותו בענייני ירושה מוגבלת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 28, '2019-S-S-Q28';
END
$$;

-- ============================================================
-- Q29 — 2019-S-S-Q29 — chapter=family_inheritance subtopic=marriage_divorce
-- classifier_note: Civil marriage abroad (Jew + Christian); inheritance complications
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '2c6ebb34-9cb5-4688-adfa-f974b2ddafc3'::uuid;
  v_group_id uuid := '1bcfe1cf-3adc-4276-928c-3fd2e68060fe'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c7cc5b6c-cc3e-42c4-a164-5a89643b87ff'::uuid;
  v_ang_1 uuid := 'ff89a703-e489-4ca1-860b-8fcd1a63adce'::uuid;
  v_ang_2 uuid := '1acbea43-65d0-4338-89cd-23a0d4642076'::uuid;
  v_ang_3 uuid := 'bc750c77-3f50-40e2-a0c0-00e76ef03a2f'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q29';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 29, '2019-S-S-Q29';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'family_inheritance';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'family_inheritance';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'marriage_divorce' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'marriage_divorce', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q29', v_chapter_id, v_subtopic_id, 'לאחר 30 שנות נישואין נפטרה אשתו של שמעון ממחלה ממושכת. להם 3 ילדים בגירים. שמעון (יהודי), שהיה בעל רכוש רב, החליט להפיג את צערו באמצעות טיולים ברחבי העולם. באחד מהטיולים פגש בניקול, צרפתייה נוצרייה. הם נישאו בנישואין אזרחיים. לאחר תקופה קצרה נפטר שמעון ללא צוואה. בניו שואלים אם ניקול זכאית לירושה או חלקה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 29}'::jsonb, 'השאלה עוסקת בהוראות חוק הירושה, התשכ"ה-1965, ובפרט בהגדרת המונח ''בן זוג'' לצורך ירושה על פי דין, כאשר מדובר בנישואין אזרחיים שנערכו בחו"ל בין בני זוג מדתות שונות. היא בוחנת את עקרון ההכרה בנישואין אזרחיים תקפים מחו"ל ואת היחס בין חוק הירושה לדין האישי.', 'חוק הירושה, התשכ"ה-1965, הוא חוק אזרחי-חילוני. המונח ''בן זוג'' בסעיף 11 לחוק, הקובע את סדר היורשים על פי דין, מתפרש באופן רחב ואינו מוגבל לנישואין דתיים או לנישואין שנערכו בישראל. פסיקת בית המשפט העליון, ובפרט בע"מ 9607/03 פלוני נ'' פלונית (2006), קבעה כי נישואין אזרחיים תקפים שנערכו בחו"ל מוכרים בישראל לצורך חוק הירושה, גם אם הדין האישי של הצדדים (כמו הדין העברי במקרה של נישואי יהודי ונוצרייה) אינו מכיר בנישואין אלו. לפיכך, ניקול נחשבת לבת זוגו של שמעון לעניין ירושה. בהיעדר צוואה, ובהתאם לסעיף 11(א)(1) לחוק הירושה, כאשר למנוח יש ילדים, בן הזוג יורש מחצית מהעיזבון, ואת המחצית השנייה יורשים הילדים בחלקים שווים ביניהם.', 'הטעות הנפוצה היא להחיל את כללי הדין האישי (כמו איסור נישואי תערובת) על דיני הירושה, ובכך לשלול זכויות ירושה מבן זוג שנישא בנישואין אזרחיים תקפים בחו"ל.',
    '["חוק הירושה", "בן זוג", "נישואין אזרחיים", "הכרה בנישואין זרים", "דין אישי", "ירושה על פי דין", "בע\"מ 9607/03 פלוני נ'' פלונית"]'::jsonb, '**וריאציה 1 — נישואין אזרחיים בישראל:** האם נישואין אזרחיים שנערכו בישראל מוכרים לצורך ירושה? ← לא, ישראל אינה מכירה בנישואין אזרחיים שנערכו בשטחה, ולכן הם אינם מקנים מעמד של ''בן זוג'' לירושה.
**וריאציה 2 — ידועים בציבור:** מה הדין אם ניקול ושמעון היו ידועים בציבור? ← ייתכן שניקול הייתה יורשת, אם הוכיחה שהם חיו חיי משפחה וניהלו משק בית משותף, ובלבד שלא היה נשוי לאחר (סעיף 55 לחוק הירושה).
**וריאציה 3 — תכלית ההכרה:** מהי התכלית של הכרה בנישואין אזרחיים לצורך ירושה? ← להגן על זכויות בן הזוג שחי עם המנוח, ללא קשר לדת או למקום עריכת הנישואין, ובהתאם למגמה הכללית של הכרה בנישואין אזרחיים (בע"מ 9607/03 פלוני נ'' פלונית).', 'נישואין אזרחיים תקפים בחו"ל ← מוכרים לצורך ירושה ← בן הזוג יורש כרגיל (בע"מ 9607/03).', '["חוק הירושה, תשכ\"ה-1965, סעיף 11", "בע\"מ 9607/03 פלוני נ'' פלונית (2006)", "חוק הירושה, תשכ\"ה-1965, סעיף 55"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''marriage_divorce'' | classifier_note: Civil marriage abroad (Jew + Christian); inheritance complications | source_review_note: השאלה עוסקת בדיני ירושה ודיני משפחה, תחומים שאינם נכללים ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן, ניקול יורשת כבת זוג לכל דבר ועניין, ולפיכך היא יורשת מחצית והילדים כולם יחד יורשים מחצית.', true, 'תשובה זו נכונה. נישואין אזרחיים תקפים שנערכו בחו"ל מוכרים בישראל לצורך חוק הירושה, ועל כן ניקול נחשבת לבת זוגו של שמעון ויורשת על פי דין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'שאלה זו נותרה בצריך עיון בפסיקת בית המשפט העליון.', false, 'טענה זו שגויה. פסיקת בית המשפט העליון (בע"מ 9607/03 פלוני נ'' פלונית) הכריעה בסוגיה וקבעה כי נישואין אזרחיים תקפים שנערכו בחו"ל מוכרים לצורך חוק הירושה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לא. על פי הדין האישי של שמעון הנישואין לא תופסים, שכן מדובר בנישואין בין יהודי ללא יהודייה, ולכן ניקול לא יכולה להיחשב כבת זוג על פי חוק הירושה.', false, 'טענה זו שגויה. חוק הירושה הוא חוק אזרחי-חילוני, והמונח ''בן זוג'' בו מתפרש באופן עצמאי, ללא תלות בדין האישי של הצדדים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא. ניקול לא יכולה להיחשב כבת זוג לאור העובדה שהנישואין הם נישואין אזרחיים ולא התקיימו בארץ.', false, 'טענה זו שגויה. העובדה שהנישואין הם אזרחיים ונערכו בחו"ל אינה פוגעת בתוקפם לצורך חוק הירושה, כל עוד הם תקפים במקום עריכתם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ירושת ידועים בציבור',
    1, 'שמעון וניקול חיו יחד במשך 5 שנים כידועים בציבור, ניהלו משק בית משותף ולא היו נשואים לאחרים. שמעון נפטר ללא צוואה. בניו שואלים אם ניקול זכאית לירושה או חלקה. מה הדין לעניין ירושתה של ניקול?', 'שאלה זו בוחנת את זכות הירושה של ידועים בציבור על פי חוק הירושה, התשכ"ה-1965, ובפרט את התנאים המצטברים הנדרשים להכרה בהם כיורשים על פי דין, בהתאם לסעיף 55 לחוק.', 'סעיף 55 לחוק הירושה, התשכ"ה-1965, קובע כי ''איש ואשה שחיו חיי משפחה במשק בית משותף אך אינם נשואים זה לזה, ומת אחד מהם ובשעת מותו אף אחד מהם לא היה נשוי לאדם אחר, רואים את הנשאר בחיים כאילו היה בן זוגו של המת לענין ירושה''. במקרה זה, שמעון וניקול חיו יחד 5 שנים כידועים בציבור, ניהלו משק בית משותף ולא היו נשואים לאחרים. לכן, ניקול עומדת בתנאים הקבועים בסעיף 55 לחוק הירושה, והיא תירש את שמעון כאילו הייתה בת זוגו הנשואה, כלומר מחצית מהעיזבון, ואת המחצית השנייה יירשו הילדים (סעיף 11 לחוק הירושה).',
    'הטעות הנפוצה היא להניח כי רק בני זוג נשואים זכאים לירושה על פי דין, ולהתעלם מהוראת סעיף 55 לחוק הירושה המעניקה זכות זו גם לידועים בציבור.', '["ידועים בציבור", "חוק הירושה סעיף 55", "חיי משפחה", "משק בית משותף", "ירושה על פי דין", "בן זוג"]'::jsonb, '**וריאציה 1 — נשוי לאחר:** מה הדין אם שמעון היה נשוי לאישה אחרת בעת פטירתו? ← ניקול לא הייתה יורשת כידועה בציבור, שכן אחד התנאים בסעיף 55 הוא ש''אף אחד מהם לא היה נשוי לאדם אחר''.
**וריאציה 2 — נטל ההוכחה:** על מי מוטל נטל ההוכחה להיות ידוע בציבור? ← על הטוען לכך, במקרה זה ניקול, ועליה להוכיח את קיום חיי המשפחה ומשק הבית המשותף (ע"א 107/87 אלון נ'' מנדלסון).
**וריאציה 3 — תכלית סעיף 55:** מהי תכלית סעיף 55 לחוק הירושה? ← להגן על בן זוג שחי עם המנוח חיי משפחה וניהל עמו משק בית משותף, גם ללא נישואין פורמליים, מתוך הכרה במציאות החיים המשתנה (בג"ץ 10471/07 פלונית נ'' בית הדין הרבני הגדול).', 'ידוע בציבור יורש ← אם חי חיי משפחה וניהל משק בית משותף ← ולא היה נשוי לאחר (סעיף 55 לחוק הירושה).',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 55", "חוק הירושה, תשכ\"ה-1965, סעיף 11", "ע\"א 107/87 אלון נ'' מנדלסון, פ\"ד מג(1) 255 (1989)", "בג\"ץ 10471/07 פלונית נ'' בית הדין הרבני הגדול (20.07.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ניקול יורשת כבת זוג לכל דבר ועניין, אם הוכיחה שהם חיו חיי משפחה וניהלו משק בית משותף.', true, 'תשובה זו נכונה. סעיף 55 לחוק הירושה קובע כי ידוע בציבור יורש את המנוח כאילו היה בן זוגו, בתנאי שהוכיח כי חי עמו חיי משפחה וניהל עמו משק בית משותף, ובלבד שלא היה נשוי לאחר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ניקול אינה יורשת כלל, שכן לא היו נשואים.', false, 'טענה זו שגויה. חוק הירושה מכיר בזכות ירושה גם לידועים בציבור העומדים בתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ניקול יורשת רק אם שמעון הותיר צוואה לטובתה.', false, 'טענה זו שגויה. ידועים בציבור יורשים על פי דין, גם בהיעדר צוואה, אם עומדים בתנאי סעיף 55 לחוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ניקול יורשת רק אם הייתה אזרחית ישראלית.', false, 'טענה זו שגויה. אזרחות אינה תנאי לירושה כידועה בציבור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני ''בן זוג'' לעניין ירושה',
    2, 'מהם המבחנים העיקריים להכרה בבן זוג כיורש על פי חוק הירושה, בהיעדר צוואה?', 'שאלה זו מסכמת את המבחנים המשפטיים להכרה ב''בן זוג'' כיורש על פי חוק הירושה, תוך התייחסות למגוון סוגי הקשרים הזוגיים המוכרים על ידי הדין הישראלי לצורך זה.', 'המונח ''בן זוג'' בחוק הירושה, התשכ"ה-1965, מתפרש באופן רחב וכולל מספר קטגוריות: ראשית, בני זוג נשואים בנישואין דתיים תקפים, בין אם נערכו בישראל ובין אם בחו"ל. שנית, בני זוג שנישאו בנישואין אזרחיים תקפים בחו"ל, גם אם הדין האישי שלהם אינו מאפשר נישואין כאלה (כפי שנקבע בבע"מ 9607/03 פלוני נ'' פלונית). שלישית, ידועים בציבור, העומדים בתנאים המצטברים הקבועים בסעיף 55 לחוק הירושה: חיו חיי משפחה במשק בית משותף, ובשעת מות המנוח אף אחד מהם לא היה נשוי לאדם אחר. כל אחת מקטגוריות אלו מקנה זכות ירושה על פי דין.',
    'הטעות הנפוצה היא להגביל את ההכרה ב''בן זוג'' רק לבני זוג נשואים בנישואין דתיים, או לנישואין שנערכו בישראל, ובכך להתעלם מהתפתחות הפסיקה והחקיקה בתחום.', '["בן זוג", "חוק הירושה", "נישואין אזרחיים", "ידועים בציבור", "דין אישי", "הכרה בנישואין זרים", "סעיף 11 לחוק הירושה", "סעיף 55 לחוק הירושה"]'::jsonb, '**וריאציה 1 — נישואין פיקטיביים:** האם נישואין פיקטיביים יוכרו לצורך ירושה? ← לא, נדרש קיום כנה של קשר נישואין, ולא רק פורמלי (ע"א 207/68 מורד נ'' מורד).
**וריאציה 2 — פרידה לפני מוות:** מה הדין אם בני הזוג נפרדו לפני המוות? ← אם הנישואין לא הותרו, בן הזוג עדיין יורש, אלא אם הוכח שהם לא חיו יחד כבני זוג (ע"א 112/79 שרף נ'' שרף).
**וריאציה 3 — השפעת הדין האישי:** האם הדין האישי משפיע על הגדרת ''בן זוג'' לצורך ירושה? ← לא, לצורך חוק הירושה, ההגדרה היא אזרחית-חילונית, ואינה כפופה לדין האישי (בע"מ 9607/03 פלוני נ'' פלונית).', '''בן זוג'' לירושה ← נשואים (דתיים/אזרחיים תקפים מחו"ל) או ידועים בציבור (סעיפים 11 ו-55 לחוק הירושה).',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 11", "חוק הירושה, תשכ\"ה-1965, סעיף 55", "בע\"מ 9607/03 פלוני נ'' פלונית (2006)", "ע\"א 207/68 מורד נ'' מורד, פ\"ד כב(2) 142 (1968)", "ע\"א 112/79 שרף נ'' שרף, פ\"ד לד(2) 604 (1980)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קיום נישואין תקפים (דתיים או אזרחיים שנערכו בחו"ל) או עמידה בתנאי ידועים בציבור.', true, 'תשובה זו נכונה. חוק הירושה מכיר בשתי קטגוריות עיקריות של ''בן זוג'' לצורך ירושה על פי דין: בני זוג נשואים (בין בנישואין דתיים ובין בנישואין אזרחיים תקפים מחו"ל) וידועים בציבור העומדים בתנאי סעיף 55 לחוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיום נישואין דתיים בלבד.', false, 'טענה זו שגויה. חוק הירושה אינו מגביל את ההכרה בבן זוג לנישואין דתיים בלבד, אלא מכיר גם בנישואין אזרחיים תקפים ובידועים בציבור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'קיום נישואין שנערכו בישראל בלבד.', false, 'טענה זו שגויה. ישראל מכירה בנישואין אזרחיים תקפים שנערכו בחו"ל לצורך חוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קיום נישואין וכן אזרחות ישראלית.', false, 'טענה זו שגויה. אזרחות אינה תנאי להכרה בבן זוג כיורש על פי חוק הירושה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'נישואין אזרחיים ודין אישי',
    3, 'האם העובדה שעל פי הדין האישי של שמעון (יהודי) נישואיו לניקול (נוצרייה) אינם תקפים, משפיעה על זכותה לרשת אותו על פי חוק הירושה?', 'שאלה זו מתמקדת בהבחנה הקריטית בין הדין האישי לבין חוק הירושה, ומבהירה כי חוק הירושה הוא חוק אזרחי-חילוני המעניק הגדרה עצמאית למונח ''בן זוג'', שאינה מושפעת מהדין האישי של הצדדים, כפי שנקבע בפסיקת בית המשפט העליון.', 'פסיקת בית המשפט העליון, ובפרט בע"מ 9607/03 פלוני נ'' פלונית (2006), קבעה באופן מפורש כי לצורך חוק הירושה, המונח ''בן זוג'' מתפרש באופן אזרחי-חילוני, ואינו כפוף לדין האישי של הצדדים. כלומר, אם נישואין אזרחיים נערכו בחו"ל והם תקפים לפי דיני המקום שבו נערכו, הם יוכרו בישראל לצורך חוק הירושה, גם אם על פי הדין האישי של אחד הצדדים (כמו הדין העברי במקרה של נישואי יהודי ונוצרייה) הנישואין אינם תקפים. חוק הירושה נועד להסדיר את חלוקת העיזבון באופן אזרחי, ולכן הוא מתעלם מההגבלות של הדין האישי לעניין זה.',
    'הטעות הנפוצה היא להחיל את כללי הדין האישי (כמו איסור נישואי תערובת) על דיני הירושה, ובכך לשלול זכויות ירושה מבן זוג שנישא בנישואין אזרחיים תקפים בחו"ל.', '["דין אישי", "חוק הירושה", "נישואין אזרחיים", "הכרה בנישואין זרים", "בע\"מ 9607/03 פלוני נ'' פלונית", "הגדרה אזרחית-חילונית"]'::jsonb, '**וריאציה 1 — נישואין אזרחיים בישראל:** האם נישואין אזרחיים שנערכו בישראל מוכרים לצורך ירושה? ← לא, ישראל אינה מכירה בנישואין אזרחיים שנערכו בשטחה, ולכן הם אינם מקנים מעמד של ''בן זוג'' לירושה.
**וריאציה 2 — תעודת נישואין:** האם תעודת נישואין אזרחית מחו"ל מספיקה להוכחת מעמד ''בן זוג'' לירושה? ← כן, אם היא תקפה לפי דיני המקום שבו ניתנה, היא מהווה ראיה מספקת (ע"א 305/80 שילה נ'' רצקובסקי).
**וריאציה 3 — תכלית ההפרדה:** מהי התכלית של הפרדת דיני הירושה מהדין האישי בעניין זה? ← להבטיח שוויון, להגן על זכויות בן הזוג שחי עם המנוח, ולמנוע עיוותים הנובעים מהגבלות הדין האישי (בע"מ 9607/03 פלוני נ'' פלונית).', 'חוק הירושה ← הגדרת ''בן זוג'' עצמאית ← אינה כפופה לדין האישי (בע"מ 9607/03).',
    '["בע\"מ 9607/03 פלוני נ'' פלונית (2006)", "חוק הירושה, תשכ\"ה-1965", "ע\"א 305/80 שילה נ'' רצקובסקי, פ\"ד לה(3) 449 (1981)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, הדין האישי קובע את מעמד הנישואין, ולכן ניקול אינה נחשבת בת זוג.', false, 'טענה זו שגויה. חוק הירושה הוא חוק אזרחי-חילוני, והמונח ''בן זוג'' בו מתפרש באופן עצמאי, ללא תלות בדין האישי של הצדדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חוק הירושה קובע הגדרה עצמאית ל"בן זוג" שאינה כפופה לדין האישי.', true, 'תשובה זו נכונה. פסיקת בית המשפט העליון (בע"מ 9607/03 פלוני נ'' פלונית) קבעה כי לצורך חוק הירושה, המונח ''בן זוג'' מתפרש באופן אזרחי-חילוני, ואינו כפוף לדין האישי של הצדדים, כל עוד הנישואין תקפים במקום עריכתם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם הנישואין אושרו על ידי בית דין רבני.', false, 'טענה זו שגויה. אישור בית דין רבני אינו רלוונטי לתוקפם של נישואין אזרחיים שנערכו בחו"ל לצורך חוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם הנישואין נערכו במדינה שבה הדין האישי אינו רלוונטי.', false, 'טענה זו שגויה. תוקף הנישואין נקבע לפי דיני המקום שבו נערכו, ולא לפי רלוונטיות הדין האישי באותה מדינה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הגשת התנגדות לצו ירושה',
    4, 'בניו של שמעון מעוניינים למנוע מניקול לרשת את אביהם. איזה הליך משפטי עליהם לנקוט, ומהו המועד לכך?', 'שאלה זו בוחנת את ההליך הפרוצדורלי הנכון לערעור על זכות ירושה, ובפרט את הליך הגשת התנגדות לבקשה למתן צו ירושה, ואת הסמכות העניינית לדון בכך.', 'כאשר מוגשת בקשה למתן צו ירושה לרשם לענייני ירושה (או לבית הדין הרבני, אם הוגשה שם), כל אדם המעוניין לערער על תוכנה או על זכותו של מי מהמבקשים או היורשים, רשאי להגיש התנגדות לבקשה. ההתנגדות צריכה להיות מוגשת בכתב, בצירוף תצהיר, בתוך המועד הקבוע בחוק (14 יום מיום פרסום הבקשה ברשומות, או מיום שנודע למתנגד על הבקשה, לפי המאוחר). במקרה זה, בניו של שמעון צריכים להגיש התנגדות לבקשה למתן צו ירושה, בטענה שניקול אינה עונה על הגדרת ''בן זוג'' לצורך חוק הירושה (טענה שתידחה לאור הפסיקה). הסמכות העניינית לדון בהתנגדות נתונה לבית המשפט לענייני משפחה (סעיף 6 לחוק בית המשפט לענייני משפחה, התשנ"ה-1995).',
    'הטעות הנפוצה היא לנקוט בהליכים משפטיים שאינם רלוונטיים או שאינם בסמכות בית המשפט המתאים, במקום בהליך הספציפי הקבוע בחוק הירושה לערעור על זכות ירושה.', '["צו ירושה", "התנגדות לצו ירושה", "רשם הירושה", "בית המשפט לענייני משפחה", "סמכות עניינית", "חוק הירושה", "הליך פרוצדורלי"]'::jsonb, '**וריאציה 1 — מועד הגשת התנגדות:** מהו המועד להגשת התנגדות לצו ירושה? ← 14 יום מיום פרסום הבקשה ברשומות, או מיום שנודע למתנגד על הבקשה, לפי המאוחר (תקנה 14 לתקנות הירושה).
**וריאציה 2 — סמכות בית הדין הרבני:** האם בית הדין הרבני מוסמך לדון בהתנגדות לצו ירושה? ← כן, אם כל היורשים הסכימו בכתב להעביר את הדיון אליו (סעיף 155 לחוק הירושה).
**וריאציה 3 — תוצאות קבלת התנגדות:** מה קורה אם ההתנגדות מתקבלת? ← צו הירושה לא יינתן כפי שהתבקש, ובית המשפט יכריע מי הם היורשים ומה חלקם (סעיף 67 לחוק הירושה).', 'ערעור על זכות ירושה ← הגשת התנגדות לבקשה לצו ירושה ← לבית המשפט לענייני משפחה (סעיף 6 לחוק ביהמ"ש לענייני משפחה).',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 67", "חוק הירושה, תשכ\"ה-1965, סעיף 155", "חוק בית המשפט לענייני משפחה, תשנ\"ה-1995, סעיף 6", "תקנות הירושה, תשנ\"ח-1998, תקנה 14"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'עליהם להגיש תביעה לבית המשפט לענייני משפחה לביטול הנישואין האזרחיים.', false, 'טענה זו שגויה. בית המשפט לענייני משפחה אינו מוסמך לבטל נישואין אזרחיים שנערכו בחו"ל, והליך זה אינו הדרך הנכונה למנוע ירושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'עליהם להגיש התנגדות לבקשה למתן צו ירושה, בטענה שניקול אינה ''בת זוג'' על פי חוק הירושה.', true, 'תשובה זו נכונה. הדרך הנכונה לערער על זכות ירושה של אדם היא באמצעות הגשת התנגדות לבקשה למתן צו ירושה, בטענה שהמבקש אינו יורש על פי דין או צוואה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'עליהם להגיש תביעה לבית הדין הרבני לקביעת מעמדה האישי של ניקול.', false, 'טענה זו שגויה. לבית הדין הרבני אין סמכות לדון במעמדה האישי של ניקול (נוצרייה), וגם אם הייתה לו, זה לא היה משפיע על זכותה לירושה על פי חוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'עליהם להגיש תביעה לבית המשפט המחוזי להצהיר על בטלות הנישואין.', false, 'טענה זו שגויה. הסמכות לדון בתביעות הצהרתיות בענייני מעמד אישי נתונה לבית המשפט לענייני משפחה, אך הליך זה אינו הדרך הנכונה למנוע ירושה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 29, '2019-S-S-Q29';
END
$$;

