-- classifier_note: Yaakov-Esav lentil-stew sale — basic contract of sale
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b9754fa7-04db-4e36-a4c8-8a6372d6f592'::uuid;
  v_group_id uuid := '51c178b8-652f-434a-98d7-e5ae970f73ab'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '10f97e03-d72c-4de2-bd9c-4b22561df282'::uuid;
  v_ang_1 uuid := '73dab8d7-35e4-4f08-bebf-9e5c0f9ec0e1'::uuid;
  v_ang_2 uuid := '8e6935b5-c175-4f8a-aa10-af5bebdaad54'::uuid;
  v_ang_3 uuid := '702eb051-b36d-4250-9075-70b159d7e6d5'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q30';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 30, '2019-S-S-Q30';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sale' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sale', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q30', v_chapter_id, v_subtopic_id, 'יעקב מכר לעשו נזיד עדשים. למרות שעשו היה רעב מאוד סוכם שנזיד עדשים יסופק לעשו בתוך שבועיים ממועד ההסכמה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 30}'::jsonb, 'השאלה עוסקת במועד מסירת ממכר כאשר הצדדים הסכימו על תקופת מסירה, ובפרט בוחנת את סמכות המוכר לקבוע את המועד המדויק בתוך התקופה, ואת חובתו להודיע על כך לקונה זמן סביר מראש, בהתאם לסעיף 9 לחוק המכר, תשכ"ח-1968.', 'סעיף 9 לחוק המכר, תשכ"ח-1968, דן במועד המסירה. סעיף 9(ב) קובע כי ''הוסכם על מסירה תוך תקופה פלונית, רשאי המוכר לקבוע את מועד המסירה בתוך אותה תקופה''. כלומר, כאשר הצדדים קבעו טווח זמנים למסירה, המוכר הוא זה שקובע את המועד המדויק בתוך הטווח הזה. אולם, סעיף 9(ג) לחוק מוסיף חובה חשובה: ''במקרים האמורים בסעיפים קטנים (א) ו-(ב), על המוכר להודיע לקונה זמן סביר מראש על מועד המסירה''. חובה זו נועדה לאפשר לקונה להיערך לקבלת הממכר. לכן, במקרה של יעקב ועשו, יעקב רשאי לבחור כל מועד בתוך השבועיים למסירת נזיד העדשים, אך עליו להודיע לעשו על המועד הנבחר זמן סביר מראש. סעיף 9(ב) לחוק המכר | מועד המסירה', 'הטעות הנפוצה היא להתעלם מחובת המוכר למתן הודעה מוקדמת לקונה על מועד המסירה, גם כאשר הוסכם על תקופת מסירה.',
    '["מועד מסירה", "חוק המכר סעיף 9", "הודעה מוקדמת", "תקופת מסירה", "זמן סביר", "חיובים חוזיים"]'::jsonb, '**וריאציה 1 — מועד משוער:** מה הדין אם סוכם על ''מועד מסירה משוער''? ← הסכמה על מועד משוער דוחה את תחולת כלל ''הזמן הסביר'' שבסעיף 9(א), אך המוכר עדיין חייב להודיע לקונה זמן סביר מראש על המועד המדויק (איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א, סעיף 9, עמ'' 15).
**וריאציה 2 — חובת קבלה:** האם הקונה חייב לקבל את הממכר במועד שנקבע על ידי המוכר? ← כן, חובת המוכר למסור את הממכר וחובת הקונה לשלם את מחירו הם חיובים מקבילים שיש לקיימם בד בבד (סעיף 23 לחוק המכר).
**וריאציה 3 — איחור במסירה:** מה קורה אם המוכר לא עומד במועד המסירה שקבע? ← איחור במסירה מהווה הפרת חוזה, המזכה את הקונה בסעדים הקבועים בחוק החוזים (תרופות בשל הפרת חוזה), אלא אם כן הוסכם אחרת כדין (חוק המכר (דירות) סעיף 5א).', 'הוסכם על מסירה תוך תקופה ← המוכר קובע מועד מדויק בתוכה ← חייב להודיע לקונה זמן סביר מראש (סעיף 9(ב) ו-(ג) לחוק המכר).', '["חוק המכר, תשכ\"ח-1968, סעיף 9(ב)", "חוק המכר, תשכ\"ח-1968, סעיף 9(ג)", "חוק המכר, תשכ\"ח-1968, סעיף 23", "איל זמיר חוק המכר - פירוש לחוקי החוזים - כרך א (2023) | סעיף 9. מועד המסירה", "חוק המכר (דירות), תשל\"ג-1973, סעיף 5א"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''sale'' | classifier_note: Yaakov-Esav lentil-stew sale — basic contract of sale | source_review_note: השאלה עוסקת בדיני חוזים (מכר), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יעקב רשאי לספק את הנזיד לעשו בכל מועד שיבחר בתוך השבועיים האמורים, ובלבד שיודיע לעשו זמן סביר מראש על מועד המסירה.', true, 'תשובה זו נכונה. כאשר הוסכם על מסירה תוך תקופה פלונית, המוכר רשאי לקבוע את מועד המסירה בתוך אותה תקופה, ובלבד שיודיע לקונה זמן סביר מראש על מועד המסירה, בהתאם לסעיף 9(ב) ו-(ג) לחוק המכר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יעקב רשאי לספק את הנזיד לעשו בכל מועד שיבחר בתוך השבועיים האמורים.', false, 'טענה זו שגויה. אף שהמוכר רשאי לקבוע את המועד בתוך התקופה המוסכמת, הוא חייב להודיע לקונה זמן סביר מראש על מועד המסירה, בהתאם לסעיף 9(ג) לחוק המכר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות אלה יעקב רשאי לספק את הנזיד לעשו במהלך השבועיים האמורים, אך עשו הוא שיקבע את המועד המדויק לקבלו.', false, 'טענה זו שגויה. כאשר הוסכם על מסירה תוך תקופה פלונית, הזכות לקבוע את המועד המדויק נתונה למוכר, ולא לקונה, בהתאם לסעיף 9(ב) לחוק המכר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות אלה על יעקב להיות מוכן לספק נזיד עדשים לעשו בכל מועד שבו עשו יבוא למקום העסק של יעקב על מנת לאסוף את נזיד העדשים, וזאת בתוך 48 שעות ממועד גיבוש העסקה ובמהלך יתרת השבועיים האמורים.', false, 'טענה זו שגויה. אין בחוק המכר הוראה הקובעת כי הקונה רשאי לקבוע את מועד המסירה באופן חד-צדדי בתוך התקופה המוסכמת, ואין דרישה לזמינות תוך 48 שעות במקרה זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מועד מסירה שלא הוסכם',
    1, 'יעקב מכר לעשו נזיד עדשים. הצדדים לא סיכמו כלל על מועד למסירת הנזיד. מה הדין לעניין מועד המסירה?', 'שאלה זו בוחנת את ברירת המחדל הקבועה בחוק המכר לעניין מועד המסירה, כאשר הצדדים לא קבעו מועד מפורש בחוזה, ואת זהות הצד המוסמך לקבוע את המועד המדויק, בהתאם לסעיף 9(א) ו-(ג) לחוק המכר.', 'סעיף 9(א) לחוק המכר, תשכ"ח-1968, קובע כי ''מקום שהממכר לא נמסר על אתר, תהא המסירה זמן סביר לאחר גמירת החוזה''. כלומר, בהיעדר הסכמה מפורשת על מועד המסירה, החוק משלים את החסר וקובע כי המסירה תתבצע תוך זמן סביר. סעיף 9(ג) לחוק מוסיף כי ''במקרים האמורים בסעיפים קטנים (א) ו-(ב), על המוכר להודיע לקונה זמן סביר מראש על מועד המסירה''. מכאן עולה כי הזכות לקבוע את המועד המדויק בתוך ''הזמן הסביר'' נתונה למוכר, וזאת בכפוף למתן הודעה מוקדמת לקונה. מבחן ''הזמן הסביר'' הוא אובייקטיבי ומתחשב בנסיבות העניין, לרבות טיב הממכר ומיהות הצדדים. איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 9 - מועד המסירה',
    'הטעות הנפוצה היא לחשוב שבהיעדר מועד מסירה מפורש, החוזה בטל מחוסר מסוימות, או שהקונה הוא הקובע את מועד המסירה.', '["מועד מסירה", "זמן סביר", "חוק המכר סעיף 9", "השלמת חוזה", "מסוימות", "הודעה מוקדמת"]'::jsonb, '**וריאציה 1 — טיב הממכר:** האם ''זמן סביר'' למסירת נזיד עדשים זהה ל''זמן סביר'' למסירת מכונית? ← לא, ''הזמן הסביר'' תלוי בטיב הממכר ובמצבו בעת גמירת החוזה (ע"א 565/79 רובינשטיין ושות'', חברה קבלנית בע"מ נ'' מולי לויס).
**וריאציה 2 — חובת הודעה:** האם המוכר חייב להודיע על מועד המסירה גם אם הקונה יודע שהממכר מוכן? ← כן, חובת ההודעה היא מרכיב הכרחי של חיוב המסירה, וכל עוד לא נמסרה, אין לראות את המוכר כמי שהעמיד את הממכר לרשות הקונה (איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א, סעיף 9, עמ'' 11).
**וריאציה 3 — השלמה מכוח חוק החוזים:** האם סעיף 41 לחוק החוזים (חלק כללי) חל במקרה זה? ← סעיף 9 לחוק המכר הוא הוראה ספציפית הגוברת על סעיף 41 לחוק החוזים הכללי, שכן הוא קובע שהמוכר (החייב) הוא הקובע את המועד, בניגוד לסעיף 41 המעניק את הזכות לנושה (איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א, סעיף 9, עמ'' 3).', 'אין מועד מסירה מוסכם ← מסירה ''זמן סביר'' לאחר החוזה ← המוכר קובע את המועד המדויק בהודעה מראש (סעיף 9(א) ו-(ג) לחוק המכר).',
    '["חוק המכר, תשכ\"ח-1968, סעיף 9(א)", "חוק המכר, תשכ\"ח-1968, סעיף 9(ג)", "ע\"א 565/79 רובינשטיין ושות'', חברה קבלנית בע\"מ נ'' מולי לויס (18.08.1980)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 9 - מועד המסירה", "איל זמיר חוק המכר - פירוש לחוקי החוזים - כרך א (2023) | סעיף 9. מועד המסירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'המסירה תהא זמן סביר לאחר גמירת החוזה, ויעקב רשאי לקבוע את המועד המדויק, ובלבד שיודיע לעשו זמן סביר מראש.', true, 'תשובה זו נכונה. סעיף 9(א) לחוק המכר קובע כי מקום שהממכר לא נמסר על אתר, תהא המסירה זמן סביר לאחר גמירת החוזה. סעיף 9(ג) קובע כי על המוכר להודיע לקונה זמן סביר מראש על מועד המסירה. הזכות לקבוע את המועד המדויק נתונה למוכר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'המסירה תהא זמן סביר לאחר גמירת החוזה, ועשו הוא שיקבע את המועד המדויק, ובלבד שיודיע ליעקב זמן סביר מראש.', false, 'טענה זו שגויה. אף שהמסירה תהא זמן סביר, הזכות לקבוע את המועד המדויק נתונה למוכר, ולא לקונה, בהתאם לסעיף 9(א) ו-(ג) לחוק המכר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'החוזה בטל מחוסר מסוימות, שכן לא נקבע בו מועד מסירה.', false, 'טענה זו שגויה. חוק המכר משלים את הפרט החסר של מועד המסירה באמצעות הוראת סעיף 9(א), ולכן החוזה אינו בטל מחוסר מסוימות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'המסירה תהא מיד עם גמירת החוזה, שכן לא הוסכם אחרת.', false, 'טענה זו שגויה. ''על אתר'' (מיד) היא אפשרות, אך אם לא נמסר מיד, ברירת המחדל היא ''זמן סביר'' ולא ''מיד'', בהתאם לסעיף 9(א) לחוק המכר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תניית פטור ממועד מסירה בדירת מגורים',
    2, 'קונה רכש דירת מגורים מקבלן. בחוזה המכר נקבע כי מועד המסירה יהיה ''בתוך 36 חודשים ממועד קבלת היתר הבנייה או ממועד השלמת קומות המסחר בפרויקט, לפי המאוחר''. האם תניה זו תקפה?', 'שאלה זו עוסקת בתוקפן של תניות בחוזי מכר דירות המעניקות למוכר גמישות רבה בקביעת מועד המסירה, ובפרט בוחנת את המושג ''תניית פטור'' אסורה, בהתאם לחוק המכר (דירות) ולהלכת שמש של בית המשפט העליון.', 'חוק המכר (דירות), התשל"ג-1973, נועד להגן על רוכשי דירות, הנחשבים לצד חלש בעסקה. סעיף 7א(א) לחוק קובע כי ''אין להתנות על הוראות חוק זה, אלא לטובת הקונה או קונה המשנה''. פסיקת בתי המשפט, ובמיוחד הלכת שמש (רע"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע"מ), קבעה כי תניות בחוזי מכר דירות המקנות למוכר כוח בלתי מוגבל לדחות את מועד המסירה, או שאינן קובעות מועד ברור וקצוב, נחשבות ל''תניית פטור'' אסורה ובטלה. תניה כזו מותירה את הקונה באי-ודאות מכבידה ומונעת ממנו היערכות לקראת קבלת הדירה. במקרה הנדון, התניה ''בתוך 36 חודשים ממועד קבלת היתר הבנייה או ממועד השלמת קומות המסחר בפרויקט, לפי המאוחר'' אינה קובעת מועד קצוב וברור, אלא מותירה את מועד המסירה נתון לשליטתו הבלעדית של הקבלן, ולכן היא בטלה. ת"א (שלום ת"א) 42648-04-18 יורי אוסטייב נ'' קבוצת אהרוני (מ.א) יזום והשקעות בע"מ (17.04.2023)',
    'הטעות הנפוצה היא להתייחס לחוזה מכר דירה כאל חוזה רגיל, ולהתעלם מההגנות המיוחדות הקבועות בחוק המכר (דירות) ובפסיקה לטובת רוכשי דירות.', '["חוק המכר (דירות)", "תניית פטור", "מועד מסירה", "הלכת שמש", "חוזים אחידים", "קוגנטיות"]'::jsonb, '**וריאציה 1 — מועד מסירה משוער:** האם תניה הקובעת מועד מסירה ''משוער'' היא תניית פטור אסורה? ← לא בהכרח, אך היא עלולה להיחשב מקפחת לפי חוק החוזים האחידים אם היא מותירה אי-ודאות רבה (ע"א 449/85 היועץ המשפטי לממשלה נ'' גד חברה לבניין בע"מ).
**וריאציה 2 — דחייה מוסכמת:** האם הצדדים יכולים להסכים על דחיית מועד המסירה? ← כן, אך הסכמה זו צריכה להיות קצובה וברורה, ולא תניית פטור ''המתחפשת'' להסכמה (רע"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע"מ).
**וריאציה 3 — שינויים בדירה:** האם בקשת שינויים בדירה מצד הקונה יכולה להצדיק דחייה במועד המסירה? ← כן, אך רק אם הדחייה קצובה וסבירה ביחס לשינויים, ולא תניית פטור גורפת (רע"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע"מ).', 'תניית פטור בחוזה מכר דירה ← המותירה למוכר שליטה מוחלטת על מועד המסירה ← בטלה (הלכת שמש, חוק המכר (דירות) סעיף 7א(א)).',
    '["חוק המכר (דירות), תשל\"ג-1973, סעיף 5א", "חוק המכר (דירות), תשל\"ג-1973, סעיף 7א(א)", "רע\"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע\"מ (21.02.2016)", "ע\"א 449/85 היועץ המשפטי לממשלה נ'' גד חברה לבניין בע\"מ (27.03.1989)", "ת\"א (שלום ת\"א) 42648-04-18 יורי אוסטייב נ'' קבוצת אהרוני (מ.א) יזום והשקעות בע\"מ (17.04.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, הצדדים חופשיים לקבוע את מועד המסירה כרצונם, ובלבד שהמועד ברור וניתן לחישוב.', false, 'טענה זו שגויה. בעסקאות מכר דירות, חופש החוזים מוגבל על ידי חוק המכר (דירות) והלכות תניות פטור, במיוחד כאשר התניה מותירה למוכר שליטה מוחלטת על מועד המסירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, זוהי ''תניית פטור'' אסורה המנוגדת לחוק המכר (דירות) ולכן בטלה, שכן היא מותירה למוכר שליטה מוחלטת על מועד המסירה.', true, 'תשובה זו נכונה. תניה המותירה למוכר שליטה מוחלטת על מועד המסירה, שאינו קצוב בזמן ונתון לשיקול דעתו הבלעדי, נחשבת ל''תניית פטור'' אסורה ובטלה, שכן היא עומדת בסתירה להוראות חוק המכר (דירות) והלכת שמש. ת"א (שלום ת"א) 42648-04-18 יורי אוסטייב נ'' קבוצת אהרוני (מ.א) יזום והשקעות בע"מ (17.04.2023)', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם הקונה הסכים לתניה זו במפורש ובכתב, לאחר שהוסברו לו השלכותיה.', false, 'טענה זו שגויה. גם הסכמה מפורשת של הקונה לא תכשיר תניית פטור אסורה, שכן הוראות חוק המכר (דירות) הן קוגנטיות ולא ניתן להתנות עליהן אלא לטובת הקונה (סעיף 7א(א) לחוק המכר (דירות)).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן הקבלן יוכיח שהעיכוב נגרם מנסיבות שאינן בשליטתו.', false, 'טענה זו שגויה. סעיף 5א(ג) לחוק המכר (דירות) מאפשר הסכמה על איחור ללא פיצוי בנסיבות שאינן בשליטת המוכר, אך אינו מכשיר תניה המעניקה למוכר שליטה מוחלטת על מועד המסירה מלכתחילה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הקדמת מועד מסירה',
    3, 'יעקב מכר לעשו נזיד עדשים. סוכם שנזיד העדשים יסופק לעשו בתוך שבועיים ממועד ההסכמה. יעקב מעוניין לספק את הנזיד לעשו כבר ביום למחרת ההסכמה. האם יעקב רשאי להקדים את מועד המסירה?', 'שאלה זו בוחנת את האפשרות של מוכר להקדים את מועד מסירת הממכר, כאשר הוסכם על תקופת מסירה, ואת התנאים לכך, בהתאם לסעיף 42 לחוק החוזים (חלק כללי) וסעיף 9 לחוק המכר.', 'סעיף 42 לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''חיוב יכול שיקוים לפני מועדו, ובלבד שהודיע החייב לנושה על כך זמן סביר מראש והדבר לא יפגע בנושה''. עקרון דומה מופיע גם בסעיף 9 לחוק המכר, תשכ"ח-1968, הקובע כי כאשר נקבע מועד למסירה, רשאי המוכר להקדים את המסירה בתנאי שיודיע על כך לקונה זמן סביר מראש ובתנאי שההקדמה לא תפגע בקונה. תכלית הסעיף היא לאפשר לחייב (המוכר) לוותר על יתרונו ולקיים את החיוב מוקדם יותר, כל עוד אין בכך פגיעה בנושה (הקונה). במקרה זה, יעקב רשאי להקדים את מסירת נזיד העדשים, ובלבד שיודיע לעשו זמן סביר מראש ויוודא שהקדמה זו אינה גורמת לעשו נזק או אי-נוחות בלתי סבירה. ת"ק (תביעות קטנות ת"א) 34224-02-24 איתן גרשון נ'' שופרסל בע"מ (04.08.2024)',
    'הטעות הנפוצה היא לחשוב שמועד קיום חיוב הוא קשיח ואינו ניתן לשינוי על ידי החייב, או להתעלם מהתנאים המצטברים להקדמת קיום חיוב.', '["הקדמת קיום חיוב", "חוק החוזים סעיף 42", "חוק המכר סעיף 9", "הודעה מוקדמת", "פגיעה בנושה", "חופש החוזים"]'::jsonb, '**וריאציה 1 — פגיעה בקונה:** מהי דוגמה לפגיעה בקונה שתמנע הקדמת מסירה? ← אם הקונה אינו יכול לקבל את הממכר במועד המוקדם, למשל, אם הוא נמצא בחו"ל או שאין לו מקום אחסון מתאים (איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א, סעיף 9, עמ'' 15).
**וריאציה 2 — הקדמת תשלום:** האם מוכר שהקדים את מועד המסירה זכאי להקדמה מקבילה של מועד התשלום? ← לא, מוכר שהקדים את מועד המסירה איננו זכאי להקדמה מקבילה של מועד התשלום (איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו, הפירוש הקצר לחוקים במשפט הפרטי, סעיף 9, עמ'' 22).
**וריאציה 3 — תום לב:** האם הקדמת המסירה צריכה להיעשות בתום לב? ← כן, כל קיום חיוב חוזי, לרבות הקדמתו, כפוף לעקרון תום הלב הקבוע בסעיף 39 לחוק החוזים (חלק כללי) (ת"ק (תביעות קטנות ת"א) 34224-02-24 איתן גרשון נ'' שופרסל בע"מ).', 'הקדמת מסירה ← מותרת למוכר ← בתנאי הודעה מראש ואי פגיעה בקונה (סעיף 42 לחוק החוזים, סעיף 9 לחוק המכר).',
    '["חוק המכר, תשכ\"ח-1968, סעיף 9", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 42", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 39", "ת\"ק (תביעות קטנות ת\"א) 34224-02-24 איתן גרשון נ'' שופרסל בע\"מ (04.08.2024)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 9 - מועד המסירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, יעקב רשאי להקדים את מועד המסירה, ובלבד שיודיע לעשו זמן סביר מראש ושההקדמה לא תפגע בעשו.', true, 'תשובה זו נכונה. סעיף 42 לחוק החוזים (חלק כללי) וסעיף 9 לחוק המכר מאפשרים לחייב (המוכר) להקדים את מועד קיום החיוב, ובלבד שיודיע לנושה (הקונה) זמן סביר מראש ושההקדמה לא תפגע בנושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, יעקב אינו רשאי להקדים את מועד המסירה, שכן המועד נקבע לטובת שני הצדדים.', false, 'טענה זו שגויה. ככלל, המועד נקבע לטובת החייב, והוא רשאי לוותר על יתרונו ולהקדים את הקיום, בכפוף לתנאים הקבועים בחוק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, יעקב רשאי להקדים את מועד המסירה ללא כל תנאי, שכן הוא המוכר.', false, 'טענה זו שגויה. הקדמת מועד המסירה כפופה לתנאים של מתן הודעה מראש ואי פגיעה בקונה, בהתאם לסעיף 42 לחוק החוזים (חלק כללי) וסעיף 9 לחוק המכר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עשו יסכים במפורש להקדמת המסירה.', false, 'טענה זו שגויה. הסכמת הקונה אינה תנאי הכרחי להקדמת המסירה, אלא אי פגיעה בו היא התנאי המרכזי, בנוסף למתן הודעה מראש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלמת פרטים חסרים בחוזה מכר מקרקעין',
    4, 'ראובן ושמעון חתמו על זיכרון דברים למכירת דירה. בזיכרון הדברים צוינו הצדדים, מהות הנכס והמחיר, אך לא נקבעו מועדי תשלום התמורה ומועד מסירת החזקה. האם זיכרון דברים זה תקף ומחייב?', 'שאלה זו עוסקת בדרישת המסוימות בחוזי מכר מקרקעין, ובאפשרות להשלים פרטים חסרים בזיכרון דברים באמצעות הוראות חוק המכר וחוק החוזים, ובכך להכיר בתוקפו המחייב של זיכרון הדברים, בהתאם לפסיקת בית המשפט העליון.', 'זיכרון דברים למכר מקרקעין צריך לעמוד בדרישת הכתב המהותית הקבועה בסעיף 8 לחוק המקרקעין, התשכ"ט-1969, וכן בדרישת המסוימות. דרישת המסוימות מחייבת קיומם של פרטים מהותיים כגון שמות הצדדים, מהות הנכס, המחיר ומועדי תשלום ומסירה. אולם, הפסיקה קבעה כי ניתן להשלים פרטים חסרים שאינם ''גרעין העסקה'' באמצעות הוראות חוק או נוהג. מועדי תשלום ומסירה נחשבים לפרטים הניתנים להשלמה. סעיף 21 לחוק המכר, תשכ"ח-1968, קובע כי ''המחיר ישולם במועד מסירת הממכר'', וסעיף 9(א) לחוק קובע כי ''מקום שהממכר לא נמסר על אתר, תהא המסירה זמן סביר לאחר גמירת החוזה''. בנוסף, סעיף 41 לחוק החוזים (חלק כללי) קובע כי ''חיוב שלא הוסכם על מועד קיומו, יש לקיים זמן סביר לאחר כריתת החוזה''. שילוב הוראות אלו מאפשר להשלים את הפרטים החסרים ולהכיר בתוקפו המחייב של זיכרון הדברים, כפי שנקבע בפסיקה (למשל, ע"א 235/75 קאדרי נ'' מסדר האחיות צ''רלס הקדוש, ע"א 3102/95 כהן נ'' כהן). ה"פ (מחוזי מרכז) 1005-06-10 אלשב חברה לבנין ולהשקעות בע"מ נ'' מוריס צדוק (11.09.2012)',
    'הטעות הנפוצה היא לחשוב שכל פרט חסר בזיכרון דברים מקרקעין מוביל לבטלותו, ולהתעלם ממנגנוני ההשלמה הקבועים בחוק ובפסיקה.', '["זיכרון דברים", "מסוימות", "דרישת הכתב", "השלמת חוזה", "חוק המכר סעיף 9", "חוק המכר סעיף 21", "חוק החוזים סעיף 41"]'::jsonb, '**וריאציה 1 — גרעין העסקה:** אילו פרטים נחשבים ל''גרעין העסקה'' ואינם ניתנים להשלמה? ← שמות הצדדים, מהות הנכס, המחיר (ע"א 235/75 חסן ערפאת קאדרי נ'' מסדר האחיות צ''רלס הקדוש).
**וריאציה 2 — כוונת הצדדים:** האם כוונת הצדדים משפיעה על השלמת הפרטים? ← כן, אם ניתן ללמוד מזיכרון הדברים על גמירות דעת להתקשר בחוזה מחייב, בית המשפט ייטה להשלים את הפרטים החסרים (ע"א 3102/95 יגאל כהן נ'' שמואל כהן).
**וריאציה 3 — סעדים בגין הפרה:** מה הדין אם זיכרון הדברים אינו מתייחס לסעדים בגין הפרה? ← בהיעדר הסדר ייחודי, יחול חוק החוזים (תרופות בשל הפרת חוזה), התש"ל-1970, ולא נדרשת כל השלמה (ת"א (מחוזי מרכז) 13216-05-22 אלמוג גנון נ'' יוסף עזריאל).', 'זיכרון דברים מקרקעין ← חסרים מועדי תשלום ומסירה ← ניתן להשלים מכוח חוק המכר וחוק החוזים ← תקף ומחייב (ע"א 235/75 קאדרי, ע"א 3102/95 כהן).',
    '["חוק המכר, תשכ\"ח-1968, סעיף 9", "חוק המכר, תשכ\"ח-1968, סעיף 21", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 41", "ע\"א 235/75 חסן ערפאת קאדרי נ'' מסדר האחיות צ''רלס הקדוש (03.03.1976)", "ע\"א 3102/95 יגאל כהן נ'' שמואל כהן (20.05.1996)", "ה\"פ (מחוזי מרכז) 1005-06-10 אלשב חברה לבנין ולהשקעות בע\"מ נ'' מוריס צדוק (11.09.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, זיכרון הדברים אינו תקף, שכן חסרים בו פרטים מהותיים וחיוניים לעסקת מכר מקרקעין.', false, 'טענה זו שגויה. אף שמועדי תשלום ומסירה הם פרטים חשובים, הם ניתנים להשלמה מכוח חוק או נוהג, ולכן אינם פוגעים בתוקף זיכרון הדברים אם שאר הפרטים המהותיים קיימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, זיכרון הדברים תקף ומחייב, שכן ניתן להשלים את הפרטים החסרים מכוח הוראות חוק המכר וחוק החוזים.', true, 'תשובה זו נכונה. הפסיקה קבעה כי ניתן להשלים פרטים חסרים בזיכרון דברים, כגון מועדי תשלום ומסירה, באמצעות הוראות חוק המכר (סעיפים 9 ו-21) וחוק החוזים (סעיף 41), הקובעים קיום ''זמן סביר'' בהיעדר הסכמה. ה"פ (מחוזי מרכז) 1005-06-10 אלשב חברה לבנין ולהשקעות בע"מ נ'' מוריס צדוק (11.09.2012)', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם הצדדים יסכימו על הפרטים החסרים בדיעבד.', false, 'טענה זו שגויה. הסכמה בדיעבד אינה הכרחית, שכן החוק מספק מנגנוני השלמה לפרטים אלו, המאפשרים אכיפת החוזה גם ללא הסכמה נוספת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן זיכרון הדברים נחתם על ידי עורך דין.', false, 'טענה זו שגויה. חתימת עורך דין אינה תנאי לתוקפו של זיכרון דברים, אלא עמידה בדרישות המסוימות והכתב.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 30, '2019-S-S-Q30';
END
$$;

-- ============================================================
-- Q31 — 2019-S-S-Q31 — chapter=contracts subtopic=sale
-- classifier_note: Used-car dealer sold encumbered car — buyer's protection (תקנת השוק)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '13a7306f-00a2-42c1-8e3f-73343d66ec80'::uuid;
  v_group_id uuid := '02ebd0d3-3ecf-4faf-8739-b5c8fea277da'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'd9ffbacd-49ff-4db3-ad56-575f1c1a60f5'::uuid;
  v_ang_1 uuid := 'd9b15fbb-663a-4007-b800-54fa9e2dcb04'::uuid;
  v_ang_2 uuid := '9e8f3232-906c-4d61-93f4-ebc109ac0c16'::uuid;
  v_ang_3 uuid := 'ea315eba-0409-4c44-af6a-a42180c96bfe'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 31, '2019-S-S-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sale' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sale', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q31', v_chapter_id, v_subtopic_id, 'פזית היא בעלת חברה למכירת רכבי יד שנייה. היא מכרה רכב לשמעון, אך התברר שרכב זה משועבד לבנק. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 31}'::jsonb, 'השאלה עוסקת בחובת המוכר למסור ממכר נקי מזכויות צד שלישי, כפי שקבוע בסעיף 18(א) לחוק המכר, התשכ"ח-1968. היא מדגישה את אופייה המוחלט של חובה זו, שאינה תלויה בידיעת המוכר על קיומו של השעבוד או ברשלנות הקונה בבדיקתו.', 'סעיף 18(א) לחוק המכר, התשכ"ח-1968, קובע כי ''המוכר חייב למסור את הממכר כשהוא נקי מכל שעבוד, עיקול וזכות אחרת של צד שלישי''. חובה זו היא חובה מוחלטת, כלומר, היא חלה על המוכר גם אם לא ידע על קיומו של השעבוד, וגם אם הקונה התרשל ולא בדק את מצב הממכר. הפסיקה, למשל בע"א 838/75 ספקטור נ'' צרפתי ובע"א 8068/11 אורי עיני נ'' שיפריס, הדגישה כי אין לייחס משקל למידת רשלנותו של הקונה בפגם בזכות, שכן פגם בזכות קשה יותר לגילוי מפגם פיזי, והסתמכות הקונה על המוכר גדולה יותר. מכירת רכב משועבד מהווה הפרה של חובה זו, ולכן פזית הפרה את חובותיה כמוכרת. סעיף 18(א) לחוק המכר | פגם בזכות', 'הטעות הנפוצה היא לבלבל בין חובת המוכר למסור ממכר נקי מזכויות צד שלישי (סעיף 18(א)) לבין חובת הגילוי על אי-התאמה (סעיף 16), ולחשוב שידיעת המוכר או רשלנות הקונה רלוונטיות לאחריות המוחלטת לפי סעיף 18(א).',
    '["חוק המכר סעיף 18", "פגם בזכות", "שעבוד", "אחריות מוחלטת", "חובת גילוי", "רשלנות הקונה"]'::jsonb, '**וריאציה 1 — ידיעת המוכר:** האם ידיעת המוכר על השעבוד משנה את הדין? ← לא, חובת המוכר לפי סעיף 18(א) היא מוחלטת ואינה תלויה בידיעתו. ידיעה רלוונטית לחובת הגילוי לפי סעיף 18(ב) ולסעדים (ת"א (שלום ת"א) 153426/02 קלסיקלטת_בע"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע"מ).
**וריאציה 2 — רשלנות הקונה:** האם רשלנות הקונה באי-בדיקת השעבוד פוטרת את המוכר? ← לא, הפסיקה קבעה כי אין לייחס משקל למידת רשלנותו של הקונה בפגם בזכות, שכן חובת המוכר היא מוחלטת (ע"א 8068/11 אורי עיני נ'' שיפריס).
**וריאציה 3 — סוג הממכר:** האם סוג הממכר (רכב, מקרקעין, זכויות) משנה את תחולת סעיף 18? ← לא, סעיף 18 חל על כל סוגי הממכר, לרבות מקרקעין וזכויות, בשינויים המחויבים (ת"א (מחוזי ב"ש) 42045-02-11 אנטיפוד השקעות בע"מ נ'' קיבוץ כרמים).', 'מוכר חייב למסור ממכר נקי משעבודים (סעיף 18(א) לחוק המכר) ← חובה מוחלטת ← לא תלויה בידיעת המוכר או ברשלנות הקונה.', '["חוק המכר, תשכ\"ח-1968, סעיף 18(א)", "חוק המכר, תשכ\"ח-1968, סעיף 18(ב)", "ע\"א 838/75 חיים ספקטור נ'' יוסף צרפתי, לב(1) 231 (30.11.1977)", "ע\"א (מחוזי חי'') 8747-12-20 דורית לוי נ'' פאדי חורי (07.06.2021)", "ת\"א (שלום ת\"א) 153426/02 קלסיקלטת_בע\"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע\"מ (18.05.2004)", "ת\"א (מחוזי ב\"ש) 42045-02-11 אנטיפוד השקעות בע\"מ נ'' קיבוץ כרמים (28.02.2017)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''sale'' | classifier_note: Used-car dealer sold encumbered car — buyer''s protection (תקנת השוק) | source_review_note: השאלה עוסקת בדיני חוזים (מכר), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'פזית לא הפרה את החובות המוטלות עליה כמוכרת אם לא ידעה על השעבוד.', false, 'טענה זו שגויה. חובת המוכר למסור ממכר נקי משעבודים לפי סעיף 18(א) לחוק המכר היא חובה מוחלטת, שאינה תלויה בידיעת המוכר על השעבוד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'פזית לא הפרה את החובות המוטלות עליה כמוכרת, שכן היה על שמעון לברר עניין זה.', false, 'טענה זו שגויה. חובת המוכר לפי סעיף 18(א) לחוק המכר אינה מושפעת מרשלנות הקונה בבדיקת מצב הממכר, שכן מדובר בפגם בזכות שקשה יותר לגילוי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'פזית הפרה את החובות המוטלות עליה כמוכרת.', true, 'תשובה זו נכונה. סעיף 18(א) לחוק המכר מטיל על המוכר חובה מוחלטת למסור את הממכר כשהוא נקי מכל שעבוד, עיקול וזכות אחרת של צד שלישי. מכירת רכב משועבד מהווה הפרה של חובה זו.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'פזית לא הפרה את החובות המוטלות עליה כמוכרת, שכן היא מוכרת רכבי יד שנייה. היא הייתה מפרה את חובותיה אם הייתה מוכרת רכבים חדשים.', false, 'טענה זו שגויה. חוק המכר חל על מכירת כל סוגי הממכר, לרבות רכבי יד שנייה, וחובת המוכר לפי סעיף 18(א) אינה משתנה בהתאם לסוג הממכר או אם הוא חדש או משומש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חובת גילוי וידיעת המוכר',
    1, 'פזית, בעלת חברה למכירת רכבי יד שנייה, מכרה רכב לשמעון. פזית ידעה על השעבוד לבנק אך לא גילתה זאת לשמעון. שמעון, מצידו, לא בדק את רישומי השעבודים. מה הדין?', 'שאלה זו בוחנת את היחס בין חובת הגילוי של המוכר על שעבודים לבין רשלנות הקונה בבדיקתם, בהתאם לסעיף 18(ב) לחוק המכר והפסיקה הרלוונטית, המדגישה את אחריותו המוגברת של המוכר בפגמים בזכות.', 'סעיף 18(ב) לחוק המכר, התשכ"ח-1968, מטיל על המוכר חובה אקטיבית להודיע לקונה ''מיד על כל תביעת זכות לגבי הממכר שידע, או שהיה עליו לדעת עליה, לפני מסירת הממכר''. במקרה זה, פזית ידעה על השעבוד ולא גילתה, ולכן הפרה את חובתה זו. הפסיקה קבעה כי חובת המוכר למסור ממכר נקי מזכויות צד שלישי לפי סעיף 18(א) היא מוחלטת, ואינה מושפעת מרשלנות הקונה בבדיקה. בית המשפט העליון בע"א 8068/11 אורי עיני נ'' שיפריס קבע כי אין לייחס משקל למידת רשלנותו של הקונה בפגם בזכות, שכן לשון סעיף 16 (העוסק באי-התאמה) מתמקדת בידיעת המוכר ואינה כוללת מצב של אשם תורם. קל וחומר הדבר לעניין סעיף 18(א) ו-(ב) העוסקים בפגם בזכות, שבו הסתמכות הקונה על המוכר גדולה יותר. ע"א (מחוזי חי'') 8747-12-20 דורית לוי נ'' פאדי חורי (07.06.2021)',
    'הטעות הנפוצה היא לחשוב שרשלנות הקונה בבדיקת הממכר פוטרת את המוכר מאחריות, במיוחד כאשר מדובר בפגם בזכות, שבו חובת הגילוי של המוכר מוגברת.', '["חוק המכר סעיף 18(ב)", "חובת גילוי", "פגם בזכות", "אשם תורם", "ידיעת המוכר", "רשלנות הקונה"]'::jsonb, '**וריאציה 1 — חובת גילוי אקטיבית:** האם חובת הגילוי של המוכר היא אקטיבית או פסיבית? ← חובת הגילוי היא אקטיבית ודורשת מהמוכר לגלות עובדות מהותיות, גם אם הקונה לא שאל עליהן (ע"א 7991/07 רפאלי נ'' רזין).
**וריאציה 2 — חובת תום לב במשא ומתן:** האם אי-גילוי שעבוד מהווה גם הפרה של חובת תום הלב במשא ומתן? ← כן, אי-גילוי עובדה מהותית כמו שעבוד מהווה הפרה של חובת תום הלב לפי סעיף 12 לחוק החוזים (חלק כללי) (ת"א (שלום חי'') 47843-10-15 שחר רוזן נ'' ערן גילווארג).
**וריאציה 3 — פגם בזכות מול אי-התאמה:** מה ההבדל בין פגם בזכות (סעיף 18) לאי-התאמה (סעיף 16)? ← פגם בזכות מתייחס לזכויות צד שלישי בממכר, בעוד אי-התאמה מתייחסת למצב הפיזי או לתכונות הממכר. סעיף 18(א) מטיל אחריות מוחלטת, בעוד סעיף 16 מתייחס לידיעת המוכר או שהיה עליו לדעת (ע"א 838/75 ספקטור נ'' צרפתי).', 'מוכר ידע על שעבוד ולא גילה ← הפרת סעיף 18(ב) לחוק המכר ← רשלנות הקונה אינה פוטרת (ע"א 8068/11 עיני נ'' שיפריס).',
    '["חוק המכר, תשכ\"ח-1968, סעיף 18(ב)", "ע\"א (מחוזי חי'') 8747-12-20 דורית לוי נ'' פאדי חורי (07.06.2021)", "ע\"א 7991/07 שמעון רפאלי נ'' שמואל רזין ו-30 אח'' (12.04.2011)", "ת\"א (שלום חי'') 47843-10-15 שחר רוזן נ'' ערן גילווארג (27.05.2019)", "ע\"א 838/75 חיים ספקטור נ'' יוסף צרפתי, לב(1) 231 (30.11.1977)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'פזית הפרה את חובת הגילוי המוטלת עליה, ורשלנותו של שמעון אינה פוטרת אותה מאחריות.', true, 'תשובה זו נכונה. פזית הפרה את חובת הגילוי לפי סעיף 18(ב) לחוק המכר, המחייב מוכר להודיע לקונה על כל תביעת זכות שידע או שהיה עליו לדעת עליה. רשלנות הקונה בבדיקה אינה שוללת את אחריות המוכר במקרה של פגם בזכות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'פזית לא הפרה את חובותיה, שכן שמעון התרשל בכך שלא בדק את רישומי השעבודים.', false, 'טענה זו שגויה. הפסיקה קבעה כי רשלנות הקונה בבדיקה אינה פוטרת את המוכר מאחריותו לפי סעיף 18 לחוק המכר, שכן פגם בזכות קשה יותר לגילוי מפגם פיזי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'פזית הפרה את חובותיה, אך שמעון אינו זכאי לסעדים בשל אשם תורם מצידו.', false, 'טענה זו שגויה. הפסיקה קבעה כי אין לייחס משקל למידת רשלנותו של הקונה בפגם בזכות, וכי סעיף 18(א) הוא קוגנטי ואינו כולל מצב של אשם תורם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'פזית לא הפרה את חובותיה, שכן חובת הגילוי חלה רק על פגמים פיזיים בממכר.', false, 'טענה זו שגויה. חובת הגילוי לפי סעיף 18(ב) לחוק המכר חלה במפורש על ''תביעת זכות'' לגבי הממכר, ולא רק על פגמים פיזיים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היקף "זכות אחרת של צד שלישי"',
    2, 'פזית מכרה לשמעון רכב. לאחר הרכישה התברר שהרכב נגנב בעבר והוא למעשה שייך לצד שלישי (הבעלים המקורי). מה הדין לעניין חובותיה של פזית?', 'שאלה זו מתמקדת בהיקף הפרשנות של המונח ''זכות אחרת של צד שלישי'' בסעיף 18(א) לחוק המכר, וקובעת כי הוא כולל גם זכות בעלות מלאה של צד שלישי, כגון במקרה של ממכר גנוב, המטילה אחריות מוחלטת על המוכר.', 'סעיף 18(א) לחוק המכר, התשכ"ח-1968, קובע כי ''המוכר חייב למסור את הממכר כשהוא נקי מכל שעבוד, עיקול וזכות אחרת של צד שלישי''. הפסיקה פירשה את המונח ''זכות אחרת של צד שלישי'' באופן רחב, כך שיכלול לא רק שעבודים ועיקולים, אלא גם זכויות קניין רוחני (כפי שנקבע בע"א 3912/90 Eximin S.A.) ואף בעלות מלאה של צד שלישי, כגון במקרה של ממכר גנוב. במקרה כזה, המוכר אינו יכול להקנות לקונה בעלות נקייה, ולכן הוא מפר את חובתו לפי סעיף 18(א), גם אם לא ידע שהממכר גנוב. אחריות זו היא אחריות מוחלטת. ת"א (שלום ת"א) 153426/02 קלסיקלטת_בע"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע"מ (18.05.2004)',
    'הטעות הנפוצה היא להגביל את פרשנות ''זכות אחרת של צד שלישי'' רק לשעבודים ועיקולים, ולא לכלול בה זכויות קניין מהותיות יותר, כמו בעלות מלאה.', '["חוק המכר סעיף 18(א)", "פגם בזכות", "זכות צד שלישי", "אחריות מוחלטת", "ממכר גנוב", "הקניית בעלות"]'::jsonb, '**וריאציה 1 — זכויות קניין רוחני:** האם ''זכות אחרת של צד שלישי'' כוללת גם זכויות קניין רוחני? ← כן, הפסיקה קבעה כי הפרה של זכות קניין רוחני (כגון פטנט או סימן מסחר) נכללת בהפרת סעיף 18(א) לחוק המכר (ע"א 3912/90 Eximin S.A.).
**וריאציה 2 — הגבלות תכנוניות:** האם הגבלות תכנוניות על מקרקעין נחשבות ל''זכות אחרת של צד שלישי''? ← כן, זכות קיימת של ועדת תכנון ובנייה להפקיע חלקה או למנוע בנייה נחשבת לזכות צד שלישי לעניין זה (ע"א 838/75 ספקטור נ'' צרפתי).
**וריאציה 3 — תקנת השוק:** האם קונה שרכש רכב גנוב בתנאי תקנת השוק מוגן? ← אם הקונה עומד בתנאי תקנת השוק (סעיף 34 לחוק המכר), הוא רוכש בעלות נקייה, אך המוכר עדיין הפר את חובתו כלפיו (ת"א (שלום אשקלון) 2609/97 אבי בן חמו נ'' ברנס נינט).', 'סעיף 18(א) לחוק המכר ← ''זכות אחרת של צד שלישי'' ← כוללת בעלות מלאה (רכב גנוב) וזכויות קניין רוחני ← אחריות מוחלטת של המוכר.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 18(א)", "ע\"א 3912/90 Eximin S.A, תאגיד בלגי נ'' טקסטיל והנעלה איטל סטייל פראררי בע\"מ, מז(4) 064 (22.08.1993)", "ת\"א (שלום ת\"א) 153426/02 קלסיקלטת_בע\"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע\"מ (18.05.2004)", "ע\"א 838/75 חיים ספקטור נ'' יוסף צרפתי, לב(1) 231 (30.11.1977)", "ת\"א (שלום אשקלון) 2609/97 אבי בן חמו נ'' ברנס נינט (07.06.2001)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'פזית הפרה את חובתה למסור ממכר נקי מזכות צד שלישי, שכן בעלותו של צד שלישי נחשבת ל"זכות אחרת" לפי סעיף 18(א) לחוק המכר.', true, 'תשובה זו נכונה. סעיף 18(א) לחוק המכר מחייב את המוכר למסור ממכר נקי מכל זכות של צד שלישי, והמונח ''זכות אחרת'' כולל גם זכות בעלות מלאה של צד שלישי, כגון במקרה של רכב גנוב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'פזית לא הפרה את חובותיה, שכן סעיף 18(א) לחוק המכר מתייחס רק לשעבודים ועיקולים, ולא לבעלות מלאה של צד שלישי.', false, 'טענה זו שגויה. הפסיקה הרחיבה את פרשנות המונח ''זכות אחרת של צד שלישי'' בסעיף 18(א) לחוק המכר, והיא כוללת גם זכויות קניין רוחני ואף בעלות מלאה של צד שלישי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'פזית לא הפרה את חובותיה, אלא אם כן ידעה שהרכב גנוב.', false, 'טענה זו שגויה. חובת המוכר לפי סעיף 18(א) לחוק המכר היא חובה מוחלטת, שאינה תלויה בידיעת המוכר על קיומה של זכות צד שלישי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'פזית הפרה את חובותיה, אך שמעון אינו זכאי לסעדים אם לא בדק את מקור הרכב.', false, 'טענה זו שגויה. רשלנות הקונה בבדיקה אינה פוטרת את המוכר מאחריותו לפי סעיף 18(א) לחוק המכר, במיוחד כאשר מדובר בפגם בזכות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התנאה על סעיף 18 לחוק המכר',
    3, 'פזית מכרה רכב לשמעון. בחוזה המכר נכתב במפורש כי שמעון קונה את הרכב "כמות שהוא" (as is) ומוותר על כל טענה בגין שעבודים או זכויות צד שלישי. לאחר הרכישה התברר שהרכב משועבד לבנק. מה הדין?', 'שאלה זו בוחנת את האופי הדיספוזיטיבי של סעיף 18(א) לחוק המכר, המאפשר לצדדים להתנות על חובת המוכר למסור ממכר נקי מזכויות צד שלישי, ובלבד שההתניה ברורה וחד משמעית, ואינה נוגדת את עקרונות תום הלב.', 'סעיף 18(א) לחוק המכר, התשכ"ח-1968, קובע את חובת המוכר למסור ממכר נקי מזכויות צד שלישי. אולם, הוראה זו, בניגוד לסעיף 16 לחוק המכר (העוסק באי-התאמה), נחשבת להוראה דיספוזיטיבית, כלומר, הצדדים רשאים להתנות עליה בחוזה המכר. אם הצדדים הסכימו במפורש ובאופן חד משמעי כי הקונה רוכש את הממכר ''כמות שהוא'' ומוותר על טענות בגין שעבודים או זכויות צד שלישי, הרי שהתניה זו תהיה תקפה ותשלול את אחריות המוכר. עם זאת, יש לבחון תמיד את תום ליבם של הצדדים ואת נסיבות ההתניה, כדי לוודא שהיא לא נועדה להסתיר פגם מהותי ביודעין. במקרה זה, אם ההתניה ברורה, היא גוברת על הוראת סעיף 18(א). ת"ק (תביעות קטנות חד'') 26409-05-11 שגיב ערבה נ'' מיכאל בר-אל (14.09.2011)',
    'הטעות הנפוצה היא לבלבל בין האופי הקוגנטי של סעיף 16 לחוק המכר (אי-התאמה) לבין האופי הדיספוזיטיבי של סעיף 18(א) (פגם בזכות), ולחשוב שלא ניתן להתנות על האחרון.', '["חוק המכר סעיף 18(א)", "דיספוזיטיביות", "התנאה חוזית", "פגם בזכות", "תום לב", "as is"]'::jsonb, '**וריאציה 1 — התניה על סעיף 16:** האם ניתן להתנות על סעיף 16 לחוק המכר (אי-התאמה)? ← לא, סעיף 16 הוא קוגנטי ולא ניתן להתנות עליו לרעת הקונה, במיוחד אם המוכר ידע או היה עליו לדעת על אי-ההתאמה (ע"א 8068/11 אורי עיני נ'' שיפריס).
**וריאציה 2 — התניה כללית:** האם התניה כללית בחוזה לפיה הקונה בדק את הממכר פוטרת את המוכר מאחריות לפי סעיף 18(א)? ← לא, התניה כזו אינה מספיקה כדי לשלול את אחריות המוכר, אלא נדרשת התניה מפורשת וברורה לגבי פגמים בזכות (ת"א (מחוזי ב"ש) 41900-03-14 גי אלכסנדר בנאילוז נ'' שלמה אלמליח).
**וריאציה 3 — תום לב בהתניה:** האם התניה על סעיף 18(א) יכולה להיפסל בשל חוסר תום לב? ← כן, אם המוכר ידע על השעבוד והסתיר אותו, וההתניה נועדה לעקוף את חובת הגילוי, היא עלולה להיפסל בשל חוסר תום לב (ה"פ (שלום ירושלים) 602/05 רם שן טיח וגבס בע"מ נ'' סלע שיווק מוצרי בטון בע"מ).', 'סעיף 18(א) לחוק המכר ← דיספוזיטיבי ← ניתן להתנות עליו בהסכמה מפורשת וברורה ← בכפוף לתום לב.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 18(א)", "חוק המכר, תשכ\"ח-1968, סעיף 16", "ת\"ק (תביעות קטנות חד'') 26409-05-11 שגיב ערבה נ'' מיכאל בר-אל (14.09.2011)", "ע\"א 8068/11 אורי עיני נ'' חן שיפריס (11.02.2014)", "ת\"א (מחוזי ב\"ש) 41900-03-14 גי אלכסנדר בנאילוז נ'' שלמה אלמליח (16.08.2018)", "ה\"פ (שלום ירושלים) 602/05 רם שן טיח וגבס בע\"מ נ'' סלע שיווק מוצרי בטון בע\"מ (25.09.2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'התניה זו תקפה, שכן סעיף 18(א) לחוק המכר הוא דיספוזיטיבי וניתן להתנות עליו, ובלבד שההתניה ברורה וחד משמעית.', true, 'תשובה זו נכונה. סעיף 18(א) לחוק המכר הוא דיספוזיטיבי, כלומר הצדדים רשאים להתנות עליו בחוזה. אם ההתניה ברורה וחד משמעית, היא תהיה תקפה ותשלול את אחריות המוכר לשעבוד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'התניה זו בטלה, שכן סעיף 18(א) לחוק המכר הוא קוגנטי ולא ניתן להתנות עליו.', false, 'טענה זו שגויה. בניגוד לסעיף 16 לחוק המכר, סעיף 18(א) הוא דיספוזיטיבי וניתן להתנות עליו, אלא אם כן ההתניה נוגדת את עקרון תום הלב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'התניה תקפה רק אם פזית לא ידעה על השעבוד בעת המכירה.', false, 'טענה זו שגויה. תוקף ההתניה אינו תלוי בידיעת המוכר, אלא ברצון הצדדים להתנות על הוראות החוק. ידיעת המוכר רלוונטית לחובת הגילוי לפי סעיף 18(ב).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'התניה בטלה אם שמעון לא קיבל הסבר מפורט על משמעותה.', false, 'טענה זו שגויה. אף שחובת הגילוי ותום הלב מחייבות הסבר, התניה עצמה תקפה אם היא ברורה וחד משמעית, ואינה נחשבת לתניית פטור אסורה כשלעצמה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדי הקונה בגין הפרת סעיף 18',
    4, 'פזית מכרה רכב לשמעון. התברר שהרכב משועבד לבנק. שמעון מעוניין לבטל את העסקה ולקבל את כספו בחזרה. מהם הסעדים העומדים לרשותו של שמעון?', 'שאלה זו עוסקת בסעדים העומדים לרשות קונה שנפגע מהפרת סעיף 18(א) לחוק המכר, המטיל על המוכר חובה למסור ממכר נקי מזכויות צד שלישי. הסעדים נגזרים מחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970.', 'הפרת סעיף 18(א) לחוק המכר, התשכ"ח-1968, המטיל על המוכר חובה למסור ממכר נקי משעבודים וזכויות צד שלישי, מהווה הפרת חוזה. במקרה של הפרת חוזה, הקונה זכאי לסעדים הקבועים בחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970. סעדים אלו כוללים, בין היתר, את הזכות לבטל את החוזה (בדרך כלל הפרה זו נחשבת ליסודית), לקבל השבה של התמורה ששולמה, וכן לדרוש פיצויים בגין הנזקים שנגרמו לו עקב ההפרה (כגון ירידת ערך, עוגמת נפש, הוצאות נלוות). הפסיקה מדגישה כי הקונה אינו צריך ''ללכת בדרך ייסורים'' מול הצד השלישי, אלא זכאי לחזור אל המוכר ולדרוש את התרופות בשל הפרת החוזה. ת"א (שלום ת"א) 153426/02 קלסיקלטת_בע"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע"מ (18.05.2004)',
    'הטעות הנפוצה היא להגביל את הסעדים העומדים לרשות הקונה, או לחשוב שחובת הבדיקה של הקונה שוללת את זכותו לסעדים במקרה של פגם בזכות.', '["הפרת חוזה", "חוק החוזים (תרופות)", "ביטול חוזה", "השבה", "פיצויים", "חוק המכר סעיף 18(א)", "סעדים"]'::jsonb, '**וריאציה 1 — הפרה יסודית:** האם הפרת סעיף 18(א) היא תמיד הפרה יסודית? ← לרוב כן, שכן היא פוגעת באופן מהותי בציפיית הקונה לקבל בעלות נקייה, אך הדבר תלוי בנסיבות ובמהות הפגם (ע"א 838/75 ספקטור נ'' צרפתי).
**וריאציה 2 — פיצויים מוסכמים:** האם ניתן לתבוע פיצויים מוסכמים בגין הפרת סעיף 18(א)? ← כן, אם נקבעו פיצויים מוסכמים בחוזה, הקונה זכאי לתבוע אותם, בנוסף או במקום סעדים אחרים, בכפוף לסמכות בית המשפט להפחיתם (סעיף 15 לחוק החוזים (תרופות)).
**וריאציה 3 — אכיפה:** האם שמעון יכול לדרוש אכיפה, כלומר שפזית תסיר את השעבוד? ← כן, אכיפה היא סעד ראשוני בדיני חוזים, ושמעון יכול לדרוש מפזית לפעול להסרת השעבוד, אם הדבר אפשרי (סעיף 3 לחוק החוזים (תרופות)).', 'הפרת סעיף 18(א) לחוק המכר ← הפרת חוזה ← סעדים: ביטול, השבה, פיצויים (חוק החוזים (תרופות)).',
    '["חוק המכר, תשכ\"ח-1968, סעיף 18(א)", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 3", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15", "ת\"א (שלום ת\"א) 153426/02 קלסיקלטת_בע\"מ נ'' יפו מ.ג. הפקות קולנוע וטלויזיה בע\"מ (18.05.2004)", "ע\"א 838/75 חיים ספקטור נ'' יוסף צרפתי, לב(1) 231 (30.11.1977)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'שמעון זכאי לבטל את החוזה ולקבל השבה של התמורה ששילם, וכן פיצויים בגין הנזקים שנגרמו לו עקב ההפרה.', true, 'תשובה זו נכונה. הפרת סעיף 18(א) לחוק המכר מהווה הפרת חוזה, המזכה את הקונה בסעדים הקבועים בחוק החוזים (תרופות בשל הפרת חוזה), לרבות ביטול החוזה, השבה ופיצויים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'שמעון זכאי רק לפיצויים בגין ירידת ערך הרכב, אך אינו יכול לבטל את החוזה.', false, 'טענה זו שגויה. הפרת סעיף 18(א) לחוק המכר נחשבת לרוב להפרה יסודית, המקנה לקונה זכות לבטל את החוזה, בנוסף לפיצויים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שמעון זכאי רק להשבת התמורה, אך לא לפיצויים.', false, 'טענה זו שגויה. בנוסף להשבה, הקונה זכאי גם לפיצויים בגין הנזקים שנגרמו לו עקב הפרת החוזה, כגון עוגמת נפש או הוצאות נלוות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שמעון אינו זכאי לסעדים, שכן היה עליו לבדוק את מצב הרכב לפני הרכישה.', false, 'טענה זו שגויה. רשלנות הקונה בבדיקה אינה שוללת את זכותו לסעדים בגין הפרת סעיף 18(א) לחוק המכר, המטיל אחריות מוחלטת על המוכר.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 31, '2019-S-S-Q31';
END
$$;

