-- Q32 — 2019-S-S-Q32 — chapter=contracts subtopic=breach_remedies
-- classifier_note: Liquidated damages (פיצוי מוסכם) clause — enforceability
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '8a85ddf0-b184-4d46-b0a7-64a1dd476de2'::uuid;
  v_group_id uuid := '677d9fca-af87-4191-acaf-c63c4859360b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'e4996710-08c2-454b-91bc-929c15fbe232'::uuid;
  v_ang_1 uuid := '7a5fe89f-f6aa-423d-bf96-d3364c0e6b08'::uuid;
  v_ang_2 uuid := '40f46c87-0a4a-4b5b-80be-8c764cf5a6af'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q32';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 32, '2019-S-S-Q32';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'breach_remedies' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'breach_remedies', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q32', v_chapter_id, v_subtopic_id, 'משה ומרים התקשרו ביניהם בחוזה. הם סיכמו כי אם לא יעמוד משה בהחזרי הכספים שלהם התחייב במסגרת החוזה, ישלם פיצוי מוסכם, שהועמד על סכום נתון בגין כל חודש של אי תשלום. למרבה הצער משה לא עמד בתשלומים שלהם התחייב. מרים תבעה אותו ועתרה לקבל את הפיצוי המוסכם בהתאם לחוזה. משה טען כי מדובר בפיצוי מוסכם לא סביר, ושלא נגרם למרים כל נזק, ולכן התעקשותה לקבל פיצוי מוסכם מהווה עמידה על זכות בחוסר תום לב, ואין מקום לשלמו. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 32}'::jsonb, 'השאלה עוסקת בפיצויים מוסכמים לפי סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970. היא בוחנת את העיקרון לפיו פיצוי מוסכם ניתן ללא הוכחת נזק, ואת סמכותו המצומצמת של בית המשפט להפחיתו רק במקרים חריגים שבהם אין כל יחס סביר בין הפיצוי המוסכם לנזק שניתן היה לצפותו מראש בעת כריתת החוזה.', 'סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, קובע כי ''הסכימו הצדדים מראש על שיעור פיצויים... יהיו הפיצויים כמוסכם, ללא הוכחת נזק''. משמעות הדבר היא שהנפגע אינו צריך להוכיח שנגרם לו נזק בפועל, ואף אם יוכיח המפר כי הנזק שנגרם בפועל היה נמוך מהפיצוי המוסכם, או שלא נגרם נזק כלל, הפיצוי המוסכם ייפסק. נקודת המוצא היא כי יש לכבד את הסכמת הצדדים, כביטוי לעקרון חופש החוזים. סמכות בית המשפט להפחית את הפיצוי המוסכם היא חריגה ומופעלת רק אם מצא שהפיצויים נקבעו ''ללא כל יחס סביר לנזק שניתן היה לראותו מראש בעת כריתת החוזה כתוצאה מסתברת של ההפרה''. המבחן הוא אובייקטיבי ומתייחס למועד כריתת החוזה, ולא לנזק שנגרם בפועל. סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה) | פיצויים מוסכמים', 'הטעות הנפוצה היא לחשוב שהעדר נזק בפועל או נזק נמוך מהפיצוי המוסכם, שולל או מפחית אוטומטית את הפיצוי המוסכם, מבלי להתחשב במבחן הצפיות בעת כריתת החוזה.',
    '["פיצויים מוסכמים", "חוק החוזים (תרופות)", "סעיף 15(א)", "ללא הוכחת נזק", "חופש החוזים", "יחס סביר לנזק צפוי", "מועד כריתת החוזה"]'::jsonb, '**וריאציה 1 — תכליות הפיצוי המוסכם:** מהן התכליות העיקריות של פיצוי מוסכם? ← הוא משקף את אומד דעת הצדדים, יוצר ודאות, חוסך הוצאות התדיינות ויוצר תמריץ לקיום החוזה (ע"א 8506/13 זאבי תקשורת).
**וריאציה 2 — סמכות ההפחתה:** האם בית המשפט חייב להפחית פיצוי מוסכם אם הוא מוצא חוסר יחס סביר? ← לא, הסמכות היא ''רשאי'', ומופעלת במשורה ובמקרים חריגים בלבד (ע"א 10208/16 קרסו מוטורס).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל לשכנע את בית המשפט להפחית פיצוי מוסכם? ← על הצד המפר, אלא אם מדובר בתניה גורפת (ת"א (שלום ת"א) 46682-02-16 אגודים בע"מ).', 'פיצוי מוסכם ← ישולם ללא הוכחת נזק ← בית המשפט יפחית רק אם אין יחס סביר לנזק צפוי בעת כריתת החוזה (סעיף 15(א) לחוק החוזים (תרופות)).', '["חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15(א)", "ע\"א 8506/13 זאבי תקשורת אחזקות בע\"מ נ'' בנק הפועלים בע\"מ (23.08.2015)", "ע\"א 10208/16 קרסו מוטורס בע\"מ נ'' Better Place Inc (13.12.2017)", "ת\"א (שלום ת\"א) 46682-02-16 אגודים בע\"מ נ'' ס. אלון חברה להשקעות ובנין בע\"מ (09.12.2018)", "ת\"א (שלום רח'') 17082-08-20 טי.אס. השקעות 2007 בע\"מ נ'' מכבי בני שעריים על שם יהודה מצהלה (26.01.2023)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''breach_remedies'' | classifier_note: Liquidated damages (פיצוי מוסכם) clause — enforceability | source_review_note: השאלה עוסקת בדיני חוזים, תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כדי להעריך את סבירות הפיצוי המוסכם יש לבחון את היחס הסביר בין הפיצוי המוסכם לבין הנזק שניתן היה לצפות מראש. עם זאת, מכיוון שלא נגרם למרים נזק אין לשלם כאן פיצוי מוסכם כלל.', false, 'טענה זו שגויה. אף שהמבחן הוא אכן היחס הסביר לנזק שניתן היה לצפות מראש, העובדה שלא נגרם נזק בפועל אינה שוללת את הזכות לפיצוי מוסכם, אלא אם כן הפיצוי נקבע ללא כל יחס סביר לנזק הצפוי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כדי להעריך את סבירות הפיצוי המוסכם יש לבחון את היחס הסביר בין הפיצוי המוסכם לבין הנזק שנגרם בפועל. מכיוון שלא נגרם למרים נזק אין לשלם כאן פיצוי מוסכם כלל.', false, 'טענה זו שגויה. המבחן לסבירות הפיצוי המוסכם אינו מתחשב בנזק שנגרם בפועל, אלא בנזק שניתן היה לצפותו מראש בעת כריתת החוזה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'משקבעו הצדדים פיצוי מוסכם על בית המשפט לכבדו אלא אם יתברר כי משה הוטעה או נפל פגם אחר הקשור בעצם כריתת החוזה.', false, 'טענה זו שגויה. אף שבית המשפט נוטה לכבד פיצוי מוסכם, סעיף 15(א) לחוק החוזים (תרופות) מקנה לו סמכות להפחיתו גם ללא פגם בכריתה, אם מצא שהפיצוי נקבע ללא כל יחס סביר לנזק שניתן היה לצפותו מראש.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'גם אם לא נגרם למרים נזק לא יהיה בכך כדי למנוע ממנה לדרוש פיצוי מוסכם.', true, 'תשובה זו נכונה. סעיף 15(א) לחוק החוזים (תרופות) קובע כי פיצויים מוסכמים ישולמו ''ללא הוכחת נזק''. העובדה שבפועל לא נגרם נזק, או שנגרם נזק נמוך מהפיצוי המוסכם, אינה שוללת את הזכות לפיצוי, כל עוד קיים יחס סביר כלשהו בין הפיצוי המוסכם לנזק שניתן היה לצפותו מראש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הפחתת פיצוי מוסכם בתניה גורפת',
    1, 'משה ומרים התקשרו בחוזה. בחוזה נקבע סעיף פיצוי מוסכם אחיד בסכום גבוה, שיחול על כל הפרה של החוזה, בין אם היא קלה ובין אם היא יסודית. משה הפר סעיף שולי בחוזה, ומרים תובעת את הפיצוי המוסכם. משה טוען כי יש להפחית את הפיצוי. מה הדין לעניין נטל ההוכחה במקרה זה?', 'שאלה זו עוסקת בהשפעת ניסוחה של תניית פיצויים מוסכמים כתניה גורפת על נטל ההוכחה לעניין סבירות הפיצוי, בהתאם לסעיף 15(א) לחוק החוזים (תרופות) ולהלכה הפסוקה.', 'סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, קובע כי בית המשפט רשאי להפחית פיצויים מוסכמים אם מצא שהם נקבעו ''ללא כל יחס סביר לנזק שניתן היה לראותו מראש בעת כריתת החוזה כתוצאה מסתברת של ההפרה''. הכלל הוא שנטל השכנוע להפחתת הפיצוי מוטל על הצד המפר. אולם, הפסיקה, למשל בע"א 8506/13 זאבי תקשורת אחזקות בע"מ נ'' בנק הפועלים בע"מ ובע"א 10208/16 קרסו מוטורס בע"מ נ'' Better Place Inc, קבעה חריג לכלל זה: כאשר מדובר בתניית פיצויים מוסכמים המנוסחת כתניה גורפת, כלומר, שאינה מבחינה בין הפרה ''קלה'' לבין הפרה יסודית ומהותית של החוזה, אזי אין צורך להניח תשתית ראייתית מיוחדת. די בניסוחה הגורף כדי לחשוף אותה לבדיקת בית המשפט, ונטל השכנוע עשוי לעבור לכתפי הנפגע לשכנע מדוע אין מקום לעשות שימוש בסמכות ההפחתה של בית המשפט. ת"א (שלום ת"א) 46682-02-16 אגודים בע"מ נ'' ס. אלון חברה להשקעות ובנין בע"מ (09.12.2018)',
    'הטעות הנפוצה היא להניח שנטל ההוכחה להפחתת פיצוי מוסכם תמיד מוטל על המפר, גם במקרים של תניה גורפת.', '["פיצויים מוסכמים", "תניה גורפת", "נטל ההוכחה", "סעיף 15(א) לחוק החוזים (תרופות)", "הפרה קלה", "הפרה יסודית"]'::jsonb, '**וריאציה 1 — תכלית התניה הגורפת:** האם תניה גורפת יכולה לשרת תכלית לגיטימית? ← כן, היא יכולה ליצור ודאות ולחסוך עלויות התדיינות, אך היא חשופה יותר להתערבות בית המשפט (ע"א 8506/13 זאבי תקשורת).

**וריאציה 2 — סמכות בית המשפט:** האם בית המשפט חייב להפחית פיצוי מוסכם בתניה גורפת? ← לא, הסמכות היא ''רשאי'', וגם אם מצא חוסר יחס סביר, עדיין מדובר בשיקול דעת (ע"א 10208/16 קרסו מוטורס).
**וריאציה 3 — יחס סביר דחוק:** מה קורה אם קיים יחס סביר ''דחוק'' בין הפיצוי לנזק הצפוי? ← בית המשפט לא יתערב וישאיר את הפיצוי המוסכם על כנו, שכן התערבותו מצומצמת ונדירה (ע"א 4630/04 קניונים נכסים).', 'תניה גורפת לפיצוי מוסכם ← נטל השכנוע עובר לנפגע ← להראות סבירות הפיצוי (זאבי תקשורת, קרסו מוטורס).',
    '["חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15(א)", "ע\"א 8506/13 זאבי תקשורת אחזקות בע\"מ נ'' בנק הפועלים בע\"מ (23.08.2015)", "ע\"א 10208/16 קרסו מוטורס בע\"מ נ'' Better Place Inc (13.12.2017)", "ת\"א (שלום ת\"א) 46682-02-16 אגודים בע\"מ נ'' ס. אלון חברה להשקעות ובנין בע\"מ (09.12.2018)", "ע\"א 4630/04 קניונים נכסים ובנין בע\"מ נ'' בני יעקב נדל\"ן בע\"מ (13.12.2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'נטל ההוכחה כי הפיצוי נקבע ללא כל יחס סביר מוטל על משה, המפר.', false, 'טענה זו שגויה. אף שזהו הכלל הרגיל, במקרה של תניה גורפת, נטל ההוכחה עשוי לעבור לצד הנפגע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'נטל ההוכחה כי הפיצוי סביר מוטל על מרים, הנפגעת, שכן מדובר בתניית פיצויים מוסכמים גורפת.', true, 'תשובה זו נכונה. הפסיקה קבעה כי כאשר מדובר בתניית פיצויים מוסכמים גורפת, שאינה מבחינה בין הפרה קלה להפרה יסודית, די בניסוחה הגורף כדי לחשוף אותה לבדיקת בית המשפט, ונטל השכנוע עשוי לעבור לכתפי הנפגעת להראות מדוע אין מקום להפחית את הפיצוי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'נטל ההוכחה מוטל על בית המשפט, שכן עליו לבחון את סבירות הפיצוי מיוזמתו.', false, 'טענה זו שגויה. בית המשפט אינו נושא בנטל ההוכחה, אלא הצדדים לדיון. בית המשפט מפעיל את סמכותו על בסיס הראיות שהוצגו בפניו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'אין צורך בנטל הוכחה, שכן תניה גורפת בטלה מעיקרה.', false, 'טענה זו שגויה. תניה גורפת אינה בטלה מעיקרה, אך היא חשופה יותר להתערבות בית המשפט, ומשנה את נטל ההוכחה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן היחס הסביר בפיצוי מוסכם',
    2, 'מהו המבחן המרכזי שבית המשפט בוחן כאשר הוא שוקל להפחית פיצוי מוסכם, בהתאם לסעיף 15(א) לחוק החוזים (תרופות)?', 'שאלה זו מתמקדת במבחן המהותי להפחתת פיצויים מוסכמים על ידי בית המשפט, כפי שנקבע בסעיף 15(א) לחוק החוזים (תרופות), ומדגישה את אופיו האובייקטיבי והפרוספקטיבי של מבחן זה.', 'סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, קובע במפורש את המבחן להפחתת פיצויים מוסכמים: ''רשאי בית המשפט להפחיתם אם מצא שהפיצויים נקבעו ללא כל יחס סביר לנזק שניתן היה לראותו מראש בעת כריתת החוזה כתוצאה מסתברת של ההפרה''. מבחן זה הוא אובייקטיבי ופרוספקטיבי, כלומר, בית המשפט בוחן מה היה סביר לצפות כנזק בעת כריתת החוזה, ולא מהו הנזק שנגרם בפועל. הפסיקה, למשל בע"א 8506/13 זאבי תקשורת אחזקות בע"מ נ'' בנק הפועלים בע"מ ובע"א 10208/16 קרסו מוטורס בע"מ נ'' Better Place Inc, מדגישה כי ''המבט – כהכוונת המחוקק – הוא אל המועד שבו נכרת החוזה; אולם, שאלת הסבירות דאז נבחנת לאור ההפרה דהיום''. כל עוד קיים יחס סביר כלשהו, ולו גם דחוק, בין הפיצוי המוסכם לבין הנזק הצפוי במועד הכריתה, בית המשפט לא יפחית את הפיצוי. ת"א (שלום ת"א) 36366-11-16 360 טל בע"מ נ'' גיא שמואל ליברמן (07.05.2019)',
    'הטעות הנפוצה היא לבחון את סבירות הפיצוי המוסכם ביחס לנזק שנגרם בפועל, במקום ביחס לנזק שניתן היה לצפותו מראש בעת כריתת החוזה.', '["פיצויים מוסכמים", "סעיף 15(א) לחוק החוזים (תרופות)", "יחס סביר לנזק צפוי", "מועד כריתת החוזה", "מבחן אובייקטיבי", "שיקול דעת בית המשפט"]'::jsonb, '**וריאציה 1 — נזק בפועל אפס:** האם פיצוי מוסכם יופחת אם בפועל לא נגרם נזק כלל? ← לא בהכרח. אם בעת כריתת החוזה ניתן היה לצפות נזק סביר, הפיצוי המוסכם יישאר על כנו גם אם בפועל לא נגרם נזק (ע"א 8506/13 זאבי תקשורת).

**וריאציה 2 — סמכות ''רשאי'':** מה משמעות המילה ''רשאי'' בסעיף 15(א)? ← גם אם בית המשפט מצא שאין יחס סביר, הוא אינו חייב להפחית את הפיצוי, אלא זו סמכות שבשיקול דעת (ע"א 4481/90 אהרן נ'' ג. פרץ מ. בן גיאת).
**וריאציה 3 — נטל השכנוע:** על מי מוטל נטל השכנוע להראות שאין יחס סביר? ← על הצד המפר המבקש להפחית את הפיצוי המוסכם (ע"א 4794046 ת"א (שלום ת"א) 36366-11-16 360 טל בע"מ נ'' גיא שמואל ליברמן).', 'מבחן הפחתת פיצוי מוסכם ← יחס סביר לנזק שניתן היה לצפותו מראש ← בעת כריתת החוזה (סעיף 15(א) לחוק החוזים (תרופות)).',
    '["חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15(א)", "ע\"א 8506/13 זאבי תקשורת אחזקות בע\"מ נ'' בנק הפועלים בע\"מ (23.08.2015)", "ע\"א 10208/16 קרסו מוטורס בע\"מ נ'' Better Place Inc (13.12.2017)", "ת\"א (שלום ת\"א) 36366-11-16 360 טל בע\"מ נ'' גיא שמואל ליברמן (07.05.2019)", "ע\"א 4481/90 אהרן נ'' ג.פרץ מ.בן גיאת חברה להנדסה ובנין בע\"מ, פ\"ד מז(3) 427 (18.07.1993)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם קיים יחס סביר בין הפיצוי המוסכם לבין הנזק שנגרם בפועל עקב ההפרה.', false, 'טענה זו שגויה. המבחן אינו מתייחס לנזק שנגרם בפועל, אלא לנזק שניתן היה לצפותו מראש בעת כריתת החוזה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם קיים יחס סביר בין הפיצוי המוסכם לבין הנזק שניתן היה לצפותו מראש בעת כריתת החוזה כתוצאה מסתברת של ההפרה.', true, 'תשובה זו נכונה. זהו המבחן המפורש הקבוע בסעיף 15(א) לחוק החוזים (תרופות), והוא מבחן אובייקטיבי ופרוספקטיבי, המתייחס למועד כריתת החוזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם הפיצוי המוסכם מהווה קנס עונשי ולא פיצוי אמיתי.', false, 'טענה זו שגויה. אף שפיצוי מוסכם עונשי עלול להיפסל, המבחן המרכזי בסעיף 15(א) הוא מבחן היחס הסביר לנזק הצפוי, ולא רק אופי הפיצוי כ''קנס''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם הצד המפר פעל בתום לב בעת ההפרה.', false, 'טענה זו שגויה. תום ליבו של המפר בעת ההפרה אינו רלוונטי למבחן הפחתת הפיצוי המוסכם, שכן המבחן מתמקד בנזק הצפוי בעת כריתת החוזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פיצוי מוסכם ואשם תורם',
    3, 'משה ומרים התקשרו בחוזה. משה הפר את החוזה, ומרים תובעת פיצוי מוסכם. משה טוען כי מרים לא נקטה באמצעים סבירים להקטנת נזקיה, וכי יש לייחס לה אשם תורם. האם טענות אלו רלוונטיות לתביעת פיצוי מוסכם?', 'שאלה זו בוחנת את היחס בין תביעת פיצויים מוסכמים לבין עקרונות הקטנת הנזק ואשם תורם, ומבהירה כי ככלל, עקרונות אלו אינם חלים על פיצוי מוסכם, למעט חריגים מסוימים.', 'סעיף 15(א) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970, קובע כי פיצויים מוסכמים יינתנו ''ללא הוכחת נזק''. משמעות הדבר היא שהנפגע אינו נדרש להוכיח את עצם קיומו של נזק או את שיעורו, ובהתאם לכך, הוא אינו חשוף לטענות בדבר חובת הקטנת הנזק (סעיף 14 לחוק התרופות) או אשם תורם. גישה זו משקפת את תכלית הפיצוי המוסכם ליצור ודאות ולחסוך התדיינויות. עם זאת, בספרות המשפטית ובפסיקה נדונו סוגיות של אשם תורם גם במסגרת הדיון בפיצויים מוסכמים, במיוחד כאשר מדובר בפיצוי מוסכם עיתי (יומי/חודשי), שם עשויה להיות רלוונטיות לשאלת השליטה של הנפגע על משך ההפרה. אולם, הכלל הבסיסי נותר כי אין הנפגע כפוף לנטל הקטנת הנזק בתביעת פיצוי מוסכם. ת"א (שלום רח'') 17082-08-20 טי.אס. השקעות 2007 בע"מ נ'' מכבי בני שעריים על שם יהודה מצהלה (26.01.2023)',
    'הטעות הנפוצה היא להחיל באופן אוטומטי את חובת הקטנת הנזק ואת עקרון האשם התורם על תביעות לפיצוי מוסכם, מבלי להבין את הייחוד של סעד זה.', '["פיצויים מוסכמים", "הקטנת נזק", "אשם תורם", "סעיף 15(א) לחוק החוזים (תרופות)", "סעיף 14 לחוק החוזים (תרופות)", "ללא הוכחת נזק"]'::jsonb, '**וריאציה 1 — פיצוי מוסכם עיתי:** האם אשם תורם רלוונטי לפיצוי מוסכם עיתי? ← במקרים מסוימים, בית המשפט עשוי להתחשב בכך שהנפגע לא פעל להקטנת הנזק או להפסקת ההפרה, במיוחד כאשר משך ההפרה תלוי גם בו (גבריאלה שלו ויהודה אדר, דיני חוזים - התרופות, עמ'' 236).
**וריאציה 2 — תכלית הפיצוי המוסכם:** מדוע אין חובת הקטנת נזק בפיצוי מוסכם? ← כי הפיצוי נקבע מראש על ידי הצדדים, והוא נועד לחסוך את הצורך בהוכחת נזק ובדיקת הקטנתו (ע"א 1880/19 הליגה למניעת מחלות ריאה).
**וריאציה 3 — השפעת אשם תורם על הפחתה:** האם אשם תורם יכול להשפיע על סמכות בית המשפט להפחית פיצוי מוסכם? ← ככלל, אשמם של הצדדים אינו רלוונטי למבחן ההפחתה, שכן המבחן עוסק ביחס שבין הנזק שניתן היה לצפותו במועד הכריתה לבין הפיצוי המוסכם (ת"א (מחוזי חי'') 55773-02-20 אילנה קירשנבוים).', 'פיצוי מוסכם ← ללא הוכחת נזק ← אין חובת הקטנת נזק או אשם תורם (סעיף 15(א) לחוק החוזים (תרופות)).',
    '["חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15(א)", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 14", "ת\"א (שלום רח'') 17082-08-20 טי.אס. השקעות 2007 בע\"מ נ'' מכבי בני שעריים על שם יהודה מצהלה (26.01.2023)", "ע\"א 1880/19 הליגה למניעת מחלות ריאה תל אביב נ'' שיר משכנות וותיקים בע\"מ (25.10.2020)", "גבריאלה שלו, יהודה אדר דיני חוזים - התרופות (2009) | פרק 7: פיצויים", "ת\"א (מחוזי חי'') 55773-02-20 אילנה קירשנבוים נ'' מלון נוף הכרמל חיפה בע\"מ (12.03.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חובת הקטנת הנזק ואשם תורם חלים גם על תביעת פיצוי מוסכם.', false, 'טענה זו שגויה. ככלל, חובת הקטנת הנזק אינה חלה על תביעת פיצוי מוסכם, וגם אשם תורם אינו רלוונטי למבחן הפחתת הפיצוי המוסכם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, תביעת פיצוי מוסכם אינה טעונה הוכחת נזק, ולכן אין רלוונטיות לחובת הקטנת נזק או לאשם תורם.', true, 'תשובה זו נכונה. פיצוי מוסכם ניתן ''ללא הוכחת נזק'', ולכן הנפגע אינו נדרש להוכיח את עצם קיומו של נזק או את שיעורו, ואינו חשוף לטענות בדבר הקטנת נזק או אשם תורם, כפי שנקבע בפסיקה ובספרות המשפטית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הפיצוי המוסכם נקבע כסכום עונשי ולא כפיצוי אמיתי.', false, 'טענה זו שגויה. גם אם הפיצוי המוסכם נחשב עונשי, המבחן להפחתתו הוא היחס הסביר לנזק הצפוי, ולא חובת הקטנת הנזק או אשם תורם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן מדובר בפיצוי מוסכם עיתי (יומי/חודשי), שאז יש רלוונטיות לאשם תורם.', false, 'טענה זו שגויה חלקית. אף שקיימת פסיקה המאפשרת התחשבות באשם תורם בפיצוי מוסכם עיתי, הכלל הבסיסי הוא שאין רלוונטיות לאשם תורם או הקטנת נזק בתביעת פיצוי מוסכם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 32, '2019-S-S-Q32';
END
$$;

