-- Q34 — 2019-S-S-Q34 — chapter=contracts subtopic=general_part
-- classifier_note: Performance with alternative consideration (Ming vase OR cash) — חוזה ברירה
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e0cfb8c0-32d7-47c3-8345-d859e78b7135'::uuid;
  v_group_id uuid := '1f2e0fd9-0af1-43b2-b48f-b0c83728d523'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'b99df095-8715-4137-95f1-f91e59ee7375'::uuid;
  v_ang_1 uuid := '8b73dde8-c424-48d2-a8da-a1d3936e0b2f'::uuid;
  v_ang_2 uuid := 'bfa075be-c3ee-4a47-b842-0424ada30c49'::uuid;
  v_ang_3 uuid := '7352f454-d3c5-42f9-9e0e-ea4d78ac5bf0'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q34';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 34, '2019-S-S-Q34';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q34', v_chapter_id, v_subtopic_id, 'נחמה התקשרה בחוזה עם נחמיה. על פי ההסכם נחמה תמכור לנחמיה את מכונית הספורט האדומה שלה בתמורה למיליון ש"ח, שנחמיה ישלם לה לאחר 30 יום ממועד המסירה של המכונית, או בתמורה לכד יקר משושלת מינג המצוי בבעלותו, שיועבר לחזקתה ולבעלותה לאחר 30 יום כאמור. נחמה מסרה לנחמיה את המכונית. הגיעה העת שנחמיה יעמוד בחלקו בהסכם. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 34}'::jsonb, 'השאלה עוסקת בחיובים חלופיים בחוזה, כפי שמוסדר בסעיף 51 לחוק החוזים (חלק כללי), התשל"ג-1973. היא בוחנת את הכלל לפיו זכות הבחירה בין החיובים נתונה לחייב, וכן את חובתו להודיע על בחירתו לנושה במועד הקבוע בחוק או בחוזה.', 'החוזה בין נחמה לנחמיה הוא ''חוזה חלופין'', שכן הוא מעניק לנחמיה (החייב) בחירה בין שתי דרכי קיום אלטרנטיביות של חיובו – תשלום כסף או מסירת כד. סעיף 51(א) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''בחיובים חלופים רשאי החייב, בהודעה לנושה תוך תקופה שנקבעה לכך, ובאין תקופה כזו – תוך זמן סביר לפני המועד לקיום, לבחור את החיוב שיקיים''. כלומר, ככלל, זכות הבחירה נתונה לחייב, והוא רשאי לבחור באיזה חיוב יקיים את החוזה. עם זאת, זכות זו כפופה לחובת הודעה לנושה (נחמה) תוך זמן סביר לפני מועד הקיום. אם נחמיה לא היה מודיע על בחירתו במועד, זכות הבחירה הייתה עוברת לנחמה. סעיף 51(א) לחוק החוזים (חלק כללי) | בחירה בין חיובים חלופים', 'הטעות הנפוצה היא לחשוב שזכות הבחירה בחיובים חלופיים נתונה תמיד לנושה, או שהיא אינה כפופה לחובת הודעה במועד, מבלי להתחשב בהוראות סעיף 51 לחוק החוזים.',
    '["חיובים חלופיים", "זכות בחירה", "חייב", "נושה", "הודעה לנושה", "זמן סביר", "חוק החוזים סעיף 51"]'::jsonb, '**וריאציה 1 — התנאה על סעיף 51:** האם הצדדים יכולים לקבוע בחוזה שזכות הבחירה תהיה נתונה לנושה? ← כן, סעיף 51 הוא דיספוזיטיבי, והצדדים רשאים להתנות עליו בחוזה (סעיף 51(ב) לחוק החוזים (חלק כללי)).
**וריאציה 2 — מועד הבחירה:** מה קורה אם לא נקבע מועד להודעה על הבחירה? ← על החייב להודיע על בחירתו תוך זמן סביר לפני המועד לקיום (סעיף 51(א) לחוק החוזים (חלק כללי)).
**וריאציה 3 — בחירה חד פעמית:** האם הבחירה היא חד פעמית? ← כן, אם החייב הודיע על בחירתו, שוב אין הוא רשאי לחזור בו (ללא הסכמת הנושה), ולבצע את האפשרות השנייה (פרידמן וכהן, חוזים, כרך ד'', עמ'' 21).', 'בחיובים חלופיים ← החייב בוחר את החיוב שיקיים ← בהודעה לנושה תוך זמן סביר לפני הקיום (סעיף 51(א) לחוק החוזים).', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 51(א)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 51(ב)", "דניאל פרידמן, נילי כהן חוזים - כרך ד'' (2011) | חיובים חלופיים"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Performance with alternative consideration (Ming vase OR cash) — חוזה ברירה | source_review_note: השאלה עוסקת בדיני חוזים (קיום חיובים), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'נחמיה יוכל לבחור אם לשלם לנחמה מיליון ש"ח או למסור לחזקתה ולבעלותה את הכד.', false, 'טענה זו נכונה חלקית. נחמיה אכן יכול לבחור, אך הבחירה כפופה לדרישת הודעה לנושה במועד הקבוע בחוק או בחוזה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'נחמיה יוכל לבחור אם לשלם לנחמה מיליון ש"ח או למסור לחזקתה ולבעלותה את הכד, ובלבד שהודיע לנחמה על בחירתו זמן סביר לפני המועד שבו עליו למלא את התחייבותו.', true, 'תשובה זו נכונה. סעיף 51(א) לחוק החוזים (חלק כללי) קובע כי בחיובים חלופיים, זכות הבחירה נתונה לחייב, ובלבד שימסור הודעה לנושה תוך תקופה שנקבעה לכך, או תוך זמן סביר לפני מועד הקיום.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'נחמה תוכל לבחור אם ברצונה לקבל את הכד או את מיליון הש"ח.', false, 'טענה זו שגויה. בהיעדר הסכמה מפורשת בחוזה, זכות הבחירה בחיובים חלופיים נתונה לחייב, ולא לנושה, אלא אם החייב לא מימש את זכותו במועד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על נחמיה להעביר לבעלות נחמה את הנכס שערכו גבוה יותר.', false, 'טענה זו שגויה. החוק אינו קובע כי יש לבחור בחלופה בעלת הערך הגבוה יותר, אלא מעניק את זכות הבחירה לאחד הצדדים, לרוב החייב, בהתאם לתנאים הקבועים בסעיף 51 לחוק החוזים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'העברת זכות הבחירה לנושה',
    1, 'נחמה התקשרה בחוזה עם נחמיה. על פי ההסכם נחמה תמכור לנחמיה את מכונית הספורט האדומה שלה בתמורה למיליון ש"ח, שנחמיה ישלם לה לאחר 30 יום ממועד המסירה של המכונית, או בתמורה לכד יקר משושלת מינג המצוי בבעלותו, שיועבר לחזקתה ולבעלותה לאחר 30 יום כאמור. נחמה מסרה לנחמיה את המכונית. הגיעה העת שנחמיה יעמוד בחלקו בהסכם, אך הוא לא הודיע לנחמה על בחירתו תוך זמן סביר לפני מועד הקיום. מה הדין?', 'שאלה זו בוחנת את הכלל הקבוע בסעיף 51(א) לחוק החוזים (חלק כללי) לעניין העברת זכות הבחירה בחיובים חלופיים מהחייב לנושה, במקרה שהחייב לא מימש את זכותו במועד.', 'סעיף 51(א) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''בחיובים חלופים רשאי החייב, בהודעה לנושה תוך תקופה שנקבעה לכך, ובאין תקופה כזו – תוך זמן סביר לפני המועד לקיום, לבחור את החיוב שיקיים; לא עשה זאת, רשאי הנושה, בהודעה לחייב, לבחור את החיוב''. במקרה הנדון, נחמיה הוא החייב, והוא לא הודיע על בחירתו במועד. לכן, זכות הבחירה עוברת לנחמה, הנושה, והיא רשאית לבחור איזה חיוב נחמיה יקיים. הפסיקה והספרות המשפטית מדגישות כי מטרת הסעיף היא למנוע מצב של אי-ודאות ולשמור על קיום החוזה. סעיף 51(א) לחוק החוזים (חלק כללי) | בחירה בין חיובים חלופים',
    'הטעות הנפוצה היא לחשוב שאי-בחירה של החייב מבטלת את החוזה או משנה את מהותו, במקום להבין שהיא רק מעבירה את זכות הבחירה לצד השני.', '["חיובים חלופיים", "זכות בחירה", "הודעה לנושה", "זמן סביר", "חוק החוזים סעיף 51(א)", "קיום חוזה"]'::jsonb, '**וריאציה 1 — מועד ההודעה של הנושה:** אם זכות הבחירה עברה לנחמה, תוך כמה זמן עליה להודיע על בחירתה? ← גם הנושה מוגבל בזמן ההודעה שלו, ועליו לעשותה תוך זמן סביר לפני הזמן שנקבע לביצוע החיוב הראשון, אלא אם כן קבעו הצדדים אחרת (פרידמן וכהן, חוזים, כרך ד'', עמ'' 21).
**וריאציה 2 — בחירה חד פעמית:** האם הבחירה של נחמה היא חד פעמית? ← כן, אם הנושה בחר באפשרות קיום אחת, שוב אין הוא רשאי לחזור בו (ללא הסכמת החייב), ולבצע את האפשרות השנייה (פרידמן וכהן, חוזים, כרך ד'', עמ'' 21).
**וריאציה 3 — השפעת אי-הודעה על החייב:** האם אי-הודעה של החייב מהווה הפרת חוזה? ← אי-הודעה במועד אינה הפרה כשלעצמה, אלא רק מעבירה את זכות הבחירה לנושה. הפרה תתרחש אם החייב יסרב לקיים את החיוב שנבחר על ידי הנושה (ע"א 8336/17 ראובן נ'' סופר-דוש בע"מ).', 'חייב לא בחר במועד ← זכות הבחירה עוברת לנושה ← הנושה בוחר ומחייב את החייב (סעיף 51(א) לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 51(א)", "דניאל פרידמן, נילי כהן חוזים - כרך ד'' (2011) | חיובים חלופיים", "ע\"א 8336/17 מיכאל ראובן נ'' סופר-דוש בע\"מ (15.05.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'זכות הבחירה עוברת לנחמה, והיא רשאית לבחור את החיוב שנחמיה יקיים.', true, 'תשובה זו נכונה. סעיף 51(א) לחוק החוזים (חלק כללי) קובע כי אם החייב לא בחר את החיוב שיקיים במועד, זכות הבחירה עוברת לנושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'החוזה בטל, שכן נחמיה לא מימש את זכות הבחירה במועד.', false, 'טענה זו שגויה. אי-מימוש זכות הבחירה על ידי החייב אינו מבטל את החוזה, אלא מעביר את זכות הבחירה לנושה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'נחמיה חייב לקיים את החיוב שערכו נמוך יותר, שכן הוא התרשל באי-הודעה.', false, 'טענה זו שגויה. החוק אינו קובע סנקציה של בחירה בחיוב בעל ערך נמוך יותר במקרה של אי-הודעה, אלא מעביר את זכות הבחירה לנושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'נחמה זכאית לפיצויים בלבד, שכן נחמיה הפר את חובת ההודעה.', false, 'טענה זו שגויה. אי-הודעה במועד אינה הופכת את החוזה לחוזה פיצויים בלבד, אלא מעבירה את זכות הבחירה לנושה, אשר יכולה לדרוש את קיום אחד החיובים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'בחירה בחיובים חלופיים בידי הנושה',
    2, 'נחמה התקשרה בחוזה עם נחמיה. על פי ההסכם נחמה תמכור לנחמיה את מכונית הספורט האדומה שלה. בחוזה נקבע במפורש כי נחמה (הנושה) היא זו שתבחר אם לקבל מנחמיה מיליון ש"ח או את הכד היקר, וכי עליה להודיע על בחירתה תוך 3 ימים ממועד המסירה. נחמה מסרה את המכונית, אך לא הודיעה על בחירתה תוך 3 ימים. מה הדין?', 'שאלה זו עוסקת במצב שבו זכות הבחירה בחיובים חלופיים נתונה לנושה על פי הסכמה חוזית, ובתוצאות אי-מימוש זכות זו במועד הקבוע, בהתאם לסעיף 51(ב) לחוק החוזים (חלק כללי).', 'סעיף 51(ב) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''הוסכם כי זכות הבחירה תהיה בידי הנושה והוא לא השתמש בה תוך התקופה שנקבעה לכך, ובאין תקופה כזו – תוך זמן סביר לפני המועד לקיום, רשאי החייב, בהודעה לנושה, לבחור את החיוב''. במקרה הנדון, הוסכם שנחמה (הנושה) תבחר, אך היא לא הודיעה על בחירתה תוך 3 ימים כפי שנקבע. לכן, זכות הבחירה עוברת לנחמיה, החייב, והוא רשאי לבחור איזה חיוב יקיים. הוראה זו משלימה את סעיף 51(א) ומבטיחה שהחוזה יקוים גם אם הצד שהוקנתה לו זכות הבחירה לא מימש אותה במועד. סעיף 51(ב) לחוק החוזים (חלק כללי) | בחירה בין חיובים חלופים',
    'הטעות הנפוצה היא להניח שזכות הבחירה תמיד נתונה לחייב, או שהיא נשארת בידי הנושה גם אם לא מימש אותה במועד, מבלי להתחשב בהוראה הספציפית של סעיף 51(ב).', '["חיובים חלופיים", "זכות בחירה לנושה", "העברת זכות בחירה", "מועד הודעה", "חוק החוזים סעיף 51(ב)", "הסכמה חוזית"]'::jsonb, '**וריאציה 1 — זמן סביר:** מהו ''זמן סביר'' בהקשר זה? ← זמן סביר מושפע ממכלול הנסיבות האופפות את העסקה: מהותה, היקף ועלות ההכנות שיש לעשות לפני ביצועה וכדומה (איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 147).
**וריאציה 2 — הודעה לחייב:** אם זכות הבחירה עברה לנחמיה, האם עליו להודיע לנחמה על בחירתו? ← כן, סעיף 51(ב) קובע כי החייב רשאי לבחור ''בהודעה לנושה'' (סעיף 51(ב) לחוק החוזים (חלק כללי)).
**וריאציה 3 — התנאה על סעיף 51:** האם הצדדים יכולים להתנות על הוראות סעיף 51? ← כן, סעיף 51 הוא דיספוזיטיבי, והצדדים רשאים להתנות עליו בחוזה (ע"א 45599-01-13 פונז אחזקות בע"מ נ'' בנק לאומי לישראל בע"מ).', 'נושה לא בחר במועד (כשהבחירה בידיו) ← זכות הבחירה עוברת לחייב ← החייב בוחר ומחייב את הנושה (סעיף 51(ב) לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 51(ב)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 51 - בחירה בין חיובים חלופים", "ע\"א (מחוזי ת\"א) 45599-01-13 פונז אחזקות בע\"מ נ'' בנק לאומי לישראל בע\"מ -סניף קרית אונו (04.04.2014)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'זכות הבחירה עוברת לנחמיה, והוא רשאי לבחור את החיוב שיקיים.', true, 'תשובה זו נכונה. סעיף 51(ב) לחוק החוזים (חלק כללי) קובע כי אם הוסכם שזכות הבחירה תהיה בידי הנושה והוא לא השתמש בה במועד, זכות הבחירה עוברת לחייב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'החוזה בטל, שכן נחמה לא מימשה את זכות הבחירה במועד.', false, 'טענה זו שגויה. אי-מימוש זכות הבחירה על ידי הנושה אינו מבטל את החוזה, אלא מעביר את זכות הבחירה לחייב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'נחמיה חייב לקיים את החיוב שערכו גבוה יותר, שכן נחמה התרשלה באי-הודעה.', false, 'טענה זו שגויה. החוק אינו קובע סנקציה של בחירה בחיוב בעל ערך גבוה יותר במקרה של אי-הודעה מצד הנושה, אלא מעביר את זכות הבחירה לחייב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'נחמה זכאית לפיצויים בלבד, שכן היא הפרה את חובת ההודעה.', false, 'טענה זו שגויה. אי-הודעה במועד אינה הופכת את החוזה לחוזה פיצויים בלבד, אלא מעבירה את זכות הבחירה לחייב, אשר יכול לקיים את אחד החיובים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סיכול אחת החלופות בחוזה חלופין',
    3, 'נחמה התקשרה בחוזה עם נחמיה. על פי ההסכם נחמה תמכור לנחמיה את מכונית הספורט האדומה שלה בתמורה למיליון ש"ח, שנחמיה ישלם לה לאחר 30 יום ממועד המסירה של המכונית, או בתמורה לכד יקר משושלת מינג המצוי בבעלותו, שיועבר לחזקתה ולבעלותה לאחר 30 יום כאמור. נחמה מסרה לנחמיה את המכונית. לפני מועד הקיום, הכד נשבר לרסיסים בתאונה שאינה באשמת נחמיה. מה הדין?', 'שאלה זו בוחנת את הדין החל על חוזה חלופין כאשר אחת מחלופות הקיום סוכלה או הפכה לבלתי אפשרית, ומדגישה כי במקרה כזה, החוזה הופך לחוזה רגיל עם החלופה שנותרה, והחייב נושא בסיכון.', 'הלכה פסוקה היא כי כאשר נופלת אחת מחלופות הקיום שבחוזה חלופין, שעה שחלופה מוסכמת אחרת בעינה עומדת, חייב בעל האופציה לקיים את חיוביו בדרך שנותרה פתוחה לפניו. למעשה, החוזה חדל מלהיות חוזה חלופין והופך לחוזה רגיל הנעדר אפשרות בחירה. העובדה שאחת מן החלופות אינה מעשית עוד, לא הופכת את החוזה כולו לבלתי מעשי ולא פוטרת את בעל האופציה מהחובה לקיים את החוזה בדרך שנותרה אפשרית. במובן זה, בעל הברירה בחוזה החלופין נושא בסיכון שאחת האלטרנטיבות תתגלה כבלתי מעשית, והוא ייאלץ לקיים את האחרת. כך נקבע בע"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע"מ נ'' מנהל מס שבח מקרקעין, נתניה. ע"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע"מ נ'' מנהל מס שבח מקרקעין, נתניה (10.11.1993)',
    'הטעות הנפוצה היא לחשוב שסיכול אחת החלופות בחוזה חלופין מוביל לבטלות החוזה כולו, במקום להבין שהחוזה נשאר תקף ביחס לחלופה שנותרה.', '["חוזה חלופין", "סיכול חיוב", "אחריות לסיכון", "קיום חיוב", "חוק החוזים סעיף 51", "בטלות חוזה"]'::jsonb, '**וריאציה 1 — סיכול באשמת החייב:** מה הדין אם הכד נשבר באשמת נחמיה? ← אם אחד ממושאי העסקה אבד או התקלקל באשמת החייב לפני הפעלת הברירה, מצטמצמת החבות לדרך שנותרה פתוחה, והנושה יכול לתבוע פיצויים בשל חסימת הדרך האחרת (פרידמן וכהן, חוזים, כרך ד'', עמ'' 21).
**וריאציה 2 — סיכול באשמת הנושה:** מה הדין אם הכד נשבר באשמת נחמה? ← אם הנושה אחראי לאבדן או לקלקול, והברירה הייתה בידיו, מצטמצם החיוב לנכס שנותר, והנושה יפצה את החייב (פרידמן וכהן, חוזים, כרך ד'', עמ'' 21).
**וריאציה 3 — תחליף קיום:** האם סעיף 52 לחוק החוזים (תחליף קיום) רלוונטי כאן? ← סעיף 52 עוסק במצב שבו קיום חיוב נעשה בלתי אפשרי, ולחייב יש זכות לפיצוי או שיפוי מצד שלישי. במקרה זה, החייב צריך להעביר לנושה את הזכות או מה שקיבל על פיה (סעיף 52 לחוק החוזים (חלק כללי)).', 'אחת החלופות בחוזה חלופין סוכלה ← החייב חייב לקיים את החלופה שנותרה ← החוזה הופך לרגיל (ע"א 133/89 חוף התכלת).',
    '["ע\"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע\"מ נ'' מנהל מס שבח מקרקעין, נתניה (10.11.1993)", "דניאל פרידמן, נילי כהן חוזים - כרך ד'' (2011) | חיובים חלופיים", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 52"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'החוזה בטל, שכן אחת החלופות סוכלה, ואין אפשרות בחירה.', false, 'טענה זו שגויה. סיכול אחת החלופות אינו מבטל את החוזה כולו, אלא מצמצם את הבחירה לחלופה שנותרה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'נחמיה חייב לקיים את החלופה שנותרה, קרי, לשלם לנחמה מיליון ש"ח.', true, 'תשובה זו נכונה. כאשר אחת מחלופות הקיום בחוזה חלופין נופלת, החוזה חדל מלהיות חוזה חלופין והופך לחוזה רגיל הנעדר אפשרות בחירה, והחייב חייב לקיים את החלופה שנותרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'נחמיה פטור מקיום החוזה, שכן לא נותרה לו זכות בחירה.', false, 'טענה זו שגויה. העובדה שאחת החלופות אינה מעשית עוד, לא פוטרת את בעל האופציה מהחובה לקיים את החוזה בדרך שנותרה אפשרית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'נחמה זכאית לפיצויים בגין הנזק שנגרם לכד, בנוסף לקיום החלופה הכספית.', false, 'טענה זו שגויה. הנזק לכד אינו באשמת נחמיה, ולכן הוא אינו חייב בפיצויים בגינו. חובתו היא לקיים את החלופה שנותרה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הבחנה בין חוזה אופציה לחוזה חלופין',
    4, 'מהו ההבדל המהותי בין ''חוזה אופציה'' לבין ''חוזה חלופין''?', 'שאלה זו עוסקת בהבחנה קריטית בין ''חוזה אופציה'' ל''חוזה חלופין'', שני מונחים בעלי מאפיינים דומים אך מהות משפטית שונה, כפי שפורש בפסיקת בית המשפט העליון.', 'ההבחנה בין חוזה אופציה לחוזה חלופין היא מהותית. בבסיס ''חוזה האופציה'' מונחת יכולת בחירה דו-כיוונית – הבחירה בין התקשרות לבין אי-התקשרות בעיסקה העיקרית נושא האופציה. חוזה האופציה הוא מעין חוזה משני הנספח לחוזה נוסף ועיקרי, אשר משתכלל אם, ורק אם, האופציה ממומשת. בעל האופציה יכול לבחור שלא לממש אותה, ובמקרה זה לא נכרתה בין הצדדים העיסקה העיקרית. לעומת זאת, ''חוזה חלופין'' (alternative contracts) הוא חוזה שבו ניתנת לאחד הצדדים הבחירה בין שתי דרכי קיום אלטרנטיביות של חיוב קיים. מרגע שנקשר ההסכם, קמה חובה לקיים את החיוב, בין בדרך האחת ובין בדרך האחרת, ללא זכות בחירה שלא לקיים את העיסקה כלל. כך הובהר בע"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע"מ נ'' מנהל מס שבח מקרקעין, נתניה. ע"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע"מ נ'' מנהל מס שבח מקרקעין, נתניה (10.11.1993)',
    'הטעות הנפוצה היא לבלבל בין חוזה אופציה, המעניק בחירה אם לכרות חוזה, לבין חוזה חלופין, המעניק בחירה כיצד לקיים חיוב בחוזה שכבר נכרת.', '["חוזה אופציה", "חוזה חלופין", "בחירה בין התקשרות", "בחירה בין דרכי קיום", "חיובים חלופיים", "חוק החוזים סעיף 51"]'::jsonb, '**וריאציה 1 — סעיף 51 לחוק החוזים:** איזה סוג חוזה מתואר בסעיף 51 לחוק החוזים? ← סעיף 51 עוסק ב''בחירה בין חיובים חלופים'', כלומר בחוזה חלופין (סעיף 51 לחוק החוזים (חלק כללי)).
**וריאציה 2 — חוזה כלאיים:** האם ייתכן ''חוזה כלאיים'' המשלב מאפיינים של אופציה וחלופין? ← כן, המציאות מספקת דוגמאות של מצבי ביניים, וניתן לפרש חוזה ככזה המשלב מאפיינים של שניהם (ת"א (מחוזי ת"א) 1599-05 ישרופ מלונות ונופש בע"מ נ'' מלון עדי אילת בע"מ).
**וריאציה 3 — מסוימות:** האם דרישת המסוימות שונה בין חוזה אופציה לחוזה חלופין? ← בשני המקרים נדרשת מסוימות מספקת. בחוזה אופציה, המסוימות צריכה להתייחס לפרטי העסקה העיקרית שתיכרת אם האופציה תמומש. בחוזה חלופין, המסוימות צריכה להתייחס לפרטי כל אחת מהחלופות (ע"א 133/89 חוף התכלת).', 'חוזה אופציה ← בחירה אם להתקשר בחוזה ← חוזה חלופין ← בחירה כיצד לקיים חיוב קיים (ע"א 133/89 חוף התכלת).',
    '["ע\"א 133/89 החברה לפיתוח חוף התכלת (תל-אביב-הרצליה) בע\"מ נ'' מנהל מס שבח מקרקעין, נתניה (10.11.1993)", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 51", "ת\"א (מחוזי ת\"א) 1599-05 ישרופ מלונות ונופש בע\"מ נ'' מלון עדי אילת בע\"מ (27.06.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'חוזה אופציה מעניק בחירה בין התקשרות לבין אי-התקשרות בעיסקה העיקרית, בעוד חוזה חלופין מעניק בחירה בין שתי דרכי קיום אלטרנטיביות של חיוב קיים.', true, 'תשובה זו נכונה. זהו ההבדל המהותי והמובהק בין שני סוגי החוזים, כפי שהובהר בפסיקה ובספרות המשפטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'חוזה אופציה הוא תמיד חוזה משני, בעוד חוזה חלופין הוא תמיד חוזה עיקרי.', false, 'טענה זו שגויה. חוזה אופציה הוא אכן חוזה משני הנספח לחוזה עיקרי, אך חוזה חלופין הוא חוזה עיקרי לכל דבר ועניין, המכיל בתוכו את אפשרויות הקיום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בחוזה אופציה זכות הבחירה נתונה תמיד לחייב, בעוד בחוזה חלופין היא נתונה תמיד לנושה.', false, 'טענה זו שגויה. בחוזה אופציה זכות הבחירה נתונה לבעל האופציה (שיכול להיות החייב או הנושה), ובחוזה חלופין זכות הבחירה נתונה לחייב ככלל, אלא אם הוסכם אחרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'חוזה אופציה דורש מסוימות גבוהה יותר מחוזה חלופין.', false, 'טענה זו שגויה. שני סוגי החוזים דורשים עמידה ביסודות גמירת הדעת והמסוימות, ואין הבדל מהותי בדרישת המסוימות ביניהם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 34, '2019-S-S-Q34';
END
$$;

-- ============================================================
-- Q35 — 2019-S-S-Q35 — chapter=contracts subtopic=general_part
-- classifier_note: Third-party performance of obligation — Rembrandt painting / 30M payment
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b10822f4-e186-4e11-b17b-98e2e6a47553'::uuid;
  v_group_id uuid := '77ce6571-ba28-4f28-b06e-faa92a14ba72'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '37872c15-2cc4-4afd-99c1-e9bb6823321b'::uuid;
  v_ang_1 uuid := '737bf141-0181-421a-afca-51bde53991e4'::uuid;
  v_ang_2 uuid := '577ec0a7-2d0d-45c7-9b39-f23e99fdd4cc'::uuid;
  v_ang_3 uuid := 'd57a5350-1d03-4b7f-b86d-e0279f5261ca'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q35';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 35, '2019-S-S-Q35';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q35', v_chapter_id, v_subtopic_id, 'דגנית התחייבה לשלם לסאשה 30 מיליון ש"ח תמורת תמונה של רמברנדט. כשהגיע מועד התשלום הגיע נחי לסאשה ומסר לה כי הוא זה שישלם לה את התמורה, והתמונה תועבר לדגנית, כמוסכם. סאשה המופתעת התקשרה לדגנית שאישרה שאכן כך. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 35}'::jsonb, 'השאלה עוסקת בעקרון ''קיום חיוב בידי אחר'' הקבוע בסעיף 40 לחוק החוזים (חלק כללי), התשל"ג-1973. היא בוחנת את הכלל לפיו חיוב יכול שיקויים על ידי אדם שאינו החייב, אלא אם כן מהות החיוב או הסכמת הצדדים מחייבת קיום אישי, ומדגישה כי חיוב כספי אינו נחשב לחיוב אישי.', 'סעיף 40 לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''חיוב יכול שיקויים בידי אדם שאיננו החייב, זולת אם לפי מהות החיוב, או לפי המוסכם בין הצדדים, על החייב לקיימו אישית''. כלומר, נקודת המוצא בדין הישראלי היא שאין חובה על החייב לקיים את חיוביו בעצמו, אלא אם כן מדובר בחיוב אישי. חיוב כספי, כמו תשלום 30 מיליון ש"ח, אינו נחשב לחיוב אישי במהותו, ואין חשיבות לזהות המשלם. לכן, נחי יכול לשלם את התמורה במקום דגנית, ואין צורך בהסכמת סאשה לכך, כל עוד החיוב אינו אישי. העובדה שדגנית אישרה את התשלום על ידי נחי רק מחזקת את הלגיטימיות של הקיום בידי אחר. סעיף 40 לחוק החוזים (חלק כללי) | קיום – בידי מי', 'הטעות הנפוצה היא להניח שכל חיוב חוזי דורש קיום אישי על ידי החייב, או שקיום בידי אחר דורש הסכמה מפורשת של הנושה, מבלי להבחין בין חיובים אישיים ללא-אישיים.',
    '["קיום חיוב בידי אחר", "חיוב אישי", "חיוב כספי", "סעיף 40 לחוק החוזים", "הסכמת הנושה", "מהות החיוב"]'::jsonb, '**וריאציה 1 — אחריות החייב המקורי:** אם נחי היה משלם פחות מהסכום המוסכם, האם דגנית עדיין הייתה אחראית ליתרה? ← כן, קיום בידי אחר אינו משחרר את החייב המקורי מאחריותו, אלא אם כן מדובר בהמחאת חבות (ת"א (מחוזי חי'') 8463-04-22 עזבון המנוח דאוד גיריס נ'' רוגינה גרייס).
**וריאציה 2 — סירוב הנושה:** מה הדין אם סאשה הייתה מסרבת לקבל את התשלום מנחי, למרות שאינו חיוב אישי? ← סירוב בלתי סביר של הנושה לקבל קיום מזר, כאשר החיוב אינו אישי, עלול להיחשב כהפרת חוזה מצד הנושה (איל זמיר, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 121).
**וריאציה 3 — התנאה על סעיף 40:** האם הצדדים יכולים להתנות על סעיף 40 ולקבוע שגם חיוב כספי יקוים אישית? ← כן, סעיף 40 הוא דיספוזיטיבי, והצדדים רשאים להתנות עליו בחוזה (איל זמיר, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 120).', 'חיוב כספי ← אינו חיוב אישי ← יכול להתקיים בידי אחר ← ללא צורך בהסכמת הנושה (סעיף 40 לחוק החוזים).', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 40", "ת\"א (מחוזי חי'') 8463-04-22 עזבון המנוח דאוד גיריס נ'' רוגינה גרייס (13.11.2025)", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 40 - קיום - בידי מי"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Third-party performance of obligation — Rembrandt painting / 30M payment | source_review_note: השאלה עוסקת בדיני חוזים (קיום חיובים), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דיני חיובים כרוכים בהתחייבויות אישיות. שעה שדגנית התחייבה לשלם את הסכום, עליה לעשות זאת בעצמה.', false, 'טענה זו שגויה. הכלל הוא שחיוב אינו כרוך בהתחייבות אישית, אלא אם כן נקבע אחרת במפורש או משתמע ממהות החיוב. חיוב כספי אינו נחשב לחיוב אישי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דיני חיובים כרוכים בהתחייבויות אישיות. רק אם סאשה תסכים שנחי ישלם לה את התמורה ניתן יהיה לעשות כן.', false, 'טענה זו שגויה. סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יכול שיקויים בידי אדם שאינו החייב, ואין צורך בהסכמת הנושה, אלא אם כן מדובר בחיוב אישי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דיני חיובים כרוכים בהתחייבויות אישיות, בכפוף להסכמות הצדדים. היה על הצדדים להסדיר את הנושא מראש, ולקבוע כי תשלום התמורה יוכל להתבצע על ידי צד שלישי. משלא עשו כן, על דגנית לשלם לסאשה את התמורה בעצמה.', false, 'טענה זו שגויה. סעיף 40 לחוק החוזים (חלק כללי) קובע כלל דיספוזיטיבי לפיו חיוב יכול שיקויים בידי אדם שאינו החייב, אלא אם כן נקבע אחרת או שהחיוב אישי במהותו. אין צורך בהסדרה מראש כדי לאפשר קיום בידי אחר בחיוב שאינו אישי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות העניין יוכל נחי לשלם את התמורה אלא אם לפי מהות החיוב על דגנית לשלם את התמורה בעצמה.', true, 'תשובה זו נכונה. סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יכול שיקויים בידי אדם שאינו החייב, אלא אם כן לפי מהות החיוב או לפי המוסכם בין הצדדים, על החייב לקיימו אישית. חיוב כספי, כמו במקרה זה, אינו נחשב לחיוב אישי במהותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הבחנה בין קיום בידי אחר להמחאת חבות',
    1, 'דגנית התחייבה לשלם לסאשה 30 מיליון ש"ח. נחי הגיע לסאשה ואמר לה שהוא לוקח על עצמו את החוב של דגנית, וכי דגנית אינה חייבת לה יותר. סאשה הסכימה לכך במפורש. נחי לא שילם את החוב. האם סאשה יכולה לתבוע את דגנית?', 'שאלה זו מדגישה את ההבחנה המהותית בין ''קיום חיוב בידי אחר'' לפי סעיף 40 לחוק החוזים (חלק כללי), לבין ''המחאת חבות'' לפי סעיף 6 לחוק המחאת חיובים, ובפרט את השלכותיה על אחריות החייב המקורי.', 'סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יכול שיקויים בידי אדם שאינו החייב, אלא אם כן מדובר בחיוב אישי. במקרה כזה, החייב המקורי נותר אחראי לקיום החיוב. לעומת זאת, ''המחאת חבות'' (או ''המחאת חוב'') היא העברת חוב מצד אחד (החייב המקורי) לצד שלישי (החייב החדש), בהסכמת הנושה, באופן שהחייב המקורי משתחרר מהחבות. סעיף 6 לחוק המחאת חיובים, התשכ"ט-1969, קובע כי ''חבותו של חייב ניתנת להמחאה, בהסכמת הנושה, לזולתו''. הסכמת הנושה צריכה להיות ברורה וחד משמעית, אך אינה טעונה צורה מסוימת. במקרה הנדון, סאשה הסכימה במפורש לכך שנחי ייקח על עצמו את החוב ודגנית תשתחרר, ולכן מדובר בהמחאת חבות. משמעות הדבר היא שדגנית יצאה מהתמונה וסאשה אינה יכולה לתבוע אותה. ת"א (מחוזי ת"א) 37454-07-17 ראוף עיסא נ'' אבו מנה טלאל (02.06.2019)',
    'הטעות הנפוצה היא לבלבל בין קיום חיוב בידי אחר (שאינו משחרר את החייב המקורי) לבין המחאת חבות (שמשחררת את החייב המקורי), במיוחד כאשר הנושה מסכים לשינוי.', '["קיום חיוב בידי אחר", "המחאת חבות", "סעיף 40 לחוק החוזים", "סעיף 6 לחוק המחאת חיובים", "אחריות החייב המקורי", "הסכמת הנושה"]'::jsonb, '**וריאציה 1 — הסכמת הנושה:** האם הסכמת הנושה נדרשת לקיום חיוב בידי אחר לפי סעיף 40? ← לא, אלא אם כן החיוב אישי במהותו או הוסכם אחרת. הסכמת הנושה נדרשת רק להמחאת חבות (ע"א 2138/10 מועצה מקומית דלית אל כרמל נ'' סונול ישראל בע"מ).
**וריאציה 2 — נטל ההוכחה:** על מי מוטל הנטל להוכיח שהנושה הסכים להמחאת חבות? ← על הצד הטוען להמחאת החבות, כלומר על החייב המקורי, וההסכמה צריכה להיות ברורה וחד משמעית (ת"א (מחוזי ת"א) 37454-07-17 ראוף עיסא נ'' אבו מנה טלאל).
**וריאציה 3 — המחאת זכות:** מה ההבדל בין המחאת חבות להמחאת זכות? ← המחאת חבות היא העברת חוב, הדורשת הסכמת הנושה. המחאת זכות היא העברת זכות (למשל, זכות לקבל כסף), ואינה דורשת את הסכמת החייב, אלא רק הודעה לו (חוק המחאת חיובים, סעיפים 1 ו-6).', 'קיום בידי אחר (סעיף 40) ← חייב מקורי נשאר אחראי. המחאת חבות (סעיף 6) ← חייב מקורי משתחרר ← דורש הסכמת נושה.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 40", "חוק המחאת חיובים, תשכ\"ט-1969, סעיף 6", "ת\"א (מחוזי ת\"א) 37454-07-17 ראוף עיסא נ'' אבו מנה טלאל (02.06.2019)", "ע\"א 2138/10 מועצה מקומית דלית אל כרמל נ'' סונול ישראל בע\"מ (16.02.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן לפי סעיף 40 לחוק החוזים (חלק כללי), החייב המקורי נותר תמיד אחראי לקיום החיוב, גם אם צד שלישי מקיים אותו.', false, 'טענה זו שגויה. סעיף 40 לחוק החוזים (חלק כללי) עוסק בקיום חיוב בידי אחר, שאינו משחרר את החייב המקורי. אולם, במקרה זה מדובר בהמחאת חבות, שבה החייב המקורי משתחרר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, שכן המחאת חבות דורשת הסכמה בכתב של הנושה, וזו לא ניתנה.', false, 'טענה זו שגויה. הסכמת הנושה להמחאת חבות אינה טעונה דרישה צורנית כלשהי, ויכולה להינתן גם בעל פה או בהתנהגות, ובלבד שהיא ברורה וחד משמעית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, שכן הסכמת סאשה לכך שנחי יקח על עצמו את החוב של דגנית, משמעותה המחאת חבות, ודגנית יצאה מהתמונה.', true, 'תשובה זו נכונה. כאשר הנושה מסכים לכך שצד שלישי ייקח על עצמו את החוב במקום החייב המקורי, והחייב המקורי ישתחרר מהחבות, מדובר בהמחאת חבות לפי סעיף 6 לחוק המחאת חיובים, התשכ"ט-1969. במקרה כזה, החייב המקורי (דגנית) יוצא מהתמונה, והנושה (סאשה) אינה יכולה לתבוע אותו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שכן החוזה המקורי בין דגנית לסאשה בטל עקב שינוי מהותי בזהות החייב.', false, 'טענה זו שגויה. המחאת חבות אינה מבטלת את החוזה המקורי, אלא מחליפה את זהות החייב בו, בהסכמת הנושה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני חיוב אישי',
    2, 'מהם המבחנים לקביעה האם חיוב הוא ''אישי'' ואינו יכול להתקיים בידי אדם אחר, לפי סעיף 40 לחוק החוזים (חלק כללי)?', 'שאלה זו מתמקדת במבחנים המשפטיים לקביעת אופיו של חיוב כ''אישי'' או ''לא אישי'' לצורך סעיף 40 לחוק החוזים (חלק כללי), ומבהירה את הקריטריונים המנחים את בית המשפט בסוגיה זו.', 'סעיף 40 לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''חיוב יכול שיקויים בידי אדם שאיננו החייב, זולת אם לפי מהות החיוב, או לפי המוסכם בין הצדדים, על החייב לקיימו אישית''. המבחן לקביעה האם חיוב הוא אישי מתמקד בשאלה האם יש חשיבות לזהותו של המקיים, למיומנותו, לניסיונו, למוניטין שלו או לכישוריו המיוחדים. דוגמאות לחיובים אישיים כוללות שירותי עורך דין, רופא, אמן (כמו צייר דיוקנאות), או קבלן שנבחר בשל מוניטין וניסיון ספציפיים. לעומת זאת, חיובים כספיים או חיובים לביצוע פעולות סטנדרטיות שרבים מסוגלים לבצען ברמה דומה (כמו אספקת סחורה סטנדרטית) אינם נחשבים לחיובים אישיים. המבחן הוא אובייקטיבי-נסיבתי, ובוחן את אומד דעת הצדדים בעת כריתת החוזה. סעיף 40 לחוק החוזים (חלק כללי) | קיום – בידי מי',
    'הטעות הנפוצה היא להניח שכל חיוב שירות הוא אישי, מבלי לבחון את מהותו הספציפית ואת חשיבות זהות המבצע בעיני הצדדים.', '["חיוב אישי", "מהות החיוב", "הסכמת הצדדים", "מיומנות", "מוניטין", "סעיף 40 לחוק החוזים"]'::jsonb, '**וריאציה 1 — חיוב כספי:** האם חיוב כספי יכול להיות אישי? ← ככלל, חיוב כספי אינו אישי, וניתן לקיימו בידי אחר. אולם, הצדדים יכולים להסכים במפורש שהתשלום יבוצע רק על ידי החייב עצמו (פרידמן וכהן, חוזים, כרך ג'', עמ'' 409).
**וריאציה 2 — חיוב עשייה סטנדרטי:** האם חיוב עשייה שתוצאתו סטנדרטית הוא אישי? ← לא, בחיובי עשייה שבהם התוצאה סטנדרטית, הנטייה היא להניח שלא נדרש קיום אישי (איל זמיר, חוק חוזה הקבלנות, עמ'' 6).
**וריאציה 3 — חובת סודיות:** האם חובת סודיות יכולה להפוך חיוב לאישי? ← כן, הטלת חובת סודיות על החייב, במידה שקיומה אינו מתיישב עם שיתוף אנשים אחרים בביצוע, יכולה להוות איסור משתמע על קיום בידי אחר (איל זמיר, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 121).', 'חיוב אישי ← חשיבות לזהות המקיים, מיומנות, ניסיון, מוניטין ← לפי מהות החיוב או הסכמת הצדדים (סעיף 40 לחוק החוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 40", "דניאל פרידמן, נילי כהן חוזים - כרך ג'' (2003) | קיום על ידי צד שלישי", "איל זמיר חוק חוזה הקבלנות, תשל\"ד-1974 פירוש לחוקי החוזים (1974) | זהות המקיים", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 40 - קיום - בידי מי", "ת\"א (מחוזי מרכז) 64470-11-19 גיל מלמד נ'' ירדן מורי (09.12.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם החיוב הוא חיוב כספי, שכן חיובים כספיים תמיד ניתנים לקיום בידי אחר.', false, 'טענה זו שגויה חלקית. חיובים כספיים אכן ניתנים בדרך כלל לקיום בידי אחר, אך זהו אינו המבחן היחיד או המכריע לחיוב אישי, והוא אינו חל על כל סוגי החיובים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם לפי מהות החיוב או לפי המוסכם בין הצדדים, יש חשיבות לזהותו של המקיים, למיומנותו, לניסיונו או למוניטין שלו.', true, 'תשובה זו נכונה. סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יקוים אישית אם כך עולה ממהות החיוב או מהסכמת הצדדים. הפסיקה והספרות מפרשות זאת כמתייחס למקרים בהם יש חשיבות מיוחדת לזהות, לכישורים, למומחיות או למוניטין של החייב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם החיוב הוא חיוב מורכב או דורש השקעת זמן רב.', false, 'טענה זו שגויה. מורכבות או היקף החיוב אינם הופכים אותו בהכרח לחיוב אישי. גם חיובים מורכבים יכולים להתבצע על ידי אחרים, כל עוד אין חשיבות לזהות המבצע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם הנושה סירב לקבל את קיום החיוב מידי צד שלישי.', false, 'טענה זו שגויה. סירוב הנושה אינו קובע אם החיוב הוא אישי, אלא הוא תוצאה של קביעה כזו. אם החיוב אינו אישי, סירוב הנושה לקבל קיום מצד שלישי עלול להיחשב כהפרת חוזה מצדו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'קיום חיוב אישי על ידי אחר',
    3, 'דגנית, ציירת מפורסמת, התחייבה לצייר דיוקן של סאשה. עקב מחלה פתאומית, דגנית ביקשה מנחי, עוזרת מוכשרת שלה, לצייר את הדיוקן במקומה. נחי ציירה את הדיוקן ברמה גבוהה מאוד. סאשה סירבה לקבל את הדיוקן ולשלם, בטענה שדגנית לא קיימה את החיוב אישית. מה הדין?', 'שאלה זו בוחנת את ההשלכות של קיום חיוב אישי בידי אדם אחר, ומבהירה כי במקרים כאלה, הנושה רשאי לסרב לקבל את הביצוע, שכן עצם זהות המבצע היא חלק מהותי מהחיוב.', 'כאשר חיוב הוא אישי במהותו, כגון ציור דיוקן על ידי אמן ספציפי, זהות המבצע היא מרכיב קריטי בחוזה. סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יקוים אישית אם כך עולה ממהות החיוב. במקרה כזה, קיום החיוב בידי אדם אחר, גם אם הוא מוכשר, מהווה הפרה של החוזה. הנושה (סאשה) זכאית לסרב לקבל את הביצוע מצד שלישי (נחי), וזאת גם אם התוצאה איכותית. סירוב כזה אינו נחשב להפרה מצד הנושה, אלא מימוש זכותה לקבל את הביצוע מהחייב הספציפי שאיתו התקשרה. במצב כזה, עומדות לסאשה התרופות הרגילות בגין הפרת חוזה, כגון ביטול החוזה ופיצויים. דניאל פרידמן, נילי כהן חוזים - כרך ד'' (2011) | קיום על ידי צד שלישי',
    'הטעות הנפוצה היא להתמקד בתוצאת הביצוע (האם היא איכותית) במקום בזהות המבצע, כאשר מדובר בחיוב אישי.', '["חיוב אישי", "הפרת חוזה", "סעיף 40 לחוק החוזים", "זכות סירוב", "תרופות בגין הפרה", "זהות המבצע"]'::jsonb, '**וריאציה 1 — חיוב אישי יחסי:** האם חובת קיום אישי היא תמיד מוחלטת? ← לא, לעיתים היא יחסית, וייתכן שתידרש עזרה של אנשים נוספים. אולם, עדיין נשמרת חשיבות לזהות החייב הראשי (איל זמיר, חוק חוזה הקבלנות, עמ'' 6).
**וריאציה 2 — פיצויים בגין הפרה:** אם סאשה סירבה לקבל את הדיוקן, האם היא זכאית לפיצויים? ← כן, היא זכאית לתרופות הרגילות בגין הפרת חוזה, לרבות פיצויים, גם אם לא נגרם לה נזק נוסף מעבר לאי-קיום אישי (איל זמיר, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 121).
**וריאציה 3 — הסכמת הנושה:** מה הדין אם סאשה הייתה מסכימה לביצוע על ידי נחי? ← אם הנושה מסכים לביצוע על ידי צד שלישי, גם בחיוב אישי, החיוב יקוים כדין, והחייב המקורי ישתחרר מאחריותו (סעיף 40 לחוק החוזים (חלק כללי)).', 'חיוב אישי (כמו ציור דיוקן) ← קיום בידי אחר מהווה הפרה ← הנושה רשאי לסרב לקבל (פרידמן וכהן, חוזים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 40", "דניאל פרידמן, נילי כהן חוזים - כרך ד'' (2011) | קיום על ידי צד שלישי", "איל זמיר חוק חוזה הקבלנות, תשל\"ד-1974 פירוש לחוקי החוזים (1974) | זהות המקיים", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 40 - קיום - בידי מי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'סאשה חייבת לקבל את הדיוקן ולשלם, שכן התוצאה איכותית ואין לה נזק.', false, 'טענה זו שגויה. איכות הביצוע אינה רלוונטית כאשר מדובר בחיוב אישי. הנושה זכאי לקבל את הביצוע מהחייב הספציפי שאיתו התקשר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'סאשה רשאית לסרב לקבל את הדיוקן, שכן חיוב לציור דיוקן הוא חיוב אישי, וקיומו בידי אחר מהווה הפרת חוזה, גם אם התוצאה איכותית.', true, 'תשובה זו נכונה. ציור דיוקן על ידי אמן ספציפי הוא דוגמה מובהקת לחיוב אישי. קיום חיוב אישי בידי אדם אחר, גם אם הוא מוכשר, מהווה הפרה של החוזה, והנושה רשאי לסרב לקבל את הביצוע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'סאשה חייבת לקבל את הדיוקן, אך זכאית לפיצויים בגין עוגמת נפש על אי-קיום אישי.', false, 'טענה זו שגויה. במקרה של הפרת חיוב אישי, הנושה אינו חייב לקבל את הביצוע מצד שלישי, וזכאי לתרופות בגין הפרה, לרבות ביטול החוזה ופיצויים, ולא רק פיצויים על עוגמת נפש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'החוזה בטל עקב סיכול, שכן דגנית חלתה ולא יכלה לקיים את החיוב אישית.', false, 'טענה זו שגויה. מחלה אינה בהכרח סיכול. גם אם הייתה סיכול, התוצאה היא פקיעת החוזה, אך השאלה מתייחסת לביצוע בפועל על ידי צד שלישי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'קיום חיוב על ידי צד שלישי ללא הסכמת החייב',
    4, 'דגנית חייבת לסאשה 30 מיליון ש"ח. נחי, חבר של דגנית, שילם לסאשה את החוב, ללא ידיעתה או הסכמתה של דגנית. סאשה קיבלה את התשלום. האם נחי זכאי להשבה מדגנית?', 'שאלה זו עוסקת במצב שבו צד שלישי מקיים חיוב של חייב כלפי נושה, ללא הסכמת החייב, ובזכותו של אותו צד שלישי להשבה מכוח דיני עשיית עושר ולא במשפט.', 'סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יכול שיקויים בידי אדם שאינו החייב, אלא אם כן מדובר בחיוב אישי. חיוב כספי אינו חיוב אישי. במקרה זה, נחי שילם את חובה של דגנית לסאשה, וסאשה קיבלה את התשלום. בכך, החוב של דגנית לסאשה נפרע, ודגנית התעשרה על חשבונו של נחי. גם אם נחי פעל ללא ידיעתה או הסכמתה של דגנית, קמה לו עילה להשבה מכוח דיני עשיית עושר ולא במשפט, שכן דגנית התעשרה שלא כדין על חשבונו. הפירוש המקובל לסעיף 40 הוא שכל צד שלישי יכול לפרוע חיוב שאינו אישי, גם אם לא התבקש לכך על ידי החייב ואולי אף חרף התנגדותו. דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך א (2015) | פירעון חוב של הזולת',
    'הטעות הנפוצה היא לחשוב שפעולה ללא הסכמת החייב שוללת אוטומטית את הזכות להשבה, מבלי להתחשב בעקרונות עשיית עושר ולא במשפט.', '["קיום חיוב בידי אחר", "עשיית עושר ולא במשפט", "השבה", "סעיף 40 לחוק החוזים", "חיוב כספי", "התעשרות שלא כדין"]'::jsonb, '**וריאציה 1 — סירוב הנושה:** מה הדין אם סאשה הייתה מסרבת לקבל את התשלום מנחי? ← אם הנושה מסרב לקבל קיום מזר, הוא אינו חייב לעשות כן, והחוב לא נפרע. במקרה כזה, נחי לא היה זכאי להשבה מדגנית (פרידמן, דיני עשיית עושר ולא במשפט, עמ'' 7).
**וריאציה 2 — זכות חזרה של ערב:** מה הדין אם נחי היה ערב לחובה של דגנית? ← אם נחי היה ערב, הוא היה זכאי לחזור אל דגנית ולהיפרע ממנה כדין ערב שמילא את ערבותו, מכוח חוק הערבות (סעיף 14 לחוק המשכון, תשכ"ז-1967, בהקשר של פדיון משכון על ידי מי שאינו החייב).
**וריאציה 3 — קיום בתום לב:** האם נחי חייב לפעול בתום לב? ← כן, גם צד שלישי המקיים חיוב חייב לפעול בתום לב, כפי שנדרש מהחייב עצמו (איל זמיר, הפירוש הקצר לחוקים במשפט הפרטי, עמ'' 122).', 'צד שלישי קיים חיוב לא אישי ללא הסכמת חייב ← נושה קיבל ← חייב התעשר ← צד שלישי זכאי להשבה (דיני עשיית עושר).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 40", "דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך א (2015) | פירעון חוב של הזולת", "חוק המשכון, תשכ\"ז-1967, סעיף 14", "איל זמיר, מרדכי א'' ראבילו, גבריאלה שלו הפירוש הקצר לחוקים במשפט הפרטי (1996) | סעיף 40 - קיום - בידי מי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, כי נחי פעל ללא הסכמת דגנית, ולכן אין לו עילה לתבוע אותה.', false, 'טענה זו שגויה. אף שנחי פעל ללא הסכמת דגנית, אם פעולתו הועילה לדגנית (שחררה אותה מחוב), ייתכן שתקום לו עילה להשבה מכוח דיני עשיית עושר ולא במשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, כי סאשה לא הייתה חייבת לקבל את התשלום מנחי, ולכן התשלום אינו תקף.', false, 'טענה זו שגויה. סעיף 40 לחוק החוזים (חלק כללי) קובע כי חיוב יכול שיקויים בידי אדם שאינו החייב. אם הנושה קיבל את התשלום, החיוב נפרע, ואין זה משנה אם הנושה היה חייב לקבלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, נחי זכאי להשבה מדגנית מכוח דיני עשיית עושר ולא במשפט, שכן דגנית התעשרה שלא כדין על חשבונו.', true, 'תשובה זו נכונה. כאשר צד שלישי מקיים חיוב של חייב כלפי נושה, והנושה מקבל את הקיום, החייב משתחרר מהחוב. במקרה כזה, החייב התעשר על חשבון הצד השלישי, ועל כן קמה לצד השלישי עילה להשבה מכוח דיני עשיית עושר ולא במשפט, גם אם פעל ללא הסכמת החייב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם דגנית הייתה חייבת לנחי סכום זהה מעסקה אחרת.', false, 'טענה זו שגויה. הזכות להשבה מכוח עשיית עושר אינה מותנית בקיומו של חוב קודם בין הצדדים, אלא בהתעשרות שלא כדין של צד אחד על חשבון משנהו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 35, '2019-S-S-Q35';
END
$$;

-- ============================================================
-- Q36 — 2019-S-S-Q36 — chapter=contracts subtopic=standard_contracts
-- classifier_note: Pre-printed contract template for sale of apartments — standard-form contracts
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '3b20ed69-75b0-4c42-9bb8-d8c0e2277921'::uuid;
  v_group_id uuid := 'c0659c0c-d839-4e0f-84c7-abe6cdc5b67e'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '7e94b965-b7a9-4103-bd0f-817adab61dd9'::uuid;
  v_ang_1 uuid := '0c559009-9835-4525-97fd-9fce03f1d012'::uuid;
  v_ang_2 uuid := 'e5de7922-179b-463f-8a38-b86a75b35f80'::uuid;
  v_ang_3 uuid := '4d3fd91f-2eec-4de5-8836-59ef96804302'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q36';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 36, '2019-S-S-Q36';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'standard_contracts' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'standard_contracts', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q36', v_chapter_id, v_subtopic_id, 'רותם, המנהלת חברה הבונה דירות למגורים, ביקשה מענבר, עורכת הדין הקבועה של החברה, לנסח חוזה מכר שמקצת תנאיו (לא כולם!) ייקבעו מראש, על מנת שחוזה מכר זה ישמש את החברה בעתיד, כך שלפחות ביחס לתנאים שייקבעו מראש ייחסך הצורך בניהול משא ומתן ממושך עם כל רוכש ורוכש. על יסוד ניסיונה הרב בניהול משא ומתן עם רוכשים פוטנציאליים ועל רקע קשיים שנתגלעו בעת ביצוע התקשרויות עם רוכשי דירות, ביקשה רותם מעו"ד ענבר לכלול בחוזה המכר תנאי הקובע כי רוכש הדירה לא יוכל לפנות לבית המשפט כל עוד לא שילם לפחות 51% ממחיר הדירה, והפקיד בבית המשפט ערבות בנקאית בשיעור השווה ליתרת מחיר הדירה (49%). רותם מבקשת מעורכת דינה להעריך אם קיים קושי משפטי לכלול את הסעיף האמור בחוזה המכר (בהנחה שהתנאי ינוסח בצורה בהירה ומפורשת, ותינתן לרוכש שהות מספקת לבחון אותו): מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 36}'::jsonb, 'השאלה עוסקת בבחינת תנאי בחוזה מכר דירות, אשר חלק מתנאיו נקבעו מראש, ובו סעיף המגביל את זכות הרוכש לפנות לבית המשפט. היא בוחנת את תחולת חוק החוזים האחידים, תשמ"ג-1982, ובפרט את סוגיית התנאי המקפח ואת חזקת הקיפוח הקבועה בסעיף 4(8) לחוק, הנוגעת להגבלת פנייה לערכאות.', 'החוזה המתואר בשאלה, אף אם לא כל תנאיו נקבעו מראש, עונה על הגדרת ''חוזה אחיד'' לפי סעיף 2 לחוק החוזים האחידים, תשמ"ג-1982, שכן ''כל תנאיו או מקצתם, נקבעו בידי צד אחד כדי שישמשו תנאים לחוזים רבים בינו לבין אנשים בלתי מסויימים במספרם או בזהותם''. תנאי המגביל את זכות הלקוח לפנות לערכאות משפטיות הוא תנאי בעייתי במיוחד. סעיף 4(8) לחוק החוזים האחידים קובע חזקת קיפוח לתנאי ''השולל או המגביל את זכות הלקוח לפנות לערכאות משפטיות''. תנאי כזה, המונע מהרוכש לפנות לבית המשפט כל עוד לא שילם 51% והפקיד ערבות בנקאית, עלול להיחשב מקפח. בית משפט, במסגרת סכסוך בין הצדדים, מוסמך לבטל או לשנות תנאי מקפח בחוזה אחיד, בהתאם לסעיף 3 לחוק. סעיף 2 לחוק החוזים האחידים | הגדרות', 'הטעות הנפוצה היא לחשוב שחוזה שבו נדונים חלק מהתנאים אינו חוזה אחיד, או להתעלם מההגנות המיוחדות של חוק החוזים האחידים מפני תנאים המגבילים פנייה לערכאות.',
    '["חוזה אחיד", "תנאי מקפח", "חזקת קיפוח", "הגבלת פנייה לערכאות", "חוק החוזים האחידים סעיף 4(8)", "חופש החוזים"]'::jsonb, '**וריאציה 1 — הגדרת חוזה אחיד:** האם חוזה מכר דירה הוא תמיד חוזה אחיד? ← לא בהכרח, אך ברוב המקרים, כאשר הספק מנסח מראש את רוב התנאים לחוזים רבים, הוא ייחשב לחוזה אחיד (סעיף 2 לחוק החוזים האחידים).
**וריאציה 2 — תנאי שנדון פרטנית:** מה הדין אם התנאי המגביל את הפנייה לבית המשפט נדון פרטנית בין רותם לרוכש? ← תנאי שסוכם במיוחד בין הספק ללקוח אינו נחשב לחלק מחוזה אחיד, ולכן לא יחולו עליו הוראות חוק החוזים האחידים (סעיף 2 לחוק החוזים האחידים).

**וריאציה 3 — תנאי המגביל סעדים:** האם תנאי המגביל את סוג הסעדים (למשל, רק פיצויים ולא ביטול) ייחשב מקפח? ← כן, סעיף 4(6) לחוק החוזים האחידים קובע חזקת קיפוח לתנאי השולל או המגביל זכות או סעד העומדים ללקוח על פי דין.', 'חוזה מכר דירה עם תנאים קבועים מראש ← חוזה אחיד. תנאי המגביל פנייה לערכאות ← חזקת קיפוח (סעיף 4(8) לחוק החוזים האחידים) ← בית משפט יכול לבטל/לשנות.', '["חוק החוזים האחידים, תשמ\"ג-1982, סעיפים 2, 3, 4(6), 4(8)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''standard_contracts'' | classifier_note: Pre-printed contract template for sale of apartments — standard-form contracts | source_review_note: השאלה עוסקת בדיני חוזים (חוזים אחידים), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'היות שלא כל תנאי החוזה נקבעו מראש אין מדובר בחוזה אחיד, ומכאן שאין מניעה לכלול תנאי זה בחוזה בהתאם לעקרון חופש החוזים.', false, 'טענה זו שגויה. גם אם לא כל תנאי החוזה נקבעו מראש, די בכך שרובם או חלק מהותי מהם נקבעו מראש על ידי צד אחד כדי שהחוזה ייחשב לחוזה אחיד. עקרון חופש החוזים מוגבל על ידי חוק החוזים האחידים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התנאי האמור עלול להיחשב תנאי מקפח בחוזה אחיד, ועל כן בית משפט עשוי לבטל אותו או לשנותו.', true, 'תשובה זו נכונה. התנאי מגביל את זכות הרוכש לפנות לערכאות משפטיות, וסעיף 4(8) לחוק החוזים האחידים, תשמ"ג-1982, קובע חזקת קיפוח לתנאי כזה. בית משפט רשאי לבטל או לשנות תנאי מקפח בחוזה אחיד.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התנאי האמור בטל.', false, 'טענה זו שגויה. תנאי מקפח בחוזה אחיד אינו בטל אוטומטית, אלא נתון לסמכות בית המשפט או בית הדין לחוזים אחידים לבטלו או לשנותו, לאחר בחינת נסיבות העניין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התנאי האמור הוא בבחינת תנאי מקפח בחוזה אחיד, אך רק בית הדין לחוזים אחידים יוכל לקבוע זאת, לפי פניית היועץ המשפטי לממשלה או ארגון צרכנים, ובהתאם - לבטלו או לשנותו.', false, 'טענה זו שגויה. גם בית משפט רגיל, במסגרת דיון בתביעה בין הצדדים, מוסמך לקבוע שתנאי בחוזה אחיד הוא מקפח ולבטלו או לשנותו, ולא רק בית הדין לחוזים אחידים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תנאי מקפח המגביל סעדים',
    1, 'חברת ''בונים בכיף'' כללה בחוזה אחיד למכירת דירות סעיף הקובע כי במקרה של איחור במסירה, הרוכש יהיה זכאי לפיצוי מוסכם בסך 1,000 ש"ח ליום בלבד, וכי לא יהיה רשאי לבטל את החוזה או לדרוש כל סעד אחר. מה הדין לגבי סעיף זה?', 'שאלה זו בוחנת את סוגיית התנאים המקפחים בחוזים אחידים, ובפרט את חזקת הקיפוח הקבועה בסעיף 4(6) לחוק החוזים האחידים, הנוגעת לשלילה או הגבלה של זכויות וסעדים המגיעים ללקוח על פי דין.', 'חוק החוזים האחידים, תשמ"ג-1982, נועד להגן על לקוחות מפני תנאים מקפחים בחוזים אחידים. סעיף 3 לחוק קובע כי בית משפט או בית הדין לחוזים אחידים רשאי לבטל או לשנות תנאי מקפח בחוזה אחיד. סעיף 4 לחוק מפרט חזקות קיפוח, כלומר תנאים שקיומם בחוזה אחיד מהווה ראיה לכאורה לקיפוח. סעיף 4(6) קובע חזקת קיפוח לתנאי ''השולל או המגביל זכות או סעד העומדים ללקוח על פי דין, או המתנה אותם במתן הודעה כלשהי או בצורה מסוימת''. הגבלת זכות הרוכש לבטל את החוזה או לדרוש סעדים אחרים, מעבר לפיצוי מוסכם נמוך, נופלת בגדר חזקה זו. לכן, סעיף כזה עלול להיחשב מקפח ובית המשפט רשאי לבטלו או לשנותו. סעיף 4(6) לחוק החוזים האחידים | תנאים שיש בהם חזקת קיפוח',
    'הטעות הנפוצה היא להתעלם מההגנות המיוחדות הקבועות בחוק החוזים האחידים, וליישם עקרונות כלליים של דיני חוזים (כמו חופש החוזים) באופן בלתי מסויג.', '["חוזה אחיד", "תנאי מקפח", "חזקת קיפוח", "הגבלת סעדים", "חוק החוזים האחידים סעיף 4(6)", "ביטול חוזה"]'::jsonb, '**וריאציה 1 — פיצוי מוסכם בלבד:** האם תנאי הקובע פיצוי מוסכם בלבד, ללא הגבלת סעדים אחרים, יכול להיחשב מקפח? ← כן, אם הפיצוי המוסכם נקבע ללא יחס סביר לנזק שניתן היה לראותו מראש, בית המשפט רשאי להפחיתו (סעיף 15 לחוק החוזים (תרופות בשל הפרת חוזה)). בנוסף, אם הוא שולל סעדים אחרים, הוא מקפח (סעיף 4(6) לחוק החוזים האחידים).

**וריאציה 2 — נטל ההוכחה:** על מי מוטל נטל ההוכחה שהתנאי אינו מקפח? ← כאשר קיימת חזקת קיפוח לפי סעיף 4, נטל ההוכחה עובר לספק להוכיח שהתנאי אינו מקפח (ע"א 825/88 ארגון הקבלנים והבונים נ'' מוזס).
**וריאציה 3 — תנאי שאינו מקפח:** האם ישנם תנאים בחוזה אחיד שאינם יכולים להיחשב מקפחים? ← כן, סעיף 23 לחוק החוזים האחידים קובע כי הוראות מסוימות, כגון אלו הקובעות את התמורה הכספית העיקרית, אינן ניתנות לביטול או שינוי מחמת היותן מקפחות.', 'חוזה אחיד + תנאי המגביל סעדים ← חזקת קיפוח (סעיף 4(6) לחוק החוזים האחידים) ← בית משפט יכול לבטל/לשנות.',
    '["חוק החוזים האחידים, תשמ\"ג-1982, סעיפים 3, 4(6)", "חוק החוזים (תרופות בשל הפרת חוזה), תשל\"א-1970, סעיף 15", "ע\"א 825/88 ארגון הקבלנים והבונים נ'' מוזס, פ\"ד מ\"ה(3) 329 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הסעיף תקף, שכן הצדדים רשאים לקבוע פיצוי מוסכם ולהגביל סעדים במסגרת חופש החוזים.', false, 'טענה זו שגויה. חופש החוזים מוגבל על ידי חוק החוזים האחידים, במיוחד כאשר מדובר בהגבלת סעדים בחוזה אחיד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'הסעיף עלול להיחשב תנאי מקפח בחוזה אחיד, שכן הוא שולל או מגביל את זכות הרוכש לסעדים המגיעים לו על פי דין.', true, 'תשובה זו נכונה. סעיף 4(6) לחוק החוזים האחידים, תשמ"ג-1982, קובע חזקת קיפוח לתנאי השולל או מגביל זכות או סעד המגיעים ללקוח על פי דין. הגבלת סעדים כפי שתוארה נופלת בגדר חזקה זו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הסעיף בטל מעיקרו, שכן הוא נוגד את תקנת הציבור.', false, 'טענה זו שגויה. הסעיף אינו בטל מעיקרו אלא נתון לבחינה כ''תנאי מקפח'' וביטולו או שינויו תלוי בהחלטת בית המשפט או בית הדין לחוזים אחידים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הסעיף תקף, אלא אם כן הפיצוי המוסכם נמוך באופן בלתי סביר מהנזק הצפוי.', false, 'טענה זו שגויה. גם אם הפיצוי המוסכם סביר, הגבלת סעדים אחרים (כמו ביטול החוזה) עדיין עלולה להיחשב מקפחת בחוזה אחיד, ללא קשר לסבירות הפיצוי המוסכם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני קיפוח בחוזה אחיד',
    2, 'מהו המבחן העיקרי לקביעה האם תנאי בחוזה אחיד הוא ''מקפח''?', 'שאלה זו עוסקת במבחן המהותי לקביעת ''תנאי מקפח'' בחוזה אחיד, כפי שנקבע בסעיף 3 לחוק החוזים האחידים, תוך התייחסות לפרשנות הפסיקה לעניין חוסר איזון בין הצדדים.', 'סעיף 3 לחוק החוזים האחידים, תשמ"ג-1982, קובע כי ''בית משפט ובית הדין יבטלו או ישנו, בהתאם להוראות חוק זה, תנאי בחוזה אחיד שיש בו – בשים לב למכלול תנאי החוזה ולנסיבות אחרות – משום קיפוח לקוחות או משום יתרון בלתי הוגן של הספק העלול להביא לידי קיפוח לקוחות''. המבחן העיקרי לקיפוח הוא אפוא מבחן מהותי, הבוחן האם התנאי מעניק יתרון בלתי הוגן לספק על פני הלקוח, באופן הפוגע בחופש ההתקשרות של הלקוח או ביכולתו לממש את זכויותיו. בחינה זו נעשית תוך התחשבות במכלול תנאי החוזה ובנסיבות העניין, לרבות מעמד הצדדים, חשיבות התנאי, והאם הוא סביר בנסיבות העניין. סעיף 3 לחוק החוזים האחידים | ביטול ושינוי',
    'הטעות הנפוצה היא להתמקד במבחנים פורמליים או טכניים, במקום במבחן המהותי של חוסר הגינות ויתרון בלתי הוגן, תוך התעלמות ממכלול הנסיבות.', '["תנאי מקפח", "חוזה אחיד", "יתרון בלתי הוגן", "מכלול תנאי החוזה", "חוק החוזים האחידים סעיף 3", "חופש התקשרות"]'::jsonb, '**וריאציה 1 — חזקות הקיפוח:** מה תפקידן של חזקות הקיפוח בסעיף 4 לחוק? ← חזקות הקיפוח מעבירות את נטל ההוכחה לספק, שצריך להוכיח שהתנאי אינו מקפח, גם אם הוא נופל בגדר אחת החזקות (ע"א 825/88 ארגון הקבלנים והבונים נ'' מוזס).
**וריאציה 2 — תנאי שאינו חלק מחוזה אחיד:** מה הדין אם תנאי מסוים נדון בין הצדדים? ← תנאי שסוכם במיוחד בין הספק ללקוח אינו נחשב לחלק מחוזה אחיד, ולכן אינו כפוף לבחינת קיפוח לפי חוק החוזים האחידים (סעיף 2 לחוק החוזים האחידים).
**וריאציה 3 — תנאי ספציפי:** האם תנאי ספציפי יכול להיחשב מקפח גם אם אינו נופל בגדר חזקות הקיפוח? ← כן, חזקות הקיפוח אינן רשימה סגורה, ובית המשפט יכול לקבוע שתנאי הוא מקפח גם אם אינו עונה על אחת החזקות, בהתאם למבחן הכללי שבסעיף 3 (ע"א 179/87 גלאור נ'' חברת כלל).', 'מבחן קיפוח ← יתרון בלתי הוגן לספק + פגיעה בלקוח ← בהתחשב במכלול תנאי החוזה ונסיבות (סעיף 3 לחוק החוזים האחידים).',
    '["חוק החוזים האחידים, תשמ\"ג-1982, סעיפים 2, 3, 4", "ע\"א 825/88 ארגון הקבלנים והבונים נ'' מוזס, פ\"ד מ\"ה(3) 329 (1991)", "ע\"א 179/87 גלאור נ'' חברת כלל, פ\"ד מ\"ג(2) 66 (1989)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם התנאי סוטה מהוראות חוק קוגנטיות (שאינן ניתנות להתנאה).', false, 'טענה זו שגויה. תנאי הסוטה מהוראות קוגנטיות הוא בטל מעיקרו, ללא קשר להיותו מקפח בחוזה אחיד. מבחן הקיפוח רלוונטי לתנאים שאינם נוגדים חוק קוגנטי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם התנאי מעניק יתרון בלתי הוגן לספק על פני הלקוח, באופן הפוגע בחופש ההתקשרות של הלקוח או ביכולתו לממש את זכויותיו, וזאת בהתחשב במכלול תנאי החוזה ובנסיבות אחרות.', true, 'תשובה זו נכונה. זהו המבחן המרכזי לקיפוח, כפי שנקבע בסעיף 3 לחוק החוזים האחידים וכפי שפורש בפסיקה. המבחן הוא מהותי ובוחן את חוסר האיזון בין הצדדים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם התנאי לא נדון בין הצדדים באופן פרטני לפני חתימת החוזה.', false, 'טענה זו שגויה. העובדה שתנאי לא נדון פרטנית היא מאפיין של חוזה אחיד (סעיף 2 לחוק), אך אינה המבחן לקיפוח. תנאי שנדון פרטנית אינו נחשב לחלק מהחוזה האחיד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם התנאי אינו מנוסח בצורה ברורה ומובנת ללקוח הסביר.', false, 'טענה זו שגויה. חוסר בהירות בניסוח עלול להוביל לפרשנות לרעת המנסח (כלל הפרשנות נגד המנסח), אך אינו המבחן הישיר לקיפוח. תנאי יכול להיות ברור ומובן ועדיין מקפח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תנאים שאינם מקפחים בחוזה אחיד',
    3, 'חברת ''בונים בכיף'' כללה בחוזה אחיד למכירת דירות סעיף הקובע את מחיר הדירה, מועדי התשלום, וכן את מפרט הדירה. האם תנאים אלו יכולים להיחשב תנאים מקפחים בחוזה אחיד?', 'שאלה זו עוסקת בחריגים לתחולת חוק החוזים האחידים, ובפרט בסעיף 23 לחוק, הקובע אילו תנאים בחוזה אחיד אינם ניתנים לביטול או שינוי מחמת היותם מקפחים, כגון תנאים הקובעים את התמורה העיקרית ואת מהות הנכס או השירות.', 'סעיף 23 לחוק החוזים האחידים, תשמ"ג-1982, קובע חריגים לתחולת החוק. סעיף 23(1) מורה כי ''הוראות חוק זה לא יחולו על תנאי הקובע את התמורה הכספית שישלם הלקוח בעד הנכס או השירות, ובלבד שהוא מנוסח בלשון פשוטה וברורה''. כמו כן, סעיף 23(2) מוציא מתחולת החוק תנאים התואמים תנאים שנקבעו או אושרו בחיקוק. תנאים הקובעים את מחיר הדירה, מועדי התשלום (כחלק מהתמורה הכספית העיקרית) ואת מפרט הדירה (כחלק ממהות הנכס) נופלים בגדר חריגים אלו. מטרת החריג היא למנוע התערבות שיפוטית בתנאים המהווים את ליבת העסקה, אשר לגביהם יש לצפות כי הלקוח יבחן אותם היטב לפני ההתקשרות. סעיף 23(1) לחוק החוזים האחידים | סייגים לתחולה',
    'הטעות הנפוצה היא להניח שכל תנאי בחוזה אחיד, ללא יוצא מן הכלל, כפוף לבחינת קיפוח, מבלי להכיר את החריגים הקבועים בסעיף 23 לחוק.', '["חוזה אחיד", "תנאי מקפח", "סייגים לתחולה", "תמורה כספית עיקרית", "מהות הנכס/שירות", "חוק החוזים האחידים סעיף 23"]'::jsonb, '**וריאציה 1 — תנאי מחיר:** האם תנאי מחיר יכול להיות מקפח אם הוא מנוסח בצורה לא ברורה? ← סעיף 23(1) דורש שהתמורה הכספית תהיה ''מנוסח בלשון פשוטה וברורה''. אם לא, הוא עלול לאבד את ההגנה של סעיף 23 ולהיבחן כתנאי מקפח (ע"א 1108/03 בנק דיסקונט לישראל בע"מ נ'' יורם וייס).
**וריאציה 2 — תנאי שנקבע בחיקוק:** מה הדין לגבי תנאי בחוזה אחיד התואם הוראת חוק? ← סעיף 23(2) קובע כי הוראות חוק החוזים האחידים לא יחולו על תנאי התואם תנאים שנקבעו או אושרו בחיקוק, ולכן הוא אינו יכול להיחשב מקפח.
**וריאציה 3 — תנאי שנדון פרטנית:** האם תנאי שנדון פרטנית יכול להיחשב מקפח? ← לא, תנאי שסוכם במיוחד בין הספק ללקוח אינו נחשב לחלק מחוזה אחיד, ולכן אינו כפוף לבחינת קיפוח (סעיף 2 לחוק החוזים האחידים).', 'תנאי מחיר ותנאי מהות הנכס/שירות ← אינם מקפחים בחוזה אחיד ← לפי סעיף 23 לחוק החוזים האחידים.',
    '["חוק החוזים האחידים, תשמ\"ג-1982, סעיף 23", "ע\"א 1108/03 בנק דיסקונט לישראל בע\"מ נ'' יורם וייס, פ\"ד נח(2) 343 (2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כל תנאי בחוזה אחיד יכול להיחשב מקפח אם הוא מעניק יתרון בלתי הוגן לספק.', false, 'טענה זו שגויה. סעיף 23 לחוק החוזים האחידים קובע חריגים מפורשים לתחולת החוק, וקובע אילו תנאים אינם יכולים להיחשב מקפחים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, סעיף 23 לחוק החוזים האחידים קובע כי תנאים הקובעים את התמורה הכספית העיקרית ואת מהות הנכס או השירות אינם ניתנים לביטול או שינוי מחמת היותם מקפחים.', true, 'תשובה זו נכונה. סעיף 23(1) לחוק החוזים האחידים מוציא מתחולת החוק תנאים הקובעים את התמורה הכספית העיקרית ואת מהות הנכס או השירות, ולכן הם אינם יכולים להיחשב מקפחים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם מחיר הדירה גבוה באופן בלתי סביר ממחיר השוק.', false, 'טענה זו שגויה. סעיף 23(1) לחוק החוזים האחידים מוציא את התמורה הכספית העיקרית מתחולת החוק, ולכן מחיר הדירה אינו יכול להיחשב מקפח, גם אם הוא גבוה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הוכח שהרוכש לא הבין את משמעות התנאים הללו.', false, 'טענה זו שגויה. הבנת הרוכש את התנאים אינה רלוונטית לשאלת הקיפוח של תנאים אלו, שכן הם מוחרגים במפורש מתחולת החוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות בית הדין לחוזים אחידים',
    4, 'מהי הסמכות הייחודית של בית הדין לחוזים אחידים, בשונה מבית משפט רגיל, ביחס לתנאים מקפחים בחוזים אחידים?', 'שאלה זו בוחנת את ההבדל המהותי בסמכויות בין בית הדין לחוזים אחידים לבין בית משפט רגיל, תוך התמקדות בסמכותו הייחודית של בית הדין לפעול באופן אובייקטיבי וכללי ביחס לחוזים אחידים.', 'חוק החוזים האחידים, תשמ"ג-1982, הקים את בית הדין לחוזים אחידים. סמכותו של בית הדין היא סמכות אובייקטיבית, כללית ומונעת. הוא מוסמך לאשר חוזה אחיד (לפי בקשת ספק) או לבטל או לשנות תנאי מקפח בחוזה אחיד (לפי בקשת היועץ המשפטי לממשלה, נציג ארגון צרכנים, או רשות ציבורית), באופן שיחול על כלל ההתקשרויות העתידיות של הספק. זאת בניגוד לבית משפט רגיל, אשר מוסמך לדון בתנאי מקפח רק במסגרת סכסוך קונקרטי בין ספק ללקוח, והחלטתו מחייבת רק את הצדדים לאותו סכסוך. סעיפים 12, 14 ו-18 לחוק החוזים האחידים מפרטים את סמכויות בית הדין. סעיף 12 לחוק החוזים האחידים | סמכויות בית הדין',
    'הטעות הנפוצה היא לבלבל בין סמכויות בית הדין לחוזים אחידים לבין סמכויות בית המשפט הרגיל, ולא להבין את האופי הכללי והמונע של פעולת בית הדין.', '["בית הדין לחוזים אחידים", "סמכות אובייקטיבית", "ביטול תנאי מקפח", "אישור חוזה אחיד", "חוק החוזים האחידים", "היועץ המשפטי לממשלה"]'::jsonb, '**וריאציה 1 — יוזמי הפנייה לבית הדין:** מי רשאי לפנות לבית הדין בבקשה לביטול או שינוי תנאי מקפח? ← היועץ המשפטי לממשלה, נציג ארגון צרכנים, או רשות ציבורית (סעיף 16 לחוק החוזים האחידים).
**וריאציה 2 — תוקף החלטת בית הדין:** מה תוקפה של החלטת בית הדין לחוזים אחידים? ← החלטת בית הדין לביטול או שינוי תנאי מקפח חלה על כל החוזים האחידים של הספק, גם אלה שייכרתו בעתיד (סעיף 18 לחוק החוזים האחידים).

**וריאציה 3 — ערעור על החלטת בית הדין:** לאיזו ערכאה ניתן לערער על החלטת בית הדין לחוזים אחידים? ← על החלטת בית הדין ניתן לערער לבית המשפט העליון (סעיף 20 לחוק החוזים האחידים).', 'בית הדין לחוזים אחידים ← מאשר/מבטל/משנה תנאים מקפחים ← באופן כללי ועתידי (סעיפים 12, 14, 18 לחוק החוזים האחידים).',
    '["חוק החוזים האחידים, תשמ\"ג-1982, סעיפים 12, 14, 16, 18, 20"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית הדין מוסמך לבטל או לשנות תנאי מקפח בחוזה אחיד, אך רק לגבי חוזה ספציפי שהובא בפניו על ידי לקוח.', false, 'טענה זו שגויה. סמכות זו נתונה גם לבית משפט רגיל. סמכותו הייחודית של בית הדין היא לבטל או לאשר תנאים בחוזים אחידים באופן כללי, ולא רק בחוזה ספציפי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית הדין מוסמך לאשר חוזה אחיד או לבטל או לשנות תנאי מקפח בחוזה אחיד, באופן כללי, כך שהחלטתו תחול על כל החוזים העתידיים של הספק.', true, 'תשובה זו נכונה. סמכותו של בית הדין לחוזים אחידים היא סמכות אובייקטיבית, המאפשרת לו לאשר חוזים אחידים או לבטל/לשנות תנאים מקפחים בהם, באופן שיחול על כלל ההתקשרויות העתידיות של הספק, ולא רק על מקרה ספציפי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית הדין מוסמך לדון רק בתביעות ייצוגיות הנוגעות לחוזים אחידים.', false, 'טענה זו שגויה. בית הדין אינו דן בתביעות ייצוגיות, אלא בבקשות לאישור או לביטול/שינוי תנאים בחוזים אחידים. תביעות ייצוגיות נדונות בבתי המשפט הרגילים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית הדין מוסמך להטיל קנסות על ספקים המשתמשים בתנאים מקפחים בחוזים אחידים.', false, 'טענה זו שגויה. לבית הדין לחוזים אחידים אין סמכות להטיל קנסות. סמכותו מתמקדת בביטול או שינוי תנאים מקפחים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 36, '2019-S-S-Q36';
END
$$;

