-- classifier_note: Power of attorney to contractor for procurement — agency law
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '26b21c73-02e7-41b2-8393-2809b45e2f43'::uuid;
  v_group_id uuid := '57c61def-632e-43fa-ab47-b8df2d94d8b4'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '07428544-da66-485e-9a37-257a74e3d8ba'::uuid;
  v_ang_1 uuid := 'ac712536-1cb6-4985-a294-1036336f2067'::uuid;
  v_ang_2 uuid := 'd1632fc2-0c8a-402a-a24c-a0b6d05ca65b'::uuid;
  v_ang_3 uuid := '4b9dffec-9c62-4dcd-ad8f-7ce5abb16678'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q37';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 37, '2019-S-S-Q37';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'agency' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'agency', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q37', v_chapter_id, v_subtopic_id, 'חיים ייפה את כוחו של שלום, קבלן הבניין ששכר לצורך הקמת פרויקט בנייה, כשלוח שלו לצורך ניהול משא ומתן וחתימה על שורת הסכמים לרכישת מוצרים וציוד לפרויקט הבנייה של חיים מספקים ויצרנים שונים. בייפוי הכוח צוין שהוא ניתן מתוך אמון שרוחש חיים לשלום. שלום חתם אישית על ההסכם הראשון לרכישת מוצרים וציוד לאתר הבנייה מאחד היצרנים, וייפה את כוחו של קבלן המשנה שלו כשלוח שלו לצורך ניהול משא ומתן וחתימה על יתרת ההסכמים לרכישת המוצרים והציוד מהספקים והיצרנים השונים. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 37}'::jsonb, 'השאלה עוסקת בסוגיית מינוי שלוח משנה בדיני שליחות, ובפרט ביישום סעיף 16 לחוק השליחות, התשכ"ה-1965, הקובע את הכלל לפיו שלוח אינו רשאי למנות שלוח אחר במקומו, אלא אם הוסמך לכך במפורש או מכללא, או שקיים צורך דחוף או נוהג.', 'סעיף 16 לחוק השליחות, התשכ"ה-1965, קובע את הכלל המרכזי בעניין מינוי שלוח משנה: ''שלוח אינו רשאי למנות שלוח אחר במקומו, אלא אם הוסמך לכך במפורש או מכללא, או שקיים צורך דחוף או נוהג''. במקרה הנדון, שלום (השלוח) ייפה את כוחו של קבלן המשנה שלו (שלוח המשנה) ללא הרשאה מפורשת או מכללא מחיים (השולח). כמו כן, לא מתוארים נסיבות של צורך דחוף (כמו אירוע בלתי צפוי המונע משלום לבצע את השליחות בעצמו) או נוהג מקובל בענף הבנייה המאפשר מינוי כזה באופן אוטומטי. העובדה שייפוי הכוח ניתן מתוך אמון אישי בחיים דווקא מחזקת את הצורך בהרשאה מפורשת למינוי שלוח משנה. לכן, פעולתו של שלום במינוי שלוח משנה הייתה שלא כדין. סעיף 16 לחוק השליחות | מינוי שלוח אחר', 'הטעות הנפוצה היא להניח ששלוח, מעצם מעמדו, רשאי למנות שלוח משנה, או לבלבל בין חובת נאמנות לבין סמכות למינוי שלוח משנה.',
    '["שליחות", "שלוח משנה", "הרשאה מפורשת", "הרשאה מכללא", "צורך דחוף", "חוק השליחות סעיף 16"]'::jsonb, '**וריאציה 1 — חובת נאמנות:** האם חובת הנאמנות של שלום כלפי חיים מאפשרת לו למנות שלוח משנה? ← לא, חובת הנאמנות (סעיף 8 לחוק השליחות) מחייבת את השלוח לפעול לטובת השולח, אך אינה מקנה לו סמכות למינוי שלוח משנה ללא הרשאה או חריג מפורש בחוק.
**וריאציה 2 — אשרור בדיעבד:** מה הדין אם חיים היה מאשר בדיעבד את מינוי קבלן המשנה? ← אם חיים היה מאשר את המינוי, פעולותיו של קבלן המשנה היו מחייבות את חיים כאילו ניתנה הרשאה מלכתחילה (סעיף 6 לחוק השליחות).
**וריאציה 3 — אחריות שלום:** אם שלום פעל שלא כדין, האם הוא אחראי כלפי חיים? ← כן, שלום הפר את חובתו לפי סעיף 16 לחוק השליחות, ולכן הוא אחראי כלפי חיים על הנזקים שנגרמו כתוצאה מכך (סעיף 8 לחוק השליחות).', 'שלוח אינו ממנה שלוח משנה ← אלא אם הרשאה מפורשת/מכללא, צורך דחוף, או נוהג (סעיף 16 לחוק השליחות).', '["חוק השליחות, תשכ\"ה-1965, סעיפים 6, 8, 16"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''agency'' | classifier_note: Power of attorney to contractor for procurement — agency law | source_review_note: השאלה עוסקת בדיני שליחות (חוק השליחות), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'שלום פעל כדין, שכן בהיותו שלוח מחויב הוא לפעול בנאמנות כלפי שולחו וממילא מוסמך הוא לעשות כל פעולה הנדרשת לביצוע השליחות כמו מינוי שלוח מטעמו לקידום שליחותו.', false, 'טענה זו שגויה. סעיף 16 לחוק השליחות קובע כי שלוח אינו רשאי למנות שלוח אחר במקומו, אלא אם הוסמך לכך במפורש או מכללא, או שקיים צורך דחוף או נוהג. נאמנות אינה מקנה סמכות אוטומטית למינוי שלוח משנה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'שלום פעל שלא כדין, שכן אף שהוא מוסמך למנות שלוח מטעמו לקידום מטלותיו, מוסמך הוא לעשות כן רק באופן חד פעמי, ולאשרר פעולתו זו עם השולח בהזדמנות הראשונה.', false, 'טענה זו שגויה. אין בחוק השליחות הוראה המגבילה מינוי שלוח משנה לפעולה חד פעמית או מחייבת אישרור בדיעבד, אלא קובעת את התנאים למינוי מלכתחילה. אם המינוי נעשה שלא כדין, הוא אינו מחייב את השולח.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שלום פעל כדין, שכן שלוח רשאי למנות שלוח לנושא שליחותו, ומשעשה כן רואים את השלוח הנוסף כמי שקיבל הרשאה לשליחות מחיים עצמו, וחב הוא בכל חיוביו של שלום ביחד ולחוד עימו, לרבות חובתו לגלות לחיים כל ידיעה הנוגעת לנושא השליחות ולא לקבל מכל אדם טובת הנאה או הבטחה לטובת הנאה בקשר לנושא השליחות שלא בהסכמתו של השולח.', false, 'טענה זו שגויה. הכלל הוא ששלוח אינו רשאי למנות שלוח משנה ללא הרשאה. גם אם היה מוסמך, שלוח המשנה אינו חב בכל חיובי השלוח הראשי ביחד ולחוד, אלא חב חובות מסוימות כלפי השולח הראשי והשולח המקורי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'שלום פעל שלא כדין, שכן לא הייתה לו הרשאה מפורשת או מכללא למנות שלוח מטעמו לנושא השליחות. כמו כן, מינוי קבלן המשנה לשלוח לא נבע מצורך בביצוע פעולה דחופה ובלתי צפויה מראש הדרושה באופן סביר לשמירה על ענייניו של חיים.', true, 'תשובה זו נכונה. סעיף 16 לחוק השליחות קובע כי שלוח אינו רשאי למנות שלוח אחר במקומו, אלא אם הוסמך לכך במפורש או מכללא, או שקיים צורך דחוף או נוהג. במקרה זה, לא ניתנה הרשאה כזו, ולא מתקיימים החריגים המאפשרים מינוי שלוח משנה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חריג לכלל איסור מינוי שלוח משנה',
    1, 'חיים ייפה את כוחו של שלום לרכוש עבורו ציוד בנייה ייחודי מספק בחו"ל. ביום שבו היה אמור שלום לטוס לחו"ל כדי לחתום על ההסכם ולפקח על העמסת הציוד, פרצה שביתה כללית בלתי צפויה בנמל התעופה, וטיסתו בוטלה. שלום, כדי למנוע עיכובים ונזקים לחיים, מינה את עוזרו המהימן, נחי, לטוס במקומו ולבצע את הפעולות הדרושות. האם שלום פעל כדין?', 'שאלה זו בוחנת את החריגים לכלל איסור מינוי שלוח משנה על ידי שלוח, כפי שקבועים בסעיף 16 לחוק השליחות, ובפרט את חריג ''הצורך הדחוף'' לשמירה על ענייני השולח.', 'סעיף 16 לחוק השליחות, התשכ"ה-1965, קובע את הכלל לפיו ''שלוח אינו רשאי למנות שלוח אחר במקומו, אלא אם הוסמך לכך במפורש או מכללא, או שקיים צורך דחוף או נוהג''. החריג הרלוונטי כאן הוא ''צורך דחוף''. סעיף 16(2) מפרט כי שלוח רשאי למנות שלוח משנה אם ''הדבר דרוש, באופן סביר, לשמירה על ענייני השולח, ואין באפשרותו של השלוח לקבל הוראותיו במועד''. במקרה הנדון, השביתה הבלתי צפויה מנעה משלום לטוס, והצורך למנוע עיכובים ונזקים לחיים (השולח) עונה על דרישת ''צורך דחוף'' לשמירה על ענייני השולח. לכן, פעולתו של שלום במינוי נחי כשלוח משנה הייתה כדין. סעיף 16 לחוק השליחות | מינוי שלוח אחר',
    'הטעות הנפוצה היא להתמקד בכלל איסור מינוי שלוח משנה, מבלי לזכור את החריגים החשובים הקבועים בחוק, ובפרט את חריג הצורך הדחוף.', '["שליחות", "שלוח משנה", "חוק השליחות סעיף 16", "צורך דחוף", "שמירה על ענייני השולח", "הרשאה מכללא"]'::jsonb, '**וריאציה 1 — נוהג:** האם מינוי שלוח משנה יכול להיות מותר מכוח נוהג? ← כן, סעיף 16(3) לחוק השליחות קובע כי שלוח רשאי למנות שלוח משנה אם ''הדבר הוא מנהג מקובל בעסקים מסוג זה''.
**וריאציה 2 — אחריות השלוח הראשי:** גם אם המינוי כדין, האם שלום עדיין אחראי לפעולותיו של נחי? ← כן, ככלל, השלוח הראשי אחראי כלפי השולח לפעולותיו של שלוח המשנה, כאילו היו פעולותיו שלו (סעיף 16(ב) לחוק השליחות).
**וריאציה 3 — חריג ''אמון אישי'':** האם העובדה שייפוי הכוח ניתן מתוך אמון אישי מבטלת את חריג הצורך הדחוף? ← לא בהכרח. גם כאשר קיים יסוד של אמון אישי, צורך דחוף ובלתי צפוי יכול להצדיק מינוי שלוח משנה, במיוחד אם מטרתו היא שמירה על ענייני השולח (ע"א 180/70 קלמר נ'' גיא).', 'שלוח אינו ממנה שלוח משנה ← אלא אם הרשאה מפורשת/מכללא, צורך דחוף, או נוהג (סעיף 16 לחוק השליחות).',
    '["חוק השליחות, תשכ\"ה-1965, סעיף 16", "ע\"א 180/70 קלמר נ'' גיא, פ\"ד כה(1) 185 (1971)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן שלוח אינו רשאי למנות שלוח משנה ללא הרשאה מפורשת מהשולח, גם במקרה של צורך דחוף.', false, 'טענה זו שגויה. סעיף 16 לחוק השליחות קובע חריג לכלל זה במקרה של צורך דחוף ובלתי צפוי מראש, הדרוש באופן סביר לשמירה על ענייני השולח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, שכן מינוי שלוח משנה במקרה זה נבע מצורך בביצוע פעולה דחופה ובלתי צפויה מראש, הדרושה באופן סביר לשמירה על ענייניו של חיים.', true, 'תשובה זו נכונה. סעיף 16(2) לחוק השליחות מאפשר לשלוח למנות שלוח משנה אם ''הדבר דרוש, באופן סביר, לשמירה על ענייני השולח, ואין באפשרותו של השלוח לקבל הוראותיו במועד''. השביתה הבלתי צפויה והצורך למנוע נזקים עונים על חריג זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם חיים יאשר את פעולתו של שלום בדיעבד.', false, 'טענה זו שגויה. אישור בדיעבד (אשרור) הופך פעולה שנעשתה ללא הרשאה לתקפה, אך אינו תנאי ללגיטימיות המינוי מלכתחילה במקרה של צורך דחוף. במקרה זה, המינוי תקף כבר מעצם קיום החריג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שכן ייפוי הכוח ניתן מתוך אמון אישי בשלום, ולכן הוא אינו יכול להעביר את השליחות לאחר.', false, 'טענה זו שגויה. אף שייפוי הכוח ניתן מתוך אמון, חוק השליחות מכיר בחריגים לכלל אי-העברת השליחות, כגון צורך דחוף, המאפשרים מינוי שלוח משנה גם בנסיבות של אמון אישי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני הרשאה למינוי שלוח משנה',
    2, 'מהם המבחנים לקביעה האם לשלוח ניתנה ''הרשאה מכללא'' למנות שלוח משנה, לפי סעיף 16(1) לחוק השליחות?', 'שאלה זו מתמקדת בפרשנות המונח ''הרשאה מכללא'' בהקשר של מינוי שלוח משנה לפי סעיף 16(1) לחוק השליחות, ומבהירה את הקריטריונים המשפטיים לקביעת קיומה של הרשאה כזו.', 'סעיף 16(1) לחוק השליחות, התשכ"ה-1965, קובע כי שלוח רשאי למנות שלוח אחר במקומו אם ''הוסמך לכך במפורש או מכללא''. ''הרשאה מכללא'' היא הרשאה שאינה ניתנת במפורש, אלא נלמדת מהתנהגות הצדדים, מנסיבות העניין, ממהות השליחות, או מנוהג מקובל בענף. בית המשפט יבחן את אומד דעת הצדדים, כפי שהיא משתקפת מהתנהגותם ומהקשר העסקי ביניהם. לדוגמה, אם השולח ידע בעבר על מינוי שלוח משנה על ידי השלוח ולא התנגד, או אם מדובר בפעולה שעל פי טיבה מקובל למנות לה שלוח משנה, ניתן יהיה להסיק על קיומה של הרשאה מכללא. המבחן הוא אובייקטיבי-נסיבתי. סעיף 16 לחוק השליחות | מינוי שלוח אחר',
    'הטעות הנפוצה היא לבלבל בין הרשאה מכללא לבין חריג ''הצורך הדחוף'', או לחשוב שהרשאה מכללא דורשת הסכמה אקטיבית של השולח לכל מינוי ספציפי.', '["שליחות", "הרשאה מכללא", "שלוח משנה", "חוק השליחות סעיף 16", "אומד דעת הצדדים", "נוהג"]'::jsonb, '**וריאציה 1 — הרשאה מפורשת:** מהי הרשאה מפורשת? ← הרשאה הניתנת במילים ברורות, בכתב או בעל פה, המאפשרת לשלוח למנות שלוח משנה (סעיף 16(1) לחוק השליחות).
**וריאציה 2 — נטל ההוכחה:** על מי מוטל נטל ההוכחה לקיומה של הרשאה מכללא? ← על השלוח הטוען כי הייתה לו הרשאה כזו (ע"א 180/70 קלמר נ'' גיא).
**וריאציה 3 — היקף ההרשאה:** אם ניתנה הרשאה מכללא למינוי שלוח משנה, האם היא בלתי מוגבלת? ← לא, היקף ההרשאה מכללא יפורש בהתאם לנסיבות העניין ולמהות השליחות, והיא לא תאפשר מינוי שלוח משנה לכל פעולה שהיא (ע"א 180/70 קלמר נ'' גיא).', 'הרשאה מכללא למינוי שלוח משנה ← נלמדת מנסיבות, התנהגות, מהות השליחות, נוהג (סעיף 16(1) לחוק השליחות).',
    '["חוק השליחות, תשכ\"ה-1965, סעיף 16", "ע\"א 180/70 קלמר נ'' גיא, פ\"ד כה(1) 185 (1971)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הרשאה מכללא קיימת רק אם השולח ידע על כוונת השלוח למנות שלוח משנה ולא התנגד לכך במפורש.', false, 'טענה זו שגויה. הרשאה מכללא אינה מסתכמת בידיעה ואי-התנגדות בלבד, אלא דורשת בחינה אובייקטיבית של נסיבות העניין ואומד דעת הצדדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הרשאה מכללא נלמדת מנסיבות העניין, מהתנהגות הצדדים, ממהות השליחות, או מנוהג מקובל בענף, המעידים על הסכמה משתמעת של השולח למינוי שלוח משנה.', true, 'תשובה זו נכונה. הרשאה מכללא היא הרשאה שאינה מפורשת, ונלמדת מהתנהגות הצדדים, מהקשר העסקי, ממהות הפעולה או מנוהג, המעידים על כך שהשולח הסכים למינוי שלוח משנה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הרשאה מכללא קיימת תמיד כאשר השליחות דורשת מומחיות מיוחדת שאינה מצויה בידי השלוח הראשי.', false, 'טענה זו שגויה. דרישת מומחיות אינה יוצרת הרשאה מכללא אוטומטית, אלא יכולה להוות שיקול בבחינת הצורך הדחוף או מהות השליחות, אך אינה מבחן עצמאי להרשאה מכללא.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הרשאה מכללא ניתנת רק אם השלוח הוכיח כי לא היה באפשרותו לבצע את השליחות בעצמו.', false, 'טענה זו שגויה. חוסר יכולת לבצע את השליחות בעצמו יכול להצדיק מינוי שלוח משנה מכוח ''צורך דחוף'' (סעיף 16(2)), אך אינו המבחן להרשאה מכללא (סעיף 16(1)).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות השולח כלפי צד שלישי',
    3, 'חיים ייפה את כוחו של שלום לרכוש עבורו ציוד בנייה. שלום, ללא הרשאה מחיים, מינה את קבלן המשנה שלו, נחי, כשלוח משנה. נחי חתם על הסכם לרכישת ציוד פגום מיצרן, וגרם לחיים נזקים כבדים. חיים תובע את היצרן בטענה שההסכם אינו מחייב אותו, שכן נחי פעל ללא סמכות. היצרן טוען כי נחי היה שלוח משנה של שלום, ולכן חיים מחויב. מה הדין?', 'שאלה זו עוסקת בהשלכות של מינוי שלוח משנה ללא הרשאה על אחריות השולח המקורי כלפי צד שלישי, ובכלל זה עקרונות ההרשאה והאשרור בדיני שליחות.', 'לפי סעיף 2 לחוק השליחות, ''פעולת שלוח שנעשתה בתוך הרשאתו מחייבת ומזכה את השולח''. כאשר שלוח ממנה שלוח משנה ללא הרשאה מהשולח (מפורשת, מכללא, צורך דחוף או נוהג), פעולותיו של שלוח המשנה אינן נחשבות כפעולות שנעשו ''בתוך הרשאתו'' של השולח. לכן, ככלל, השולח המקורי (חיים) אינו מחויב להסכם שנחתם על ידי שלוח המשנה (נחי) עם צד שלישי (היצרן). היצרן לא יכול לטעון כי חיים מחויב, אלא אם כן חיים אישר את הפעולה בדיעבד (אשרור לפי סעיף 6 לחוק השליחות), או שקיימת ''הרשאה נחזית'' (מצג של חיים כלפי היצרן שנחי מוסמך). בהיעדר נתונים כאלה, חיים אינו מחויב. סעיף 2 לחוק השליחות | מעשה השלוח',
    'הטעות הנפוצה היא להניח שכל פעולה של שלוח משנה מחייבת את השולח המקורי, מבלי לבחון את חוקיות מינוי שלוח המשנה ואת קיומה של הרשאה.', '["שליחות", "שלוח משנה", "הרשאה", "אחריות השולח", "אשרור", "הרשאה נחזית"]'::jsonb, '**וריאציה 1 — אשרור בדיעבד:** מה הדין אם חיים, לאחר שנודע לו על ההסכם, היה מאשר אותו? ← אם חיים היה מאשר את ההסכם, הוא היה מחויב לו כאילו נחתם בהרשאתו מלכתחילה (סעיף 6 לחוק השליחות).
**וריאציה 2 — אחריות שלום:** האם שלום אחראי כלפי חיים על הנזקים שנגרמו מפעולת נחי? ← כן, שלום הפר את חובתו לפי סעיף 16 לחוק השליחות במינוי נחי ללא הרשאה, ולכן הוא אחראי כלפי חיים על הנזקים שנגרמו כתוצאה מכך (סעיף 8 לחוק השליחות).
**וריאציה 3 — אחריות נחי:** האם נחי אחראי כלפי היצרן? ← אם נחי חתם על ההסכם בשם חיים ללא סמכות, הוא עלול להיות אחראי אישית כלפי היצרן בגין הפרת מצג שווא של סמכות (סעיף 5 לחוק השליחות).', 'מינוי שלוח משנה ללא הרשאה ← פעולותיו אינן מחייבות את השולח המקורי ← אלא אם אשרור או הרשאה נחזית (סעיף 2 לחוק השליחות).',
    '["חוק השליחות, תשכ\"ה-1965, סעיפים 2, 5, 6, 8, 16"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'חיים מחויב להסכם, שכן נחי פעל כשלוח משנה של שלום, ופעולות שלוח משנה מחייבות את השולח המקורי.', false, 'טענה זו שגויה. פעולות שלוח משנה מחייבות את השולח המקורי רק אם מינוי שלוח המשנה היה כדין, או אם השולח אישר את הפעולה בדיעבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'חיים אינו מחויב להסכם, שכן נחי מונה כשלוח משנה ללא הרשאה מחיים, ולכן פעולותיו אינן מחייבות את חיים.', true, 'תשובה זו נכונה. כאשר שלוח ממנה שלוח משנה ללא הרשאה מהשולח, פעולותיו של שלוח המשנה אינן מחייבות את השולח המקורי, אלא אם כן השולח אישר אותן בדיעבד (אשרור) או שקיימת הרשאה נחזית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'חיים מחויב להסכם, אך רשאי לתבוע את שלום בגין הנזקים שנגרמו לו עקב מינוי שלוח המשנה ללא הרשאה.', false, 'טענה זו שגויה. אם חיים אינו מחויב להסכם, אין לו צורך לתבוע את שלום בגין הנזקים מההסכם עצמו, אלא לכל היותר בגין הפרת חובת הנאמנות של שלום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'היצרן יכול לתבוע את נחי אישית בגין הפרת חוזה, אך לא את חיים.', false, 'טענה זו שגויה. היצרן יכול לתבוע את נחי אישית אם נחי חרג מסמכותו, אך השאלה מתמקדת באחריות חיים כלפי היצרן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חובות שלוח משנה כלפי השולח',
    4, 'חיים ייפה את כוחו של שלום לרכוש עבורו ציוד בנייה. בהסכמת חיים, שלום מינה את נחי כשלוח משנה. נחי, במהלך ביצוע השליחות, קיבל הצעה מיצרן אחר לקבל עמלה סודית אם ירכוש ממנו ציוד במחיר גבוה יותר. נחי קיבל את העמלה ורכש את הציוד היקר יותר. האם נחי חב בחובת נאמנות וגילוי ישירות כלפי חיים?', 'שאלה זו בוחנת את היקף חובותיו של שלוח משנה כלפי השולח המקורי, ובפרט את חובות הנאמנות והגילוי, כאשר מינוי שלוח המשנה נעשה כדין ובהסכמת השולח.', 'סעיף 16(ב) לחוק השליחות, התשכ"ה-1965, קובע כי ''שלוח שמינה שלוח אחר במקומו, רואים את שלוח המשנה כשלוחו של השולח''. משמעות הדבר היא שנוצר קשר ישיר בין השולח המקורי (חיים) לבין שלוח המשנה (נחי). כתוצאה מכך, שלוח המשנה חב בחובות המוטלות על שלוח כלפי שולחו, ובכלל זה חובת הנאמנות והגילוי הקבועות בסעיפים 8 ו-9 לחוק השליחות. סעיף 8 קובע כי ''שלוח חייב לפעול בנאמנות כלפי שולחו''. סעיף 9 קובע כי ''שלוח חייב לגלות לשולח כל ידיעה וחומר הנוגעים לשליחות''. קבלת עמלה סודית והעדפת אינטרס אישי על פני אינטרס השולח מהווה הפרה חמורה של חובות אלו. סעיף 16(ב) לחוק השליחות | מינוי שלוח אחר',
    'הטעות הנפוצה היא לחשוב ששלוח משנה חב חובות רק כלפי השלוח הראשי שמינה אותו, ולא כלפי השולח המקורי, גם כאשר המינוי נעשה כדין.', '["שליחות", "שלוח משנה", "חובת נאמנות", "חובת גילוי", "חוק השליחות סעיף 16(ב)", "קשר ישיר"]'::jsonb, '**וריאציה 1 — אחריות השלוח הראשי:** האם שלום עדיין אחראי כלפי חיים על פעולותיו של נחי? ← כן, סעיף 16(ב) לחוק השליחות קובע כי ''אין בכך כדי לגרוע מאחריותו של השלוח כלפי השולח''. כלומר, שלום וגם נחי חבים בחובות כלפי חיים.
**וריאציה 2 — סעדים לחיים:** אילו סעדים עומדים לחיים כנגד נחי? ← חיים יכול לתבוע מנחי השבה של העמלה שקיבל, פיצויים על הנזקים שנגרמו לו עקב רכישת הציוד היקר יותר, ואף ביטול העסקה עם היצרן אם יוכח שהיצרן ידע על הפרת הנאמנות (סעיפים 8, 9, 10 לחוק השליחות).
**וריאציה 3 — יחסי שלוח-שלוח משנה:** האם נחי חב חובות גם כלפי שלום? ← כן, נחי הוא שלוח של שלום, ולכן חב גם כלפיו בחובות שלוח, לרבות חובת נאמנות וגילוי (סעיפים 8 ו-9 לחוק השליחות).', 'שלוח משנה שמונה כדין ← נחשב שלוח של השולח המקורי ← חב חובות נאמנות וגילוי ישירות כלפיו (סעיף 16(ב) לחוק השליחות).',
    '["חוק השליחות, תשכ\"ה-1965, סעיפים 8, 9, 10, 16"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, נחי חב בחובותיו רק כלפי שלום, שמינה אותו, ולא כלפי חיים השולח המקורי.', false, 'טענה זו שגויה. כאשר מינוי שלוח המשנה נעשה כדין (בהסכמת השולח), שלוח המשנה חב בחובות מסוימות גם כלפי השולח המקורי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, נחי חב בחובת נאמנות וגילוי ישירות כלפי חיים, בדומה לחובותיו של שלום כלפי חיים.', true, 'תשובה זו נכונה. סעיף 16(ב) לחוק השליחות קובע כי ''שלוח שמינה שלוח אחר במקומו, רואים את שלוח המשנה כשלוחו של השולח''. מכאן ששלוח המשנה חב בחובות נאמנות וגילוי ישירות כלפי השולח המקורי, בדומה לשלוח הראשי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם חיים הוכיח כי נגרם לו נזק כתוצאה מפעולת נחי.', false, 'טענה זו שגויה. חובת הנאמנות והגילוי קיימת ללא קשר לשאלת הנזק. הפרתה מהווה עילה לתביעה, גם אם לא נגרם נזק ישיר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן נקבע במפורש בייפוי הכוח שניתן לנחי כי הוא חב חובות כלפי חיים.', false, 'טענה זו שגויה. חובות הנאמנות והגילוי של שלוח משנה כלפי השולח המקורי נובעות מהוראות חוק השליחות, ואינן דורשות קביעה מפורשת בייפוי הכוח.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 37, '2019-S-S-Q37';
END
$$;

-- ============================================================
-- Q38 — 2019-S-S-Q38 — chapter=torts subtopic=nuisance_trespass
-- classifier_note: Trespass to apartment (הסגת גבול), tenant ousting + eviction tort
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'dffd6302-828d-4707-8f89-05874f3b476f'::uuid;
  v_group_id uuid := '531ab22b-b490-44f0-a412-9d84f50cab54'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'd3d3a5bd-2d2d-4226-8c56-f21d7f23cb51'::uuid;
  v_ang_1 uuid := 'f0450333-2a4e-4462-b08d-3225c8ce045c'::uuid;
  v_ang_2 uuid := '58eda1a1-0394-473a-afd7-86d9398d1f00'::uuid;
  v_ang_3 uuid := '3f056035-3ae7-46a3-b194-a4ecd385ae4e'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q38';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 38, '2019-S-S-Q38';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'nuisance_trespass' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'nuisance_trespass', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q38', v_chapter_id, v_subtopic_id, 'עם שובה מטיול ממושך בחו"ל גילתה נטע להפתעתה כי יצחק נכנס לפני חודשיים לדירה שבה היא מתגוררת בשכירות, ומסרב לפנותה. נטע הגישה תביעה נזיקית ובה טענה כי יצחק הסיג את גבולה והיא מבקשת מבית המשפט לצוות על פינויו מן הדירה ולפסוק לה פיצויים בגובה הסכום שהיא נאלצת לשלם בגין שהותה במלון. יצחק טוען שנטע אינה זכאית לתובעו כלל, וכן שהיא מסרה לו בעבר מפתח לדירתה והוא זכאי לשהות בה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 38}'::jsonb, 'השאלה עוסקת בעוולת הסגת גבול במקרקעין לפי פקודת הנזיקין, ובפרט בנטל ההוכחה המוטל על הצדדים וביכולת לתבוע סעדים שונים (סילוק יד ופיצויים) באותה תביעה. היא מדגישה את מעמדו של שוכר (מחזיק) כבעל זכות תביעה בעוולה זו.', 'הדירה שבה מתגוררת נטע היא דירה שכורה, ולכן נטע היא ''מחזיק'' במקרקעין. עוולת הסגת גבול במקרקעין, המוגדרת בסעיף 29 לפקודת הנזיקין [נוסח חדש], נועדה להגן על זכות ההחזקה, ולכן גם מחזיק (כמו שוכר) זכאי לתבוע בגינה, ולא רק הבעלים. סעיף 30 לפקודת הנזיקין קובע כי ''בתובענה שהוגשה על הסגת גבול במקרקעין על הנתבע הראיה שהמעשה שעליו מתלוננים לא היה שלא כדין''. כלומר, הנטל להוכיח זכות חוקית להחזקה מוטל על יצחק. בנוסף, הפסיקה קבעה כי ניתן לתבוע הן צו לסילוק יד (פינוי) והן פיצויים (כמו דמי שכירות ראויים או נזקים ממשיים) באותה תביעה נזיקית, בהתאם לסעיפים 71 ו-76 לפקודת הנזיקין. סעיף 30 לפקודת הנזיקין | חובת הראיה', 'הטעות הנפוצה היא לחשוב שרק בעל מקרקעין יכול לתבוע בגין הסגת גבול, או לבלבל בין נטל ההוכחה הראשוני לבין הנטל המועבר לנתבע.',
    '["הסגת גבול במקרקעין", "פקודת הנזיקין סעיף 29", "פקודת הנזיקין סעיף 30", "נטל הוכחה", "זכות החזקה", "סילוק יד", "פיצויים"]'::jsonb, '**וריאציה 1 — מעמד השוכר:** האם שוכר דירה נחשב ''מחזיק'' לצורך עוולת הסגת גבול? ← כן, הפסיקה קבעה כי עוולת הסגת גבול מגינה על זכות ההחזקה, ולכן גם שוכר (מחזיק בפועל או בעל זכות להחזקה מיידית) זכאי לתבוע (רע"א 5058/99 כספי נ'' דויטש).
**וריאציה 2 — נזק ממון:** האם נטע חייבת להוכיח נזק ממון כדי לקבל צו פינוי? ← לא, צו פינוי (צו עשה) יכול להינתן גם ללא הוכחת נזק ממון, אך פיצויים כספיים דורשים הוכחת נזק ממון (סעיף 29 סיפא וסעיף 71 לפקודת הנזיקין).
**וריאציה 3 — טענת ''רשות'':** אם יצחק טוען שנטע מסרה לו מפתח, האם זה משנה את נטל ההוכחה? ← לא, גם אם יצחק טוען לרשות, הנטל עדיין עליו להוכיח שהרשות תקפה ובלתי ניתנת לביטול, או שלא בוטלה כדין (ע"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון).', 'שוכר (מחזיק) זכאי לתבוע הסגת גבול ← נטל הוכחה על הנתבע להראות זכות חוקית (סעיף 30 לפקודת הנזיקין) ← ניתן לתבוע פינוי ופיצויים יחד.', '["פקודת הנזיקין [נוסח חדש], סעיפים 29, 30, 71, 76", "רע\"א 5058/99 אילנה כספי נ'' מנחם דויטש, פ\"ד נה(4) 529 (2001)", "ע\"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון (2006)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''nuisance_trespass'' | classifier_note: Trespass to apartment (הסגת גבול), tenant ousting + eviction tort', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על נטע להוכיח שיצחק שוהה בדירה שלא כדין. נטע זכאית לתבוע הן צו לפינויו של יצחק הן פיצויים באותה תביעה.', false, 'טענה זו שגויה. בתביעה על הסגת גבול במקרקעין, הנטל להוכיח שהמעשה היה כדין מוטל על הנתבע, ולא על התובע, בהתאם לסעיף 30 לפקודת הנזיקין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על יצחק להוכיח שהוא שוהה בדירה כדין. נטע זכאית לתבוע הן צו לפינויו של יצחק הן פיצויים באותה תביעה.', true, 'תשובה זו נכונה. סעיף 30 לפקודת הנזיקין קובע כי הנטל להוכיח שהמעשה לא היה שלא כדין מוטל על הנתבע. נטע, כשוכרת, היא ''מחזיק'' וזכאית לתבוע סילוק יד ופיצויים בגין הסגת גבול, כפי שנקבע בפסיקה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על יצחק להוכיח שהוא שוהה בדירה כדין. נטע זכאית לתבוע צו לפינויו של יצחק, אך עליה להגיש תביעה נפרדת לפיצויים.', false, 'טענה זו שגויה. אין מניעה לתבוע צו פינוי ופיצויים באותה תביעה נזיקית בגין הסגת גבול, שכן שניהם סעדים הנובעים מאותה עוולה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'נטע אינה זכאית לתבוע את יצחק מאחר שהיא אינה בעלת הדירה.', false, 'טענה זו שגויה. עוולת הסגת גבול במקרקעין נועדה להגן על זכות ההחזקה, ולכן גם שוכר (מחזיק) זכאי לתבוע בגינה, ולא רק הבעלים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'נטל ההוכחה בתביעת סילוק יד',
    1, 'ראובן, בעל מקרקעין רשום, גילה כי שמעון בנה מחסן על חלק מאדמתו ללא רשותו. ראובן הגיש תביעה לסילוק יד. מהו נטל ההוכחה המוטל על הצדדים בתביעה זו?', 'שאלה זו עוסקת בנטל ההוכחה בתביעת סילוק יד ממקרקעין, המבוססת על זכות קניינית של התובע. היא מדגישה את הכלל לפיו די בהוכחת הבעלות כדי להעביר את הנטל לנתבע להוכיח זכות חוקית להחזקה.', 'בתביעה לסילוק יד ממקרקעין, המבוססת על זכות קניינית, הכלל הוא כי על התובע להוכיח את בעלותו במקרקעין. משעשה כן, עובר הנטל לנתבע להוכיח כי הוא מחזיק במקרקעין כדין. הלכה זו נקבעה בפסיקה עקבית, בין היתר, בע"א 127/77 קפה נ'' לוי. סעיף 16 לחוק המקרקעין, תשכ"ט-1969, קובע כי ''בעל מקרקעין ומי שזכאי להחזיק בהם זכאי לדרוש מסירת המקרקעין ממי שמחזיק בהם שלא כדין''. סעיף 30 לפקודת הנזיקין [נוסח חדש] מחזק זאת בקובעו כי ''בתובענה שהוגשה על הסגת גבול במקרקעין על הנתבע הראיה שהמעשה שעליו מתלוננים לא היה שלא כדין''. לכן, ראובן צריך להוכיח את בעלותו, ואז שמעון צריך להוכיח שיש לו זכות חוקית להחזיק במחסן. סעיף 30 לפקודת הנזיקין | חובת הראיה',
    'הטעות הנפוצה היא לחשוב שעל התובע להוכיח יסוד שלילי, כלומר, שהנתבע מחזיק שלא כדין, בעוד שהנטל להוכחת זכות חוקית מוטל על הנתבע.', '["נטל הוכחה", "סילוק יד", "הסגת גבול", "חוק המקרקעין סעיף 16", "פקודת הנזיקין סעיף 30", "בעלות במקרקעין"]'::jsonb, '**וריאציה 1 — תביעה קניינית מול נזיקית:** האם יש הבדל בנטל ההוכחה בין תביעת סילוק יד מכוח סעיף 16 לחוק המקרקעין לבין תביעה מכוח עוולת הסגת גבול? ← לא, הפסיקה קבעה כי בשני המקרים, לאחר שהתובע הוכיח את זכותו (בעלות/החזקה), הנטל עובר לנתבע להוכיח זכות חוקית להחזקה (ע"א 127/77 קפה נ'' לוי).
**וריאציה 2 — רף ראייתי נמוך:** מהו הרף הראייתי הנדרש מהתובע להוכחת העדר זכותו של הנתבע? ← כאשר מדובר ביסוד שלילי (העדר זכות), די ברף ראייתי נמוך כדי להעביר את הנטל המשני להבאת ראיות לנתבע (רע"א 4311/00 מדינת ישראל נ'' בן שמחון).
**וריאציה 3 — כניסה ברשות שבוטלה:** מה הדין אם שמעון נכנס למקרקעין ברשות, אך הרשות בוטלה? ← גם במקרה כזה, אם שמעון ממשיך להחזיק במקרקעין לאחר ביטול הרשות, הוא הופך למסיג גבול, ונטל ההוכחה לזכותו להחזיק עובר אליו (ע"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון).', 'תביעת סילוק יד ← תובע מוכיח בעלות/זכות להחזיק ← נטל עובר לנתבע להוכיח זכות חוקית להחזקה (סעיף 16 לחוק המקרקעין, סעיף 30 לפקודת הנזיקין).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 16", "פקודת הנזיקין [נוסח חדש], סעיף 30", "ע\"א 127/77 מלכה קפה נ'' יוסף לוי, פ\"ד לא(3) 455 (1977)", "רע\"א 4311/00 מדינת ישראל נ'' אליעזר בן שמחון, פ\"ד נח(1) 827 (2003)", "ע\"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון (2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'על ראובן להוכיח את בעלותו במקרקעין, ועל שמעון להוכיח זכות חוקית להחזיק בהם.', true, 'תשובה זו נכונה. בתביעת סילוק יד, התובע (ראובן) צריך להוכיח את בעלותו, ואז הנטל עובר לנתבע (שמעון) להוכיח זכות חוקית להחזיק במקרקעין, בהתאם לסעיף 16 לחוק המקרקעין וסעיף 30 לפקודת הנזיקין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'על ראובן להוכיח הן את בעלותו והן את העדר זכותו של שמעון להחזיק במקרקעין.', false, 'טענה זו שגויה. בעוד שעל התובע להוכיח את זכותו, הנטל להוכחת העדר זכותו של הנתבע עובר לנתבע עצמו, במיוחד כאשר מדובר ביסוד שלילי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'על שמעון להוכיח כי הבנייה נעשתה בתום לב, וכי ראובן ידע עליה ולא התנגד.', false, 'טענה זו שגויה. תום לב וידיעה של הבעלים עשויים להשפיע על הסעדים, אך אינם משנים את נטל ההוכחה הראשוני של זכות חוקית להחזקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'על ראובן להוכיח כי נגרם לו נזק ממון כתוצאה מהבנייה, ורק אז יעבור הנטל לשמעון.', false, 'טענה זו שגויה. הוכחת נזק ממון נדרשת לפיצויים בעוולת הסגת גבול (סעיף 29 סיפא), אך לא לצורך סילוק יד מכוח בעלות (סעיף 16 לחוק המקרקעין).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסודות עוולת הסגת גבול',
    2, 'מהם היסודות הנדרשים להוכחת עוולת הסגת גבול במקרקעין, לפי סעיף 29 לפקודת הנזיקין?', 'שאלה זו מתמקדת ביסודות עוולת הסגת גבול במקרקעין, כפי שהיא מוגדרת בסעיף 29 לפקודת הנזיקין. היא מבהירה את הצורך בקיום אחד מיסודות הפגיעה (כניסה, היזק או הפרעה) ואת הדרישה לנזק ממון כתנאי לפיצויים.', 'סעיף 29 לפקודת הנזיקין [נוסח חדש] מגדיר את עוולת הסגת גבול במקרקעין בשני חלקים. הרישא קובעת את יסודות העוולה: ''הסגת גבול במקרקעין היא כניסה למקרקעין שלא כדין, או היזק או הפרעה בידי אדם למקרקעין שלא כדין''. הסיפא קובעת תנאי לפיצויים: ''אך אין תובע יכול להיפרע פיצויים על הסגת גבול במקרקעין אלא אם סבל על ידי כך נזק ממון''. כלומר, כדי שהעוולה תתקיים, יש להוכיח כניסה, היזק או הפרעה למקרקעין, ושהמעשה נעשה ''שלא כדין''. כדי לקבל פיצויים, יש להוכיח בנוסף נזק ממון. העוולה נועדה להגן על זכות ההחזקה במקרקעין. סעיף 29 לפקודת הנזיקין | הסגת גבול במקרקעין',
    'הטעות הנפוצה היא לבלבל בין יסודות העוולה לבין התנאים לקבלת פיצויים, או לחשוב שיש צורך ביסוד נפשי של כוונה להסיג גבול.', '["הסגת גבול במקרקעין", "פקודת הנזיקין סעיף 29", "כניסה שלא כדין", "היזק למקרקעין", "הפרעה למקרקעין", "נזק ממון"]'::jsonb, '**וריאציה 1 — טעות בתום לב:** האם טעות בתום לב לגבי הבעלות או זכות ההחזקה מהווה הגנה מפני עוולת הסגת גבול? ← לא, סעיף 33 לפקודת הנזיקין קובע כי ''טעות בנוגע לבעלות או לזכות החזקה, ואפילו טעות בתום לב... אינן הצדק להפרעה בנכסיו של אחר'' (ת"א (שלום נצ'') 32293-09-19 אילן סירי נ'' שובל עזאני).
**וריאציה 2 — הגנה על החזקה:** מי זכאי לתבוע בגין הסגת גבול? ← העוולה נועדה להגן על החזקה, ולכן זכות התביעה נתונה למחזיק בפועל או לבעל הזכות להחזקה מיידית (רע"א 5058/99 כספי נ'' דויטש).
**וריאציה 3 — היזק או הפרעה:** האם הסגת גבול חייבת להיות כניסה פיזית? ← לא, הסעיף כולל גם ''היזק או הפרעה בידי אדם למקרקעין שלא כדין'', גם אם אין כניסה פיזית ממשית (ע"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון).', 'הסגת גבול ← כניסה/היזק/הפרעה שלא כדין (סעיף 29 רישא) + נזק ממון לפיצויים (סעיף 29 סיפא).',
    '["פקודת הנזיקין [נוסח חדש], סעיפים 29, 33", "רע\"א 5058/99 אילנה כספי נ'' מנחם דויטש, פ\"ד נה(4) 529 (2001)", "ע\"א (מחוזי תל אביב-יפו) 2213/04 לילי ארז נ'' מדינת ישראל- משרד הביטחון (2006)", "ת\"א (שלום נצ'') 32293-09-19 אילן סירי נ'' שובל עזאני (2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כניסה למקרקעין שלא כדין, או היזק או הפרעה למקרקעין שלא כדין, וכן נזק ממון שנגרם לתובע.', true, 'תשובה זו נכונה. סעיף 29 לפקודת הנזיקין מגדיר את העוולה כ''כניסה למקרקעין שלא כדין, או היזק או הפרעה בידי אדם למקרקעין שלא כדין'', ומוסיף כי ''אין תובע יכול להיפרע פיצויים על הסגת גבול במקרקעין אלא אם סבל על ידי כך נזק ממון''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כניסה למקרקעין שלא כדין, וכן כוונה של הנתבע להסיג גבול.', false, 'טענה זו שגויה. עוולת הסגת גבול אינה דורשת יסוד נפשי של כוונה. גם טעות בתום לב אינה מהווה הגנה, כפי שנקבע בסעיף 33 לפקודת הנזיקין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הוכחת בעלות התובע במקרקעין, וכן העדר הסכמה של התובע לכניסת הנתבע.', false, 'טענה זו שגויה. העוולה מגינה על החזקה, לאו דווקא על הבעלות. כמו כן, העדר הסכמה הוא חלק מיסוד ''שלא כדין'', אך אינו היסוד היחיד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הוכחת נזק ממון בלבד, ללא צורך להוכיח כניסה או הפרעה למקרקעין.', false, 'טענה זו שגויה. נזק ממון הוא תנאי לפיצויים, אך לא לעצם קיום העוולה. יש להוכיח גם את יסודות הכניסה, ההיזק או ההפרעה שלא כדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הגבלת סעד סילוק יד בתום לב',
    3, 'ראובן בנה בטעות מחסן על חלקת אדמה השייכת לשמעון, מתוך אמונה כנה שהשטח שלו. שמעון דורש את הריסת המחסן. האם בית המשפט חייב להיעתר לדרישתו של שמעון להריסת המחסן?', 'שאלה זו עוסקת בהגבלת זכות הקניין ובשיקול דעתו של בית המשפט במתן סעדים, ובפרט צווי הריסה, במקרים של הסגת גבול ובנייה שלא כדין. היא מתייחסת לעקרונות תום הלב ואיסור שימוש לרעה בזכות, כפי שפורשו בפסיקה (הלכת רוקר).', 'זכות הקניין, אף שהיא זכות יסוד חוקתית, אינה מוחלטת וכפופה לעקרונות תום הלב ואיסור שימוש לרעה בזכות. סעיף 14 לחוק המקרקעין, תשכ"ט-1969, קובע כי ''בעלות וזכויות אחרות במקרקעין, אין בהן כשלעצמן כדי להצדיק עשיית דבר הגורם נזק או אי נוחות לאחר''. הפסיקה, ובראשה הלכת רוקר נ'' סלומון (רע"א 6339/97), קבעה כי לבית המשפט נתון שיקול דעת רחב בבואו להעניק סעדים בגין פגיעה בזכות קניינית, ובמקרים חריגים הוא רשאי להימנע ממתן צו הריסה, גם אם מדובר בבנייה שלא כדין. שיקול הדעת יופעל תוך בחינת עוצמת הפגיעה בזכות הקניינית, עוצמת התוצאות של הסרת הפגיעה (הריסה), והתנהגות הצדדים, לרבות תום ליבו של הפולש. במקרה של בנייה בתום לב, בית המשפט עשוי להעדיף פיצוי כספי על פני הריסה. סעיף 71 לפקודת הנזיקין | פיצויים',
    'הטעות הנפוצה היא לראות בזכות הקניין זכות מוחלטת שאינה ניתנת להגבלה, ולהתעלם מהשפעת עקרונות תום הלב על הסעדים הניתנים בגין פגיעה בה.', '["זכות קניין", "תום לב", "איסור שימוש לרעה בזכות", "סעיף 14 לחוק המקרקעין", "הלכת רוקר", "צו הריסה"]'::jsonb, '**וריאציה 1 — שיקולי בית המשפט:** מהם השיקולים המנחים את בית המשפט בהפעלת שיקול דעתו? ← עוצמתה של הזכות הקניינית שנפגעה, עוצמת הפגיעה בזכות, עוצמת התוצאות של הסרת הפגיעה (הריסה), והתנהגות בעלי הדין (הלכת רוקר).
**וריאציה 2 — פיצוי במקום הריסה:** באילו מקרים בית המשפט יעדיף פיצוי כספי על פני הריסה? ← כאשר הפגיעה קטנה, ניתנת להערכה בכסף ולפיצוי מספיק, ומתן צו הריסה יהווה התעמרות בנתבע (סעיף 74 לפקודת הנזיקין; ע"א 44/76 אתא חברה לטכסטיל בע"מ נ'' שוורץ).
**וריאציה 3 — הסגת גבול תת-קרקעית:** האם הסגת גבול תת-קרקעית (כמו יסודות בניין) כפופה לאותם שיקולים? ← כן, גם במקרים של פלישה תת-קרקעית, בית המשפט יפעיל שיקול דעת דומה, תוך בחינת הנסיבות והאיזון בין זכויות הצדדים (תא"מ (שלום קריות) 2855-04 חאלד חמאדה נ'' אחמד נאסר בע"מ).', 'זכות קניין אינה מוחלטת ← כפופה לתום לב (סעיף 14 לחוק המקרקעין) ← בית המשפט רשאי להימנע מצו הריסה במקרים חריגים (הלכת רוקר).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 14", "פקודת הנזיקין [נוסח חדש], סעיפים 71, 74", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 39", "רע\"א 6339/97 משה רוקר נ'' משה סלומון, פ\"ד נה(1) 199 (1999)", "ע\"א 44/76 אתא חברה לטכסטיל בע\"מ נ'' זאב שוורץ, פ\"ד ל(3) 785 (1976)", "תא\"מ (שלום קריות) 2855-04 חאלד חמאדה נ'' אחמד נאסר בע\"מ (2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, זכות הקניין של שמעון היא מוחלטת, ובית המשפט חייב להגן עליה באמצעות צו הריסה.', false, 'טענה זו שגויה. זכות הקניין אינה מוחלטת וכפופה לעקרונות תום הלב ואיסור שימוש לרעה בזכות, כפי שנקבע בפסיקה (הלכת רוקר).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, בית המשפט רשאי להפעיל שיקול דעת ולהימנע ממתן צו הריסה, אם הדבר יהווה שימוש לרעה בזכות או התעמרות בראובן, תוך התחשבות בעוצמת הפגיעה ובנסיבות העניין.', true, 'תשובה זו נכונה. הפסיקה (הלכת רוקר) קבעה כי זכות הקניין כפופה לעקרון תום הלב (סעיף 39 לחוק החוזים) ואיסור שימוש לרעה בזכות (סעיף 14 לחוק המקרקעין), ובית המשפט רשאי להפעיל שיקול דעת במתן סעדים, לרבות הימנעות מצו הריסה במקרים חריגים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן ראובן יוכיח כי שמעון ידע על הבנייה ולא התנגד לה במשך שנים רבות.', false, 'טענה זו שגויה. ידיעה ושיהוי של הבעלים עשויים להשפיע על שיקול הדעת, אך אינם התנאי היחיד להימנעות מצו הריסה. המבחן רחב יותר וכולל את עקרון תום הלב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן שמעון יסכים לקבל פיצוי כספי במקום הריסת המחסן.', false, 'טענה זו שגויה. הסכמת הבעלים לקבל פיצוי היא אפשרות, אך בית המשפט יכול להחליט על כך גם ללא הסכמה, מכוח שיקול דעתו ובהתאם לעקרונות תום הלב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים חלופיים בהסגת גבול',
    4, 'ראובן הסיג גבול במקרקעין של שמעון ועשה בהם שימוש ללא רשות. שמעון מעוניין לתבוע פיצוי כספי. אילו עילות תביעה עומדות לרשותו של שמעון, ומה ההבדל ביניהן?', 'שאלה זו בוחנת את הסעדים הכספיים העומדים לרשות בעל מקרקעין שנפגע מהסגת גבול, תוך התמקדות בהבחנה בין עוולת הסגת גבול (נזיקין) לבין עילת עשיית עושר ולא במשפט, ובדרישות ההוכחה הייחודיות לכל אחת מהן.', 'כאשר מקרקעין נתפסים או נעשה בהם שימוש שלא כדין, עומדות לבעל הזכות שתי עילות תביעה עיקריות לסעד כספי: עוולת הסגת גבול לפי סעיף 29 לפקודת הנזיקין [נוסח חדש], ועילת עשיית עושר ולא במשפט לפי חוק עשיית עושר ולא במשפט, תשל"ט-1979. ההבדל המהותי הוא שבעוולת הסגת גבול, התובע נדרש להוכיח ''נזק ממון'' שנגרם לו כתוצאה מההסגה (למשל, דמי שכירות ראויים שהיה יכול לקבל). בעילת עשיית עושר ולא במשפט, התובע נדרש להוכיח את ''התעשרותו'' של הנתבע שלא כדין (כלומר, את הרווח שהפיק או את החיסכון בדמי שימוש). דמי שימוש ראויים יכולים לשמש מדד בשתי העילות, אך בנזיקין הם נחשבים לנזק, ובעשיית עושר הם נחשבים לרווח שהנתבע חסך. התובע רשאי לבחור באיזו עילה לתבוע, או לתבוע בשתיהן במצטבר, ובלבד שלא יקבל כפל פיצוי. סעיף 29 לפקודת הנזיקין | הסגת גבול במקרקעין',
    'הטעות הנפוצה היא לבלבל בין דרישות ההוכחה של שתי העילות, או לחשוב שאחת מהן שוללת את השנייה. יש להבין את ההבחנה בין פיצוי על נזק לבין השבה על התעשרות.', '["הסגת גבול במקרקעין", "עשיית עושר ולא במשפט", "נזק ממון", "דמי שימוש ראויים", "פיצויים", "השבה"]'::jsonb, '**וריאציה 1 — הוכחת נזק ממון:** האם תמיד קל להוכיח נזק ממון בעוולת הסגת גבול? ← לא תמיד. במקרים רבים, קשה להוכיח נזק ממון ספציפי, ולכן הפסיקה מאפשרת להסתמך על דמי שימוש ראויים כמדד לנזק (ע"א 19/83 חברת שלמה כרמל בע"מ נ'' בריח חברה לייצור בע"מ).
**וריאציה 2 — צירוף עילות:** האם ניתן לצרף את שתי העילות (נזיקין ועשיית עושר) באותה תביעה? ← כן, ניתן לצרף עילות תביעה מקבילות, ובלבד שלא יינתן כפל פיצוי (ע"א 588/87 כהן נ'' שמש; ת"א (מחוזי ת"א) 2336-04 עיריית ראשון לציון נ'' משה קידר).
**וריאציה 3 — נזק לא ממוני:** האם ניתן לתבוע פיצוי על עוגמת נפש בעוולת הסגת גבול? ← ככלל, סעיף 29 לפקודת הנזיקין דורש נזק ממון לפיצויים. עם זאת, במקרים מסוימים, אם הוכח נזק ממון, ניתן לפסוק גם פיצוי על עוגמת נפש כסעד נלווה (ת"א (שלום נצ'') 5053/98 סימון ח''ורי נ'' נעמה אבראהים נסייר).', 'פיצוי כספי בהסגת גבול ← נזיקין (נזק ממון) או עשיית עושר (התעשרות) ← דמי שימוש ראויים יכולים לשמש מדד בשתיהן.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 29", "חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 1", "ע\"א 19/83 חברת שלמה כרמל בע\"מ נ'' בריח חברה לייצור בע\"מ, פ\"ד לט(4) 522 (1985)", "ע\"א 588/87 כהן נ'' שמש, פ\"ד מה(5) 297 (1991)", "ת\"א (מחוזי ת\"א) 2336-04 עיריית ראשון לציון נ'' משה קידר (2011)", "ת\"א (שלום נצ'') 5053/98 סימון ח''ורי נ'' נעמה אבראהים נסייר (2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'עוולת הסגת גבול (פקודת הנזיקין) ועשיית עושר ולא במשפט (חוק עשיית עושר ולא במשפט). בעוולת הסגת גבול נדרש להוכיח נזק ממון, ובעשיית עושר נדרש להוכיח את התעשרות המסיג גבול.', true, 'תשובה זו נכונה. אלו הן שתי העילות העיקריות לתביעת פיצויים כספיים בגין הסגת גבול, וההבחנה ביניהן נעוצה בדרישת הוכחת נזק (בנזיקין) מול הוכחת התעשרות (בעשיית עושר).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'עוולת הסגת גבול בלבד, שכן זו העילה היחידה המאפשרת פיצוי בגין פלישה למקרקעין.', false, 'טענה זו שגויה. לצד עוולת הסגת גבול, קיימת גם עילת עשיית עושר ולא במשפט, המאפשרת השבת רווחים שהופקו מהשימוש שלא כדין במקרקעין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'עשיית עושר ולא במשפט בלבד, שכן רק עילה זו מאפשרת קבלת דמי שימוש ראויים.', false, 'טענה זו שגויה. דמי שימוש ראויים יכולים להיפסק גם במסגרת עוולת הסגת גבול, כמדד לנזק הממון שנגרם לבעלים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'עוולת הסגת גבול, ובה ניתן לתבוע פיצויים גם בגין עוגמת נפש ללא הוכחת נזק ממון.', false, 'טענה זו שגויה. סעיף 29 לפקודת הנזיקין קובע במפורש כי ''אין תובע יכול להיפרע פיצויים על הסגת גבול במקרקעין אלא אם סבל על ידי כך נזק ממון''. עוגמת נפש אינה נזק ממון.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 38, '2019-S-S-Q38';
END
$$;

-- ============================================================
-- Q39 — 2019-S-S-Q39 — chapter=torts subtopic=road_accident_victims
-- classifier_note: Pedestrian + driver dispute over right-of-way; intentional vehicle strike → road-accident victims compensation (PLT'D)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e0d3e631-ff6e-446d-9ffa-f15a7cbe68e8'::uuid;
  v_group_id uuid := 'aa43d32f-7cb0-450b-abd7-12bdbf617dca'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'd6b57146-9d26-4eef-b415-ea3c4899acfa'::uuid;
  v_ang_1 uuid := 'a9f3aa4f-e208-40bd-85ba-cff851ac4e1c'::uuid;
  v_ang_2 uuid := '20ddcf3b-dc7d-431c-9127-7af7b4520514'::uuid;
  v_ang_3 uuid := '473ae0b0-927d-4a21-9264-6e51ac008b3f'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-S-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 39, '2019-S-S-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'road_accident_victims' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'road_accident_victims', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q39', v_chapter_id, v_subtopic_id, 'בין יצחק – הולך רגל – לבין יעקב, שנהג ברכב בסמוך אליו, התפתח ויכוח בדבר זכות קדימה, ויעקב פגע ביצחק ברכבו במתכוון ואגב כך נפגע בעצמו עקב איבוד השליטה ברכבו. הן ליצחק הן ליעקב נגרם נזק גוף בשל האירוע. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 39}'::jsonb, 'השאלה עוסקת בסיווג אירוע שבו נגרם נזק גוף כתוצאה ממעשה מכוון, ובחינת תחולת חוק פיצויים לנפגעי תאונות דרכים, תשל"ה-1975 (הפלת"ד). היא מתמקדת בחזקה הממעטת שבסעיף 1 לחוק, השוללת את סיווג האירוע כתאונת דרכים במקרים של מעשה מכוון, וכן בשלילת זכאותו של נפגע שגרם לתאונה במתכוון לפי סעיף 7(1) לחוק, ובחריג לייחוד העילה שבסעיף 8(א).', 'האירוע המתואר בשאלה, שבו יעקב פגע ביצחק ברכבו במתכוון, אינו נחשב ל"תאונת דרכים" כהגדרתה בסעיף 1 לחוק הפלת"ד. זאת בשל החזקה הממעטת הקבועה בסיפא לסעיף זה, הקובעת כי "לא יראו כתאונת דרכים מאורע שאירע כתוצאה ממעשה שנעשה במתכוון כדי לגרום נזק לגופו או לרכושו של אותו אדם, והנזק נגרם על ידי המעשה עצמו ולא על ידי השפעתו של המעשה על השימוש ברכב המנועי". במקרה זה, הפגיעה ביצחק הייתה מכוונת, והנזק נגרם ישירות מהמעשה המכוון (הפגיעה ברכב), ולא מהשפעת המעשה על השימוש ברכב. לכן, יצחק אינו זכאי לפיצויים מכוח חוק הפלת"ד. עם זאת, סעיף 8(א) לחוק הפלת"ד קובע חריג לעקרון ייחוד העילה, המאפשר לנפגע בתאונה שנגרמה על ידי אדם אחר במתכוון לתבוע לפי פקודת הנזיקין. לפיכך, יצחק זכאי לתבוע את יעקב מכוח פקודת הנזיקין. סעיף 1 לחוק פיצויים לנפגעי תאונות דרכים | הגדרותסעיף 8(א) לחוק פיצויים לנפגעי תאונות דרכים | ייחוד העילהבאשר ליעקב, הוא גרם לתאונה במתכוון. גם לגביו, האירוע אינו תאונת דרכים בשל החזקה הממעטת. בנוסף, סעיף 7(1) לחוק הפלת"ד שולל זכאות לפיצויים מ"מי שגרם לתאונה במתכוון". לכן, יעקב אינו זכאי לפיצויים מכוח חוק הפלת"ד. כמו כן, הוא אינו יכול לתבוע את יצחק או אחרים מכוח פקודת הנזיקין, שכן הוא עצמו גרם לנזק במתכוון. סעיף 7(1) לחוק פיצויים לנפגעי תאונות דרכים | הגבלת זכאותם של נפגעים', 'הטעות הנפוצה היא לבלבל בין שני היסודות של החזקה הממעטת בסעיף 1 לחוק הפלת"ד, או להתעלם משלילת הזכאות בסעיף 7(1) לחוק, וכן מהחריג לעקרון ייחוד העילה בסעיף 8(א).',
    '["חוק פיצויים לנפגעי תאונות דרכים", "תאונה מכוונת", "חזקה ממעטת", "ייחוד העילה", "פקודת הנזיקין", "שלילת זכאות"]'::jsonb, '**וריאציה 1 — סיווג האירוע:** האם אירוע של פגיעה מכוונת ברכב הוא תמיד מחוץ להגדרת ''תאונת דרכים''? ← לא תמיד. אם הנזק נגרם על ידי השפעת המעשה על השימוש ברכב המנועי (ולא על ידי המעשה עצמו), האירוע ייחשב לתאונת דרכים (סעיף 1 סיפא לחוק הפלת"ד).
**וריאציה 2 — תלויים בנפגע:** האם תלויים ביעקב (הנהג הפוגע) זכאים לפיצויים? ← לא, מכיוון שהאירוע אינו תאונת דרכים בשל החזקה הממעטת, חוק הפלת"ד אינו חל כלל, ולכן גם התלויים אינם זכאים לפיצויים (אליעזר ריבלין, תאונת הדרכים, עמ'' 19).
**וריאציה 3 — תביעה נזיקית של יעקב:** האם יעקב יכול לתבוע את יצחק בנזיקין? ← לא, שכן יעקב הוא זה שגרם לנזק במתכוון, ואין לו עילת תביעה נזיקית כנגד יצחק בנסיבות אלו.', 'פגיעה מכוונת ברכב ← אינה תאונת דרכים (סעיף 1 לפלת"ד) ← הנפגע (יצחק) תובע בנזיקין (חריג סעיף 8(א)). הגורם (יעקב) ← נשללת זכאותו (סעיף 7(1) לפלת"ד) ואינו יכול לתבוע כלל.', '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיפים 1, 7(1), 8(א)", "אליעזר ריבלין תאונת הדרכים (2020) | תוצאותיה של שלילת הזכאות"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''road_accident_victims'' | classifier_note: Pedestrian + driver dispute over right-of-way; intentional vehicle strike → road-accident victims compensation (PLT''D) | source_review_note: השאלה עוסקת בדיני נזיקין (פלת"ד), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יצחק זכאי להגיש תביעה נגד מבטחת הרכב של יעקב ונגד יעקב, הן מכוח חוק הפלת"ד הן מכוח פקודת הנזיקין. יעקב אינו זכאי כלל להגיש תביעה.', false, 'טענה זו שגויה. יצחק אינו זכאי לתבוע מכוח חוק הפלת"ד, שכן האירוע אינו נחשב לתאונת דרכים בשל החזקה הממעטת של מעשה מכוון. הוא זכאי לתבוע את יעקב רק מכוח פקודת הנזיקין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יצחק זכאי להגיש תביעה נגד מבטחת הרכב של יעקב מכוח חוק הפלת"ד. יעקב זכאי להגיש תביעה מכוח חוק הפלת"ד נגד קרנית.', false, 'טענה זו שגויה. יצחק אינו זכאי לתבוע מכוח חוק הפלת"ד, ויעקב אינו זכאי לתבוע מכוח חוק הפלת"ד (לא ממבטח ולא מקרנית), שכן שניהם נפגעו ממעשה מכוון, ויעקב אף גרם לתאונה במתכוון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יצחק זכאי להגיש תביעה נגד יעקב מכוח פקודת הנזיקין. יעקב אינו זכאי כלל להגיש תביעה.', true, 'תשובה זו נכונה. האירוע אינו תאונת דרכים בשל החזקה הממעטת של מעשה מכוון, ולכן יצחק אינו זכאי לפיצויים מכוח הפלת"ד אך יכול לתבוע בנזיקין. יעקב גרם לתאונה במתכוון, ולכן אינו זכאי לפיצויים כלל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יצחק זכאי להגיש תביעה נגד מבטחת הרכב של יעקב ונגד יעקב, הן מכוח חוק הפלת"ד הן מכוח פקודת הנזיקין. יעקב זכאי להגיש תביעה מכוח חוק הפלת"ד נגד קרנית.', false, 'טענה זו שגויה. יצחק אינו זכאי לתבוע מכוח חוק הפלת"ד, ויעקב אינו זכאי לתבוע מכוח חוק הפלת"ד (לא ממבטח ולא מקרנית), שכן שניהם נפגעו ממעשה מכוון, ויעקב אף גרם לתאונה במתכוון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'נטל ההוכחה בחזקה הממעטת',
    1, 'פלוני נפגע בתאונת פגע וברח, וזהות הנהג הפוגע אינה ידועה. פלוני הגיש תביעה נגד קרנית. קרנית טוענת כי מדובר בתאונה מכוונת, ולכן האירוע אינו תאונת דרכים. על מי מוטל נטל ההוכחה לטענה זו?', 'שאלה זו עוסקת בנטל ההוכחה בתביעות לפי חוק פיצויים לנפגעי תאונות דרכים, ובפרט כאשר נטענת החזקה הממעטת של ''תאונה מכוונת''. היא מבהירה כי הנטל מוטל על הצד הטוען לחזקה זו, וכי רמת ההוכחה הנדרשת היא במאזן הסתברויות.', 'החזקה הממעטת שבסעיף 1 לחוק פיצויים לנפגעי תאונות דרכים, תשמ"ה-1975, קובעת כי אירוע שנגרם כתוצאה ממעשה מכוון אינו נחשב לתאונת דרכים. הנטל להוכיח את קיומה של חזקה ממעטת זו מוטל על הצד הטוען לה, במקרה זה קרנית או חברת הביטוח. נטל ההוכחה הוא בהתאם לכלל הרגיל במשפט אזרחי, כלומר, במאזן הסתברויות. על הטוען לתאונה מכוונת להוכיח כי התקיימו שני היסודות המצטברים של החזקה הממעטת: א. התאונה נגרמה כתוצאה ממעשה מכוון שנועד לגרום נזק לגופו או לרכושו של אדם. ב. הנזק נגרם על ידי המעשה עצמו, במישרין, להבדיל מהשפעתו של המעשה על השימוש ברכב המנועי. ת"א (שלום ת"א) 5021-07-14 משה אפל נ'' קרנית קרן לפיצוי נפגעי תאונת דרכים (29.03.2017)ת"א (שלום עכו) 25227-01-17 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (24.04.2020)רע"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)',
    'הטעות הנפוצה היא להניח שנטל ההוכחה מוטל תמיד על התובע, גם כאשר הנתבע מעלה טענת הגנה המבוססת על חזקה ממעטת.', '["נטל הוכחה", "חזקה ממעטת", "תאונה מכוונת", "מאזן הסתברויות", "חוק פיצויים לנפגעי תאונות דרכים", "קרנית"]'::jsonb, '**וריאציה 1 — רמת ההוכחה:** האם נטל ההוכחה משתנה אם מדובר בטענה פלילית (כוונה לפגוע)? ← לא, גם אם הטענה נושאת אופי פלילי, במשפט אזרחי נטל ההוכחה נותר במאזן הסתברויות (ע"א 2781/93 דעקה נ'' בית החולים "כרמל").
**וריאציה 2 — קושי בהוכחת כוונה:** האם קושי בהוכחת כוונת הפוגע משפיע על הנטל? ← קושי בהוכחה אינו משנה את הנטל, אך עשוי להקשות על הצד שעליו הנטל לעמוד בו. הפסיקה מכירה בכך שקשה להוכיח כוונה, ולכן נדרשת מסקנה ברורה ומסתברת ממעשיו של הפוגע (רע"א 1117/09 קרנית נ'' בלבן).
**וריאציה 3 — עמימות ראייתית:** מה קורה כאשר הראיות עמומות ואינן מאפשרות הכרעה ברורה? ← במקרה של עמימות ראייתית, הצד שעליו נטל ההוכחה לא עמד בו, ולכן הטענה לא תתקבל (ע"א 59408-09-19 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים).', 'נטל הוכחה לחזקה ממעטת ← על הטוען אותה (קרנית/מבטח) ← במאזן הסתברויות.',
    '["ת\"א (שלום ת\"א) 5021-07-14 משה אפל נ'' קרנית קרן לפיצוי נפגעי תאונת דרכים (29.03.2017)", "רע\"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)", "ת\"א (שלום עכו) 25227-01-17 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונות דרכים (24.04.2020)", "ע\"א 59408-09-19 פלוני נ'' קרנית-קרן לפיצוי נפגעי תאונת דרכים (23.01.2020)", "ע\"א 2781/93 דעקה נ'' בית החולים \"כרמל\", פ\"ד נג(4) 122 (1999)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'על פלוני להוכיח כי לא מדובר בתאונה מכוונת, שכן הוא התובע.', false, 'טענה זו שגויה. הנטל להוכחת החזקה הממעטת מוטל על הטוען אותה, במקרה זה קרנית, ולא על התובע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'על קרנית להוכיח כי מדובר בתאונה מכוונת, וזאת במאזן הסתברויות.', true, 'תשובה זו נכונה. הנטל להוכיח את קיומה של החזקה הממעטת מוטל על הטוען אותה, במקרה זה קרנית, וזאת בהתאם לכלל הרגיל במשפט אזרחי במאזן ההסתברויות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'על קרנית להוכיח כי מדובר בתאונה מכוונת, וזאת מעבר לספק סביר.', false, 'טענה זו שגויה. הנטל הנדרש להוכחת החזקה הממעטת הוא במאזן הסתברויות, כמקובל במשפט אזרחי, ולא מעבר לספק סביר, המאפיין את המשפט הפלילי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הנטל מוטל על בית המשפט לקבוע אם מדובר בתאונה מכוונת, על בסיס הראיות שהוצגו.', false, 'טענה זו שגויה. בית המשפט מכריע על בסיס הראיות, אך הנטל להבאת הראיות ולהוכחת הטענה מוטל על הצד הטוען אותה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני הכוונה בחזקה הממעטת',
    2, 'מהי הפרשנות למונח "מעשה שנעשה במתכוון כדי לגרום נזק לגופו או לרכושו של אותו אדם" שבחזקה הממעטת בסעיף 1 לחוק הפלת"ד?', 'שאלה זו עוסקת בפרשנות יסוד ה''כוונה'' בחזקה הממעטת שבסעיף 1 לחוק הפלת"ד. היא מדגישה את הפרשנות המצמצמת של הפסיקה למונח זה, הדורשת ''רצון חפצי'' של ממש בתוצאה של פגיעה, תוך התעלמות מהמניע.', 'החזקה הממעטת שבסעיף 1 לחוק פיצויים לנפגעי תאונות דרכים, תשמ"ה-1975, מוציאה אירוע שנגרם כתוצאה ממעשה מכוון מגדר ''תאונת דרכים''. הפסיקה מפרשת את יסוד ה''כוונה'' הנדרש בחזקה זו בצמצום. אין די במודעות לאפשרות קרובה לוודאי לגרימת הנזק (כפי שמקובל לעיתים בדין הפלילי), אלא נדרש ''רצון חפצי'' של ממש בתוצאה של פגיעה בגופו או ברכושו של האדם. כלומר, הפוגע צריך לרצות שהנזק יקרה. יחד עם זאת, נקבע כי אין חשיבות למניע העומד מאחורי הכוונה לפגוע. גם אם הפגיעה המכוונת היא אמצעי להשגת מטרה אחרת (למשל, הימלטות מגניבת רכב), עדיין תתקיים דרישת הכוונה. רע"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)ת"א (שלום ת"א) 20581-01-11 משה קוריאט נ'' קרנית קרן לפיצוי נפגעי תאונות דרכים (03.02.2015)אליעזר ריבלין תאונת הדרכים (2020) | המניע העומד מאחורי הכוונה לפגוע - אין לו חשיבות',
    'הטעות הנפוצה היא ליישם את מבחני הכוונה מהדין הפלילי (כמו מודעות לאפשרות קרובה לוודאי) על חוק הפלת"ד, או לחשוב שהמניע (למשל, גניבה) מבטל את יסוד הכוונה לפגוע.', '["כוונה", "רצון חפצי", "חזקה ממעטת", "חוק פיצויים לנפגעי תאונות דרכים סעיף 1", "מניע", "מודעות"]'::jsonb, '**וריאציה 1 — כוונה מועברת:** האם כוונה לפגוע באדם אחד שפגעה באדם אחר נחשבת כוונה לעניין החזקה הממעטת? ← לא, אם המזיק טעה בזהות הנפגע ופגע במי שלא נתכוון לו, הרי שמבחינת הנפגע שהפגיעה לא כוונה לו, אין זה מעשה מכוון וזו תאונת דרכים (אליעזר ריבלין, תאונת הדרכים, עמ'' 4).
**וריאציה 2 — כוונה כלפי ציבור:** מה הדין אם הכוונה הייתה לפגוע בציבור מסוים ונפגע אחד מבני הציבור? ← אם המזיק התכוון לפגוע בבני אדם באופן כללי והשיג את מטרתו, זו אינה תאונת דרכים (אליעזר ריבלין, תאונת הדרכים, עמ'' 4).
**וריאציה 3 — נהיגה בשכרות:** האם נהיגה בשכרות שגרמה לתאונה נחשבת למעשה מכוון? ← לא, מי שנוהג בשכרותו וגורם לתאונה אינו נחשב למי שגרם לתאונה במתכוון לעניין חוק הפלת"ד (אליעזר ריבלין, תאונת הדרכים, עמ'' 4).', 'כוונה בחזקה הממעטת ← רצון חפצי לפגיעה (לא מודעות) ← מניע לא רלוונטי (סעיף 1 לפלת"ד, הלכת בלבן).',
    '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 1", "רע\"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)", "ת\"א (שלום ת\"א) 20581-01-11 משה קוריאט נ'' קרנית קרן לפיצוי נפגעי תאונות דרכים (03.02.2015)", "אליעזר ריבלין תאונת הדרכים (2020) | הכוונה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'די במודעות לאפשרות קרובה לוודאי לגרימת הנזק, בדומה לדין הפלילי.', false, 'טענה זו שגויה. הפסיקה קבעה כי לעניין חוק הפלת"ד, יש לפרש את יסוד הכוונה בצמצום, ואין די במודעות לאפשרות קרובה לוודאי, אלא נדרש רצון חפצי של ממש בתוצאה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'נדרש רצון "חפצי" של ממש בתוצאה של פגיעה בגופו או ברכושו של האדם, ואין חשיבות למניע העומד מאחורי הכוונה.', true, 'תשובה זו נכונה. הפסיקה מפרשת את יסוד הכוונה בחוק הפלת"ד בצמצום, ודורשת רצון ממשי לפגוע. המניע (למשל, הימלטות מגניבה) אינו רלוונטי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'נדרש רצון "חפצי" של ממש בתוצאה של פגיעה, וכן מניע זדוני מובהק.', false, 'טענה זו שגויה. הפסיקה קבעה במפורש כי אין חשיבות למניע העומד מאחורי הכוונה לפגוע, ודי ברצון חפצי בתוצאה, גם אם הוא אמצעי להשגת מטרה אחרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'די בכוונה לגרום לתאונה ערטילאית, גם ללא כוונה לגרום נזק כלשהו.', false, 'טענה זו שגויה. כוונה לגרום ''תאונה בלא נזק'' אינה כוונה לגרום תאונה, וסעיף 1 לחוק דורש כוונה לגרום נזק לגוף או לרכוש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'נזק שנגרם מהשפעת המעשה על השימוש',
    3, 'אדם זרק אבן גדולה על רכב נוסע במטרה לפגוע בנהג. כתוצאה מכך, הנהג איבד שליטה על הרכב, סטה מנתיבו ופגע בהולך רגל שעמד בצד הדרך. הולך הרגל נפגע קשה. האם האירוע ייחשב לתאונת דרכים לעניין חוק הפלת"ד?', 'שאלה זו בוחנת את הסייג לחזקה הממעטת של ''תאונה מכוונת'' שבסעיף 1 לחוק הפלת"ד. היא מדגישה את ההבחנה בין נזק שנגרם ישירות מהמעשה המכוון לבין נזק שנגרם על ידי השפעת המעשה על השימוש ברכב המנועי, כאשר רק במקרה השני האירוע ייחשב לתאונת דרכים.', 'החזקה הממעטת שבסעיף 1 לחוק פיצויים לנפגעי תאונות דרכים, תשמ"ה-1975, קובעת כי ''לא יראו כתאונת דרכים מאורע שאירע כתוצאה ממעשה שנעשה במתכוון כדי לגרום נזק לגופו או לרכושו של אותו אדם, והנזק נגרם על ידי המעשה עצמו ולא על ידי השפעתו של המעשה על השימוש ברכב המנועי''. הסייג לחזקה הממעטת קובע כי אם הנזק נגרם על ידי השפעת המעשה המכוון על השימוש ברכב המנועי, אזי האירוע ייחשב לתאונת דרכים. במקרה הנדון, זריקת האבן הייתה מעשה מכוון לפגוע בנהג. אולם, הנזק להולך הרגל לא נגרם ישירות מזריקת האבן, אלא כתוצאה מאיבוד השליטה של הנהג על הרכב וסטייתו מנתיבו – כלומר, מהשפעת המעשה המכוון על השימוש התחבורתי ברכב. לכן, האירוע ייחשב לתאונת דרכים. סעיף 1 לחוק פיצויים לנפגעי תאונות דרכים | הגדרותרע"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)אליעזר ריבלין תאונת הדרכים (2020) | הרכב כזירה למעשה מכוון',
    'הטעות הנפוצה היא להתמקד רק בקיומו של מעשה מכוון, מבלי לבחון את הסייג לחזקה הממעטת, המבחין בין נזק ישיר מהמעשה לבין נזק עקיף הנובע מהשפעת המעשה על השימוש ברכב.', '["חזקה ממעטת", "סייג לחזקה הממעטת", "תאונה מכוונת", "שימוש ברכב מנועי", "קשר סיבתי", "חוק פיצויים לנפגעי תאונות דרכים סעיף 1"]'::jsonb, '**וריאציה 1 — דוגמה נוספת לסייג:** האם פגיעה ממעשה מכוון שגרם לנהג להתעלף, ולאחר מכן הרכב התנגש בעמוד, תיחשב לתאונת דרכים? ← כן, הנזק נגרם מהשפעת המעשה המכוון (התעלפות הנהג) על השימוש ברכב (התנגשות), ולכן חל הסייג לחזקה הממעטת (אליעזר ריבלין, תאונת הדרכים, עמ'' 12).
**וריאציה 2 — נזק ישיר מהמעשה:** מה הדין אם זריקת האבן פגעה ישירות בהולך הרגל, ללא מעורבות הרכב? ← במקרה כזה, הנזק נגרם ישירות מהמעשה המכוון, ולא מהשפעת המעשה על השימוש ברכב, ולכן לא תהיה זו תאונת דרכים (סעיף 1 לחוק הפלת"ד).
**וריאציה 3 — תכלית הסייג:** מהי תכלית הסייג לחזקה הממעטת? ← תכליתו היא להחזיר לחיק חוק הפלת"ד מקרים שבהם, למרות המעשה המכוון, קיים קשר הדוק לסיכון התחבורתי, והנזק נגרם כתוצאה מהשימוש ברכב (ע"א 2199/99 עזבון המנוח לזר נ'' רשות הנמלים והרכבות).', 'מעשה מכוון + נזק נגרם מהשפעת המעשה על השימוש ברכב ← תאונת דרכים (סייג לחזקה הממעטת בסעיף 1 לפלת"ד).',
    '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיף 1", "רע\"א 1117/09 קרנית קרן לפיצוי נפגעי תאונות דרכים נ'' יעקב בלבן (21.09.2009)", "ע\"א 2199/99 עזבון המנוח לזר, ז\"ל נ'' רשות הנמלים והרכבות, פ\"ד נו(1) 938 (2001)", "אליעזר ריבלין תאונת הדרכים (2020) | הרכב כזירה למעשה מכוון"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן מדובר במעשה מכוון של זריקת אבן, ולכן חלה החזקה הממעטת.', false, 'טענה זו שגויה. אף שמדובר במעשה מכוון, יש לבחון את הסייג לחזקה הממעטת, הנוגע לאופן שבו נגרם הנזק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן הנזק להולך הרגל נגרם על ידי השפעת המעשה המכוון (זריקת האבן) על השימוש ברכב המנועי (איבוד השליטה והסטייה).', true, 'תשובה זו נכונה. סעיף 1 לחוק הפלת"ד קובע סייג לחזקה הממעטת: אם הנזק נגרם על ידי השפעת המעשה המכוון על השימוש ברכב המנועי, ולא על ידי המעשה עצמו, אזי האירוע ייחשב לתאונת דרכים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, שכן הרכב שימש ככלי לגרימת נזק, ולא למטרות תחבורה.', false, 'טענה זו שגויה. הרכב שימש ככלי לגרימת נזק במעשה המכוון של זריקת האבן, אך הנזק להולך הרגל נגרם כתוצאה עקיפה של מעשה זה על השימוש התחבורתי ברכב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם זורק האבן לא נתפס, וזהות הנהג הפוגע אינה ידועה.', false, 'טענה זו שגויה. סיווג האירוע כתאונת דרכים אינו תלוי בזהות הפוגע או ביכולת לתפוס אותו, אלא באופי גרימת הנזק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ייחוד העילה וחריגיו',
    4, 'ראובן נפגע בתאונת דרכים שנגרמה על ידי שמעון במתכוון. ראובן הגיש תביעה לפיצויים נגד שמעון מכוח פקודת הנזיקין. האם ראובן יכול היה לתבוע גם מכוח חוק הפלת"ד?', 'שאלה זו בוחנת את עקרון ייחוד העילה שבסעיף 8 לחוק הפלת"ד ואת החריג לו במקרה של פגיעה מכוונת על ידי אדם אחר. היא מדגישה כי במקרה כזה, האירוע אינו נחשב לתאונת דרכים, ולכן אין עילה לפי הפלת"ד, אך ניתן לתבוע בנזיקין.', 'עקרון ייחוד העילה, הקבוע בסעיף 8(א) לחוק פיצויים לנפגעי תאונות דרכים, תשמ"ה-1975, קובע כי מי שתאונת דרכים מקנה לו עילת תביעה לפי חוק זה, לא תהיה לו עילת תביעה לפי פקודת הנזיקין בשל נזק גוף. אולם, סעיף 8(א) קובע חריג מפורש: ''זולת אם נפגע בתאונה שנגרמה על ידי אדם אחר במתכוון''. חריג זה מאפשר לנפגע לתבוע לפי פקודת הנזיקין במקרה של פגיעה מכוונת על ידי אחר. חשוב להבין כי במקרה של פגיעה מכוונת, האירוע אינו נחשב ל''תאונת דרכים'' מלכתחילה, בשל החזקה הממעטת שבסעיף 1 לחוק. לכן, אין לנפגע עילת תביעה לפי חוק הפלת"ד כלל. החריג בסעיף 8(א) רק מבהיר שגם אם היה מדובר בתאונת דרכים, עדיין ניתן היה לתבוע בנזיקין במקרה של כוונה. סעיף 8(א) לחוק פיצויים לנפגעי תאונות דרכים | ייחוד העילהסעיף 1 לחוק פיצויים לנפגעי תאונות דרכים | הגדרותנבו - המתמחה דיני נזיקין (2026) | מקרים שבהם כלל ייחוד העילה אינו חל',
    'הטעות הנפוצה היא לבלבל בין המקרים שבהם האירוע אינו ''תאונת דרכים'' כלל (בשל החזקה הממעטת) לבין המקרים שבהם האירוע הוא ''תאונת דרכים'' אך הנפגע אינו זכאי לפיצויים (בשל סעיף 7). ההבחנה חשובה להבנת תחולת ייחוד העילה.', '["ייחוד העילה", "חריג לייחוד העילה", "תאונה מכוונת", "חוק פיצויים לנפגעי תאונות דרכים סעיף 8", "פקודת הנזיקין", "חזקה ממעטת"]'::jsonb, '**וריאציה 1 — תביעה לאחר מיצוי עילה:** מה הדין אם נזק התפתח לאחר שניתן פסק דין סופי לפי חוק הפלת"ד? ← כלל ייחוד העילה אינו חל על נזק שהתפתח לאחר שניתן פסק דין סופי בתביעה לפי חוק הפלת"ד, ולכן הנפגע רשאי לתבוע את נזקיו הנוספים לפי פקודת הנזיקין (ע"א 8535/01 ליפשיץ).
**וריאציה 2 — נפגע שאין לו עילה בפלת"ד:** מה הדין אם לנפגע אין עילת תביעה לפי חוק הפלת"ד (למשל, נהג ללא רישיון)? ← סעיף 8(ג) לחוק הפלת"ד קובע כי אין בהוראת ייחוד העילה כדי לגרוע מתביעה לפי פקודת הנזיקין של מי שאין לו עילת תביעה לפי חוק זה (אליעזר ריבלין, תאונת הדרכים, עמ'' 19).
**וריאציה 3 — תלויים בנפגע:** האם תלויים בנפגע שגרם לתאונה במתכוון זכאים לפיצויים? ← אם האירוע אינו תאונת דרכים בשל החזקה הממעטת, התלויים אינם זכאים לפיצויים. אם האירוע הוא תאונת דרכים אך הנפגע עצמו נשללה זכאותו לפי סעיף 7(1), התלויים זכאים לפיצויים מכוח סעיף 7ב לחוק (אליעזר ריבלין, תאונת הדרכים, עמ'' 19).', 'פגיעה מכוונת על ידי אחר ← אינה תאונת דרכים (סעיף 1 לפלת"ד) ← אין עילה בפלת"ד ← ניתן לתבוע בנזיקין (חריג סעיף 8(א)).',
    '["חוק פיצויים לנפגעי תאונות דרכים, תשל\"ה-1975, סעיפים 1, 7(1), 7ב, 8(א), 8(ג)", "ע\"א 8535/01 גנאדי ליפשיץ נ'' מדינת ישראל, משרד הבריאות, פ\"ד נז(6) 656 (2003)", "אליעזר ריבלין תאונת הדרכים (2020) | תוצאותיה של שלילת הזכאות", "נבו - המתמחה דיני נזיקין (2026) | מקרים שבהם כלל ייחוד העילה אינו חל"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, ראובן יכול היה לתבוע הן מכוח חוק הפלת"ד והן מכוח פקודת הנזיקין, ובלבד שלא יקבל כפל פיצוי.', false, 'טענה זו שגויה. במקרה של פגיעה מכוונת על ידי אדם אחר, האירוע אינו נחשב לתאונת דרכים, ולכן אין עילה לתבוע מכוח חוק הפלת"ד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, שכן האירוע אינו תאונת דרכים בשל החזקה הממעטת, ולכן אין עילה לפי חוק הפלת"ד, אך ראובן זכאי לתבוע לפי פקודת הנזיקין.', true, 'תשובה זו נכונה. החזקה הממעטת בסעיף 1 לחוק הפלת"ד מוציאה אירוע של פגיעה מכוונת מגדר ''תאונת דרכים''. משאין זו תאונת דרכים, חוק הפלת"ד אינו חל. עם זאת, סעיף 8(א) לחוק הפלת"ד מאפשר לתבוע בנזיקין במקרה כזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, ראובן יכול היה לתבוע מכוח חוק הפלת"ד, שכן סעיף 8(א) לחוק קובע חריג לייחוד העילה במקרה של פגיעה מכוונת.', false, 'טענה זו שגויה. סעיף 8(א) קובע חריג לייחוד העילה, כלומר, הוא מאפשר לתבוע בנזיקין למרות קיומה של עילה בפלת"ד. אך במקרה של פגיעה מכוונת, אין עילה בפלת"ד מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, שכן עקרון ייחוד העילה שולל תמיד תביעה לפי פקודת הנזיקין כאשר מדובר בתאונת דרכים.', false, 'טענה זו שגויה. עקרון ייחוד העילה חל רק כאשר קיימת עילת תביעה לפי חוק הפלת"ד. במקרה של פגיעה מכוונת, אין עילה לפי חוק הפלת"ד, ולכן עקרון ייחוד העילה אינו חל.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 39, '2019-S-S-Q39';
END
