  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-S-Q40', v_chapter_id, v_subtopic_id, 'אבישי עובד אצל יוסף כמלצר במסעדתו. במהלך עבודתו ניצל אבישי את הפסקת הצהריים ושטף את מכוניתו החונה במגרש החנייה הסמוך למסעדה, והותיר במקום שלולית מים. בתום ההפסקה חזר אבישי למסעדה, ותוך כדי פינוי אחד השולחנות הפיל על רצפתה שיירי מזון. למרות הנחיה מפורשת שקיבל לנקותם מיד, לא עשה כן. אברהם שבא לסעוד במסעדה עם אחיו החליק על שלולית המים שבמגרש החנייה, ואילו אחיו החליק על שיירי המזון במסעדה, ולשניהם נגרם נזק גוף. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 40}'::jsonb, 'השאלה עוסקת באחריות שילוחית של מעביד למעשי עובדו לפי סעיף 13 לפקודת הנזיקין, ובפרט בהבחנה בין מעשה שנעשה ''תוך כדי עבודתו'' לבין מעשה שנעשה ''למטרות של עצמו ולא לענין המעביד''. כמו כן, היא בוחנת את אחריותו האישית של העובד למעשיו, גם כאשר המעביד חב באחריות שילוחית.', 'פקודת הנזיקין [נוסח חדש], בסעיף 13(א)(2), מטילה אחריות שילוחית על מעביד למעשה שעשה עובד שלו ''תוך כדי עבודתו''. סעיף 13(ב) מבהיר כי מעשה ייחשב ''תוך כדי עבודתו'' גם אם היה ''ביצוע לא נאות של מעשה שהרשה המעביד'', אך לא יראו כן מעשה שעשה העובד ''למטרות של עצמו ולא לענין המעביד''.
במקרה של אברהם, אבישי שטף את מכוניתו בהפסקת הצהריים. פעולה זו נעשתה למטרותיו האישיות הבלעדיות של אבישי ולא לעניין המעביד (יוסף). לכן, יוסף אינו חב באחריות שילוחית לנזק שנגרם לאברהם, ואבישי הוא האחראי היחיד לנזק זה. סעיף 13(ב) לפקודת הנזיקין | חבות מעבידתא"מ (שלום נת'') 69185-12-19 שוורץ סימונה נ'' איי.די.איי. חברה לביטוח בע"מ (15.08.2024)

במקרה של אחיו של אברהם, אבישי הפיל שיירי מזון תוך כדי פינוי שולחנות ולא ניקה אותם, למרות הנחיה מפורשת. פעולה זו, אף שהיא רשלנית ומהווה ''ביצוע לא נאות'' של תפקידו כמלצר, נעשתה ''תוך כדי עבודתו'' ולמען המעביד. לכן, יוסף חב באחריות שילוחית לנזק שנגרם לאחיו של אברהם. בנוסף, סעיף 16 לפקודת הנזיקין קובע כי אחריות המעביד אינה גורעת מחבותו של העובד. לפיכך, גם אבישי אחראי באחריות אישית לנזק שגרם, והוא ויוסף נחשבים כמעוולים במשותף. סעיף 13(ב) לפקודת הנזיקין | חבות מעבידסעיף 16 לפקודת הנזיקין | שמירת חבותת"א (שלום י-ם) 16806/08 כלל חב` לביטוח בע"מ נ'' ואליד חוסיין (07.01.2018)', 'הטעות הנפוצה היא לבלבל בין מעשה שנעשה ''תוך כדי עבודתו'' לבין מעשה שנעשה ''למטרות של עצמו ולא לענין המעביד'', או לחשוב שאחריות המעביד פוטרת את העובד מאחריות אישית.',
    '["אחריות שילוחית", "יחסי עובד-מעביד", "תוך כדי עבודתו", "למטרות של עצמו ולא לענין המעביד", "ביצוע לא נאות", "אחריות אישית", "מעוולים במשותף"]'::jsonb, '**וריאציה 1 — חובת נאמנות:** האם העובדה שאבישי הפר הנחיה מפורשת לנקות את שיירי המזון משפיעה על אחריות המעביד? ← לא, סעיף 13(ב) לפקודת הנזיקין קובע במפורש כי אחריות המעביד קיימת גם אם מעשהו של העובד היה ''ביצוע לא נאות של מעשה שהרשה המעביד''.
**וריאציה 2 — אחריות המעביד לנזקי רכוש:** האם אחריות שילוחית חלה גם על נזקי רכוש? ← כן, סעיף 13 לפקודת הנזיקין אינו מבחין בין נזקי גוף לנזקי רכוש, והוא חל על כל עוולה שביצע העובד ''תוך כדי עבודתו''.
**וריאציה 3 — אחריות ישירה של המעביד:** האם יוסף יכול להיות אחראי גם באחריות ישירה? ← כן, אם יוסף התרשל בעצמו, למשל, בכך שלא דאג לתנאי בטיחות נאותים במסעדה או שלא פיקח כראוי על עובדיו, הוא יכול לחוב גם באחריות ישירה בנוסף לאחריות השילוחית (ת"א (שלום ביש"א) 39768-06-17 פלוני נ'' חאלד אבו רודא).', 'מעשה עובד למטרות עצמיות ← אין אחריות שילוחית למעביד. מעשה עובד ''תוך כדי עבודתו'' (גם אם ביצוע לא נאות) ← אחריות שילוחית למעביד + אחריות אישית לעובד.', '["פקודת הנזיקין [נוסח חדש], סעיפים 13, 16", "תא\"מ (שלום נת'') 69185-12-19 שוורץ סימונה נ'' איי.די.איי. חברה לביטוח בע\"מ (15.08.2024)", "ת\"א (שלום י-ם) 16806/08 כלל חב` לביטוח בע\"מ נ'' ואליד חוסיין (07.01.2018)", "ת\"א (שלום ביש\"א) 39768-06-17 פלוני נ'' חאלד אבו רודא (20.05.2019)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Employer vicarious liability — waiter mopping during break left puddle. Negligence is closest; could also be strict_liability_torts for employer-employee specifics | source_review_note: השאלה עוסקת בדיני נזיקין (אחריות שילוחית), תחום שאינו נכלל ברשימת הפרקים הראשיים. סווג תחת ''סדר דין אזרחי'' ו''הליכים'' כמיפוי חלופי. יש לשקול הוספת פרקים אלו לרשימת הפרקים הראשיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'האחריות לנזקיו של אברהם תוטל על אבישי ועל יוסף. האחריות לנזקיו של אחיו תוטל על יוסף.', false, 'טענה זו שגויה. נזקיו של אברהם נגרמו ממעשה שאבישי עשה למטרותיו האישיות בלבד, ולכן יוסף אינו חב באחריות שילוחית. נזקיו של האח נגרמו ממעשה שנעשה תוך כדי עבודתו, ולכן יוסף חב באחריות שילוחית בנוסף לאבישי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'האחריות לנזקיו של אברהם תוטל על אבישי. האחריות לנזקיו של אחיו תוטל על אבישי ויוסף.', true, 'תשובה זו נכונה. שטיפת הרכב הייתה למטרותיו האישיות של אבישי, ולכן יוסף אינו אחראי. הפלת שיירי המזון ואי-ניקויים היו ביצוע לא נאות של תפקיד במסגרת העבודה, ולכן יוסף חב באחריות שילוחית בנוסף לאבישי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'האחריות לנזקיו של אברהם תוטל על אבישי. האחריות לנזקיו של אחיו תוטל על יוסף.', false, 'טענה זו שגויה. גם אם יוסף חב באחריות שילוחית לנזקי האח, אין בכך כדי לפטור את אבישי מאחריותו האישית למעשה העוולה שביצע.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'האחריות לנזקיהם של אברהם ואחיו תוטל על אבישי ויוסף.', false, 'טענה זו שגויה. יוסף אינו חב באחריות שילוחית לנזקיו של אברהם, שכן המעשה שגרם לנזק זה נעשה למטרותיו האישיות של אבישי ולא לעניין המעביד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות שילוחית למעשה מכוון',
    1, 'עובד של חברת שמירה, שהוצב לשמור על מתחם מסחרי, תקף במתכוון לקוח שסירב לעזוב את המקום לאחר שעות הפעילות, וגרם לו נזק גוף. האם חברת השמירה אחראית באחריות שילוחית למעשה התקיפה?', 'שאלה זו עוסקת בהיקף האחריות השילוחית של מעביד למעשים מכוונים של עובדיו, ובפרט עוולת התקיפה. היא בוחנת את הפרשנות לסעיף 13(ב) לפקודת הנזיקין, המבחין בין ביצוע לא נאות של תפקיד לבין מעשה שנעשה למטרות העובד בלבד.', 'סעיף 13(א)(2) לפקודת הנזיקין [נוסח חדש] מטיל אחריות שילוחית על מעביד אם העובד עשה את המעשה ''תוך כדי עבודתו''. סעיף 13(ב) מבהיר כי ''רואים מעשה כאילו נעשה תוך כדי עבודתו של עובד, אם עשהו כעובד וכשהוא מבצע את התפקידים הרגילים של עבודתו והכרוכים בה אף על פי שמעשהו של העובד היה ביצוע לא נאות של מעשה שהרשה המעביד; אולם לא יראו כן מעשה שעשה העובד למטרות של עצמו ולא לענין המעביד''. הפסיקה קבעה כי גם מעשה מכוון, כמו תקיפה, יכול להיחשב כ''ביצוע לא נאות'' של תפקיד, אם הוא קשור באופן הדוק לתפקיד שהוטל על העובד (למשל, אכיפת כללים). במקרה כזה, אם המעשה לא נעשה למטרותיו האישיות הבלעדיות של העובד, אלא לקידום ענייני המעביד (גם אם בדרך פסולה), תוטל אחריות שילוחית. סעיף 13(ב) לפקודת הנזיקין | חבות מעבידת"א (שלום ת"א) 51168-08 איתן לוינטל נ'' שמשון ברייה (26.01.2013)נבו - המתמחה דיני נזיקין (2026) | אחריות שילוחית לעוולה שביצע עובד תוך כדי עבודתו (סעיף ב שלעיל)',
    'הטעות הנפוצה היא להניח שכל מעשה מכוון של עובד פוטר אוטומטית את המעביד מאחריות שילוחית, מבלי לבחון את הקשר בין המעשה לתפקיד ואת מטרת העובד.', '["אחריות שילוחית", "תקיפה", "מעשה מכוון", "תוך כדי עבודתו", "ביצוע לא נאות", "למטרות של עצמו"]'::jsonb, '**וריאציה 1 — מניע כפול:** מה הדין אם העובד פעל מתוך מניע כפול – גם לקידום ענייני המעביד וגם למטרותיו הפרטיות? ← לפי סעיף 13(ב) סיפא, מניע כפול אינו שולל אחריות שילוחית, אלא אם העובד פעל למטרותיו הפרטיות בלבד ובעשותו כן לא פעל כלל למען המעביד (ת"א (שלום ת"א) 51168-08 לוינטל נ'' ברייה).
**וריאציה 2 — מעשה חריג לחלוטין:** מה הדין אם השומר תקף את הלקוח מתוך נקמה אישית על אירוע קודם שלא קשור לעבודה? ← במקרה כזה, המעשה נעשה למטרותיו האישיות הבלעדיות של העובד ולא לעניין המעביד, ולכן לא תוטל אחריות שילוחית על חברת השמירה (סעיף 13(ב) לפקודת הנזיקין).
**וריאציה 3 — אחריות אישית של העובד:** האם העובד עצמו יהיה אחראי למעשה התקיפה? ← כן, אחריות המעביד היא בנוסף לאחריות העובד ולא במקומה. העובד תמיד חב באחריות אישית למעשיו (סעיף 16 לפקודת הנזיקין).', 'מעשה מכוון של עובד ← אחריות שילוחית אם ביצוע לא נאות של תפקיד ← ולא למטרות עצמיות בלבד (סעיף 13 לפקודת הנזיקין).',
    '["פקודת הנזיקין [נוסח חדש], סעיפים 13, 16", "ת\"א (שלום ת\"א) 51168-08 איתן לוינטל נ'' שמשון ברייה (26.01.2013)", "נבו - המתמחה דיני נזיקין (2026) | אחריות שילוחית לעוולה שביצע עובד תוך כדי עבודתו (סעיף ב שלעיל)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן תקיפה היא מעשה מכוון, ועל מעביד לא מוטלת אחריות שילוחית למעשים מכוונים של עובדיו.', false, 'טענה זו שגויה. אף שתקיפה היא מעשה מכוון, אחריות שילוחית יכולה לקום גם למעשים מכוונים אם הם מהווים ביצוע לא נאות של תפקיד שניתן לעובד, ולא נעשו למטרותיו האישיות בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, אם התקיפה הייתה ביצוע לא נאות של תפקידו של השומר לאכוף את הכללים במתחם, ולא נעשתה למטרותיו האישיות בלבד.', true, 'תשובה זו נכונה. סעיף 13(ב) לפקודת הנזיקין קובע כי מעשה ייחשב ''תוך כדי עבודתו'' גם אם היה ביצוע לא נאות של מעשה שהרשה המעביד, ובלבד שלא נעשה למטרות העובד בלבד. תקיפה יכולה להיחשב כביצוע לא נאות של אכיפת כללים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן חברת השמירה הרשתה במפורש את התקיפה או אישררה אותה בדיעבד.', false, 'טענה זו שגויה. אחריות שילוחית יכולה לקום גם אם המעביד לא הרשה או אישרר את המעשה במפורש, אלא אם העובד עשה את המעשה ''תוך כדי עבודתו'' (סעיף 13(א)(2) לפקודת הנזיקין).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, בכל מקרה, שכן השומר פעל במהלך עבודתו, וחברת השמירה אחראית לכל מעשה של עובדיה בזמן העבודה.', false, 'טענה זו שגויה. אחריות שילוחית אינה אוטומטית לכל מעשה שנעשה בזמן העבודה. יש לבחון אם המעשה נעשה ''תוך כדי עבודתו'' ו''לא למטרות של עצמו ולא לענין המעביד''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן יחסי עובד-מעביד בנזיקין',
    2, 'מהו המבחן העיקרי לקביעת קיומם של יחסי עובד-מעביד לצורך הטלת אחריות שילוחית בנזיקין, לפי פקודת הנזיקין?', 'שאלה זו מתמקדת במבחן המשפטי לקביעת יחסי עובד-מעביד לצורך הטלת אחריות שילוחית בנזיקין. היא מדגישה את ההבחנה בין מבחן ''השליטה הגמורה'' בפקודת הנזיקין לבין מבחנים אחרים המקובלים בדיני עבודה.', 'פקודת הנזיקין [נוסח חדש] מגדירה בסעיף 2 את המונחים ''מעביד'' ו''עובד'' לצורך אחריות שילוחית. ''מעביד'' הוא ''מי שיש לו ביחסיו עם אדם אחר שליטה גמורה על הדרך שבו אדם אחר מבצע עבודה בשבילו'', ו''עובד'' הוא ''מי שעבודתו נתונה לשליטה כאמור''. הפסיקה קבעה כי המבחן הקובע בדיני נזיקין לעניין קביעת יחסי עובד ומעביד הוא מבחן השליטה הגמורה, המרות והפיקוח. מבחן זה מתמקד בזכות המעביד לשלוט על אופן ביצוע העבודה, ולאו דווקא בשליטה בפועל. הוא שונה ממבחן ההשתלבות המקובל בדיני עבודה. ע"א 502/78 מדינת ישראל נ'' ירוחם ניסים (12.11.1981)ת"א (שלום אשד'') 72160-12-19 לי פייקס נ'' איתן פתרונות בניה בע"מ (18.04.2024)זוהר גושן אסף אקשטיין דיני חברות (2023) | 3.2.1 אחריותה הנזיקית של החברה',
    'הטעות הנפוצה היא לבלבל בין מבחן ''השליטה הגמורה'' בדיני נזיקין לבין מבחן ''ההשתלבות'' המקובל בדיני עבודה, או לחשוב ששליטה בפועל היא תנאי הכרחי, בעוד שדי בזכות לשליטה.', '["יחסי עובד-מעביד", "אחריות שילוחית", "מבחן השליטה הגמורה", "פקודת הנזיקין סעיף 2", "מרות ופיקוח", "מבחן ההשתלבות"]'::jsonb, '**וריאציה 1 — קבלן עצמאי:** האם מעביד אחראי לנזקי קבלן עצמאי? ← ככלל, מעביד אינו אחראי לנזקי קבלן עצמאי, אלא אם מתקיימים חריגים מסוימים הקבועים בסעיף 15 לפקודת הנזיקין (ת"ק (תביעות קטנות הרצ'') 31377-02-22 יובל עמיר נ'' מי רמת גן בע"מ).
**וריאציה 2 — שליטה בפועל מול זכות לשליטה:** האם נדרשת שליטה בפועל של המעביד על העובד? ← לא, די בזכות לשליטה, גם אם היא אינה ממומשת בפועל (ת"א (שלום אשד'') 72160-12-19 לי פייקס נ'' איתן פתרונות בניה בע"מ).
**וריאציה 3 — שני מעבידים:** האם לעובד יכולים להיות שני מעבידים לצורך דיני נזיקין? ← כן, עובד יכול שיהיו לו שני מעבידים שונים בעת ובעונה אחת, והתשובה לשאלה מי נחשב למעבידו במקרה קונקרטי תלויה בנסיבות המיוחדות של המקרה (אמנון כרמי, בריאות ומשפט, עמ'' 95).', 'יחסי עובד-מעביד בנזיקין ← נקבעים לפי מבחן השליטה הגמורה ← המרות והפיקוח (סעיף 2 לפקודת הנזיקין).',
    '["פקודת הנזיקין [נוסח חדש], סעיפים 2, 15", "ע\"א 502/78 מדינת ישראל נ'' ירוחם ניסים (12.11.1981)", "ת\"א (שלום אשד'') 72160-12-19 לי פייקס נ'' איתן פתרונות בניה בע\"מ (18.04.2024)", "ת\"ק (תביעות קטנות הרצ'') 31377-02-22 יובל עמיר נ'' מי רמת גן בע\"מ (04.09.2022)", "אמנון כרמי בריאות ומשפט (2013) | (ב) אחריות מעביד"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן ההשתלבות האורגנית במפעל המעביד.', false, 'טענה זו שגויה. מבחן ההשתלבות הוא המבחן העיקרי לקביעת יחסי עובד-מעביד בדיני עבודה, אך לא בדיני נזיקין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן השליטה הגמורה, המרות והפיקוח.', true, 'תשובה זו נכונה. הפסיקה קבעה כי לצורך הטלת אחריות שילוחית בנזיקין, המבחן הקובע הוא מבחן השליטה הגמורה, המרות והפיקוח, המתמקד בזכות המעביד לשלוט על אופן ביצוע העבודה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן התלות הכלכלית של העובד במעביד.', false, 'טענה זו שגויה. תלות כלכלית היא אחד מהשיקולים במבחן ההשתלבות בדיני עבודה, אך אינה המבחן העיקרי בדיני נזיקין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן מהות העבודה והאם היא חלק מליבת העסק של המעביד.', false, 'טענה זו שגויה. אף שמהות העבודה רלוונטית, המבחן הספציפי בדיני נזיקין הוא מבחן השליטה הגמורה, המרות והפיקוח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריג למעשה ''תוך כדי עבודתו''',
    3, 'נהג משאית של חברת הובלות, שהיה בדרכו למסור סחורה ללקוח, סטה ממסלולו המתוכנן כדי לאסוף חבר לבילוי אישי. במהלך הסטייה, כשהוא נוהג ברכב המשאית של החברה, גרם הנהג לתאונת דרכים שבה נפגע צד שלישי. האם חברת ההובלות אחראית באחריות שילוחית לנזקי התאונה?', 'שאלה זו בוחנת את החריג הקבוע בסעיף 13(ב) לפקודת הנזיקין, לפיו מעביד לא יישא באחריות שילוחית למעשה שעשה עובד ''למטרות של עצמו ולא לענין המעביד''. היא מדגימה מצב של סטייה משמעותית מתפקיד למטרות אישיות.', 'סעיף 13(ב) לפקודת הנזיקין [נוסח חדש] קובע כי ''רואים מעשה כאילו נעשה תוך כדי עבודתו של עובד... אולם לא יראו כן מעשה שעשה העובד למטרות של עצמו ולא לענין המעביד''. הפסיקה מבחינה בין סטייה קלה מהעבודה, שאינה מוציאה את המעשה מתחום האחריות השילוחית, לבין סטייה משמעותית, הנחשבת כמעשה שנעשה למטרות העובד בלבד. במקרה הנדון, סטייה ממסלול מתוכנן כדי לאסוף חבר לבילוי אישי היא סטייה משמעותית, שאינה קשורה לענייני המעביד. לכן, חברת ההובלות לא תישא באחריות שילוחית לנזקי התאונה. סעיף 13(ב) לפקודת הנזיקין | חבות מעבידתא"מ (שלום נת'') 69185-12-19 שוורץ סימונה נ'' איי.די.איי. חברה לביטוח בע"מ (15.08.2024)עמוס הרמן דיני נזיקין (2020) | 5. תוך כדי העבודה',
    'הטעות הנפוצה היא לבלבל בין סטייה קלה מהעבודה לבין סטייה משמעותית, או לחשוב שכל שימוש ברכב המעביד בזמן העבודה מטיל אחריות שילוחית, גם אם הוא למטרות אישיות בלבד.', '["אחריות שילוחית", "תוך כדי עבודתו", "למטרות של עצמו", "סטייה מהעבודה", "פקודת הנזיקין סעיף 13(ב)", "רכב מעביד"]'::jsonb, '**וריאציה 1 — סטייה קלה:** מה הדין אם הנהג סטה רק כדי לקנות כוס קפה בדרך ללקוח? ← סטייה קלה כזו, הנחשבת כחלק מהתנהלות סבירה במהלך העבודה, לא תוציא את המעשה מגדר ''תוך כדי עבודתו'', והמעביד יישא באחריות (עמוס הרמן, דיני נזיקין, עמ'' 6).
**וריאציה 2 — הפרת הוראות:** האם הפרת הוראות המעביד שוללת אחריות שילוחית? ← לא בהכרח. הפרת הוראות המגבילות את דרך ביצוע העבודה (ולא את תחום ההעסקה) אינה שוללת אחריות שילוחית, אלא אם ההפרה גורמת לכך שלפעולת העובד אין שום קשר לעבודה (אמנון כרמי, בריאות ומשפט, עמ'' 95).
**וריאציה 3 — נזק לעובד עצמו:** מה הדין אם הנהג עצמו נפגע בתאונה? ← אם התאונה נגרמה כתוצאה ממעשה שנעשה למטרותיו האישיות בלבד, הוא לא ייחשב כנפגע ''תוך כדי עבודתו'' לעניין חוק הביטוח הלאומי, ולא יהיה זכאי לדמי פגיעה (חוק הביטוח הלאומי [נוסח משולב], סעיף 80).', 'מעשה למטרות עצמיות בלבד ← לא ''תוך כדי עבודתו'' ← אין אחריות שילוחית למעביד (סעיף 13(ב) לפקודת הנזיקין).',
    '["פקודת הנזיקין [נוסח חדש], סעיף 13(ב)", "תא\"מ (שלום נת'') 69185-12-19 שוורץ סימונה נ'' איי.די.איי. חברה לביטוח בע\"מ (15.08.2024)", "עמוס הרמן דיני נזיקין (2020) | 5. תוך כדי העבודה", "אמנון כרמי בריאות ומשפט (2013) | (ב) אחריות מעביד", "חוק הביטוח הלאומי [נוסח משולב], תשנ\"ה-1995, סעיף 80"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן הנהג נהג ברכב החברה, והיה עדיין ''במהלך עבודתו'' גם אם סטה ממסלולו.', false, 'טענה זו שגויה. סטייה משמעותית ממסלול העבודה למטרות אישיות יכולה להוציא את המעשה מגדר ''תוך כדי עבודתו'', גם אם הרכב הוא של המעביד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן הנהג עשה את המעשה למטרות של עצמו ולא לעניין המעביד, ולכן לא יראו את המעשה כ''תוך כדי עבודתו''.', true, 'תשובה זו נכונה. סעיף 13(ב) לפקודת הנזיקין קובע חריג מפורש לפיו לא יראו מעשה כ''תוך כדי עבודתו'' אם העובד עשה אותו למטרות של עצמו ולא לעניין המעביד, כפי שקרה במקרה של סטייה משמעותית לבילוי אישי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן חברת ההובלות הוכיחה שהנהג הפר הוראה מפורשת שלה שלא לסטות מהמסלול.', false, 'טענה זו שגויה. הפרת הוראה אינה התנאי היחיד לשלילת אחריות שילוחית. אם המעשה נעשה למטרות העובד בלבד, האחריות נשללת גם ללא הפרת הוראה מפורשת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שכן נהיגה ברכב היא פעולה מסוכנת, ועל המעביד חלה חובה מוגברת לפקח על עובדיו.', false, 'טענה זו שגויה. אף שקיימת חובת פיקוח, היא אינה מבטלת את החריג הקבוע בסעיף 13(ב) לפיו מעשה שנעשה למטרות העובד בלבד אינו נחשב ''תוך כדי עבודתו''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות אישית של העובד',
    4, 'עובד גרם נזק לצד שלישי במהלך עבודתו, והמעביד חויב באחריות שילוחית. האם העובד פטור מאחריות אישית לנזק שגרם?', 'שאלה זו עוסקת בעקרון האחריות האישית של העובד למעשיו, גם כאשר המעביד חב באחריות שילוחית. היא מדגישה כי אחריות המעביד אינה גורעת מאחריות העובד, וכי שניהם נחשבים כמעוולים במשותף.', 'סעיף 16 לפקודת הנזיקין [נוסח חדש] קובע במפורש כי ''האמור בסעיף 13 אינו גורע מחבותו של העובד על מעשה שעשה''. כלומר, אחריותו השילוחית של המעביד אינה באה במקום אחריותו האישית של העובד, אלא בנוסף לה. העובד שביצע את העוולה נותר אחראי באחריות אישית למעשיו. כלפי הניזוק, המעביד והעובד נחשבים כ''מעוולים במשותף'', וניתן לתבוע את שניהם יחד ולחוד. עקרון זה מבטא את הגישה לפיה כל אדם שביצע עוולה יישא בתוצאותיה, ואין בעובדה שפעל כעובד כדי לפטור אותו מאחריות. סעיף 16 לפקודת הנזיקין | שמירת חבותת"א (שלום י-ם) 16806/08 כלל חב` לביטוח בע"מ נ'' ואליד חוסיין (07.01.2018)תא"מ (שלום ת"א) 53835-06-14 דומיקאר בע"מ נ'' סיגלית אליהו (27.08.2017)',
    'הטעות הנפוצה היא לחשוב שאחריות שילוחית של המעביד פוטרת את העובד מאחריות אישית, או שהיא באה במקומה, בעוד שהיא אחריות מצטברת.', '["אחריות אישית", "אחריות שילוחית", "מעוולים במשותף", "פקודת הנזיקין סעיף 16", "שיפוי", "חבות העובד"]'::jsonb, '**וריאציה 1 — תביעת שיפוי:** האם המעביד יכול לתבוע שיפוי מהעובד? ← כן, אם המעביד חויב בפיצויים, הוא רשאי לתבוע שיפוי מהעובד מכוח סעיף 84 לפקודת הנזיקין, אך בית המשפט יבחן את נסיבות המקרה ואת מידת האשם של כל צד (ת"א (שלום י-ם) 16806/08 כלל חב` לביטוח בע"מ נ'' ואליד חוסיין).
**וריאציה 2 — אחריות העובד כלפי מעביד:** האם העובד אחראי כלפי המעביד על הנזק שנגרם לו? ← כן, העובד חב כלפי המעביד בגין הנזק שגרם לו, למשל, אם המעביד נאלץ לשלם פיצויים לצד שלישי (תאד"מ (שלום קריות) 8342-06-21 סולטאן ספורי נ'' זוזו הסעות בע"מ).
**וריאציה 3 — אחריות פלילית:** האם אחריות שילוחית בנזיקין משפיעה על אחריות פלילית של העובד? ← לא, אחריות שילוחית בנזיקין אינה משפיעה על אחריותו הפלילית של העובד למעשיו, אם המעשה מהווה עבירה פלילית (פקודת הבטיחות בעבודה [נוסח חדש], סעיף 202).', 'עובד אחראי אישית למעשיו ← גם אם המעביד חב שילוחית ← שניהם מעוולים במשותף (סעיף 16 לפקודת הנזיקין).',
    '["פקודת הנזיקין [נוסח חדש], סעיפים 16, 84", "ת\"א (שלום י-ם) 16806/08 כלל חב` לביטוח בע\"מ נ'' ואליד חוסיין (07.01.2018)", "תא\"מ (שלום ת\"א) 53835-06-14 דומיקאר בע\"מ נ'' סיגלית אליהו (27.08.2017)", "תאד\"מ (שלום קריות) 8342-06-21 סולטאן ספורי נ'' זוזו הסעות בע\"מ (13.03.2023)", "פקודת הבטיחות בעבודה [נוסח חדש], תש\"ל-1970, סעיף 202"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, שכן אחריות המעביד מחליפה את אחריות העובד, והוא פטור מאחריות אישית.', false, 'טענה זו שגויה. אחריות המעביד היא בנוסף לאחריות העובד ולא במקומה. העובד אינו פטור מאחריות אישית למעשיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, העובד נותר אחראי באחריות אישית למעשה העוולה שביצע, והוא והמעביד נחשבים כמעוולים במשותף.', true, 'תשובה זו נכונה. סעיף 16 לפקודת הנזיקין קובע כי אחריות המעביד אינה גורעת מחבותו של העובד, והוא והמעביד נחשבים כמעוולים במשותף כלפי הניזוק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אלא אם כן המעביד יוכיח שהעובד פעל בזדון או ברשלנות חמורה.', false, 'טענה זו שגויה. אחריותו האישית של העובד קיימת לכל עוולה שביצע, ללא קשר לרמת האשם, ואינה תלויה בהוכחת זדון או רשלנות חמורה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אך המעביד חייב לשפות את העובד על כל סכום שישלם לצד השלישי.', false, 'טענה זו שגויה. שאלת השיפוי בין מעביד לעובד היא שאלה נפרדת, ואינה אוטומטית. היא תלויה בנסיבות ובסעיף 84 לפקודת הנזיקין.', 4);

